) end end end end end end end end


-- DATA / v2 description codec. Legacy flat descriptions are accepted.
local Codec = {}
Codec.assetFields = {"Face", "Head", "Torso", "LeftArm", "RightArm", "LeftLeg", "RightLeg", "Shirt", "Pants", "GraphicTShirt",
    "ClimbAnimation", "FallAnimation", "IdleAnimation", "JumpAnimation", "RunAnimation", "SwimAnimation", "WalkAnimation", "MoodAnimation"}
Codec.scaleFields = {"BodyTypeScale", "DepthScale", "HeadScale", "HeightScale", "ProportionScale", "WidthScale"}
Codec.colorFields = {"HeadColor", "LeftArmColor", "RightArmColor", "LeftLegColor", "RightLegColor", "TorsoColor"}
Codec.accessoryFields = {"HatAccessory", "HairAccessory", "FaceAccessory", "NeckAccessory", "ShouldersAccessory", "FrontAccessory", "BackAccessory", "WaistAccessory"}
function Codec.number(v, low, high)
    return type(v) == "number" and v == v and v >= low and v <= high
end
function Codec.id(v)
    local n = tonumber(v)
    return Codec.number(n, 1, 9007199254740991) and n % 1 == 0 and n or nil
end
-- An emote list and the wheel slots that play it, made consistent: every slot (1-8) holds one emote that is in the
-- list. A slot whose emote is gone stays empty in Roblox's wheel but still counted as taken, so emotes added after it
-- all landed on slot 8, each one replacing the last.
function Codec.emoteSet(emotes, equipped)
    local list, slots, clean = {}, {}, {}
    if type(emotes) == "table" then
        for name, ids in pairs(emotes) do if type(name) == "string" and type(ids) == "table" and #ids > 0 then list[name] = ids end end
    end
    for _, row in ipairs(type(equipped) == "table" and equipped or {}) do
        local slot = type(row) == "table" and tonumber(row.Slot)
        if slot and slot % 1 == 0 and slot >= 1 and slot <= 8 and not slots[slot] and type(row.Name) == "string" and list[row.Name] then
            slots[slot] = true; table.insert(clean, {Name = row.Name, Slot = slot})
        end
    end
    table.sort(clean, function(a, b) return a.Slot < b.Slot end)
    return list, clean
end
-- A name cut to a number of characters (not bytes, so an emoji is never split), without control characters.
function Codec.cut(text, limit)
    text = tostring(text or ""):gsub("%c", " ")
    if not utf8.len(text) then text = text:gsub("[\128-\255]", "") end
    if utf8.len(text) > limit then text = text:sub(1, utf8.offset(text, limit + 1) - 1) end
    return text
end
function Codec.encode(desc)
    local data = {Version = 2, Properties = {}, Colors = {}, Accessories = {}, Emotes = {}, EquippedEmotes = {}}
    for _, fields in ipairs({Codec.assetFields, Codec.scaleFields, Codec.accessoryFields}) do
        for _, field in ipairs(fields) do pcall(function() data.Properties[field] = desc[field] end) end
    end
    for _, field in ipairs(Codec.colorFields) do
        local c = desc[field]; data.Colors[field] = {c.R, c.G, c.B}
    end
    local ok, list = pcall(function() return desc:GetAccessories(true) end)
    data.HasAccessories = ok
    if ok then
        for _, item in ipairs(list) do
            local row = {AssetId = item.AssetId, AccessoryType = item.AccessoryType.Name, IsLayered = item.IsLayered}
            if item.Order ~= nil then row.Order = item.Order end
            if item.Puffiness ~= nil then row.Puffiness = item.Puffiness end
            for _, key in ipairs({"Position", "Rotation", "Scale"}) do
                local v = item[key]
                if typeof(v) == "Vector3" then row[key] = {v.X, v.Y, v.Z} end
            end
            table.insert(data.Accessories, row)
        end
    end
    pcall(function() data.Emotes, data.EquippedEmotes = Codec.emoteSet(desc:GetEmotes(), desc:GetEquippedEmotes()) end)
    -- Makeup (face, lip and eye layers) lives in MakeupDescription children of the description.
    data.Makeup = {}
    for _, item in ipairs(desc:GetChildren()) do
        if item.ClassName == "MakeupDescription" and #data.Makeup < 30 then
            local read, row = pcall(function() return {AssetId = item.AssetId, MakeupType = item.MakeupType.Name, Order = item.Order} end)
            if read and Codec.id(row.AssetId) then table.insert(data.Makeup, row) end
        end
    end
    return data
end
function Codec.decode(data)
    assert(type(data) == "table", "Invalid avatar data.")
    assert(data.Version == nil or data.Version == 2, "Unsupported avatar version.")
    local props = data.Version == 2 and data.Properties or data
    assert(type(props) == "table" and next(props) ~= nil, "Saved avatar data is incomplete.")
    local desc = Instance.new("HumanoidDescription")
    local assigned = 0
    for _, field in ipairs(Codec.assetFields) do
        local v = props[field]
        if Codec.number(v, 0, 9007199254740991) and v % 1 == 0 then
            local ok = pcall(function() desc[field] = v end); if ok then assigned = assigned + 1 end
        end
    end
    for _, field in ipairs(Codec.scaleFields) do
        if Codec.number(props[field], 0, 10) then desc[field] = props[field] end
    end
    for _, field in ipairs(Codec.accessoryFields) do
        local v = props[field]
        if type(v) == "string" and #v < 6000 and v:match("^[%d,%s]*$") then pcall(function() desc[field] = v end) end
    end
    for _, field in ipairs(Codec.colorFields) do
        local c = type(data.Colors) == "table" and data.Colors[field]
        if type(c) == "table" and Codec.number(c[1], 0, 1) and Codec.number(c[2], 0, 1) and Codec.number(c[3], 0, 1) then
            desc[field] = Color3.new(c[1], c[2], c[3])
        end
    end
    if data.HasAccessories and type(data.Accessories) == "table" then
        local accessories = {}
        for i, row in ipairs(data.Accessories) do
            if i > 150 then break end
            if type(row) == "table" and Codec.id(row.AssetId) and type(row.AccessoryType) == "string" then
                local ok, kind = pcall(function() return Enum.AccessoryType[row.AccessoryType] end)
                if ok and kind then
                    local item = {AssetId = row.AssetId, AccessoryType = kind, IsLayered = row.IsLayered == true}
                    if Codec.number(row.Order, 0, 1000) then item.Order = row.Order end
                    if Codec.number(row.Puffiness, 0, 10) then item.Puffiness = row.Puffiness end
                    for _, key in ipairs({"Position", "Rotation", "Scale"}) do
                        local v = row[key]
                        if type(v) == "table" and Codec.number(v[1], -10000, 10000) and Codec.number(v[2], -10000, 10000) and Codec.number(v[3], -10000, 10000) then
                            item[key] = Vector3.new(v[1], v[2], v[3])
                        end
                    end
                    table.insert(accessories, item)
                end
            end
        end
        local ok, err = pcall(function() desc:SetAccessories(accessories, true) end)
        if not ok then desc:Destroy(); error("Saved accessories are incompatible: " .. tostring(err), 0) end
    end
    if type(data.Emotes) == "table" then
        local emotes = {}; local count = 0
        local function add(name, ids)
            if emotes[name] or type(name) ~= "string" or #name > 100 or type(ids) ~= "table" or count >= 250 then return end
            local valid = {}
            for i, id in ipairs(ids) do if i > 20 then break end; if Codec.id(id) then table.insert(valid, id) end end
            if #valid > 0 then emotes[name] = valid; count = count + 1 end
        end
        -- The equipped ones first, so a long emote list never pushes them out of the wheel.
        for _, row in ipairs(type(data.EquippedEmotes) == "table" and data.EquippedEmotes or {}) do
            if type(row) == "table" and type(row.Name) == "string" then add(row.Name, data.Emotes[row.Name]) end
        end
        for name, ids in pairs(data.Emotes) do add(name, ids) end
        pcall(function() desc:SetEmotes(emotes) end)
        -- Only slots whose emote is in the list (see Codec.emoteSet).
        local _, equipped = Codec.emoteSet(emotes, data.EquippedEmotes)
        pcall(function() desc:SetEquippedEmotes(equipped) end)
    end
    if type(data.Makeup) == "table" then
        for i, row in ipairs(data.Makeup) do
            if i > 30 then break end
            if type(row) == "table" and Codec.id(row.AssetId) and type(row.MakeupType) == "string" and #row.MakeupType < 40 then
                pcall(function()
                    local item = Instance.new("MakeupDescription")
                    item.AssetId = row.AssetId; item.MakeupType = Enum.MakeupType[row.MakeupType]
                    if Codec.number(row.Order, -100000, 100000) and row.Order % 1 == 0 then item.Order = row.Order end
                    item.Parent = desc
                end)
            end
        end
    end
    if assigned == 0 then desc:Destroy(); error("No valid avatar data was found.", 0) end
    return desc
end

-- Deep copy of plain saved data (tables of numbers, strings and booleans).
function Codec.copy(value)
    if type(value) ~= "table" then return value end
    local out = {}
    for key, item in pairs(value) do out[key] = Codec.copy(item) end
    return out
end
-- What an appearance keeps besides its description: the gear its hand holds and the background behind it in the
-- Roblox menu's picture (see HELD ITEM AND BACKGROUND). Copied, checked, from one appearance's data to another's.
Codec.Extras = {"Gear", "Background"}
function Codec.extras(from, to)
    if type(to) ~= "table" then return to end
    for _, field in ipairs(Codec.Extras) do to[field] = type(from) == "table" and Codec.id(from[field]) or nil end
    return to
end

-- ITEM ADJUSTMENTS: move, turn, resize or fade single accessories of an appearance, keyed by accessory name and
--|YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
-- stored in the appearance data (Data.Tweaks = {[name] = {P = {x, y, z}, R = {x, y, z}, S = size, T = fade}}).
-- Effects (fire, particles, trails) keep their own size and stay visible, so a plain item with a nice effect can
-- shrink or disappear while its effect stays. Movement and turns are around the point the item hangs from, in
-- the axes of the body attachment; layered clothing can only fade, because it is fitted to the body.
local Tweaks = {Limits = {Move = 6, Turn = 180, SizeMin = 0.05, SizeMax = 5}}
function Tweaks.empty(row)
    local function zero(v) return not v or (v[1] == 0 and v[2] == 0 and v[3] == 0) end
    return not row or (zero(row.P) and zero(row.R) and (row.S == nil or row.S == 1) and (row.T == nil or row.T == 0))
end
-- Saved, imported and shared adjustments are checked like the rest of a skin; bad entries are dropped.
function Tweaks.clean(list)
    if type(list) ~= "table" then return nil end
    local out, count = {}, 0
    local function vector(v, limit)
        if type(v) == "table" and Codec.number(v[1], -limit, limit) and Codec.number(v[2], -limit, limit) and Codec.number(v[3], -limit, limit) then return {v[1], v[2], v[3]} end
    end
    for name, row in pairs(list) do
        if count >= 150 then break end
        if type(name) == "string" and #name <= 120 and type(row) == "table" then
            local clean = {P = vector(row.P, Tweaks.Limits.Move), R = vector(row.R, Tweaks.Limits.Turn)}
            if Codec.number(row.S, Tweaks.Limits.SizeMin, Tweaks.Limits.SizeMax) then clean.S = row.S end
            if Codec.number(row.T, 0, 1) then clean.T = row.T end
            if not Tweaks.empty(clean) then out[name] = clean; count = count + 1 end
        end
    end
    return next(out) and out or nil
end
-- The handle attachment that matches an attachment of the body (the point the item hangs from).
function Tweaks.mount(character, handle)
    for _, item in ipairs(handle:GetChildren()) do
        if item.ClassName == "Attachment" then
            for _, part in ipairs(character:GetChildren()) do
                if Appearance.isBody(part, character) then
                    local match = part:FindFirstChild(item.Name)
                    if match and match:IsA("Attachment") then return item, match, part end
                end
            end
        end
    end
end
-- The untouched values are kept as attributes the first time, so every adjustment starts from the original
-- item, and the copies made from it (on your character, in the repair list) carry them along.
function Tweaks.base(accessory, handle)
    if handle:GetAttribute("Lyra_BaseSize") ~= nil then return end
    handle:SetAttribute("Lyra_BaseSize", handle.Size); handle:SetAttribute("Lyra_BaseTransparency", handle.Transparency)
    for _, item in ipairs(handle:GetDescendants()) do
        if item.ClassName == "Attachment" and item.Parent == handle then item:SetAttribute("Lyra_BaseCFrame", item.CFrame)
        elseif item:IsA("DataModelMesh") then pcall(function() item:SetAttribute("Lyra_BaseScale", item.Scale); item:SetAttribute("Lyra_BaseOffset", item.Offset) end)
        elseif item:IsA("Decal") then item:SetAttribute("Lyra_BaseTransparency", item.Transparency) end
    end
    local mount = accessory:GetAttribute("Lyra_MountOffset")
    if typeof(mount) == "CFrame" then accessory:SetAttribute("Lyra_BaseMount", mount) end
end
-- Applies one adjustment (an empty one puts the item back as it was) to an accessory of a character or model.
function Tweaks.apply(character, accessory, row)
    local handle = accessory:FindFirstChild("Handle")
    if not handle or not handle:IsA("BasePart") then return end
    Tweaks.base(accessory, handle)
    row = row or {}
    local layered = handle:FindFirstChildOfClass("WrapLayer") ~= nil
    local size = (not layered and row.S) or 1
    local p, r = row.P or {0, 0, 0}, row.R or {0, 0, 0}
    local turn = layered and CFrame.new() or CFrame.new(p[1], p[2], p[3]) * CFrame.Angles(math.rad(r[1]), math.rad(r[2]), math.rad(r[3]))
    local fade = row.T or 0
    local function faded(base) return 1 - (1 - base) * (1 - fade) end
    local baseSize = handle:GetAttribute("Lyra_BaseSize")
    if typeof(baseSize) == "Vector3" then handle.Size = Vector3.new(math.max(baseSize.X * size, 0.01), math.max(baseSize.Y * size, 0.01), math.max(baseSize.Z * size, 0.01)) end
    local baseFade = handle:GetAttribute("Lyra_BaseTransparency")
    if type(baseFade) == "number" then handle.Transparency = faded(baseFade) end
    local mountAttachment, bodyAttachment, body = Tweaks.mount(character, handle)
    for _, item in ipairs(handle:GetDescendants()) do
        local baseCFrame = item:GetAttribute("Lyra_BaseCFrame")
        if typeof(baseCFrame) == "CFrame" and item:IsA("Attachment") then
            -- Attachments keep their place on the item as it resizes; the mount also carries the move and turn.
            local scaled = CFrame.new(baseCFrame.Position * size) * (baseCFrame - baseCFrame.Position)
            item.CFrame = item == mountAttachment and scaled * turn:Inverse() or scaled
        elseif item:IsA("DataModelMesh") and item:GetAttribute("Lyra_BaseScale") ~= nil then
            pcall(function() item.Scale = item:GetAttribute("Lyra_BaseScale") * size; item.Offset = item:GetAttribute("Lyra_BaseOffset") * size end)
        elseif item:IsA("Decal") and type(item:GetAttribute("Lyra_BaseTransparency")) == "number" then
            item.Transparency = faded(item:GetAttribute("Lyra_BaseTransparency"))
        end
    end
    -- A game item welded without a matching attachment moves through its saved weld offset instead.
    local baseMount = accessory:GetAttribute("Lyra_BaseMount")
    if typeof(baseMount) == "CFrame" then accessory:SetAttribute("Lyra_MountOffset", CFrame.new(baseMount.Position) * turn * (baseMount - baseMount.Position)) end
    -- The weld already holding the item follows at once.
    for _, joint in ipairs(handle:GetChildren()) do
        if joint:IsA("JointInstance") and (joint.Part0 == handle or joint.Part1 == handle) then
            local other = joint.Part0 == handle and joint.Part1 or joint.Part0
            local mountOffset = accessory:GetAttribute("Lyra_MountOffset")
            local c0, c1
            if mountAttachment and other == body then c0, c1 = bodyAttachment.CFrame, mountAttachment.CFrame
            elseif typeof(mountOffset) == "CFrame" and other and other.Name == accessory:GetAttribute("Lyra_MountBody") then c0, c1 = mountOffset, CFrame.new() end
            if c0 then
                if joint.Part1 == handle then joint.C0, joint.C1 = c0, c1 else joint.C0, joint.C1 = c1, c0 end
            end
        end
    end
end
function Tweaks.applyAll(character, list)
    if type(list) ~= "table" then return end
    for _, item in ipairs(character:GetChildren()) do
        if item:IsA("Accessory") and list[item.Name] then pcall(Tweaks.apply, character, item, list[item.Name]) end
    end
end

-- Visual snapshot codec. This block is embedded in the delivered single-file hub.
local Visual = {}
-- Skin overlay and skin sync are defined after the UI; declared here so applySnapshot can reach them. So are the
-- stand-ins (copies of you that a game builds), your in-game picture and the picture pose.
local Overlay, Sync, Presence = {Active = {}}, {Peers = {}, Shown = {}}, {}
local Mirror, Thumbs, Pose, Ident = {}, {}, {}, {}
Visual.MeshCache = {}; Visual.MeshOrder = {}
function Visual.clearCache()
    for _,part in pairs(Visual.MeshCache) do part:Destroy() end
    Visual.MeshCache = {}; Visual.MeshOrder = {}
end
function Visual.remember(part)
    if not part:IsA("MeshPart") or part.MeshId=="" or Visual.MeshCache[part.MeshId] then return end
    local ok,copy=pcall(function() return part:Clone() end)
    if not ok or not copy then return end
    copy.Parent=nil
    for _,child in ipairs(copy:GetChildren()) do child:Destroy() end
    Visual.MeshCache[part.MeshId]=copy; table.insert(Visual.MeshOrder,part.MeshId)
    if #Visual.MeshOrder>64 then
        local id=table.remove(Visual.MeshOrder,1); Visual.MeshCache[id]:Destroy(); Visual.MeshCache[id]=nil
    end
end
Visual.schemas = {
    Attachment = {CFrame="CFrame"}, Bone = {CFrame="CFrame"},
    SpecialMesh = {MeshId="string",TextureId="string",MeshType="Enum",Scale="Vector3",Offset="Vector3",VertexColor="Vector3"},
    BlockMesh = {Scale="Vector3",Offset="Vector3"}, CylinderMesh = {Scale="Vector3",Offset="Vector3"},
    Decal = {Texture="string",Face="Enum",Color3="Color3",Transparency="number"},
    Texture = {Texture="string",Face="Enum",Color3="Color3",Transparency="number",StudsPerTileU="number",StudsPerTileV="number",OffsetStudsU="number",OffsetStudsV="number"},
    SurfaceAppearance = {ColorMap="string",MetalnessMap="string",NormalMap="string",RoughnessMap="string",AlphaMode="Enum",Color="Color3"},
    WrapTarget = {CageMeshId="string",CageOrigin="CFrame",ImportOrigin="CFrame",Stiffness="number"},
    WrapLayer = {CageMeshId="string",CageOrigin="CFrame",ImportOrigin="CFrame",ReferenceMeshId="string",ReferenceOrigin="CFrame",BindOffset="CFrame",Order="number",Puffiness="number",Enabled="boolean",AutoSkin="Enum"},
    FaceControls = {},
}
-- Visual effects (horns, fire, sparkles, glows) are captured with their skin.
-- Effects the copier creates are tagged (Lyra_Effect), so a later skin only removes its own effects, never the game's.
Visual.effects = {
    -- How far and how fast particles travel (TimeScale, LockedToPart, VelocityInheritance, Shape*) and how an
    -- animated texture plays (Flipbook*) decide the look of a flame or aura as much as its colour and size.
    ParticleEmitter = {Enabled="boolean",Texture="string",Color="ColorSequence",Size="NumberSequence",Transparency="NumberSequence",
        Lifetime="NumberRange",Speed="NumberRange",Rate="number",SpreadAngle="Vector2",Rotation="NumberRange",RotSpeed="NumberRange",
        LightEmission="number",LightInfluence="number",Drag="number",Acceleration="Vector3",EmissionDirection="Enum",Shape="Enum",ZOffset="number",
        Brightness="number",TimeScale="number",Squash="NumberSequence",Orientation="Enum",LockedToPart="boolean",VelocityInheritance="number",
        WindAffectsDrag="boolean",ShapeStyle="Enum",ShapeInOut="Enum",ShapePartial="number",FlipbookLayout="Enum",FlipbookMode="Enum",
        FlipbookFramerate="NumberRange",FlipbookStartRandom="boolean"},
    Fire = {Enabled="boolean",Color="Color3",SecondaryColor="Color3",Heat="number",Size="number",TimeScale="number"},
    Sparkles = {Enabled="boolean",Color="Color3",SparkleColor="Color3",TimeScale="number"},
    Smoke = {Enabled="boolean",Color="Color3",Opacity="number",RiseVelocity="number",Size="number",TimeScale="number"},
    PointLight = {Enabled="boolean",Color="Color3",Brightness="number",Range="number",Shadows="boolean"},
    SpotLight = {Enabled="boolean",Color="Color3",Brightness="number",Range="number",Angle="number",Face="Enum",Shadows="boolean"},
    SurfaceLight = {Enabled="boolean",Color="Color3",Brightness="number",Range="number",Angle="number",Face="Enum",Shadows="boolean"},
    -- Trails and beams point at attachments; only sibling attachments (saved by name) can be rebuilt.
    Trail = {Enabled="boolean",Attachment0="Attachment",Attachment1="Attachment",Color="ColorSequence",Transparency="NumberSequence",
        WidthScale="NumberSequence",Texture="string",TextureLength="number",TextureMode="Enum",Lifetime="number",MinLength="number",
        MaxLength="number",LightEmission="number",LightInfluence="number",Brightness="number",FaceCamera="boolean"},
    Beam = {Enabled="boolean",Attachment0="Attachment",Attachment1="Attachment",Color="ColorSequence",Transparency="NumberSequence",
        Texture="string",TextureLength="number",TextureMode="Enum",TextureSpeed="number",Width0="number",Width1="number",
        CurveSize0="number",CurveSize1="number",Segments="number",LightEmission="number",LightInfluence="number",Brightness="number",
        FaceCamera="boolean",ZOffset="number"},
}
for class,fields in pairs(Visual.effects) do Visual.schemas[class]=fields end
function Visual.array(value, length, low, high)
    if type(value) ~= "table" or #value ~= length then return false end
    for i=1,length do if not Codec.number(value[i],low,high) then return false end end
    return true
end
function Visual.asset(value)
    return type(value)=="string" and #value<=300 and (value=="" or value:match("^rbxassetid://%d+$") or value:match("^https?://[%w%.%-]+/[^%s]*[?&]id=%d+") or value:match("^rbxasset://[%w%p]+$"))
end
function Visual.pack(value, kind)
    if kind=="CFrame" then return {value:GetComponents()} end
    if kind=="Vector3" then return {value.X,value.Y,value.Z} end
    if kind=="Color3" then return {value.R,value.G,value.B} end
    if kind=="Enum" then return {tostring(value.EnumType):gsub("^Enum%.",""),value.Name} end
    if kind=="Vector2" then return {value.X,value.Y} end
    if kind=="NumberRange" then return {value.Min,value.Max} end
    if kind=="ColorSequence" then
        local keys={}
        for i,key in ipairs(value.Keypoints) do keys[i]={key.Time,key.Value.R,key.Value.G,key.Value.B} end
        return keys
    end
    if kind=="NumberSequence" then
        local keys={}
        for i,key in ipairs(value.Keypoints) do keys[i]={key.Time,key.Value,key.Envelope} end
        return keys
    end
    return value
end
function Visual.unpack(value, kind)
    if kind=="CFrame" then return CFrame.new(table.unpack(value)) end
    if kind=="Vector3" then return Vector3.new(table.unpack(value)) end
    if kind=="Color3" then return Color3.new(table.unpack(value)) end
    if kind=="Enum" then return Enum[value[1]][value[2]] end
    if kind=="Vector2" then return Vector2.new(table.unpack(value)) end
    if kind=="NumberRange" then return NumberRange.new(value[1],value[2]) end
    if kind=="ColorSequence" then
        local keys={}
        for i,key in ipairs(value) do keys[i]=ColorSequenceKeypoint.new(key[1],Color3.new(key[2],key[3],key[4])) end
        return ColorSequence.new(keys)
    end
    if kind=="NumberSequence" then
        local keys={}
        for i,key in ipairs(value) do keys[i]=NumberSequenceKeypoint.new(key[1],key[2],key[3] or 0) end
        return NumberSequence.new(keys)
    end
    return value
end
function Visual.valueValid(value, kind, effect)
    if kind=="CFrame" then
        if not Visual.array(value,12,-128,128) then return false end
        for i=4,12 do if math.abs(value[i])>1.001 then return false end end
        return true
    end
    -- Effect vectors are forces (particle acceleration such as gravity), not sizes.
    if kind=="Vector3" then local limit=effect and 100000 or 128; return Visual.array(value,3,-limit,limit) end
    -- Roblox accepts colour channels above 1 (HDR glow, used by particle, fire and light effects).
    if kind=="Color3" then return Visual.array(value,3,-100000,100000) end
    if kind=="Enum" then
        return type(value)=="table" and #value==2 and type(value[1])=="string" and #value[1]<60 and type(value[2])=="string" and #value[2]<60
    end
    if kind=="Vector2" or kind=="NumberRange" then return Visual.array(value,2,-100000,100000) end
    if kind=="ColorSequence" then
        if type(value)~="table" or #value<2 or #value>20 then return false end
        for _,key in ipairs(value) do
            if not (Visual.array(key,4,-100000,100000) and Codec.number(key[1],0,1)) then return false end
        end
        return true
    end
    if kind=="NumberSequence" then
        if type(value)~="table" or #value<2 or #value>20 then return false end
        for _,key in ipairs(value) do
            if not (Codec.number(key[1],0,1) and Codec.number(key[2],-100000,100000) and Codec.number(key[3] or 0,-100000,100000)) then return false end
        end
        return true
    end
    if kind=="Attachment" then return type(value)=="string" and #value<=120 end
    if kind=="number" then return Codec.number(value,-100000,100000) end
    return type(value)==kind and (kind~="string" or #value<=300)
end
-- The value an item has as its own avatar made it: an item adjustment (see ITEM ADJUSTMENTS) keeps the untouched value
-- as an attribute, and the game hiding your character (see GAME INVISIBILITY) keeps the item's own transparency. A
-- skin is saved untouched, with its adjustments listed apart, so they are never applied twice.
Visual.BaseAttributes = {CFrame = "Lyra_BaseCFrame", Scale = "Lyra_BaseScale", Offset = "Lyra_BaseOffset"}
function Visual.ownValue(item, field)
    if field == "Transparency" then
        -- The untouched item first (an adjusted item is listed apart), else its own value before the game hid it.
        local base = item:GetAttribute("Lyra_BaseTransparency")
        if type(base) == "number" then return base end
        local hidden = item:GetAttribute("Lyra_CloakBase")
        if type(hidden) == "number" then return hidden end
        return nil
    end
    if field == "Enabled" then
        local enabled = item:GetAttribute("Lyra_CloakEnabled")
        if type(enabled) == "boolean" then return enabled end
        return nil
    end
    local name = Visual.BaseAttributes[field]
    local base = name and item:GetAttribute(name)
    if base ~= nil and typeof(base) == typeof(item[field]) then return base end
    return nil
end
-- skip: instances left out of the snapshot (the composed makeup decal, rebuilt from the description instead).
function Visual.nodes(parent, depth, skip)
    assert(depth<12,"Visual hierarchy is too deep.")
    local rows={}
    for _,item in ipairs(parent:GetChildren()) do
        local schema=Visual.schemas[item.ClassName]
        if schema and (skip and skip[item] or item:GetAttribute("Lyra_Makeup")) then schema=nil end
        if schema then
            local row={Class=item.ClassName,Name=item.Name,Properties={},Children=Visual.nodes(item,depth+1,skip)}
            for field,kind in pairs(schema) do
                local ok,value=pcall(function() return item[field] end)
                if ok and kind~="Attachment" then
                    local own=Visual.ownValue(item,field)
                    if own~=nil then value=own end
                end
                if ok and kind=="Attachment" then
                    if typeof(value)=="Instance" and value:IsA("Attachment") and value.Parent==parent then row.Properties[field]=value.Name end
                elseif ok then row.Properties[field]=Visual.pack(value,kind) end
            end
            table.insert(rows,row)
        end
    end
-- cache YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
    return rows
end
function Visual.validateNodes(rows, depth, budget)
    assert(type(rows)=="table" and depth<12,"Invalid visual nodes.")
    for _,row in ipairs(rows) do
        budget[1]=budget[1]+1; assert(budget[1]<=4000,"Skin is too complex.")
        assert(type(row)=="table" and Visual.schemas[row.Class] and type(row.Name)=="string" and #row.Name<=120,"Invalid visual node.")
        assert(type(row.Properties)=="table","Propriedades visuais ausentes.")
        for field,value in pairs(row.Properties) do
            local kind=Visual.schemas[row.Class][field]
            if not (kind and Visual.valueValid(value,kind,Visual.effects[row.Class]~=nil)) then
                -- An effect is decoration: one value it cannot use is dropped, the rest of the skin still applies.
                assert(Visual.effects[row.Class],"Invalid visual property: "..tostring(field))
                row.Properties[field]=nil
            end
        end
        Visual.validateNodes(row.Children or {},depth+1,budget)
    end
end
function Visual.part(part, skip)
    Visual.remember(part)
    local size=part:GetAttribute("Lyra_BaseSize")
    if typeof(size)~="Vector3" then size=part.Size end
    -- A body part the game hides right now (see GAME INVISIBILITY) is saved as the avatar shows it.
    local transparency=Visual.ownValue(part,"Transparency")
    if transparency==nil then
        local cloaked=Cloak.Parts and Cloak.Parts[part]
        transparency=cloaked and cloaked.Wanted or part.Transparency
    end
    if transparency>0.99 then transparency=1 end
    local row={Class=part:IsA("MeshPart") and "MeshPart" or "Part",Size=Visual.pack(size,"Vector3"),Color=Visual.pack(part.Color,"Color3"),Transparency=transparency,Nodes=Visual.nodes(part,0,skip)}
    if part:IsA("MeshPart") then row.MeshId=part.MeshId; row.TextureId=part.TextureID end
    row.Material=part.Material.Name; row.Reflectance=part.Reflectance
    local original=part:FindFirstChild("OriginalSize")
    if original and original:IsA("Vector3Value") then row.OriginalSize=Visual.pack(original.Value,"Vector3") end
    local scaleType=part:FindFirstChild("AvatarPartScaleType")
    if scaleType and scaleType:IsA("StringValue") then row.ScaleType=scaleType.Value end
    return row
end
function Visual.validate(v)
    assert(type(v)=="table" and v.Version==1 and (v.RigType=="R15" or v.RigType=="R6"),"Invalid skin format or rig.")
    assert(type(v.Body)=="table" and type(v.Accessories)=="table" and #v.Accessories<=150,"Invalid body/accessories.")
    local count,budget=0,{0}
    local function part(row)
        assert(type(row)=="table" and (row.Class=="Part" or row.Class=="MeshPart"),"Invalid part type.")
        assert(Visual.array(row.Size,3,0.001,64) and Visual.array(row.Color,3,0,1) and Codec.number(row.Transparency,0,1),"Invalid dimensions or colors.")
        if row.Class=="MeshPart" then assert(Visual.asset(row.MeshId) and row.MeshId~="" and Visual.asset(row.TextureId or ""),"Invalid mesh/texture ID.") end
        if row.Nodes then Visual.validateNodes(row.Nodes,0,budget) end
        if row.OriginalSize then assert(Visual.array(row.OriginalSize,3,0.001,64),"Invalid original dimensions.") end
        if row.ScaleType then assert(type(row.ScaleType)=="string" and #row.ScaleType<80,"Invalid scale type.") end
    end
    for name,row in pairs(v.Body) do assert(S.BD[name] and name~="HumanoidRootPart","Membro desconhecido."); part(row); count=count+1 end
    assert(count>0 and count<=20,"The skin contains no body.")
    for _,row in ipairs(v.Accessories) do
        assert(type(row)=="table" and type(row.Name)=="string" and #row.Name<=120,"Invalid accessory."); part(row.Handle)
        if row.AttachmentPoint then assert(Visual.valueValid(row.AttachmentPoint,"CFrame"),"Invalid attachment.") end
        -- The saved weld is only a fallback: a damaged one is dropped instead of rejecting the skin.
        if row.Mount~=nil and not (type(row.Mount)=="table" and type(row.Mount.Body)=="string" and S.BD[row.Mount.Body]
            and Visual.valueValid(row.Mount.Offset,"CFrame")) then row.Mount=nil end
        -- The catalog item it is (see Visual.overlay) and whether it is made of several parts are optional too.
        if row.AssetId~=nil and not Codec.id(row.AssetId) then row.AssetId=nil end
        if row.Multi~=nil and row.Multi~=true then row.Multi=nil end
    end
    for name,id in pairs(v.Clothes or {}) do assert((name=="Shirt" or name=="Pants" or name=="Graphic") and Visual.asset(id),"Invalid clothing.") end
    for name,color in pairs(v.Colors or {}) do assert(({Head=true,Torso=true,LeftArm=true,RightArm=true,LeftLeg=true,RightLeg=true})[name] and Visual.array(color,3,0,1),"Invalid color.") end
    assert(type(v.Links or {})=="table" and #(v.Links or {})<=32,"Invalid joints.")
    for _,link in ipairs(v.Links or {}) do
        assert(type(link)=="table" and S.BD[link.A] and S.BD[link.B] and Visual.valueValid(link.C0,"CFrame") and Visual.valueValid(link.C1,"CFrame"),"Invalid body connection.")
    end
    for name,value in pairs(v.Scales or {}) do
        assert(({BodyDepthScale=true,BodyHeightScale=true,BodyWidthScale=true,HeadScale=true,BodyProportionScale=true,BodyTypeScale=true})[name] and Codec.number(value,0,10),"Invalid scale.")
    end
    if v.HipHeight~=nil then assert(Codec.number(v.HipHeight,0,64),"Invalid height.") end
    -- The pose kept for pictures is optional: a damaged one is dropped instead of rejecting the skin.
    if v.Pose~=nil then
        local joints,valid=0,type(v.Pose)=="table"
        for name,offset in pairs(valid and v.Pose or {}) do
            joints=joints+1
            if joints>20 or type(name)~="string" or not S.BD[name] or not Visual.valueValid(offset,"CFrame") then valid=false; break end
        end
        if not valid then v.Pose=nil end
    end
    -- The rig the kept pose was made on, when it isn't the skin's own (see Looks.capture).
    if v.PoseRig~=nil and v.PoseRig~="R15" and v.PoseRig~="R6" then v.PoseRig=nil end
    -- Skins saved before poses were kept apart may still carry one in their joints.
    if not v.PoseChecked then pcall(Visual.unpose,v,false) end
    if v.RootSize then assert(Visual.array(v.RootSize,3,0.001,64),"Invalid root dimensions.") end
    assert(type(v.Animations or {})=="table" and #(v.Animations or {})<=100,"Invalid animations.")
    for _,row in ipairs(v.Animations or {}) do
        assert(type(row)=="table" and type(row.Path)=="table" and #row.Path<=12 and Visual.asset(row.Id),"Invalid animation.")
        for _,name in ipairs(row.Path) do assert(type(name)=="string" and #name<=120,"Invalid animation path.") end
        -- Weights and the whole-set mark are optional; a bad one is dropped instead of rejecting the skin.
        if row.Weight~=nil and not Codec.number(row.Weight,0,100000) then row.Weight=nil end
        if row.Full~=nil and row.Full~=true then row.Full=nil end
    end
    return v
end
-- The body part an accessory is really welded to on this character, and the handle's offset from it.
function Visual.mount(character, handle, links)
    for _,link in ipairs(links) do
        local body
        if link.B==handle and Appearance.isBody(link.A,character) then body=link.A
        elseif link.A==handle and Appearance.isBody(link.B,character) then body=link.B end
        if body then
            local offset=body.CFrame:ToObjectSpace(handle.CFrame)
            if offset.Position.Magnitude<=64 then return {Body=body.Name,Offset=Visual.pack(offset,"CFrame")} end
        end
    end
end
-- SAVED POSE: posing games bend the body by changing its joints. A skin saved like that kept the bent joints, so
-- wearing it twisted the character or lifted it off the ground. A skin is saved standing; a real pose is kept apart
-- (Visual.Pose: the offset of each bent joint from its rest) and only shows in the Roblox menu picture and the game's
-- pictures of you (see POSE).
-- R6 joints at rest, by the part they move: the parent part, the shared rotation, and where the joint sits on each
-- part for its size (a classic R6 body: torso 2x2x1, limbs 1x2x1, head 2x1x1).
do
    local function turn(...) return CFrame.new(0, 0, 0, ...) end
    local back, right, left = turn(-1, 0, 0, 0, 0, 1, 0, 1, 0), turn(0, 0, 1, 0, 1, 0, -1, 0, 0), turn(0, 0, -1, 0, 1, 0, 1, 0, 0)
    Visual.R6Rest = {
        Head = {A = "Torso", R = back, P0 = function(t) return Vector3.new(0, t.Y / 2, 0) end, P1 = function(_, b) return Vector3.new(0, -b.Y / 2, 0) end},
        Torso = {A = "HumanoidRootPart", R = back, P0 = function() return Vector3.zero end, P1 = function() return Vector3.zero end},
        ["Right Arm"] = {A = "Torso", R = right, P0 = function(t) return Vector3.new(t.X / 2, t.Y / 4, 0) end, P1 = function(_, b) return Vector3.new(-b.X / 2, b.Y / 4, 0) end},
        ["Left Arm"] = {A = "Torso", R = left, P0 = function(t) return Vector3.new(-t.X / 2, t.Y / 4, 0) end, P1 = function(_, b) return Vector3.new(b.X / 2, b.Y / 4, 0) end},
        ["Right Leg"] = {A = "Torso", R = right, P0 = function(t) return Vector3.new(t.X / 2, -t.Y / 2, 0) end, P1 = function(_, b) return Vector3.new(b.X / 2, b.Y / 2, 0) end},
        ["Left Leg"] = {A = "Torso", R = left, P0 = function(t) return Vector3.new(-t.X / 2, -t.Y / 2, 0) end, P1 = function(_, b) return Vector3.new(-b.X / 2, b.Y / 2, 0) end},
    }
end
-- Limbs: a pose bends at least one of them; a game that only turns the head or torso (looking around) is no pose.
Visual.PoseLimbs = {LeftUpperArm = true, RightUpperArm = true, LeftLowerArm = true, RightLowerArm = true, LeftUpperLeg = true,
    RightUpperLeg = true, LeftLowerLeg = true, RightLowerLeg = true, ["Left Arm"] = true, ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true}
Visual.PoseBends = {LeftLowerArm = true, RightLowerArm = true, LeftUpperLeg = true, RightUpperLeg = true, LeftLowerLeg = true, RightLowerLeg = true,
    ["Left Leg"] = true, ["Right Leg"] = true}
-- Rest offsets (C0, C1) of the joint from part a to part b of a saved skin, or nil when unknown. R15 joints sit on
-- the rig attachments both parts share (Roblox builds them from those); R6 joints on the classic places.
function Visual.restJoint(v, a, b)
    local rowA, rowB = v.Body[a], v.Body[b]
    if not rowA or not rowB then
        -- The root is not stored as a body part; its size is.
        if a ~= "HumanoidRootPart" or not rowB then return nil end
    end
    if v.RigType == "R15" then
        local function attachments(row)
            local list = {}
            for _, node in ipairs(row and row.Nodes or {}) do
                if node.Class == "Attachment" and type(node.Name) == "string" and node.Name:match("RigAttachment$")
                    and type(node.Properties) == "table" and Visual.valueValid(node.Properties.CFrame, "CFrame") then
                    list[node.Name] = Visual.unpack(node.Properties.CFrame, "CFrame")
                end
            end
            return list
        end
        local listA, listB = attachments(rowA), attachments(rowB)
        local best
        for name, cf in pairs(listB) do
            if listA[name] and (not best or name < best) then best = name end
        end
        if best then return listA[best], listB[best] end
        return nil
    end
    local rest = Visual.R6Rest[b]
    if not rest or rest.A ~= a then return nil end
    local sizeA = rowA and Visual.unpack(rowA.Size, "Vector3") or (v.RootSize and Visual.unpack(v.RootSize, "Vector3")) or Vector3.new(2, 2, 1)
    local sizeB = Visual.unpack(rowB.Size, "Vector3")
    return CFrame.new(rest.P0(sizeA, sizeB)) * rest.R, CFrame.new(rest.P1(sizeA, sizeB)) * rest.R
end
-- Puts the bent joints of a saved skin back at rest and returns the pose they made ({[part] = packed offset}) and
-- whether it is a real pose: three or more joints bent, a limb among them, an elbow, knee or leg among them (or four
-- joints at least). force: a capture (R15 joints always go back to rest, a real pose or not); otherwise an older skin,
-- which is only changed when it holds a real pose.
function Visual.unpose(v, force)
    v.PoseChecked = true
    local rows, bent, limb, bend = {}, 0, false, false
    for index, link in ipairs(v.Links or {}) do
        local ok, r0, r1 = pcall(Visual.restJoint, v, link.A, link.B)
        if ok and r0 and r1 then
            local c0, c1 = Visual.unpack(link.C0, "CFrame"), Visual.unpack(link.C1, "CFrame")
            local offset = r0:Inverse() * c0 * c1:Inverse() * r1
            local _, angle = offset:ToAxisAngle()
            angle = math.deg(math.abs(angle))
            local distance = offset.Position.Magnitude
            if angle > 12 or distance > 0.15 then
                table.insert(rows, {Index = index, Part = link.B, R0 = r0, R1 = r1, Offset = offset})
                if angle >= 20 or distance >= 0.5 then
                    bent = bent + 1
                    if Visual.PoseLimbs[link.B] then limb = true end
                    if Visual.PoseBends[link.B] then bend = true end
                end
            end
        end
    end
    local real = bent >= 3 and limb and (bend or bent >= 4)
    if force then Visual.LastPoseCheck = {Rig = v.RigType, Bent = bent, Limb = limb, Bend = bend, Real = real} end
    if not real and not (force and v.RigType == "R15") then return nil, false end
    local pose = {}
    for _, row in ipairs(rows) do
        local link = v.Links[row.Index]
        link.C0 = Visual.pack(row.R0, "CFrame"); link.C1 = Visual.pack(row.R1, "CFrame")
        pose[row.Part] = Visual.pack(row.Offset, "CFrame")
    end
    -- An older skin that held a real pose was posed on purpose: its pictures keep it.
    if real and not force then v.Pose = pose end
    return real and pose or nil, real
end
-- Yields. Poses a model with a skin's saved pose (the same rig only); returns whether it did.
function Visual.applyPose(model, v)
    if type(v) ~= "table" or type(v.Pose) ~= "table" or not next(v.Pose) then return false end
    if F.getTrueRigType(model) ~= Enum.HumanoidRigType[v.RigType] then return false end
    local map = {}
    for name, offset in pairs(v.Pose) do map[name] = Visual.unpack(offset, "CFrame") end
    Pose.set(model, map)
    return true
end
-- A joint as the drawn avatar shows it (visual-only). It copies your character's pose either into its joints'
-- Transform or, with its joints off, by placing each part where your character's is. Either way the turn between the
-- two parts is the pose; an offset of the joint itself (a crouch) is only taken from its Transform.
function Visual.drawnJoint(link)
    local ok, c0 = pcall(function()
        local relative = link.C0:Inverse() * link.A.CFrame:ToObjectSpace(link.B.CFrame) * link.C1
        return link.C0 * CFrame.new(link.Transform.Position) * (relative - relative.Position)
    end)
    return ok and c0 or link.C0 * link.Transform
end
-- The pose a look's pictures use: the one saved with the skin, else one kept for the avatar worn now (a pose you
-- chose to keep after saving it). Returns a table with RigType and Pose, or nil.
function Visual.picturePose(snapshot)
    if type(snapshot) ~= "table" then return nil end
    local v = type(snapshot.Data) == "table" and snapshot.Data.Visual or nil
    if type(v) == "table" and type(v.Pose) == "table" and next(v.Pose) then
        local rig = v.PoseRig or v.RigType
        if Enum.HumanoidRigType[rig] then return {RigType = rig, Pose = v.Pose} end
    end
    local kept = snapshot.Pose
    if type(kept) == "table" and type(kept.Pose) == "table" and next(kept.Pose) and Enum.HumanoidRigType[kept.RigType] then return kept end
    return nil
end
-- Returns the snapshot and the names of accessories it had to leave out.
-- source: the model the look is read from, your character itself or (visual-only) the avatar drawn over it, whose
-- joints are read as it shows them (see Visual.drawnJoint).
function Visual.meshOf(handle)
    if handle:IsA("MeshPart") then return handle.MeshId end
    local mesh=handle:FindFirstChildWhichIsA("SpecialMesh")
    return mesh and mesh.MeshId or ""
end
-- Yields. The catalog id of each accessory of a description, by name: {Name = {{Id, Mesh}, ...}}. Items a game put on
-- (a Catalog Creator outfit) carry no id of ours, so the save looks them up here (see Visual.capture).
function Visual.descIds(desc,rig)
    local ids={}
    local model=API.model(desc,rig)
    for _,item in ipairs(model:GetChildren()) do
        local id=item:IsA("Accessory") and Codec.id(item:GetAttribute("Lyra_AssetId"))
        local handle=id and item:FindFirstChild("Handle")
        if handle and handle:IsA("BasePart") then
            ids[item.Name]=ids[item.Name] or {}
            table.insert(ids[item.Name],{Id=id,Mesh=Mirror.assetKey(Visual.meshOf(handle))})
        end
    end
    pcall(function() model:Destroy() end)
    return ids
end
function Visual.lookupId(ids,item,handle)
    local rows=ids and ids[item.Name]
    if not rows then return nil end
    local mesh=Mirror.assetKey(Visual.meshOf(handle))
    for index,row in ipairs(rows) do
        if row.Mesh==mesh then table.remove(rows,index); return row.Id end
    end
    if #rows==1 then return table.remove(rows,1).Id end
    return nil
end
-- ids: the description's catalog ids (see Visual.descIds), for items that carry none.
function Visual.capture(character, animations, source, ids)
    local model=source or character
    local hum=model and model:FindFirstChildOfClass("Humanoid")
    assert(hum and character==lp.Character,"Wait for your character to load.")
    -- Your character keeps the game's HipHeight with the body raised on the root joint (see fitGeometry): the skin is
    -- saved as the avatar stands, without that offset.
    local hipLift=not source and hum:GetAttribute("Lyra_HipLift") or nil
    hipLift=type(hipLift)=="number" and hipLift or 0
    local v={Version=1,RigType=hum.RigType.Name,Body={},Accessories={},Clothes={},Colors={},Scales={},Links={},HipHeight=hum.HipHeight+hipLift,Animations=animations or {}}
    local root=model:FindFirstChild("HumanoidRootPart")
    assert(root and root:IsA("BasePart"),"Wait for your character's root to load.")
    v.RootSize=Visual.pack(root.Size,"Vector3")
    -- Makeup is one decal composed from the description's makeup items. The description already carries them,
    -- so the generated decal is left out and rebuilt on apply.
    local skip={}
    for _,source in ipairs(hum:GetChildren()) do
        if source:IsA("HumanoidDescription") then
            for _,item in ipairs(source:GetChildren()) do
                if item.ClassName=="MakeupDescription" then
                    local ok,decal=pcall(function() return item:GetAppliedInstance() end)
                    if ok and typeof(decal)=="Instance" then skip[decal]=true end
                end
            end
        end
    end
    local links,skipped=Rig.links(model),{}
    for _,part in ipairs(model:GetChildren()) do
        if Appearance.isBody(part,model) and part.Name~="HumanoidRootPart" then
            local display=model:FindFirstChild("LyraVisual_"..part.Name)
            if display and display:GetAttribute("Lyra_VisualFor")~=part.Name then display=nil end
            local row=Visual.part(display or part,skip)
            if display then
                for i=#row.Nodes,1,-1 do if row.Nodes[i].Class=="Attachment" then table.remove(row.Nodes,i) end end
                for _,node in ipairs(Visual.nodes(part,0,skip)) do if node.Class=="Attachment" then table.insert(row.Nodes,node) end end
            end
            row.Size=Visual.pack(part.Size,"Vector3"); v.Body[part.Name]=row
        elseif part:IsA("Accessory") then
            local handle=part:FindFirstChild("Handle")
            if handle and handle:IsA("BasePart") then
                local single=true
                for _,child in ipairs(part:GetDescendants()) do if child:IsA("BasePart") and child~=handle then single=false; break end end
                -- A catalog item keeps its id: the skin is rebuilt with Roblox's own copy of it (see Visual.overlay).
                local assetId=Codec.id(part:GetAttribute("Lyra_AssetId")) or Visual.lookupId(ids,part,handle)
                -- An item built from several parts can only come back as that catalog item; without one it is left
                -- out instead of failing the whole save.
                if (single or assetId) and #v.Accessories<150 then
                    local mount=Visual.mount(model,handle,links)
                    -- A moved or turned item is saved where its avatar puts it; the move is in the skin's adjustments.
                    local baseMount=part:GetAttribute("Lyra_BaseMount")
                    if mount and typeof(baseMount)=="CFrame" and baseMount.Position.Magnitude<=64 then mount.Offset=Visual.pack(baseMount,"CFrame") end
                    table.insert(v.Accessories,{Name=part.Name,Type=part.AccessoryType.Name,Handle=Visual.part(handle,skip),
                        AttachmentPoint=Visual.pack(part.AttachmentPoint,"CFrame"),Mount=mount,AssetId=assetId,Multi=(not single) or nil})
                else table.insert(skipped,part.Name) end
            end
        elseif part:IsA("Shirt") then v.Clothes.Shirt=part.ShirtTemplate
        elseif part:IsA("Pants") then v.Clothes.Pants=part.PantsTemplate
        elseif part:IsA("ShirtGraphic") then v.Clothes.Graphic=part.Graphic
        elseif part:IsA("BodyColors") then
            for _,name in ipairs({"Head","Torso","LeftArm","RightArm","LeftLeg","RightLeg"}) do v.Colors[name]=Visual.pack(part[name.."Color3"],"Color3") end
        end
    end
    for _,name in ipairs({"BodyDepthScale","BodyHeightScale","BodyWidthScale","HeadScale","BodyProportionScale","BodyTypeScale"}) do
        local value=hum:FindFirstChild(name); if value and value:IsA("NumberValue") then v.Scales[name]=value.Value end
    end
    for _,link in ipairs(links) do
        if Appearance.isBody(link.A,model) and Appearance.isBody(link.B,model) then
            local c0=source and Visual.drawnJoint(link) or link.C0
            local c1=link.C1
            if hipLift~=0 then
                if link.A.Name=="HumanoidRootPart" then c0=CFrame.new(0,-hipLift,0)*c0
                elseif link.B.Name=="HumanoidRootPart" then c1=CFrame.new(0,-hipLift,0)*c1 end
            end
            table.insert(v.Links,{A=link.A.Name,B=link.B.Name,C0=Visual.pack(c0,"CFrame"),C1=Visual.pack(c1,"CFrame")})
        end
    end
    -- Saved standing (see SAVED POSE). A real pose is offered for your pictures; one made while holding a tool is a
    -- game aiming it, not a pose.
    local pose,real=Visual.unpose(v,true)
    if not real or character:FindFirstChildOfClass("Tool") then pose=nil end
    return Visual.validate(v),skipped,pose
end
function Visual.legacy(raw)
    assert(type(raw)=="table" and (type(raw.MembrosCorpo)=="table" or type(raw.MembrosCustom)=="table"),"Old JSON not recognized.")
    local v={Version=1,RigType=raw.RigType,Body={},Accessories={},Clothes=raw.Roupas or {},Colors=raw.Cores or {},Scales=raw.Escalas or {},Links={},Animations={},Legacy=true}
    local function part(old, accessory)
        local row={Class="MeshPart",Size=old.Size,Color=old.Color,Transparency=old.Transparency or 0,MeshId=old.MeshId,TextureId=old.TextureId or "",Nodes={}}
        if old.SurfaceColorMap and old.SurfaceColorMap~="" then table.insert(row.Nodes,{Class="SurfaceAppearance",Name="SurfaceAppearance",Properties={ColorMap=old.SurfaceColorMap},Children={}}) end
        if accessory and old.AttachmentName then table.insert(row.Nodes,{Class="Attachment",Name=old.AttachmentName,Properties={CFrame=old.AttachmentCFrame},Children={}}) end
        -- These files do not record whether a Handle was a SpecialMesh or MeshPart.
        -- Non-default mesh transforms identify the SpecialMesh form unambiguously.
        local sc,off=old.Scale,old.Offset
        if accessory and ((sc and (sc[1]~=1 or sc[2]~=1 or sc[3]~=1)) or (off and (off[1]~=0 or off[2]~=0 or off[3]~=0))) then
            row.Class="Part"
            table.insert(row.Nodes,{Class="SpecialMesh",Name="Mesh",Properties={MeshType={"MeshType","FileMesh"},MeshId=old.MeshId,TextureId=old.TextureId or "",Scale=sc or {1,1,1},Offset=off or {0,0,0}},Children={}})
        end
        return row
    end
    for name,row in pairs(raw.MembrosCustom or raw.MembrosCorpo) do v.Body[name]=part(row,false) end
    for _,row in ipairs(raw.Acessorios or {}) do table.insert(v.Accessories,{Name=row.Nome or "Accessory",Handle=part(row,true)}) end
    if raw.IsHeadless and v.Body.Head then v.Body.Head.Transparency=1 end
    for name,id in pairs(raw.Animacoes or {}) do table.insert(v.Animations,{Path={name},Id=id}) end
    Visual.validate(v)
    local properties={}; for _,field in ipairs(Codec.assetFields) do properties[field]=0 end
    local map={BodyTypeScale="BodyTypeScale",BodyProportionScale="ProportionScale",HeadScale="HeadScale",BodyWidthScale="WidthScale",BodyDepthScale="DepthScale",BodyHeightScale="HeightScale"}
    for name,value in pairs(v.Scales) do properties[map[name]]=value end
    local colors={}; for name,color in pairs(v.Colors) do colors[name.."Color"]=color end
    return {Version=2,Properties=properties,Colors=colors,Accessories={},HasAccessories=true,Emotes={},EquippedEmotes={},Visual=v}
end
-- Whether a property already holds a saved value. Values that only differ in the way they are written (an asset as
-- rbxassetid:// or as a web link, a number rounded by the save file) are not written again: rewriting the textures of
-- an item Roblox made could stop them from loading.
function Visual.same(a, b, kind)
    if a == b then return true end
    if kind == "string" then return type(a) == "string" and type(b) == "string" and a ~= "" and Mirror.assetKey(a) == Mirror.assetKey(b) end
    if kind == "number" then return type(a) == "number" and type(b) == "number" and math.abs(a - b) < 1e-5 end
    if kind == "CFrame" then return Fit.same(a, b) end
    if kind == "Vector3" then return typeof(a) == "Vector3" and typeof(b) == "Vector3" and (a - b).Magnitude < 1e-4 end
    if kind == "Color3" then return typeof(a) == "Color3" and typeof(b) == "Color3" and math.abs(a.R - b.R) + math.abs(a.G - b.G) + math.abs(a.B - b.B) < 1e-4 end
    return false
end
function Visual.restoreNodes(parent, rows, preserveAttachments)
    local kept,links={},{}
    for _,row in ipairs(rows or {}) do
        local item=parent:FindFirstChild(row.Name)
        if item and item.ClassName~=row.Class then item:Destroy(); item=nil end
        local effect=Visual.effects[row.Class]~=nil
        if not item then
            item=Instance.new(row.Class); item.Name=row.Name; item.Parent=parent
            if effect then item:SetAttribute("Lyra_Effect",true) end
        end
        kept[item]=true
        for field,value in pairs(row.Properties) do
            local kind=Visual.schemas[row.Class][field]
            if kind=="Attachment" then
                table.insert(links,{Item=item,Field=field,Name=value})
            else
                local ok,err=pcall(function()
                    local decoded=Visual.unpack(value,kind)
                    if not Visual.same(item[field],decoded,kind) then item[field]=decoded end
                end)
                -- A single effect property the game refuses should not block the whole skin.
                if not ok and not effect then error("Could not rebuild "..row.Class.."."..field..": "..tostring(err),0) end
            end
        end
        Visual.restoreNodes(item,row.Children,false)
    end
    -- Attachments may come after the trail/beam that uses them, so links are set once every sibling exists.
    for _,link in ipairs(links) do
        local target=parent:FindFirstChild(link.Name)
        if target and target:IsA("Attachment") then pcall(function() link.Item[link.Field]=target end) end
    end
    for _,item in ipairs(parent:GetChildren()) do
        local ours=Visual.effects[item.ClassName]~=nil and item:GetAttribute("Lyra_Effect")==true
        local schemaOwned=Visual.schemas[item.ClassName] and Visual.effects[item.ClassName]==nil
        if (schemaOwned or ours) and not kept[item] and not (preserveAttachments and item:IsA("Attachment")) and not item:GetAttribute("Lyra_Makeup") then item:Destroy() end
    end
end
function Visual.mesh(id)
    if Visual.MeshCache[id] then return Visual.MeshCache[id]:Clone() end
    local ok,part=pcall(function() return game:GetService("AssetService"):CreateMeshPartAsync(Content.fromUri(id),{}) end)
    if not ok then ok,part=pcall(function() return game:GetService("InsertService"):CreateMeshPartAsync(id,Enum.CollisionFidelity.Default,Enum.RenderFidelity.Automatic) end) end
    assert(ok and part and part:IsA("MeshPart"),"Roblox could not load mesh "..id..". Your character has not been changed yet.")
    if not IsAlive() then part:Destroy(); error("Execution ended.",0) end
    Visual.remember(part)
    return part
end
function Visual.applyPart(target,row,preserveAttachments)
    if row.Class=="MeshPart" and target.MeshId~=row.MeshId then
        local mesh=Visual.mesh(row.MeshId)
        local ok,err=pcall(function() target:ApplyMesh(mesh) end); mesh:Destroy()
        assert(ok,"Falha ao preparar a malha: "..tostring(err))
    end
    target.Size=Visual.unpack(row.Size,"Vector3"); target.Color=Visual.unpack(row.Color,"Color3"); target.Transparency=row.Transparency
    if target:IsA("MeshPart") and not Visual.same(target.TextureID,row.TextureId or "","string") then target.TextureID=row.TextureId or "" end
    if row.Material then pcall(function() target.Material=Enum.Material[row.Material] end) end
    target.Reflectance=row.Reflectance or 0
    Visual.restoreNodes(target,row.Nodes,preserveAttachments)
    local original=target:FindFirstChild("OriginalSize") or Instance.new("Vector3Value")
    original.Name="OriginalSize"; original.Value=Visual.unpack(row.OriginalSize or row.Size,"Vector3"); original.Parent=target
    if row.ScaleType then
        local scaleType=target:FindFirstChild("AvatarPartScaleType") or Instance.new("StringValue")
        scaleType.Name="AvatarPartScaleType"; scaleType.Value=row.ScaleType; scaleType.Parent=target
    end
end
-- Returns the model and the names of accessories that could not be attached on this rig.
function Visual.overlay(model,v)
    Visual.validate(v)
    model:SetAttribute("Lyra_VisualSnapshot",true)
    local hum=model:FindFirstChildOfClass("Humanoid")
    assert(hum and hum.RigType.Name==v.RigType,"This skin is "..v.RigType.."; apply it to a character of the same rig type.")
    hum.AutomaticScalingEnabled=false
    if v.RootSize then model:FindFirstChild("HumanoidRootPart").Size=Visual.unpack(v.RootSize,"Vector3") end
    local oldSizes={}
    for name,row in pairs(v.Body) do
        local part=model:FindFirstChild(name); assert(part and part:IsA("BasePart"),"Missing limb: "..name)
        oldSizes[name]=part.Size
        if part.ClassName~=row.Class then
            local replacement=Instance.new(row.Class); replacement.Name=name; replacement.CFrame=part.CFrame; replacement.Size=part.Size; replacement.Parent=model
            for _,child in ipairs(part:GetChildren()) do child.Parent=replacement end
            for _,joint in ipairs(model:GetDescendants()) do
                if joint:IsA("JointInstance") or joint:IsA("WeldConstraint") then
                    if joint.Part0==part then joint.Part0=replacement end
                    if joint.Part1==part then joint.Part1=replacement end
                end
            end
            replacement.Parent=model; part:Destroy(); part=replacement
        end
        -- Generated AnimationConstraints may refer to sockets absent in an older
        -- Motor6D snapshot. Retain those instances and set their offsets below.
        Visual.applyPart(part,row,true)
    end
    local function scaleOffset(cf,ratio) return CFrame.new(cf.Position*ratio)*(cf-cf.Position) end
    local links=Rig.links(model)
    if v.Legacy then
        for name,old in pairs(oldSizes) do
            local part=model:FindFirstChild(name)
            for _,at in ipairs(part:GetChildren()) do if at:IsA("Attachment") and not at:IsA("Bone") then at.CFrame=scaleOffset(at.CFrame,part.Size/old) end end
        end
    end
    for _,link in ipairs(links) do
        if Appearance.isBody(link.A,model) and Appearance.isBody(link.B,model) then
            local a,b
            for _,saved in ipairs(v.Links) do
                if saved.A==link.A.Name and saved.B==link.B.Name then a=Visual.unpack(saved.C0,"CFrame"); b=Visual.unpack(saved.C1,"CFrame"); break end
                if saved.B==link.A.Name and saved.A==link.B.Name then b=Visual.unpack(saved.C0,"CFrame"); a=Visual.unpack(saved.C1,"CFrame"); break end
            end
            if not a and v.Legacy then
                local ra=oldSizes[link.A.Name] and link.A.Size/oldSizes[link.A.Name] or Vector3.new(1,1,1)
                local rb=oldSizes[link.B.Name] and link.B.Size/oldSizes[link.B.Name] or Vector3.new(1,1,1)
                a=scaleOffset(link.C0,ra); b=scaleOffset(link.C1,rb)
            end
            assert(a and b,"The skin is missing the joints required for "..link.A.Name.." / "..link.B.Name)
            if link.Object:IsA("JointInstance") then link.Object.C0=a; link.Object.C1=b
            elseif link.Object:IsA("RigidConstraint") or link.Object:IsA("AnimationConstraint") then link.Object.Attachment0.CFrame=a; link.Object.Attachment1.CFrame=b
            else error("Body joint cannot be adjusted.",0) end
        end
    end
    -- Roblox's own copies of the skin's catalog items (built from its description) are kept aside, and an item the skin
    -- names is rebuilt from that copy instead of from scratch. Only Roblox can load a SurfaceAppearance (the textures of
    -- most new hair and hats) or fit layered clothing; the ones a script made showed nothing, so a saved skin came back
    -- bald and without its hat. The saved place, size and look still apply on top.
    local spares={}
    for _,item in ipairs(model:GetChildren()) do
        if item:IsA("Accessory") then
            local handle=item:FindFirstChild("Handle")
            if handle and handle:IsA("BasePart") then item.Parent=nil; table.insert(spares,item) else item:Destroy() end
        elseif item:IsA("Shirt") or item:IsA("Pants") or item:IsA("ShirtGraphic") or item:IsA("BodyColors") then item:Destroy() end
    end
    local meshOf=Visual.meshOf
    local function savedMesh(row)
        if row.Class=="MeshPart" then return tostring(row.MeshId or "") end
        for _,node in ipairs(row.Nodes or {}) do
            if node.Class=="SpecialMesh" and type(node.Properties)=="table" then return tostring(node.Properties.MeshId or "") end
        end
        return ""
    end
    local function spare(row)
        local wanted=tonumber(row.AssetId)
        local mesh=Mirror.assetKey(savedMesh(row.Handle))
        for index,item in ipairs(spares) do
            local handle=item:FindFirstChild("Handle")
            local same
            -- Skins saved before items kept their id are matched by name and mesh.
            if wanted then same=tonumber(item:GetAttribute("Lyra_AssetId"))==wanted
            else same=mesh~="" and item.Name==row.Name and Mirror.assetKey(meshOf(handle))==mesh end
            if same and handle.ClassName==row.Handle.Class then table.remove(spares,index); return item end
        end
        return nil
    end
    for name,id in pairs(v.Clothes or {}) do
        local item=Instance.new(name=="Graphic" and "ShirtGraphic" or name)
        item[name=="Graphic" and "Graphic" or name.."Template"]=id; item.Parent=model
    end
    if next(v.Colors or {}) then
        local colors=Instance.new("BodyColors")
        for name,color in pairs(v.Colors) do colors[name.."Color3"]=Visual.unpack(color,"Color3") end
        colors.Parent=model
    end
    for name,row in pairs(v.Body) do model:FindFirstChild(name).Color=Visual.unpack(row.Color,"Color3") end
    local skipped,scratch={},{}
    for _,row in ipairs(v.Accessories) do
        local accessory,handle=spare(row),nil
        if accessory then
            accessory.Name=row.Name; accessory.Parent=model; handle=accessory:FindFirstChild("Handle")
        elseif not row.Multi then
            scratch[row.Name]=true
            accessory=Instance.new("Accessory"); accessory.Name=row.Name; accessory.Parent=model
            handle=Instance.new(row.Handle.Class); handle.Name="Handle"; handle.Parent=accessory
        end
        if accessory then
            if row.Type then pcall(function() accessory.AccessoryType=Enum.AccessoryType[row.Type] end) end
            if row.AttachmentPoint then accessory.AttachmentPoint=Visual.unpack(row.AttachmentPoint,"CFrame") end
            if row.Mount then
                accessory:SetAttribute("Lyra_MountBody",row.Mount.Body); accessory:SetAttribute("Lyra_MountOffset",Visual.unpack(row.Mount.Offset,"CFrame"))
            end
            Visual.applyPart(handle,row.Handle,false)
            -- One item that has no place on this rig (a game's own pet or weapon saved before mounts were recorded)
            -- is left out; the rest of the skin still applies.
            local attached,err=Appearance.attach(model,accessory)
            if not attached then table.insert(skipped,row.Name); warn("[Lyra Skin] Left out "..row.Name..": "..tostring(err)) end
        else
            -- An item made of several parts whose catalog copy is not in this skin's description.
            table.insert(skipped,row.Name)
        end
    end
    -- An item of the skin's description that no saved row names was worn when the skin was saved but could not be
    -- matched to its catalog copy (a Catalog Creator game put it on, so it carried no id). It stays, as Roblox built it,
    -- unless a row of the same name was already rebuilt from scratch. Dropping it took the hat off the skin's pictures.
    for _,item in ipairs(spares) do
        local kept=false
        if not scratch[item.Name] then
            item.Parent=model
            local ok,attached=pcall(Appearance.attach,model,item)
            kept=ok and attached
        end
        if not kept then pcall(function() item:Destroy() end) end
    end
    for name,value in pairs(v.Scales or {}) do
        local scale=hum:FindFirstChild(name) or Instance.new("NumberValue"); scale.Name=name; scale.Value=value; scale.Parent=hum
    end
    -- A saved HipHeight is the one the game the skin was saved in had: a game that raised it made the skin float in
    -- every other game (until a Customize size change rebuilt it). An R15 skin stands on its own legs: the height is
    -- measured from its body in the rest pose (its lowest point, as for an avatar drawn with visual-only), and the saved
    -- value is kept only when it agrees.
    local measured
    if v.RigType=="R15" then
        pcall(function()
            Rig.reachable(model,true)
            local root=model:FindFirstChild("HumanoidRootPart"); local lowest
            for _,part in ipairs(model:GetChildren()) do
                if part~=root and Appearance.isBody(part,model) then
                    local cf,half=part.CFrame,part.Size/2
                    for _,x in ipairs({-1,1}) do for _,y in ipairs({-1,1}) do for _,z in ipairs({-1,1}) do
                        local point=cf*Vector3.new(half.X*x,half.Y*y,half.Z*z)
                        if not lowest or point.Y<lowest then lowest=point.Y end
                    end end end
                end
            end
            if root and lowest then measured=math.max(0,root.Position.Y-root.Size.Y/2-lowest) end
        end)
--YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
    end
    if measured and (not v.HipHeight or math.abs(v.HipHeight-measured)>0.3) then hum.HipHeight=measured
    elseif v.HipHeight then hum.HipHeight=v.HipHeight end
    return model,skipped
end
-- Returns the model, a note for the player (or nil) and whether a saved snapshot had to be dropped for this rig.
function Visual.model(data,desc,rig,rebuild)
    local visual,note,rebuilt=data.Visual,nil,false
    if visual and visual.RigType~=rig.Name then
        -- A snapshot is rig-specific (joint by joint). On another rig it is rebuilt from its avatar description instead.
        note="This skin was saved on "..visual.RigType.." but your character is "..rig.Name.."; it was rebuilt from its avatar description, so custom details may differ."
        visual=nil; rebuilt=true
    elseif visual and rebuild then
        -- The game sizes bodies its own way (see GAME SCALE VALUES): the skin is rebuilt from its items at that size.
        visual=nil; rebuilt=true
    end
    local model=API.model(desc,rig)
    -- A skin is a whole look on any rig: the avatar items on your character come off under it (see Appearance.apply),
    -- also when it had to be rebuilt for this rig. An R15 skin worn on an R6 body kept your own hair on: only items
    -- recognised by name came off, and a hair the game put on (or one fetched under another name) stayed.
    if data.Visual then model:SetAttribute("Lyra_VisualSnapshot",true) end
    if visual then
        local ok,err,skipped=pcall(Visual.overlay,model,visual)
        if not ok then model:Destroy(); error(err,0) end
        if skipped and #skipped>0 then
            note=(note and (note.." ") or "")..tostring(#skipped)..(#skipped==1 and " item" or " items").." from this skin had no place on this rig and were left out: "
                ..table.concat(skipped,", ",1,math.min(#skipped,4))..(#skipped>4 and "…" or "")
        end
    end
    Tweaks.applyAll(model,data.Tweaks)
    return model,note,rebuilt
end

-- BODY EFFECTS: fire, particles, lights and trails that belong to the avatar's body (a flaming head, an aura on
-- the torso). Copies are tagged, so the next avatar removes only what an earlier one added, never the game's own.
-- Defined after Visual because they use its list of effect classes.
function Appearance.clearEffects(character)
    for _,part in ipairs(character:GetChildren()) do
        if Appearance.isBody(part,character) then
            for _,item in ipairs(part:GetDescendants()) do
                if item:GetAttribute("Lyra_BodyEffect") then pcall(function() item:Destroy() end) end
            end
        end
    end
end
function Appearance.copyEffects(character,sourceModel,copied)
    for name in pairs(copied) do
        local source,target=sourceModel:FindFirstChild(name),character:FindFirstChild(name)
        if source and target then
            local function place(from,to)
                for _,child in ipairs(from:GetChildren()) do
                    if Visual.effects[child.ClassName] then
                        local existing=to:FindFirstChild(child.Name)
                        -- The same effect is already there and not ours (your own avatar's, being restored): no duplicate.
                        if not (existing and existing.ClassName==child.ClassName and not existing:GetAttribute("Lyra_BodyEffect")) then
                            local ok,clone=pcall(function() return child:Clone() end)
                            if ok and clone then
                                clone:SetAttribute("Lyra_BodyEffect",true)
                                -- Trails and beams point at attachments of the source model; point them at the live ones.
                                for _,field in ipairs({"Attachment0","Attachment1"}) do
                                    pcall(function()
                                        local ref=child[field]
                                        if ref then
                                            local mapped=(ref.Parent==from and to or target):FindFirstChild(ref.Name)
                                            clone[field]=(mapped and mapped:IsA("Attachment")) and mapped or nil
                                        end
                                    end)
                                end
                                clone.Parent=to
                            end
                        end
                    elseif from==source and child:IsA("Attachment") and not child:IsA("Bone") then
                        local holder=target:FindFirstChild(child.Name)
                        if holder and holder:IsA("Attachment") then place(child,holder) end
                    end
                end
            end
            place(source,target)
        end
    end
end
-- Effects of your own avatar's body pause while an avatar without them is worn, and come back with your avatar.
-- Effects the game added are never touched.
function Appearance.pauseOwnEffects(character,sourceModel,copied)
    local own=S.ownEffectNames or {}
    for name in pairs(copied) do
        local source,target=sourceModel:FindFirstChild(name),character:FindFirstChild(name)
        if source and target then
            for _,item in ipairs(target:GetDescendants()) do
                if Visual.effects[item.ClassName] and not item:GetAttribute("Lyra_BodyEffect") then
                    local paused=item:GetAttribute("Lyra_PausedEffect")
                    if paused~=nil or own[name.."/"..item.Name.."/"..item.ClassName] then
                        local keep=false
                        for _,other in ipairs(source:GetDescendants()) do
                            if other.Name==item.Name and other.ClassName==item.ClassName then keep=true; break end
                        end
                        pcall(function()
                            if paused==nil then paused=item.Enabled; item:SetAttribute("Lyra_PausedEffect",paused) end
                            if keep then item.Enabled=paused; item:SetAttribute("Lyra_PausedEffect",nil) else item.Enabled=false end
                        end)
                    end
                end
            end
        end
    end
end

local Store = {File = "Copier_SavedProfiles.json", Favorites = {}, Recent = {}, Looks = {}, ShopFavorites = {}, EmoteSets = {}, LoadIssue = nil, Generation = 0,
    -- Item adjustments of your own avatar ("self") and of Roblox profiles you copy ("user:<id>"); a saved skin keeps
    -- its own in its data (see Tweaks.owner).
    ItemTweaks = {}}
Store.Settings = {AutoReset = false, CopyAnims = Config.CopyAnimation, AutoReapply = true, MapPersist = true,
    GlassBlur = true, MobileOrb = true, ReducedMotion = false, LowEffects = false, Keybind = "RightControl", HideOriginal = true,
    SwapEffect = true, Notifications = true, StartHidden = false, MenuReopen = true, HideTipSeen = false, MenuAvatar = true, SkinRequests = true, VisualOnly = false, VisualOnlyReset = false, UIScale = 85, ScaleMigrated = false, WindowW = 0, WindowH = 0,
    CopyDiscord = true, LoadingScreen = true, AutoRunTeleport = false, GameChange = "Yield", VisualRig = "Auto", StandIns = true, GameWear = true,
    KeepGameClothes = true, KeepGameItems = true,
    Theme = "Lavender", ThemeDecor = true, CastTipSeen = false, Font = "Builder Sans", TextSize = 100, Language = "auto", CommunityDiscord = "",
    NameMode = "Off", Badge = "Off", CustomName = "", CustomDisplay = "", HomeGuide = true, WelcomeSeen = false, SeenNews = ""}
-- Numeric settings: 0 means automatic. Window sizes are in unscaled pixels.
Store.SettingRanges = {UIScale = {70, 130}, WindowW = {300, 4000}, WindowH = {240, 4000}, TextSize = {80, 130}}
-- Named settings and their allowed values (the first one is the default).
--   GameChange: what happens when the game changes your avatar while a copied one is on (see Repair.watchGame).
--   VisualRig: the rig a visual-only avatar is drawn as.
--   Theme and Font: the look of the window (see THEMES).
--   NameMode and Badge: the name and verified badge Roblox's menus show for you on your screen (see YOUR NAME).
Store.SettingOptions = {GameChange = {"Yield", "Keep", "Ignore"}, VisualRig = {"Auto", "R15", "R6"},
    NameMode = {"Off", "Copied", "Custom"}, Badge = {"Off", "Copied", "On"},
    Theme = {"Lavender", "Midnight", "Rose", "Mint", "Ember", "Halloween", "Christmas", "Re:Zero", "Code Geass", "Attack on Titan", "Demon Slayer", "Bleach", "Tensura", "Franxx"},
    Font = {"Builder Sans", "Gotham", "Nunito", "Ubuntu", "Fredoka One", "Patrick Hand"},
    Language = {"auto", "en", "pt", "es", "ru", "id", "vi"}}
-- Auto-load on execute and the avatar cycle. An entry is a Roblox profile ({Kind="User"}) or a saved skin ({Kind="Look"}).
Store.Auto = {LoadEnabled = false, LoadSource = "Chosen", LoadDelay = 2, Chosen = nil, Last = nil, Games = {},
    CycleEnabled = false, Trigger = "Death", EveryDeaths = 1, TimerSeconds = 120, Order = "Sequential", Cooldown = 3,
    EndAction = "Loop", Resume = true, Notify = true, Index = 0, List = {}}
Store.AutoOptions = {LoadSource = {"Chosen", "Last", "Random", "Cycle"}, Trigger = {"Death", "Respawn", "Timer", "Both"},
    Order = {"Sequential", "Shuffle", "Random", "PingPong"}, EndAction = {"Loop", "Stop", "Restore"}}
-- Discord invite pacing: runs of this version and how many invites were shown (at most two, ever).
Store.Promo = {Runs = 0, Shown = 0, FirstAt = 0}
Store.AutoRanges = {LoadDelay = {0, 30}, EveryDeaths = {1, 50}, TimerSeconds = {10, 3600}, Cooldown = {0, 300}, Index = {0, 50}}
function Store.entry(row)
    if type(row) ~= "table" then return nil end
    if row.Kind == "Look" then
        local key = type(row.Key) == "string" and row.Key:sub(1, 80) or ""
        if key == "" then return nil end
        return {Kind = "Look", Key = key, Name = type(row.Name) == "string" and row.Name:sub(1, 48) or "Saved skin"}
    end
    local id = Codec.id(row.Id)
    local name = type(row.Name) == "string" and row.Name:sub(1, 64) or ""
    if not id and not name:match("^[%w_]+$") then return nil end
    if name == "" then name = tostring(id) end
    return {Kind = "User", Id = id, Name = name, DisplayName = type(row.DisplayName) == "string" and row.DisplayName:sub(1, 80) or name}
end
function Store.loadAuto(saved)
    if type(saved) ~= "table" then return end
    local auto = Store.Auto
    for _, key in ipairs({"LoadEnabled", "CycleEnabled", "Resume", "Notify"}) do
        if type(saved[key]) == "boolean" then auto[key] = saved[key] end
    end
    for key, range in pairs(Store.AutoRanges) do
        if type(saved[key]) == "number" and saved[key] == saved[key] then auto[key] = math.clamp(math.floor(saved[key]), range[1], range[2]) end
    end
    for key, options in pairs(Store.AutoOptions) do
        if table.find(options, saved[key]) then auto[key] = saved[key] end
    end
    auto.Chosen = Store.entry(saved.Chosen); auto.Last = Store.entry(saved.Last)
    if type(saved.Games) == "table" then
        local count = 0
        for place, row in pairs(saved.Games) do
            local entry = Store.entry(row)
            if count < 100 and type(place) == "string" and place:match("^%d+$") and entry then auto.Games[place] = entry; count = count + 1 end
        end
    end
    if type(saved.List) == "table" then
        for _, row in ipairs(saved.List) do
            local entry = Store.entry(row)
            if #auto.List >= 50 then break end
            if entry then table.insert(auto.List, entry) end
        end
    end
    if auto.Index > #auto.List then auto.Index = 0 end
end
function Store.read(file)
    if type(readfile) ~= "function" then return nil, "Storage unavailable. Data will remain in this session." end
    local knownExists = false
    if type(isfile) == "function" then local ok, exists = pcall(isfile, file); if ok and not exists then return nil end; knownExists = ok and exists end
    local ok, raw = pcall(readfile, file)
    if not ok then return nil, knownExists and "The saved file could not be opened." or nil end
    if type(raw) ~= "string" or #raw > 16000000 then return nil, "The saved file is invalid or too large." end
    local decoded, data = pcall(function() return HttpService:JSONDecode(raw) end)
    if not decoded or type(data) ~= "table" then return nil, "The saved file could not be read." end
    return data
end
function Store.write(file, data, noBackup)
    if type(writefile) ~= "function" then return false, "File access unavailable. Changes will remain in this session." end
    local ok, result = pcall(function() return HttpService:JSONEncode(data) end)
    if not ok then return false, "The data could not be prepared." end
    return Store.writeText(file, result, noBackup)
end
-- Writes JSON text that is already encoded (see Store.write).
function Store.writeText(file, result, noBackup)
    if type(writefile) ~= "function" then return false, "File access unavailable. Changes will remain in this session." end
    if #result > 16000000 then return false, "Storage is full (16 MB). Remove some skins to save again." end
    -- Saving a large file can freeze a phone for a moment, so nothing is written when nothing changed.
    Store.Written = Store.Written or {}
    if Store.Written[file] == result then return true end
    -- Retain the previous JSON before overwriting. A cheap shape check (a full parse is slow on large files)
    -- skips a file that an interrupted write left cut short. No deletion API is required. Once per run: the file as it
    -- was when the script started is the recovery copy, so later saves write the big file once instead of three times
    -- (read, copy, write), which froze phones for a moment after every change.
    Store.BackedUp = Store.BackedUp or {}
    if not noBackup and not Store.BackedUp[file] and type(readfile) == "function" then
        Store.BackedUp[file] = true
        local oldOK, old = pcall(readfile, file)
        if oldOK and type(old) == "string" and #old <= 16000000 and old:match("^%s*{") and old:match("}%s*$") then
            pcall(writefile, file .. ".bak", old)
        end
    end
    local written = pcall(writefile, file, result)
    if written then Store.Written[file] = result end
    return written, written and nil or "Saving failed. Your data remains available in this session."
end
-- A username typed for YOUR NAME: letters, digits and underscores, 20 at most (Roblox's own rule).
function Ident.cleanName(text)
    return (tostring(text or ""):gsub("[^%w_]", ""):sub(1, 20))
end
-- A display name typed for YOUR NAME: one line of at most 30 characters, without rich text tags or the badge sign.
function Ident.cleanDisplay(text)
    local clean = tostring(text or ""):gsub("[%c<>]", ""):gsub("\238\128\128", ""):gsub("^%s+", ""):gsub("%s+$", "")
    if not utf8.len(clean) then return "" end
    local cut = utf8.offset(clean, 31)
    if cut then clean = clean:sub(1, cut - 1) end
    return clean
end
function Store.normalize(list, limit)
    local rows, seen = {}, {}
    if type(list) ~= "table" then return rows end
    for _, row in ipairs(list) do
        if #rows >= limit then break end
        if type(row) == "table" then
            local id = Codec.id(row.Id)
            local name = type(row.Name) == "string" and row.Name:sub(1, 64) or ""
            local key = id and tostring(id) or name:lower()
            if not seen[key] and (id or name:match("^[%w_]+$")) then
                seen[key] = true
                table.insert(rows, {Id = id, Name = name ~= "" and name or tostring(id),
                    DisplayName = type(row.DisplayName) == "string" and row.DisplayName:sub(1, 80) or name})
            end
        end
    end
    return rows
end
-- Roblox Shop favorites: catalog items and bundles starred in the shop.
function Store.shopFavorites(list)
    local rows, seen = {}, {}
    if type(list) ~= "table" then return rows end
    for _, row in ipairs(list) do
        if #rows >= 300 then break end
        local id = type(row) == "table" and Codec.id(row.Id)
        local key = id and ((row.Bundle == true and "b" or "a") .. tostring(id))
        if key and not seen[key] then
            seen[key] = true
            table.insert(rows, {Id = id, Name = type(row.Name) == "string" and row.Name:sub(1, 80) or ("Item " .. tostring(id)), Bundle = row.Bundle == true,
                BundleKind = type(row.BundleKind) == "string" and row.BundleKind:sub(1, 40) or nil, Kind = type(row.Kind) == "string" and row.Kind:sub(1, 40) or nil})
        end
    end
    return rows
end
-- Saved emote sets: a name and up to 8 emotes with their wheel slots (see EMOTE SETS).
function Store.emoteSets(list)
    local rows, seen = {}, {}
    if type(list) ~= "table" then return rows end
    for _, row in ipairs(list) do
        if #rows >= 20 then break end
        if type(row) == "table" and type(row.Key) == "string" and #row.Key <= 60 and not seen[row.Key] and type(row.Name) == "string" then
            local emotes = {}
            for name, ids in pairs(type(row.Emotes) == "table" and row.Emotes or {}) do
                if type(name) == "string" and #name <= 100 and type(ids) == "table" then
                    local valid = {}
                    for i, id in ipairs(ids) do if i <= 20 and Codec.id(id) then table.insert(valid, id) end end
                    if #valid > 0 then emotes[name] = valid end
                end
            end
            local list2, equipped = Codec.emoteSet(emotes, row.Equipped)
            if #equipped > 0 then
                seen[row.Key] = true
                table.insert(rows, {Key = row.Key, Name = Codec.cut(row.Name, 30), Emotes = list2, Equipped = equipped,
                    Updated = Codec.number(row.Updated, 0, 9007199254740991) and row.Updated or os.time()})
            end
        end
    end
    return rows
end
function Store.load()
    local data, err = Store.read(Store.File)
    if err then
        local backup = Store.read(Store.File .. ".bak")
        if backup then data = backup; err = "A recovery copy of your data was loaded." end
    end
    Store.LoadIssue = err
    if not data then return end
    if data.Version ~= nil and (type(data.Version) ~= "number" or data.Version > 4) then Store.LoadIssue = "Unsupported data format. Saving was disabled to protect the file."; Store.ReadOnly = true; return end
    Store.Favorites = Store.normalize(data.Favorites or data.SavedUsers, 200)
    Store.Recent = Store.normalize(data.Recent, 30)
    if type(data.Looks) == "table" then
        local seen = {}
        for _, row in ipairs(data.Looks) do
            if #Store.Looks >= 100 then break end
            if type(row) == "table" and type(row.Name) == "string" and type(row.Data) == "table" then
                local name = row.Name:match("^%s*(.-)%s*$"):sub(1, 48)
                local id = type(row.Key) == "string" and row.Key:sub(1, 80) or ""
                if name ~= "" and id ~= "" and not seen[id] then
                    -- Only the shape is checked here: building a description for every skin made starting the script
                    -- slow with a full library. Each skin's description is checked when it is used (and fails safely).
                    local valid = pcall(function()
                        if row.Data.Visual then Visual.validate(row.Data.Visual) end
                        assert(row.Data.Version == nil or row.Data.Version == 2, "Unsupported avatar version.")
                        local props = row.Data.Version == 2 and row.Data.Properties or row.Data
                        assert(type(props) == "table" and next(props) ~= nil, "Saved avatar data is incomplete.")
                    end)
                    if valid then
                        seen[id] = true
                        row.Data.Tweaks = Tweaks.clean(row.Data.Tweaks)
                        if name == "Novo visual" then name = "New skin" end
                        local source = type(row.Source) == "string" and row.Source:sub(1, 80) or "Imported"
                        source = source:gsub("^Meu personagem", "My character"):gsub("^Importado", "Imported"):gsub("^Código compartilhado", "Shared code")
                        table.insert(Store.Looks, {Key = id, Name = name, Data = row.Data, FromUser = Codec.id(row.FromUser),
                            Source = source,
                            Updated = Codec.number(row.Updated, 0, 9007199254740991) and row.Updated or os.time()})
                    end
                end
            end
        end
    end
    if type(data.Settings) == "table" then
        for key, value in pairs(Store.Settings) do
            local saved = data.Settings[key]
            if type(value) == "boolean" and type(saved) == "boolean" then Store.Settings[key] = saved end
        end
        if type(data.Settings.Keybind) == "string" then
            local ok, key = pcall(function() return Enum.KeyCode[data.Settings.Keybind] end)
            if ok and key and key ~= Enum.KeyCode.Unknown then Store.Settings.Keybind = key.Name end
        end
        for key, options in pairs(Store.SettingOptions) do
            if table.find(options, data.Settings[key]) then Store.Settings[key] = data.Settings[key] end
        end
        -- The Discord username last put on a Community post.
        if type(data.Settings.CommunityDiscord) == "string" then Store.Settings.CommunityDiscord = data.Settings.CommunityDiscord:gsub("[^%w_%.#]", ""):sub(1, 37) end
        -- The name typed for YOUR NAME (Custom).
        if type(data.Settings.CustomName) == "string" then Store.Settings.CustomName = Ident.cleanName(data.Settings.CustomName) end
        if type(data.Settings.CustomDisplay) == "string" then Store.Settings.CustomDisplay = Ident.cleanDisplay(data.Settings.CustomDisplay) end
        -- What's new entries already opened on Home (keys separated by commas).
        if type(data.Settings.SeenNews) == "string" then Store.Settings.SeenNews = data.Settings.SeenNews:gsub("[^%w,]", ""):sub(1, 400) end
        -- The emote set on the wheel (see EMOTE SETS).
        if type(data.Settings.EmoteSet) == "string" and #data.Settings.EmoteSet <= 60 then Store.Settings.EmoteSet = data.Settings.EmoteSet end
        for key, range in pairs(Store.SettingRanges) do
            local saved = data.Settings[key]
            if type(saved) == "number" and saved == saved then
                Store.Settings[key] = saved <= 0 and 0 or math.clamp(math.floor(saved), range[1], range[2])
            end
        end
    end
    pcall(Store.loadAuto, data.Auto)
    if type(data.ItemTweaks) == "table" then
        local count = 0
        for owner, list in pairs(data.ItemTweaks) do
            if count >= 200 then break end
            if type(owner) == "string" and (owner == "self" or owner:match("^user:%d+$")) and #owner <= 40 then
                local clean = Tweaks.clean(list)
                if clean then Store.ItemTweaks[owner] = clean; count = count + 1 end
            end
        end
    end
    Store.ShopFavorites = Store.shopFavorites(data.ShopFavorites)
    Store.EmoteSets = Store.emoteSets(data.EmoteSets)
    if type(data.Promo) == "table" then
        for key, range in pairs({Runs = 1000, Shown = 2, FirstAt = 1000}) do
            local saved = data.Promo[key]
--[==[YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU]==]
            if type(saved) == "number" and saved == saved then Store.Promo[key] = math.clamp(math.floor(saved), 0, range) end
        end
    end
    Store.MainStamp = type(data.Saved) == "number" and data.Saved == data.Saved and data.Saved or nil
    pcall(Store.loadState)
end
function Store.sync()
    Config.CopyAnimation = Store.Settings.CopyAnims
    Config.AutoReapply = Store.Settings.AutoReapply
    Config.MapPersist = Store.Settings.MapPersist
end
function Store.save()
    Store.sync()
    if Store.ReadOnly then return false, Store.LoadIssue end
    local encoded, body = pcall(function()
        return HttpService:JSONEncode({Version = 4, Favorites = Store.Favorites, Recent = Store.Recent, Looks = Store.Looks, Settings = Store.Settings, Auto = Store.Auto, Promo = Store.Promo, ShopFavorites = Store.ShopFavorites, EmoteSets = Store.EmoteSets,
            ItemTweaks = Store.ItemTweaks})
    end)
    if not encoded or type(body) ~= "string" or body:sub(1, 1) ~= "{" then return false, "The data could not be prepared." end
    -- Nothing changed since the last save: nothing is written.
    if Store.SavedBody == body then return true end
    -- Saved: when this file was written, so the small state file (see Store.saveState) is only used when it is newer.
    local stamp = os.time()
    local ok, err = Store.writeText(Store.File, '{"Saved":' .. string.format("%d", stamp) .. "," .. body:sub(2))
    -- Only the text without the stamp is kept to compare with (one copy of a big file in memory, not two).
    if Store.Written then Store.Written[Store.File] = nil end
    if ok then Store.MainStamp = stamp; Store.SavedBody = body end
    return ok, err
end
-- SMALL SAVES: the last avatar worn, the avatar cycle's position and the Recent list change on almost every apply and
-- respawn. Writing them used to rewrite the whole save file (every saved skin, often megabytes), which froze phones for
-- a moment each time. They now go to a small file of their own, read after the main file when it is newer.
Store.StateFile = "Copier_SavedState.json"
function Store.saveState()
    if Store.ReadOnly then return false, Store.LoadIssue end
    -- A main file from an older version has no stamp to compare with: one full save first.
    if not Store.MainStamp then return Store.save() end
    return Store.write(Store.StateFile, {Version = 1, Saved = os.time(), Last = Store.Auto.Last, Index = Store.Auto.Index, Recent = Store.Recent}, true)
end
function Store.loadState()
    if not Store.MainStamp then return end
    local state = Store.read(Store.StateFile)
    if type(state) ~= "table" or state.Version ~= 1 or type(state.Saved) ~= "number" or state.Saved < Store.MainStamp then return end
    if state.Last ~= nil then Store.Auto.Last = Store.entry(state.Last) end
    if type(state.Index) == "number" and state.Index == state.Index then Store.Auto.Index = math.clamp(math.floor(state.Index), 0, 50) end
    if Store.Auto.Index > #Store.Auto.List then Store.Auto.Index = 0 end
    if type(state.Recent) == "table" then Store.Recent = Store.normalize(state.Recent, 30) end
end
Store.load()

-- LANGUAGE (Settings > Look): the window, its messages and pop-ups speak English, Português, Español, Русский, Bahasa
-- Indonesia or Tiếng Việt; Automatic follows the language of your Roblox. Texts are written in English in the code and
-- looked up when shown: a whole sentence, a sentence with a name or a number in it (a pattern), or the known pieces of a
-- longer message (fragments). Words players use in English anyway (script, skin, avatar, plugin, hub, FPS, Visual-only)
-- stay as they are; the rest is written the way a player of that language says it. A text with no translation shows in
-- English.
local Lang = {Code = "en", Exact = {}, Patterns = {}, Fragments = {}}
Lang.Codes = {"en", "pt", "es", "ru", "id", "vi"}
Lang.Names = {auto = "Automatic", en = "English", pt = "Português", es = "Español", ru = "Русский", id = "Bahasa Indonesia", vi = "Tiếng Việt"}
function Lang.detect()
    local ok, locale = pcall(function() return lp.LocaleId end)
    local code = (ok and type(locale) == "string" and locale or ""):lower():sub(1, 2)
    if code == "in" then code = "id" end
    return table.find(Lang.Codes, code) and code or "en"
end
function Lang.load(choice)
    local code = choice == "auto" and Lang.detect() or choice
    if not table.find(Lang.Codes, code) then code = "en" end
    Lang.Code = code
    Lang.Exact, Lang.Patterns, Lang.Fragments = {}, {}, {}
    if code == "en" or type(Lang.Data) ~= "string" then return end
    local column = table.find(Lang.Codes, code)
    for line in Lang.Data:gmatch("[^\n]+") do
        local cells = {}
        for cell in (line .. "\t"):gmatch("([^\t]*)\t") do table.insert(cells, (cell:gsub("\\n", "\n"))) end
        local english, text = cells[1], cells[column]
        if english and english ~= "" and text and text ~= "" then
            if english:sub(1, 1) == "~" then table.insert(Lang.Patterns, {english:sub(2), text})
            else
                Lang.Exact[english] = text
                if #english >= 8 and english:find(" ", 1, true) then table.insert(Lang.Fragments, {english, text}) end
            end
        end
    end
    table.sort(Lang.Fragments, function(a, b) return #a[1] > #b[1] end)
end
-- English text in, the chosen language's text out; a text with no translation comes back as it is.
function Lang.text(text)
    if Lang.Code == "en" or type(text) ~= "string" or text == "" then return text end
    local exact = Lang.Exact[text]
    if exact then return exact end
    for _, pattern in ipairs(Lang.Patterns) do
        local captures = {text:match(pattern[1])}
        if #captures > 0 then
            return (pattern[2]:gsub("%%(%d)", function(n) local part = captures[tonumber(n)]; return part and Lang.text(part) or "" end))
        end
    end
    -- Messages built from pieces have punctuation or are long; a plain name (an item, a player) is left alone quickly.
    if #text < 10 or not text:find(" ", 1, true) or (#text < 40 and not text:find("[%.:·…%(%)'\"!?;,]")) then return text end
    -- Known pieces of a longer message, longest first. Each piece becomes a token until the end, so a translated piece
    -- is never matched again.
    local pieces, out = {}, text
    for _, pair in ipairs(Lang.Fragments) do
        local at = #pair[1] <= #out and string.find(out, pair[1], 1, true)
        while at do
            table.insert(pieces, pair[2])
            local token = "\1" .. #pieces .. "\2"
            out = out:sub(1, at - 1) .. token .. out:sub(at + #pair[1])
            at = string.find(out, pair[1], at + #token, true)
        end
    end
    if #pieces == 0 then return text end
    return (out:gsub("\1(%d+)\2", function(n) return pieces[tonumber(n)] end))
end
-- A pop-up's texts in the chosen language.
function Lang.toast(spec)
    if Lang.Code == "en" or type(spec) ~= "table" then return spec end
    local copy = {}
    for key, value in pairs(spec) do copy[key] = value end
    copy.Title = Lang.text(spec.Title); copy.Text = Lang.text(spec.Text)
    if type(spec.Action) == "table" then
        copy.Action = {}
        for key, value in pairs(spec.Action) do copy.Action[key] = value end
        copy.Action.Text = Lang.text(spec.Action.Text)
    end
    return copy
end
-- 85% became the default size: a saved Auto (0) from before it was a choice becomes 85 once; picking Auto later sticks.
if not Store.Settings.ScaleMigrated then
    if Store.Settings.UIScale == 0 then Store.Settings.UIScale = 85 end
    Store.Settings.ScaleMigrated = true
end
-- Visual-only is off for everyone once (it drew some avatars stiff); from then on it stays as you set it. Games that draw
-- the character their own way suggest it (see CUSTOM CHARACTERS), and Evade always uses it (see Overlay.visualOnly).
if not Store.Settings.VisualOnlyReset then
    Store.Settings.VisualOnly = false
    Store.Settings.VisualOnlyReset = true
end
Store.sync()

local App = {Busy = false, QueryToken = 0, Preview = nil, Cache = {}, History = {}, Initial = nil, Current = nil, Closed = false}
App.Creator = {Name = "lyraEz", GitHub = "https://github.com/lyraEz", Discord = "https://discord.gg/8bxXcn2Vfb"}
App.Notify = function(message, kind) if kind == "error" then warn("[Lyra] " .. message) end end
App.Refresh = function() end
function App.alive() return IsAlive() and not App.Closed end
-- Some executors put the script's chunk name and line in front of every error ("RzHHx…:11778: …"): a message for
-- the player is shown without it.
function App.report(message, kind)
    if not App.alive() then return end
    App.Notify((tostring(message):gsub("^[%w_%.%-]+:%d+: ", "", 1)), kind or "info")
end
-- Pop-up notifications go through the hub's own Lyra Toast notifier (set once the window is built).
App.ToastSink = nil
function App.toast(spec) if App.alive() and App.ToastSink and Store.Settings.Notifications then pcall(App.ToastSink, Lang.toast(spec)) end end
-- Test builds (the owner's dev loader) explain what they did, to find a problem from a phone; public builds stay quiet.
-- DEV: CHARACTER LOG (see App.startLog). Lines are only kept while "/lyralog" is recording.
App.Log = {Lines = {}, Until = 0, Start = 0, Ids = setmetatable({}, {__mode = "k"}), Next = 0}
function App.tracing() return os.clock() < App.Log.Until end
function App.trace(text)
    local log = App.Log
    if os.clock() >= log.Until or #log.Lines >= 8000 then return end
    table.insert(log.Lines, string.format("%7.2f  %s", os.clock() - log.Start, tostring(text)))
    log.Dirty = true
end
-- An instance as the log names it: class, name and a number that stays with that instance for the whole log.
function App.traceName(item)
    if typeof(item) ~= "Instance" then return tostring(item) end
    local log = App.Log
    local id = log.Ids[item]
    if not id then log.Next = log.Next + 1; id = log.Next; log.Ids[item] = id end
    return string.format("%s \"%s\" #%d", item.ClassName, item.Name, id)
end
function App.devNote(text)
    App.trace("Note: " .. tostring(text))
    if type(rawget(_G, "LyraDevBuild")) ~= "string" then return end
    warn("[Lyra dev] " .. tostring(text))
    if App.alive() and App.ToastSink then pcall(App.ToastSink, {Title = "Dev", Text = tostring(text), Kind = "info", Duration = 9}) end
end
function App.persist()
    local ok, err = Store.save(); if not ok then App.report(err, "warning") end
    return ok
end
-- The last avatar, the cycle position and Recent only (see SMALL SAVES).
function App.persistState()
    local ok, err = Store.saveState(); if not ok then App.report(err, "warning") end
    return ok
end
-- The public loader runs before this script, so it reads the start-up settings ("Copy the Discord invite on start",
-- "Show the loading screen", "Run again after a teleport") from this small file instead of the saved data. It is
-- only written when the settings differ from what the file says.
App.LoaderFlag = "LyraAvatarStudio_loader.txt"
App.LoaderUrl = "https://api.lyraez.lol/loader"
function App.writeLoaderFlag()
    if type(writefile) ~= "function" then return end
    local settings = Store.Settings
    local wanted = table.concat({"copy_discord=" .. (settings.CopyDiscord and 1 or 0), "loading_ui=" .. (settings.LoadingScreen and 1 or 0),
        "auto_teleport=" .. (settings.AutoRunTeleport and 1 or 0)}, "\n")
    local current
    pcall(function() if type(isfile) == "function" and type(readfile) == "function" and isfile(App.LoaderFlag) then current = readfile(App.LoaderFlag) end end)
    -- Without a file every option is at its default, so nothing needs writing until one changes.
    local defaults = settings.CopyDiscord and settings.LoadingScreen and not settings.AutoRunTeleport
    if current ~= wanted and not (current == nil and defaults) then pcall(writefile, App.LoaderFlag, wanted) end
end
-- "Run again after a teleport": the executor runs a line in the next server that starts the loader. That line reads
-- the setting again there (so turning it off also cancels a queued run) and skips when the script already runs.
function App.teleportQueue()
    local queue = queue_on_teleport or queueonteleport or (syn and syn.queue_on_teleport) or (fluxus and fluxus.queue_on_teleport)
    return type(queue) == "function" and queue or nil
end
function App.queueTeleport()
    if not Store.Settings.AutoRunTeleport or _G.Copier_TeleportQueued then return end
    local queue = App.teleportQueue()
    if not queue then return end
    local code = "local skip=_G.Copier_ExecutionID~=nil;pcall(function() if isfile and readfile and isfile(\"" .. App.LoaderFlag .. "\") and string.find(readfile(\""
        .. App.LoaderFlag .. "\"),\"auto_teleport=0\",1,true) then skip=true end end);if not skip then loadstring(game:HttpGet(\"" .. App.LoaderUrl .. "\"))() end"
    if pcall(queue, code) then _G.Copier_TeleportQueued = true end
end
function App.favoriteIndex(profile)
    for i, row in ipairs(Store.Favorites) do
        if (profile.Id and row.Id == profile.Id) or row.Name:lower() == profile.Name:lower() then return i end
    end
end
function App.toggleFavorite(profile)
    if not profile then return end
    local i = App.favoriteIndex(profile)
    if i then table.remove(Store.Favorites, i) else
        if #Store.Favorites >= 200 then App.report("The 200-favorite limit has been reached.", "warning"); return end
        table.insert(Store.Favorites, 1, {Id = profile.Id, Name = profile.Name, DisplayName = profile.DisplayName})
    end
    App.Refresh(); App.persist()
end
function App.addRecent(profile)
    for i = #Store.Recent, 1, -1 do if Store.Recent[i].Id == profile.Id then table.remove(Store.Recent, i) end end
    table.insert(Store.Recent, 1, {Id = profile.Id, Name = profile.Name, DisplayName = profile.DisplayName})
    while #Store.Recent > 30 do table.remove(Store.Recent) end
    App.Refresh(); App.persistState()
end
function App.resolve(raw, valid)
    local text = tostring(raw):match("^%s*(.-)%s*$"):gsub("^@", "")
    local id = Codec.id(text)
    if not id and (not text:match("^[%w_]+$") or #text < 3 or #text > 20 or text:match("^%d+$")) then
        return nil, "Enter a valid username or numeric user ID."
    end
    local name, display
    if not id then
        for _, player in ipairs(Players:GetPlayers()) do if player.Name:lower() == text:lower() then id = player.UserId; name = player.Name; display = player.DisplayName; break end end
---- YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
        if not id then
            local ok, value = pcall(function() return Players:GetUserIdFromNameAsync(text) end)
            if not valid() then return nil, "cancelled" end
            if not ok or not Codec.id(value) then return nil, "User not found or the service is unavailable. Check the username." end
            id = value
        end
    end
    if not valid() then return nil, "cancelled" end
    local cached = App.Cache[id]
    if cached and os.clock() - cached.Time < 120 then return cached.Profile end
    if not name then
        local ok, value = pcall(function() return Players:GetNameFromUserIdAsync(id) end)
        if not valid() then return nil, "cancelled" end
        if not ok then return nil, "This user ID could not be retrieved. Try again." end
        name = value
    end
    local okInfo, info = pcall(function() return US:GetUserInfosByUserIdsAsync({id}) end)
    if not valid() then return nil, "cancelled" end
    display = (okInfo and info and info[1] and info[1].DisplayName) or display or name
    local ok, desc = pcall(API.description, id)
    if not valid() then if ok and desc then desc:Destroy() end; return nil, "cancelled" end
    if not ok then return nil, "The profile exists, but its avatar could not be loaded. Try again." end
    local profile = {Id = id, Name = name, DisplayName = display, Description = desc}
    if cached then cached.Profile.Description:Destroy() end
    App.Cache[id] = {Time = os.clock(), Profile = profile}
    local count, oldestId, oldest = 0, nil, math.huge
    for k, row in pairs(App.Cache) do count = count + 1; if row.Time < oldest and k ~= id and (not App.Preview or k ~= App.Preview.Id) then oldestId = k; oldest = row.Time end end
    if count > 20 and oldestId then App.Cache[oldestId].Profile.Description:Destroy(); App.Cache[oldestId] = nil end
    return profile
end
-- The game's description of your character: the one the server keeps on the Humanoid. It follows the outfit the game
-- gave you (a catalog game's look, a team uniform), unlike GetAppliedDescription, which can still be your profile.
-- A description the copier made (older versions replaced the game's one) is only used when there is no other.
function App.liveDescription(hum)
    if not hum then return nil end
    local tagged
    for _, item in ipairs(hum:GetChildren()) do
        if item:IsA("HumanoidDescription") then
            if not item:GetAttribute("Lyra_Description") then return item end
            tagged = tagged or item
        end
    end
    return tagged
end
-- The undo base ("Original"): your character as the game made it. It is taken again (force) right before the copier
-- first changes a character, so it is the look the game has on you at that moment, never an older one. Visual-only
-- never changes the character, so there it can also come from your profile, or be an empty placeholder.
App.InitialFor = setmetatable({}, {__mode = "k"})
function App.captureInitial(char, force)
    if App.Initial and not force then return true end
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local desc
    if hum then
        local live = App.liveDescription(hum)
        if live and not live:GetAttribute("Lyra_Description") then
            pcall(function()
                desc = live:Clone()
                desc:SetEmotes(live:GetEmotes()); desc:SetEquippedEmotes(live:GetEquippedEmotes())
            end)
        end
        if not desc then
            local ok, applied = pcall(function() return hum:GetAppliedDescription() end)
            if ok and applied then desc = applied end
        end
    end
    local visualOnly = Overlay.visualOnly()
    if not desc and visualOnly and not App.Initial then pcall(function() desc = API.description(lp.UserId) end) end
    local data
    if desc then
        local ok, encoded = pcall(Codec.encode, desc); pcall(function() desc:Destroy() end)
        if ok then data = encoded end
    end
    if not data then
        if not visualOnly or App.Initial then return App.Initial ~= nil and not force end
        -- Visual-only only needs to know that "Original" means: no overlay.
        App.Initial = {Name = "Initial appearance", Original = true, Animations = {}, Placeholder = true}
        if not App.Current then App.Current = App.Initial end
        return true
    end
    local snapshot = {Data = data, Name = "Initial appearance", Original = true, Animations = hum and App.captureAnimations(char) or {}}
    -- Your own avatar keeps the item adjustments you made on it (see SAVED ADJUSTMENTS).
    if Store.ItemTweaks.self then data.Tweaks = Codec.copy(Store.ItemTweaks.self) end
    if hum then
        local visualOK, visual = pcall(Visual.capture, char, snapshot.Animations)
        if visualOK then snapshot.Data.Visual = visual
        else warn("[Lyra Initial] Visual backup unavailable: " .. tostring(visual)) end
    end
    App.Initial = snapshot
    -- Each body keeps its own: a body the game swaps in for a while (see SWAPPED BODIES) is captured when the copied
    -- avatar goes on it, and yours is the undo base again when it comes back (Restore must not make you a giant).
    if char then App.InitialFor[char] = snapshot end
    -- Your own look, to recognise the copies of you a game builds (see STAND-INS).
    if hum and Mirror.learn then pcall(Mirror.learn, char) end
    -- While your own look is on, the fresh capture is what is worn now.
    if not App.Current or App.Current.Original then App.Current = snapshot end
    return true
end
-- SAVED ADJUSTMENTS: item adjustments (Customize: move, turn, resize or fade an item, for example a hat faded away so only
-- its fire shows) used to last only until you left the server, and the ones on your own avatar until the next respawn
-- or the next item you put on. They are now kept in the save file for your own avatar and for every Roblox profile you
-- copy, and come back on the next respawn, after a teleport, in the next server and when items are added or removed.
-- A saved skin already keeps them in its own data. Returns "self", "user:<id>" or nil.
function Tweaks.owner(snapshot)
    if type(snapshot) ~= "table" or snapshot.LookKey then return nil end
    if snapshot.Original or snapshot.SelfEdit then return "self" end
    local id = Codec.id(snapshot.Id) or (snapshot.Catalog and Codec.id(snapshot.ThumbId)) or nil
    return id and ("user:" .. tostring(id)) or nil
end
-- A snapshot about to be worn gets the adjustments kept for it (none when it already carries its own).
function Tweaks.attach(snapshot)
    if type(snapshot) ~= "table" or type(snapshot.Data) ~= "table" or snapshot.Data.Tweaks ~= nil then return end
    local owner = Tweaks.owner(snapshot)
    local saved = owner and Store.ItemTweaks[owner]
    if saved then snapshot.Data.Tweaks = Codec.copy(saved) end
end
-- Remembers the adjustments of the snapshot being worn (written with the next save).
function Tweaks.keep(snapshot)
    local owner = Tweaks.owner(snapshot)
    if not owner then return end
    local list = type(snapshot.Data) == "table" and Tweaks.clean(snapshot.Data.Tweaks) or nil
    Store.ItemTweaks[owner] = list and Codec.copy(list) or nil
end
-- Your own avatar is never rebuilt by the copier, so its adjustments are put on its items directly: after a respawn,
-- when the script starts, and when an item is added to your character.
function Tweaks.applySelf(char)
    local list = Store.ItemTweaks.self
    if not list or not char or char ~= lp.Character or (App.Current and not App.Current.Original) then return end
    for _, item in ipairs(char:GetChildren()) do
        if item:IsA("Accessory") and list[item.Name] and item:FindFirstChild("Handle")
            and not item:FindFirstChildWhichIsA("Script", true) and not item:FindFirstChildWhichIsA("LocalScript", true) then
            pcall(Tweaks.apply, char, item, list[item.Name])
        end
    end
end
function Tweaks.watchSelf(char)
    if Tweaks.SelfWatch then Tweaks.SelfWatch:Disconnect(); Tweaks.SelfWatch = nil end
    if not char then return end
    pcall(Tweaks.applySelf, char)
    local pending = false
    Tweaks.SelfWatch = RegisterConnection(char.ChildAdded:Connect(function(child)
        if pending or not child:IsA("Accessory") or not Store.ItemTweaks.self or not App.alive() then return end
        pending = true
        -- An item arrives in pieces: it is adjusted once it is complete.
        task.delay(0.3, function() pending = false; if App.alive() then pcall(Tweaks.applySelf, char) end end)
    end))
end
-- Running the script again while a copied avatar is on: the new run takes over the undo base, the timeline and the
-- kept-aside game items of the run it replaces, instead of mistaking the copied look for your own.
function App.adoptCarry()
    local carry = _G.Copier_Carry; _G.Copier_Carry = nil
    local char = lp.Character
    if type(carry) ~= "table" or not char or carry.Character ~= char or not char.Parent then return end
    if type(carry.Initial) ~= "table" or type(carry.Initial.Data) ~= "table" or type(carry.Current) ~= "table" then return end
    App.Initial = carry.Initial; App.Current = carry.Current
    App.History = type(carry.History) == "table" and carry.History or {}
    S.TouchedChar = char; S.appliedChar = char; S.fvOn = not App.Current.Original
    if type(carry.Stash) == "table" then Appearance.Stash[char] = carry.Stash end
    if type(carry.Parts) == "table" then
        Appearance.TouchedFor[char] = true
        for _, part in ipairs(carry.Parts) do if typeof(part) == "Instance" then Appearance.TouchedParts[part] = true end end
    end
end
function App.leaveCarry()
    local char = lp.Character
    _G.Copier_Carry = nil
    if not char or S.TouchedChar ~= char or not App.Initial or type(App.Initial.Data) ~= "table" or not App.Current then return end
    local parts = {}
    for _, part in ipairs(char:GetChildren()) do if Appearance.TouchedParts[part] then table.insert(parts, part) end end
    _G.Copier_Carry = {Character = char, Initial = App.Initial, Current = App.Current, History = App.History,
        Stash = Appearance.Stash[char], Parts = Appearance.TouchedFor[char] and parts or nil}
end
-- A character the game has finished loading: alive, with a root part.
function App.charReady(char)
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    return hum ~= nil and hum.Health > 0 and char:FindFirstChild("HumanoidRootPart") ~= nil and char.Parent ~= nil
end
-- Yields until every body part is joined to the root. A character the game is still building (or rebuilding, as
-- catalog games do on every try-on) is waited for instead of failing with a disconnected rig.
function App.waitRig(char, timeout)
    local deadline = os.clock() + (timeout or 6)
    while true do
        if #Appearance.rigMissing(char) == 0 then return true end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if os.clock() >= deadline or not App.alive() or char ~= lp.Character or not char.Parent or (hum and hum.Health <= 0) then return false end
        task.wait(0.1)
    end
end
-- Yields after a respawn until the character has settled: at least a second old, standing (or seated) and joined
-- up, as a game finishes placing and dressing it. Changing the body while the game still moves it could tip it over.
App.SpawnTimes = setmetatable({}, {__mode = "k"})
-- minAge: how old the character must be (a second by default). Putting the copied avatar back after a respawn waits
-- less, since the character is covered meanwhile (see COVER) and kept on its feet afterwards (App.guardUpright).
function App.waitSettled(char, limit, minAge)
    local born = App.SpawnTimes[char] or os.clock()
    minAge = minAge or 1
    local deadline = os.clock() + (limit or 6)
    local steady = {[Enum.HumanoidStateType.Running] = true, [Enum.HumanoidStateType.RunningNoPhysics] = true,
        [Enum.HumanoidStateType.Landed] = true, [Enum.HumanoidStateType.Seated] = true, [Enum.HumanoidStateType.Swimming] = true,
        [Enum.HumanoidStateType.Climbing] = true}
    while os.clock() < deadline and App.alive() and char.Parent and char == lp.Character do
        local hum = char:FindFirstChildOfClass("Humanoid")
        local root = char:FindFirstChild("HumanoidRootPart")
        local ok, state = pcall(function() return hum:GetState() end)
        local anchored = root and root:IsA("BasePart") and root.Anchored
        if os.clock() - born >= minAge and hum and hum.Health > 0 and ok and steady[state] and not anchored and #Appearance.rigMissing(char) == 0 then return true end
        task.wait(0.05)
    end
    return false
end
-- For a moment after the body changes, a character that was standing is kept from tipping over: if it falls over
-- without the game asking for it (no ragdoll, sit or platform stand already on), it is stood up again.
function App.guardUpright(char, seconds)
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not hum or not root or not root:IsA("BasePart") then return end
    local okState, state = pcall(function() return hum:GetState() end)
    local calm = {[Enum.HumanoidStateType.Running] = true, [Enum.HumanoidStateType.RunningNoPhysics] = true, [Enum.HumanoidStateType.Landed] = true,
        [Enum.HumanoidStateType.Freefall] = true, [Enum.HumanoidStateType.Jumping] = true}
    if not okState or not calm[state] or root.CFrame.UpVector.Y < 0.8 or hum.PlatformStand or hum.Sit then return end
    local fallen = {[Enum.HumanoidStateType.FallingDown] = true, [Enum.HumanoidStateType.Ragdoll] = true, [Enum.HumanoidStateType.Physics] = true}
    local deadline, fixes = os.clock() + (seconds or 2.5), 0
    task.spawn(function()
        while os.clock() < deadline and fixes < 4 and App.alive() and char.Parent and root.Parent == char and hum.Health > 0 do
            local ok, now = pcall(function() return hum:GetState() end)
            if ok and not hum.PlatformStand and not hum.Sit and now ~= Enum.HumanoidStateType.Seated and now ~= Enum.HumanoidStateType.Swimming
                and now ~= Enum.HumanoidStateType.Climbing and (fallen[now] or root.CFrame.UpVector.Y < 0.35) then
                fixes = fixes + 1
                pcall(function()
                    local look = root.CFrame.LookVector
                    local flat = Vector3.new(look.X, 0, look.Z)
                    if flat.Magnitude < 0.1 then flat = Vector3.new(0, 0, -1) end
                    root.AssemblyAngularVelocity = Vector3.zero
                    root.CFrame = CFrame.lookAt(root.Position, root.Position + flat.Unit)
                    hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                end)
            end
            RS.Heartbeat:Wait()
        end
    end)
end
-- COVER: after a respawn, a teleport or Auto-load, the game first builds your character with your own avatar, and it
-- showed until the copied one was put back on. Now your character is hidden on your screen from the moment it appears
-- until the copied avatar is on (at most a few seconds; it shows again whatever happens). Only LocalTransparencyModifier
-- is used, so nothing changes for the game or for other players, and held tools stay visible. The camera (zooming in,
-- first person) writes the same property: what it writes meanwhile is kept and put back when the cover comes off.
-- The cover writes the mask (see Cloak.Mask) instead of 1, so a value of 1 from the camera still shows as a change.
Cover.Items = {}
Cover.Mask = Cloak.Mask
function Cover.wanted() return Store.Settings.HideOriginal ~= false end
function Cover.add(item)
    if Cover.Items[item] ~= nil then return end
    if not (item:IsA("BasePart") or item:IsA("Decal") or item:IsA("Texture")) or item:FindFirstAncestorOfClass("Tool") then return end
    local ok, value = pcall(function() return item.LocalTransparencyModifier end)
    if not ok then return end
    Cover.Items[item] = isMask(value) and 0 or value
    pcall(function() item.LocalTransparencyModifier = Cover.Mask end)
end
-- Hides char until Cover.finish(char), or for seconds at most.
function Cover.begin(char, seconds)
    if not char or not Cover.wanted() or not App.alive() then return end
    if Cover.Char and Cover.Char ~= char then Cover.finish() end
    Cover.Until = os.clock() + (seconds or 10)
    if Cover.Char == char then return end
    Cover.Char = char
    for _, item in ipairs(char:GetDescendants()) do Cover.add(item) end
    Cover.Added = char.DescendantAdded:Connect(function(item) if Cover.Char == char then Cover.add(item) end end)
    -- Right after the camera's own update, so what is drawn this frame is always covered.
    pcall(function() RS:BindToRenderStep("LyraAvatarCover", Enum.RenderPriority.Camera.Value + 1, Cover.step) end)
end
function Cover.step()
    local char = Cover.Char
    if not char or not char.Parent or char ~= lp.Character or os.clock() > (Cover.Until or 0) or not App.alive() then Cover.finish(); return end
    for item in pairs(Cover.Items) do
        local ok, value = pcall(function() return item.LocalTransparencyModifier end)
        if ok and not isMask(value) then
            -- The camera (or the game) set its own value: kept for later, and covered again.
            Cover.Items[item] = value
            pcall(function() item.LocalTransparencyModifier = Cover.Mask end)
        end
    end
end
-- Shows the character again (only the one given, when given).
function Cover.finish(char)
    if char and Cover.Char ~= char then return end
    pcall(function() RS:UnbindFromRenderStep("LyraAvatarCover") end)
    if Cover.Added then Cover.Added:Disconnect(); Cover.Added = nil end
    for item, value in pairs(Cover.Items) do
        pcall(function() if isMask(item.LocalTransparencyModifier) then item.LocalTransparencyModifier = value end end)
    end
    table.clear(Cover.Items); Cover.Char = nil
end
-- Emotes live in the description the game put on the Humanoid. They are set on that same description (as Roblox's
-- own emote setup does): a replacement description showed the copied emotes in the wheel, but Roblox only played the
-- ones the original also had. The game's own emotes are kept per description and come back with your look.
-- EMOTE SETS (Roblox Shop > Emotes): the emotes of your wheel saved under a name, so a set of dances goes on in one
-- tap. The set in use stays on the wheel whatever avatar you wear (and on the next run), until you stop using it or
-- change an emote in the shop.
local EmoteSets = {Max = 20}
function EmoteSets.active()
    local key = Store.Settings.EmoteSet
    if type(key) ~= "string" then return nil end
    for _, set in ipairs(Store.EmoteSets) do if set.Key == key then return set end end
    return nil
end
function EmoteSets.live()
    local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
    return App.liveDescription(hum)
end
-- The emotes on your wheel right now: the list and the equipped slots.
function EmoteSets.wheel()
    local live = EmoteSets.live()
    if not live then return {}, {} end
    local ok, emotes, equipped = pcall(function() return live:GetEmotes(), live:GetEquippedEmotes() end)
    if not ok then return {}, {} end
    return Codec.emoteSet(emotes, equipped)
end
-- Saves the wheel as a set (only the emotes in its slots). Returns the set, or nil and why not.
function EmoteSets.save(name)
    local emotes, equipped = EmoteSets.wheel()
    if #equipped == 0 then return nil, "Your emote wheel is empty. Add emotes in Search (filter Emotes) first." end
    if #Store.EmoteSets >= EmoteSets.Max then return nil, "You can keep up to 20 emote sets. Delete one first." end
    local kept = {}
    for _, row in ipairs(equipped) do kept[row.Name] = emotes[row.Name] end
    name = Codec.cut(tostring(name or ""):match("^%s*(.-)%s*$"), 30)
    if name == "" then name = Lang.text("Set") .. " " .. tostring(#Store.EmoteSets + 1) end
    local set = {Key = HttpService:GenerateGUID(false), Name = name, Emotes = kept, Equipped = equipped, Updated = os.time()}
    table.insert(Store.EmoteSets, 1, set)
    App.persist()
    return set
end
-- Puts emotes on the live description: the set's in their slots (the rest of the list is kept), or without a set the
-- emotes of the avatar you wear.
function EmoteSets.apply()
    local live = EmoteSets.live()
    if not live then return false end
    local set = EmoteSets.active()
    if not set then
        local current = App.Current
        local data = current and not current.Original and type(current.Data) == "table" and current.Data or nil
        local desc = data and type(data.Emotes) == "table" and next(data.Emotes) ~= nil and select(2, pcall(Codec.decode, data)) or nil
        App.setEmotes(live, typeof(desc) == "Instance" and desc or nil, desc == nil)
        if typeof(desc) == "Instance" then desc:Destroy() end
        return true
    end
    App.setEmotes(live, nil, true)
    return true
end
function EmoteSets.use(set)
    Store.Settings.EmoteSet = set and set.Key or nil
    App.persist()
    return EmoteSets.apply()
end
function EmoteSets.remove(key)
    for i = #Store.EmoteSets, 1, -1 do if Store.EmoteSets[i].Key == key then table.remove(Store.EmoteSets, i) end end
    if Store.Settings.EmoteSet == key then Store.Settings.EmoteSet = nil; EmoteSets.apply() end
    App.persist()
end
App.EmoteBackup = setmetatable({}, {__mode = "k"})
function App.setEmotes(live, desc, original)
    local backup = App.EmoteBackup[live]
    if not backup then
        local ok, emotes, equipped = pcall(function() return live:GetEmotes(), live:GetEquippedEmotes() end)
        backup = {Emotes = ok and type(emotes) == "table" and emotes or {}, Equipped = ok and type(equipped) == "table" and equipped or {}}
        App.EmoteBackup[live] = backup
    end
    local emotes, equipped
    if not original and desc then
        local ok, e, q = pcall(function() return desc:GetEmotes(), desc:GetEquippedEmotes() end)
        -- A look without emotes (an old skin) keeps the emotes you have.
        if ok and type(e) == "table" and next(e) ~= nil then emotes, equipped = e, type(q) == "table" and q or {} end
    end
    if not emotes then emotes, equipped = backup.Emotes, backup.Equipped end
    -- An equipped slot whose emote is missing from the list would stay dead in the wheel.
    local list, valid = Codec.emoteSet(emotes, equipped)
    -- The emote set in use fills the wheel (its emotes join the list).
    local set = EmoteSets.active()
    if set then
        for name, ids in pairs(set.Emotes) do list[name] = ids end
        list, valid = Codec.emoteSet(list, set.Equipped)
    end
    pcall(function() live:SetEmotes(list); live:SetEquippedEmotes(valid) end)
end
-- Animation rows by the character they were read from (weak keys): rows read from this very character undo the
-- copier's own changes (see restoreAnimations).
App.AnimSource = setmetatable({}, {__mode = "k"})
App.AnimFields = {"ClimbAnimation", "FallAnimation", "IdleAnimation", "JumpAnimation", "RunAnimation", "SwimAnimation", "WalkAnimation", "MoodAnimation"}
-- Starts getting an avatar's animations ready while the rest of it is built (body and accessories take a moment),
-- so they play at once when they go into Animate (see F.preloadAnimations). Returns a handle; wait() yields until
-- they are ready, a few seconds at most.
function App.prefetchAnimations(char, snapshot, desc)
    local handle = {Done = false}
    local ids, packs = {}, {}
    local data = type(snapshot.Data) == "table" and snapshot.Data or {}
    -- Animations Animate already holds are not fetched: they are on the character now. A shop or Customize change keeps
    -- the animations being played, so it waits for nothing here.
    local have = {}
    local animate = char and char:FindFirstChild("Animate")
    for _, item in ipairs(animate and animate:GetDescendants() or {}) do
        if item:IsA("Animation") then have[F.normalizeAnimId(item.AnimationId)] = true end
    end
    for _, rows in ipairs({snapshot.Animations, type(data.Visual) == "table" and data.Visual.Animations or nil}) do
        if type(rows) == "table" then
            for _, row in ipairs(rows) do
                if type(row) == "table" and row.Id and not have[F.normalizeAnimId(row.Id)] then table.insert(ids, row.Id) end
            end
        end
    end
    if desc and (Store.Settings.CopyAnims or snapshot.ForceAnims) then
        for _, field in ipairs(App.AnimFields) do
            local ok, assetId = pcall(function() return desc[field] end)
            if ok and tonumber(assetId) and tonumber(assetId) ~= 0 then table.insert(packs, assetId) end
        end
    end
    task.spawn(function()
        if #packs > 0 then
            for _, id in ipairs(F.packAnimationIds(packs)) do if not have[F.normalizeAnimId(id)] then table.insert(ids, id) end end
        end
        pcall(F.preloadAnimations, char, ids, 4)
        handle.Done = true
    end)
    function handle.wait(timeout)
        local deadline = os.clock() + (timeout or 3)
        while not handle.Done and os.clock() < deadline and App.alive() do task.wait(0.05) end
    end
    return handle
end
-- Whether Roblox made an animation (its default and pack animations are Roblox's). Asked once per id.
App.RobloxAnims = {}
function App.robloxAnimation(id)
    local number = tonumber(tostring(id):match("(%d+)$"))
    if not number then return false end
    local known = App.RobloxAnims[number]
    if known ~= nil then return known end
    local ok, info = pcall(function() return MPS:GetProductInfo(number, Enum.InfoType.Asset) end)
    local creator = ok and type(info) == "table" and type(info.Creator) == "table" and info.Creator or nil
    local result = creator ~= nil and (creator.CreatorTargetId == 1 or creator.Id == 1 or creator.Name == "Roblox")
    App.RobloxAnims[number] = result
    return result
end
-- Your profile's animation fields, read once: the packs Roblox puts in Animate in games that keep avatar animations.
function App.profileAnimData()
    if App.ProfileAnimData == nil then
        App.ProfileAnimData = false
        pcall(function()
            local desc = API.description(lp.UserId)
            local data = {}
            for _, field in ipairs(App.AnimFields) do
                local ok, value = pcall(function() return desc[field] end)
                if ok then data[field] = value end
            end
            pcall(function() desc:Destroy() end)
            App.ProfileAnimData = data
        end)
    end
    return App.ProfileAnimData or nil
end
-- Animation ids that belong to avatars rather than to a game: Roblox's defaults, ids the copier put in, and the
-- animation packs of your profile and of the look being worn. The game's description of you (your own look in this
-- game) is left out: a game that sets its own animations puts them there, and they must stay the game's.
function App.avatarAnimIds(snapshot)
    local ids = {}
    for id in pairs(F.DefaultAnimIds) do ids[id] = true end
    for id in pairs(F.WrittenIds) do ids[id] = true end
    local function packs(data)
        local props = type(data) == "table" and (data.Version == 2 and data.Properties or data) or nil
        if type(props) ~= "table" then return end
        for _, field in ipairs(App.AnimFields) do
            local assetId = Codec.id(props[field])
            if assetId then
                local sets = F.animationSets(assetId)
                if sets then
                    for _, list in pairs(sets) do for _, row in ipairs(list) do ids[F.normalizeAnimId(row.Id)] = true end end
                else
                    local one = F.resolveAnimationTrackId(assetId)
                    if one then ids[F.normalizeAnimId(one)] = true end
                end
            end
        end
    end
    packs(App.profileAnimData())
    if snapshot and not snapshot.Original then packs(snapshot.Data) end
    return ids
end
-- hold: change the folders only and leave the restart to the caller. Returns whether anything changed.
function App.restoreAnimations(char, snapshot, hold)
    local animate = char:FindFirstChild("Animate")
    if animate and snapshot.Animations then
        local changed = false
        -- Rows read from this character undo what the copier put in. Rows from anywhere else (a saved skin, the
        -- character before a respawn) never replace a game's own animations: a folder only changes when it holds
        -- avatar animations, and only to avatar animations. A saved skin used to put the animations of the game it
        -- was saved in over another game's own ones, and a restore put back animations the game had replaced since.
        local own = App.AnimSource[snapshot.Animations] == char
        -- Avatar animations are R15 animations. On an R6 or custom rig they play nothing and the character stands
        -- stiff, so there rows from elsewhere change nothing and the game's animations stay (as with a pack).
        if not own and F.getTrueRigType(char) ~= Enum.HumanoidRigType.R15 then return end
        local avatar = not own and App.avatarAnimIds(snapshot) or {}
        local function isAvatar(id)
            id = F.normalizeAnimId(id)
            if id == "" or avatar[id] then return true end
            local roblox = App.robloxAnimation(id)
            if roblox then avatar[id] = true end
            return roblox
        end
        local function free(node)
            if node:IsA("Animation") then return isAvatar(node.AnimationId) end
            for _, child in ipairs(node:GetDescendants()) do
                if child:IsA("Animation") and not isAvatar(child.AnimationId) then return false end
            end
            return true
        end
        -- Your own rows only undo what the copier put in: an animation the game changed since (a game that sets
        -- its own moves after you spawn) stays the game's.
        local function written(node)
            if node:IsA("Animation") then return F.WrittenIds[F.normalizeAnimId(node.AnimationId)] == true end
            for _, child in ipairs(node:GetDescendants()) do
                if child:IsA("Animation") and F.WrittenIds[F.normalizeAnimId(child.AnimationId)] then return true end
            end
            return false
        end
        -- Rows captured whole (Full) describe every animation of their folder: the folder is made to match exactly,
        -- so an animation another avatar added (a second idle, for example) goes away again. Older rows only set ids.
        local sets, order = {}, {}
        for _, row in ipairs(snapshot.Animations) do
            local path = type(row.Path) == "table" and row.Path or {}
            if row.Full and #path >= 2 then
                local key = table.concat(path, "\0", 1, #path - 1)
                if not sets[key] then sets[key] = {Path = table.move(path, 1, #path - 1, 1, {}), List = {}}; table.insert(order, key) end
                table.insert(sets[key].List, {Name = path[#path], Id = row.Id, Weight = row.Weight})
            else
                local node = animate
                for _, name in ipairs(path) do node = node and node:FindFirstChild(name) end
                if node and node ~= animate and ((own and written(node)) or (not own and isAvatar(row.Id) and free(node))) then
                    if not own then F.markWritten({row}) end
                    if node:IsA("Animation") then
                        if F.setAnimationId(node, row.Id) then changed = true end
                    else
                        for _, child in ipairs(node:GetDescendants()) do
                            if child:IsA("Animation") and F.setAnimationId(child, row.Id) then changed = true end
                        end
                    end
                end
            end
        end
        for _, key in ipairs(order) do
            local set = sets[key]
            local folder = animate
            for _, name in ipairs(set.Path) do folder = folder and folder:FindFirstChild(name) end
            if folder and not folder:IsA("Animation") then
                local allowed = (own and written(folder)) or (not own and free(folder))
                if allowed and not own then
                    for _, row in ipairs(set.List) do if not isAvatar(row.Id) then allowed = false; break end end
                end
                if allowed then
                    if not own then F.markWritten(set.List) end
                    if F.applyAnimationSet(folder, set.List) then changed = true end
                end
            end
        end
        -- Unchanged ids are already playing; restarting Animate then would only interrupt them.
        if changed and not hold then F.restartAnimate(char, true) end
        return changed
    end
    return false
end
-- STALE ANIMATIONS: an avatar used to keep the animations of the one worn before it when it brought none of its own (a
-- profile copied with Copy animations off) or only some of them (a skin saved with fewer Animate folders). A new avatar
-- now starts from your character's own animations: what the copier put in Animate comes out first (only that: a game's
-- own animations stay), then the new avatar's go in, and Animate restarts once. Returns whether anything changed.
-- base: the rows to go back to, read from this character (the undo base, or visual-only's own capture).
function App.resetAnimations(char, base)
    if type(base) ~= "table" or App.AnimSource[base] ~= char then return false end
    return App.restoreAnimations(char, {Animations = base}, true) == true
end
-- An avatar's animation pack as Animate rows (each set whole, with its weights), or a single id per state when the
-- pack has no sets.
App.PackFolders = {ClimbAnimation = {"climb"}, FallAnimation = {"fall"}, IdleAnimation = {"idle"}, JumpAnimation = {"jump"},
    RunAnimation = {"run"}, SwimAnimation = {"swim", "swimidle"}, WalkAnimation = {"walk"}, MoodAnimation = {"mood"}}
function App.packRows(desc)
    local rows = {}
    for _, field in ipairs(App.AnimFields) do
        local names = App.PackFolders[field]
        local ok, asset = pcall(function() return desc[field] end)
        if names and ok and tonumber(asset) and tonumber(asset) ~= 0 then
            local sets = F.animationSets(asset)
            if sets then
                for _, name in ipairs(names) do
                    for _, row in ipairs(sets[name] or {}) do table.insert(rows, {Path = {name, row.Name}, Id = row.Id, Weight = row.Weight, Full = true}) end
                end
            else
                local one = F.resolveAnimationTrackId(asset)
                if one then table.insert(rows, {Path = {names[1]}, Id = one}) end
            end
        end
    end
    return rows
end
-- A saved skin's animations: the ones its Animate had when it was saved, with the animation pack its own items include
-- (the one the shop's Wearing list shows) taking over the states that pack covers. A skin saved in a game that keeps
-- Roblox's default animations used to lose its pack, and showed the defaults or an earlier avatar's animations.
function App.skinAnimations(data, desc)
    local pack = desc and App.packRows(desc) or {}
    local covered, rows = {}, {}
    for _, row in ipairs(pack) do
        local first = type(row.Path) == "table" and row.Path[1]
        if type(first) == "string" then covered[first:lower()] = true end
    end
    local saved = type(data) == "table" and type(data.Visual) == "table" and data.Visual.Animations or {}
    for _, row in ipairs(type(saved) == "table" and saved or {}) do
        local first = type(row) == "table" and type(row.Path) == "table" and row.Path[1]
        if not (type(first) == "string" and covered[first:lower()]) then table.insert(rows, row) end
    end
    for _, row in ipairs(pack) do table.insert(rows, row) end
    return rows
end
-- VISUAL-ONLY ANIMATIONS: with Copy animations on, the avatar's animation pack is played by your character itself, not
-- only by the avatar drawn over it. The overlay copies the character's joints, so the hidden body and the avatar you
-- see move the same. Only when the overlay is of the same rig (R15) and follows the character itself, and only in
-- Animate folders that hold avatar animations (a game's own animations stay, as on a normal apply). A saved skin's own
-- animations are not put on the hidden body: that left some avatars standing stiff. Each
-- avatar starts from your character's own animations (see STALE ANIMATIONS); taking the avatar off, or wearing one
-- without a pack, gives the character its animations back.
App.VisualAnimBase = setmetatable({}, {__mode = "k"})
function App.visualAnimations(char, desc, snapshot)
    local base = App.VisualAnimBase[char]
    local entry = Overlay.Active[char]
    local rig = F.getTrueRigType(char)
    if desc and rig == Enum.HumanoidRigType.R15 and entry and entry.Target == char and F.getTrueRigType(entry.Model) == rig then
        -- Rows read from this character (a shop or Customize change, Undo, the timeline) say what to keep.
        if type(snapshot.Animations) == "table" and App.AnimSource[snapshot.Animations] == char then
            if base then App.restoreAnimations(char, snapshot) end
            return
        end
        local rows = (Store.Settings.CopyAnims or snapshot.ForceAnims) and App.packRows(desc) or {}
        if #rows > 0 then
            local changed = false
            if base then changed = App.resetAnimations(char, base)
            else App.VisualAnimBase[char] = App.captureAnimations(char) end
            changed = App.restoreAnimations(char, {Animations = rows, Data = snapshot.Data}, true) or changed
            if changed then F.restartAnimate(char, true) end
            return
        end
    end
    if base then
        App.VisualAnimBase[char] = nil
        App.restoreAnimations(char, {Animations = base})
    end
end
function App.captureAnimations(char)
    local rows = {}; local animate = char and char:FindFirstChild("Animate")
    if animate then for _, item in ipairs(animate:GetDescendants()) do
        if item:IsA("Animation") and #rows < 100 then
            local path, cursor = {}, item
            while cursor and cursor ~= animate do table.insert(path, 1, cursor.Name); cursor = cursor.Parent end
            local weight = item:FindFirstChild("Weight")
            F.rememberAnimateId(item.AnimationId)
            table.insert(rows, {Path = path, Id = item.AnimationId, Full = true, Weight = weight and weight:IsA("NumberValue") and weight.Value or nil})
        end
    end end
    if char then App.AnimSource[rows] = char end
    return rows
end

-- RETURNING ITEMS: your own items set aside under a copied avatar are only unparented on your screen. A game that moves
-- them from the server (JJS re-welds or re-parents accessories) sends them back, and your own hair and cap showed
-- again on the copied avatar. An item of yours that comes back while a copied avatar is on is set aside again.
-- Test builds: the accessories left on your character under a copied avatar, and why, so a game whose own items still
-- show can be told apart from a missed avatar item.
function App.noteKept(char)
    local kept = {}
    for _, item in ipairs(char:GetDescendants()) do
        if item:IsA("Accessory") and not item:GetAttribute("Copier_CopiedItem") and not item:FindFirstAncestorOfClass("Tool") then
            local why = (item:FindFirstChildWhichIsA("Script", true) or item:FindFirstChildWhichIsA("LocalScript", true)) and "has a script"
                or Appearance.ownItem(item) and "yours, kept by the game" or not Appearance.avatarItem(item) and "not on an avatar attachment, not known as yours"
                or "name and mesh not known as yours"
            table.insert(kept, item.Name .. (item.Parent ~= char and (" in " .. item.Parent.Name) or "") .. " (" .. why .. ")")
            if #kept >= 6 then break end
        end
    end
    if #kept > 0 then App.devNote("Left on your character as the game's: " .. table.concat(kept, ", ")) end
end
function Appearance.watchReturns(character)
    if Appearance.ReturnWatch then Appearance.ReturnWatch:Disconnect(); Appearance.ReturnWatch = nil end
    if not character then return end
    Appearance.ReturnWatch = character.DescendantAdded:Connect(function(item)
        if not (item:IsA("Accessory") or item:IsA("Shirt") or item:IsA("Pants") or item:IsA("ShirtGraphic")) then return end
        if item:GetAttribute("Copier_CopiedItem") or item:FindFirstAncestorOfClass("Tool") then return end
        -- A uniform the game puts on while a copied avatar is worn (see THE GAME'S CLOTHES AND ITEMS).
        if not item:IsA("Accessory") and item.Parent == character and Store.Settings.KeepGameClothes then
            task.delay(0.1, function()
                if item.Parent ~= character or not Appearance.copyOn(character) then return end
                if Appearance.keepsClothing(character, item) then
                    App.devNote("The game dressed you in " .. item.Name .. "; it shows over the copied avatar.")
                    Appearance.wearGameClothing(character, item)
                elseif Appearance.stashed(character, item) then
                    App.devNote("The game put back " .. item.Name .. " on your character; set aside again.")
                    Appearance.stash(character, item)
                end
            end)
            return
        end
        if item:IsA("Accessory") and Appearance.keepsItem(character, item) then return end
        if not Appearance.stashed(character, item) then return end
        -- Its parts arrive with it; checked again a moment later, when the copier is not changing the body itself.
--|YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
        task.delay(0.1, function()
            if not App.alive() or App.Busy or not item:IsDescendantOf(character) or character ~= lp.Character then return end
            if not App.Current or App.Current.Original or S.TouchedChar ~= character then return end
            App.devNote("The game put back " .. item.Name .. " on your character; set aside again.")
            Appearance.stash(character, item)
        end)
    end)
    RegisterConnection(Appearance.ReturnWatch)
end
-- Incremental recovery is driven by removal events, never by full-body polling.
local Repair = {Generation = 0, Rows = {}, Connections = {}, Budget = 0}
function Repair.stop()
    Repair.Generation = Repair.Generation + 1
    for _, connection in ipairs(Repair.Connections) do connection:Disconnect() end
    table.clear(Repair.Connections)
    for _, row in ipairs(Repair.Rows) do if row.Template then row.Template:Destroy() end end
    table.clear(Repair.Rows); Repair.Budget = 0; Repair.Character = nil
    Repair.dropParked()
end
-- A new character took over while the one wearing the copied avatar may come back (a size potion swaps in a bigger
-- body for a while): its list of items is kept aside instead of thrown away, and follows it again when it is back.
function Repair.park()
    local char, rows = Repair.Character, Repair.Rows
    -- Nothing followed now (the body before was never changed): what is kept aside stays.
    if not char then return end
    Repair.Rows = {}
    Repair.stop()
    if #rows > 0 then Repair.Parked = {Character = char, Rows = rows} end
end
function Repair.dropParked()
    local parked = Repair.Parked
    Repair.Parked = nil
    for _, row in ipairs(parked and parked.Rows or {}) do if row.Template then pcall(function() row.Template:Destroy() end) end end
end
-- Follows char again with the items kept aside for it. Returns whether there were any.
function Repair.unpark(char)
    local parked = Repair.Parked
    if not parked or parked.Character ~= char then return false end
    Repair.Parked = nil
    Repair.watch({Items = parked.Rows}, char)
    return true
end
function Repair.present(row)
    if row.Instance and row.Instance.Parent == Repair.Character then return row.Instance end
    if not Repair.Character then return nil end
    for _, child in ipairs(Repair.Character:GetChildren()) do
        if child:GetAttribute("Lyra_ItemKey") == row.Key then row.Instance = child; return child end
    end
end
function Repair.queue(row)
    if row.Pending or row.Suppressed or not Config.MapPersist or App.Busy or not S.fvOn or not App.alive() then return end
    if Repair.present(row) then return end
    local generation = Repair.Generation
    row.Pending = true
    task.delay(0.8, function()
        row.Pending = false
        if generation ~= Repair.Generation or not App.alive() or App.Busy or not Config.MapPersist or not S.fvOn then return end
        local char = Repair.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not char or char ~= lp.Character or not char.Parent or not hum or hum.Health <= 0 or Repair.present(row) then return end
        if row.Attempts >= 2 or Repair.Budget >= 12 then
            row.Suppressed = true
            if not Repair.Warned then Repair.Warned = true; App.report("The game keeps removing some items. Recovery was paused to prevent repeated reconstruction.", "warning") end
            return
        end
        row.Attempts = row.Attempts + 1; Repair.Budget = Repair.Budget + 1
        local ok, item = pcall(Appearance.item, row.Template, char, row.Key)
        if ok and item then row.Instance = item else row.Suppressed = true end
        -- No call to applySnapshot, no reset, no body replacement, no retry loop.
    end)
end
function Repair.watch(report, character)
    Repair.stop()
    Repair.Character = character; Repair.Rows = report and report.Items or {}; Repair.Warned = false
    if not character then return end
    table.insert(Repair.Connections, character.ChildRemoved:Connect(function(child)
        for _, row in ipairs(Repair.Rows) do if row.Instance == child then Repair.queue(row); break end end
    end))
    if S.fvOn then Repair.watchGame(character) end
end
-- GAME AVATAR CHANGES: catalog games (Catalog Avatar Creator and others), morphs and outfit loaders change your
-- avatar from the server. On top of a copied avatar that used to mix both looks (pieces of each clipping together).
-- A change is recognised by a new description from the game or a replaced body part, or by at least three new
-- avatar pieces at once (clothing, and accessories worn on standard avatar attachments or layered). Game items such
-- as weapons or tools do not count, and the copier's own items are tagged and never count. Then, by GameChange:
--   Yield  - the copied avatar comes off and the game's new look becomes your starting point (Undo brings it back).
--   Keep   - what the game just added is taken off and the copied avatar is put back.
--   Ignore - nothing happens (the old behaviour).
Repair.AvatarAttachments = Appearance.AvatarAttachments
-- An accessory that looks like an avatar item: layered clothing, or worn on a standard avatar attachment, without scripts.
function Repair.avatarItem(accessory) return Appearance.avatarItem(accessory) end
function Repair.watchGame(character)
    local hum = character:FindFirstChildOfClass("Humanoid")
    if not hum or Store.Settings.GameChange == "Ignore" then return end
    local generation, batch = Repair.Generation, nil
    local function signal(kind, item)
        if App.Busy or not S.fvOn or generation ~= Repair.Generation or not App.alive() then return end
        if not batch then
            batch = {Accessories = {}, Clothes = {}, Pieces = 0, Strong = false}
            local current = batch
            -- A server change arrives in pieces; it is judged once, after it settles (children have arrived by then).
            task.delay(0.8, function()
                if batch == current then batch = nil end
                if generation ~= Repair.Generation or App.Busy or not S.fvOn or not App.alive() or character ~= lp.Character then return end
                local avatarItems = {}
                for _, accessory in ipairs(current.Accessories) do
                    if accessory.Parent == character and Repair.avatarItem(accessory) and not Appearance.keepsItem(character, accessory) then
                        table.insert(avatarItems, accessory)
                    end
                end
                current.Accessories = avatarItems
                -- The game's clothes the settings keep are not a new look (see THE GAME'S CLOTHES AND ITEMS).
                current.Pieces = 0
                for _, piece in ipairs(current.Clothes) do
                    if piece.Parent == character and not Appearance.keepsClothing(character, piece) then current.Pieces = current.Pieces + 1 end
                end
                if current.Strong or current.Pieces + #avatarItems >= 3 then Repair.gameChanged(character, current) end
            end)
        end
        if kind == "accessory" then table.insert(batch.Accessories, item)
        elseif kind == "clothing" then batch.Pieces = batch.Pieces + 1; table.insert(batch.Clothes, item)
        else batch.Strong = true; if kind == "description" then batch.Description = item else batch.Body = true end end
    end
    table.insert(Repair.Connections, hum.ChildAdded:Connect(function(child)
        if child:IsA("HumanoidDescription") and not child:GetAttribute("Lyra_Description") then signal("description", child) end
    end))
    -- The game's description stays on the Humanoid (the copier only changes its emotes), so a catalog game that edits
    -- it from the server (try-ons, refinements) is noticed as well.
    local live = App.liveDescription(hum)
    if live and not live:GetAttribute("Lyra_Description") then
        local watched = {}
        for _, fields in ipairs({Codec.assetFields, Codec.scaleFields, Codec.colorFields, Codec.accessoryFields}) do
            -- Animations are not part of the look: a game that gives you its own moves through the description
            -- (Violence District) is not changing your avatar.
            for _, field in ipairs(fields) do if not field:find("Animation", 1, true) then watched[field] = true end end
        end
        table.insert(Repair.Connections, live.Changed:Connect(function(property)
            if watched[property] and live.Parent == hum then signal("description", live) end
        end))
    end
    table.insert(Repair.Connections, character.ChildAdded:Connect(function(child)
        if child:GetAttribute("Copier_CopiedItem") or child:GetAttribute("Lyra_VisualFor") then return end
        if child:IsA("Accessory") then signal("accessory", child)
        elseif child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then signal("clothing", child)
        elseif child:IsA("BasePart") and S.BD[child.Name] and child.Name ~= "HumanoidRootPart" then signal("body", child) end
    end))
end
Repair.GameReactions = {}
-- Everything a description shows (body, clothing, colours, sizes, accessories), animations and emotes left out.
-- noScales: the body's size left out too.
function App.lookKey(desc, noScales)
    local parts = {}
    local ok = pcall(function()
        for _, field in ipairs(Codec.assetFields) do if not field:find("Animation", 1, true) then table.insert(parts, tostring(desc[field])) end end
        if not noScales then
            for _, field in ipairs(Codec.scaleFields) do table.insert(parts, string.format("%.3f", desc[field])) end
        end
        for _, field in ipairs(Codec.colorFields) do
            local color = desc[field]
            table.insert(parts, string.format("%d,%d,%d", math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5)))
        end
        local ids = {}
        for _, row in ipairs(desc:GetAccessories(true)) do table.insert(ids, tostring(row.AssetId)) end
        table.sort(ids)
        table.insert(parts, table.concat(ids, ","))
    end)
    return ok and table.concat(parts, "|") or nil
end
function Repair.gameChanged(character, batch)
    local mode = Store.Settings.GameChange
    App.trace(string.format("Game changed the avatar (%s): description=%s body=%s clothing=%d avatar items=%d", tostring(mode),
        batch.Description and App.traceName(batch.Description) or "none", tostring(batch.Body == true), batch.Pieces, #batch.Accessories))
    if mode == "Ignore" or not App.Current or App.Current.Original then return end
    local hum = character:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then return end
    -- A game that re-applies its look every time ours goes on would loop: at most 3 reactions a minute.
    local now = os.clock()
    for i = #Repair.GameReactions, 1, -1 do if now - Repair.GameReactions[i] > 60 then table.remove(Repair.GameReactions, i) end end
    if #Repair.GameReactions >= 3 then return end
    table.insert(Repair.GameReactions, now)
    -- A new description that only changes animations or emotes (a game giving you its own moves) is not a new look.
    if batch.Description and batch.Description.Parent and not batch.Body and batch.Pieces == 0 and #batch.Accessories == 0 and S.gameDescription then
        local before, after = App.lookKey(S.gameDescription), App.lookKey(batch.Description)
        if before and before == after then
            pcall(function() local old = S.gameDescription; S.gameDescription = batch.Description:Clone(); old:Destroy() end)
            table.remove(Repair.GameReactions)
            return
        end
    end
    -- Only the body's size changed (a potion or power-up that makes you bigger or smaller): the same look at another
    -- size. The copied avatar stays on and takes the new size (see GAME SIZE CHANGES).
    if batch.Description and batch.Description.Parent and S.gameDescription then
        local before, after = App.lookKey(S.gameDescription, true), App.lookKey(batch.Description, true)
        if before and before == after then
            pcall(function() local old = S.gameDescription; S.gameDescription = batch.Description:Clone(); old:Destroy() end)
            table.remove(Repair.GameReactions)
            -- The game may have rebuilt limbs or items at the new size: the avatar goes on again either way.
            local rebuilt = batch.Body or batch.Pieces > 0 or #batch.Accessories > 0
            task.delay(0.6, function() if App.alive() then pcall(Scale.check, character, rebuilt) end end)
            return
        end
    end
    -- The game's look is new, so the list of its avatar items is rebuilt before the next application.
    S.gameAccNames = nil
    if batch.Description and batch.Description.Parent then
        if S.gameDescription then pcall(function() S.gameDescription:Destroy() end) end
        S.gameDescription = batch.Description:Clone()
    end
    if mode == "Keep" then
        -- What the game just added is kept aside (see STASH) and comes back with your own look.
        for _, item in ipairs(batch.Accessories) do
            if item.Parent == character and not Appearance.keepsItem(character, item) then Appearance.stash(character, item) end
        end
        App.toast({Title = "Avatar kept", Text = "The game changed your avatar; the copied one was put back on.", Kind = "info", Icon = "shirt", Duration = 4})
        task.spawn(App.applySnapshot, App.Current, "reapply", character)
        return
    end
    -- Yield: rebuild your body, clothing and colours from the game's new look (its accessories are already on
    -- the character) and make it the new starting point.
    -- Only a description that came with this change describes the new look (an older one would bring the old body back).
    local source = batch.Description and batch.Description.Parent and batch.Description or nil
    local ok, data = pcall(function() return Codec.encode(source) end)
    if not ok or not data then
        -- No new description came with this change: your own look comes back (the undo base, with the game's items as
        -- the game has them now). Undo brings the copied avatar back.
        if not App.Initial then return end
        task.spawn(function()
            if App.applySnapshot(App.Initial, "yield", character) then
                App.toast({Title = "The game changed your avatar", Text = "The copied avatar was taken off so the two looks don't mix. Undo puts it back.",
                    Kind = "info", Icon = "shirt", Duration = 7, Action = {Text = "Put it back", Callback = function() App.undo() end}})
            end
        end)
        return
    end
    local snapshot = {Data = data, Name = "Game appearance", Original = true, GameLook = true,
        Animations = App.Initial and App.Initial.Animations or App.captureAnimations(character)}
    task.spawn(function()
        if App.applySnapshot(snapshot, "game", character) then
            App.Initial = snapshot; App.InitialFor[character] = snapshot
            App.toast({Title = "The game changed your avatar", Text = "The copied avatar was taken off so the two looks don't mix. Undo puts it back.",
                Kind = "info", Icon = "shirt", Duration = 7, Action = {Text = "Put it back", Callback = function() App.undo() end}})
        end
    end)
end
function Repair.resume()
    if not Config.MapPersist then return end
    -- Changing the toggle does not reset a repeatedly rejected item's budget.
    for _, row in ipairs(Repair.Rows) do if not Repair.present(row) then Repair.queue(row) end end
end
-- THE GAME'S CLOTHES AND ITEMS: games dress you themselves: a team or class uniform (Prison Life, SCP games), the Beast's
-- hammer on the back in Flee the Facility. Under a copied avatar those used to go: the uniform was set aside with your
-- own clothes, and an item worn on an avatar attachment was taken for an avatar item. Two settings keep them, and the
-- rest of the avatar (body, face, hair, accessories, layered clothing) still goes on:
--   KeepGameClothes - a Shirt, Pants or T-shirt the game put on you stays, in place of the avatar's own of that kind. Your
--                     own avatar's clothes are told apart by their template; until they are known, nothing is kept.
--   KeepGameItems   - an accessory that is not one of your own avatar's items (nor of a look the game gave you) stays.
-- A uniform the game puts on later (a new piece, or a new template on your own shirt set aside) shows at once and takes
-- the copied piece of its kind off, and such a change is not taken for the game changing your whole avatar.
-- THE GAME'S CLOTHES ON SCRIPT USERS: a script user's synced skin is drawn over their character on your screen, and the
-- game dresses them too. With the same settings on, what the game put on them shows on their drawn skin as it does on
-- yours: their uniform replaces the skin's clothes of its kind and the game's items stay visible. It is told apart the
-- same way, from their own avatar (its clothes by template, its items by name and mesh), read from Roblox once per
-- player (see Sync.lookOf). Until it is read, nothing of theirs is kept.
function Appearance.gameClothing(item)
    if not (item:IsA("Shirt") or item:IsA("Pants") or item:IsA("ShirtGraphic")) or item:GetAttribute("Copier_CopiedItem") then return false end
    if not S.ownClothes then return false end
    local key = F.clothingKey(item)
    return key ~= nil and S.ownClothes[key] ~= true
end
-- The own avatar of the script user a character belongs to, once read, or nil (you, anyone else, not read yet).
function Appearance.peerLook(character)
    local player = Players:GetPlayerFromCharacter(character)
    if not player or player == lp or not Sync.Shown[player.UserId] then return nil end
    return Sync.lookOf(player.UserId)
end
function Appearance.keepsClothing(character, item)
    if Store.Settings.KeepGameClothes ~= true then return false end
    if character == lp.Character then return Appearance.gameClothing(item) end
    if not (item:IsA("Shirt") or item:IsA("Pants") or item:IsA("ShirtGraphic")) then return false end
    local look = Appearance.peerLook(character)
    local key = look and F.clothingKey(item)
    return key ~= nil and look.Clothes[key] ~= true
end
function Appearance.keepsItem(character, item)
    if Store.Settings.KeepGameItems ~= true then return false end
    if not item:IsA("Accessory") or item:GetAttribute("Copier_CopiedItem") then return false end
    if character == lp.Character then return S.ownAccNames ~= nil and not Appearance.isAvatarAccessory(item) end
    local look = Appearance.peerLook(character)
    if not look then return false end
    if item:FindFirstChildWhichIsA("Script", true) or item:FindFirstChildWhichIsA("LocalScript", true) then return true end
    return not Appearance.ownItem(item, look.Names, look.Meshes)
end
-- A keep setting changed: the avatar you wear goes on again with it (the drawn one follows by itself).
function App.keepSettingChanged()
    task.spawn(function()
        pcall(F.getSafeAccessoryNames)
        if not App.alive() or Overlay.visualOnly() or App.Busy or not App.Current or App.Current.Original or not S.fvOn then return end
        App.applySnapshot(App.Current, "reapply")
    end)
end
-- Puts back the stashed pieces the settings now keep (one turned on while a copied avatar was worn).
function Appearance.returnKept(character)
    local list = Appearance.Stash[character]
    if not list then return end
    for index = #list, 1, -1 do
        local item = list[index]
        local keep = (item:IsA("Accessory") and Appearance.keepsItem(character, item)) or Appearance.keepsClothing(character, item)
        if keep then
            local from = Appearance.StashedFrom[item]
            local parent = (from and from:IsDescendantOf(character)) and from or character
            if pcall(function() item.Parent = parent end) and item.Parent == parent then
                table.remove(list, index)
                Appearance.StashedFrom[item] = nil
                local watch = Appearance.StashWatch[item]
                if watch then watch:Disconnect(); Appearance.StashWatch[item] = nil end
            end
        end
    end
end
-- The game's piece of clothing shows: the copied one of the same kind comes off and is not put back by Repair until
-- the game takes its piece off again (the round ends).
function Appearance.wearGameClothing(character, item)
    local held = {}
    for _, child in ipairs(character:GetChildren()) do
        if child ~= item and child.ClassName == item.ClassName and child:GetAttribute("Copier_CopiedItem") then
            for _, row in ipairs(Repair.Rows) do if row.Instance == child then row.Suppressed = true; table.insert(held, row) end end
            pcall(function() child:Destroy() end)
        end
    end
    if #held == 0 then return end
    local connection
    connection = item.AncestryChanged:Connect(function()
        if item:IsDescendantOf(character) then return end
        connection:Disconnect()
        task.delay(0.3, function()
            if not Appearance.copyOn(character) then return end
            for _, other in ipairs(character:GetChildren()) do
                if other.ClassName == item.ClassName and Appearance.keepsClothing(character, other) then return end
            end
            for _, row in ipairs(held) do row.Suppressed = false; row.Attempts = 0; Repair.queue(row) end
        end)
    end)
    table.insert(Repair.Connections, connection)
end
function Appearance.copyOn(character)
    return App.alive() and not App.Busy and character == lp.Character and App.Current ~= nil and not App.Current.Original
        and S.TouchedChar == character
end
function Appearance.watchStashed(character, item)
    if not (item:IsA("Shirt") or item:IsA("Pants") or item:IsA("ShirtGraphic")) or Appearance.StashWatch[item] then return end
    Appearance.StashWatch[item] = item.Changed:Connect(function(property)
        if property ~= "ShirtTemplate" and property ~= "PantsTemplate" and property ~= "Graphic" then return end
        task.defer(function()
            if item.Parent ~= nil or not Appearance.copyOn(character) or not Appearance.keepsClothing(character, item) then return end
            Appearance.returnKept(character)
            if item.Parent then
                App.devNote("The game dressed you in a new " .. item.ClassName .. "; it shows over the copied avatar.")
                Appearance.wearGameClothing(character, item)
            end
        end)
    end)
end

-- GAME INVISIBILITY: games make your character invisible (an invisibility cloak, a ghost or stealth power) by changing
-- the transparency of its body parts. What the copier adds is its own: copied accessories, the local copies drawn
-- over limbs that would not take a new mesh (a Korblox leg, for example), copied faces and body effects. They stayed
-- visible, so a hat, a face or a whole leg walked around on their own. Now the transparency the game gives each body
-- part is followed: everything the copier put on that part fades with it, and when the game shows the part again the
-- copied avatar's own look comes back (a headless head stays headless). Body parts the copier keeps hidden itself use
-- the mask (Cloak.Mask) instead of 1, so the game's own 1 still shows as a change.
Cloak.Known = setmetatable({}, {__mode = "k"})
Cloak.Connections = {}
-- How much the game hides a body part right now: 0 (as the game shows it) to 1 (invisible).
function Cloak.hidden(row)
    if row.Normal >= 0.5 then return 0 end
    return math.clamp((row.Known - row.Normal) / (1 - row.Normal), 0, 1)
end
-- Whether the game's value of this part can be read (the copier does not keep it at 1 itself).
function Cloak.readable(row)
    return row.Normal < 0.5 and (row.Wanted < 0.99 or row.Covered ~= nil)
end
-- The body part an accessory hangs from, by name.
function Cloak.mountOf(accessory, char)
    local handle = accessory:FindFirstChild("Handle")
    for _, joint in ipairs(handle and handle:GetChildren() or {}) do
        if joint:IsA("JointInstance") or joint:IsA("WeldConstraint") then
            for _, part in ipairs({joint.Part0, joint.Part1}) do
                if part and part ~= handle and Appearance.isBody(part, char) then return part.Name end
            end
        end
    end
    local body = accessory:GetAttribute("Lyra_MountBody")
    return type(body) == "string" and body or nil
end
-- Fades one of the copier's own parts or decals by f, keeping its own transparency to give back later.
function Cloak.fadeOne(item, f)
    local base, set = item:GetAttribute("Lyra_CloakBase"), item:GetAttribute("Lyra_CloakSet")
    if f <= 0.001 then
        if type(base) == "number" then
            -- Something else changed it meanwhile (an item adjustment): that value stays.
            if type(set) ~= "number" or math.abs(item.Transparency - set) < 1e-4 then item.Transparency = base end
            item:SetAttribute("Lyra_CloakBase", nil); item:SetAttribute("Lyra_CloakSet", nil)
        end
        return
    end
    if type(base) ~= "number" or (type(set) == "number" and math.abs(item.Transparency - set) > 1e-4) then
        base = item.Transparency; item:SetAttribute("Lyra_CloakBase", base)
    end
    local value = 1 - (1 - base) * (1 - f)
    item:SetAttribute("Lyra_CloakSet", value)
    if math.abs(item.Transparency - value) > 1e-4 then item.Transparency = value end
end
-- Effects stop while the part they are on is invisible, and start again with it.
function Cloak.effect(item, f)
    local saved = item:GetAttribute("Lyra_CloakEnabled")
    if f >= 0.99 then
        if saved == nil then
            local ok, enabled = pcall(function() return item.Enabled end)
            if ok and type(enabled) == "boolean" then item:SetAttribute("Lyra_CloakEnabled", enabled); pcall(function() item.Enabled = false end) end
        end
    elseif type(saved) == "boolean" then
        item:SetAttribute("Lyra_CloakEnabled", nil); pcall(function() item.Enabled = saved end)
    end
end
function Cloak.fadeAll(root, f)
    for _, item in ipairs(root:GetDescendants()) do
        if item:IsA("BasePart") or item:IsA("Decal") then pcall(Cloak.fadeOne, item, f)
        elseif Visual.effects[item.ClassName] then pcall(Cloak.effect, item, f) end
    end
    if root:IsA("BasePart") then pcall(Cloak.fadeOne, root, f) end
end
function Cloak.update()
    local char = Cloak.Character
    if not char or not char.Parent or char ~= lp.Character or not App.alive() then return end
    -- A part whose game value cannot be read follows the whole body (the least hidden part that can be read).
    local body, count = 1, 0
    for part, row in pairs(Cloak.Parts) do
        if part.Parent == char and Cloak.readable(row) then body = math.min(body, Cloak.hidden(row)); count = count + 1 end
    end
    if count == 0 then body = 0 end
    local factors = {}
    for part, row in pairs(Cloak.Parts) do
        if part.Parent == char then
            local f = Cloak.readable(row) and Cloak.hidden(row) or body
            factors[part.Name] = f
            -- The copied avatar's own transparency, faded as much as the game fades this part. A part the game always
            -- hides is left to the game, and so is one the game keeps changing back (no tug of war, at most 8 writes
            -- in 3 seconds). A cloak fading in and out uses those writes up on a limb the copied avatar hides (a Korblox
            -- leg), and the game's last step (0, shown) stayed: the part is looked at again once writes are allowed.
            local wanted = row.Covered and Cloak.Mask or (1 - (1 - row.Wanted) * (1 - f))
            local now = os.clock()
            if now - (row.WindowAt or 0) > 3 then row.WindowAt = now; row.Writes = 0 end
            if row.Normal < 0.5 and math.abs(part.Transparency - wanted) > 0.005 then
                if (row.Writes or 0) < 8 then
                    row.Writes = (row.Writes or 0) + 1; row.Pending = wanted; pcall(function() part.Transparency = wanted end)
                elseif not Cloak.Retry then
                    Cloak.Retry = true
                    task.delay(3.1 - (now - row.WindowAt), function() Cloak.Retry = false; if App.alive() then Cloak.schedule() end end)
                end
            end
            for _, child in ipairs(part:GetChildren()) do
                if child:IsA("Decal") then
                    -- A face the copier copied fades; the game's own face under a local copy stays hidden.
                    if child:GetAttribute("Lyra_CopiedSurface") then pcall(Cloak.fadeOne, child, f)
                    elseif row.Covered and child:GetAttribute("Lyra_BeforeOverlay") ~= nil and child.Transparency < 1 then pcall(function() child.Transparency = 1 end) end
                end
            end
            for _, item in ipairs(part:GetDescendants()) do
                if item:GetAttribute("Lyra_BodyEffect") then pcall(Cloak.effect, item, f) end
            end
        end
    end
    Cloak.Body = body
    if App.tracing() then
        local rows = {}
        for name, f in pairs(factors) do if f > 0.005 then table.insert(rows, string.format("%s %.2f", name, f)) end end
        table.sort(rows)
        local summary = string.format("Cloak: whole body %.2f; hidden parts: %s", body, #rows > 0 and table.concat(rows, ", ") or "none")
        if summary ~= Cloak.LastTrace then Cloak.LastTrace = summary; App.trace(summary) end
    end
    for _, item in ipairs(char:GetChildren()) do
        if item:IsA("Accessory") and item:GetAttribute("Copier_CopiedItem") then
            Cloak.fadeAll(item, factors[Cloak.mountOf(item, char) or ""] or body)
        elseif item:IsA("BasePart") and item:GetAttribute("Lyra_VisualFor") then
            Cloak.fadeAll(item, factors[tostring(item:GetAttribute("Lyra_VisualFor"))] or body)
        end
    end
end
function Cloak.schedule()
    if Cloak.Scheduled then return end
    Cloak.Scheduled = true
    task.defer(function() Cloak.Scheduled = false; pcall(Cloak.update) end)
end
function Cloak.changed(row)
    local value = row.Part.Transparency
    if row.Pending and math.abs(value - row.Pending) < 1e-4 then row.Pending = nil; return end
    row.Pending = nil
    -- The copier's own mark on a limb drawn by a local copy.
    if row.Covered and isMask(value) then return end
    row.Known = value
    Cloak.schedule()
end
-- Follows the character the copier just reshaped (your own character, not visual-only).
function Cloak.watch(char)
    Cloak.stop()
    if not char or not char.Parent then return end
    Cloak.Character = char
    for _, part in ipairs(char:GetChildren()) do
        if Appearance.isBody(part, char) and part.Name ~= "HumanoidRootPart" then
            local normal = part:GetAttribute("Lyra_GameTransparency")
            if type(normal) ~= "number" then normal = 0 end
            local covered = char:FindFirstChild("LyraVisual_" .. part.Name)
            if covered and covered:GetAttribute("Lyra_VisualFor") ~= part.Name then covered = nil end
            local row = {Part = part, Normal = normal, Wanted = covered and Cloak.Mask or part.Transparency, Covered = covered}
            -- What the game did before the copier changed the body is still true (a cloak worn while the avatar went on).
            row.Known = Cloak.Known[part] or normal
            Cloak.Parts[part] = row
            table.insert(Cloak.Connections, part:GetPropertyChangedSignal("Transparency"):Connect(function() Cloak.changed(row) end))
        end
    end
    -- Items put back later (Keep avatar between rounds) follow at once.
    table.insert(Cloak.Connections, char.ChildAdded:Connect(function(child)
        if child:GetAttribute("Copier_CopiedItem") or child:GetAttribute("Lyra_VisualFor") then Cloak.schedule() end
    end))
    Cloak.update()
end
function Cloak.stop()
    for _, connection in ipairs(Cloak.Connections) do connection:Disconnect() end
    table.clear(Cloak.Connections)
    for part, row in pairs(Cloak.Parts) do Cloak.Known[part] = row.Known end
    table.clear(Cloak.Parts)
    Cloak.Character = nil
end
--: YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU

-- GAME SIZE CHANGES: potions and power-ups make your character bigger or smaller by resizing its body parts. On a copied
-- avatar that gave the copied meshes the game's sizes and joints (a Korblox leg grew huge and split from the body) and
-- left the copied items at their old size (a hat or hair sank inside a giant head). Changing the body's size through
-- the game's description also counted as a new avatar, so the copied one came off. Now a size change by the game is
-- measured against the size the game had when the copied avatar went on, and the copied avatar is put back on at the
-- same scale (and at its own size again when the effect ends). At most four times in half a minute.
Scale.Connections = {}
Scale.Reactions = {}
function Scale.stop()
    for _, connection in ipairs(Scale.Connections) do connection:Disconnect() end
    table.clear(Scale.Connections)
    Scale.Character = nil
end
-- Records the sizes the copier just gave the body and follows the game's changes to them.
function Scale.watch(char)
    Scale.stop()
    if not char or not char.Parent then return end
    Scale.Character = char
    for _, part in ipairs(char:GetChildren()) do
        if Appearance.isBody(part, char) and part.Name ~= "HumanoidRootPart" and typeof(part:GetAttribute("Lyra_GameSize")) == "Vector3" then
            part:SetAttribute("Lyra_SetSize", part.Size)
            table.insert(Scale.Connections, part:GetPropertyChangedSignal("Size"):Connect(function() Scale.changed(char, part) end))
        end
    end
    -- The body joints and HipHeight as the copier set them, held while the game rescales your own body (see GAME
    -- SCALE VALUES).
    for _, joint in ipairs(char:GetDescendants()) do
        if joint:IsA("Motor6D") and joint.Part0 and joint.Part1 and Appearance.isBody(joint.Part0, char) and Appearance.isBody(joint.Part1, char) then
            joint:SetAttribute("Lyra_SetC0", joint.C0); joint:SetAttribute("Lyra_SetC1", joint.C1)
            for _, field in ipairs({"C0", "C1"}) do
                table.insert(Scale.Connections, joint:GetPropertyChangedSignal(field):Connect(function() if Scale.holding(char) then Scale.holdJoint(joint, field) end end))
            end
        end
    end
    -- The scale values the game writes (see GAME SCALE VALUES).
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        hum:SetAttribute("Lyra_SetHip", hum.HipHeight)
        table.insert(Scale.Connections, hum:GetPropertyChangedSignal("HipHeight"):Connect(function() if Scale.holding(char) then Scale.holdHip(hum) end end))
    end
    for _, row in ipairs(Scale.ValueFields) do
        local value = hum and hum:FindFirstChild(row[2])
        if value and value:IsA("NumberValue") then
            table.insert(Scale.Connections, value.Changed:Connect(function() Scale.valueChanged(char, row[1], value) end))
        end
    end
end
-- GAME SCALE VALUES: some games size your body through the Humanoid's scale values (Muscle Legends writes its own
-- height, width, depth and head size for your strength: thin and tall at first, wider as you train), whatever your
-- avatar's are. A copied avatar went on with its own values (or, later, scaled evenly by the body's height), so it was
-- too wide, too big, and your own look came back at the wrong size too. The values the game writes are now told apart
-- from your avatar's (they differ from the game's description of your look), and every avatar on that body, your own
-- look included, is built with them, as Roblox builds a body in that game. A value the game writes later (you got
-- stronger) puts the avatar on again at the new size.
Scale.ValueFields = {{"HeightScale", "BodyHeightScale"}, {"WidthScale", "BodyWidthScale"}, {"DepthScale", "BodyDepthScale"},
    {"HeadScale", "HeadScale"}, {"ProportionScale", "BodyProportionScale"}, {"BodyTypeScale", "BodyTypeScale"}}
Scale.GameValues = setmetatable({}, {__mode = "k"})
-- The description fields the game forces on char (field -> value), or nil. Read from the Humanoid while the copier has
-- not changed the body; kept up to date by the game's own writes after that.
function Scale.gameValues(char)
    if not char or F.getTrueRigType(char) ~= Enum.HumanoidRigType.R15 then return nil end
    if S.TouchedChar ~= char then
        local hum = char:FindFirstChildOfClass("Humanoid")
        local desc = hum and App.liveDescription(hum)
        local forced = {}
        if desc and not desc:GetAttribute("Lyra_Description") then
            for _, row in ipairs(Scale.ValueFields) do
                local value = hum:FindFirstChild(row[2])
                local ok, own = pcall(function() return desc[row[1]] end)
                if value and value:IsA("NumberValue") and ok and type(own) == "number" and math.abs(value.Value - own) > math.max(0.02, math.abs(own) * 0.02) then
                    forced[row[1]] = value.Value
                end
            end
        end
        Scale.GameValues[char] = next(forced) and forced or false
    end
    return Scale.GameValues[char] or nil
end
-- HOLDING THE COPIED SHAPE: the game writes its new values from the server, and the server then rescales your body
-- for your own avatar's shape: on a copied avatar the torso went thin and a leg looked huge until the avatar went on
-- again (a second later, and not at all past four times in half a minute, so while training in Muscle Legends it often
-- stayed so). For a few seconds after the game writes its values, the sizes, joints and HipHeight the copier set are
-- put back the moment the server changes them, and the avatar goes on again with the new values as soon as they
-- settle (at most every 1.5 s, the last change always).
function Scale.holding(char)
    return Scale.GameValues[char] and char == Scale.Character and os.clock() < (Scale.HoldUntil or 0) or false
end
function Scale.holdPart(part)
    local set = part:GetAttribute("Lyra_SetSize")
    if typeof(set) == "Vector3" and (part.Size - set).Magnitude > 1e-4 then pcall(function() part.Size = set end) end
end
function Scale.holdJoint(joint, field)
    local set = joint:GetAttribute("Lyra_Set" .. field)
    if typeof(set) == "CFrame" and not Fit.same(joint[field], set) then pcall(function() joint[field] = set end) end
end
function Scale.holdHip(hum)
    local set = hum:GetAttribute("Lyra_SetHip")
    if type(set) == "number" and math.abs(hum.HipHeight - set) > 1e-4 then pcall(function() hum.HipHeight = set end) end
end
function Scale.hold(char)
    Scale.HoldUntil = os.clock() + 3
    for _, item in ipairs(char:GetDescendants()) do
        if item:IsA("BasePart") and item.Parent == char then Scale.holdPart(item)
        elseif item:IsA("Motor6D") then Scale.holdJoint(item, "C0"); Scale.holdJoint(item, "C1")
        elseif item:IsA("Humanoid") then Scale.holdHip(item) end
    end
end
function Scale.valueChanged(char, field, item)
    if not App.alive() or char ~= Scale.Character then return end
    -- The copier's own writes carry the value it set; anything else is the game's (also while an avatar goes on).
    local set = item:GetAttribute("Lyra_SetScale")
    if type(set) == "number" and math.abs(item.Value - set) < 1e-3 then return end
    local known = Scale.GameValues[char]
    if not known then known = {}; Scale.GameValues[char] = known end
    if known[field] ~= nil and math.abs(known[field] - item.Value) < 1e-3 then return end
    known[field] = item.Value
    if not App.Busy then Scale.hold(char) else Scale.HoldUntil = os.clock() + 3 end
    -- The game writes its values together: the avatar goes on again once they settle, at most every 1.5 s, and a
    -- newer change always gets its own (an older wait gives way to it).
    Scale.ValueSerial = (Scale.ValueSerial or 0) + 1
    local serial = Scale.ValueSerial
    task.spawn(function()
        task.wait(0.4)
        local deadline = os.clock() + 20
        while App.alive() and serial == Scale.ValueSerial and os.clock() < deadline
            and (App.Busy or os.clock() - (Scale.LastValueApply or -math.huge) < 1.5) do task.wait(0.2) end
        if serial ~= Scale.ValueSerial or not App.alive() or App.Busy or char ~= lp.Character or char ~= S.TouchedChar then return end
        if not App.Current or App.Current.Original then return end
        Scale.LastValueApply = os.clock()
        App.devNote("The game wrote new scale values: the avatar goes on again with them.")
        App.applySnapshot(App.Current, "reapply", char)
    end)
end
function Scale.changed(char, part)
    -- The game rescaling your own body after writing its scale values: the copied sizes are held (see GAME SCALE VALUES).
    if part and Scale.holding(char) then Scale.holdPart(part); return end
    if App.Busy or Scale.Pending or not App.alive() or char ~= Scale.Character then return end
    Scale.Pending = true
    -- A resize arrives part by part: it is measured once it has settled.
    task.delay(0.5, function()
        Scale.Pending = false
        if App.alive() and char == Scale.Character then pcall(Scale.check, char, false) end
    end)
end
-- The scale the game has given the body now, relative to the size it had when the copied avatar went on (nil when the
-- game did not resize it evenly), and whether any part was resized by the game.
function Scale.measure(char)
    local ratios, touched = {}, false
    for _, part in ipairs(char:GetChildren()) do
        local before, set = part:GetAttribute("Lyra_GameSize"), part:GetAttribute("Lyra_SetSize")
        if Appearance.isBody(part, char) and typeof(before) == "Vector3" and typeof(set) == "Vector3" and (part.Size - set).Magnitude > 1e-3 then
            touched = true
            local size = part.Size
            local x, y, z = size.X / math.max(before.X, 1e-3), size.Y / math.max(before.Y, 1e-3), size.Z / math.max(before.Z, 1e-3)
            local low, high = math.min(x, y, z), math.max(x, y, z)
            if low > 0.05 and high / low < 1.15 then table.insert(ratios, (x + y + z) / 3) end
        end
    end
    if #ratios == 0 then return nil, touched end
    table.sort(ratios)
    local middle = ratios[math.ceil(#ratios / 2)]
    for _, ratio in ipairs(ratios) do if math.abs(ratio - middle) > middle * 0.1 then return nil, touched end end
    -- Back to the game's own size: exactly 1.
    if math.abs(middle - 1) < 0.02 then middle = 1 end
    return middle, touched
end
-- force: the game rebuilt part of the body or its items along with the size change, so the avatar goes on again even
-- when the scale stays the same.
function Scale.check(char, force)
    if App.Busy or not App.alive() or char ~= lp.Character or char ~= S.TouchedChar or not App.Current or App.Current.Original then return end
    -- A game that sizes the body through its scale values is followed there (see GAME SCALE VALUES).
    if Scale.GameValues[char] then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 or Overlay.visualOnly() then return end
    local measured, touched = Scale.measure(char)
    if not touched and not force then return end
    -- Measured from the size the game had when the copied avatar went on, which may itself be the game's (see GAME SIZE).
    local factor = measured and math.clamp(measured * (Scale.Bases[char] or 1), 0.1, 10) or Scale.Factor
    local now = os.clock()
    for i = #Scale.Reactions, 1, -1 do if now - Scale.Reactions[i] > 30 then table.remove(Scale.Reactions, i) end end
    if #Scale.Reactions >= 4 then return end
    table.insert(Scale.Reactions, now)
    App.devNote(string.format("Game resized the body: scale %.2f -> %.2f", Scale.Factor, factor))
    Scale.Factor = factor
    task.spawn(App.applySnapshot, App.Current, "reapply", char)
end
-- SWAPPED BODIES: some games resize you by putting a whole new body in your place for a while (a giant potion that
-- swaps in a bigger copy of you, then puts your own back). The new body is the game's, so it showed your own avatar,
-- and the copied avatar would have gone on it at its usual size. The scale of a body is read from its
-- HumanoidRootPart, which the copier never reshapes: the copied avatar goes on the new body as much bigger or smaller
-- as its root is than the root of the body it replaced (only while that one is still alive: after a death, a new
-- body is your usual size). Each body keeps the scale its copied avatar was built at, for when it comes back.
Scale.Factors = setmetatable({}, {__mode = "k"})
Scale.Roots = setmetatable({}, {__mode = "k"})
function Scale.rootSize(char)
    local root = char and char:FindFirstChild("HumanoidRootPart")
    return root and root:IsA("BasePart") and root.Size or nil
end
-- How many times bigger size is than base, or nil when it is not resized evenly (or not at all measurable).
function Scale.ratio(size, base)
    if typeof(size) ~= "Vector3" or typeof(base) ~= "Vector3" then return nil end
    local x, y, z = size.X / math.max(base.X, 1e-3), size.Y / math.max(base.Y, 1e-3), size.Z / math.max(base.Z, 1e-3)
    local low, high = math.min(x, y, z), math.max(x, y, z)
    if low <= 0.05 or high / low > 1.15 then return nil end
    local ratio = (x + y + z) / 3
    if math.abs(ratio - 1) < 0.02 then return 1 end
    return ratio
end
-- A new body took over: its scale is worked out from the body it replaced (see SWAPPED BODIES).
function Scale.arrived(char, previous)
    Scale.From = nil
    if Scale.Factors[char] then Scale.Factor = Scale.Factors[char]; return end
    Scale.Factor = 1
    local hum = previous and previous ~= char and previous:FindFirstChildOfClass("Humanoid")
    if hum and hum.Health > 0 and Scale.Factors[previous] and Scale.Roots[previous] then
        Scale.From = {Char = char, Factor = Scale.Factors[previous], Root = Scale.Roots[previous]}
    end
end
-- GAME SIZE: some games make your whole body bigger or smaller than your avatar and keep it so (Muscle Legends grows
-- you with your strength). A copied avatar went on at its own size, so you shrank back to an avatar's size the moment
-- you wore one, and had to raise its height in Body size to stand as tall as before. The size the game gives a body the
-- copier has not changed yet is now measured against your own avatar, by the height of each body part (such a game may
-- leave the root as it was, and widen the body more than it lengthens it), and the copied avatar (or the one drawn
-- over your character) goes on as much bigger or smaller. Every part has to agree and the difference has to be a tenth
-- or more, so a game that gives you another body, has its own character or merely limits avatar scales changes nothing.
Scale.Bases = setmetatable({}, {__mode = "k"})
function Scale.gameFactor(char)
    local rig = F.getTrueRigType(char)
    if not rig then return 1 end
    -- A game that writes its own scale values sizes the avatar through them instead (see GAME SCALE VALUES).
    if Scale.gameValues(char) then return 1 end
    if not (S.ownPartSizes and S.ownPartSizes[rig.Name]) then pcall(F.getSafeAccessoryNames) end
    local own = S.ownPartSizes and S.ownPartSizes[rig.Name]
    if type(own) ~= "table" then return 1 end
    local ratios = {}
    for _, part in ipairs(char:GetChildren()) do
        local size = own[part.Name]
        if part.Name ~= "HumanoidRootPart" and part.Name ~= "Head" and Appearance.isBody(part, char) and typeof(size) == "Vector3" and size.Y > 0.05 then
            table.insert(ratios, part.Size.Y / size.Y)
        end
    end
    if #ratios < 3 then return 1 end
    table.sort(ratios)
    local factor = ratios[math.ceil(#ratios / 2)]
    for _, ratio in ipairs(ratios) do if math.abs(ratio - factor) > factor * 0.12 then return 1 end end
    if math.abs(factor - 1) < 0.1 then return 1 end
    return math.clamp(factor, 0.1, 10)
end
-- The scale the copied avatar takes on char.
function Scale.factorFor(char)
    local from = Scale.From
    if from and from.Char == char then
        local ratio = Scale.ratio(Scale.rootSize(char), from.Root)
        return math.clamp(from.Factor * (ratio or 1), 0.1, 10)
    end
    if char == S.TouchedChar then return Scale.Factor end
    -- A body the game made (see GAME SIZE): later size changes are measured from this one.
    local base = Scale.gameFactor(char)
    Scale.Bases[char] = base
    return base
end
-- The copied avatar went on char at factor.
function Scale.remember(char, factor)
    Scale.Factor = factor; Scale.Factors[char] = factor; Scale.Roots[char] = Scale.rootSize(char)
    if Scale.From and Scale.From.Char == char then Scale.From = nil end
end
-- Gives a freshly built avatar model the game's scale (a copy of the cached model, never the cache itself).
function Scale.apply(model, factor)
    if not model or not factor or math.abs(factor - 1) < 0.01 then return end
    local hum = model:FindFirstChildOfClass("Humanoid")
    local hip = hum and hum.HipHeight
    local ok = pcall(function() model:ScaleTo(model:GetScale() * factor) end)
    -- ScaleTo leaves HipHeight as it was on some versions: it follows the legs.
    if ok and hum and hip and math.abs(hum.HipHeight - hip) < 1e-3 then pcall(function() hum.HipHeight = hip * factor end) end
end

-- SWAP EFFECT
-- A short local glow over the character and a sparkle burst at the moment of the change, so a swap doesn't pop.
-- Created in the camera (never inside the character), so the appearance transaction never touches it.
F.Swap = {Tweens = game:GetService("TweenService"), Color = Color3.fromRGB(188, 167, 246)}
function F.Swap.begin(char)
    if not Store.Settings.SwapEffect or Store.Settings.ReducedMotion or not char then return nil end
    local fx = {}
    pcall(function()
        local glow = Instance.new("Highlight")
        glow.Name = "LyraSwapGlow"; glow.Adornee = char; glow.DepthMode = Enum.HighlightDepthMode.Occluded
        glow.FillColor = F.Swap.Color; glow.OutlineColor = Color3.fromRGB(244, 239, 255)
        glow.FillTransparency = 1; glow.OutlineTransparency = 1
        glow.Parent = workspace.CurrentCamera or workspace
        fx.Glow = glow
        F.Swap.Tweens:Create(glow, TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {FillTransparency = 0.3, OutlineTransparency = 0.1}):Play()
    end)
    return fx
end
function F.Swap.burst(fx, char)
    if not fx or Store.Settings.LowEffects then return end
    pcall(function()
        local root = char:FindFirstChild("HumanoidRootPart"); if not root then return end
        local anchor = Instance.new("Part")
        anchor.Name = "LyraSwapBurst"; anchor.Anchored = true; anchor.CanCollide = false; anchor.CanQuery = false; anchor.CanTouch = false
        anchor.Transparency = 1; anchor.Size = Vector3.new(2, 4, 1); anchor.CFrame = root.CFrame
        local emitter = Instance.new("ParticleEmitter")
        emitter.Texture = "rbxasset://textures/particles/sparkles_main.dds"
        emitter.Color = ColorSequence.new(F.Swap.Color, Color3.fromRGB(255, 255, 255))
        emitter.LightEmission = 1; emitter.Rate = 0; emitter.Lifetime = NumberRange.new(0.5, 0.9)
        emitter.Speed = NumberRange.new(4, 9); emitter.SpreadAngle = Vector2.new(180, 180)
        emitter.Size = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.45), NumberSequenceKeypoint.new(1, 0)})
        emitter.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1)})
        emitter.Parent = anchor
        anchor.Parent = workspace.CurrentCamera or workspace
        emitter:Emit(36)
        task.delay(1.5, function() pcall(function() anchor:Destroy() end) end)
    end)
end
function F.Swap.finish(fx)
    if not fx or not fx.Glow then return end
    local glow = fx.Glow; fx.Glow = nil
    pcall(function() F.Swap.Tweens:Create(glow, TweenInfo.new(0.45, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {FillTransparency = 1, OutlineTransparency = 1}):Play() end)
    task.delay(0.5, function() pcall(function() glow:Destroy() end) end)
end

-- Auto-load and avatar cycle state. Its functions are defined after Looks; declared here so applySnapshot can reach it.
local Auto = {Deaths = 0, DeathsSince = 0, LastSwitch = -math.huge, TimerStart = os.clock(), Pending = nil, Switching = false,
    Bag = {}, Direction = 1, SkipDeath = false, SkipRespawn = false, Rng = Random.new(), OnChange = function() end, OnTick = function() end}

-- One mutation path for apply, undo, restore and respawn on your screen. Previews never enter it (App.applySnapshot
-- decides between this and the game's own outfit menu, see CATALOG AVATAR CREATOR).
-- inPlace: change the character even when visual-only is on (used to take a copied avatar off the character when
-- switching to visual-only).
function App.applyLocal(snapshot, mode, readyChar, inPlace)
    if App.Busy or not App.alive() then return false end
    local char = readyChar or lp.Character
    -- Visual-only draws the avatar over the character and never touches the character itself.
    local visualOnly = Overlay.visualOnly() and not inPlace
    if not char or (not App.captureInitial(char) and not visualOnly) then App.report("Wait for your character to load.", "warning"); return false end
    -- The undo base is your character as the game made it, taken again while the copier has not changed it yet.
    if not visualOnly and S.TouchedChar ~= char and App.charReady(char) then App.captureInitial(char, true) end
    -- "Original" always means the current undo base (older timeline entries point at an earlier capture).
    local requested = snapshot
    if snapshot.Original and not snapshot.GameLook and App.Initial then snapshot = App.Initial end
    -- Read while the character is still the game's (see CUSTOM CHARACTERS): once reshaped, its hidden body shows again.
    local customRig
    if not visualOnly and not snapshot.Original and not App.SuggestedVisual[game.GameId] and S.TouchedChar ~= char
        and App.charReady(char) and os.clock() - (App.SpawnTimes[char] or 0) >= 3 then
        customRig = App.customCharacter(char)
    end
    App.Busy = true; S.applyBusy = true; App.Refresh()
    App.report(mode == "undo" and "Returning to the previous appearance…" or (mode == "restore" or mode == "yield") and "Restoring your own appearance…" or "Preparing the avatar…", "loading")
    local desc, dummy, oldAnchored, anchorPart, oldRequiresNeck, applicationReport, rigNote, rigRebuilt, swapFx, reshaped, prefetch, coveredHere
    local previous = App.Current
    if previous and previous.Original and not previous.GameLook and App.Initial then previous = App.Initial end
    if previous and mode ~= "reapply" then previous.Animations = App.captureAnimations(char) end
    -- A catalog edit keeps the animations being played unless it changed an animation item.
    if (mode == "catalog" or mode == "customize") and previous and not snapshot.ForceAnims and not snapshot.Animations then snapshot.Animations = previous.Animations end
    -- Builds the avatar model, reusing an untouched copy of the last one built for this snapshot and
    -- rig, so reapplying after a respawn skips the slow rebuild.
    local builtFactor = 1
    local function build(rig)
        -- The scale values the game writes for this body (see GAME SCALE VALUES): the avatar is built with them, as the
        -- game would build it, and a skin is rebuilt from its items to take them.
        local values = rig == Enum.HumanoidRigType.R15 and Scale.gameValues(char) or nil
        local valuesKey = ""
        if values then
            local keys = {}
            for field, value in pairs(values) do table.insert(keys, field .. "=" .. string.format("%.3f", value)) end
            table.sort(keys); valuesKey = table.concat(keys, ",")
        end
        -- The game's size for this character (see GAME SIZE CHANGES, SWAPPED BODIES and GAME SIZE); the cached model
        -- always stays at its own size. An avatar drawn over the character takes the size the game gives the body too.
        local factor = values and 1 or visualOnly and Scale.gameFactor(char) or Scale.factorFor(char)
        builtFactor = factor
        local cache = App.ModelCache
        if cache and cache.Snapshot == snapshot and cache.Rig == rig and (cache.Values or "") == valuesKey then
            local cloned, copy = pcall(function() return cache.Model:Clone() end)
            if cloned and copy then Scale.apply(copy, factor); return copy, cache.Note, cache.Rebuilt end
        end
        local source = desc
        if values then
            source = desc:Clone()
            for field, value in pairs(values) do pcall(function() source[field] = value end) end
        end
        local made, model, note, rebuilt = pcall(Visual.model, snapshot.Data, source, rig, values ~= nil)
        if source ~= desc then pcall(function() source:Destroy() end) end
        if not made then error(model, 0) end
        -- The game already put its own accessories on; only body, clothing and colours are rebuilt.
        if snapshot.GameLook then for _, item in ipairs(model:GetChildren()) do if item:IsA("Accessory") then item:Destroy() end end end
        local copied, copy = pcall(function() return model:Clone() end)
        if copied and copy then
            if cache then pcall(function() cache.Model:Destroy() end) end
            App.ModelCache = {Snapshot = snapshot, Rig = rig, Model = copy, Note = note, Rebuilt = rebuilt, Values = valuesKey}
        end
        Scale.apply(model, factor)
        return model, note, rebuilt
    end
    local ok, err = xpcall(function()
        -- Your own look on a character the copier has not changed (or drawn over with visual-only): nothing to rebuild.
        local nothing = snapshot.Original and not snapshot.GameLook and (visualOnly or S.TouchedChar ~= char)
        local rig
        if not nothing then
            assert(type(snapshot.Data) == "table", "This appearance has no avatar data.")
            desc = Codec.decode(snapshot.Data)
            prefetch = App.prefetchAnimations(char, snapshot, desc)
            -- A visual-only avatar can be drawn as R6 or R15 whatever the game's rig is (Settings > VisualRig).
            local chosenRig = visualOnly and Store.Settings.VisualRig ~= "Auto" and Enum.HumanoidRigType[Store.Settings.VisualRig] or nil
            -- Drawn as R15 because the game's R6 body can't show it (see R15 AVATARS IN R6 GAMES).
            if visualOnly and not chosenRig and Overlay.Auto then chosenRig = Enum.HumanoidRigType.R15 end
            -- A custom character with no standard body still gets an overlay (R15); it then follows the root.
            rig = visualOnly and (chosenRig or Overlay.rigType(char) or Enum.HumanoidRigType.R15) or F.getTrueRigType(char)
            assert(rig, "The character rig could not be identified.")
            dummy, rigNote, rigRebuilt = build(rig)
        end
        assert(App.alive(), "Execution ended.")
        if Store.Settings.AutoReset and mode == "apply" and not visualOnly and not nothing then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum and hum.Health > 0 then
                App.report("Waiting for your character to respawn…", "loading")
                -- This respawn is ours: the avatar cycle must not count it as a death.
                Auto.SkipDeath = true; Auto.SkipRespawn = true
                task.delay(15, function() Auto.SkipDeath = false; Auto.SkipRespawn = false end)
                local old = char; hum.Health = 0; local deadline = os.clock() + 12
                repeat
                    task.wait(0.1); char = lp.Character
                    -- The new character stays covered until the avatar is on (see COVER).
                    if char and char ~= old and not coveredHere then coveredHere = char; Cover.begin(char, 15) end
                until not App.alive() or (char and char ~= old and char:FindFirstChild("HumanoidRootPart") and char:FindFirstChildOfClass("Humanoid")) or os.clock() >= deadline
                assert(App.alive(), "Execution ended.")
                if char and char ~= old and char:FindFirstChild("HumanoidRootPart") then
                    local appearanceDeadline = os.clock() + 5
                    while not lp:HasAppearanceLoaded() and os.clock() < appearanceDeadline and App.alive() do task.wait(0.1) end
                    App.waitSettled(char, 5)
                    if F.getTrueRigType(char) ~= rig then
                        dummy:Destroy(); rig = F.getTrueRigType(char); dummy, rigNote, rigRebuilt = build(rig)
                    end
                    -- The fresh character is the game's: it becomes the undo base.
                    App.captureInitial(char, true)
                else
                    -- Round-based games can block or delay respawning. Keep going on the current character when it is still alive.
                    char = lp.Character
                    local liveHum = char and char:FindFirstChildOfClass("Humanoid")
-- YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
                    assert(liveHum and liveHum.Health > 0 and char:FindFirstChild("HumanoidRootPart"),
                        "This game did not respawn your character. Turn off \"Reset character first\" in Settings, wait until you can move, and try again.")
                    App.report("This game blocked the respawn, so the avatar is being applied to your current character…", "loading")
                end
            end
        end
        assert(char == lp.Character and char.Parent and App.alive(), "Your character changed during the operation. Try again.")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if visualOnly then
            -- Some games (Evade) drive the character without a Humanoid: the overlay only needs something to follow.
            assert(not hum or hum.Health > 0, "Wait for your character to respawn.")
            assert(nothing or Overlay.rootOf(char), "Your character has not loaded yet. Wait for it to appear and try again.")
        else
            assert(hum and hum.Health > 0, "Wait for your character to respawn.")
        end
        S.operationSerial = (S.operationSerial or 0) + 1
        -- The drawn avatar also tells your own items and clothes from the game's when the settings keep the game's.
        if visualOnly and not nothing and (Store.Settings.KeepGameItems or Store.Settings.KeepGameClothes) then pcall(F.getSafeAccessoryNames) end
        if not visualOnly and not nothing then
            anchorPart = char:FindFirstChild("HumanoidRootPart"); oldAnchored = anchorPart and anchorPart.Anchored
            oldRequiresNeck = hum.RequiresNeck
            F.ensureOriginalTagsScanned(char)
            F.getSafeAccessoryNames()
            -- A character the game is still building is waited for (catalog games rebuild it on every try-on).
            if not App.waitRig(char, 6) then
                error(mode == "reapply" and "Your character is still loading. The avatar goes back on when it has loaded."
                    or "Your character is not fully loaded yet (some body parts are not connected). Wait a moment and try again.", 0)
            end
        end
        -- The swap glow marks a new avatar; adding or removing one item (shop, Customize) changes it without one.
        if mode ~= "reapply" and mode ~= "catalog" and mode ~= "customize" and not nothing then swapFx = F.Swap.begin(char); if swapFx then task.wait(0.14) end end
        assert(App.alive() and char == lp.Character and char.Parent and (not hum or hum.Health > 0), "Your character changed. Wait and try again.")
        -- The game retains camera/controller ownership during cosmetic application.
        App.report("Applying appearance, clothing, and accessories…", "loading")
        -- The copier is about to change the body itself: it stops following the game's changes to it until it is done.
        Cloak.stop(); Scale.stop()
        if visualOnly then
            -- The game's character is left untouched: the avatar is drawn over it (see SKIN OVERLAY).
            Repair.stop()
            if snapshot.Original then Overlay.clear(char) else Overlay.showLocal(char, dummy) end
            if prefetch then prefetch.wait(2.5) end
            App.visualAnimations(char, not snapshot.Original and desc or nil, snapshot)
        elseif nothing then
            Overlay.clear(char)
        else
            Overlay.clear(char)
            Appearance.checkLiveRig(char)
            App.Dirty = true
            Repair.stop()
            -- From here on this character carries the copier's changes until your own look is fully back.
            S.TouchedChar = char; reshaped = true
            applicationReport = F.aAv(char, dummy, snapshot.Original and {Original = true, KeepAccessories = snapshot.GameLook == true} or nil)
        end
        F.Swap.burst(swapFx, char)
        assert(App.alive() and char == lp.Character and char.Parent, "Your character changed while the avatar was being applied.")
        if reshaped then
            -- The game's description stays on the Humanoid: catalog games keep editing it, and Roblox's emote wheel
            -- plays emotes from it. It is remembered (it tells the game's avatar items apart) and only its emotes change.
            local live = App.liveDescription(hum)
            if live and not live:GetAttribute("Lyra_Description") then
                if S.gameDescription then pcall(function() S.gameDescription:Destroy() end) end
                pcall(function() S.gameDescription = live:Clone() end)
            end
            if not live then
                live = Instance.new("HumanoidDescription"); live.Name = "HumanoidDescription"; live:SetAttribute("Lyra_Description", true); live.Parent = hum
            end
            -- Older versions left their own copy next to the game's description.
            for _, item in ipairs(hum:GetChildren()) do
                if item:IsA("HumanoidDescription") and item ~= live and item:GetAttribute("Lyra_Description") then pcall(function() item:Destroy() end) end
            end
            App.setEmotes(live, desc, snapshot.Original == true)
            if prefetch then prefetch.wait(2.5) end
            -- A new avatar starts from your own animations (see STALE ANIMATIONS). Rows read from this character (a shop
            -- or Customize change, Undo, the timeline, your own look) already say what to keep.
            local ownRows = type(snapshot.Animations) == "table" and App.AnimSource[snapshot.Animations] == char
            local animChanged = false
            if not ownRows and App.Initial then animChanged = App.resetAnimations(char, App.Initial.Animations) end
            if snapshot.Animations then
                animChanged = App.restoreAnimations(char, snapshot, true) or animChanged
            elseif snapshot.Data.Visual and not rigRebuilt then
                animChanged = App.restoreAnimations(char, {Animations = App.skinAnimations(snapshot.Data, desc), Data = snapshot.Data}, true) or animChanged
            elseif Store.Settings.CopyAnims or snapshot.ForceAnims then
                animChanged = F.applyAnimationIdsToAnimate(char, desc) or animChanged
            end
            if animChanged then F.restartAnimate(char, true) end
            -- Existing tag instances were retained by the appearance transaction.
            local currentHead=char:FindFirstChild("Head")
            if currentHead then F.ensureTagsVisible(currentHead) end
        end
        -- Attachments and game links are restored synchronously by the transaction.
        assert(App.alive() and char == lp.Character and char.Parent, "Your character changed before the operation finished.")
        App.Dirty = false
        if mode == "undo" then table.remove(App.History)
        elseif mode ~= "reapply" and previous and previous ~= snapshot then
            -- Jumping back through the timeline moves that entry out of the history instead of duplicating it.
            if mode == "history" then for i = #App.History, 1, -1 do if App.History[i] == snapshot or App.History[i] == requested then table.remove(App.History, i); break end end end
            table.insert(App.History, previous); while #App.History > 12 do table.remove(App.History, 1) end
        end
        App.Current = snapshot
        if dummy then
            if S.cD and S.cD ~= dummy then pcall(function() S.cD:Destroy() end) end
            S.cD = dummy; dummy = nil
        end
        S.cU = snapshot.Id or "SAVED"; S.tN = snapshot.Name or "SavedAvatar"
        if desc then
            if S.customDesc then S.customDesc:Destroy() end
            S.customDesc = desc:Clone()
        end
        S.fvOn = not snapshot.Original; S.hdOn = false
        S.appliedChar = char; S.currentRigType = F.getTrueRigType(char)
        _G.Copier_TargetID = nil
        if reshaped then
            Repair.watch(applicationReport, char)
            -- Your own items the game puts back are set aside again (see RETURNING ITEMS).
            Appearance.watchReturns(char)
            if not snapshot.Original then App.noteKept(char) end
            -- The game hiding or resizing the copied avatar is followed from now on (see GAME INVISIBILITY and GAME SIZE CHANGES).
            if not snapshot.Original then Scale.remember(char, builtFactor); Cloak.watch(char); Scale.watch(char)
            else Scale.Factor = 1; Scale.Factors[char] = nil end
            if snapshot.Original then
                Appearance.releaseGeometry(hum)
                -- Nothing of the copier is left and the game's own pieces are back: the character is the game's again,
                -- so the next avatar takes a fresh undo base from it.
                local leftover = false
                for _, item in ipairs(char:GetChildren()) do if item:GetAttribute("Copier_CopiedItem") then leftover = true; break end end
                if not leftover then S.TouchedChar = nil end
            end
        end
        if oldRequiresNeck ~= nil then hum.RequiresNeck = oldRequiresNeck end
    end, function(e) return tostring(e) end)
    if anchorPart and oldAnchored ~= nil then pcall(function() anchorPart.Anchored = oldAnchored end) end
    if char and oldRequiresNeck ~= nil then pcall(function() char:FindFirstChildOfClass("Humanoid").RequiresNeck = oldRequiresNeck end) end
    pcall(F.unlockCamera); pcall(F.resumeCamScripts)
    F.Swap.finish(swapFx)
    table.clear(S_SafeTools)
    if desc then desc:Destroy() end; if dummy then dummy:Destroy() end
    App.Busy = false; S.applyBusy = false
    -- The new body settles in the next physics steps; a character that was standing is kept on its feet.
    if ok and reshaped then App.guardUpright(char, 2.5) end
    App.trace(string.format("Apply (%s) of %s on %s: %s", tostring(mode), snapshot.Original and "your own look" or ("\"" .. tostring(snapshot.Name) .. "\""),
        App.traceName(char), ok and string.format("done, scale %.2f", builtFactor) or ("failed: " .. tostring(err))))
    if ok then Repair.resume() end
    -- Copies of you in the game (lobby, cutscenes) and your picture follow the new look.
    if ok then task.spawn(Mirror.refresh) end
    -- The picture in the Roblox menu (Esc) is made ready a moment later, so it already shows the new avatar when opened.
    if ok and not snapshot.Original and Store.Settings.MenuAvatar then
        task.delay(1.5, function() if App.alive() and App.Current == snapshot and not App.Busy then pcall(Thumbs.model) end end)
    end
    if ok and not snapshot.Original and Auto.remember(snapshot) then App.persistState() end
    -- Wearing someone from any list also puts them in Recent, so they are easy to find again.
    if ok and mode == "apply" and snapshot.Id and not snapshot.LookKey then
        App.addRecent({Id = snapshot.Id, Name = tostring(snapshot.Name or snapshot.Id), DisplayName = snapshot.DisplayName or snapshot.Name})
    end
    if not ok then
        if applicationReport then for _, row in ipairs(applicationReport.Items or {}) do if row.Template then row.Template:Destroy() end end end
        S.lastError = err; S.operationSerial = (S.operationSerial or 0) + 1; S.fvOn = false; App.report(err .. (App.Dirty and " Use Restore to recover your appearance." or ""), "error") else
        App.report(mode == "undo" and "Previous appearance restored." or mode == "restore" and "Your own appearance is back." or mode == "yield" and "The game changed your avatar, so the copied one came off. Undo puts it back." or mode == "reapply" and "Avatar reapplied." or mode == "catalog" and "Catalog change applied." or mode == "customize" and "Change applied." or mode == "cycle" and ("Avatar cycle: now wearing " .. tostring(snapshot.Name or "the next avatar") .. ".") or mode == "history" and ("Back to " .. (snapshot.Original and "your own appearance" or tostring(snapshot.Name or "that avatar")) .. ".") or mode == "game" and "The game's new look is on. Undo puts the copied avatar back."  or ((char and not visualOnly and F.getTrueRigType(char) ~= Enum.HumanoidRigType.R15) and "Avatar applied. This game does not use an R15 rig, so its own animations were kept." or "Avatar applied. Tap Customize to remove its items or add new ones."), "success")
    end
    if ok and rigNote then
        App.report(rigNote, "warning")
    elseif ok and applicationReport and (#applicationReport.Skipped > 0 or #applicationReport.BodyErrors > 0) then
        App.report("Avatar applied with limitations: " .. tostring(#applicationReport.Skipped + #applicationReport.BodyErrors) .. " unavailable items/body parts in this game.", "warning")
    elseif ok and snapshot.Data and snapshot.Data.Visual and snapshot.Data.Visual.Legacy then
        App.report("Old JSON applied. Attachments were estimated because the backup contains no joints.", "warning")
    end
    if customRig or (not ok and not visualOnly and tostring(err):find("none of the expected body parts", 1, true)) then
        task.delay(1, App.suggestVisualOnly, customRig or "nobody")
    end
    if App.alive() then App.Refresh() end
    return ok
end
-- CATALOG AVATAR CREATOR: every player there may wear any catalog item, and the game's own outfit menu sends the
-- outfit to the server through its CatalogGuiRemote. The copier sends the avatar you apply the same way, so the game
-- itself puts it on your character and everyone in the server sees it, not only you. Undo, Restore, the timeline,
-- shop and Customize changes and the avatar cycle go through the game too. When the game does not take it (no
-- remote, an error, nothing changes on your character), the avatar is applied on your screen as before. Visual-only
-- keeps it on your screen only. Settings > Advanced > "Wear through Catalog Avatar Creator" turns this off.
local CAC = {PlaceId = 7041939546}
CAC.RigidFields = {Hat = "HatAccessory", Hair = "HairAccessory", Face = "FaceAccessory", Neck = "NeckAccessory", Shoulder = "ShouldersAccessory",
    Front = "FrontAccessory", Back = "BackAccessory", Waist = "WaistAccessory", TShirt = "TShirtAccessory", Shirt = "ShirtAccessory",
    Pants = "PantsAccessory", Jacket = "JacketAccessory", Sweater = "SweaterAccessory", Shorts = "ShortsAccessory", LeftShoe = "ShoesAccessory",
    RightShoe = "ShoesAccessory", DressSkirt = "DressSkirtAccessory", Eyebrow = "EyebrowAccessory", Eyelash = "EyelashAccessory"}
function CAC.remote()
    if game.PlaceId ~= CAC.PlaceId then return nil end
    local events = game:GetService("ReplicatedStorage"):FindFirstChild("Events")
    local remote = events and events:FindFirstChild("CatalogGuiRemote")
    return remote and remote:IsA("RemoteFunction") and remote or nil
end
function CAC.enabled() return Store.Settings.GameWear ~= false and CAC.remote() ~= nil end
-- Whether an application goes through the game: not with visual-only, not when the character is changed in place
-- (switching modes), and not for the copier's own reaction to the game changing your avatar.
function CAC.handles(mode, inPlace)
    return not inPlace and mode ~= "game" and mode ~= "yield" and not Overlay.visualOnly() and CAC.enabled()
end
-- The game's outfit format: colours as 0-255 tables, vectors as tagged tables.
function CAC.color(c)
    return {r = math.floor(c.R * 255 + 0.5), g = math.floor(c.G * 255 + 0.5), b = math.floor(c.B * 255 + 0.5), IsRGBTable = true}
end
function CAC.vector(v, default)
    v = typeof(v) == "Vector3" and v or default
    return {X = v.X, Y = v.Y, Z = v.Z, Vector3 = true}
end
function CAC.properties(desc)
    local props = {}
    for _, field in ipairs(Codec.assetFields) do props[field] = tonumber(desc[field]) or 0 end
    for _, field in ipairs(Codec.colorFields) do props[field] = CAC.color(desc[field]) end
    for _, field in ipairs(Codec.scaleFields) do props[field] = tonumber(desc[field]) or 1 end
    local lists, layered, refinements = {}, {}, {}
    for _, field in pairs(CAC.RigidFields) do lists[field] = {} end
    for _, row in ipairs(desc:GetAccessories(true)) do
        local typeName = typeof(row.AccessoryType) == "EnumItem" and row.AccessoryType.Name or tostring(row.AccessoryType or "Unknown")
        if row.IsLayered then
            table.insert(layered, {AssetId = row.AssetId, AccessoryType = typeName, Order = row.Order or 1, IsLayered = true, Puffiness = row.Puffiness or 0.5,
                Position = CAC.vector(row.Position, Vector3.zero), Rotation = CAC.vector(row.Rotation, Vector3.zero), Scale = CAC.vector(row.Scale, Vector3.one)})
        else
            local field = CAC.RigidFields[typeName]
            if field then table.insert(lists[field], tostring(row.AssetId)) end
            -- An item moved, turned or resized (Customize, or the copied avatar's own fitting).
            local ref = {}
            if typeof(row.Position) == "Vector3" and row.Position.Magnitude > 1e-4 then ref.Position = CAC.vector(row.Position) end
            if typeof(row.Rotation) == "Vector3" and row.Rotation.Magnitude > 1e-4 then ref.Rotation = CAC.vector(row.Rotation) end
            if typeof(row.Scale) == "Vector3" and (row.Scale - Vector3.one).Magnitude > 1e-4 then ref.Scale = CAC.vector(row.Scale) end
            if next(ref) then refinements[tostring(row.AssetId)] = ref end
        end
    end
    for field, ids in pairs(lists) do props[field] = table.concat(ids, ",") end
    props.LayeredAccessories = layered
    props.AccessoryRefinements = refinements
    local makeup = {}
    for _, item in ipairs(desc:GetChildren()) do
        if item.ClassName == "MakeupDescription" and tonumber(item.AssetId) and item.AssetId > 0 then
            table.insert(makeup, {AssetId = item.AssetId, MakeupType = item.MakeupType.Name, Order = item.Order})
        end
    end
    props.MakeupItems = makeup
    local headShape = ""
    pcall(function()
        for _, item in ipairs(desc:GetChildren()) do
            if item.ClassName == "BodyPartDescription" and item.BodyPart == Enum.BodyPart.Head and type(item.HeadShape) == "string" then headShape = item.HeadShape; break end
        end
    end)
    props.HeadShape = headShape
    local okFacial, facial = pcall(function() return desc.StaticFacialAnimation end)
    props.StaticFacialAnimation = okFacial and facial == true
    return props
end
-- What an outfit is made of (clothing, face, body parts and accessories), to see when the game has put it on.
function CAC.key(desc)
    local parts = {}
    local ok = pcall(function()
        for _, field in ipairs({"Shirt", "Pants", "GraphicTShirt", "Face", "Head", "Torso", "LeftArm", "RightArm", "LeftLeg", "RightLeg"}) do
            table.insert(parts, tostring(tonumber(desc[field]) or 0))
        end
        local ids = {}
        for _, row in ipairs(desc:GetAccessories(true)) do table.insert(ids, tostring(row.AssetId)) end
        table.sort(ids)
        table.insert(parts, table.concat(ids, ","))
    end)
    return ok and table.concat(parts, "|") or nil
end
-- The key of the outfit the game has on your character right now.
function CAC.liveKey()
    local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
    local live = hum and App.liveDescription(hum)
    return live and not live:GetAttribute("Lyra_Description") and CAC.key(live) or nil
end
-- Yields until the game has put the outfit on: "full" when it matches, "partial" when the game changed your outfit
-- and kept it that way (it leaves out items it does not allow), nil when nothing changed.
-- failed: tells when the game refused the outfit, so there is no need to wait any longer.
function CAC.wait(wanted, before, timeout, failed)
    local deadline = os.clock() + (timeout or 8)
    local changedAt, lastKey
    while os.clock() < deadline and App.alive() do
        if failed and failed() then break end
        local key = CAC.liveKey()
        if key and key == wanted then return "full" end
        if key and key ~= before then
            if key ~= lastKey then lastKey = key; changedAt = os.clock()
            elseif os.clock() - changedAt >= 1.5 then return "partial" end
        end
        task.wait(0.2)
    end
    return lastKey and "partial" or nil
end
-- Puts a snapshot on through the game. Falls back to applying it on your screen when the game does not take it.
function App.serverWear(requested, mode, readyChar)
    if App.Busy or not App.alive() then return false end
    local char = readyChar or lp.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then App.report("Wait for your character to respawn.", "warning"); return false end
    local current = App.Current
    -- The undo base is your own outfit: taken again unless what you wear is the outfit the copier sent.
    local sentOn = current and current.Server and current.ServerKey ~= nil and CAC.liveKey() == current.ServerKey
    if not sentOn and S.TouchedChar ~= char and App.charReady(char) then App.captureInitial(char, true) end
    local snapshot = requested
    if snapshot.Original and not snapshot.GameLook and App.Initial then snapshot = App.Initial end
    if type(snapshot.Data) ~= "table" then return App.applyLocal(requested, mode, readyChar) end
    local decoded, desc = pcall(Codec.decode, snapshot.Data)
    if not decoded then return App.applyLocal(requested, mode, readyChar) end
    local wanted = CAC.key(desc)
    -- Already on (after a respawn the game keeps the outfit it was sent): nothing to send.
    if mode == "reapply" and wanted and CAC.liveKey() == wanted then
        desc:Destroy(); S.appliedChar = char
        return true
    end
    -- A copy drawn on this character on your screen only comes off first, so the game's outfit is all that shows.
    if S.TouchedChar == char and App.Initial then
        local kept = #App.History
        App.applyLocal(App.Initial, "restore", char)
        while #App.History > kept do table.remove(App.History) end
        App.Current = current
    end
    if App.Busy or not App.alive() then desc:Destroy(); return false end
    -- Your own outfit that is already on needs nothing from the game.
    local already = snapshot.Original and wanted ~= nil and CAC.liveKey() == wanted
    App.Busy = true; S.applyBusy = true; App.Refresh()
    App.report(snapshot.Original and "Putting your own outfit back on through the game…" or "Putting the avatar on through the game, so everyone sees it…", "loading")
    local before = CAC.liveKey()
    local rig = F.getTrueRigType(char) or hum.RigType
    local result = already and "full" or nil
    local built, props = pcall(CAC.properties, desc)
    if built and not already then
        -- Sent on its own thread: a game that never answers cannot leave the copier waiting. What counts is what the
        -- game then puts on your character.
        local remote, refused = CAC.remote(), false
        task.spawn(function()
            local sent = pcall(function()
                remote:InvokeServer({Properties = props, Action = "CreateAndWearHumanoidDescription", RigType = rig})
            end)
            if not sent then refused = true end
        end)
        result = CAC.wait(wanted, before, 8, function() return refused end)
    end
    App.Busy = false; S.applyBusy = false
    if not result then
        desc:Destroy()
        if not App.alive() then return false end
        App.report("The game did not take the avatar, so it is put on for you only.", "warning")
        return App.applyLocal(requested, mode, readyChar)
    end
    local newChar = lp.Character
    local newHum = newChar and newChar:FindFirstChildOfClass("Humanoid")
    local live = newHum and App.liveDescription(newHum)
    -- Emotes are not part of the game's outfit: the emote wheel gets the avatar's emotes on your screen.
    if live then App.setEmotes(live, desc, snapshot.Original == true) end
    local previous = App.Current
    if previous and previous.Original and not previous.GameLook and App.Initial then previous = App.Initial end
    if mode == "undo" then table.remove(App.History)
    elseif mode ~= "reapply" and previous and previous ~= snapshot then
        if mode == "history" then for i = #App.History, 1, -1 do if App.History[i] == snapshot or App.History[i] == requested then table.remove(App.History, i); break end end end
        table.insert(App.History, previous); while #App.History > 12 do table.remove(App.History, 1) end
    end
    snapshot.Server = not snapshot.Original or nil
    snapshot.ServerKey = CAC.liveKey()
    App.Current = snapshot
    S.cU = snapshot.Id or "SAVED"; S.tN = snapshot.Name or "SavedAvatar"
    if S.customDesc then pcall(function() S.customDesc:Destroy() end) end
    S.customDesc = desc
    S.fvOn = false; S.hdOn = false; S.appliedChar = newChar
    S.operationSerial = (S.operationSerial or 0) + 1
    task.spawn(Mirror.refresh)
    if not snapshot.Original and Auto.remember(snapshot) then App.persistState() end
    if mode == "apply" and snapshot.Id and not snapshot.LookKey then
        App.addRecent({Id = snapshot.Id, Name = tostring(snapshot.Name or snapshot.Id), DisplayName = snapshot.DisplayName or snapshot.Name})
    end
    App.report(snapshot.Original and "Your own outfit is back on." or result == "full" and "Avatar on through the game: everyone in this server sees it."
        or "Avatar on through the game. The game left out the items it does not allow.", "success")
    App.Refresh()
    return true
end
-- Every application, undo, restore and respawn goes through here: through the game in Catalog Avatar Creator, else
-- on your character (or drawn over it with visual-only).
-- R15 AVATARS IN R6 GAMES: Roblox can't put layered clothing (jackets, shirts, pants, shoes made to wrap the body) on
-- an R6 body, and a skin saved on R15 keeps its exact look only on R15. Worn on an R6 character (A Bizarre Run and
-- other R6 games), such an avatar came out as plain blocks with only its hair and hats. It is now drawn as R15 over
-- the character (visual-only, see SKIN OVERLAY), which follows the character's moves, tools and the game's own
-- animations. This stays on for the game until the script closes; the notice it shows can put avatars back on the R6
-- body instead, and turning Visual-only off in Settings does too.
Overlay.AutoDeclined = {}
-- Whether an avatar only shows right on R15: layered clothing, or a skin saved on R15.
function App.wantsR15(data)
    if type(data) ~= "table" then return false end
    if type(data.Visual) == "table" and data.Visual.RigType == "R15" then return true end
    for _, row in ipairs(type(data.Accessories) == "table" and data.Accessories or {}) do
        if type(row) == "table" and row.IsLayered == true then return true end
    end
    return false
end
-- Turns R15 drawing on for this game before snapshot goes on char, when it needs it. Yields (the character first gets
-- its own body back when the copier had reshaped it).
function App.autoR15(snapshot, mode, char)
    if Overlay.Auto or Overlay.visualOnly() or Overlay.AutoDeclined[game.GameId] or Overlay.BodyGames[game.GameId] or App.Busy then return end
    if type(snapshot) ~= "table" or snapshot.Original or not App.wantsR15(snapshot.Data) then return end
    if Store.Settings.VisualRig == "R6" then return end
    if not char or F.getTrueRigType(char) ~= Enum.HumanoidRigType.R6 then return end
--[==[YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU]==]
    -- Nothing of the copier may stay on the R6 body under the drawn avatar: it gets its own look back first, and the
    -- timeline is left as it was (the avatar worn until now stays the one Undo goes back to).
    if S.TouchedChar == char and App.Initial then
        local current, history = App.Current, #App.History
        if not App.applyLocal(App.Initial, "restore", char, true) then return end
        while #App.History > history do table.remove(App.History) end
        App.Current = current
    end
    Overlay.Auto = true
    App.devNote("This avatar needs R15 (layered clothing or a skin saved on R15) and this game's character is R6: drawn over it as R15.")
    App.toast({Title = "Drawn as R15 in this game", Kind = "info", Icon = "eye", Duration = 12,
        Text = "This game uses R6 bodies, which can't show layered clothing, so the avatar is drawn as R15 over your character. Only you see it, as always.",
        Action = {Text = "Use the R6 body", Callback = function()
            if not App.alive() or not Overlay.Auto then return end
            Overlay.Auto = false; Overlay.AutoDeclined[game.GameId] = true
            -- The notice shows while the avatar is still being drawn: a tap then waits for it to finish, instead of
            -- leaving it drawn over the character with the R6 body already chosen.
            task.spawn(function()
                local deadline = os.clock() + 20
                repeat task.wait(0.1) until not App.Busy or not App.alive() or os.clock() > deadline
                if App.alive() and not App.Busy then App.switchVisualOnly(false) end
            end)
        end}})
end
function App.applySnapshot(snapshot, mode, readyChar, inPlace)
    -- The item adjustments kept for this avatar go on with it (see SAVED ADJUSTMENTS).
    Tweaks.attach(snapshot)
    if not inPlace and not CAC.handles(mode, inPlace) then pcall(App.autoR15, snapshot, mode, readyChar or lp.Character) end
    local ok
    if CAC.handles(mode, inPlace) then ok = App.serverWear(snapshot, mode, readyChar)
    else ok = App.applyLocal(snapshot, mode, readyChar, inPlace) end
    -- The avatar is on: your character shows again (see COVER).
    if ok then Cover.finish(readyChar or lp.Character) end
    return ok
end
-- Yields. Builds the avatar model of a snapshot ahead of time (Auto-load builds it while the window is being made), so
-- applying it only copies the model. Nothing happens when a model is already cached.
function App.prebuild(snapshot, rig)
    if App.ModelCache or App.Busy or type(snapshot) ~= "table" or type(snapshot.Data) ~= "table" or not rig then return end
    local desc = Codec.decode(snapshot.Data)
    local ok, model, note, rebuilt = pcall(Visual.model, snapshot.Data, desc, rig)
    pcall(function() desc:Destroy() end)
    if not ok or not model then return end
    if App.ModelCache or not App.alive() then pcall(function() model:Destroy() end); return end
    App.ModelCache = {Snapshot = snapshot, Rig = rig, Model = model, Note = note, Rebuilt = rebuilt}
end
function App.applyPreview()
    if not App.Preview or App.Busy then return end
    local profile = App.Preview
    local snapshot = {Data = profile.SnapshotData or Codec.encode(profile.Description), Id = profile.Id, Name = profile.Name, LookKey = profile.LookKey}
    -- What a player wears in this game is not their profile: it keeps their picture but not their id.
    if profile.Live then snapshot.Id = nil; snapshot.ThumbId = profile.Id; snapshot.Name = tostring(profile.Name) .. " (in game)" end
    task.spawn(App.applySnapshot, snapshot, "apply")
end
function App.undo()
    if #App.History > 0 and not App.Busy then task.spawn(App.applySnapshot, App.History[#App.History], "undo") end
end
-- Timeline: go straight back to any earlier appearance of this session.
function App.jump(snapshot)
    if not snapshot or snapshot == App.Current or App.Busy then return end
    task.spawn(App.applySnapshot, snapshot, "history")
end
-- One-tap wear from a list (Server, Favorites, Recent) without opening the 3D preview first.
function App.wearProfile(profile)
    if not profile or App.Busy then return end
    App.report("Loading " .. tostring(profile.DisplayName or profile.Name) .. "…", "loading")
    task.spawn(function()
        local ok, resolved, err = pcall(App.resolve, tostring(profile.Id or profile.Name), App.alive)
        if not ok then err = tostring(resolved); resolved = nil end
        if not resolved then if err ~= "cancelled" then App.report(err or "This profile is unavailable.", "error") end; return end
        App.applySnapshot({Data = Codec.encode(resolved.Description), Id = resolved.Id, Name = resolved.Name}, "apply")
    end)
end
function App.restore()
    if App.Initial and not App.Busy then task.spawn(App.applySnapshot, App.Initial, "restore") end
end
-- Switching between changing the character and drawing over it while an avatar is on (Store.Settings.VisualOnly is
-- already the new value): the character first gets your own look back, or the overlay comes off, then the same
-- avatar goes on the new way. Nothing is left of the old way.
function App.switchVisualOnly(on)
    if Overlay.BodyGames[game.GameId] then App.report("Visual-only is always off in this game.", "info"); return end
    local current, char = App.Current, lp.Character
    -- Turning it off also ends the drawing an R6 game turned on by itself (see R15 AVATARS IN R6 GAMES).
    if not on and Overlay.Auto then Overlay.Auto = false; Overlay.AutoDeclined[game.GameId] = true end
    if App.Busy or not App.alive() or not current or current.Original or not char or game.GameId == Overlay.EvadeGame then
        App.report("Applies the next time you wear an avatar.", "info"); return
    end
    task.spawn(function()
        local restored = false
        if on and S.TouchedChar == char and App.Initial then
            restored = App.applySnapshot(App.Initial, "restore", char, true)
            if not restored then return end
        elseif not on then
            Overlay.clear(char)
        end
        -- After a restore the copied avatar is the newest timeline entry: "undo" puts it back and takes it out again.
        App.applySnapshot(current, restored and "undo" or "reapply", char)
    end)
end
-- Clean reset: respawns your character so the game builds it again with its own avatar, with nothing of the copier
-- left on it. The copied avatar stays in the timeline. With visual-only the character was never changed, so the
-- overlay simply comes off.
function App.cleanReset()
    if App.Busy or App.CleanReset or not App.alive() then return end
    local char = lp.Character
    if Overlay.visualOnly() then App.restore(); return end
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then App.report("Wait for your character to respawn.", "warning"); return end
    App.CleanReset = true; App.Refresh()
    App.report("Respawning with the game's avatar…", "loading")
    task.spawn(function()
        -- This respawn is ours: the avatar cycle must not count it, and the copied avatar must not go back on.
        Auto.SkipDeath = true; Auto.SkipRespawn = true
        task.delay(15, function() Auto.SkipDeath = false; Auto.SkipRespawn = false end)
        Repair.stop()
        pcall(function() hum.Health = 0 end)
        local deadline, fresh = os.clock() + 15, nil
        repeat task.wait(0.2); fresh = lp.Character until not App.alive() or (fresh and fresh ~= char and fresh.Parent) or os.clock() >= deadline
        if not App.alive() then return end
        if fresh and fresh ~= char then
            if App.Current and not App.Current.Original then
                table.insert(App.History, App.Current); while #App.History > 12 do table.remove(App.History, 1) end
            end
            S.fvOn = false; S.TouchedChar = nil; S.appliedChar = fresh
            Appearance.Stash[char] = nil
            -- The new character is the game's: it becomes the undo base once it has loaded.
            local loaded = os.clock() + 6
            while not lp:HasAppearanceLoaded() and os.clock() < loaded and App.alive() do task.wait(0.15) end
            fresh:WaitForChild("HumanoidRootPart", 5)
            App.captureInitial(fresh, true)
            App.Current = App.Initial
            App.CleanReset = false
            App.report("Your character respawned with the game's avatar. The copied one is in the timeline.", "success")
        else
            App.CleanReset = false
            App.report("This game did not respawn your character. Use Restore instead.", "warning")
        end
        App.Refresh()
    end)
end

