    Faces = {Assets = {"Face", "EyebrowAccessory", "EyelashAccessory", "FaceMakeup", "LipMakeup", "EyeMakeup"}},
    Animations = {Bundles = {"Animations"}},
    Emotes = {Assets = {"EmoteAnimation"}},
    Gear = {Assets = {"Gear"}},
    Backgrounds = {Assets = {"AvatarBackground"}},
}
-- Second level for the two broad groups, so a player can go straight to classic shirts, pants or T-shirts, or to
-- one kind of accessory.
Catalog.Subs = {
    Clothing = {"All", "Shirts", "Pants", "T-Shirts", "Layered"},
    Accessories = {"All", "Face", "Neck", "Shoulder", "Front", "Back", "Waist"},
}
Catalog.SubLabels = {Shirts = "Classic shirts", Pants = "Classic pants", ["T-Shirts"] = "Classic T-shirts", Layered = "Layered clothing"}
Catalog.SubCategories = {
    ["Clothing/Shirts"] = {Assets = {"Shirt"}}, ["Clothing/Pants"] = {Assets = {"Pants"}}, ["Clothing/T-Shirts"] = {Assets = {"TShirt"}},
    ["Clothing/Layered"] = {Assets = {"TShirtAccessory", "ShirtAccessory", "PantsAccessory", "JacketAccessory", "SweaterAccessory",
        "ShortsAccessory", "DressSkirtAccessory", "LeftShoeAccessory", "RightShoeAccessory"}},
    ["Accessories/Face"] = {Assets = {"FaceAccessory"}}, ["Accessories/Neck"] = {Assets = {"NeckAccessory"}},
    ["Accessories/Shoulder"] = {Assets = {"ShoulderAccessory"}}, ["Accessories/Front"] = {Assets = {"FrontAccessory"}},
    ["Accessories/Back"] = {Assets = {"BackAccessory"}}, ["Accessories/Waist"] = {Assets = {"WaistAccessory"}},
}
function Catalog.filterFor(query)
    local sub = query.Sub and query.Sub ~= "All" and Catalog.SubCategories[tostring(query.Category) .. "/" .. query.Sub]
    return sub or Catalog.Categories[query.Category] or Catalog.Categories.All
end
-- Roblox's own sort and price filters. Popular (most favorited of all time) is the default, so a
-- search such as "korblox" or "headless" leads with the original, most wanted item.
Catalog.Sorts = {
    {Value = "Popular", Label = "Most popular", Enum = {"MostFavorited"}, Web = 1, AllTime = true},
    {Value = "BestSelling", Label = "Best selling", Enum = {"Bestselling", "BestSelling"}, Web = 2, AllTime = true},
    {Value = "Relevance", Label = "Best match", Enum = {"Relevance"}, Web = 0},
    {Value = "Newest", Label = "Newest", Enum = {"RecentlyCreated", "RecentlyUpdated"}, Web = 3},
    {Value = "PriceLow", Label = "Price: low to high", Enum = {"PriceLowToHigh"}, Web = 4},
    {Value = "PriceHigh", Label = "Price: high to low", Enum = {"PriceHighToLow"}, Web = 5},
}
Catalog.Prices = {
    {Value = "Any", Label = "Any price"},
    {Value = "ForSale", Label = "For sale only", ForSale = true},
    {Value = "Free", Label = "Free", Min = 0, Max = 0, ForSale = true},
    {Value = "Low", Label = "Up to R$ 100", Min = 1, Max = 100, ForSale = true},
    {Value = "Mid", Label = "R$ 100 to 1,000", Min = 100, Max = 1000, ForSale = true},
    {Value = "High", Label = "R$ 1,000 and up", Min = 1000, ForSale = true},
}
function Catalog.option(list, value)
    for _, row in ipairs(list) do if row.Value == value then return row end end
    return list[1]
end
-- Accepts a type id, an Enum item or a type name (as the search and GetProductInfo return them).
function Catalog.kind(value)
    if typeof(value) == "EnumItem" then value = value.Name end
    if type(value) == "string" and tonumber(value) then value = tonumber(value) end
    if type(value) == "number" then return Catalog.Types[value] end
    if type(value) == "string" then return Catalog.ByName[(value:lower():gsub("[%s_]", ""))] end
end
function Catalog.bundleKind(value)
    if typeof(value) == "EnumItem" then return value.Name end
    if type(value) == "string" and tonumber(value) then value = tonumber(value) end
    if type(value) == "number" then return Catalog.BundleKinds[value] end
    if type(value) == "string" then return value end
end
-- Yields. Product info is cached per session.
function Catalog.info(id)
    local cached = Catalog.Info[id]
    if cached ~= nil then return cached or nil end
    local ok, info = pcall(function() return MPS:GetProductInfo(id, Enum.InfoType.Asset) end)
    Catalog.Info[id] = ok and type(info) == "table" and info or false
    return Catalog.Info[id] or nil
end
function Catalog.normalize(raw)
    if type(raw) ~= "table" then return nil end
    local id = Codec.id(raw.Id or raw.id)
    if not id then return nil end
    local item = {Id = id, Name = tostring(raw.Name or raw.name or ("Item " .. id)), Creator = raw.CreatorName or raw.creatorName,
        Price = tonumber(raw.Price or raw.price or raw.LowestPrice or raw.lowestPrice)}
    local status = tostring(raw.PriceStatus or raw.priceStatus or ""):lower()
    item.OffSale = raw.IsOffSale == true or raw.isOffSale == true or status:find("off") ~= nil
    -- Limited, Limited U and collectible items. Unknown (nil) when the answer has no restrictions list.
    local restrictions = raw.ItemRestrictions or raw.itemRestrictions
    if type(restrictions) == "table" then
        item.Limited = false
        for _, value in ipairs(restrictions) do
            local name = tostring(value):lower()
            if name:find("limited") or name:find("collectible") then item.Limited = true; break end
        end
    end
    if tostring(raw.ItemType or raw.itemType or "Asset"):lower():find("bundle") then
        item.Bundle = true; item.BundleKind = Catalog.bundleKind(raw.BundleType or raw.bundleType)
    else
        -- A known type that has no place on an avatar (gear, emotes…) is shown but cannot be added.
        local assetType = raw.AssetType or raw.assetType
        item.Kind = Catalog.kind(assetType)
        item.Unwearable = assetType ~= nil and item.Kind == nil
    end
    return item
end
function Catalog.accepts(item, filter)
    if not filter.Assets and not filter.Bundles then return true end
    if item.Bundle then return filter.Bundles ~= nil and table.find(filter.Bundles, item.BundleKind) ~= nil end
    return filter.Assets ~= nil and item.Kind ~= nil and table.find(filter.Assets, item.Kind.Name) ~= nil
end
-- The search already filters by price; this guards the web fallback and items without a price.
function Catalog.priced(item, price)
    if item.Bundle and not price.Min and not price.Max then return not (price.ForSale and item.OffSale) end
    if price.ForSale and item.OffSale then return false end
    if price.Min or price.Max then
        if not item.Price then return false end
        if price.Min and item.Price < price.Min then return false end
        if price.Max and item.Price > price.Max then return false end
    end
    return true
end
function Catalog.read(list, query)
    local items = {}
    local price, filter = Catalog.option(Catalog.Prices, query.Price), Catalog.filterFor(query)
    for _, raw in ipairs(type(list) == "table" and list or {}) do
        local item = Catalog.normalize(raw)
        if item and Catalog.accepts(item, filter) and Catalog.priced(item, price) and not (filter.Limited and item.Limited == false) then table.insert(items, item) end
    end
    return items
end
function Catalog.params(query)
    local params = CatalogSearchParams.new()
    params.SearchKeyword = query.Keyword
    local filter = Catalog.filterFor(query)
    local function enums(enum, names)
        local list = {}
        for _, name in ipairs(names) do local ok, item = pcall(function() return enum[name] end); if ok and item then table.insert(list, item) end end
        return list
    end
    if filter.Assets then params.AssetTypes = enums(Enum.AvatarAssetType, filter.Assets) end
    if filter.Bundles then params.BundleTypes = enums(Enum.BundleType, filter.Bundles) end
    if filter.Limited then pcall(function() params.SalesTypeFilter = Enum.SalesTypeFilter.Collectibles end) end
    local sort, price = Catalog.option(Catalog.Sorts, query.Sort), Catalog.option(Catalog.Prices, query.Price)
    for _, name in ipairs(sort.Enum) do
        local ok, item = pcall(function() return Enum.CatalogSortType[name] end)
        if ok and item then pcall(function() params.SortType = item end); break end
    end
    if sort.AllTime then pcall(function() params.SortAggregation = Enum.CatalogSortAggregation.AllTime end) end
    -- Off-sale items still load on a local avatar, so they are included unless a price filter is set.
    pcall(function() params.IncludeOffSale = not price.ForSale end)
    if price.Min then pcall(function() params.MinPrice = price.Min end) end
    if price.Max then pcall(function() params.MaxPrice = price.Max end) end
    return params
end
-- Executor HTTP fallback for games where the in-game catalog search is unavailable.
function Catalog.web(query)
    local sort, price = Catalog.option(Catalog.Sorts, query.Sort), Catalog.option(Catalog.Prices, query.Price)
    local url = "https://catalog.roblox.com/v1/search/items/details?Limit=30&SortType=" .. sort.Web .. (sort.AllTime and "&SortAggregation=5" or "")
        .. "&IncludeNotForSale=" .. (price.ForSale and "false" or "true") .. "&Keyword=" .. HttpService:UrlEncode(query.Keyword)
    if price.Min then url = url .. "&MinPrice=" .. price.Min end
    if price.Max then url = url .. "&MaxPrice=" .. price.Max end
    if Catalog.filterFor(query).Limited then url = url .. "&SalesTypeFilter=2" end
    if query.Cursor then url = url .. "&Cursor=" .. HttpService:UrlEncode(query.Cursor) end
    local ok, body = pcall(function() return game:HttpGet(url) end)
    assert(ok and type(body) == "string", "The catalog is unavailable right now. Try again in a moment.")
    local decoded, data = pcall(function() return HttpService:JSONDecode(body) end)
    assert(decoded and type(data) == "table" and type(data.data) == "table", "The catalog returned an unexpected answer.")
    query.Cursor = type(data.nextPageCursor) == "string" and data.nextPageCursor ~= "" and data.nextPageCursor or nil
    query.Finished = query.Cursor == nil
    return Catalog.read(data.data, query)
end
-- An item ID, or a catalog / bundle link, typed in the search box: (id, "Asset" | "Bundle" | nil when unknown).
function Catalog.idFrom(keyword)
    local text, kind = tostring(keyword):lower(), nil
    local id = text:match("/catalog/(%d+)")
    if id then kind = "Asset" else
        id = text:match("/bundles/(%d+)")
        if id then kind = "Bundle" else id = text:match("^#?(%d+)$") end
    end
    id = Codec.id(id)
    if not id then return nil end
    return id, kind
end
-- Yields. The exact item with that ID. A bare number is tried as an item first and as a bundle when it is not a
-- wearable item (item and bundle IDs overlap).
function Catalog.byId(id, kind)
    local asset
    if kind ~= "Bundle" then
        local info = Catalog.info(id)
        if info and info.AssetTypeId then
            asset = Catalog.normalize({Id = id, Name = info.Name, AssetType = info.AssetTypeId, Price = info.IsForSale and info.PriceInRobux or nil,
                IsOffSale = info.IsForSale == false, CreatorName = type(info.Creator) == "table" and info.Creator.Name or nil,
                ItemRestrictions = (info.IsLimited or info.IsLimitedUnique or info.CollectibleItemId) and {"Limited"} or {}})
            if asset and not asset.Unwearable then return asset end
        end
    end
    if kind ~= "Asset" then
        local ok, details = pcall(function() return Catalog.Assets:GetBundleDetailsAsync(id) end)
        if ok and type(details) == "table" and details.Name then
            return Catalog.normalize({Id = id, Name = details.Name, ItemType = "Bundle", BundleType = details.BundleType})
        end
    end
    return asset
end
-- Yields. query = {Keyword, Category, Sort, Price}; it keeps the paging state, so "more" continues the same search.
function Catalog.search(query, more)
    if not more then
        local id, kind = Catalog.idFrom(query.Keyword)
        if id then
            query.Finished = true
            local item = Catalog.byId(id, kind)
            assert(item, "No catalog item or bundle was found with the ID " .. tostring(id) .. ".")
            return {item}
        end
    end
    if more then
        assert(not query.Finished, "There are no more results.")
        if query.Pages then
            query.Pages:AdvanceToNextPageAsync(); query.Finished = query.Pages.IsFinished
            return Catalog.read(query.Pages:GetCurrentPage(), query)
        end
        return Catalog.web(query)
    end
    local ok, pages = pcall(function() return Catalog.AvatarEditor:SearchCatalog(Catalog.params(query)) end)
    if ok and pages then
        query.Pages = pages; query.Finished = pages.IsFinished
        return Catalog.read(pages:GetCurrentPage(), query)
    end
    warn("[Lyra Catalog] In-game search unavailable, using the web catalog: " .. tostring(pages))
    return Catalog.web(query)
end
-- Yields. A bundle's assets with their types, body parts first (head, torso, arms, legs).
function Catalog.bundle(id)
    if Catalog.Bundles[id] then return Catalog.Bundles[id] end
    local ok, details = pcall(function() return Catalog.Assets:GetBundleDetailsAsync(id) end)
    assert(ok and type(details) == "table" and type(details.Items) == "table", "This bundle could not be loaded. Try again.")
    local parts, pending = {}, 0
    for _, entry in ipairs(details.Items) do
        local assetId = Codec.id(entry.Id)
        if assetId and tostring(entry.Type) == "Asset" then
            local part = {Id = assetId, Name = tostring(entry.Name or ("Item " .. assetId))}
            table.insert(parts, part); pending = pending + 1
            task.spawn(function()
                local info = Catalog.info(assetId)
                part.Kind = info and Catalog.kind(info.AssetTypeId)
                pending = pending - 1
            end)
        end
    end
    local deadline = os.clock() + 15
    while pending > 0 and os.clock() < deadline and App.alive() do task.wait(0.05) end
    for _, part in ipairs(parts) do
        if not part.Kind then
            -- Names such as "Robloxian 2.0 - Left Arm" still identify a limb when product info fails.
            local name = part.Name:lower()
            for typeId, pattern in pairs({[29] = "left arm", [28] = "right arm", [30] = "left leg", [31] = "right leg", [27] = "torso", [17] = "head"}) do
                if name:find(pattern, 1, true) then part.Kind = Catalog.Types[typeId]; break end
            end
        end
    end
    table.sort(parts, function(a, b)
        local ra, rb = a.Kind and a.Kind.Rank or 99, b.Kind and b.Kind.Rank or 99
        if ra ~= rb then return ra < rb end
        return a.Id < b.Id
    end)
    local bundle = {Id = id, Name = tostring(details.Name or ("Bundle " .. id)), Parts = parts}
    Catalog.Bundles[id] = bundle
    return bundle
end
-- The snapshot being worn: the last applied one, or the appearance the script started with.
function Catalog.base()
    if not App.Current and not App.Initial then App.captureInitial(lp.Character) end
    return App.Current or App.Initial
end
-- The same, for an edit: while your own look is on and the copier has not changed your character, your look is taken
-- again first (a catalog game may have changed it since), so the edit starts from what you really wear.
function Catalog.freshBase()
    local char = lp.Character
    if (not App.Current or App.Current.Original) and not Overlay.visualOnly() and char and S.TouchedChar ~= char and App.charReady(char) then
        App.captureInitial(char, true)
    end
    return Catalog.base()
end
-- Asset id -> {Field = description field} or {Accessory = type name} for everything in the worn snapshot.
function Catalog.worn()
    local snapshot = Catalog.base()
    if Catalog.WornFor == snapshot and Catalog.WornSetKey == Store.Settings.EmoteSet and Catalog.WornSet then return Catalog.WornSet end
    local set = {}
    local data = snapshot and snapshot.Data
    if type(data) == "table" then
        local props = data.Version == 2 and data.Properties or data
        if type(props) == "table" then
            for _, field in ipairs(Codec.assetFields) do local id = Codec.id(props[field]); if id then set[id] = {Field = field} end end
        end
        if data.HasAccessories and type(data.Accessories) == "table" then
            for _, row in ipairs(data.Accessories) do
                local id = type(row) == "table" and Codec.id(row.AssetId)
                if id then set[id] = {Accessory = tostring(row.AccessoryType or "Accessory")} end
            end
        elseif type(props) == "table" then
            for _, field in ipairs(Codec.accessoryFields) do
                if type(props[field]) == "string" then
                    for value in props[field]:gmatch("%d+") do local id = Codec.id(tonumber(value)); if id then set[id] = {Accessory = (field:gsub("Accessory$", ""))} end end
                end
            end
        end
    end
    if type(data) == "table" then
        for _, field in ipairs(Codec.Extras) do
            local id = Codec.id(data[field])
            if id then set[id] = {Extra = field} end
        end
    end
    if type(data) == "table" and type(data.Makeup) == "table" then
        for _, row in ipairs(data.Makeup) do
            local id = type(row) == "table" and Codec.id(row.AssetId)
            if id then set[id] = {Makeup = tostring(row.MakeupType or "Face")} end
        end
    end
    -- Emotes count when they are on the wheel (the emote set in use when there is one); the rest of an avatar's
    -- emote list is not worn.
    local emoteSet = EmoteSets.active()
    local emotes, equipped
    if emoteSet then emotes, equipped = emoteSet.Emotes, emoteSet.Equipped
    elseif type(data) == "table" and type(data.Emotes) == "table" then emotes, equipped = Codec.emoteSet(data.Emotes, data.EquippedEmotes) end
    if emotes then
        local onWheel = #equipped > 0 and {} or nil
        for _, row in ipairs(equipped) do onWheel[row.Name] = true end
        for name, ids in pairs(emotes) do
            if not onWheel or onWheel[name] then
                for _, value in ipairs(type(ids) == "table" and ids or {}) do local id = Codec.id(value); if id then set[id] = {Emote = true} end end
            end
        end
    end
    Catalog.WornFor = snapshot; Catalog.WornSet = set; Catalog.WornSetKey = Store.Settings.EmoteSet
    return set
end
function Catalog.slotLabel(slot)
    if slot.Emote then return "Emote", 45 end
    for _, row in pairs(Catalog.Types) do
        if (slot.Field and row.Field == slot.Field) or (slot.Accessory and row.Accessory == slot.Accessory) or (slot.Makeup and row.Makeup == slot.Makeup)
            or (slot.Extra and row.Extra == slot.Extra) then return row.Label, row.Rank end
    end
    return tostring(slot.Accessory or slot.Field or slot.Makeup or "Item"), 99
end
-- ITEM IDS: every item of the appearance being worn as "Label: id" lines, accessories first (hat, hair, face,
-- neck, shoulder, front, back, waist), then clothing (classic shirt, pants, T-shirt, then layered), then the rest.
Catalog.CopyAccessories = {Hat = 1, Hair = 2, Face = 3, Neck = 4, Shoulder = 5, Front = 6, Back = 7, Waist = 8,
    TShirt = 13, Shirt = 14, Pants = 15, Jacket = 16, Sweater = 17, Shorts = 18, DressSkirt = 19, LeftShoe = 20, RightShoe = 21}
Catalog.CopyFields = {Shirt = 10, Pants = 11, GraphicTShirt = 12}
function Catalog.copyRank(slot)
    local rank = slot.Accessory and Catalog.CopyAccessories[slot.Accessory] or slot.Field and Catalog.CopyFields[slot.Field]
    if rank then return rank end
    local _, shopRank = Catalog.slotLabel(slot)
    return 100 + shopRank
end
function Catalog.idList()
    local rows = {}
    for id, slot in pairs(Catalog.worn()) do
        table.insert(rows, {Id = id, Label = (Catalog.slotLabel(slot)), Rank = Catalog.copyRank(slot)})
    end
    table.sort(rows, function(a, b) if a.Rank ~= b.Rank then return a.Rank < b.Rank end return a.Id < b.Id end)
    local lines = {}
    for _, row in ipairs(rows) do table.insert(lines, row.Label .. ": " .. tostring(row.Id)) end
    return table.concat(lines, "\n"), #rows
end
-- SHOP FAVORITES
function Catalog.favoriteIndex(item)
    for index, row in ipairs(Store.ShopFavorites) do
        if row.Id == item.Id and row.Bundle == (item.Bundle == true) then return index end
    end
end
function Catalog.toggleFavorite(item)
    local index = Catalog.favoriteIndex(item)
    if index then table.remove(Store.ShopFavorites, index); App.persist(); return false end
    if #Store.ShopFavorites >= 300 then App.report("The 300 shop favorites limit has been reached.", "warning"); return false end
    local info = not item.Bundle and Catalog.Info[item.Id]
    table.insert(Store.ShopFavorites, 1, {Id = item.Id, Name = tostring(item.Name or (info and info.Name) or ("Item " .. tostring(item.Id))):sub(1, 80),
        Bundle = item.Bundle == true, BundleKind = item.BundleKind, Kind = item.Kind and item.Kind.Name or nil})
    App.persist(); return true
end
-- A saved favorite as a shop item (its type comes back from the saved name; prices are not stored).
function Catalog.fromFavorite(row)
    if row.Bundle then return {Id = row.Id, Name = row.Name, Bundle = true, BundleKind = row.BundleKind} end
    return {Id = row.Id, Name = row.Name, Kind = row.Kind and Catalog.kind(row.Kind) or nil}
end
-- Taking accessories off the avatar being worn: the model already built for it, without those accessories, is the
-- new avatar's model, so nothing is rebuilt (rebuilding the whole avatar took seconds for one item). Only for an
-- avatar drawn from its items (a saved skin's snapshot is rebuilt from its items on any shop change) and only when
--YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
-- every accessory is found in that model. Returns whether it did.
function Catalog.reuseModel(base, snapshot, ids)
    local cache = App.ModelCache
    if not cache or cache.Snapshot ~= base or base ~= App.Current or base.Original or type(base.Data) ~= "table" or type(base.Data.Visual) == "table" then return false end
    local found = {}
    for _, item in ipairs(cache.Model:GetChildren()) do
        local id = item:IsA("Accessory") and item:GetAttribute("Lyra_AssetId")
        if id and ids[id] then found[id] = true end
    end
    for id in pairs(ids) do if not found[id] then return false end end
    local ok, copy = pcall(function() return cache.Model:Clone() end)
    if not ok or not copy then return false end
    for _, item in ipairs(copy:GetChildren()) do
        local id = item:IsA("Accessory") and item:GetAttribute("Lyra_AssetId")
        if id and ids[id] then item:Destroy() end
    end
    pcall(function() cache.Model:Destroy() end)
    App.ModelCache = {Snapshot = snapshot, Rig = cache.Rig, Model = copy, Note = nil, Rebuilt = false}
    return true
end
-- HELD ITEM AND BACKGROUND: Roblox Shop > Gear and Backgrounds. A gear (a sword, a pumpkin…) and an avatar background
-- go with the avatar you wear (Data.Gear, Data.Background) and are saved with it as a skin, shared in its codes and
-- seen by script users through Skin sync. Neither is put on your character: a gear is a game tool only the game can
-- give, and a background has no place in the world. They show where Roblox shows a profile's own: the Roblox menu's
-- picture of you and Roblox's avatar panel draw the avatar holding the gear, in the arm-forward pose Roblox's pictures
-- use, in front of the background. Only on your screen.
-- The field of the avatar's data an item lives in when it is not on the description ("Gear" or "Background"), else nil.
function Catalog.extraField(item, data)
    if item.Bundle then return nil end
    if item.Kind and item.Kind.Extra then return item.Kind.Extra end
    if type(data) == "table" then
        for _, field in ipairs(Codec.Extras) do if Codec.id(data[field]) == item.Id then return field end end
    end
    return nil
end
-- Yields. A gear or a background added or taken off: only the avatar's data changes, so the avatar model already built
-- for it is kept (nothing is rebuilt).
function Catalog.editExtras(base, items, remove, context)
    local data = Codec.copy(base.Data)
    local changed = 0
    for _, item in ipairs(items) do
        local field = Catalog.extraField(item, data)
        if remove then
            if field and Codec.id(data[field]) == item.Id then data[field] = nil; changed = changed + 1 end
        elseif field then data[field] = item.Id; changed = changed + 1 end
    end
    if changed == 0 then App.report("That item is not on your avatar.", "warning"); return false end
    local name = (base.Original and "My avatar" or tostring(base.Name or "Avatar")):gsub(" %(edited%)$", "")
    local subject = context or items[1]
    local info = not context and Catalog.Info[subject.Id]
    local snapshot = {Data = data, Name = name .. " (edited)", Catalog = true, ThumbId = base.Id or base.ThumbId,
        SelfEdit = (base.Original or base.SelfEdit) and true or nil,
        Change = {Text = (remove and "Removed " or "Added ") .. tostring(subject.Name or (info and info.Name) or "an item"), Id = subject.Id}}
    local cache = App.ModelCache
    if cache and cache.Snapshot == base and base == App.Current then cache.Snapshot = snapshot end
    return App.applySnapshot(snapshot, "catalog")
end
-- Yields. Adds (or removes) the items on the appearance being worn and applies the result.
-- context = {Id, Name, Bundle} names a bundle when several of its parts change at once.
function Catalog.edit(items, remove, context)
    if App.Busy or not App.alive() then App.report("Wait for the current change to finish.", "warning"); return false end
    local base = Catalog.freshBase()
    if not base then App.report("Wait for your character to load.", "warning"); return false end
    App.report(remove and "Removing from your avatar…" or "Adding to your avatar…", "loading")
    if not remove then
        for _, item in ipairs(items) do
            if not item.Kind then local info = Catalog.info(item.Id); item.Kind = info and Catalog.kind(info.AssetTypeId) end
        end
    end
    if App.Busy or not App.alive() then return false end
    -- A gear or a background is kept with the avatar, not on its description (see HELD ITEM AND BACKGROUND).
    local extras = true
    for _, item in ipairs(items) do if not Catalog.extraField(item, base.Data) then extras = false; break end end
    if extras and #items > 0 then return Catalog.editExtras(base, items, remove, context) end
    local decoded, desc = pcall(Codec.decode, base.Data)
    if not decoded then App.report("The current appearance could not be read: " .. tostring(desc), "error"); return false end
    local changed, animations = 0, false
    local playName, wheelFull, leaveSet, emotesTouched
    -- Accessories taken off, and whether anything else changed (then the avatar is rebuilt).
    local removedAccessories, otherChange = {}, not remove
    local ok, err = pcall(function()
        -- Emotes live in the description too. When the snapshot has none (your own avatar), start from
        -- the emotes the character has right now, so adding one never wipes the emote wheel.
        local emotes, equipped, emoteChanged
        local function loadEmotes()
            if emotes then return end
            -- With an emote set on the wheel, the edit starts from the wheel (and the set is left).
            if EmoteSets.active() then emotes, equipped = EmoteSets.wheel(); leaveSet = true; return end
            emotes, equipped = Codec.emoteSet(desc:GetEmotes(), desc:GetEquippedEmotes())
            if next(emotes) == nil then
                local humanoid = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
                local live = humanoid and humanoid:FindFirstChildOfClass("HumanoidDescription")
                if live then emotes, equipped = Codec.emoteSet(live:GetEmotes(), live:GetEquippedEmotes()) end
            end
        end
        local accessories = desc:GetAccessories(true)
        local top = 0
        for _, row in ipairs(accessories) do if row.IsLayered and type(row.Order) == "number" and row.Order > top then top = row.Order end end
        for _, item in ipairs(items) do
            local before = #accessories
            for i = #accessories, 1, -1 do if accessories[i].AssetId == item.Id then table.remove(accessories, i) end end
            if remove then
                if #accessories < before then changed = changed + 1; removedAccessories[item.Id] = true end
                loadEmotes()
                for name, ids in pairs(emotes) do
                    local kept = {}
                    for _, value in ipairs(ids) do if value ~= item.Id then table.insert(kept, value) end end
                    if #kept < #ids then
                        changed = changed + 1; emoteChanged = true; otherChange = true
                        if #kept == 0 then
                            emotes[name] = nil
                            for i = #equipped, 1, -1 do if equipped[i].Name == name then table.remove(equipped, i) end end
                        else emotes[name] = kept end
                    end
                end
                for _, field in ipairs(Codec.assetFields) do
                    if desc[field] == item.Id then desc[field] = 0; changed = changed + 1; otherChange = true; animations = animations or field:find("Animation") ~= nil end
                end
                for _, layer in ipairs(desc:GetChildren()) do
                    if layer.ClassName == "MakeupDescription" and layer.AssetId == item.Id then layer:Destroy(); changed = changed + 1; otherChange = true end
                end
            elseif item.Kind and item.Kind.Accessory then
                local row = {AssetId = item.Id, AccessoryType = Enum.AccessoryType[item.Kind.Accessory], IsLayered = item.Kind.Layered == true}
                if row.IsLayered then top = math.min(1000, top + 1); row.Order = top end
                table.insert(accessories, row); changed = changed + 1
            elseif item.Kind and item.Kind.Makeup then
                -- A new makeup layer goes on top of the ones already worn.
                local order = 0
                for _, layer in ipairs(desc:GetChildren()) do
                    if layer.ClassName == "MakeupDescription" then
                        if layer.AssetId == item.Id then layer:Destroy() elseif layer.Order >= order then order = layer.Order + 1 end
                    end
                end
                local layer = Instance.new("MakeupDescription")
                layer.AssetId = item.Id; layer.MakeupType = Enum.MakeupType[item.Kind.Makeup]; layer.Order = order; layer.Parent = desc
                changed = changed + 1
            elseif item.Kind and item.Kind.Emote then
                -- Equips the emote in the first free slot of the wheel (slot 8 when all are taken).
                loadEmotes()
                local name = Codec.cut(item.Name or "Emote", 40)
                if name:match("^%s*$") then name = "Emote " .. tostring(item.Id) end
                local used = {}
                for i = #equipped, 1, -1 do if equipped[i].Name == name then table.remove(equipped, i) else used[equipped[i].Slot] = equipped[i].Name end end
                -- The slot picked on the wheel (see EMOTE SLOT PICKER), else the first free one (slot 8 when all are taken).
                local slot = tonumber(item.Slot); item.Slot = nil
                if not (slot and slot >= 1 and slot <= 8 and slot % 1 == 0) then
                    slot = nil
                    for candidate = 1, 8 do if not used[candidate] then slot = candidate; break end end
                    if not slot then slot = 8; wheelFull = true end
                end
                for i = #equipped, 1, -1 do if equipped[i].Slot == slot then table.remove(equipped, i) end end
                -- The emote that was in that slot leaves the list too (it showed as worn in the shop while off the wheel).
                local replaced = used[slot]
                if replaced then
                    local elsewhere = false
                    for _, row in ipairs(equipped) do if row.Name == replaced then elsewhere = true; break end end
                    if not elsewhere then emotes[replaced] = nil end
                end
                emotes[name] = {item.Id}; table.insert(equipped, {Name = name, Slot = slot})
                changed = changed + 1; emoteChanged = true; playName = name
            elseif item.Kind and item.Kind.Field then
                desc[item.Kind.Field] = item.Id; changed = changed + 1
                animations = animations or item.Kind.Field:find("Animation") ~= nil
            end
        end
        desc:SetAccessories(accessories, true)
        if emoteChanged then desc:SetEmotes(emotes); desc:SetEquippedEmotes(equipped); emotesTouched = true end
    end)
    if not ok or changed == 0 then
        desc:Destroy()
        App.report(not ok and ("Roblox rejected this change: " .. tostring(err)) or remove and "That item is not on your avatar." or "This item cannot be worn on an avatar.", not ok and "error" or "warning")
        return false
    end
    local data = Codec.encode(desc); desc:Destroy()
    -- Item adjustments are kept (items are matched by name), and so are the held gear and the background.
    data.Tweaks = Codec.copy(base.Data.Tweaks)
    Codec.extras(base.Data, data)
    local name = base.Original and "My avatar" or tostring(base.Name or "Avatar")
    name = name:gsub(" %(edited%)$", "")
    -- What changed, with its picture, so the Undo bar and the timeline can show it.
    local subject = context or items[1]
    local info = not context and Catalog.Info[subject.Id]
    local itemName = tostring(subject.Name or (info and info.Name) or "an item")
    local verb = remove and "Removed " or "Added "
    local snapshot = {Data = data, Name = name .. " (edited)", Catalog = true, ThumbId = base.Id or base.ThumbId, ForceAnims = animations or nil,
        SelfEdit = (base.Original or base.SelfEdit) and true or nil,
--YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
        Change = {Text = verb .. (context and #items > 1 and (tostring(#items) .. " parts of " .. itemName) or itemName), Id = subject.Id, Bundle = context and context.Bundle or nil}}
    if leaveSet and emotesTouched then Store.Settings.EmoteSet = nil end
    if not otherChange and next(removedAccessories) then Catalog.reuseModel(base, snapshot, removedAccessories) end
    local applied = App.applySnapshot(snapshot, "catalog")
    -- A new emote plays once, so it is clear that it was added; it stays in the emote wheel afterwards.
    if applied and playName then
        if wheelFull then App.report("The emote wheel was full, so this emote took slot 8. Remove an emote to free a slot.", "warning") end
        task.wait(0.4)
        local humanoid = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
        if humanoid and not pcall(function() humanoid:PlayEmoteAsync(playName) end) then pcall(function() humanoid:PlayEmote(playName) end) end
    end
    return applied
end

-- IDEAS (Roblox Shop > Ideas): looks to try, from what you and the players around you wear.
-- The catalog type of an accessory (by its type name and whether it is layered) or of a description field.
function Catalog.accessoryKind(typeName, layered)
    if typeof(typeName) == "EnumItem" then typeName = typeName.Name end
    for _, id in ipairs(Catalog.TypeOrder) do
        local row = Catalog.Types[id]
        if row.Accessory == typeName and (row.Layered == true) == (layered == true) then return row end
    end
    for _, id in ipairs(Catalog.TypeOrder) do if Catalog.Types[id].Accessory == typeName then return Catalog.Types[id] end end
end
function Catalog.fieldKind(field)
    for _, id in ipairs(Catalog.TypeOrder) do if Catalog.Types[id].Field == field then return Catalog.Types[id] end end
end
Catalog.TypeOrder = {}
for id in pairs(Catalog.Types) do table.insert(Catalog.TypeOrder, id) end
table.sort(Catalog.TypeOrder)
-- The description another player's character shows: the game's one on its Humanoid, else what Roblox applied.
function Catalog.playerDescription(player)
    local char = player.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum then return nil end
    local live = App.liveDescription(hum)
    if live then return live end
    local ok, applied = pcall(function() return hum:GetAppliedDescription() end)
    return ok and applied or nil
end
-- TRENDING HERE: the items the other players in this server wear right now, the most worn first, each one on its own:
-- a reference to try, never someone's whole look. Items already on your avatar are left out. Returns the rows
-- ({Id, Count, Kind}) and how many players were read.
function Catalog.trending(limit)
    local counts, kinds, players = {}, {}, 0
    for _, player in ipairs(Players:GetPlayers()) do
        local desc = player ~= lp and Catalog.playerDescription(player)
        if desc then
            players = players + 1
            local seen = {}
            local function count(value, kind)
                local id = Codec.id(value)
                if id and kind and not seen[id] then seen[id] = true; counts[id] = (counts[id] or 0) + 1; kinds[id] = kinds[id] or kind end
            end
            pcall(function()
                for _, row in ipairs(desc:GetAccessories(true)) do count(row.AssetId, Catalog.accessoryKind(row.AccessoryType, row.IsLayered)) end
            end)
            for _, field in ipairs(Codec.assetFields) do
                local ok, value = pcall(function() return desc[field] end)
                if ok then count(value, Catalog.fieldKind(field)) end
            end
        end
    end
    local worn, rows = Catalog.worn(), {}
    for id, number in pairs(counts) do
        if not worn[id] then table.insert(rows, {Id = id, Count = number, Kind = kinds[id]}) end
    end
    table.sort(rows, function(a, b) if a.Count ~= b.Count then return a.Count > b.Count end return a.Id < b.Id end)
    while #rows > (limit or 24) do table.remove(rows) end
    return rows, players
end
-- FROM A PLAYER: with a player's avatar open in Copy Avatar, Ideas lists that avatar's items instead of the server's,
-- each one on its own, so the look can be used as a reference without copying it whole. Items already on your avatar
-- are left out. Returns rows like Catalog.trending.
function Catalog.fromAvatar(desc, limit)
    local rows, seen, worn = {}, {}, Catalog.worn()
    local function add(value, kind)
        local id = Codec.id(value)
        if id and kind and not seen[id] and not worn[id] then seen[id] = true; table.insert(rows, {Id = id, Count = 1, Kind = kind}) end
    end
    pcall(function()
        for _, row in ipairs(desc:GetAccessories(true)) do add(row.AssetId, Catalog.accessoryKind(row.AccessoryType, row.IsLayered)) end
    end)
    for _, field in ipairs(Codec.assetFields) do
        local ok, value = pcall(function() return desc[field] end)
        if ok then add(value, Catalog.fieldKind(field)) end
    end
    -- The shop's order: body and face, accessories, clothing, animations.
    table.sort(rows, function(a, b)
        local ra, rb = a.Kind.Rank or 99, b.Kind.Rank or 99
        if ra ~= rb then return ra < rb end
        return a.Id < b.Id
    end)
    while #rows > (limit or 40) do table.remove(rows) end
    return rows
end
-- The player whose avatar Ideas reads instead of the server: the profile open in Copy Avatar (not you, not a saved skin).
function Catalog.ideasPlayer()
    local preview = App.Preview
    local id = preview and tonumber(preview.Id)
    if not id or id == lp.UserId or typeof(preview.Description) ~= "Instance" then return nil end
    return preview
end
-- SURPRISE: a new look made from your own pieces. The avatar you wear stays the base (body, face, layered clothing,
-- animations, emotes); two to four of its accessory or classic clothing slots get another piece of yours of the same
-- kind, picked at random from your Roblox avatar, your saved skins and your shop favorites. It goes on like a shop
-- change, so Undo brings the look back.
Catalog.SurpriseSlots = {Hat = true, Hair = true, Face = true, Neck = true, Shoulder = true, Front = true, Back = true, Waist = true,
    Shirt = true, Pants = true, GraphicTShirt = true}
-- Yields (your Roblox avatar is read once). Slot -> list of {Id, Kind}.
function Catalog.ownPieces()
    local pool, seen = {}, {}
    local function add(value, kind)
        local id = Codec.id(value)
        if not id or not kind or seen[id] then return end
        local slot = (kind.Accessory and not kind.Layered and kind.Accessory) or kind.Field
        if not (slot and Catalog.SurpriseSlots[slot]) then return end
        seen[id] = true
        pool[slot] = pool[slot] or {}
        table.insert(pool[slot], {Id = id, Kind = kind})
    end
    local function fromData(data)
        if type(data) ~= "table" then return end
        local props = data.Version == 2 and data.Properties or data
        if type(props) == "table" then
            for _, field in ipairs({"Shirt", "Pants", "GraphicTShirt"}) do add(props[field], Catalog.fieldKind(field)) end
        end
        for _, row in ipairs(type(data.Accessories) == "table" and data.Accessories or {}) do
            if type(row) == "table" then add(row.AssetId, Catalog.accessoryKind(tostring(row.AccessoryType or ""), row.IsLayered)) end
        end
    end
    if Catalog.OwnAvatarData == nil then
        Catalog.OwnAvatarData = false
        pcall(function()
            local desc = API.description(lp.UserId)
            Catalog.OwnAvatarData = Codec.encode(desc)
            desc:Destroy()
        end)
    end
    fromData(Catalog.OwnAvatarData or nil)
    for _, row in ipairs(Store.Looks) do fromData(row.Data) end
    for _, row in ipairs(Store.ShopFavorites) do
        if not row.Bundle then add(row.Id, row.Kind and Catalog.kind(row.Kind)) end
    end
    return pool
end
-- Yields. Puts a surprise look on; returns whether it did.
function Catalog.surprise()
    if App.Busy or not App.alive() then App.report("Wait for the current change to finish.", "warning"); return false end
    local base = Catalog.freshBase()
    if not base or type(base.Data) ~= "table" then App.report("Wait for your character to load.", "warning"); return false end
    App.report("Mixing your pieces…", "loading")
    local pool = Catalog.ownPieces()
    if App.Busy or not App.alive() then return false end
    local decoded, desc = pcall(Codec.decode, base.Data)
    if not decoded then App.report("The current appearance could not be read: " .. tostring(desc), "error"); return false end
    local accessories = desc:GetAccessories(true)
    local slots = {}
    for slot, list in pairs(pool) do
        local current = {}
        if Catalog.SurpriseFields[slot] then
            local ok, value = pcall(function() return desc[slot] end)
            if ok and Codec.id(value) then current[value] = true end
        else
            for _, row in ipairs(accessories) do
                if not row.IsLayered and row.AccessoryType and row.AccessoryType.Name == slot then current[row.AssetId] = true end
            end
        end
        local options = {}
        for _, item in ipairs(list) do if not current[item.Id] then table.insert(options, item) end end
        if #options > 0 then table.insert(slots, {Slot = slot, Options = options}) end
    end
    if #slots == 0 then
        desc:Destroy()
        App.report("Nothing to mix yet: save a few skins or star items in the shop, and Surprise mixes those pieces into your look.", "warning")
        return false
    end
    local rng = Random.new()
    for i = #slots, 2, -1 do local j = rng:NextInteger(1, i); slots[i], slots[j] = slots[j], slots[i] end
    local count = math.min(#slots, rng:NextInteger(2, 4))
    local first
    local ok, err = pcall(function()
        for i = 1, count do
            local slot = slots[i]
            local item = slot.Options[rng:NextInteger(1, #slot.Options)]
            first = first or item
            if Catalog.SurpriseFields[slot.Slot] then
                desc[slot.Slot] = item.Id
            else
                for j = #accessories, 1, -1 do
                    local row = accessories[j]
                    if not row.IsLayered and row.AccessoryType and row.AccessoryType.Name == slot.Slot then table.remove(accessories, j) end
                end
                table.insert(accessories, {AssetId = item.Id, AccessoryType = Enum.AccessoryType[slot.Slot], IsLayered = false})
            end
        end
        desc:SetAccessories(accessories, true)
    end)
    if not ok then desc:Destroy(); App.report("Roblox rejected this change: " .. tostring(err), "error"); return false end
    local data = Codec.encode(desc); desc:Destroy()
    data.Tweaks = Codec.copy(base.Data.Tweaks)
    Codec.extras(base.Data, data)
    local name = (base.Original and "My avatar" or tostring(base.Name or "Avatar")):gsub(" %(edited%)$", "")
    local snapshot = {Data = data, Name = name .. " (edited)", Catalog = true, ThumbId = base.Id or base.ThumbId,
        Change = {Text = "Surprise: " .. tostring(count) .. " new pieces", Id = first and first.Id}}
    return App.applySnapshot(snapshot, "catalog")
end
Catalog.SurpriseFields = {Shirt = true, Pants = true, GraphicTShirt = true}

-- CUSTOMIZE: body, item adjustments and layered clothing order of the appearance being worn.
local Customize = {}
-- Yields. A body or layer change is a new snapshot (Undo and the timeline cover it), like a catalog edit.
-- change(desc, data) edits the description and/or a copy of the data; keepVisual keeps a saved skin's snapshot.
function Customize.edit(change, keepVisual, done)
    if App.Busy or not App.alive() then App.report("Wait for the current change to finish.", "warning"); return false end
    local base = Catalog.freshBase()
    if not base or type(base.Data) ~= "table" then App.report("Wait for your character to load.", "warning"); return false end
    local data = Codec.copy(base.Data)
    local ok, err = pcall(function()
        local desc = Codec.decode(data)
        local changed, problem = pcall(change, desc, data)
        if not changed then desc:Destroy(); error(problem, 0) end
        local encoded = Codec.encode(desc); desc:Destroy()
        encoded.Visual = keepVisual and data.Visual or nil
        encoded.Tweaks = data.Tweaks
        Codec.extras(data, encoded)
        data = encoded
    end)
    if not ok then App.report("This change could not be made: " .. tostring(err), "error"); return false end
    local name = (base.Original and "My avatar" or tostring(base.Name or "Avatar")):gsub(" %(edited%)$", "")
    local applied = App.applySnapshot({Data = data, Name = name .. " (edited)", Catalog = true, ThumbId = base.Id or base.ThumbId,
        SelfEdit = (base.Original or base.SelfEdit) and true or nil}, "customize")
    if applied and done then done() end
    return applied
end
-- One colour for every body part (skin tone). A saved skin keeps its snapshot; its parts are recoloured too.
function Customize.skinTone(color)
    return Customize.edit(function(desc, data)
        for _, field in ipairs(Codec.colorFields) do desc[field] = color end
        local v = data.Visual
        if type(v) == "table" then
            for name in pairs(v.Colors or {}) do v.Colors[name] = {color.R, color.G, color.B} end
            for _, row in pairs(v.Body or {}) do row.Color = {color.R, color.G, color.B} end
        end
    end, true)
end
-- Body proportions. A saved skin's snapshot holds fixed part sizes, so it is rebuilt from its items.
function Customize.setScales(values)
    return Customize.edit(function(desc)
        for field, value in pairs(values) do desc[field] = math.clamp(value, 0, 10) end
    end, false)
end
function Customize.scales()
    local base = Catalog.base(); local values = {}
    local ok, desc = pcall(Codec.decode, base and base.Data)
    for _, field in ipairs(Codec.scaleFields) do values[field] = ok and desc[field] or 1 end
    if ok then desc:Destroy() end
    return values
end
-- Layered clothing, bottom layer first: {Name, Order, Id (description items) or Index (snapshot items)}.
-- A saved skin's snapshot draws the clothes, so its order is read and changed there.
function Customize.layers()
    local base = Catalog.base(); local data = base and base.Data; local rows = {}
    if type(data) ~= "table" then return rows end
    if type(data.Visual) == "table" then
        for index, accessory in ipairs(data.Visual.Accessories or {}) do
            for _, node in ipairs(accessory.Handle and accessory.Handle.Nodes or {}) do
                if node.Class == "WrapLayer" then table.insert(rows, {Name = accessory.Name, Order = tonumber(node.Properties.Order) or 0, Index = index}); break end
            end
        end
    elseif type(data.Accessories) == "table" then
        for _, accessory in ipairs(data.Accessories) do
            if type(accessory) == "table" and accessory.IsLayered and Codec.id(accessory.AssetId) then
                table.insert(rows, {Name = tostring(accessory.AccessoryType or "Layer"), Order = tonumber(accessory.Order) or 0, Id = accessory.AssetId})
            end
        end
    end
    table.sort(rows, function(a, b) if a.Order ~= b.Order then return a.Order < b.Order end return (a.Id or a.Index) < (b.Id or b.Index) end)
    return rows
end
-- Moves a layer one step outward (+1) or inward (-1); every layer gets a clean order 1..n.
function Customize.moveLayer(index, step)
    local rows = Customize.layers()
    local target = index + step
    if not rows[index] or not rows[target] then return false end
    rows[index], rows[target] = rows[target], rows[index]
    return Customize.edit(function(desc, data)
        if type(data.Visual) == "table" then
            for order, row in ipairs(rows) do
                for _, node in ipairs(data.Visual.Accessories[row.Index].Handle.Nodes) do
                    if node.Class == "WrapLayer" then node.Properties.Order = order end
                end
            end
        else
            local list = desc:GetAccessories(true)
            for order, row in ipairs(rows) do
                for _, accessory in ipairs(list) do if accessory.AssetId == row.Id and accessory.IsLayered then accessory.Order = order end end
            end
            desc:SetAccessories(list, true)
        end
    end, true)
end
-- Where adjustments show: your character, or in visual-only mode the drawn avatar (and its spare copy).
function Customize.targets()
    local char = lp.Character; local list = {}
    local entry = char and Overlay.Active[char]
    if entry and entry.Local then
        table.insert(list, entry.Model); if entry.Spare then table.insert(list, entry.Spare) end
    elseif char then table.insert(list, char) end
    return list
end
function Customize.adjustable(item, overlay)
    if not item:IsA("Accessory") or not item:FindFirstChild("Handle") then return false end
    if overlay or item:GetAttribute("Copier_CopiedItem") then return true end
    -- On your own appearance its avatar items can be adjusted too; the game's scripted items never.
    return App.Current ~= nil and App.Current.Original == true and not item:FindFirstChildWhichIsA("Script", true) and not item:FindFirstChildWhichIsA("LocalScript", true)
end
-- Accessories that can be adjusted, one row per name: {Name, Type, Layered}.
function Customize.items()
    local rows, seen = {}, {}
    local target = Customize.targets()[1]
    if not target then return rows end
    local overlay = target ~= lp.Character
    for _, item in ipairs(target:GetChildren()) do
        if not seen[item.Name] and Customize.adjustable(item, overlay) then
            seen[item.Name] = true
            table.insert(rows, {Name = item.Name, Type = item.AccessoryType.Name, Layered = item.Handle:FindFirstChildOfClass("WrapLayer") ~= nil})
        end
    end
    table.sort(rows, function(a, b) return a.Name:lower() < b.Name:lower() end)
    return rows
end
function Customize.tweak(name)
    local data = App.Current and App.Current.Data
    local list = type(data) == "table" and data.Tweaks
    return Codec.copy(list and list[name]) or {}
end
-- Adjustments apply live (no rebuild) and are stored in the appearance data, so respawns, Save skin and skin
-- sharing keep them. On a saved skin they stay with that skin.
function Customize.setTweak(name, row)
    local snapshot = App.Current
    if not snapshot or type(snapshot.Data) ~= "table" or App.Busy then return false end
    local data = snapshot.Data
    data.Tweaks = data.Tweaks or {}
    data.Tweaks[name] = not Tweaks.empty(row) and Codec.copy(row) or nil
    if next(data.Tweaks) == nil then data.Tweaks = nil end
    -- Kept for your own avatar or this profile, so the next respawn, server or added item keeps it (see SAVED ADJUSTMENTS).
    Tweaks.keep(snapshot)
    -- Your own look's undo base carries them too, so a shop change on your own avatar starts from them.
    if snapshot.Original and App.Initial and App.Initial ~= snapshot and type(App.Initial.Data) == "table" then App.Initial.Data.Tweaks = Codec.copy(data.Tweaks) end
    local current = data.Tweaks and data.Tweaks[name] or {}
    for _, model in ipairs(Customize.targets()) do
        local overlay = model ~= lp.Character
        for _, item in ipairs(model:GetChildren()) do
--YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
            if item.Name == name and Customize.adjustable(item, overlay) then pcall(Tweaks.apply, model, item, current) end
        end
    end
    -- Items the game removes are put back from these templates, so they follow too.
    for _, rowItem in ipairs(Repair.Rows) do
        local template = rowItem.Template
        if template and template.Name == name and template:IsA("Accessory") and lp.Character then pcall(Tweaks.apply, lp.Character, template, current) end
    end
    -- An item adjusted while the game hides your character stays hidden (see GAME INVISIBILITY).
    if Cloak.Character then Cloak.schedule() end
    -- Cached builds of this appearance are stale now; skin sync sends the new version.
    if App.ModelCache and App.ModelCache.Snapshot == snapshot then pcall(function() App.ModelCache.Model:Destroy() end); App.ModelCache = nil end
    Sync.MineFor = nil
    Customize.Serial = (Customize.Serial or 0) + 1
    local serial = Customize.Serial
    task.delay(1, function() if serial == Customize.Serial and App.alive() then App.persist() end end)
    return true
end

-- A look is an independent snapshot. It never follows a username or a catalog cart.
local Looks = {}
local Share = {}
local Community = {}
function Looks.name(value)
    local name = tostring(value or ""):gsub("[%c]", " "):match("^%s*(.-)%s*$"):sub(1, 48)
    return name ~= "" and name or nil
end
function Looks.find(key)
    for index, row in ipairs(Store.Looks) do if row.Key == key then return row, index end end
end
function Looks.description(model)
    assert(model and model.Parent, "Your character is not available yet. Wait for it to respawn.")
    local hum = model:FindFirstChildOfClass("Humanoid")
    assert(hum, "The source has no Humanoid.")
    -- Your character keeps the game's description (only its emotes change), so the worn avatar's own one is used.
    if model == lp.Character and S.fvOn and S.customDesc then return S.customDesc:Clone(), "worn avatar description" end
    local desc = hum:FindFirstChildOfClass("HumanoidDescription") or model:FindFirstChildOfClass("HumanoidDescription")
    if desc then return desc:Clone(), "preview description" end
    local ok, applied = pcall(function() return hum:GetAppliedDescription() end)
    assert(ok and applied, "Could not read the character description.")
    return applied, "description applied to the Humanoid"
end
function Looks.capture(model, name, existingKey)
    assert(App.alive() and not App.Busy and not App.Dirty, "Wait for the application to finish or restore your character before saving.")
    assert(model == lp.Character, "Capture only accepts your current character.")
    -- Visual-only: your character keeps its own look (hidden under the drawn avatar), so the avatar you see is saved:
    -- the drawn one, with its description and animations. Your character's pose shows on it.
    local entry = Overlay.visualOnly() and Overlay.Active[model]
    local worn = App.Current
    local drawn = entry and entry.Local and entry.Model and entry.Model.Parent and worn and not worn.Original and type(worn.Data) == "table" and entry.Model or nil
    local desc
    if drawn then
        local decoded, made = pcall(Codec.decode, worn.Data)
        assert(decoded and made, "Could not read the avatar you are wearing.")
        desc = made
    else
        desc = Looks.description(model)
    end
    -- Items a game put on your character carry no catalog id; they are found in the description by name and mesh,
    -- so the skin keeps them (see Visual.overlay).
    local ids
    if not drawn then
        local found, result = pcall(Visual.descIds, desc, F.getTrueRigType(model) or Enum.HumanoidRigType.R15)
        ids = found and result or nil
    end
    local ok, data = pcall(Codec.encode, desc); desc:Destroy()
    assert(ok and data, "Could not save the description.")
    local skipped, pose
    local animations = drawn and Codec.copy(type(worn.Data.Visual) == "table" and worn.Data.Visual.Animations or {}) or App.captureAnimations(model)
    data.Visual, skipped, pose = Visual.capture(model, animations, drawn, ids)
    -- The items are saved untouched (see Visual.ownValue); the adjustments of what you wear go with them as a list.
    local adjusted = worn or App.Initial
    data.Tweaks = Tweaks.clean(Codec.copy(type(adjusted) == "table" and type(adjusted.Data) == "table" and adjusted.Data.Tweaks or nil))
    -- The gear held and the background chosen in the shop are saved with the skin (see HELD ITEM AND BACKGROUND).
    Codec.extras(type(adjusted) == "table" and adjusted.Data or nil, data)
    local check, poseRig = Visual.LastPoseCheck, nil
    -- A drawn avatar of the other rig plays its own animations instead of your pose (see PUPPET): when it shows no
    -- pose, the pose is read from your character itself, and kept with your character's rig.
    if drawn and not pose then
        local readable, real, _, realPose = pcall(Visual.capture, model, {}, nil)
        if readable and realPose and real then pose, poseRig = realPose, real.RigType end
    end
    App.devNote(string.format("Pose check (%s): %d bent joints, limb %s, elbow/knee %s → %s%s", drawn and ("drawn avatar, " .. tostring(entry and entry.Mode or "?")) or "your character",
        check and check.Bent or -1, tostring(check and check.Limb), tostring(check and check.Bend), pose and "pose found" or "no pose",
        poseRig and (" (read from your " .. poseRig .. " character)") or ""))
    assert(App.alive() and model == lp.Character, "Your character changed during the capture.")
    local row = existingKey and Looks.find(existingKey)
    if existingKey then assert(row, "The selected skin no longer exists.") end
    if not row then
        assert(#Store.Looks < 100, "Limit of 100 skins.")
        row = {Key = HttpService:GenerateGUID(false)}; table.insert(Store.Looks, 1, row)
    end
    row.Name = Looks.name(name) or row.Name or "New skin"
    row.Data = data; row.Source = "My character · " .. data.Visual.RigType; row.Updated = os.time()
    -- The profile this skin is a copy of, when it was saved while wearing that profile as it is (see ROBLOX'S OWN PICTURE).
    row.FromUser = (worn and not worn.Original and not worn.Catalog and not worn.LookKey and not worn.SyncUser and not drawn) and Codec.id(worn.Id) or nil
    -- The copied avatar you wear now was saved: a pose you keep shows on it at once (see UI.offerPose).
    local wornNow = worn and not worn.Original and (drawn or not Overlay.visualOnly()) and worn or nil
    return row, "the character's real appearance", #skipped > 0 and skipped or false, App.persist(), pose, wornNow, poseRig
end
function Looks.import(raw, name)
    assert(type(raw) == "string" and #raw <= 2000000, "Invalid code/JSON or larger than 2 MB.")
    raw = raw:match("^%s*(.-)%s*$")
    if Share.isCode(raw) then raw = "LYRA3:" .. Share.fetch(raw) end
    local prefixed = raw:sub(1,6) == "LYRA2:" or raw:sub(1,6) == "LYRA3:"
    local ok, packet = pcall(function() return HttpService:JSONDecode(prefixed and raw:sub(7) or raw) end)
    assert(ok and type(packet) == "table", "Paste a LYRA code or the full contents of the old JSON.")
    local data, title
    if packet.MembrosCorpo or packet.MembrosCustom then data = Visual.legacy(packet); title = Looks.name(name) or "Old skin"
    elseif packet.Version == 3 and type(packet.Skins) == "table" then
        -- A pack: several skins in one code (see Looks.packPacket). They keep the pack's order, first on top.
        local skins = {}
        for index, entry in ipairs(packet.Skins) do
            if index > Looks.PackMax then break end
            assert(type(entry) == "table", "Code not recognized.")
            table.insert(skins, {Name = Looks.name(entry.Name) or "Imported skin", Data = Looks.readData(entry.Data)})
        end
        assert(#skins > 0, "This code has no skins.")
        assert(#Store.Looks + #skins <= 100, "Not enough room in your library (100 skins at most).")
        local first
        for index = #skins, 1, -1 do
            first = {Key = HttpService:GenerateGUID(false), Name = skins[index].Name, Data = skins[index].Data, Source = "Shared code", Updated = os.time()}
            table.insert(Store.Looks, 1, first)
        end
        return first, App.persist(), #skins
    else
        assert((packet.Version == 1 or packet.Version == 2) and type(packet.Data) == "table", "Code not recognized.")
        data = Looks.readData(packet.Data)
        title = Looks.name(packet.Name) or Looks.name(name) or "Imported skin"
    end
    assert(#Store.Looks < 100, "Limit of 100 skins.")
    local row = {Key = HttpService:GenerateGUID(false), Name = title, Data = data,
        Source = data.Visual and data.Visual.Legacy and "Old JSON · estimated attachments" or "Shared code", Updated = os.time()}
    table.insert(Store.Looks, 1, row)
    return row, App.persist(), 1
end
-- A shared skin's data, from someone else: checked like an imported code, then rebuilt from its description.
function Looks.readData(raw)
    assert(type(raw) == "table", "Code not recognized.")
    if raw.Visual then Visual.validate(raw.Visual) end
    local valid, desc = pcall(Codec.decode, raw)
    assert(valid and desc, "Incompatible description.")
    local data = Codec.encode(desc); desc:Destroy(); data.Visual = raw.Visual; data.Tweaks = Tweaks.clean(raw.Tweaks)
    Codec.extras(raw, data)
    return data
end
-- PACKS: several saved skins shared in one code (Saved Skins > Select). Importing it adds every skin.
Looks.PackMax = 20
function Looks.packPacket(rows)
    local skins = {}
    for _, row in ipairs(rows) do table.insert(skins, {Name = row.Name, Data = row.Data}) end
    return HttpService:JSONEncode({Version = 3, Name = tostring(#rows) .. " skins", Skins = skins})
end
function Looks.share(row)
    return "LYRA3:" .. HttpService:JSONEncode({Version = 2, Name = row.Name, Data = row.Data})
end
-- A skin from another player (a skin request or the Community), kept in Saved Skins. It was checked when it arrived.
function Looks.addReceived(data, name, source)
    assert(#Store.Looks < 100, "Limit of 100 skins.")
    local row = {Key = HttpService:GenerateGUID(false), Name = Looks.name(name) or "Received skin", Data = Codec.copy(data),
        Source = tostring(source or "Shared code"), Updated = os.time()}
    table.insert(Store.Looks, 1, row)
    App.persist()
    return row
end
-- SHORT CODES: a shared skin is kept on the Lyra server and passed around as "<your username> | <skin name>"; another
-- skin you share under the same name gets a number ("Goth 2"). Pasting the short code in Import fetches the skin. The
-- long LYRA code still works, and is what you get when the server can't be reached. A code nobody imports for 180
-- days expires.
Share.Url = "https://api.lyraez.lol/v1/share"
function Share.call(body)
    local requestFn = Sync.requestFn(); if not requestFn then return nil end
    local ok, response = pcall(requestFn, {Url = Share.Url, Method = "POST", Headers = {["Content-Type"] = "application/json"}, Body = HttpService:JSONEncode(body)})
    if not ok or type(response) ~= "table" or type(response.Body) ~= "string" then return nil end
    local decoded, reply = pcall(function() return HttpService:JSONDecode(response.Body) end)
    return decoded and type(reply) == "table" and reply or nil
end
-- Yields. The short code of a saved skin, or nil and the reason.
function Share.publish(row) return Share.publishPacket(Looks.share(row):sub(7), row.Name) end
-- Yields. The short code of a packet (one skin or a pack) under a name, or nil and the reason.
function Share.publishPacket(packet, name)
    if #packet > 250000 then return nil, "too_large" end
    local reply = Share.call({a = "put", user = lp.UserId, name = lp.Name, skin = name, data = packet})
    if reply and reply.ok == true and type(reply.code) == "string" then return reply.code end
    return nil, reply and tostring(reply.error) or "offline"
end
-- Whether pasted text is a short code ("name | skin") rather than a LYRA code or a JSON backup.
function Share.isCode(raw)
    if type(raw) ~= "string" or #raw > 120 or raw:find("^LYRA%d:") or raw:find("^[%[{]") then return false end
    return raw:match("^@?[%w_]+%s*|%s*%S") ~= nil
end
-- Yields. The skin packet (JSON) behind a short code.
function Share.fetch(code)
    local reply = Share.call({a = "get", code = code})
    if reply and reply.ok == true and type(reply.data) == "string" then return reply.data end
    if reply and reply.error == "not_found" then error("No skin uses this code. Codes nobody imports for 180 days expire.", 0) end
    if reply and reply.error == "invalid_code" then error("This code is not valid. It looks like: username | skin name.", 0) end
    error("Could not reach the Lyra server to read this code. Try again, or ask for the full LYRA code.", 0)
end
-- COMMUNITY (Saved Skins > Community): skins posted by Avatar Studio players, kept on the Lyra server. A post holds the
-- skin, a name, a description and the ids of its items. Your script makes a key the first time you post; it stays in
-- your workspace and is what lets you delete your posts later.
Community.Url = "https://api.lyraez.lol/v1/community"
Community.KeyFile = "Copier_CommunityKey.txt"
Community.Cache = {}
function Community.call(body)
    local requestFn = Sync.requestFn(); if not requestFn then return nil end
    local ok, response = pcall(requestFn, {Url = Community.Url, Method = "POST", Headers = {["Content-Type"] = "application/json"}, Body = HttpService:JSONEncode(body)})
    if not ok or type(response) ~= "table" or type(response.Body) ~= "string" then return nil end
    local decoded, reply = pcall(function() return HttpService:JSONDecode(response.Body) end)
    return decoded and type(reply) == "table" and reply or nil
end
function Community.key()
    if Community.Key then return Community.Key end
    local key
    pcall(function() if type(isfile) == "function" and isfile(Community.KeyFile) then key = readfile(Community.KeyFile) end end)
    key = type(key) == "string" and key:match("^%s*([%w%-]+)%s*$") or nil
    if not key or #key < 16 or #key > 64 then
        key = HttpService:GenerateGUID(false)
        if type(writefile) == "function" then pcall(writefile, Community.KeyFile, key) end
    end
    Community.Key = key
    return key
end
local function communityError(reply)
    local err = reply and reply.error
    if err == "rate_limited" then return "Too many requests at once. Try again in a minute." end
    if err == "not_found" then return "This post was removed." end
    if err == "already" then return "You're already a verified creator." end
    if err == "pending" then return "Your request is waiting for review." end
    if err == "not_eligible" then return "You don't meet the requirements yet." end
    return reply and "The Lyra server did not accept this." or "Could not reach the Lyra server. Try again in a moment."
end
-- A Discord username as typed: no spaces or "@"; "" when empty.
function Community.discord(text) return (tostring(text or ""):gsub("%s", ""):gsub("^@", "")) end
-- CHAT (Saved Skins > Chat): one room for every Avatar Studio player, in any game or server. The Lyra server checks
-- each message (no links, no blocked words, a few a minute) and hides one that several players report; your account
-- is tied to this device's key (the Community's), so nobody can write as you. The room is read every few seconds,
-- only while the chat is open.
local Chat = {Url = "https://api.lyraez.lol/v1/chat", Messages = {}, Last = 0, Active = 0, Interval = 4}
function Chat.call(body)
    local requestFn = Sync.requestFn(); if not requestFn then return nil end
    local ok, response = pcall(requestFn, {Url = Chat.Url, Method = "POST", Headers = {["Content-Type"] = "application/json"}, Body = HttpService:JSONEncode(body)})
    if not ok or type(response) ~= "table" or type(response.Body) ~= "string" then return nil end
    local decoded, reply = pcall(function() return HttpService:JSONDecode(response.Body) end)
    return decoded and type(reply) == "table" and reply or nil
end
Chat.Errors = {no_links = "Links can't be sent in the chat.", blocked = "That message has a word the chat doesn't allow.",
    too_long = "Messages are up to 200 characters.", empty = "Type a message first.", slow_down = "You're sending too fast. Wait a few seconds.",
    repeated = "You just sent that.", muted = "You can't send messages in the chat.", other_device = "This account chats from another device. Ask the owner on Discord to free it.",
    rate_limited = "Too many requests at once. Try again in a minute."}
function Chat.error(reply)
    -- An account another device used a moment ago comes here once that device has been quiet for a while.
    if reply and reply.error == "other_device" and type(reply.wait) == "number" then
        return "This account was just used on another device. You can chat with it here in " .. tostring(math.max(1, math.floor(reply.wait))) .. " min."
    end
    local known = reply and Chat.Errors[reply.error]
    if known then return known end
    return reply and "The Lyra server did not accept this." or "Could not reach the Lyra server. Try again in a moment."
end
-- A message from the server, checked (it is shown as plain text).
function Chat.row(raw)
    if type(raw) ~= "table" or type(raw.id) ~= "number" or type(raw.text) ~= "string" or type(raw.uname) ~= "string" then return nil end
    return {Id = raw.id, User = Codec.id(raw.user), Name = raw.uname:gsub("[^%w_]", ""):sub(1, 20), Text = Codec.cut(raw.text, 200), At = tonumber(raw.at) or 0,
        Creator = raw.creator == true, Staff = raw.staff == true, Look = Codec.id(raw.look)}
end
-- The verified creators the server lists (with the first page of Community and the chat's first read), shown at the
-- top of both.
Community.Creators = {}
function Community.readCreators(list)
    local creators = {}
    for _, raw in ipairs(list) do
        local user = type(raw) == "table" and Codec.id(raw.user)
        if user and #creators < 24 then
            table.insert(creators, {User = user, Name = type(raw.name) == "string" and raw.name:gsub("[^%w_]", ""):sub(1, 20) or "", Look = Codec.id(raw.look)})
        end
    end
    Community.Creators = creators
end
function Chat.isCreator(user)
    for _, creator in ipairs(Community.Creators) do if creator.User == user then return true end end
    return false
end
-- Yields. Reads what is new (everything the first time). Returns whether anything changed.
function Chat.fetch()
    local first = Chat.Last == 0
    local reply = Chat.call(first and {a = "list"} or {a = "list", after = Chat.Last})
    if not reply or reply.ok ~= true then return false, Chat.error(reply) end
    local changed = false
    for _, raw in ipairs(type(reply.messages) == "table" and reply.messages or {}) do
        local row = Chat.row(raw)
        if row and not Chat.Messages[row.Id] then
            Chat.Messages[row.Id] = row; changed = true
            if row.Id > Chat.Last then Chat.Last = row.Id end
        end
    end
    for _, id in ipairs(type(reply.gone) == "table" and reply.gone or {}) do
        if Chat.Messages[id] then Chat.Messages[id] = nil; changed = true end
    end
    if type(reply.creators) == "table" then Community.readCreators(reply.creators); changed = true end
    Chat.Active = math.max(0, math.floor(tonumber(reply.active) or 0))
    -- Only the latest 150 are kept on screen.
    local ids = Chat.ordered()
    for i = 1, #ids - 150 do Chat.Messages[ids[i].Id] = nil; changed = true end
    return changed or first
end
function Chat.ordered()
    local list = {}
    for _, row in pairs(Chat.Messages) do table.insert(list, row) end
    table.sort(list, function(a, b) return a.Id < b.Id end)
    return list
end
-- Yields. Sends a message; returns true, or nil and why not.
function Chat.send(text)
    text = Codec.cut(tostring(text or ""):match("^%s*(.-)%s*$"), 200)
    if text == "" then return nil, Chat.Errors.empty end
    local reply = Chat.call({a = "send", user = lp.UserId, uname = lp.Name, key = Community.key(), text = text})
    if not reply or reply.ok ~= true then return nil, Chat.error(reply) end
    if type(reply.id) == "number" then
        Chat.Messages[reply.id] = {Id = reply.id, User = lp.UserId, Name = lp.Name, Text = type(reply.text) == "string" and reply.text or text, At = tonumber(reply.at) or 0,
            Creator = Chat.isCreator(lp.UserId), Look = Presence.look() or Presence.Sent}
    end
    return true
end
function Chat.report(id) task.spawn(Chat.call, {a = "report", id = id, user = lp.UserId, key = Community.key()}) end
-- Yields. Deletes one of your messages.
function Chat.remove(id)
    local reply = Chat.call({a = "delete", id = id, user = lp.UserId, key = Community.key()})
    if reply and reply.ok == true then Chat.Messages[id] = nil; return true end
    return nil, Chat.error(reply)
end
-- Yields. Posts a saved skin; returns the post id and whether it was already posted (then its text is updated),
-- or nil and a message.
function Community.post(row, about, discord)
    local packet = Looks.share(row):sub(7)
    if #packet > 250000 then return nil, "This skin is too big to post." end
    local visual = type(row.Data) == "table" and row.Data.Visual
    local reply = Community.call({a = "post", user = lp.UserId, uname = lp.Name, key = Community.key(), name = row.Name, about = tostring(about or ""), discord = tostring(discord or ""),
        items = Community.items(row.Data), rig = type(visual) == "table" and visual.RigType == "R6" and "R6" or "R15", data = packet})
    if reply and reply.ok == true and type(reply.id) == "string" then return reply.id, reply.updated == true end
    if reply and reply.error == "limit" then return nil, "You can have 20 posts. Delete one in Community > Mine first." end
    if reply and reply.error == "exists" then return nil, "This skin was already posted from another device." end
    if reply and reply.error == "invalid_discord" then return nil, "That Discord username is not valid. Type it like lyra.ez (or leave it empty)." end
    return nil, communityError(reply)
end
-- Yields. A page of posts: sort "new" or "top", a search, an offset; mine: your own posts (hidden ones too).
-- Returns the posts and whether there are more, or nil and a message.
function Community.list(sort, query, offset, mine)
    local body = {a = "list", sort = sort, offset = offset or 0}
    if query and query ~= "" then body.q = query end
    if mine then body.user = lp.UserId; body.key = Community.key() end
    local reply = Community.call(body)
    if reply and reply.ok == true and type(reply.posts) == "table" then
        if type(reply.creators) == "table" then Community.readCreators(reply.creators) end
        return reply.posts, reply.more == true, Community.verifyState(reply.verify)
    end
    return nil, communityError(reply)
end
-- VERIFIED CREATOR requests: a player whose best skin reached 100 uses, with 2 skins at 25+ uses (posted from this
-- device), can ask for the mark from Community > Mine. The owner answers from the Lyra panel.
function Community.verifyState(raw)
    if type(raw) ~= "table" then return nil end
    local need = type(raw.need) == "table" and raw.need or {}
    local state = ({none = true, pending = true, approved = true, declined = true})[raw.state] and raw.state or "none"
    return {Creator = raw.creator == true, Top = math.max(0, math.floor(tonumber(raw.top) or 0)), Count = math.max(0, math.floor(tonumber(raw.count) or 0)),
        NeedTop = math.max(1, math.floor(tonumber(need.top) or 100)), NeedMin = math.max(1, math.floor(tonumber(need.min) or 25)),
        NeedCount = math.max(1, math.floor(tonumber(need.count) or 2)), Eligible = raw.eligible == true, State = state}
end
-- Yields. Sends the request; returns the new status, or nil and why not.
function Community.askVerify()
    local reply = Community.call({a = "verify", user = lp.UserId, uname = lp.Name, key = Community.key()})
    if reply and reply.ok == true then return Community.verifyState(reply.verify) end
    return nil, communityError(reply), reply and Community.verifyState(reply.verify)
end
-- Yields. A post's skin, checked like any shared skin (kept for this session). use: it is being worn or saved, which
-- counts for Popular.
function Community.fetch(id, use)
    local cached = Community.Cache[id]
    if cached then
        if use then task.spawn(Community.call, {a = "get", id = id, use = true, user = lp.UserId}) end
        return cached
    end
    -- A use counts once per player (the Lyra server checks who), toward the post's badges.
    local reply = Community.call({a = "get", id = id, use = use == true, user = use and lp.UserId or nil})
    if not (reply and reply.ok == true and type(reply.data) == "string") then error(communityError(reply), 0) end
    local ok, packet = pcall(function() return HttpService:JSONDecode(reply.data) end)
    if not (ok and type(packet) == "table" and packet.Version == 2) then error("This post's skin could not be read.", 0) end
    local data = Looks.readData(packet.Data)
    Community.Cache[id] = data
    return data
end
-- Yields. Deletes one of your posts; returns whether it did.
function Community.remove(id)
    local reply = Community.call({a = "delete", id = id, key = Community.key()})
    return reply and reply.ok == true
end
function Community.report(id) task.spawn(Community.call, {a = "report", id = id, user = lp.UserId}) end

-- AUTO-LOAD & AVATAR CYCLE
-- Entries never store a description: a profile is fetched again (cached) and a skin is read from the library when used.
function Auto.entryFrom(source)
    if type(source) ~= "table" or source.Original then return nil end
    if source.LookKey then
        local row = Looks.find(source.LookKey)
        return Store.entry({Kind = "Look", Key = source.LookKey, Name = row and row.Name or source.Name})
    end
    if source.Id then return Store.entry({Kind = "User", Id = source.Id, Name = source.Name, DisplayName = source.DisplayName}) end
end
function Auto.same(a, b)
    if not a or not b or a.Kind ~= b.Kind then return false end
    if a.Kind == "Look" then return a.Key == b.Key end
    if a.Id and b.Id then return a.Id == b.Id end
    return a.Name:lower() == b.Name:lower()
end
function Auto.name(entry)
    if not entry then return "None" end
    if entry.Kind == "Look" then local row = Looks.find(entry.Key); return row and row.Name or entry.Name end
    return (entry.DisplayName ~= "" and entry.DisplayName ~= entry.Name) and (entry.DisplayName .. " (@" .. entry.Name .. ")") or ("@" .. entry.Name)
end
function Auto.remember(snapshot)
    local entry = Auto.entryFrom(snapshot)
    if not entry or Auto.same(entry, Store.Auto.Last) then return false end
    Store.Auto.Last = entry; return true
end
-- Yields. Returns an apply-ready snapshot, or nil and a message.
function Auto.resolve(entry)
    if not entry then return nil, "No avatar is selected." end
    if entry.Kind == "Look" then
        local row = Looks.find(entry.Key)
        if not row then return nil, "The saved skin '" .. entry.Name .. "' no longer exists." end
        return {Data = row.Data, Name = row.Name, LookKey = row.Key, FromUser = row.FromUser}
    end
    local profile, err = App.resolve(tostring(entry.Id or entry.Name), App.alive)
    if not profile then return nil, err ~= "cancelled" and (Auto.name(entry) .. ": " .. tostring(err)) or nil end
    return {Data = Codec.encode(profile.Description), Id = profile.Id, Name = profile.Name}
end
-- Next position in the list: an index, "stop" or "restore".
function Auto.pick(step)
    local auto, list = Store.Auto, Store.Auto.List
    local count, current = #list, Store.Auto.Index
    if count == 0 then return nil end
    if current > count then current = 0 end
    if step < 0 then return current <= 1 and count or current - 1 end
    if count == 1 then return 1 end
    if auto.Order == "Random" then
        local index; repeat index = Auto.Rng:NextInteger(1, count) until index ~= current
        return index
    elseif auto.Order == "Shuffle" then
        for i = #Auto.Bag, 1, -1 do if Auto.Bag[i] > count then table.remove(Auto.Bag, i) end end
        if #Auto.Bag == 0 then
            -- Every avatar once per round; a new round never starts with the avatar being worn.
            for i = 1, count do table.insert(Auto.Bag, i) end
            for i = #Auto.Bag, 2, -1 do local j = Auto.Rng:NextInteger(1, i); Auto.Bag[i], Auto.Bag[j] = Auto.Bag[j], Auto.Bag[i] end
            if Auto.Bag[count] == current then Auto.Bag[count], Auto.Bag[1] = Auto.Bag[1], Auto.Bag[count] end
        end
        local index = table.remove(Auto.Bag)
        -- A manual Wear/Previous can make the next card the avatar already on; take the following one.
        if index == current and #Auto.Bag > 0 then index, Auto.Bag[#Auto.Bag] = Auto.Bag[#Auto.Bag], index end
        return index
    elseif auto.Order == "PingPong" then
        if current == 0 then Auto.Direction = 1; return 1 end
        local nextIndex = current + Auto.Direction
        if nextIndex > count or nextIndex < 1 then Auto.Direction = -Auto.Direction; nextIndex = current + Auto.Direction end
        return nextIndex
    end
    if current < count then return current + 1 end
    return auto.EndAction == "Loop" and 1 or auto.EndAction == "Restore" and "restore" or "stop"
end
-- Yields. Resolves the next avatar without applying it; an unavailable entry is skipped.
function Auto.prepare(step, forced)
    local lastError
    for _ = 1, math.min(#Store.Auto.List, 5) do
        local index = forced or Auto.pick(step)
        if index == "restore" then
            if App.Initial then return App.Initial, nil, 0 end
            return nil, "The cycle ended, but the initial appearance is unknown."
        end
        if index == "stop" or not index then return nil, index == "stop" and "The avatar cycle reached the end of the list." or "The cycle list is empty." end
        local entry = Store.Auto.List[index]
        local ok, snapshot, err = pcall(Auto.resolve, entry)
        if ok and snapshot then return snapshot, nil, index end
        lastError = ok and err or tostring(snapshot)
        if forced or not App.alive() then break end
        -- Move past the broken entry so the next attempt picks another one.
        Store.Auto.Index = index
    end
    return nil, lastError or "No avatar in the cycle could be loaded."
end
function Auto.commit(index, snapshot)
    if index then Store.Auto.Index = index end
    Auto.LastSwitch = os.clock(); Auto.TimerStart = os.clock(); Auto.DeathsSince = 0
    App.persistState(); Auto.OnChange()
    if Store.Auto.Notify then
        App.toast({Title = "Avatar cycle", Text = snapshot.Original and "Initial appearance restored." or ("Now wearing " .. tostring(snapshot.Name) .. "."), Kind = "success", Icon = "repeat", Duration = 3})
    end
end
-- Manual next/previous, "Wear" from the list and the timer apply to the live character.
function Auto.switchNow(step, forced)
    if Auto.Switching or App.Busy or not App.alive() then return false end
    if #Store.Auto.List == 0 then App.report("Add avatars to the cycle list first.", "warning"); return false end
    local char = lp.Character; local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then App.report("Wait for your character to respawn.", "warning"); return false end
    Auto.Switching = true; Auto.OnChange()
    task.spawn(function()
        local snapshot, err, index = Auto.prepare(step, forced)
        if snapshot and App.alive() and char == lp.Character then
            if App.applySnapshot(snapshot, snapshot.Original and "restore" or "cycle", char) then Auto.commit(index, snapshot) end
        elseif err then App.report(err, "warning") end
        Auto.Switching = false; Auto.OnChange()
    end)
    return true
end
-- Moves an entry and keeps the "wearing now" position pointing at the same avatar.
function Auto.move(from, to)
    local list = Store.Auto.List
    if from == to or from < 1 or from > #list or to < 1 or to > #list then return false end
    local item = table.remove(list, from); table.insert(list, to, item)
    local current = Store.Auto.Index
    if current == from then Store.Auto.Index = to
    elseif from < current and to >= current then Store.Auto.Index = current - 1
    elseif from > current and to <= current and current > 0 then Store.Auto.Index = current + 1 end
    table.clear(Auto.Bag)
    return true
end
function Auto.countsAs(kind)
    local trigger = Store.Auto.Trigger
    if kind == "death" then return trigger == "Death" or trigger == "Both" end
    return trigger == "Respawn"
end
-- Counts a death/respawn; when the threshold is met the next avatar starts loading during the respawn timer.
function Auto.count(kind)
    local auto = Store.Auto
    if kind == "death" then Auto.Deaths = Auto.Deaths + 1 end
    if not auto.CycleEnabled or #auto.List == 0 or not Auto.countsAs(kind) or Auto.Pending then Auto.OnChange(); return end
    Auto.DeathsSince = Auto.DeathsSince + 1
    -- During the cooldown the counter is kept, so the next death after it switches.
    if Auto.DeathsSince < auto.EveryDeaths or os.clock() - Auto.LastSwitch < auto.Cooldown then Auto.OnChange(); return end
    local pending = {Done = false}
    Auto.Pending = pending
    task.spawn(function()
        local ok, snapshot, err, index = pcall(Auto.prepare, 1)
        if ok then pending.Snapshot, pending.Error, pending.Index = snapshot, err, index else pending.Error = tostring(snapshot) end
        pending.Done = true
    end)
    Auto.OnChange()
end
-- Returns true when the cycle takes over this respawn (F.reapply then stays out of it).
function Auto.onRespawn(char)
    if Auto.SkipRespawn then Auto.SkipRespawn = false; return false end
    Auto.count("respawn")
    local pending = Auto.Pending
    if not pending then return false end
    Auto.Pending = nil
    task.spawn(function()
        local ok, err = pcall(function()
            local deadline = os.clock() + 15
            while not pending.Done and os.clock() < deadline and App.alive() do task.wait(0.1) end
            local visualOnly = Overlay.visualOnly()
            local root = char:WaitForChild("HumanoidRootPart", visualOnly and 4 or 8) or (visualOnly and Overlay.rootOf(char))
            local hum = visualOnly and char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 8)
            if not App.alive() or char ~= lp.Character or (not hum and not visualOnly) or not root then return end
            local loaded = os.clock() + 4
            while not lp:HasAppearanceLoaded() and os.clock() < loaded and App.alive() do task.wait() end
            if not visualOnly then App.waitSettled(char, 6, 0.5) end
            local idle = os.clock() + 10
            while App.Busy and os.clock() < idle and App.alive() do task.wait(0.1) end
            if not App.alive() or char ~= lp.Character or (hum and hum.Health <= 0) or App.CleanReset then return end
            if pending.Snapshot then
                if App.applySnapshot(pending.Snapshot, pending.Snapshot.Original and "restore" or "cycle", char) then Auto.commit(pending.Index, pending.Snapshot); return end
            elseif pending.Error then App.report(pending.Error, "warning") end
            -- The next avatar could not be used: keep the current one, as a normal respawn would.
            F.reapply(char, false)
        end)
        Cover.finish(char)
        if not ok then warn("[Lyra Avatar Studio] Avatar cycle: " .. tostring(err)) end
    end)
    return true
end
function Auto.watch(char)
    if Auto.DiedConnection then Auto.DiedConnection:Disconnect(); Auto.DiedConnection = nil end
    local hum = char and char:WaitForChild("Humanoid", 10)
    if not hum or char ~= lp.Character or not App.alive() then return end
    Auto.DiedConnection = RegisterConnection(hum.Died:Connect(function()
        if not App.alive() or char ~= lp.Character then return end
        if Auto.SkipDeath then Auto.SkipDeath = false; return end
        Auto.count("death")
    end))
end
function Auto.startTimer()
    task.spawn(function()
        while App.alive() do
            task.wait(1)
            local auto = Store.Auto
            local timed = auto.CycleEnabled and (auto.Trigger == "Timer" or auto.Trigger == "Both") and #auto.List > 0
            if not timed or App.Busy or Auto.Switching or Auto.Pending then
                if not timed then Auto.TimerStart = os.clock() end
            elseif os.clock() - Auto.TimerStart >= auto.TimerSeconds and os.clock() - Auto.LastSwitch >= auto.Cooldown then
                Auto.TimerStart = os.clock()
                Auto.switchNow(1)
            end
            pcall(App.guardFollow)
            pcall(Auto.OnTick)
        end
    end)
end
-- The avatar used on execute: a per-game choice wins over the general source.
function Auto.startEntry()
    local auto = Store.Auto
    local perGame = auto.Games[tostring(game.PlaceId)]
    if perGame then return perGame, nil, "this game's avatar" end
    if auto.LoadSource == "Last" then return auto.Last, nil, "last applied avatar" end
    if auto.LoadSource == "Random" then
        local pool = {}
        for _, row in ipairs(Store.Favorites) do local entry = Store.entry({Kind = "User", Id = row.Id, Name = row.Name, DisplayName = row.DisplayName}); if entry then table.insert(pool, entry) end end
        if #pool == 0 then return nil, nil, "random favorite" end
        return pool[Auto.Rng:NextInteger(1, #pool)], nil, "random favorite"
    end
    if auto.LoadSource == "Cycle" then
        local count = #auto.List
        if count == 0 then return nil, nil, "cycle avatar" end
        local index = (auto.Index >= 1 and auto.Index <= count) and auto.Index or 1
        return auto.List[index], index, "cycle avatar"
    end
    return auto.Chosen, nil, "chosen avatar"
end
-- Auto-load starts as soon as the script runs, before the window is built: the avatar is fetched and its model built
-- meanwhile, and your character is covered until it is on (see COVER), so your own avatar never shows after a
-- teleport. Auto.boot applies it once the window is up.
function Auto.prefetch()
    if Auto.Prefetch or not Store.Auto.LoadEnabled or Config.TargetUsername ~= "" then return end
    local entry, index, label = Auto.startEntry()
    local job = {Entry = entry, Index = index, Label = label, Done = entry == nil}
    Auto.Prefetch = job
    if not entry then return end
    Auto.Booting = true
    -- The script ran again while a copied avatar is on: that one stays visible until the new one replaces it.
    local carry = _G.Copier_Carry
    local carried = type(carry) == "table" and carry.Character ~= nil and carry.Character == lp.Character
    if lp.Character and not carried then Cover.begin(lp.Character, 25 + Store.Auto.LoadDelay) end
    task.spawn(function()
        local ok, snapshot, err = pcall(Auto.resolve, entry)
        if not ok then err = tostring(snapshot); snapshot = nil end
        job.Snapshot, job.Error = snapshot, err
        if snapshot and App.alive() then
            Tweaks.attach(snapshot)
            local char = lp.Character
            local rig = char and not Overlay.visualOnly() and F.getTrueRigType(char)
            if rig then pcall(App.prebuild, snapshot, rig) end
        end
        job.Done = true
    end)
end
--[==[YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU]==]
function Auto.boot()
    if not Store.Auto.Resume then Store.Auto.Index = 0 end
    if not Store.Auto.LoadEnabled or Config.TargetUsername ~= "" then Auto.Booting = false; return false end
    pcall(Auto.prefetch)
    local job = Auto.Prefetch
    local entry, index = job and job.Entry, job and job.Index
    if not entry then
        Auto.Booting = false
        App.report("Auto-load is on, but no " .. tostring(job and job.Label or "avatar") .. " is set. Choose one in Auto & Cycle.", "warning"); return false
    end
    task.spawn(function()
        local done, problem = pcall(function()
            local char = lp.Character or lp.CharacterAdded:Wait()
            local deadline = os.clock() + 20
            repeat
                char = lp.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local ready = char and (hum and hum.Health > 0 and char:FindFirstChild("HumanoidRootPart") or (not hum and Overlay.visualOnly() and Overlay.rootOf(char)))
                if not ready then task.wait(0.1) end
            until ready or os.clock() > deadline or not App.alive()
            local loaded = os.clock() + 6
            while not lp:HasAppearanceLoaded() and os.clock() < loaded and App.alive() do task.wait() end
            if char and not Overlay.visualOnly() then App.waitSettled(char, 6, 0.5) end
            task.wait(Store.Auto.LoadDelay)
            while App.Busy and App.alive() do task.wait(0.1) end
            if not App.alive() then return end
            App.report("Auto-load: preparing " .. Auto.name(entry) .. "…", "loading")
            local wait = os.clock() + 20
            while not job.Done and os.clock() < wait and App.alive() do task.wait(0.05) end
            local snapshot, err = job.Snapshot, job.Error
            if not job.Done then
                local ok, value, message = pcall(Auto.resolve, entry)
                if ok then snapshot, err = value, message else err = tostring(value) end
            end
            if not snapshot then App.report("Auto-load failed: " .. tostring(err or "unknown error"), "error"); return end
            if App.applySnapshot(snapshot, "apply") and index then
                Store.Auto.Index = index; Auto.LastSwitch = os.clock(); Auto.TimerStart = os.clock(); App.persistState(); Auto.OnChange()
            end
        end)
        Auto.Booting = false
        -- Whatever happened, your character is not left covered.
        Cover.finish()
        if not done then warn("[Lyra Avatar Studio] Auto-load: " .. tostring(problem)) end
    end)
    return true
end

-- A body the game put back while it still wears the copied avatar (see SWAPPED BODIES), or one whose following
-- stopped while the avatar stayed on: nothing is rebuilt, the copier follows it again (the game hiding or resizing
-- it, and the copied items it removes). Returns false when the copied avatar is not on it any more.
function App.rearm(char)
    if not char or not char.Parent or Overlay.visualOnly() or not Appearance.TouchedFor[char] or not App.Current or App.Current.Original then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then return false end
    -- Its body parts are still the ones the copier reshaped (a game that rebuilt the body replaced them).
    if not Appearance.carries(char) then return false end
    S.TouchedChar = char; S.fvOn = true
    if Scale.Factors[char] then Scale.Factor = Scale.Factors[char] end
    if Repair.Character ~= char and not Repair.unpark(char) then Repair.watch(nil, char) end
    Cloak.watch(char); Scale.watch(char)
    App.devNote("The copied avatar is still on your character: following it again (game invisibility and size changes).")
    return true
end
-- Checked every second: while the copied avatar is on your character, the copier follows it (see GAME INVISIBILITY
-- and GAME SIZE CHANGES). Whatever stopped that (a body the game swapped out and back, an application that gave up
-- halfway), it starts again, so an invisibility cloak never leaves the copied hair or items behind.
function App.guardFollow()
    local char = lp.Character
    if App.Busy or not char or not App.Current or App.Current.Original or Overlay.visualOnly() then return end
    if S.appliedChar ~= char or S.TouchedChar ~= char then return end
    if Cloak.Character == char and Scale.Character == char then return end
    if App.rearm(char) then App.trace("Following had stopped on the character wearing the copied avatar; started again.") end
end
F.reapplyNow = function(char, transition)
    if not App.alive() or not App.Current or App.Current.Original or App.CleanReset then return end
    if transition and not Config.MapPersist then return end
    if not transition and not Config.AutoReapply then return end
    -- An application still running (often on the body that was just replaced, which it gives up on as soon as it sees
    -- the new one) is waited for. The new body used to be left with your own avatar.
    local busyUntil = os.clock() + 10
    while App.Busy and App.alive() and char == lp.Character and os.clock() < busyUntil do task.wait(0.1) end
    if not App.alive() or App.Busy or char ~= lp.Character or not App.Current or App.Current.Original or App.CleanReset then return end
    -- A body the game put back that still wears the copied avatar is only followed again (see SWAPPED BODIES); one
    -- whose copied items are gone meanwhile is dressed again.
    local redo = false
    if not transition and S.appliedChar == char then
        if App.rearm(char) then return end
        redo = Appearance.TouchedFor[char] == true and not Overlay.visualOnly()
    end
    local stamp = S.operationSerial
    local visualOnly = Overlay.visualOnly()
    -- Visual-only also follows characters without a Humanoid (Evade).
    local root = char:WaitForChild("HumanoidRootPart", visualOnly and 4 or 8) or (visualOnly and Overlay.rootOf(char))
    local hum = visualOnly and char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 8)
    if (not visualOnly and not hum) or not root or (hum and hum.Health <= 0) or not App.alive() or char ~= lp.Character then return end
    local deadline = os.clock() + 4
    while not lp:HasAppearanceLoaded() and os.clock() < deadline and App.alive() do task.wait() end
    -- Changing the body while the game is still placing and dressing the character could tip it over. The character
    -- is covered meanwhile (see COVER), so this waits only for it to stand.
    if not visualOnly then App.waitSettled(char, 6, 0.5) end
    for _ = 1, 3 do
        if not App.alive() or App.Busy or stamp ~= S.operationSerial or (S.appliedChar == char and not transition and not redo) or char ~= lp.Character
            or not App.Current or App.Current.Original or App.CleanReset then return end
        if App.applySnapshot(App.Current, "reapply", char) then return end
        -- A character that is still loading (or that the game rebuilt meanwhile) is tried again shortly.
        stamp = S.operationSerial
        task.wait(1)
    end
end
F.reapply = function(char, transition)
    local ok, err = pcall(F.reapplyNow, char, transition)
    -- Whatever happened, your character is not left covered.
    Cover.finish(char)
    if not ok then warn("[Lyra Avatar Studio] Reapply: " .. tostring(err)) end
end
RegisterConnection(lp.CharacterAdded:Connect(function(char)
    -- A body the game puts back (see SWAPPED BODIES) is not new: it still carries the copier's changes, and the one
    -- that wore the copied avatar until now is where a swapped-in body takes its scale from.
    local previous = S.TouchedChar
    local back = not Overlay.visualOnly() and Appearance.carries(char)
    if back then
        S.TouchedChar = char
        -- Its own look is the undo base again (not the body that stood in for it).
        local own = App.InitialFor[char]
        if own and App.Initial ~= own then
            if App.Current and App.Current.Original and App.Current == App.Initial then App.Current = own end
            App.Initial = own
        end
    end
    App.SpawnTimes[char] = App.SpawnTimes[char] or os.clock()
    App.trace("Character added: " .. App.traceName(char) .. (back and " (a body the copier changed, back again)" or ""))
    -- A copied avatar goes back on this character: it is covered at once, so your own avatar never shows (see COVER).
    -- A body put back that still wears it is not covered.
    if App.alive() and not App.CleanReset and not (back and S.appliedChar == char)
        and ((App.Current and not App.Current.Original and (Config.AutoReapply or Auto.Pending)) or Auto.Booting) then
        Cover.begin(char, Auto.Booting and 25 or 12)
    end
    -- A new body has the game's own size and transparency again; one put back keeps the scale it had.
    Cloak.stop(); Scale.stop(); Scale.arrived(char, previous)
    -- The emote set in use goes back on the new character's wheel (visual-only never rebuilds the character).
    task.delay(2.5, function() if App.alive() and lp.Character == char and EmoteSets.active() then pcall(EmoteSets.apply) end end)
    Repair.park()
    if not App.alive() then return end
    task.spawn(Auto.watch, char)
    -- Your own avatar gets its saved item adjustments back (see SAVED ADJUSTMENTS).
    task.spawn(Tweaks.watchSelf, char)
    if App.CleanReset then return end
    if not Auto.onRespawn(char) then task.spawn(F.reapply, char, false) end
end))
if lp.Character then task.spawn(Auto.watch, lp.Character) end

-- DEV: CHARACTER LOG. Dev builds only: "/lyralog" in chat records, for the next 3 minutes, what the game does to your
-- character and what the copier does about it, so a game's item or power can be understood from a phone: bodies
-- swapped in and out, body parts added, removed, resized or faded, items and tools put on (with the joints that hold
-- them), the description and scale values, and the copier's own decisions. It also lists the other bodies the game
-- builds (a rhythm game's stage copies, a lobby display): where each one is, whose it was taken for and how visible it
-- is. Written every few seconds to LyraLog_Character.txt in the executor's workspace folder.
function App.logValue(value)
    local kind = typeof(value)
    local function round(n) return math.floor(n + 0.5) end
    if kind == "number" then return string.format("%.3f", value) end
    if kind == "Vector3" then return string.format("(%.2f, %.2f, %.2f)", value.X, value.Y, value.Z) end
    if kind == "CFrame" then
        local rx, ry, rz = value:ToEulerAnglesXYZ()
        return string.format("[%.2f, %.2f, %.2f | %d, %d, %d]", value.X, value.Y, value.Z, round(math.deg(rx)), round(math.deg(ry)), round(math.deg(rz)))
    end
    if kind == "Color3" then return string.format("#%02X%02X%02X", round(value.R * 255), round(value.G * 255), round(value.B * 255)) end
    if kind == "EnumItem" then return value.Name end
    return tostring(value)
end
-- Where item is inside char ("RightHand.RightGripAttachment"), or its log name when it is elsewhere.
function App.logPath(item, char)
    if not item then return "nil" end
    local names, cursor = {}, item
    while cursor and cursor ~= char and #names < 8 do table.insert(names, 1, cursor.Name); cursor = cursor.Parent end
    if cursor ~= char then return "outside " .. App.traceName(item) end
    App.traceName(item)
    return table.concat(names, ".") .. " #" .. tostring(App.Log.Ids[item])
end
-- A joint, constraint or weld: what it joins, its offsets, and what the copier changed on it (see CARRIED ITEMS).
function App.logJoint(joint, char)
    local text = joint.ClassName .. " \"" .. joint.Name .. "\": "
    if joint:IsA("JointInstance") then
        text = text .. App.logPath(joint.Part0, char) .. " -> " .. App.logPath(joint.Part1, char) .. " C0=" .. App.logValue(joint.C0) .. " C1=" .. App.logValue(joint.C1)
    elseif joint:IsA("WeldConstraint") then
        text = text .. App.logPath(joint.Part0, char) .. " -> " .. App.logPath(joint.Part1, char)
    else
        local a, b = joint.Attachment0, joint.Attachment1
        text = text .. (a and (App.logPath(a, char) .. " " .. App.logValue(a.CFrame)) or "nil") .. " -> " .. (b and (App.logPath(b, char) .. " " .. App.logValue(b.CFrame)) or "nil")
    end
    for _, key in ipairs({"Lyra_GameC0", "Lyra_FitC0", "Lyra_GameC1", "Lyra_FitC1"}) do
        local value = joint:GetAttribute(key)
        if value ~= nil then text = text .. " " .. key:sub(6) .. "=" .. App.logValue(value) end
    end
    return text .. " (in " .. App.logPath(joint.Parent, char) .. ")"
end
-- A joint that holds something on the body that is not the copier's: a tool, a game item, an effect.
function App.logCarries(joint, char)
    if not (joint:IsA("JointInstance") or joint:IsA("WeldConstraint") or (joint:IsA("Constraint") and pcall(function() return joint.Attachment0 end))) then return false end
    local accessory = joint:FindFirstAncestorOfClass("Accessory")
    if accessory and accessory:GetAttribute("Copier_CopiedItem") then return false end
    if joint:FindFirstAncestorOfClass("Tool") then return true end
    local a, b
    if joint:IsA("Constraint") then
        a = joint.Attachment0 and joint.Attachment0.Parent; b = joint.Attachment1 and joint.Attachment1.Parent
    else a, b = joint.Part0, joint.Part1 end
    local bodyA, bodyB = a and Appearance.isBody(a, char), b and Appearance.isBody(b, char)
    return (bodyA and not bodyB) or (bodyB and not bodyA) or false
end
function App.logState(char)
    local current = App.Current
    return string.format("copier: wearing=%s busy=%s applied=%s changed=%s cloak=%s scale=%s factor=%.2f repair=%s visualOnly=%s r15Drawn=%s covered=%s",
        current and (current.Original and "own look" or ("\"" .. tostring(current.Name) .. "\"")) or "nothing", tostring(App.Busy), tostring(S.appliedChar == char),
        tostring(S.TouchedChar == char), tostring(Cloak.Character == char), tostring(Scale.Character == char), Scale.Factor or 1,
        tostring(Repair.Character == char), tostring(Overlay.visualOnly()), tostring(Overlay.Auto == true), tostring(Cover.Char == char))
end
function App.logPart(part)
    local ltm = 0
    pcall(function() ltm = part.LocalTransparencyModifier end)
    local text = string.format("%s size=%s T=%.3f LTM=%.3f %s %s", App.traceName(part), App.logValue(part.Size), part.Transparency, ltm,
        part.Material.Name, App.logValue(part.Color))
    local notes = {}
    if Appearance.TouchedParts[part] then table.insert(notes, "reshaped") end
    for _, key in ipairs({"Lyra_GameSize", "Lyra_SetSize", "Lyra_GameTransparency", "Lyra_BeforeOverlay"}) do
        local value = part:GetAttribute(key)
        if value ~= nil then table.insert(notes, key:sub(6) .. "=" .. App.logValue(value)) end
    end
    return #notes > 0 and (text .. " [" .. table.concat(notes, " ") .. "]") or text
end
function App.logCharacter(char, why)
    local scaleOk, scale = pcall(function() return char:GetScale() end)
    App.trace(string.format("== %s: %s in %s, model scale %s", why, App.traceName(char), char.Parent and char.Parent:GetFullName() or "nil", scaleOk and App.logValue(scale) or "?"))
    App.trace("   " .. App.logState(char))
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        local values = {}
        for _, item in ipairs(hum:GetChildren()) do
            if item:IsA("NumberValue") then table.insert(values, item.Name .. "=" .. App.logValue(item.Value))
            elseif item:IsA("HumanoidDescription") then
                local ok, line = pcall(function()
                    return string.format("description %s height=%.2f width=%.2f depth=%.2f head=%.2f%s", App.traceName(item), item.HeightScale, item.WidthScale,
                        item.DepthScale, item.HeadScale, item:GetAttribute("Lyra_Description") and " (copier's)" or "")
                end)
                if ok then table.insert(values, line) end
            end
        end
        App.trace(string.format("   %s rig=%s health=%.0f hip=%.2f autoScale=%s %s", App.traceName(hum), hum.RigType.Name, hum.Health, hum.HipHeight,
            tostring(hum.AutomaticScalingEnabled), table.concat(values, " ")))
    end
    for _, child in ipairs(char:GetChildren()) do
        if child:IsA("BasePart") then App.trace("   part " .. App.logPart(child))
        elseif child:IsA("Accessory") then
            local handle = child:FindFirstChild("Handle")
            App.trace(string.format("   accessory %s%s handle T=%s on %s", App.traceName(child), child:GetAttribute("Copier_CopiedItem") and " (copied)" or "",
                handle and handle:IsA("BasePart") and App.logValue(handle.Transparency) or "?", tostring(Cloak.mountOf(child, char) or "?")))
        else App.trace("   " .. App.traceName(child)) end
    end
    for _, joint in ipairs(char:GetDescendants()) do
        if App.logCarries(joint, char) then App.trace("   joint " .. App.logJoint(joint, char)) end
    end
end
Fit.Trace = function(joint, body, field, before, after, note)
    if not App.tracing() then return end
    local item = field == "C0" and joint.Part1 or joint.Part0
    App.trace(string.format("Fit moved %s on %s: %s %s -> %s", item and App.traceName(item) or "?", body.Name, field, App.logValue(before), App.logValue(after))
        .. " (joint " .. App.traceName(joint) .. ")" .. (note and (": " .. note) or ""))
end
function App.startLog()
    if type(writefile) ~= "function" then App.report("This executor can't write files.", "warning"); return end
    local log = App.Log
    log.Until = os.clock() + 180
    if log.Running then App.report("Character log: 3 more minutes.", "info"); return end
    log.Running = true; log.Start = os.clock(); table.clear(log.Lines); log.Dirty = true
    App.report("Character log on for 3 minutes: do what goes wrong (a potion, a cloak, a tool), then wait 5 seconds.", "info")
    local connections, followed, pending = {}, setmetatable({}, {__mode = "k"}), {}
    local function on(signal, callback)
        local ok, connection = pcall(function() return signal:Connect(function(...) if App.tracing() then pcall(callback, ...) end end) end)
        if ok then table.insert(connections, connection) end
    end
    -- One line per change at most every gap seconds, with the newest value.
    local function later(key, gap, callback)
        if pending[key] then return end
        pending[key] = true
        task.delay(gap, function() pending[key] = nil; if App.tracing() then pcall(callback) end end)
    end
    local function watchPart(part, char, carried)
        local name = App.traceName(part)
        for _, property in ipairs(carried and {"Transparency", "Size"} or {"Size", "Transparency", "LocalTransparencyModifier", "Material", "Color"}) do
            on(part:GetPropertyChangedSignal(property), function()
                later(name .. property, property == "LocalTransparencyModifier" and 0.4 or 0.15, function()
                    App.trace(string.format("%s %s = %s%s", name, property, App.logValue(part[property]), part.Parent == char and "" or " (not in the character)"))
                end)
            end)
        end
    end
    local function watchItem(item, char)
        if item:IsA("BasePart") and Appearance.isBody(item, char) then watchPart(item, char, false)
        elseif item:IsA("Accessory") or item:IsA("Tool") then
            for _, part in ipairs(item:GetDescendants()) do if part:IsA("BasePart") then watchPart(part, char, true) end end
        end
    end
    local function follow(char)
        if not char or followed[char] then return end
        followed[char] = true
        App.logCharacter(char, "Character")
        for _, child in ipairs(char:GetChildren()) do watchItem(child, char) end
        on(char.AncestryChanged, function() App.trace(App.traceName(char) .. " moved to " .. (char.Parent and char.Parent:GetFullName() or "nil")) end)
        on(char.ChildAdded, function(child)
            App.trace("Added to " .. App.traceName(char) .. ": " .. (child:IsA("BasePart") and App.logPart(child) or App.traceName(child))
                .. (child:GetAttribute("Copier_CopiedItem") and " (copier's)" or ""))
            watchItem(child, char)
            if child:IsA("Tool") then
                task.delay(0.6, function()
                    if not App.tracing() or child.Parent ~= char then return end
                    for _, part in ipairs(child:GetDescendants()) do if part:IsA("BasePart") then App.trace("   tool part " .. App.logPath(part, char) .. " " .. App.logPart(part)) end end
                    for _, joint in ipairs(char:GetDescendants()) do if App.logCarries(joint, char) then App.trace("   joint " .. App.logJoint(joint, char)) end end
                end)
            end
        end)
        on(char.ChildRemoved, function(child) App.trace("Removed from " .. App.traceName(char) .. ": " .. App.traceName(child)) end)
        on(char.DescendantAdded, function(item)
            if item:IsA("JointInstance") or item:IsA("WeldConstraint") or item:IsA("Constraint") then
                task.delay(0.2, function() if App.tracing() and item:IsDescendantOf(char) and App.logCarries(item, char) then App.trace("New joint " .. App.logJoint(item, char)) end end)
            elseif item:IsA("Highlight") or item:IsA("ForceField") or item:IsA("SurfaceAppearance") or item:IsA("HumanoidDescription") then
                App.trace("New " .. App.traceName(item) .. " in " .. App.logPath(item.Parent, char))
            end
        end)
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            on(hum:GetPropertyChangedSignal("HipHeight"), function() later(App.traceName(hum) .. "hip", 0.15, function() App.trace("HipHeight = " .. App.logValue(hum.HipHeight)) end) end)
            for _, item in ipairs(hum:GetChildren()) do
                if item:IsA("NumberValue") then on(item.Changed, function() App.trace(item.Name .. " = " .. App.logValue(item.Value)) end) end
            end
        end
    end
    on(lp:GetPropertyChangedSignal("Character"), function()
        App.trace("Player.Character = " .. (lp.Character and App.traceName(lp.Character) or "nil"))
        if lp.Character then task.delay(0.3, function() if App.tracing() then follow(lp.Character) end end) end
    end)
    local camera = workspace.CurrentCamera
    if camera then
        on(camera:GetPropertyChangedSignal("CameraSubject"), function()
            local subject = camera.CameraSubject
            App.trace("Camera follows " .. (subject and (App.traceName(subject) .. " of " .. (subject.Parent and App.traceName(subject.Parent) or "nil")) or "nothing"))
        end)
    end
    App.trace(string.format("Settings: AutoReapply=%s HideOriginal=%s GameChange=%s VisualOnly=%s MapPersist=%s",
        tostring(Config.AutoReapply), tostring(Store.Settings.HideOriginal), tostring(Store.Settings.GameChange), tostring(Store.Settings.VisualOnly), tostring(Config.MapPersist)))
    follow(lp.Character)
    -- Bodies the game builds besides the characters (a rhythm game's stage copies, a lobby display): where each one
    -- is, whose it was taken for and how visible its body is, when the log starts, as they appear and 3 s later. At
    -- most 40 of them, for games full of NPCs.
    local bodies = 0
    local function bodyLine(model)
        local parts, least = 0, 1
        for _, part in ipairs(model:GetChildren()) do
            if part:IsA("BasePart") and S.BD[part.Name] and part.Name ~= "HumanoidRootPart" then parts = parts + 1; least = math.min(least, part.Transparency) end
        end
        local root, mine = Overlay.rootOf(model), lp.Character and Overlay.rootOf(lp.Character)
        local who, dressed = Mirror.Known[model], Mirror.Dressed[model]
        return string.format("%s in %s: %s, %d body parts, least transparency %.2f, %s studs from you, %s%s", App.traceName(model),
            model.Parent and model.Parent:GetFullName() or "nil", tostring(F.getTrueRigType(model)), parts, parts > 0 and least or 0,
            (root and mine) and string.format("%.0f", (root.Position - mine.Position).Magnitude) or "?",
            who == nil and "not taken for a player" or who == lp.UserId and "taken for you" or "taken for a script user",
            dressed and (dressed.Drawn and ", avatar drawn over it" or ", dressed") or "")
    end
    local function body(model, why)
        if bodies >= 40 or not model:IsA("Model") or followed[model] or model == lp.Character or Players:GetPlayerFromCharacter(model)
            or (Overlay.Folder and model:IsDescendantOf(Overlay.Folder)) then return end
        followed[model] = true; bodies = bodies + 1
        App.trace(why .. " " .. bodyLine(model))
        task.delay(3, function() if App.tracing() and model.Parent then App.trace("   3 s later: " .. bodyLine(model)) end end)
    end
    for model in pairs(Mirror.Seen) do if model.Parent then pcall(body, model, "Body already there:") end end
    on(workspace.DescendantAdded, function(item)
        if item:IsA("Humanoid") then task.delay(0.5, function() if App.tracing() and item.Parent then pcall(body, item.Parent, "New body:") end end) end
    end)
    task.spawn(function()
        local executor = "?"
        pcall(function() executor = tostring((identifyexecutor())) end)
        local header = string.format("Avatar Studio character log · dev %s · place %d · game %d · %s · %s\n",
            tostring(rawget(_G, "LyraDevBuild")), game.PlaceId, game.GameId, executor, os.date("!%Y-%m-%d %H:%M:%S"))
        local lastState = 0
        while App.alive() and App.tracing() do
            task.wait(2)
            -- The copier's state every 10 seconds, so a change without an event still shows.
            if os.clock() - lastState >= 10 and lp.Character then lastState = os.clock(); App.trace(App.logState(lp.Character)) end
            if log.Dirty then log.Dirty = false; pcall(writefile, "LyraLog_Character.txt", header .. table.concat(log.Lines, "\n")) end
        end
        for _, connection in ipairs(connections) do pcall(function() connection:Disconnect() end) end
        pcall(writefile, "LyraLog_Character.txt", header .. table.concat(log.Lines, "\n"))
        log.Running = false
        if App.alive() then App.report("Character log written: LyraLog_Character.txt (" .. #log.Lines .. " lines).", "success") end
    end)
end
-- DEV: DEBUG CAPTURE (the Debug page, dev builds only). Saves everything about this game, your character and what the
-- copier did to it in the executor's workspace folder, "lyra debug/<game> debug", so a game's bug is fixed from what
-- really happened there instead of from guesses:
--   the character's whole tree (parts with sizes and places, accessories with attachments, welds and meshes, joints,
--   scripts by name, attributes), the Humanoid with its scale values and state, the game's description, Animate and
--   the animations playing; your own avatar for comparison; the copier's state (what it wears, what it set aside and
--   why, sizes, the drawn avatar and how it follows); the nearest other players' characters; the copier's log.
-- A recording also writes everything that happens to the character for a while (items added and removed, sizes,
-- transparencies, states, animations started), a sample each second and the state at its start and end.
-- Each save is a .json (the data) and a summary .txt (the main points, readable on a phone).
local Debug = {Options = {Others = true}, Saved = {}}
function Debug.enabled()
    local build = rawget(_G, "LyraDevBuild")
    return type(build) == "string" and build ~= ""
end
-- A value JSON can hold: numbers rounded, vectors and places as lists, colours as hex, instances as paths.
function Debug.value(value, char)
    local kind = typeof(value)
    if kind == "number" then
        if value ~= value or value == math.huge or value == -math.huge then return tostring(value) end
        return math.floor(value * 1000 + 0.5) / 1000
    elseif kind == "string" or kind == "boolean" then return value
    elseif kind == "Vector3" then return {Debug.value(value.X), Debug.value(value.Y), Debug.value(value.Z)}
    elseif kind == "Vector2" then return {Debug.value(value.X), Debug.value(value.Y)}
    elseif kind == "CFrame" then
        local rx, ry, rz = value:ToEulerAnglesXYZ()
        return {Debug.value(value.X), Debug.value(value.Y), Debug.value(value.Z), Debug.value(math.deg(rx)), Debug.value(math.deg(ry)), Debug.value(math.deg(rz))}
    elseif kind == "Color3" then
        return string.format("#%02X%02X%02X", math.floor(value.R * 255 + 0.5), math.floor(value.G * 255 + 0.5), math.floor(value.B * 255 + 0.5))
    elseif kind == "EnumItem" then return value.Name
    elseif kind == "Instance" then return Debug.path(value, char)
    elseif value == nil then return nil end
    return tostring(value)
end
-- Where item is: inside char from it ("Head/HairAttachment"), else its full name.
function Debug.path(item, char)
    if not item then return nil end
    local names, cursor = {}, item
    while cursor and cursor ~= char and #names < 12 do table.insert(names, 1, cursor.Name); cursor = cursor.Parent end
    if char and cursor == char then return #names > 0 and table.concat(names, "/") or "." end
    local ok, full = pcall(function() return item:GetFullName() end)
    return ok and full or item.Name
end
Debug.Props = {
    {"BasePart", {"Size", "Transparency", "LocalTransparencyModifier", "CanCollide", "Massless", "Anchored", "Color", "Material", "RootPriority"}},
    {"MeshPart", {"MeshId", "TextureID"}},
    {"SpecialMesh", {"MeshId", "TextureId", "MeshType", "Scale", "Offset"}},
    {"Attachment", {"CFrame"}},
    {"JointInstance", {"Part0", "Part1", "C0", "C1", "Enabled"}},
    {"Motor6D", {"Transform"}},
    {"WeldConstraint", {"Part0", "Part1", "Enabled"}},
    {"Constraint", {"Attachment0", "Attachment1", "Enabled"}},
    {"AnimationConstraint", {"Transform"}},
    {"Accessory", {"AccessoryType", "AttachmentPoint"}},
    {"WrapLayer", {"Order", "Enabled"}},
    {"Decal", {"Texture", "Transparency", "Face"}},
    {"Shirt", {"ShirtTemplate"}}, {"Pants", {"PantsTemplate"}}, {"ShirtGraphic", {"Graphic"}},
    {"BodyColors", {"HeadColor3", "TorsoColor3", "LeftArmColor3", "RightArmColor3", "LeftLegColor3", "RightLegColor3"}},
    {"ValueBase", {"Value"}},
    {"Animation", {"AnimationId"}},
    {"Highlight", {"Adornee", "Enabled", "FillColor", "FillTransparency", "OutlineColor", "OutlineTransparency", "DepthMode"}},
    {"Humanoid", {"RigType", "HipHeight", "Health", "MaxHealth", "WalkSpeed", "JumpPower", "AutomaticScalingEnabled", "RequiresNeck",
        "BreakJointsOnDeath", "PlatformStand", "Sit", "EvaluateStateMachine", "CameraOffset", "DisplayName"}},
    {"BaseScript", {"Enabled"}},
}
-- One instance and what is in it (count is shared, so a huge model stops at limit).
function Debug.node(item, char, count, limit, depth)
    count.n = count.n + 1
    local node = {Class = item.ClassName, Name = item.Name}
    for _, row in ipairs(Debug.Props) do
        if item:IsA(row[1]) then
            for _, property in ipairs(row[2]) do
                local ok, value = pcall(function() return item[property] end)
                if ok and value ~= nil then node[property] = Debug.value(value, char) end
            end
        end
    end
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if item:IsA("BasePart") and root and root:IsA("BasePart") then node.Place = Debug.value(root.CFrame:ToObjectSpace(item.CFrame)) end
    if item:IsA("Humanoid") then
        pcall(function() node.State = item:GetState().Name end)
    elseif item:IsA("Accessory") then
        node.Copied = item:GetAttribute("Copier_CopiedItem") ~= nil
        node.AvatarItem = Appearance.avatarItem(item)
        node.Yours = Appearance.ownItem(item)
        node.Mesh = F.meshKey(Appearance.handleOf(item))
    elseif item:IsA("HumanoidDescription") then
        node.Description = Debug.description(item)
    end
    local attributes = item:GetAttributes()
    if next(attributes) then
        node.Attributes = {}
        for key, value in pairs(attributes) do node.Attributes[key] = Debug.value(value, char) end
    end
    local children = item:GetChildren()
    if #children > 0 then
        if depth >= 14 or count.n >= limit then
            node.More = #children
        else
            node.Children = {}
            for _, child in ipairs(children) do
                if count.n >= limit then node.More = (node.More or 0) + 1
--|YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
                else table.insert(node.Children, Debug.node(child, char, count, limit, depth + 1)) end
            end
        end
    end
    return node
end
function Debug.tree(model, limit)
    if not model then return nil end
    local count = {n = 0}
    local tree = Debug.node(model, model, count, limit or 4000, 0)
    tree.Count = count.n
    return tree
end
function Debug.description(desc)
    local out = {}
    for _, fields in ipairs({Codec.scaleFields, Codec.assetFields, Codec.accessoryFields}) do
        for _, field in ipairs(fields) do
            local ok, value = pcall(function() return desc[field] end)
            if ok then out[field] = Debug.value(value) end
        end
    end
    pcall(function()
        out.Accessories = {}
        for _, row in ipairs(desc:GetAccessories(true)) do
            table.insert(out.Accessories, {AssetId = row.AssetId, Type = Debug.value(row.AccessoryType), Layered = row.IsLayered == true})
        end
    end)
    return out
end
-- Animate's folders and every animation playing on the character, with how the copier reads each one.
function Debug.animations(char)
    local out = {Animate = {}, Playing = {}}
    local animate = char:FindFirstChild("Animate")
    if animate then
        out.AnimateClass = animate.ClassName
        for _, folder in ipairs(animate:GetChildren()) do
            local list = {}
            for _, item in ipairs(folder:GetDescendants()) do
                if item:IsA("Animation") then
                    local weight = item:FindFirstChild("Weight")
                    table.insert(list, {Name = item.Name, Id = item.AnimationId, Weight = weight and weight:IsA("NumberValue") and weight.Value or nil,
                        Default = F.DefaultAnimIds[F.normalizeAnimId(item.AnimationId)] == true})
                end
            end
            if #list > 0 then out.Animate[folder.Name] = list end
        end
    end
    for _, animator in ipairs(char:GetDescendants()) do
        if animator:IsA("Animator") then
            local ok, tracks = pcall(function() return animator:GetPlayingAnimationTracks() end)
            for _, track in ipairs(ok and tracks or {}) do
                pcall(function()
                    local id = track.Animation and F.normalizeAnimId(track.Animation.AnimationId) or ""
                    table.insert(out.Playing, {Animator = Debug.path(animator, char), Id = id, Name = track.Name,
                        Animation = track.Animation and Debug.path(track.Animation, char) or nil, Priority = track.Priority.Name,
                        Weight = Debug.value(track.WeightCurrent), Speed = Debug.value(track.Speed), Time = Debug.value(track.TimePosition),
                        Length = Debug.value(track.Length), Looped = track.Looped, Animate = F.isAnimateTrack(track, animate),
                        Default = F.DefaultAnimIds[id] == true, GameMove = Overlay.gameMove(track)})
                end)
            end
        end
    end
    return out
end
local function debugKeys(set)
    local list = {}
    for key in pairs(set or {}) do table.insert(list, tostring(key)) end
    table.sort(list)
    return list
end
local function debugLook(snapshot)
    if type(snapshot) ~= "table" then return nil end
    local data = type(snapshot.Data) == "table" and snapshot.Data or {}
    local props = type(data.Properties) == "table" and data.Properties or data
    local scales = {}
    for _, field in ipairs(Codec.scaleFields) do scales[field] = Debug.value(props[field]) end
    return {Name = snapshot.Name, Id = snapshot.Id, Original = snapshot.Original == true, GameLook = snapshot.GameLook == true,
        Skin = type(data.Visual) == "table", SkinRig = type(data.Visual) == "table" and data.Visual.RigType or nil, Scales = scales,
        Accessories = type(data.Accessories) == "table" and #data.Accessories or nil}
end
-- The copier's own state for char: what it wears, what it set aside, sizes and the avatar drawn over the character.
function Debug.copier(char)
    local out = {Busy = App.Busy, VisualOnly = Overlay.visualOnly(), BodyGame = Overlay.BodyGames[game.GameId] == true,
        OverlayAuto = Overlay.Auto == true, AutoDeclined = Overlay.AutoDeclined[game.GameId] == true,
        Current = debugLook(App.Current), Initial = debugLook(App.Initial), History = #App.History,
        TouchedChar = char ~= nil and S.TouchedChar == char, AppliedChar = char ~= nil and S.appliedChar == char,
        Scale = {Factor = Debug.value(Scale.Factor), Base = char and Debug.value(Scale.Bases[char]) or nil},
        OwnAccessoryNames = debugKeys(S.ownAvatarNames), GameAccessoryNames = debugKeys(S.gameAccNames), KnownAsYours = debugKeys(S.ownAccNames),
        OwnMeshes = debugKeys(S.ownAccMeshes), OwnPartSizes = {}, Stash = {}, RepairRows = #Repair.Rows}
    for rig, sizes in pairs(S.ownPartSizes or {}) do
        out.OwnPartSizes[rig] = {}
        for name, size in pairs(sizes) do out.OwnPartSizes[rig][name] = Debug.value(size) end
    end
    if char then
        pcall(function() out.Scale.GameFactorNow = Debug.value(Scale.gameFactor(char)) end)
        local values = Scale.GameValues[char]
        if values then
            out.Scale.GameValues = {}
            for field, value in pairs(values) do out.Scale.GameValues[field] = Debug.value(value) end
        end
        for _, item in ipairs(Appearance.Stash[char] or {}) do
            local from = Appearance.StashedFrom[item]
            table.insert(out.Stash, {Name = item.Name, Class = item.ClassName, From = from and Debug.path(from, char) or ".", Back = item.Parent ~= nil})
        end
        local entry = Overlay.Active[char]
        if entry then
            local limbs = {}
            for _, limb in ipairs(entry.Limbs or {}) do
                table.insert(limbs, {Key = limb.Key, Real = limb.RealName, RealJoint = limb.RealJoint and Debug.path(limb.RealJoint, char) or nil,
                    Loose = limb.RealJoint == nil or Overlay.looseJoint(limb.RealJoint), Transform = Debug.value(limb.Joint.Transform)})
            end
            local tracks = {}
            for key, track in pairs(entry.Puppet and entry.Puppet.Tracks or {}) do
                if track and track.IsPlaying then table.insert(tracks, key) end
            end
            out.Overlay = {Mode = entry.Mode, Loose = entry.Loose == true, GameMoves = entry.GameMoves == true, Lit = entry.Lit == true,
                Stiff = entry.Stiff == true, ForceParts = entry.ForceParts == true, Found = entry.Found == true,
                Target = entry.Target and Debug.path(entry.Target, char) or nil, Lift = Debug.value(entry.Lift),
                ArmBlend = Debug.value(entry.ArmBlend or 0), BodyBlend = Debug.value(entry.BodyBlend or 0), Limbs = limbs, PuppetTracks = tracks,
                Hidden = #debugKeys(entry.Hidden), Model = Debug.tree(entry.Model, 1500)}
        end
    end
    return out
end
-- The game's name as a folder can hold it: no event tags in brackets, emoji or characters a file name can't have.
function Debug.gameName()
    if Debug.Name then return Debug.Name end
    local ok, info = pcall(function() return MPS:GetProductInfo(game.PlaceId) end)
    local name = ok and type(info) == "table" and tostring(info.Name or "") or ""
    name = name:gsub("%b[]", ""):gsub("%b()", ""):gsub("[\240-\247][\128-\191][\128-\191][\128-\191]", ""):gsub("[%c\\/:%*%?\"<>|]", "")
    name = name:gsub("%s+", " "):match("^%s*(.-)%s*$"):sub(1, 60)
    if name == "" then name = "Place " .. tostring(game.PlaceId) end
    Debug.Name = name
    return name
end
function Debug.folder()
    return "lyra debug/" .. Debug.gameName() .. " debug"
end
-- Everything at this moment.
function Debug.capture(why)
    local char = lp.Character
    local executor = "?"
    pcall(function() executor = tostring((identifyexecutor())) end)
    local data = {
        Capture = {Why = why, Version = Debug.Version, DevBuild = tostring(rawget(_G, "LyraDevBuild")), Time = os.date("!%Y-%m-%d %H:%M:%S"),
            Executor = executor, Game = Debug.gameName(), PlaceId = game.PlaceId, GameId = game.GameId, JobId = game.JobId,
            PlaceVersion = game.PlaceVersion, Players = #Players:GetPlayers(), Camera = Debug.value(workspace.CurrentCamera and workspace.CurrentCamera.CameraSubject)},
        Settings = {},
        Copier = Debug.copier(char),
        Character = char and Debug.tree(char) or nil,
        Animations = char and Debug.animations(char) or nil,
        Starter = {},
        Others = {},
        Log = {},
    }
    for key, value in pairs(Store.Settings) do
        local kind = type(value)
        if kind == "boolean" or kind == "number" or (kind == "string" and #value < 200) then data.Settings[key] = value end
    end
    pcall(function()
        local starter = game:GetService("StarterPlayer")
        data.Starter.StarterCharacter = starter:FindFirstChild("StarterCharacter") ~= nil
        data.Starter.CharacterScripts = {}
        for _, item in ipairs(starter:FindFirstChildOfClass("StarterCharacterScripts") and starter:FindFirstChildOfClass("StarterCharacterScripts"):GetChildren() or {}) do
            table.insert(data.Starter.CharacterScripts, item.ClassName .. " " .. item.Name)
        end
        data.Starter.LoadCharacterAppearance = starter.LoadCharacterAppearance
        data.Starter.CharacterAutoLoads = Players.CharacterAutoLoads
    end)
    -- The nearest other players: how the game builds a character it leaves alone.
    if Debug.Options.Others and char then
        local root = Overlay.rootOf(char)
        local list = {}
        for _, player in ipairs(Players:GetPlayers()) do
            local other = player ~= lp and player.Character
            local otherRoot = other and Overlay.rootOf(other)
            if otherRoot and root then table.insert(list, {other, (otherRoot.Position - root.Position).Magnitude}) end
        end
        table.sort(list, function(a, b) return a[2] < b[2] end)
        for index = 1, math.min(2, #list) do
            table.insert(data.Others, {Distance = Debug.value(list[index][2]), Character = Debug.tree(list[index][1], 1500), Animations = Debug.animations(list[index][1])})
        end
    end
    -- What else draws your body: the models in the camera (first-person arms, a body only on your screen), the copies
    -- of you the stand-ins know and the ones the drawn avatar hides, with what the camera is doing.
    pcall(function()
        local camera = workspace.CurrentCamera
        data.Camera = {Type = camera and camera.CameraType.Name, FieldOfView = camera and Debug.value(camera.FieldOfView),
            FocusDistance = camera and Debug.value((camera.CFrame.Position - camera.Focus.Position).Magnitude), Models = {}}
        for _, child in ipairs(camera and camera:GetChildren() or {}) do
            if child ~= Overlay.Folder and (child:IsA("Model") or child:IsA("Folder")) and #data.Camera.Models < 4 then
                table.insert(data.Camera.Models, {Name = child.Name, Class = child.ClassName, Tree = Debug.tree(child, 300)})
            end
        end
        data.StandIns = {}
        for model, who in pairs(Mirror.Known) do
            if #data.StandIns >= 12 then break end
            local okEligible, hum, why = pcall(Mirror.eligible, model, true)
            table.insert(data.StandIns, {Path = model:GetFullName():sub(1, 200), Who = Debug.value(who), Dressed = Mirror.Dressed[model] ~= nil,
                Eligible = okEligible and hum ~= nil, Why = why and tostring(why) or nil, InCamera = camera ~= nil and model:IsDescendantOf(camera)})
        end
        local entry = char and Overlay.Active[char]
        if entry then
            data.Copier.Overlay = data.Copier.Overlay or {}
            data.Copier.Overlay.Inside = entry.Inside == true
            data.Copier.Overlay.Extra = {}
            for _, model in ipairs(entry.Extra or {}) do table.insert(data.Copier.Overlay.Extra, model:GetFullName():sub(1, 200)) end
        end
    end)
    -- The Roblox menu's pictures (see DEBUG, THE ROBLOX MENU).
    local menuOk, menu = pcall(function() return Debug.menu() end)
    data.Menu = menuOk and menu or {Error = tostring(menu)}
    local lines = App.Log.Lines
    for index = math.max(1, #lines - 3000), #lines do table.insert(data.Log, lines[index]) end
    return data
end
-- The main points, readable on a phone.
function Debug.summary(data, timeline)
    local out = {}
    local function add(text) table.insert(out, text) end
    local c = data.Capture
    add(string.format("Avatar Studio debug · %s · %s · dev %s", tostring(c.Version), tostring(c.Time), tostring(c.DevBuild)))
    add(string.format("Game: %s (place %s, game %s) · executor %s", tostring(c.Game), tostring(c.PlaceId), tostring(c.GameId), tostring(c.Executor)))
    local copier = data.Copier
    add(string.format("Wearing: %s · visual-only %s%s · touched %s · scale %s (base %s, game now %s)",
        copier.Current and tostring(copier.Current.Name) or "nothing", tostring(copier.VisualOnly), copier.BodyGame and " (always off here)" or "",
        tostring(copier.TouchedChar), tostring(copier.Scale.Factor), tostring(copier.Scale.Base), tostring(copier.Scale.GameFactorNow)))
    if copier.Scale.GameValues then
        local values = {}
        for field, value in pairs(copier.Scale.GameValues) do table.insert(values, field .. " " .. tostring(value)) end
        table.sort(values)
        add("The game's scale values: " .. table.concat(values, ", "))
    end
    if copier.Overlay then
        local o = copier.Overlay
        add(string.format("Drawn avatar: %s · loose %s · game moves %s · highlight %s · puppet tracks %d", tostring(o.Mode), tostring(o.Loose),
            tostring(o.GameMoves), tostring(o.Lit), #o.PuppetTracks))
    end
    local char = data.Character
    if char then
        add("Character: " .. tostring(char.Count) .. " instances")
        for _, child in ipairs(char.Children or {}) do
            if child.Class == "Accessory" then
                add(string.format("  accessory %s · yours %s · avatar item %s · copied %s · mesh %s", child.Name, tostring(child.Yours), tostring(child.AvatarItem),
                    tostring(child.Copied), tostring(child.Mesh)))
            elseif child.Size then
                add(string.format("  %s %s size %s T=%s", child.Class, child.Name, table.concat(child.Size, " x "), tostring(child.Transparency)))
            elseif child.Class == "Humanoid" then
                add(string.format("  Humanoid %s state %s hip %s autoscale %s", tostring(child.RigType), tostring(child.State), tostring(child.HipHeight), tostring(child.AutomaticScalingEnabled)))
            else
                add("  " .. child.Class .. " " .. child.Name)
            end
        end
    end
    if #copier.Stash > 0 then
        local names = {}
        for _, row in ipairs(copier.Stash) do table.insert(names, row.Name .. (row.Back and " (back on!)" or "")) end
        add("Set aside: " .. table.concat(names, ", "))
    end
    for _, track in ipairs(data.Animations and data.Animations.Playing or {}) do
        add(string.format("Playing %s (%s) weight %s · Animate %s · default %s · game move %s", tostring(track.Id), tostring(track.Name), tostring(track.Weight),
            tostring(track.Animate), tostring(track.Default), tostring(track.GameMove)))
    end
    local printedCards = {}
    if data.MenuShots then
        for _, shot in ipairs(data.MenuShots) do
            add(string.format("Menu %d s after it opened:", shot.T))
            if shot.Menu.Error then add("  error " .. shot.Menu.Error) else pcall(Debug.menuLines, shot.Menu, add, printedCards) end
        end
    elseif data.Menu and data.Menu.Pictures then
        pcall(Debug.menuLines, data.Menu, add, printedCards)
    end
    if timeline then add("Timeline: " .. #timeline .. " events (see the .json)") end
    return table.concat(out, "\n")
end
function Debug.write(kind, data, timeline)
    assert(type(writefile) == "function", "This executor can't write files.")
    local folder = Debug.folder()
    pcall(makefolder, "lyra debug"); pcall(makefolder, folder)
    local stamp = os.date("!%Y-%m-%d %H-%M-%S")
    local base = folder .. "/" .. stamp .. " " .. kind
    local text = HttpService:JSONEncode(data)
    writefile(base .. ".json", text)
    writefile(base .. " summary.txt", Debug.summary(kind == "record" and data.End or data, timeline))
    table.insert(Debug.Saved, 1, {File = base .. ".json", Bytes = #text})
    while #Debug.Saved > 5 do table.remove(Debug.Saved) end
    return base .. ".json", #text
end
-- Yields. Saves a capture now.
function Debug.saveNow()
    local ok, file, bytes = pcall(function() return Debug.write("capture", Debug.capture("capture")) end)
    if ok then App.report(string.format("Debug capture saved: %s (%d KB).", file, math.ceil(bytes / 1024)), "success")
    else App.report("The debug capture could not be saved: " .. tostring(file), "error") end
    return ok
end
-- Yields until done. Records seconds of what happens to your character, then saves it with the state at its start and
-- end. tick(left) is called every second; Debug.Recording.Stop ends it early.
function Debug.record(seconds, tick)
    if Debug.Recording then return false end
    local recording = {Stop = false}
    Debug.Recording = recording
    local log = App.Log
    if not log.Running then table.clear(log.Lines); log.Start = os.clock() end
    log.Until = math.max(log.Until, os.clock() + seconds + 2)
    local start = os.clock()
    local first = Debug.capture("record start")
    local events, samples, connections, followed, throttled = {}, {}, {}, setmetatable({}, {__mode = "k"}), setmetatable({}, {__mode = "k"})
    local function now() return math.floor((os.clock() - start) * 100 + 0.5) / 100 end
    local function add(kind, item, char, detail)
        if #events >= 6000 then return end
        table.insert(events, {T = now(), Kind = kind, Path = item and Debug.path(item, char) or nil, Class = item and item.ClassName or nil, Detail = detail})
    end
    local function on(signal, callback)
        local ok, connection = pcall(function() return signal:Connect(function(...) pcall(callback, ...) end) end)
        if ok then table.insert(connections, connection) end
    end
    local function watchProperty(item, char, property)
        on(item:GetPropertyChangedSignal(property), function()
            -- One event per property every 0.15 s at most, with the newest value.
            local pending = throttled[item]
            if not pending then pending = {}; throttled[item] = pending end
            if pending[property] then return end
            pending[property] = true
            task.delay(0.15, function()
                pending[property] = nil
                if not recording.Done then add("changed", item, char, property .. " = " .. HttpService:JSONEncode({Debug.value(item[property], char)})) end
            end)
        end)
    end
    local function watchItem(item, char)
        if item:IsA("BasePart") then
            for _, property in ipairs({"Size", "Transparency", "LocalTransparencyModifier"}) do watchProperty(item, char, property) end
        elseif item:IsA("NumberValue") and item.Parent and item.Parent:IsA("Humanoid") then
            watchProperty(item, char, "Value")
        elseif item:IsA("Animator") then
            on(item.AnimationPlayed, function(track)
                local id = track.Animation and F.normalizeAnimId(track.Animation.AnimationId) or ""
                add("animation", track.Animation, char, string.format("%s priority %s · Animate %s · default %s", id, track.Priority.Name,
                    tostring(F.isAnimateTrack(track, char:FindFirstChild("Animate"))), tostring(F.DefaultAnimIds[id] == true)))
            end)
        elseif item:IsA("Humanoid") then
            on(item.StateChanged, function(old, new) add("state", item, char, old.Name .. " -> " .. new.Name) end)
            watchProperty(item, char, "HipHeight")
        elseif item:IsA("HumanoidDescription") then
            on(item.Changed, function(property) add("description", item, char, property) end)
        end
    end
    local function follow(char)
        if not char or followed[char] then return end
        followed[char] = true
        add("character", char, nil, "followed")
        -- One item the executor can't watch (a missing signal) never stops the recording.
        for _, item in ipairs(char:GetDescendants()) do pcall(watchItem, item, char) end
        on(char.DescendantAdded, function(item)
            local detail = "in " .. tostring(Debug.path(item.Parent, char))
            if item:IsA("Accessory") then detail = detail .. (item:GetAttribute("Copier_CopiedItem") and " (copier's)" or "") end
            add("added", item, char, detail)
            pcall(watchItem, item, char)
        end)
        on(char.DescendantRemoving, function(item) add("removed", item, char, nil) end)
    end
    follow(lp.Character)
    on(lp.CharacterAdded, function(char) add("respawn", char, nil, nil); task.delay(0.2, function() follow(char) end) end)
    while not recording.Stop and os.clock() - start < seconds and App.alive() do
        task.wait(1)
        local char = lp.Character
        if char then
            local sample = {T = now(), Parts = {}, Playing = {}, Accessories = {}}
            for _, name in ipairs({"HumanoidRootPart", "Torso", "UpperTorso", "LowerTorso", "Head"}) do
                local part = char:FindFirstChild(name)
                if part and part:IsA("BasePart") then sample.Parts[name] = Debug.value(part.Size) end
            end
            for _, child in ipairs(char:GetChildren()) do if child:IsA("Accessory") then table.insert(sample.Accessories, child.Name) end end
            local animations = Debug.animations(char)
            for _, track in ipairs(animations.Playing) do table.insert(sample.Playing, track.Id .. " " .. tostring(track.Weight)) end
            local entry = Overlay.Active[char]
            if entry then sample.Overlay = {Mode = entry.Mode, Loose = entry.Loose == true, GameMoves = entry.GameMoves == true, Lit = entry.Lit == true} end
            table.insert(samples, sample)
        end
        if tick then pcall(tick, math.max(0, math.ceil(seconds - (os.clock() - start)))) end
    end
    recording.Done = true
    for _, connection in ipairs(connections) do pcall(function() connection:Disconnect() end) end
    local data = {Start = first, Timeline = events, Samples = samples, End = Debug.capture("record end")}
    local ok, file, bytes = pcall(Debug.write, "record", data, events)
    Debug.Recording = nil
    if ok then App.report(string.format("Debug recording saved: %s (%d events, %d KB).", file, #events, math.ceil(bytes / 1024)), "success")
    else App.report("The debug recording could not be saved: " .. tostring(file), "error") end
    return ok
end
_G.Copier_ToolsGiverToggle = function()
    _G.ToolsGiverActive = not _G.ToolsGiverActive
    if _G.ToolsGiverActive then F.startToolsGiverLoop() end
    App.report(_G.ToolsGiverActive and "ToolsGiver enabled." or "ToolsGiver disabled.", "info")
end


-- =============================================================================
-- LYRA TOAST · in-GUI notifications (does not use Roblox's SendNotification)
-- =============================================================================
-- Self-contained: it only needs TweenService, TextService and the Instances it creates,
-- so the whole block (from here to "END LYRA TOAST") can be copied into another script.
--
-- CREATE ONE NOTIFIER PER GUI
--   local notifier = Toast.new({
--       Parent = someFrameOrScreenGui,  -- required; toasts stack in its bottom-right corner
-- @YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
--       Theme = {                       -- optional; every key has a default (see Toast.DefaultTheme)
--           Background = Color3, Text = Color3, Muted = Color3, Line = Color3,
--           Kinds = {info = Color3, success = Color3, warning = Color3, error = Color3},
--       },
--       Icon = function(parent, name, position, color) end, -- optional; draws a 24x24 icon by name for
--                                       -- spec.Icon. If it errors, the kind's built-in glyph is used.
--       Font = {Regular = Enum.Font.X, Bold = Enum.Font.Y},  -- optional
--       Width = 264,                    -- optional; shrinks automatically on small screens
--       Max = 4,                        -- optional; the oldest toast leaves when a new one exceeds it
--       Margin = 12,                    -- optional; distance from the parent's bottom-right corner
--       Lift = 0,                       -- optional; extra bottom space (e.g. above a mobile jump button)
--       ReducedMotion = function() return false end,        -- optional; true = no slide/fade
--   })
--
-- SHOW A TOAST
--   local handle = notifier:Notify({
--       Title = "Saved",                -- required
--       Text = "Your skin was saved.",  -- optional second line (wraps)
--       Kind = "success",               -- "info" (default), "success", "warning" or "error": sets colour and glyph
--       Icon = "circle-check",          -- optional; drawn with the Icon option instead of the kind's glyph
--       Duration = 4,                   -- optional seconds (default 4); 0 keeps it until tapped
--       Image = "rbxasset…",            -- optional picture in the badge instead of an icon
--       Action = {Text = "Open", Callback = function() end}, -- optional button under the text
--       Featured = true,                -- optional; wider card, larger badge, stronger accent
--       Dismissible = false,            -- optional; a tap on the card does not close it (timer or action only)
--   })
--   handle:Dismiss()                    -- close it early
--
-- OTHER CALLS
--   notifier:Clear()                    -- close every toast
--   notifier:Destroy()                  -- remove the notifier and its container
--
-- Layout: heights are measured from the text with TextService (no AutomaticSize), so a toast is
-- always exactly as tall as its content.
-- Behaviour: a toast slides in from the right and fades, a hairline under it shows the time left,
-- and a tap closes it. Newest toasts sit closest to the corner.
local Toast = {}
Toast.__index = Toast
Toast.Tweens = game:GetService("TweenService")
Toast.Text = game:GetService("TextService")
Toast.DefaultTheme = {
    Background = Color3.fromRGB(24, 22, 36), Text = Color3.fromRGB(244, 239, 255),
    Muted = Color3.fromRGB(201, 193, 223), Line = Color3.fromRGB(78, 69, 101),
    Kinds = {info = Color3.fromRGB(188, 167, 246), success = Color3.fromRGB(137, 221, 187),
        warning = Color3.fromRGB(239, 205, 143), error = Color3.fromRGB(244, 151, 171)},
}
-- Built-in glyph for each kind, drawn in vectors so it stays sharp without the icon sheet.
Toast.KindGlyphs = {info = "info", success = "check", warning = "alert", error = "cross"}
Toast.Badge = 24

function Toast.new(options)
    assert(type(options) == "table" and options.Parent, "Toast.new needs {Parent = Instance}")
    local self = setmetatable({}, Toast)
    self.Options = options
    -- Copies, so the caller's tables and the defaults are never modified.
    local theme, kinds = {}, {}
    for key, value in pairs(Toast.DefaultTheme) do theme[key] = value end
    for key, value in pairs(options.Theme or {}) do theme[key] = value end
    for key, value in pairs(Toast.DefaultTheme.Kinds) do kinds[key] = value end
    for key, value in pairs(type(options.Theme) == "table" and type(options.Theme.Kinds) == "table" and options.Theme.Kinds or {}) do kinds[key] = value end
    self.Theme, self.Kinds = theme, kinds
    self.Font = options.Font or {Regular = Enum.Font.Gotham, Bold = Enum.Font.GothamBold}
    self.Width, self.Max, self.Margin, self.Lift = options.Width or 264, options.Max or 4, options.Margin or 12, options.Lift or 0
    self.Active = {}
    self.Container = Instance.new("Frame")
    self.Container.Name = "LyraToasts"; self.Container.BackgroundTransparency = 1; self.Container.ZIndex = 200
    self.Container.AnchorPoint = Vector2.new(1, 1)
    self.Container.Position = UDim2.new(1, -self.Margin, 1, -(self.Margin + self.Lift))
    self.Container.Size = UDim2.new(0, self.Width, 1, -(self.Margin * 2 + self.Lift))
    local layout = Instance.new("UIListLayout")
    layout.SortOrder = Enum.SortOrder.LayoutOrder; layout.Padding = UDim.new(0, 6)
    layout.HorizontalAlignment = Enum.HorizontalAlignment.Right
    layout.VerticalAlignment = Enum.VerticalAlignment.Bottom
    layout.Parent = self.Container
    self.Container.Parent = options.Parent
    self.Order = 0
    return self
end

function Toast:_reduced()
    local check = self.Options.ReducedMotion
    return type(check) == "function" and check() == true
end
function Toast:_tween(item, goal, duration)
    if self:_reduced() then for key, value in pairs(goal) do item[key] = value end; return nil end
    local tween = Toast.Tweens:Create(item, TweenInfo.new(duration, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), goal)
    tween:Play(); return tween
end
local function toastNew(class, props, parent)
    local item = Instance.new(class)
    for key, value in pairs(props) do item[key] = value end
    item.Parent = parent
    return item
end
-- Glyphs are laid out on the badge's 24x24 grid with rounded 2 px strokes.
function Toast.glyph(parent, name, color)
    local function stroke(x1, y1, x2, y2)
        local dx, dy = x2 - x1, y2 - y1
        local item = toastNew("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset((x1 + x2) / 2, (y1 + y2) / 2),
            Size = UDim2.fromOffset(math.sqrt(dx * dx + dy * dy) + 2, 2), Rotation = math.deg(math.atan2(dy, dx)),
            BackgroundColor3 = color, BorderSizePixel = 0, ZIndex = 203}, parent)
        toastNew("UICorner", {CornerRadius = UDim.new(1, 0)}, item)
    end
    local function dot(x, y)
        local item = toastNew("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(2.6, 2.6),
            BackgroundColor3 = color, BorderSizePixel = 0, ZIndex = 203}, parent)
        toastNew("UICorner", {CornerRadius = UDim.new(1, 0)}, item)
    end
    if name == "check" then stroke(7.5, 12.5, 10.5, 15.5); stroke(10.5, 15.5, 16.5, 9)
    elseif name == "cross" then stroke(8.5, 8.5, 15.5, 15.5); stroke(15.5, 8.5, 8.5, 15.5)
    elseif name == "alert" then stroke(12, 7.5, 12, 12.5); dot(12, 16.2)
    else dot(12, 7.8); stroke(12, 11, 12, 16.5) end
end

function Toast:Notify(spec)
    assert(type(spec) == "table" and spec.Title, "Notify needs {Title = string}")
    local kind = self.Kinds[spec.Kind or "info"] and (spec.Kind or "info") or "info"
    local color, theme = self.Kinds[kind], self.Theme
    local duration = spec.Duration == nil and 4 or spec.Duration
    -- Fit narrow screens: never wider than the parent minus the margins.
    -- A featured toast is wider, with a larger picture badge and a stronger accent.
    local featured = spec.Featured == true
    local parentWidth = self.Options.Parent.AbsoluteSize.X
    local wanted = featured and self.Width + 56 or self.Width
    local width = parentWidth > 0 and math.min(wanted, parentWidth - self.Margin * 2) or wanted
    self.Container.Size = UDim2.new(0, math.min(self.Width, width), 1, -(self.Margin * 2 + self.Lift))
    self.Order = self.Order + 1

    -- Fixed layout: every height is measured from the text, so nothing relies on AutomaticSize
    -- (which can feed back on itself and stretch the card). Left: 10 pad + badge + 10 gap.
    local title, text = tostring(spec.Title), spec.Text and tostring(spec.Text) or ""
    local badgeSize = featured and 40 or Toast.Badge
    local textLeft, textRight = 20 + badgeSize, 14
    local textWidth = math.max(60, width - textLeft - textRight)
    local function measure(value, size, font)
        if value == "" then return 0 end
        local ok, bounds = pcall(function() return Toast.Text:GetTextSize(value, size, font, Vector2.new(textWidth, 10000)) end)
        return ok and math.ceil(bounds.Y) or size + 4
    end
    local titleHeight = measure(title, 13, self.Font.Bold)
    local textHeight = measure(text, 12, self.Font.Regular)
    -- Optional action button under the text: {Text = "Open", Callback = function() end}.
    local action = type(spec.Action) == "table" and spec.Action or nil
    local actionHeight = action and 38 or 0
    local contentHeight = math.max(badgeSize, titleHeight + (textHeight > 0 and textHeight + 1 or 0) + actionHeight)
    local height = 10 + contentHeight + 11

    -- holder keeps the list slot; card slides inside it.
    local holder = toastNew("Frame", {Name = "Toast", BackgroundTransparency = 1, Size = UDim2.fromOffset(width, height), LayoutOrder = self.Order, ZIndex = 200}, self.Container)
    local card = toastNew("CanvasGroup", {BackgroundColor3 = theme.Background, BackgroundTransparency = 0.06, Size = UDim2.fromScale(1, 1),
        Position = UDim2.fromOffset(24, 0), GroupTransparency = 1, BorderSizePixel = 0, ZIndex = 200}, holder)
    toastNew("UICorner", {CornerRadius = UDim.new(0, 12)}, card)
    toastNew("UIStroke", {Color = featured and color or theme.Line, Transparency = featured and 0.25 or 0.4, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, card)
    -- Soft wash of the kind's colour from the left edge, fading out across the card.
    local wash = toastNew("Frame", {Size = UDim2.fromScale(1, 1), BackgroundColor3 = color, BackgroundTransparency = 0, BorderSizePixel = 0, ZIndex = 200}, card)
    toastNew("UIGradient", {Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, featured and 0.7 or 0.84), NumberSequenceKeypoint.new(0.45, featured and 0.92 or 0.97), NumberSequenceKeypoint.new(1, 1)})}, wash)
    -- Badge with the glyph, the caller's icon or picture, in the kind's colour.
    local badgeTop = 10 + math.floor((contentHeight - badgeSize) / 2)
    if featured then badgeTop = 10 end
    local badge = toastNew("Frame", {Position = UDim2.fromOffset(10, badgeTop), Size = UDim2.fromOffset(badgeSize, badgeSize), BackgroundColor3 = color,
        BackgroundTransparency = 0.82, BorderSizePixel = 0, ZIndex = 201}, card)
    toastNew("UICorner", {CornerRadius = featured and UDim.new(0, 12) or UDim.new(1, 0)}, badge)
    toastNew("UIStroke", {Color = color, Transparency = 0.55, Thickness = 1}, badge)
    local drew = false
    if type(spec.Image) == "string" and spec.Image ~= "" then
        local picture = toastNew("ImageLabel", {Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Image = spec.Image, ScaleType = Enum.ScaleType.Crop, ZIndex = 202}, badge)
        toastNew("UICorner", {CornerRadius = featured and UDim.new(0, 12) or UDim.new(1, 0)}, picture)
        drew = true
    end
    if not drew and spec.Icon and type(self.Options.Icon) == "function" then
        local holderIcon = toastNew("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(24, 24), BackgroundTransparency = 1, ZIndex = 202}, badge)
        toastNew("UIScale", {Scale = featured and 1 or 0.62}, holderIcon)
        drew = pcall(self.Options.Icon, holderIcon, spec.Icon, UDim2.new(), color)
        if not drew then holderIcon:Destroy() end
    end
    if not drew then Toast.glyph(badge, Toast.KindGlyphs[kind], color) end
    -- Title and optional text, vertically centred next to the badge when short.
    local top = 10 + math.floor((contentHeight - titleHeight - (textHeight > 0 and textHeight + 1 or 0) - actionHeight) / 2)
    toastNew("TextLabel", {Position = UDim2.fromOffset(textLeft, top), Size = UDim2.fromOffset(textWidth, titleHeight), BackgroundTransparency = 1, Text = title,
        TextColor3 = theme.Text, Font = self.Font.Bold, TextSize = 13, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top, ZIndex = 201}, card)
    if textHeight > 0 then
        toastNew("TextLabel", {Position = UDim2.fromOffset(textLeft, top + titleHeight + 1), Size = UDim2.fromOffset(textWidth, textHeight), BackgroundTransparency = 1, Text = text,
            TextColor3 = theme.Muted, Font = self.Font.Regular, TextSize = 12, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top, ZIndex = 201}, card)
    end
    -- Hairline along the bottom, shrinking over the toast's lifetime.
    local fill = toastNew("Frame", {Position = UDim2.new(0, 12, 1, -2), Size = UDim2.new(1, -24, 0, 1), BackgroundColor3 = color, BackgroundTransparency = 0.25,
        BorderSizePixel = 0, ZIndex = 202, Visible = duration > 0}, card)
    -- Whole card is tappable to dismiss (unless Dismissible = false); the action button sits above that tap area.
    local hit = spec.Dismissible ~= false and toastNew("TextButton", {Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 204}, card) or nil
    local actionButton
    if action then
        local label = tostring(action.Text or "Open")
        local ok, bounds = pcall(function() return Toast.Text:GetTextSize(label, 13, self.Font.Bold, Vector2.new(1000, 40)) end)
        local buttonWidth = math.clamp((ok and math.ceil(bounds.X) or 80) + 28, 90, textWidth)
        actionButton = toastNew("TextButton", {Position = UDim2.fromOffset(textLeft, top + titleHeight + (textHeight > 0 and textHeight + 1 or 0) + 8), Size = UDim2.fromOffset(buttonWidth, 30),
            BackgroundColor3 = color, Text = label, TextColor3 = theme.Background, Font = self.Font.Bold, TextSize = 13, AutoButtonColor = false, BorderSizePixel = 0, ZIndex = 205}, card)
        toastNew("UICorner", {CornerRadius = UDim.new(0, 9)}, actionButton)
    end

    local handle = {Closed = false}
    local notifier = self
    function handle:Dismiss()
        if handle.Closed then return end
        handle.Closed = true
        for i, item in ipairs(notifier.Active) do if item == handle then table.remove(notifier.Active, i); break end end
        if notifier:_reduced() then holder:Destroy(); return end
        notifier:_tween(card, {GroupTransparency = 1, Position = UDim2.fromOffset(24, 0)}, 0.2)
        task.delay(0.22, function() if holder.Parent then holder:Destroy() end end)
    end
    if hit then hit.Activated:Connect(function() handle:Dismiss() end) end
    if actionButton then
        actionButton.Activated:Connect(function()
            handle:Dismiss()
            if type(action.Callback) == "function" then task.spawn(action.Callback) end
        end)
    end
    table.insert(self.Active, handle)
    while #self.Active > self.Max do self.Active[1]:Dismiss() end

    self:_tween(card, {GroupTransparency = 0, Position = UDim2.fromOffset(0, 0)}, 0.3)
    if duration > 0 then
        if not self:_reduced() then
            Toast.Tweens:Create(fill, TweenInfo.new(duration, Enum.EasingStyle.Linear), {Size = UDim2.new(0, 0, 0, 1)}):Play()
        end
        task.delay(duration, function() handle:Dismiss() end)
    end
    return handle
end
function Toast:Clear()
    for i = #self.Active, 1, -1 do self.Active[i]:Dismiss() end
end
function Toast:Destroy()
    self.Active = {}
    if self.Container then self.Container:Destroy(); self.Container = nil end
end
-- =============================================================================
-- END LYRA TOAST
-- =============================================================================

