-- profile), a header over the page (its title, what it is for, Quick find and the window buttons), the page, and a
-- status line under it. A medium window turns the sidebar into a rail of icons (their names show on hover); a narrow
-- one into a drawer opened with the menu button.
-- =============================================================================
UI.Version="v27.2.0"
UI.TabInfo={
    Home={Icon="house",Label="Home",About="Your hub at a glance"},
    Avatar={Icon="user",Label="Copy Avatar",About="Search, preview and wear any avatar"},
    Players={Icon="users",Label="Server",About="Everyone in this server"},
    Collection={Icon="star",Label="Favorites & Recent",About="Profiles you starred and searched"},
    Looks={Icon="shirt",Label="Saved Skins",About="Your skins and the community's"},
    Catalog={Icon="box",Label="Roblox Shop",About="Try Roblox items on your avatar"},
    Customize={Icon="pencil",Label="Customize",About="Fine-tune what you wear"},
    Auto={Icon="refresh-cw",Label="Auto & Cycle",About="Load and switch avatars by themselves"},
    Plugins={Icon="gamepad-2",Label="Plugins",About="Extra features for the hub"},
    Settings={Icon="sliders-horizontal",Label="Settings",About="Make the hub yours"},
    Creator={Icon="code-xml",Label="Creator",About="Links and credits"},
    Debug={Icon="cpu",Label="Debug",About="Capture this game for a fix (dev only)"},
}
UI.NavGroups={{Items={"Home"}},{Caption="AVATARS",Items={"Avatar","Players","Collection","Looks"}},{Caption="STYLE",Items={"Catalog","Customize"}},
    {Caption="AUTOMATION",Items={"Auto","Plugins"}},{Caption="MORE",Items={"Settings","Creator"}}}

-- MOTION: every animation is a TweenService tween, which the engine plays (no Lua runs each frame). UI.motion() is
-- the level: "full"; "light" with Performance mode, or by itself for the session when the game stays under 40 frames
-- a second for a few seconds with the window open (shorter moves; no staggered entrances, page veils, breathing glows,
-- blur or sheen); "off" with Reduced motion (everything jumps to its end).
UI.Motion={Auto=false,Slow=0}
function UI.motion()
    if Store.Settings.ReducedMotion then return "off" end
    if Store.Settings.LowEffects or UI.Motion.Auto then return "light" end
    return "full"
end
-- A tween runs on its own channel of an object: a new one on the same channel replaces it (the default channel is the
-- object itself, so hover, press and layout tweens of one object never fight).
UI.Channels=setmetatable({},{__mode="k"})
function UI.channel(item,name)
    if not name then return item end
    local slots=UI.Channels[item]; if not slots then slots={}; UI.Channels[item]=slots end
    local key=slots[name]; if not key then key={}; slots[name]=key end
    return key
end
-- A soft endless glow (a ring breathing): full motion only, and started once per object.
UI.Pulses=setmetatable({},{__mode="k"})
function UI.pulse(item,goal,duration)
    if not item or not App.alive() then return end
    if UI.motion()~="full" then UI.stopPulse(item); return end
    if UI.Pulses[item] then return end
    local tween=UI.TweenService:Create(item,TweenInfo.new(duration or 1.6,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut,-1,true),goal)
    UI.Pulses[item]=tween; UI.Tweens[UI.channel(item,"pulse")]=tween
    tween:Play()
end
function UI.stopPulse(item,rest)
    local tween=item and UI.Pulses[item]
    if tween then tween:Cancel(); UI.Pulses[item]=nil; UI.Tweens[UI.channel(item,"pulse")]=nil end
    if item and rest then for key,value in pairs(rest) do pcall(function() item[key]=value end) end end
end
-- PRESS: a control darkens under the finger and lights back up when let go. A shade inside it does it, rounded like
-- the control, so nothing around it moves or re-lays out.
function UI.press(root,connect)
    if not root or root:FindFirstChild("LyraShade") then return end
    connect=connect or UI.connect
    local shade=UI.new("Frame",{Name="LyraShade",Size=UDim2.fromScale(1,1),BackgroundColor3=Color3.new(0,0,0),BackgroundTransparency=1,BorderSizePixel=0},root)
    local corner=root:FindFirstChildOfClass("UICorner")
    if corner then UI.new("UICorner",{CornerRadius=corner.CornerRadius},shade) end
    local function down(input)
        if (input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch) and root.Active then UI.tween(shade,{BackgroundTransparency=0.8},0.06,Enum.EasingStyle.Quad) end
    end
    local function up() UI.tween(shade,{BackgroundTransparency=1},0.3,Enum.EasingStyle.Quad) end
    connect(root.InputBegan,down)
    connect(root.InputEnded,function(input) if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then up() end end)
    connect(root.MouseLeave,up)
    return shade
end
-- REVEAL: a card of a page appears out of the window: a veil of the window's colour over it melts away while its
-- content rises into place. Staggered by order. Full motion only; a card with a layout of its own just fades.
function UI.reveal(card,order,body)
    if not card or UI.motion()~="full" then return end
    local delay=math.min(order or 0,8)*0.05
    local corner=card:FindFirstChildOfClass("UICorner")
    if not card:FindFirstChildWhichIsA("UIGridStyleLayout") then
        local veil=UI.new("Frame",{Name="LyraVeil",Size=UDim2.fromScale(1,1),BackgroundColor3=UI.C.Base,BackgroundTransparency=0.1,BorderSizePixel=0,ZIndex=20},card)
        if corner then UI.new("UICorner",{CornerRadius=corner.CornerRadius},veil) end
        UI.tween(veil,{BackgroundTransparency=1},0.34,Enum.EasingStyle.Quad,Enum.EasingDirection.Out,delay)
        task.delay(delay+0.4,function() pcall(function() veil:Destroy() end) end)
    end
    if body then
        local rest=body:GetAttribute("LyraRest") or UDim2.new()
        body.Position=rest+UDim2.fromOffset(0,10)
        UI.tween(body,{Position=rest},0.45,Enum.EasingStyle.Quint,Enum.EasingDirection.Out,delay,"rise")
    end
end
-- A button that answers for a moment (Copied!): its label and icon change and it turns green, then it goes back.
function UI.flash(entry,text,seconds)
    if not entry or not entry.Label then return end
    entry.FlashSerial=(entry.FlashSerial or 0)+1; local serial=entry.FlashSerial
    local original=entry.Label:GetAttribute("LyraText") or entry.Label.Text
    if not entry.Rest then entry.Rest=entry.Root.BackgroundColor3 end
    UI.setText(entry.Label,text)
    UI.tween(entry.Root,{BackgroundColor3=UI.C.Green},0.2)
    task.delay(seconds or 1.6,function()
        if not App.alive() or entry.FlashSerial~=serial then return end
        UI.setText(entry.Label,original); UI.tween(entry.Root,{BackgroundColor3=entry.Rest},0.35)
    end)
end

-- ANCHORS: the places of the window that can be pointed at (a setting, a card, a section, a page): Quick find lists
-- them, the update log and the Home guide jump to them. A key is "setting:<Settings key>", "card:<title>",
-- "section:<title>" or a name given by its builder ("home:players", "avatar:search"...). Tab and section are the ones
-- being built when the anchor is made.
UI.Anchors={}; UI.AnchorList={}; UI.Folds=setmetatable({},{__mode="k"})
function UI.anchor(key,item,info)
    if not key or not item then return item end
    info=info or {}
    local entry=UI.Anchors[key]
    if not entry then entry={Key=key}; UI.Anchors[key]=entry; table.insert(UI.AnchorList,entry) end
    entry.Item=item; entry.Tab=info.Tab or UI.BuildingTab; entry.Title=info.Title; entry.Text=info.Text
    entry.Section=info.Section or (UI.BuildingSection~=info.Title and UI.BuildingSection or nil); entry.Hidden=info.Hidden; entry.Reveal=info.Reveal
    return item
end
-- True when an item and every one of its parents up to stop are visible.
function UI.shown(item,stop)
    local cursor=item
    while cursor and cursor~=stop and cursor~=UI.Main do
        if cursor:IsA("GuiObject") and not cursor.Visible then return false end
        cursor=cursor.Parent
    end
    return true
end
-- SPOTLIGHT: takes you to an anchor: its page opens, a folded group holding it unfolds (a hidden card, such as the Home
-- guide, is shown again), the page scrolls it into view and a ring glows around it for a few seconds with a short
-- label. A page name opens that page. From another page, a Back chip takes you back for a few seconds. False when
-- unknown.
function UI.spotlight(key,label)
    local entry=UI.Anchors[key]
    if not entry and UI.Pages[key] then UI.selectTab(key); return true end
    local item=entry and entry.Item
    if not item or not item.Parent then return false end
    local from=UI.Tab
    if UI.FindOpen then UI.closeFind(true) end
    if UI.Minimized then UI.Minimized=false; UI.layout(false) end
    if not UI.Visible then UI.setVisible(true) end
    if entry.Tab and UI.Pages[entry.Tab] and UI.Tab~=entry.Tab then UI.selectTab(entry.Tab) end
    local cursor=item
    while cursor and cursor~=UI.Main do
        local open=UI.Folds[cursor]
        if open and not cursor.Visible then open(true) end
        cursor=cursor.Parent
    end
    if not UI.shown(item) and entry.Reveal then entry.Reveal() end
    if not UI.shown(item) then return false end
    if entry.Tab and from~=entry.Tab and UI.Pages[from] then UI.showBack(from) end
    UI.SpotSerial=(UI.SpotSerial or 0)+1; local serial=UI.SpotSerial
    task.spawn(function()
        -- One frame for Roblox to lay out a page just shown or a group just unfolded before measuring it.
        RS.Heartbeat:Wait()
        if not App.alive() or serial~=UI.SpotSerial then return end
        UI.ring(item,label or "Here it is")
        local page=entry.Tab and UI.Pages[entry.Tab]
        if page and item:IsDescendantOf(page) then
            -- A scroll restore still running for this page would pull it back.
            UI.RestoreSerial=(UI.RestoreSerial or 0)+1; UI.Restoring[entry.Tab]=nil
            UI.scrollTo(page,item,serial,entry.Tab)
        end
    end)
    return true
end
-- Scrolls a page so an item sits near its top, with room for the spotlight's label above it (an item taller than the
-- page is aligned to its top). Cards above may still be growing to their size and the window is scaled, so after each
-- move it measures where the item really is and corrects, until it stays put. A finger scrolling meanwhile wins.
-- UI.CanvasScreen: whether CanvasPosition counts screen pixels (true) or the window's own (false), learnt the first time
-- a scroll moves far enough to tell.
function UI.scrollTo(page,item,serial,tab)
    local function ratio()
        local scale=math.max(UI.WindowScale.Scale,0.01)
        return UI.CanvasScreen and 1 or scale
    end
    local function goal()
        local scale=math.max(UI.WindowScale.Scale,0.01)
        local window=page.AbsoluteWindowSize.Y
        local offset=item.AbsolutePosition.Y-page.AbsolutePosition.Y
        local want=math.min(44*scale,math.max(0,(window-item.AbsoluteSize.Y)/2))
        local r=ratio()
        local room=math.max(0,(page.AbsoluteCanvasSize.Y-window)/r)
        return math.clamp(page.CanvasPosition.Y+(offset-want)/r,0,room),offset
    end
    local still=0
    for step=1,8 do
        if not App.alive() or serial~=UI.SpotSerial or UI.Tab~=tab or not item.Parent then return end
        local start=page.CanvasPosition.Y
        local y,offset=goal()
        if math.abs(y-start)<2 then
            still=still+1
            if still>=3 then return end
            RS.Heartbeat:Wait()
        else
            still=0
            local time=UI.motion()=="off" and 0 or (step==1 and 0.45 or 0.18)
            UI.tween(page,{CanvasPosition=Vector2.new(page.CanvasPosition.X,y)},time,Enum.EasingStyle.Quint,Enum.EasingDirection.Out,nil,"scroll")
            if time>0 then task.wait(time+0.03) else RS.Heartbeat:Wait() end
            if not App.alive() or serial~=UI.SpotSerial then return end
            -- Scrolled by hand meanwhile (or the page got shorter): leave it there.
            if math.abs(page.CanvasPosition.Y-y)>4 then return end
            local scale=math.max(UI.WindowScale.Scale,0.01)
            local moved=y-start
            if UI.CanvasScreen==nil and math.abs(moved)>40 and math.abs(scale-1)>0.04 then
                local seen=(offset-(item.AbsolutePosition.Y-page.AbsolutePosition.Y))/moved
                UI.CanvasScreen=math.abs(seen-1)<math.abs(seen-scale)
            end
        end
    end
end
-- The ring of the spotlight, drawn over the page (so a card laid out in a list keeps its place) and following the item
-- while the page scrolls. It grows in, breathes three times and fades. Its label sits over the item, or under it when
-- there is no room above (the header).
function UI.ring(item,label)
    if UI.Ring then pcall(function() UI.Ring.Root:Destroy(); UI.Ring.Follow:Disconnect() end); UI.Ring=nil end
    local layer=item:IsDescendantOf(UI.Content) and UI.Content or UI.Main
    local corner=item:FindFirstChildOfClass("UICorner")
    local root=UI.new("Frame",{Name="LyraSpotlight",BackgroundColor3=UI.C.Accent,BackgroundTransparency=0.9,BorderSizePixel=0,ZIndex=60},layer)
    UI.new("UICorner",{CornerRadius=corner and corner.CornerRadius or UDim.new(0,14)},root)
    local edge=UI.new("UIStroke",{Color=UI.C.Accent,Thickness=2.5,Transparency=1},root)
    local tag=UI.new("TextLabel",{Name="Tag",AnchorPoint=Vector2.new(1,1),Position=UDim2.new(1,0,0,-6),AutomaticSize=Enum.AutomaticSize.X,Size=UDim2.fromOffset(0,22),
        BackgroundColor3=UI.C.Accent,Text=label,TextColor3=UI.C.Base,Font=UI.Font.Bold,TextSize=UI.size(11),BorderSizePixel=0,ZIndex=61},root)
    UI.round(tag,11); UI.new("UIPadding",{PaddingLeft=UDim.new(0,10),PaddingRight=UDim.new(0,10)},tag)
    local ring={Root=root}
    local function place()
        local scale=math.max(UI.WindowScale.Scale,0.01)
        local at=(item.AbsolutePosition-layer.AbsolutePosition)/scale
        local size=item.AbsoluteSize/scale
        root.Position=UDim2.fromOffset(at.X-3,at.Y-3); root.Size=UDim2.fromOffset(size.X+6,size.Y+6)
        local below=at.Y<30
        tag.AnchorPoint=Vector2.new(1,below and 0 or 1)
        tag.Position=below and UDim2.new(1,0,1,6) or UDim2.new(1,0,0,-6)
    end
    place()
    ring.Follow=RS.Heartbeat:Connect(function()
        if not App.alive() or not item.Parent or not root.Parent then ring.Follow:Disconnect(); pcall(function() root:Destroy() end); return end
        pcall(place)
    end)
    UI.Ring=ring
    local level=UI.motion()
    if level=="off" then edge.Transparency=0
    else
        UI.tween(edge,{Transparency=0},0.25)
        if level=="full" then
            task.delay(0.3,function()
                if UI.Ring~=ring then return end
                local breathe=UI.TweenService:Create(edge,TweenInfo.new(0.55,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut,3,true),{Transparency=0.65})
                UI.Tweens[UI.channel(edge,"pulse")]=breathe; breathe:Play()
            end)
        end
    end
    task.delay(4,function()
        if UI.Ring~=ring then return end
        UI.tween(edge,{Transparency=1},0.3); UI.tween(root,{BackgroundTransparency=1},0.3); UI.tween(tag,{BackgroundTransparency=1,TextTransparency=1},0.3)
        task.delay(0.32,function()
            if UI.Ring==ring then UI.Ring=nil end
            pcall(function() ring.Follow:Disconnect(); root:Destroy() end)
        end)
    end)
    return ring
end
-- BACK: after a jump to another page, a chip at the bottom of the page offers the way back (to the page and the place
-- it was scrolled to) for a few seconds.
function UI.buildBack()
    local chip=UI.new("TextButton",{Name="Back",AnchorPoint=Vector2.new(0.5,1),Position=UDim2.new(0.5,0,1,-12),Size=UDim2.fromOffset(150,34),Text="",AutoButtonColor=false,
        BackgroundColor3=UI.C.Card,BorderSizePixel=0,Visible=false},UI.Overlay)
    UI.round(chip,17); UI.stroke(chip,0.35,UI.C.Accent)
    local icon=UI.icon(chip,"undo-2",UDim2.new(0,10,0.5,-12),UI.C.Accent); UI.new("UIScale",{Scale=0.8},icon)
    local text=UI.text(chip,"",12,UI.C.Text,true); text.Position=UDim2.fromOffset(38,0); text.Size=UDim2.new(1,-50,1,0)
    UI.BackChip={Root=chip,Label=text,Scale=UI.new("UIScale",{Scale=1},chip)}
    UI.press(chip)
    UI.connect(chip.Activated,function()
        local tab=UI.BackTo
        UI.hideBack()
        if tab and UI.Pages[tab] then UI.selectTab(tab) end
    end)
end
function UI.showBack(tab)
    local back=UI.BackChip
    if not back or not UI.TabInfo[tab] then return end
    UI.BackTo=tab
    UI.setText(back.Label,"Back to "..UI.TabInfo[tab].Label)
    -- As wide as its words.
    back.Root.Size=UDim2.fromOffset(math.clamp(UI.textWidth(back.Label.Text,back.Label.TextSize,back.Label)+56,120,300),34)
    UI.BackSerial=(UI.BackSerial or 0)+1; local serial=UI.BackSerial
    back.Root.Visible=true
    if UI.motion()~="off" then
        back.Root.Position=UDim2.new(0.5,0,1,8); back.Scale.Scale=0.85
        UI.tween(back.Root,{Position=UDim2.new(0.5,0,1,-12)},0.4,Enum.EasingStyle.Back)
        UI.tween(back.Scale,{Scale=1},0.35,Enum.EasingStyle.Back)
    end
    task.delay(7,function() if serial==UI.BackSerial then UI.hideBack() end end)
end
function UI.hideBack()
    local back=UI.BackChip
    if not back or not back.Root.Visible then return end
    UI.BackSerial=(UI.BackSerial or 0)+1; local serial=UI.BackSerial
    UI.BackTo=nil
    if UI.motion()=="off" then back.Root.Visible=false; return end
    UI.tween(back.Root,{Position=UDim2.new(0.5,0,1,10)},0.2,Enum.EasingStyle.Quad,Enum.EasingDirection.In)
    UI.tween(back.Scale,{Scale=0.85},0.2)
    task.delay(0.21,function() if serial==UI.BackSerial and UI.BackChip then UI.BackChip.Root.Visible=false end end)
end
-- TO THE TOP: a round button at the bottom right of a page scrolled far down brings it back to the top.
function UI.buildTop()
    local button=UI.new("TextButton",{Name="ToTop",AnchorPoint=Vector2.new(1,1),Position=UDim2.new(1,-14,1,-12),Size=UDim2.fromOffset(38,38),Text="",AutoButtonColor=false,
        BackgroundColor3=UI.C.AccentDark,BackgroundTransparency=0.1,BorderSizePixel=0,Visible=false},UI.Overlay)
    UI.new("UICorner",{CornerRadius=UDim.new(1,0)},button); UI.stroke(button,0.35,UI.C.Accent)
    local icon=UI.icon(button,"chevron-up",UDim2.fromScale(0.5,0.5),UI.C.Text); icon.AnchorPoint=Vector2.new(0.5,0.5)
    UI.TopButton={Root=button,Scale=UI.new("UIScale",{Scale=1},button)}
    UI.press(button)
    UI.connect(button.Activated,function()
        local page=UI.Pages[UI.Tab]
        if page then UI.tween(page,{CanvasPosition=Vector2.new(page.CanvasPosition.X,0)},0.5,Enum.EasingStyle.Quint,Enum.EasingDirection.Out,nil,"scroll") end
    end)
end
function UI.refreshTop()
    local top=UI.TopButton
    if not top then return end
    local page=UI.Pages[UI.Tab]
    local show=page~=nil and page.CanvasPosition.Y>500 and not UI.Minimized
    if show==top.Shown then return end
    top.Shown=show
    UI.TopSerial=(UI.TopSerial or 0)+1; local serial=UI.TopSerial
    if show then
        top.Root.Visible=true
        if UI.motion()~="off" then top.Scale.Scale=0.4; UI.tween(top.Scale,{Scale=1},0.35,Enum.EasingStyle.Back) end
    elseif UI.motion()=="off" then top.Root.Visible=false
    else
        UI.tween(top.Scale,{Scale=0.4},0.18,Enum.EasingStyle.Quad,Enum.EasingDirection.In)
        task.delay(0.19,function() if serial==UI.TopSerial and UI.TopButton then UI.TopButton.Root.Visible=false end end)
    end
end

