-- Lower case, no accents: what search compares.
function UI.fold(text)
    if not UI.FoldMap then
        UI.FoldMap={}
        local codes={}
        for _,code in utf8.codes(UI.FoldPairs) do table.insert(codes,code) end
        for index=1,#codes-1,2 do UI.FoldMap[codes[index]]=utf8.char(codes[index+1]) end
    end
    text=tostring(text or ""):lower()
    if not text:find("[\128-\255]") then return text end
    local ok,folded=pcall(function()
        local out={}
        for _,code in utf8.codes(text) do table.insert(out,UI.FoldMap[code] or utf8.char(code)) end
        return table.concat(out)
    end)
    return ok and folded or text
end
-- How well a search term matches some texts (the first two are names, the rest descriptions); nil when it doesn't.
function UI.findScore(term,texts)
    if term=="" then return nil end
    local best=nil
    for index,text in ipairs(texts) do
        local folded=UI.fold(text)
        local at=folded~="" and folded:find(term,1,true)
        if at then
            local score=(index<=2 and 20 or 6)+(at==1 and 8 or (folded:sub(at-1,at-1):match("[%s%p]") and 4 or 0))
            if not best or score>best then best=score end
        end
    end
    if best then return best end
    -- Every word of the term somewhere.
    local all=UI.fold(table.concat(texts," "))
    for word in term:gmatch("%S+") do if not all:find(word,1,true) then return nil end end
    return 3
end
UI.FindSuggestions={"home:news","settings:themes","card:Language","home:players","setting:MobileOrb","section:Name and badge"}
function UI.findResults(raw)
    local term=UI.fold(raw):gsub("^%s+",""):gsub("%s+$","")
    local results={}
    local function crumb(entry)
        local tab=entry.Tab and UI.TabInfo[entry.Tab]
        local parts={tab and Lang.text(tab.Label) or nil}
        if entry.Section and entry.Section~=entry.Title then table.insert(parts,Lang.text(entry.Section)) end
        return table.concat(parts,"  ›  ")
    end
    if term=="" then
        -- What you opened last comes first, then the usual suggestions.
        local keys,listed={},{}
        for _,key in ipairs(UI.FindRecent or {}) do if not listed[key] then listed[key]=true; table.insert(keys,key) end end
        for _,key in ipairs(UI.FindSuggestions) do if not listed[key] then listed[key]=true; table.insert(keys,key) end end
        for _,key in ipairs(keys) do
            if UI.Pages[key] and UI.TabInfo[key] then
                table.insert(results,{Key=key,Title=UI.TabInfo[key].Label,Crumb=Lang.text("Page"),Icon=UI.TabInfo[key].Icon,Recent=true})
            end
            local entry=UI.Anchors[key]
            if entry and entry.Item and entry.Item.Parent and entry.Title then
                table.insert(results,{Key=key,Title=entry.Title,Crumb=crumb(entry),Icon=entry.Tab and UI.TabInfo[entry.Tab] and UI.TabInfo[entry.Tab].Icon or "sparkles"})
            end
        end
        while #results>8 do table.remove(results) end
        return results,true
    end
    for order,name in ipairs(UI.NavOrder) do
        local info=UI.TabInfo[name]
--[[YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU]]
        local score=UI.findScore(term,{Lang.text(info.Label),info.Label,Lang.text(info.About),info.About})
        if score then table.insert(results,{Key=name,Title=info.Label,Crumb=Lang.text("Page"),Icon=info.Icon,Score=score+5,Order=order}) end
    end
    local seen={}
    for order,entry in ipairs(UI.AnchorList) do
        local item=entry.Item
        if entry.Title and not entry.Hidden and item and item.Parent and not seen[item] then
            local text=entry.Text or ""
            local score=UI.findScore(term,{Lang.text(entry.Title),entry.Title,Lang.text(text),text,entry.Section and Lang.text(entry.Section) or ""})
            if score then
                seen[item]=true
                table.insert(results,{Key=entry.Key,Title=entry.Title,Crumb=crumb(entry),Icon=entry.Tab and UI.TabInfo[entry.Tab] and UI.TabInfo[entry.Tab].Icon or "search",Score=score,Order=100+order})
            end
        end
    end
    table.sort(results,function(a,b) if a.Score~=b.Score then return a.Score>b.Score end; return a.Order<b.Order end)
    while #results>24 do table.remove(results) end
    return results,false
end
function UI.buildFind()
    UI.Find=UI.new("Frame",{Name="QuickFind",Size=UDim2.fromScale(1,1),BackgroundColor3=Color3.new(0,0,0),BackgroundTransparency=1,BorderSizePixel=0,ZIndex=85,Visible=false},UI.Main)
    local catcher=UI.new("TextButton",{Name="Catcher",Size=UDim2.fromScale(1,1),Text="",AutoButtonColor=false,BackgroundTransparency=1,ZIndex=85},UI.Find)
    UI.connect(catcher.Activated,function() UI.closeFind() end)
    local panel=UI.new("TextButton",{Name="Panel",AnchorPoint=Vector2.new(0.5,0),Position=UDim2.new(0.5,0,0,64),Size=UDim2.new(1,-32,0,380),Text="",AutoButtonColor=false,
        BackgroundColor3=UI.C.Card,BorderSizePixel=0,ZIndex=86},UI.Find)
    UI.round(panel,18); UI.stroke(panel,0.35,UI.C.Accent)
    UI.new("UISizeConstraint",{MaxSize=Vector2.new(560,420)},panel)
    UI.FindPanel=panel; UI.FindScale=UI.new("UIScale",{Scale=1},panel)
    local field=UI.new("Frame",{Position=UDim2.fromOffset(12,12),Size=UDim2.new(1,-24,0,44),BackgroundColor3=UI.C.Base,BackgroundTransparency=0.2,BorderSizePixel=0,ZIndex=87},panel)
    UI.round(field,13); UI.stroke(field,0.45,UI.C.Accent)
    UI.icon(field,"search",UDim2.new(0,12,0.5,-12),UI.C.Accent)
    UI.FindBox=UI.new("TextBox",{Name="Query",Position=UDim2.fromOffset(44,0),Size=UDim2.new(1,-100,1,0),BackgroundTransparency=1,Text="",PlaceholderText="Search pages and settings",
        PlaceholderColor3=UI.C.Muted,TextColor3=UI.C.Text,Font=UI.Font.Regular,TextSize=UI.size(15),TextXAlignment=Enum.TextXAlignment.Left,ClearTextOnFocus=false,ZIndex=88},field)
    local esc=UI.new("TextButton",{Name="Close",AnchorPoint=Vector2.new(1,0.5),Position=UDim2.new(1,-8,0.5,0),Size=UDim2.fromOffset(44,26),Text="Esc",TextColor3=UI.C.Muted,Font=UI.Font.Bold,
        TextSize=UI.size(11),AutoButtonColor=false,BackgroundColor3=UI.C.Raised,BorderSizePixel=0,ZIndex=88},field)
    UI.round(esc,8); UI.press(esc)
    UI.connect(esc.Activated,function() UI.closeFind() end)
    UI.FindHeading=UI.text(panel,"Suggestions",10,UI.C.Muted,true); UI.FindHeading.Position=UDim2.fromOffset(18,62); UI.FindHeading.Size=UDim2.new(1,-36,0,18); UI.FindHeading.ZIndex=87
    UI.FindList=UI.new("ScrollingFrame",{Name="Results",Position=UDim2.fromOffset(8,82),Size=UDim2.new(1,-16,1,-116),BackgroundTransparency=1,BorderSizePixel=0,ScrollBarThickness=3,
        ScrollBarImageColor3=UI.C.AccentDark,CanvasSize=UDim2.new(),AutomaticCanvasSize=Enum.AutomaticSize.Y,ScrollingDirection=Enum.ScrollingDirection.Y,ZIndex=87},panel)
    UI.stack(UI.FindList,4)
    UI.FindHint=UI.text(panel,UIS.KeyboardEnabled and "Enter to open · Esc to close" or "Tap a result to go there",10,UI.C.Muted); UI.FindHint.AnchorPoint=Vector2.new(0,1)
    UI.FindHint.Position=UDim2.new(0,18,1,-10); UI.FindHint.Size=UDim2.new(1,-36,0,16); UI.FindHint.ZIndex=87
    UI.connect(UI.FindBox:GetPropertyChangedSignal("Text"),function() if UI.FindOpen then UI.FindPick=1; UI.renderFind() end end)
    UI.connect(UI.FindBox.FocusLost,function(enter) if enter and UI.FindOpen then UI.chooseFind(UI.FindPick or 1) end end)
    UI.connect(UIS.InputBegan,function(input,processed)
        if input.UserInputType~=Enum.UserInputType.Keyboard then return end
        local key=input.KeyCode
        if UI.FindOpen then
            if key==Enum.KeyCode.Escape then UI.closeFind()
            elseif key==Enum.KeyCode.Down then UI.moveFind(1)
            elseif key==Enum.KeyCode.Up then UI.moveFind(-1) end
            return
        end
        if processed or UIS:GetFocusedTextBox() then return end
        if key==Enum.KeyCode.K and UI.Visible and (UIS:IsKeyDown(Enum.KeyCode.LeftControl) or UIS:IsKeyDown(Enum.KeyCode.RightControl)) then UI.openFind() end
    end)
end
function UI.renderFind()
    if not UI.FindList then return end
    UI.clearRows("find",UI.FindList)
    local results,suggested=UI.findResults(UI.FindBox.Text)
    UI.FindResults=results
    UI.setText(UI.FindHeading,suggested and "Suggestions" or (#results>0 and "Results" or ""))
    if #results==0 then
        local empty=UI.paragraph(UI.FindList,"No matches. Try another word.",12,UI.C.Muted,false,1)
        empty.TextXAlignment=Enum.TextXAlignment.Center; empty.ZIndex=88
        return
    end
    for index,result in ipairs(results) do
        local row=UI.new("TextButton",{Name="Result",LayoutOrder=index,Size=UDim2.new(1,-4,0,48),Text="",AutoButtonColor=false,BackgroundColor3=UI.C.AccentDark,
            BackgroundTransparency=1,BorderSizePixel=0,ZIndex=88},UI.FindList)
        UI.round(row,12)
        local chip=UI.new("Frame",{Position=UDim2.new(0,8,0.5,-16),Size=UDim2.fromOffset(32,32),BackgroundColor3=UI.C.Raised,BorderSizePixel=0,ZIndex=89},row); UI.round(chip,10)
        local glyph=UI.icon(chip,result.Icon,UDim2.new(0.5,-12,0.5,-12),UI.C.Accent); glyph.ZIndex=90
        for _,image in ipairs(glyph:GetDescendants()) do if image:IsA("GuiObject") then image.ZIndex=90 end end
        local title=UI.text(row,result.Title,13,UI.C.Text,true); title.Position=UDim2.fromOffset(50,6); title.Size=UDim2.new(1,-90,0,20); title.ZIndex=89
        local crumb=UI.text(row,result.Crumb,10,UI.C.Muted); crumb.Position=UDim2.fromOffset(50,26); crumb.Size=UDim2.new(1,-90,0,16); crumb.ZIndex=89
        local go=UI.icon(row,"arrow-right",UDim2.new(1,-34,0.5,-12),UI.C.Muted); go.ZIndex=89
        result.Row=row; result.Go=go
        UI.rowConnect("find",row.MouseEnter,function() UI.FindPick=index; UI.paintFind() end)
        UI.rowConnect("find",row.Activated,function() UI.chooseFind(index) end)
    end
    UI.paintFind()
end
function UI.paintFind()
    for index,result in ipairs(UI.FindResults or {}) do
        local on=index==(UI.FindPick or 1)
        if result.Row then
            UI.tween(result.Row,{BackgroundTransparency=on and 0.45 or 1},0.12)
            UI.recolor(result.Go,on and UI.C.Accent or UI.C.Muted)
        end
    end
end
function UI.moveFind(step)
    local count=#(UI.FindResults or {})
    if count==0 then return end
    UI.FindPick=((UI.FindPick or 1)-1+step)%count+1
    UI.paintFind()
    local row=UI.FindResults[UI.FindPick].Row
    if row then
        local top,bottom=row.AbsolutePosition.Y,row.AbsolutePosition.Y+row.AbsoluteSize.Y
        local listTop,listBottom=UI.FindList.AbsolutePosition.Y,UI.FindList.AbsolutePosition.Y+UI.FindList.AbsoluteSize.Y
        local scale=math.max(UI.WindowScale.Scale,0.01)
        if top<listTop then UI.FindList.CanvasPosition=Vector2.new(0,UI.FindList.CanvasPosition.Y-(listTop-top)/scale)
        elseif bottom>listBottom then UI.FindList.CanvasPosition=Vector2.new(0,UI.FindList.CanvasPosition.Y+(bottom-listBottom)/scale) end
    end
end
function UI.chooseFind(index)
    local result=UI.FindResults and UI.FindResults[index]
    if not result then return end
    -- Remembered for this session: the last three picks lead the suggestions.
    UI.FindRecent=UI.FindRecent or {}
    local at=table.find(UI.FindRecent,result.Key); if at then table.remove(UI.FindRecent,at) end
    table.insert(UI.FindRecent,1,result.Key)
    while #UI.FindRecent>3 do table.remove(UI.FindRecent) end
    UI.closeFind(true)
    UI.spotlight(result.Key)
end
function UI.openFind(text)
    if not UI.Find or UI.FindOpen then return end
    UI.closeDropdown(true)
    if UI.Drawer then UI.Drawer=false; UI.layout(false) end
    UI.FindOpen=true; UI.FindSerial=(UI.FindSerial or 0)+1; UI.FindPick=1
    UI.FindBox.Text=text or ""
    UI.renderFind()
    UI.Find.Visible=true
    UI.Find.BackgroundTransparency=1; UI.tween(UI.Find,{BackgroundTransparency=0.45},0.2)
    UI.FindScale.Scale=0.94; UI.tween(UI.FindScale,{Scale=1},0.32,Enum.EasingStyle.Back)
    UI.FindPanel.Position=UDim2.new(0.5,0,0,48); UI.tween(UI.FindPanel,{Position=UDim2.new(0.5,0,0,64)},0.3)
    task.defer(function() if UI.FindOpen and App.alive() then pcall(function() UI.FindBox:CaptureFocus() end) end end)
end
function UI.closeFind(instant)
    if not UI.FindOpen then return end
    UI.FindOpen=false; UI.FindSerial=(UI.FindSerial or 0)+1; local serial=UI.FindSerial
    pcall(function() UI.FindBox:ReleaseFocus() end)
    if instant or UI.motion()=="off" then UI.Find.Visible=false; return end
    UI.tween(UI.Find,{BackgroundTransparency=1},0.16); UI.tween(UI.FindScale,{Scale=0.96},0.16)
    task.delay(0.17,function() if serial==UI.FindSerial and not UI.FindOpen and UI.Find then UI.Find.Visible=false end end)
end

-- A name next to the rail's icons while the pointer is over one.
function UI.buildTip()
    UI.Tip=UI.new("TextLabel",{Name="Tip",AutomaticSize=Enum.AutomaticSize.X,Size=UDim2.fromOffset(0,28),BackgroundColor3=UI.C.Raised,BackgroundTransparency=1,TextColor3=UI.C.Text,
        TextTransparency=1,Font=UI.Font.Bold,TextSize=UI.size(12),Text="",BorderSizePixel=0,ZIndex=95,Visible=false},UI.Main)
    UI.round(UI.Tip,9); UI.new("UIPadding",{PaddingLeft=UDim.new(0,10),PaddingRight=UDim.new(0,10)},UI.Tip)
    UI.TipEdge=UI.stroke(UI.Tip,1,UI.C.Accent)
end
function UI.tip(button,text)
    if not UI.Tip then return end
    UI.TipSerial=(UI.TipSerial or 0)+1; local serial=UI.TipSerial
    if not button then
        UI.tween(UI.Tip,{BackgroundTransparency=1,TextTransparency=1},0.1); UI.tween(UI.TipEdge,{Transparency=1},0.1)
        task.delay(0.11,function() if serial==UI.TipSerial and UI.Tip then UI.Tip.Visible=false end end)
        return
    end
    local scale=math.max(UI.WindowScale.Scale,0.01)
    local at=(button.AbsolutePosition-UI.Main.AbsolutePosition)/scale
    local x,y=at.X+button.AbsoluteSize.X/scale+10,at.Y+button.AbsoluteSize.Y/scale/2-14
    UI.setText(UI.Tip,text)
    if not UI.Tip.Visible then UI.Tip.Position=UDim2.fromOffset(x-6,y) end
    UI.Tip.Visible=true
    UI.tween(UI.Tip,{BackgroundTransparency=0.04,TextTransparency=0,Position=UDim2.fromOffset(x,y)},0.16); UI.tween(UI.TipEdge,{Transparency=0.45},0.16)
    -- A tap has no "pointer leaves": on a touch screen the name shows for a moment only.
    if UIS.TouchEnabled and not UIS.MouseEnabled then
        task.delay(1.2,function() if serial==UI.TipSerial then UI.tip(nil) end end)
    end
end

-- A square button with one icon in its middle (window buttons, menu).
function UI.iconButton(parent,icon,callback,size)
    local entry=UI.button(parent,"",false,callback,icon)
    entry.Root.Size=UDim2.fromOffset(size or 34,size or 34); entry.Root.BackgroundTransparency=0.35
    if entry.Icon then entry.Icon.Position=UDim2.new(0.5,-12,0.5,-12); UI.new("UIScale",{Scale=0.84},entry.Icon) end
    UI.round(entry.Root,11)
    return entry
end
-- Copies the Discord invite. Without clipboard access the Creator page shows the link to copy by hand.
function UI.copyInvite()
    local copy=type(setclipboard)=="function" and setclipboard or type(toclipboard)=="function" and toclipboard or nil
    if copy and pcall(copy,App.Creator.Discord) then
        App.toast({Title="Discord invite copied",Text="Paste it in your browser or in Discord to join.",Kind="success",Icon="discord",Duration=4})
        return true
    end
    UI.selectTab("Creator"); App.report("Automatic clipboard access is unavailable. Select the link and copy it manually.","warning")
    return false
end

function UI.buildShell()
    local pg=lp:FindFirstChild("PlayerGui") or lp:WaitForChild("PlayerGui",10)
    assert(pg,"PlayerGui is unavailable.")
    pcall(UI.loadIcons)
    local containers=UI.guiParents(); table.insert(containers,pg)
    for _,container in ipairs(containers) do
        pcall(function()
            for _, name in ipairs({"CopierHubGUI","CopierMobileControls"}) do local old=container:FindFirstChild(name); if old then old:Destroy() end end
        end)
    end
    local lighting=game:GetService("Lighting")
    for _, name in ipairs({"CopierLiquidBlur","CopierLiquidColor"}) do local old=lighting:FindFirstChild(name); if old then old:Destroy() end end
    UI.Gui=UI.new("ScreenGui",{Name="CopierHubGUI",ResetOnSpawn=false,DisplayOrder=990,ZIndexBehavior=Enum.ZIndexBehavior.Sibling,IgnoreGuiInset=false})
