    -- Each frame: the frame-rate watch (see MOTION) and the sheen, which follows the camera (full motion only).
    local elapsed,frames,second=0,0,0
    UI.connect(RS.RenderStepped,function(dt)
        dt=dt or 0
        -- Labels whose box or text changed are fitted again, all at once (see FITTED TEXT).
        if next(UI.FitDirty) then
            local list={}
            for label in pairs(UI.FitDirty) do table.insert(list,label) end
            table.clear(UI.FitDirty)
            for _,label in ipairs(list) do UI.refit(label) end
        end
        if UI.Visible and not UI.Minimized and not UI.Motion.Auto and not Store.Settings.ReducedMotion and not Store.Settings.LowEffects then
            frames=frames+1; second=second+dt
            if second>=1 then
                local fps=frames/second; frames,second=0,0
                UI.Motion.Slow=fps<40 and UI.Motion.Slow+1 or 0
                if UI.Motion.Slow>=4 then UI.Motion.Auto=true; pcall(UI.effects) end
            end
        else frames,second=0,0 end
        if not UI.Visible or UI.Minimized or UI.motion()~="full" then return end
        elapsed=elapsed+dt; if elapsed<1/30 then return end; elapsed=0
        local camera=workspace.CurrentCamera
        if camera and UI.Sheen then
            local look=camera.CFrame.LookVector
            UI.Sheen.Rotation=UI.Sheen.Rotation+(65+look.X*12-look.Y*8-UI.Sheen.Rotation)*0.12
        end
    end)
end
-- True when an x (screen pixels) is over the header's buttons, where a press must not start dragging the window.
function UI.overHeaderButtons(x)
    local find=UI.QuickFindButton
    if find and x>=find.AbsolutePosition.X-4 then return true end
    local menu=UI.MenuButton and UI.MenuButton.Root
    if menu and menu.Visible and x<=menu.AbsolutePosition.X+menu.AbsoluteSize.X+4 then return true end
    return false
end
function UI.drag(handle, target, orb)
    local drag, touch, start, origin, moved
    UI.connect(handle.InputBegan,function(input)
        if input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then return end
        local scale=UI.CurrentScale or 1
        if not orb and (UI.Maximized or UI.overHeaderButtons(input.Position.X) or (UI.Narrow and handle==UI.Brand)) then return end
        -- Stop any layout animation on the window so it doesn't fight the drag.
        if not orb and UI.Tweens[UI.Main] then UI.Tweens[UI.Main]:Cancel(); UI.Tweens[UI.Main]=nil end
        drag=true; touch=input.UserInputType==Enum.UserInputType.Touch and input or nil; start=Vector2.new(input.Position.X,input.Position.Y); origin=target.AbsolutePosition-UI.Surface.AbsolutePosition; moved=false
    end)
    UI.connect(UIS.InputChanged,function(input)
        if not drag then return end
        if touch and input~=touch then return end
        if not touch and input.UserInputType~=Enum.UserInputType.MouseMovement then return end
        local delta=Vector2.new(input.Position.X,input.Position.Y)-start
        if delta.Magnitude>7 then moved=true end
        if moved then
            if orb then UI.OrbIgnoreUntil=os.clock()+1 end
            local size=UI.Surface.AbsoluteSize; local wanted=origin+delta
            target.Position=UDim2.fromOffset(math.clamp(wanted.X,8,math.max(8,size.X-target.AbsoluteSize.X-8)),math.clamp(wanted.Y,8,math.max(8,size.Y-target.AbsoluteSize.Y-8)))
        end
    end)
    UI.connect(UIS.InputEnded,function(input)
        if drag and ((touch and input==touch) or (not touch and input.UserInputType==Enum.UserInputType.MouseButton1)) then
            if orb and moved then UI.OrbIgnoreUntil=os.clock()+0.3 end
            drag=false; touch=nil
        end
    end)
end
UI.NavOrder={"Home","Avatar","Players","Collection","Looks","Catalog","Customize","Auto","Plugins","Settings","Creator"}
-- The Debug page is only for dev builds (see DEV: DEBUG CAPTURE).
if Debug.enabled() then table.insert(UI.NavOrder,"Debug"); table.insert(UI.NavGroups[#UI.NavGroups].Items,"Debug") end
-- Window geometry. HeaderH is the height of a minimized window; the window is sized in unscaled pixels and UIScale
-- shrinks or grows it. SideW is the sidebar, RailW the rail of icons, DrawerW the drawer of a narrow window.
UI.HeaderH=72; UI.SideW=212; UI.RailW=64; UI.DrawerW=240
function UI.scale()
    local percent=Store.Settings.UIScale
    if percent and percent>0 then return percent/100 end
    local size=UI.Surface and UI.Surface.AbsoluteSize or Vector2.new(1280,720)
    -- Auto: a touch smaller on phones, where every pixel of the game view matters.
    return math.min(size.X,size.Y)<500 and 0.94 or 1
end
function UI.layout(center)
    if not UI.Main then return end
    local size=UI.Surface.AbsoluteSize
    if size.X<1 or size.Y<1 then return end
    local scale=UI.scale(); local scaleChanged=UI.CurrentScale~=nil and UI.CurrentScale~=scale; UI.CurrentScale=scale
    -- Motion: 0.25 s for Settings/Reset changes, a light 0.08 s smoothing while the corner grip is dragged.
    local motion=UI.Resizing and 0.08 or 0.25
    if UI.Visible and UI.WindowScale and (scaleChanged or (UI.WindowScale.Scale~=scale and not UI.ShowingTo)) then UI.tween(UI.WindowScale,{Scale=scale},motion) end
    local availW,availH=math.max(300,(size.X-20)/scale),math.max(240,(size.Y-20)/scale)
    local phone=math.min(size.X,size.Y)<500
    local w,h
    if UI.Maximized then w,h=availW,availH
    else
        w=Store.Settings.WindowW>0 and Store.Settings.WindowW or (phone and 560 or 880)
        w=math.clamp(w,300,availW)
        h=Store.Settings.WindowH>0 and Store.Settings.WindowH or ((phone or w<520) and availH or 680)
        h=math.clamp(h,240,availH)
    end
    local header=UI.HeaderH
    local shown=not UI.Minimized
    UI.Narrow=w<560
    UI.Rail=not UI.Narrow and w<820
    local side=UI.Narrow and 0 or (UI.Rail and UI.RailW or UI.SideW)
    local left=(shown and not UI.Narrow) and side+16 or 10
    local contentWidth=w-left-10
    UI.ContentWidth=contentWidth
    UI.Compact=contentWidth<470
    UI.LowHeight=h<480
    UI.FullHeight=h
    local visualW,visualH=w*scale,(shown and h or header)*scale
    -- While the window flies open, lay it out around where it is landing, not where it is right now.
    local pos=UI.ShowingTo or UI.Main.Position
    local x=center and (size.X-visualW)/2 or pos.X.Offset
    local y=center and (size.Y-visualH)/2 or pos.Y.Offset
    -- Size and position animate together (one tween per object), so a reset glides back to the centre.
    local goal={Size=UDim2.fromOffset(w,shown and h or header),
        Position=UDim2.fromOffset(math.clamp(x,10,math.max(10,size.X-visualW-10)),math.clamp(y,10,math.max(10,size.Y-visualH-10)))}
    if not (UI.ShowingTo and UI.ShowingTo==goal.Position and UI.Main.Size==goal.Size) then
        UI.tween(UI.Main,goal,motion)
