    UI.ResizeGrip.Visible=shown and not UI.Maximized
    -- Sidebar: a column, a rail of icons, or a drawer sliding over the page.
    local drawer=UI.Narrow
    local open=drawer and UI.Drawer==true and shown
    if not drawer then UI.Drawer=false end
    local sideWidth=drawer and math.min(UI.DrawerW,w-48) or side
    UI.Sidebar.Visible=shown
    UI.Sidebar.BackgroundTransparency=drawer and 0.02 or 0.35
    UI.tween(UI.Sidebar,{Position=UDim2.fromOffset((drawer and not open) and -(sideWidth+24) or 8,8),Size=UDim2.new(0,sideWidth,1,-16)},drawer and 0.32 or motion)
    UI.DrawerSerial=(UI.DrawerSerial or 0)+1; local drawerSerial=UI.DrawerSerial
    if open then UI.DrawerScrim.Visible=true; UI.tween(UI.DrawerScrim,{BackgroundTransparency=0.45},0.25)
    elseif UI.DrawerScrim.Visible then
        UI.tween(UI.DrawerScrim,{BackgroundTransparency=1},0.2)
        task.delay(UI.motion()=="off" and 0 or 0.21,function() if drawerSerial==UI.DrawerSerial and App.alive() then UI.DrawerScrim.Visible=false end end)
    end
