    UI.tween(UI.Content,{Position=UDim2.fromOffset(left,header),Size=UDim2.new(1,-left-10,1,-(header+44))},motion)
    UI.ContentVeil.Position=UDim2.fromOffset(left,header); UI.ContentVeil.Size=UDim2.new(1,-left-10,1,-(header+44))
    UI.tween(UI.Overlay,{Position=UDim2.fromOffset(left,header),Size=UDim2.new(1,-left-10,1,-(header+44))},motion)
    UI.Overlay.Visible=shown
    UI.tween(UI.Status,{Position=UDim2.new(0,left,1,-38),Size=UDim2.new(1,-left-46,0,28)},motion)
    local menu=drawer and shown
    UI.MenuButton.Root.Visible=menu
    local hx=menu and 44 or 0
    local tight=contentWidth<560
    local findWidth=tight and 34 or 168
    UI.PageIcon.Position=UDim2.fromOffset(hx,10)
    UI.QuickFindButton.Size=UDim2.fromOffset(findWidth,34); UI.QuickFindButton.Position=UDim2.new(1,-(114+8+findWidth),0,11)
    UI.QuickFindIcon.Position=tight and UDim2.new(0.5,-12,0.5,-12) or UDim2.new(0,8,0.5,-12)
    UI.FindLabel.Visible=not tight; UI.FindKey.Visible=not tight and UIS.KeyboardEnabled
    local reserve=114+8+findWidth+10
    UI.HeaderTitle.TextSize=UI.size(UI.Narrow and 16 or 19)
    UI.HeaderTitle.Position=UDim2.fromOffset(hx+48,UI.LowHeight and 16 or 8); UI.HeaderTitle.Size=UDim2.new(1,-(hx+48+reserve),0,24)
    UI.HeaderSubtitle.Position=UDim2.fromOffset(hx+48,32); UI.HeaderSubtitle.Size=UDim2.new(1,-(hx+48+reserve),0,16)
    UI.HeaderSubtitle.Visible=not UI.LowHeight
    UI.layoutNav(UI.Rail and not drawer,UI.LowHeight)
    if UI.Tip and not UI.Rail then UI.Tip.Visible=false end
    if UI.AvatarHeading then UI.AvatarHeading.Visible=not UI.LowHeight end
    -- On narrow windows the three timeline buttons drop their icons so each label fits.
    for _,button in ipairs({UI.Undo,UI.Customize,UI.Restore}) do
