    -- The theme gallery fills its card's width with as many tiles of about 116 px as fit.
    local galleryWidth=contentWidth-8-28
    local columns=math.clamp(math.floor((galleryWidth+8)/(112+8)),2,7)
    for _,grid in ipairs(UI.ThemeGrids or {}) do grid.CellSize=UDim2.new(1/columns,-math.ceil(8*(columns-1)/columns),0,94) end
