function UI.favoriteText()
    local starred=App.Preview and App.favoriteIndex(App.Preview)
    if UI.Compact then return starred and "Unfavorite" or "Favorite" end
    return starred and "Remove favorite" or "Add favorite"
end
-- The sidebar's inside for its width and height. Every page should fit without scrolling, so it takes the first of
-- these that fits: the Discord card and your profile on two rows (or, when room is short, your profile with a Discord
-- button beside it), group names over the groups (or thin rules between them) and rows of 42 px (or 36 px). Only a
-- very short window scrolls. A rail shows the icons only.
function UI.layoutNav(mini,low)
    local brand=62
    local items,groups=0,0
    for _,group in ipairs(UI.NavGroups) do items=items+#group.Items; if group.Caption then groups=groups+1 end end
    local function need(step,captions) return items*step+groups*(captions and 26 or 11)+#UI.NavGroups*4+4 end
    local footerHeight,captions,step,compact
-- cache YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
    for _,try in ipairs({{false,true,42},{false,false,42},{true,true,42},{true,false,42},{true,false,36}}) do
        local f=low and 0 or (mini and 100 or (try[1] and 56 or 108))
        local room=(UI.FullHeight or 620)-16-brand-f-(f>0 and 16 or 6)
        if need(try[3],try[2] and not mini)<=room then footerHeight,captions,step,compact=f,try[2] and not mini,try[3],try[1]; break end
    end
    if not footerHeight then footerHeight,captions,step,compact=low and 0 or (mini and 100 or 56),false,36,true end
    UI.SideFooter.Visible=footerHeight>0
    UI.SideFooter.Size=UDim2.new(1,0,0,footerHeight)
    UI.DiscordChip.ZIndex=2
    if mini then
        UI.DiscordChip.Position=UDim2.new(0.5,-22,0,0); UI.DiscordChip.Size=UDim2.fromOffset(44,44)
        UI.ProfileChip.Position=UDim2.new(0.5,-22,0,52); UI.ProfileChip.Size=UDim2.fromOffset(44,48)
        UI.DiscordIcon.Position=UDim2.new(0.5,-12,0.5,-12); UI.ProfilePhoto.Position=UDim2.new(0.5,-18,0.5,-18)
    elseif compact then
        UI.ProfileChip.Position=UDim2.fromOffset(8,2); UI.ProfileChip.Size=UDim2.new(1,-16,0,52)
        UI.DiscordChip.Position=UDim2.new(1,-50,0,10); UI.DiscordChip.Size=UDim2.fromOffset(36,36)
        UI.DiscordIcon.Position=UDim2.new(0.5,-12,0.5,-12); UI.ProfilePhoto.Position=UDim2.new(0,8,0.5,-18)
    else
        UI.DiscordChip.Position=UDim2.fromOffset(8,0); UI.DiscordChip.Size=UDim2.new(1,-16,0,48)
        UI.ProfileChip.Position=UDim2.fromOffset(8,56); UI.ProfileChip.Size=UDim2.new(1,-16,0,52)
        UI.DiscordIcon.Position=UDim2.new(0,12,0.5,-12); UI.ProfilePhoto.Position=UDim2.new(0,8,0.5,-18)
    end
    for _,label in ipairs({UI.ProfileName,UI.ProfileSub,UI.BrandTitle,UI.BrandSub}) do label.Visible=not mini end
    UI.DiscordTitle.Visible=not mini and not compact; UI.DiscordSub.Visible=not mini and not compact
    UI.ProfileName.Size=UDim2.new(1,compact and -104 or -58,0,18); UI.ProfileSub.Size=UDim2.new(1,compact and -104 or -58,0,15)
    UI.Logo.Position=mini and UDim2.new(0.5,-19,0,12) or UDim2.fromOffset(12,12)
    UI.Brand.Size=UDim2.new(1,0,0,brand)
    UI.Nav.Position=UDim2.fromOffset(0,brand); UI.Nav.Size=UDim2.new(1,0,1,-(brand+footerHeight+(footerHeight>0 and 16 or 6)))
    local y,height=2,step-4
    for _,group in ipairs(UI.NavGroups) do
        local caption=group.CaptionItem
        if caption then
            caption.Label.Visible=captions; caption.Rule.Visible=not captions
            if captions then caption.Label.Position=UDim2.fromOffset(18,y+4); y=y+26
            else caption.Rule.Position=UDim2.new(0,14,0,y+5); caption.Rule.Size=UDim2.new(1,-28,0,1); y=y+11 end
        end
        for _,name in ipairs(group.Items) do
            local entry=UI.NavButtons[name]
            entry.Root.Position=mini and UDim2.new(0.5,-22,0,y) or UDim2.fromOffset(8,y)
            entry.Root.Size=mini and UDim2.fromOffset(44,height) or UDim2.new(1,-16,0,height)
            entry.Icon.Position=mini and UDim2.new(0.5,-12,0.5,-12) or UDim2.new(0,11,0.5,-12)
            entry.Label.Visible=not mini
            entry.Badge.AnchorPoint=mini and Vector2.new(0.5,0.5) or Vector2.new(1,0.5)
            entry.Badge.Position=mini and UDim2.new(1,-6,0,7) or UDim2.new(1,-10,0.5,0)
            entry.Badge.Size=mini and UDim2.fromOffset(16,14) or UDim2.fromOffset(22,18)
            y=y+step
        end
        y=y+4
    end
    UI.Nav.CanvasSize=UDim2.fromOffset(0,y+4)
    UI.moveGlide(false)
end
-- Moves the highlight to the page in use (gliding there, or at once).
function UI.moveGlide(animate)
    local entry=UI.NavButtons[UI.Tab]
    if not entry or not UI.NavGlide then return end
    UI.NavGlide.Visible=true
    local goal={Position=entry.Root.Position,Size=entry.Root.Size}
    if not animate then UI.tween(UI.NavGlide,goal,0); return end
    UI.tween(UI.NavGlide,goal,0.36,Enum.EasingStyle.Quint)
    -- The marker stretches while it travels and settles with a bounce.
    if UI.motion()=="full" then
        UI.NavMarker.Size=UDim2.fromOffset(3,30)
        UI.tween(UI.NavMarker,{Size=UDim2.fromOffset(3,18)},0.45,Enum.EasingStyle.Back)
    end
end
-- A page's count on its sidebar item (0 hides it); a new count pops in.
function UI.setNavBadge(name,count)
    local entry=UI.NavButtons[name]
    if not entry then return end
    local show=(count or 0)>0
    -- One digit fits the badge; more reads "9+", never a smaller number than there is.
    local text=show and (count>9 and "9+" or tostring(count)) or ""
    if entry.Badge.Text==text and entry.Badge.Visible==show then return end
    entry.Badge.Text=text; entry.Badge.Visible=show
    entry.Label.Size=UDim2.new(1,show and -76 or -52,1,0)
    if show and UI.motion()=="full" then entry.BadgeScale.Scale=0.3; UI.tween(entry.BadgeScale,{Scale=1},0.4,Enum.EasingStyle.Back) end
end
-- The header: the page's icon, name and what it is for. Changing page fades the new ones in, the icon with a pop.
function UI.setHeader(name,animate)
    local info=UI.TabInfo[name] or {}
    UI.setText(UI.HeaderTitle,info.Label or name); UI.setText(UI.HeaderSubtitle,info.About or "")
    if UI.PageGlyph then UI.PageGlyph:Destroy() end
    UI.PageGlyph=UI.icon(UI.PageIcon,info.Icon or "star",UDim2.fromScale(0.5,0.5),UI.C.Accent); UI.PageGlyph.AnchorPoint=Vector2.new(0.5,0.5)
    UI.PageIconScale=UI.new("UIScale",{Scale=1},UI.PageGlyph)
    if animate and UI.motion()~="off" then
        UI.HeaderTitle.TextTransparency=1; UI.HeaderSubtitle.TextTransparency=1
        UI.tween(UI.HeaderTitle,{TextTransparency=0},0.28); UI.tween(UI.HeaderSubtitle,{TextTransparency=0},0.32,nil,nil,0.06)
        UI.PageIconScale.Scale=0.55; UI.tween(UI.PageIconScale,{Scale=1},0.42,Enum.EasingStyle.Back)
    else UI.HeaderTitle.TextTransparency=0; UI.HeaderSubtitle.TextTransparency=0 end
end
-- The status line's dot sends a ripple out with each message; while something loads it keeps rippling.
function UI.statusPing(kind)
    local ripple,color=UI.StatusRipple,UI.StatusDot and UI.StatusDot.BackgroundColor3
    if not ripple or UI.motion()=="off" then return end
    ripple.BackgroundColor3=color or UI.C.Accent
    if kind=="loading" and UI.motion()=="full" then
        UI.stopPulse(ripple)
        ripple.Size=UDim2.fromScale(1,1); ripple.BackgroundTransparency=0.35
        UI.pulse(ripple,{Size=UDim2.fromScale(2.6,2.6),BackgroundTransparency=1},0.9)
        return
    end
    UI.stopPulse(ripple)
    ripple.Size=UDim2.fromScale(1,1); ripple.BackgroundTransparency=0.3
    UI.tween(ripple,{Size=UDim2.fromScale(3,3),BackgroundTransparency=1},0.6,Enum.EasingStyle.Quad)
end
function UI.effects(keepOrb)
    if not keepOrb then UI.Orb.Visible=(not UI.Visible or UI.Minimized) and Store.Settings.MobileOrb==true end
    local rich=UI.motion()=="full"
    UI.tween(UI.Blur,{Size=UI.Visible and not UI.Minimized and Store.Settings.GlassBlur and not Store.Settings.LowEffects and not UI.Motion.Auto and 9 or 0},0.25)
    UI.Main.BackgroundTransparency=Store.Settings.LowEffects and 0 or 0.12
    UI.Glow.Visible=not Store.Settings.LowEffects and not UI.Motion.Auto
    -- The floating button's ring breathes while it waits (full motion only).
    if rich and UI.Orb.Visible then UI.pulse(UI.OrbRing,{Transparency=0.7},1.5) else UI.stopPulse(UI.OrbRing,{Transparency=0.15}) end
end
-- Bottom-right grip: drag to resize the window live. The size is remembered.
function UI.buildResizeGrip()
    local grip=UI.new("TextButton",{Name="ResizeGrip",AnchorPoint=Vector2.new(1,1),Position=UDim2.new(1,-7,1,-7),Size=UDim2.fromOffset(28,28),Text="",
        BackgroundColor3=UI.C.Raised,BackgroundTransparency=0.35,AutoButtonColor=false,BorderSizePixel=0,ZIndex=30},UI.Main); UI.round(grip,10)
    -- Three diagonal strokes, the usual "resize corner" mark.
    for i,length in ipairs({16,10,4}) do
        local line=UI.new("Frame",{AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.fromOffset(14+(i-1)*3.6,14+(i-1)*3.6),Size=UDim2.fromOffset(length,2),Rotation=-45,
            BackgroundColor3=UI.C.Accent,BorderSizePixel=0,ZIndex=31},grip); UI.round(line,2)
    end
    UI.ResizeGrip=grip
    -- Small badge with the live size, shown near the grip while dragging.
    UI.SizeBadge=UI.new("TextLabel",{AnchorPoint=Vector2.new(1,1),Size=UDim2.fromOffset(96,26),BackgroundColor3=UI.C.Base,BackgroundTransparency=1,
        TextColor3=UI.C.Text,TextTransparency=1,Font=UI.Font.Bold,TextSize=UI.size(12),Text="",BorderSizePixel=0,ZIndex=60},UI.Surface)
    UI.round(UI.SizeBadge,9); local badgeStroke=UI.stroke(UI.SizeBadge,1,UI.C.Accent)
    local function badge(visible)
        local w,h=Store.Settings.WindowW,Store.Settings.WindowH
        UI.SizeBadge.Text=tostring(math.floor(w)).." × "..tostring(math.floor(h))
        local corner=UI.Main.AbsolutePosition+UI.Main.AbsoluteSize-UI.Surface.AbsolutePosition
        UI.SizeBadge.Position=UDim2.fromOffset(corner.X-4,corner.Y-40)
        UI.tween(UI.SizeBadge,{BackgroundTransparency=visible and 0.08 or 1,TextTransparency=visible and 0 or 1},visible and 0.12 or 0.4)
        UI.tween(badgeStroke,{Transparency=visible and 0.35 or 1},visible and 0.12 or 0.4)
    end
    local active,touch,start,startW,startH
    UI.connect(grip.InputBegan,function(input)
        if input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then return end
        active=true; touch=input.UserInputType==Enum.UserInputType.Touch and input or nil
        start=Vector2.new(input.Position.X,input.Position.Y); startW=UI.Main.Size.X.Offset; startH=UI.Main.Size.Y.Offset
        UI.Resizing=true; UI.Maximized=false
        UI.tween(grip,{BackgroundTransparency=0},0.1)
    end)
    UI.connect(UIS.InputChanged,function(input)
        if not active then return end
        if touch and input~=touch then return end
        if not touch and input.UserInputType~=Enum.UserInputType.MouseMovement then return end
        local scale=UI.CurrentScale or 1
        local delta=(Vector2.new(input.Position.X,input.Position.Y)-start)/scale
        local size=UI.Surface.AbsoluteSize; local corner=UI.Main.AbsolutePosition-UI.Surface.AbsolutePosition
        Store.Settings.WindowW=math.floor(math.clamp(startW+delta.X,300,math.max(300,(size.X-corner.X-10)/scale)))
        Store.Settings.WindowH=math.floor(math.clamp(startH+delta.Y,240,math.max(240,(size.Y-corner.Y-10)/scale)))
        UI.layout(false); badge(true)
    end)
    UI.connect(UIS.InputEnded,function(input)
        if active and ((touch and input==touch) or (not touch and input.UserInputType==Enum.UserInputType.MouseButton1)) then
            active=false; touch=nil; UI.Resizing=false
            UI.tween(grip,{BackgroundTransparency=0.35},0.15)
            UI.layout(false); App.persist()
            task.delay(0.5,function() if App.alive() and not active then badge(false) end end)
        end
    end)
end
-- With the floating button off there is no on-screen way back, so say how to reopen.
-- Ways to reopen the window that work for this player, in the order they are suggested. Chat counts
-- unless Roblox says this account cannot chat (when that is unknown it is still offered).
UI.ChatOK=nil; UI.ChatChecked=false
function UI.detectChat()
    task.spawn(function()
        local ok,can=pcall(function() return game:GetService("TextChatService"):CanUserChatAsync(lp.UserId) end)
        UI.ChatChecked=true
        if App.alive() and ok and type(can)=="boolean" then UI.ChatOK=can end
        if App.alive() then UI.refreshReopenCard() end
    end)
end
function UI.reopenMethods()
    local list={}
    if UIS.KeyboardEnabled then table.insert(list,"press "..Store.Settings.Keybind) end
    if Store.Settings.MenuReopen then table.insert(list,"open and close the Roblox menu 3 times") end
    if UI.ChatOK~=false then table.insert(list,"type /e copier in chat") end
    return list
end
function UI.canReopen() return Store.Settings.MobileOrb==true or #UI.reopenMethods()>0 end
function UI.joinList(list)
    if #list<=1 then return list[1] or "" end
    if #list==2 then return list[1].." or "..list[2] end
    return table.concat(list,", ",1,#list-1)..", or "..list[#list]
end
function UI.reopenText()
    local list=UI.reopenMethods()
    return #list>0 and ("To reopen it, "..UI.joinList(list)..".") or "Turn on a reopen method in Settings."
end
-- With the floating button off there is no on-screen way back, so say how to reopen: only the methods that
-- work on this device are named.
function UI.hiddenHint()
    if not Store.Settings.MobileOrb then
        App.toast({Title = "Avatar Studio hidden", Text = UI.reopenText(), Kind = "info", Icon = "eye-off", Duration = 6})
    end
end
function UI.hide()
    UI.setVisible(false); UI.hiddenHint()
end
-- Closing the window. With the floating button on there is always a way back. With it off, the window is
-- never hidden without one: nothing available asks to turn the Roblox menu shortcut on, and the first
-- hide asks for a confirmation that stays open on its own if nobody answers.
function UI.closeHub()
    if not UI.Visible then return end
    if Store.Settings.MobileOrb then UI.hide(); return end
    if #UI.reopenMethods()==0 then
        UI.confirm("Nothing can reopen the window","Chat is unavailable, there is no keyboard and the Roblox menu shortcut is off. Turn the shortcut on and hide the window?",function()
            Store.Settings.MenuReopen=true; App.persist()
            local refresh=UI.Toggles and UI.Toggles.MenuReopen; if refresh then refresh() end
            UI.refreshReopenCard(); UI.hide()
        end,{Confirm="Turn on and hide",Cancel="Keep open",Seconds=15})
        return
    end
    if not Store.Settings.HideTipSeen then
        UI.confirm("Hide Avatar Studio?",UI.reopenText().." Make sure you can use one of these before hiding.",function()
            Store.Settings.HideTipSeen=true; App.persist(); UI.hide()
        end,{Confirm="Hide it",Cancel="Keep open",Seconds=10})
        return
    end
    UI.hide()
end
-- Window flight: hiding shrinks the window into the floating button (or, with the button off, into a
-- brand badge at the window's centre that then pops away); showing grows it back out the same way.
-- Only the window's Position and UIScale tween, on one shared curve, so its centre glides in a
-- straight line and nothing inside it re-lays out.
UI.FlightTime=0.42; UI.FlightScale=0.06
function UI.orbCenter()
    local size=UI.Surface.AbsoluteSize; local p=UI.Orb.Position
    return Vector2.new(p.X.Scale*size.X+p.X.Offset+UI.Orb.Size.X.Offset/2,p.Y.Scale*size.Y+p.Y.Offset+UI.Orb.Size.Y.Offset/2)
end
function UI.windowCenter(position,scale)
    return Vector2.new(position.X.Offset+UI.Main.Size.X.Offset*scale/2,position.Y.Offset+UI.Main.Size.Y.Offset*scale/2)
end
function UI.flightBadge(point)
    if not UI.Badge then
        UI.Badge=UI.new("Frame",{AnchorPoint=Vector2.new(0.5,0.5),Size=UDim2.fromOffset(56,56),BackgroundColor3=UI.C.AccentDark,BorderSizePixel=0,Visible=false,ZIndex=80},UI.Surface)
        UI.round(UI.Badge,18); UI.stroke(UI.Badge,0.15,UI.C.Accent); UI.brandMark(UI.Badge,18,20)
        UI.BadgeScale=UI.new("UIScale",{Scale=0},UI.Badge)
    end
    UI.Badge.Position=UDim2.fromOffset(point.X,point.Y)
    return UI.Badge
end
function UI.setVisible(value)
    -- Opening an open window (the chat command can arrive through several chat events) or closing a
    -- closed one does nothing, so a second call can never strand the badge or restart the flight.
    if value==UI.Visible then return end
    UI.VisibilityGeneration=(UI.VisibilityGeneration or 0)+1; local generation=UI.VisibilityGeneration
    if UI.Badge then UI.Badge.Visible=false end
    UI.Visible=value
    if UI.closeDropdown then UI.closeDropdown(true) end
    local scale=UI.CurrentScale or UI.scale()
    local time=UI.FlightTime
    local still=Store.Settings.ReducedMotion or Store.Settings.LowEffects
    local useOrb=Store.Settings.MobileOrb==true
    local function later(delay,fn) task.delay(still and 0 or delay,function() if App.alive() and generation==UI.VisibilityGeneration then fn() end end) end
    local function spot(point) return UDim2.fromOffset(point.X-UI.Main.Size.X.Offset*scale*UI.FlightScale/2,point.Y-UI.Main.Size.Y.Offset*scale*UI.FlightScale/2) end
    if value then
        UI.restoreScroll(UI.Tab)
        if UI.Tab=="Looks" and UI.LooksView=="Chat" and UI.openChat then task.defer(UI.openChat) end
        local home=UI.HomePosition or UI.Main.Position; UI.HomePosition=nil; UI.ShowingTo=home
        later(time,function() UI.ShowingTo=nil end)
        if UI.Main.Visible then
            -- Reopened mid-flight: turn around from wherever the window is.
            UI.tween(UI.Main,{Position=home},time*0.7); UI.tween(UI.WindowScale,{Scale=scale},time*0.7)
        else
            local point=useOrb and UI.orbCenter() or UI.windowCenter(home,scale)
            UI.Main.Position=spot(point); UI.WindowScale.Scale=scale*UI.FlightScale; UI.Main.Visible=true
            local delay=0
            if not useOrb then
                local badge=UI.flightBadge(point); badge.Visible=true; UI.BadgeScale.Scale=0.4
                UI.tween(UI.BadgeScale,{Scale=1},0.18,Enum.EasingStyle.Back)
                later(0.2,function() UI.tween(UI.BadgeScale,{Scale=0},0.22,Enum.EasingStyle.Back,Enum.EasingDirection.In) end)
                later(0.44,function() badge.Visible=false end)
                delay=0.1
            end
            later(delay,function()
                UI.tween(UI.Main,{Position=UI.ShowingTo or home},time,Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
                UI.tween(UI.WindowScale,{Scale=scale},time,Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
            end)
        end
        if useOrb and UI.Orb.Visible then
            UI.tween(UI.OrbScale,{Scale=0.55},0.16)
            UI.effects(true); later(0.16,function() UI.effects(); UI.OrbScale.Scale=1 end)
        else UI.effects() end
        return
    end
    UI.saveHubState(true)
    if not UI.Main.Visible then UI.effects(); return end
    local home=UI.ShowingTo or UI.Main.Position; UI.ShowingTo=nil; UI.HomePosition=home
    local point=useOrb and UI.orbCenter() or UI.windowCenter(home,scale)
    if useOrb then
        -- The button appears first, then swells as the window lands inside it.
        UI.Orb.Visible=true; UI.OrbScale.Scale=0.7; UI.tween(UI.OrbScale,{Scale=1},0.24)
        later(time*0.9,function() UI.OrbScale.Scale=1.14; UI.tween(UI.OrbScale,{Scale=1},0.32,Enum.EasingStyle.Back) end)
--YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
    else
        local badge=UI.flightBadge(point); badge.Visible=true; UI.BadgeScale.Scale=0
        UI.tween(UI.BadgeScale,{Scale=1},0.26,Enum.EasingStyle.Back)
        later(time+0.04,function() UI.tween(UI.BadgeScale,{Scale=1.12},0.1) end)
        later(time+0.16,function() UI.tween(UI.BadgeScale,{Scale=0},0.24,Enum.EasingStyle.Back,Enum.EasingDirection.In) end)
        later(time+0.42,function() badge.Visible=false end)
    end
    UI.tween(UI.Main,{Position=spot(point)},time,Enum.EasingStyle.Quint,Enum.EasingDirection.InOut)
    UI.tween(UI.WindowScale,{Scale=scale*UI.FlightScale},time,Enum.EasingStyle.Quint,Enum.EasingDirection.InOut)
    later(time,function() UI.Main.Visible=false end)
    UI.effects(true)
end
function UI.selectTab(name)
    if not UI.Pages[name] then return end
    local previous=UI.Tab
    local changed=UI.Pages[previous]~=nil and previous~=name
    UI.Tab=name; UI.PageToken=UI.PageToken+1
    UI.closeDropdown(true)
    if UI.FindOpen then UI.closeFind(true) end
    UI.tip(nil); UI.hideBack()
    if UI.Drawer then UI.Drawer=false; UI.layout(false) end
    for key,page in pairs(UI.Pages) do page.Visible=key==name end
    -- The item in use: its name and icon light up while the highlight glides to it.
    for key,button in pairs(UI.NavButtons) do
        local on=key==name
        if on then button.Root.BackgroundTransparency=1 end
        UI.tween(button.Label,{TextColor3=on and UI.C.Text or UI.C.Muted},0.2)
        UI.recolor(button.Icon,on and UI.C.Accent or UI.C.Muted)
    end
    UI.moveGlide(changed)
    UI.setHeader(name,changed)
    -- The page rises a little into place while a veil over it melts away.
    local page=UI.Pages[name]
    local level=UI.motion()
    if changed and level~="off" then
        page.Position=UDim2.fromOffset(0,level=="full" and 18 or 8)
        UI.tween(page,{Position=UDim2.new()},level=="full" and 0.4 or 0.22,Enum.EasingStyle.Quint,Enum.EasingDirection.Out,nil,"slide")
        if level=="full" then
            UI.VeilSerial=(UI.VeilSerial or 0)+1; local serial=UI.VeilSerial
            UI.ContentVeil.Visible=true; UI.ContentVeil.BackgroundTransparency=0.3
            UI.tween(UI.ContentVeil,{BackgroundTransparency=1},0.28,Enum.EasingStyle.Quad)
            task.delay(0.3,function() if serial==UI.VeilSerial and UI.ContentVeil then UI.ContentVeil.Visible=false end end)
        end
    else page.Position=UDim2.new() end
    if name=="Home" then UI.openHome(changed)
    elseif name=="Players" then UI.renderPlayers() elseif name=="Collection" then UI.renderCollection() elseif name=="Looks" then UI.renderLooks(); if UI.LooksView=="Chat" then UI.openChat() end elseif name=="Catalog" then UI.renderCatalog() elseif name=="Customize" then UI.renderCustomize() elseif name=="Auto" then UI.renderAuto() elseif name=="Plugins" then UI.openPlugins() elseif name=="Creator" then UI.loadCreatorPhoto() end
    UI.restoreScroll(name); UI.saveHubState()
    UI.refreshTop()
end

-- =============================================================================
-- HOME: the first page. Who you are, the server and the session at a glance, the Discord, what's new in this version
-- (each change with a button that takes you to it), the players around you (wear or preview them in one tap) and a
-- three-step guide for a first copy. Its cards are placed by hand (no layout inside them), so each can appear with
-- the reveal; the numbers of the server refresh every second while Home is open.
-- =============================================================================
