-- The groups of What's new, in this order, each with its heading.
UI.NewsOrder={"new","better","fixed"}
UI.NewsKinds={new={Title="New features",Icon="sparkles",Color="Green"},better={Title="Improvements",Icon="zap",Color="Accent"},fixed={Title="Fixes",Icon="circle-check",Color="Gold"}}
function UI.newsSeen(key)
    return (","..(Store.Settings.SeenNews or "")..","):find(","..key..",",1,true)~=nil
end
function UI.unseenNews()
    local count=0
    for _,item in ipairs(UI.News.Items) do if not UI.newsSeen(item.Key) then count=count+1 end end
    return count
end
function UI.markNewsSeen(key)
    if UI.newsSeen(key) then return end
    -- Only keys of the current list are kept, so the setting never grows.
    local keep={}
    for _,item in ipairs(UI.News.Items) do if item.Key==key or UI.newsSeen(item.Key) then table.insert(keep,item.Key) end end
    Store.Settings.SeenNews=table.concat(keep,",")
    App.persist()
    UI.refreshNews()
end
-- A card of Home: placed by hand inside, with a body that rises in on reveal.
function UI.homeCard(parent,order,height,name,tint)
    local card=UI.new("Frame",{Name=name,LayoutOrder=order,Size=UDim2.new(1,0,0,height),BackgroundColor3=UI.C.Card,BackgroundTransparency=0.18,BorderSizePixel=0},parent)
    UI.round(card,18); UI.stroke(card,0.62)
    if tint then UI.new("UIGradient",{Color=ColorSequence.new(tint,UI.C.Card),Rotation=18},card) end
    local body=UI.new("Frame",{Name="Body",Size=UDim2.fromScale(1,1),BackgroundTransparency=1},card)
    return card,body
end
-- A card of Home that grows with its content: the body sits inside a 14 px margin.
function UI.homeAutoCard(parent,order,name)
    local card=UI.new("Frame",{Name=name,LayoutOrder=order,Size=UDim2.new(1,0,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundColor3=UI.C.Card,BackgroundTransparency=0.18,BorderSizePixel=0},parent)
    UI.round(card,18); UI.stroke(card,0.62)
    local body=UI.new("Frame",{Name="Body",Position=UDim2.fromOffset(14,14),Size=UDim2.new(1,-28,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1},card)
    body:SetAttribute("LyraRest",body.Position)
    UI.new("UIPadding",{PaddingBottom=UDim.new(0,14)},body)
    return card,body
end
-- A small rounded square with an icon, heading a card.
function UI.chipIcon(parent,icon,position,size)
    local chip=UI.new("Frame",{Position=position,Size=UDim2.fromOffset(size or 30,size or 30),BackgroundColor3=UI.C.AccentDark,BackgroundTransparency=0.35,BorderSizePixel=0},parent)
    UI.round(chip,9); UI.stroke(chip,0.6,UI.C.Accent)
    local glyph=UI.icon(chip,icon,UDim2.fromScale(0.5,0.5),UI.C.Accent); glyph.AnchorPoint=Vector2.new(0.5,0.5)
    UI.new("UIScale",{Scale=((size or 30)-10)/24},glyph)
    return chip,glyph
end
-- Numbers with thousands separators (2447 -> 2,447).
function UI.group(number)
    local text=tostring(math.floor(number or 0))
    local out=text:reverse():gsub("(%d%d%d)","%1,"):reverse()
    return (out:gsub("^,",""))
end
function UI.statCard(parent,title,icon,fields,name)
    local card,body=UI.homeCard(parent,0,112,name)
    UI.chipIcon(body,icon,UDim2.fromOffset(14,14))
    local heading=UI.text(body,title,13,nil,true); heading.Position=UDim2.fromOffset(52,14); heading.Size=UDim2.new(1,-64,0,30)
    local entry={Root=card,Body=body,Values={}}
    for index,field in ipairs(fields) do
        local cell=UI.new("Frame",{Name=field[2],Position=UDim2.new((index-1)/#fields,14,0,56),Size=UDim2.new(1/#fields,-14,0,44),BackgroundTransparency=1},body)
        local label=UI.text(cell,field[1],10,UI.C.Muted); label.Size=UDim2.new(1,0,0,16)
        UI.fit(label,9)
        local value=UI.text(cell,"—",15,nil,true); value.Name="Value"; value.Position=UDim2.fromOffset(0,18); value.Size=UDim2.new(1,0,0,22)
        UI.fit(value,11)
        entry.Values[field[2]]=value
    end
    return entry
end
-- Writes a value of a stat card. A value that changes flashes the accent for a moment, unless it is quiet (a clock
-- or a ping that changes all the time).
function UI.setStat(card,key,text,color,translate,quiet)
    local label=card and card.Values[key]
    if not label then return end
    local shown=translate and Lang.text(text) or text
    local rest=color or UI.C.Text
    if label.Text==shown then if not UI.Tweens[label] then label.TextColor3=rest end; return end
    local first=label.Text=="—"
    if translate then UI.setText(label,text) else label.Text=text end
    if first or quiet or UI.motion()=="off" then UI.tween(label,{TextColor3=rest},0); return end
    label.TextColor3=UI.C.Accent
    UI.tween(label,{TextColor3=rest},0.7,Enum.EasingStyle.Quad)
end
function UI.executorName()
    local ok,name=pcall(function() return identifyexecutor() end)
    if ok and type(name)=="string" and name~="" then return name:sub(1,24) end
    ok,name=pcall(function() return getexecutorname() end)
    if ok and type(name)=="string" and name~="" then return name:sub(1,24) end
    return "Unknown"
end
