-- The heading of one group of What's new: its icon and name in the group's colour, how many changes it has and a
-- thin line under it. Every heading after the first leaves some room above it.
function UI.newsGroup(parent,kind,count,order,first)
    local spec=UI.NewsKinds[kind]
    local color=UI.C[spec.Color]
    local head=UI.new("Frame",{Name="Group_"..kind,LayoutOrder=order,Size=UDim2.new(1,0,0,first and 28 or 40),BackgroundTransparency=1},parent)
    UI.new("Frame",{Name="Line",AnchorPoint=Vector2.new(0,1),Position=UDim2.fromScale(0,1),Size=UDim2.new(1,0,0,1),BackgroundColor3=UI.C.Line,BackgroundTransparency=0.45,BorderSizePixel=0},head)
    local icon=UI.icon(head,spec.Icon,UDim2.new(0,9,1,-16),color); icon.Name="Icon"; icon.AnchorPoint=Vector2.new(0.5,0.5); UI.new("UIScale",{Scale=0.62},icon)
    local label=UI.new("Frame",{Name="Label",AnchorPoint=Vector2.new(0,1),Position=UDim2.new(0,24,1,-6),Size=UDim2.new(1,-24,0,20),BackgroundTransparency=1},head)
    UI.new("UIListLayout",{FillDirection=Enum.FillDirection.Horizontal,VerticalAlignment=Enum.VerticalAlignment.Center,SortOrder=Enum.SortOrder.LayoutOrder,Padding=UDim.new(0,6)},label)
    local title=UI.text(label,spec.Title,12,color,true); title.Name="Title"; title.LayoutOrder=2
    title.AutomaticSize=Enum.AutomaticSize.X; title.Size=UDim2.fromOffset(0,20); title.TextTruncate=Enum.TextTruncate.None
    local pill=UI.new("TextLabel",{Name="Count",LayoutOrder=3,AutomaticSize=Enum.AutomaticSize.X,Size=UDim2.fromOffset(0,18),BackgroundColor3=color,BackgroundTransparency=0.82,
        Text=tostring(count),TextColor3=color,Font=UI.Font.Bold,TextSize=UI.size(10),BorderSizePixel=0},label)
    UI.round(pill,9); UI.new("UIPadding",{PaddingLeft=UDim.new(0,7),PaddingRight=UDim.new(0,7)},pill)
end
-- One change of What's new: its title in bold, what changed in a softer colour under it and a "Show me" button
-- (the whole row works too).
function UI.newsRow(parent,item,order)
    local row=UI.new("TextButton",{Name="News_"..item.Key,LayoutOrder=order,Size=UDim2.new(1,0,0,0),AutomaticSize=Enum.AutomaticSize.Y,Text="",AutoButtonColor=false,
        BackgroundColor3=UI.C.Raised,BackgroundTransparency=1,BorderSizePixel=0},parent)
    UI.round(row,12)
    UI.new("UIPadding",{PaddingTop=UDim.new(0,9),PaddingBottom=UDim.new(0,9)},row)
    local dot=UI.new("Frame",{Name="Unseen",Position=UDim2.fromOffset(4,6),Size=UDim2.fromOffset(6,6),BackgroundColor3=UI.C.Accent,BorderSizePixel=0},row)
    UI.new("UICorner",{CornerRadius=UDim.new(1,0)},dot)
    local body=UI.new("Frame",{Name="Body",Position=UDim2.fromOffset(18,0),Size=UDim2.new(1,-130,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1},row)
    UI.stack(body,3)
    local title=UI.paragraph(body,item.Title or "",13,UI.C.Text,true,1); title.Name="Title"
    local text=UI.paragraph(body,item.Text,12,UI.C.Muted,false,2); text.Name="Text"
    local jump=UI.new("TextButton",{Name="Jump",AnchorPoint=Vector2.new(1,0),Position=UDim2.new(1,-4,0,0),Size=UDim2.fromOffset(98,28),Text="",AutoButtonColor=false,
        BackgroundColor3=UI.C.AccentDark,BackgroundTransparency=0.35,BorderSizePixel=0},row)
    UI.round(jump,14); local jumpEdge=UI.stroke(jump,0.4,UI.C.Accent)
    local jumpLabel=UI.text(jump,"Show me",11,UI.C.Text,true); jumpLabel.Position=UDim2.fromOffset(12,0); jumpLabel.Size=UDim2.new(1,-38,1,0); jumpLabel.TextTruncate=Enum.TextTruncate.None
    local arrow=UI.icon(jump,"arrow-up-right",UDim2.new(1,-15,0.5,0),UI.C.Accent); arrow.AnchorPoint=Vector2.new(0.5,0.5); UI.new("UIScale",{Scale=0.72},arrow)
    UI.press(jump)
    local function open() UI.openNews(item) end
    UI.connect(row.Activated,open); UI.connect(jump.Activated,open)
    -- The arrow leans the way it points while the row is under the pointer.
    local function hover(on)
        UI.tween(row,{BackgroundTransparency=on and 0.6 or 1})
        UI.tween(jump,{BackgroundTransparency=on and 0.05 or 0.35}); UI.tween(jumpEdge,{Transparency=on and 0.1 or 0.4})
        UI.tween(arrow,{Position=on and UDim2.new(1,-12,0.5,-3) or UDim2.new(1,-15,0.5,0)},0.25,Enum.EasingStyle.Back)
    end
    UI.connect(row.MouseEnter,function() hover(true) end); UI.connect(row.MouseLeave,function() hover(false) end)
    UI.connect(jump.MouseEnter,function() hover(true) end)
    UI.NewsRows[item.Key]={Root=row,Dot=dot,Body=body,Title=title,Text=text,Jump=jump,JumpLabel=jumpLabel,Arrow=arrow}
end
function UI.openNews(item)
    UI.markNewsSeen(item.Key)
    if not UI.spotlight(item.Target) then App.report("That part of the window isn't available right now.","warning") end
end
-- Unseen dots, the count over the list and the badge on Home in the sidebar.
function UI.refreshNews()
    local unseen=UI.unseenNews()
    for _,item in ipairs(UI.News.Items) do
        local row=UI.NewsRows and UI.NewsRows[item.Key]
        if row then
            local seen=UI.newsSeen(item.Key)
            if row.Dot.Visible and seen and UI.motion()~="off" then
                UI.tween(row.Dot,{BackgroundTransparency=1},0.3)
                task.delay(0.31,function() if row.Dot then row.Dot.Visible=false; row.Dot.BackgroundTransparency=0 end end)
            else row.Dot.Visible=not seen end
        end
    end
    if UI.HomeNewsCount then UI.setText(UI.HomeNewsCount,unseen>0 and (tostring(unseen).." new") or "All seen") end
    UI.setNavBadge("Home",unseen)
end
-- The players of this server as tiles: script users first, then by name. At most six; See all opens the Server page.
function UI.renderHomePlayers()
    if not UI.HomePlayerGrid then return end
    UI.clearRows("home",UI.HomePlayerGrid)
    local list={}
    for _,player in ipairs(Players:GetPlayers()) do if player~=lp then table.insert(list,player) end end
    local function peer(player) return Sync.Peers and Sync.Peers[player.UserId]~=nil end
    table.sort(list,function(a,b)
        local pa,pb=peer(a),peer(b)
        if pa~=pb then return pa end
        return a.DisplayName:lower()<b.DisplayName:lower()
    end)
    UI.setText(UI.HomeSeeAll.Label,#list>6 and "See all" or "Server")
    if #list==0 then
        local empty=UI.new("Frame",{Name="Empty",LayoutOrder=1,BackgroundTransparency=1},UI.HomePlayerGrid)
        local label=UI.text(empty,"You're the only one here for now.",12,UI.C.Muted); label.Size=UDim2.fromScale(1,1); label.TextXAlignment=Enum.TextXAlignment.Center
        return
    end
    for index=1,math.min(#list,6) do
        local player=list[index]
        local profile={Id=player.UserId,Name=player.Name,DisplayName=player.DisplayName}
        local tile=UI.new("Frame",{Name="Player_"..player.Name,LayoutOrder=index,BackgroundColor3=UI.C.Raised,BackgroundTransparency=0.45,BorderSizePixel=0},UI.HomePlayerGrid)
        UI.round(tile,14); UI.stroke(tile,peer(player) and 0.35 or 0.72,peer(player) and UI.C.Accent or UI.C.Line)
        local face=UI.new("ImageLabel",{Position=UDim2.new(0,10,0.5,-20),Size=UDim2.fromOffset(40,40),BackgroundColor3=UI.C.Card,BorderSizePixel=0,
            Image="rbxthumb://type=AvatarHeadShot&id="..tostring(player.UserId).."&w=150&h=150"},tile)
        UI.new("UICorner",{CornerRadius=UDim.new(1,0)},face)
        local name=UI.text(tile,player.DisplayName,13,nil,true); name.Position=UDim2.fromOffset(58,11); name.Size=UDim2.new(1,-170,0,18)
        local sub=UI.text(tile,peer(player) and "Avatar Studio" or ("@"..player.Name),11,peer(player) and UI.C.Accent or UI.C.Muted); sub.Position=UDim2.fromOffset(58,31); sub.Size=UDim2.new(1,-170,0,16)
        local wear=UI.button(tile,"Wear",true,function() App.wearProfile(profile) end,nil,"home"); wear.Root.Name="Wear"
        wear.Root.Size=UDim2.fromOffset(62,32); wear.Root.Position=UDim2.new(1,-110,0.5,-16)
        local look=UI.button(tile,"",false,function()
            UI.selectTab("Avatar"); UI.SearchBox.Text=tostring(player.UserId); UI.query(UI.SearchBox.Text,true)
        end,"eye","home"); look.Root.Name="Preview"
        look.Root.Size=UDim2.fromOffset(38,32); look.Root.Position=UDim2.new(1,-44,0.5,-16)
        if look.Icon then look.Icon.Position=UDim2.new(0.5,-12,0.5,-12) end
        UI.reveal(tile,index)
    end
end
-- The three steps: a step you have done shows a check.
function UI.refreshGuide()
    if not UI.GuideSteps then return end
    local done={App.Preview~=nil or #Store.Recent>0,App.Preview~=nil,App.Current~=nil and App.Current~=App.Initial}
    for index,step in ipairs(UI.GuideSteps) do
        local now=done[index]==true
        if now~=step.Done then
            step.Done=now
            step.Number.Visible=not now; step.Check.Visible=now
            UI.tween(step.Dot,{BackgroundColor3=now and UI.C.Green or UI.C.AccentDark},0.3)
        end
    end
end
function UI.updateHomeStats()
    if not UI.HomeServer then return end
    local list=Players:GetPlayers()
    UI.setStat(UI.HomeServer,"players",tostring(#list))
    UI.setStat(UI.HomeServer,"max",tostring(Players.MaxPlayers))
    local ok,ping=pcall(function() return game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue() end)
    if not ok or type(ping)~="number" then ok,ping=pcall(function() return lp:GetNetworkPing()*2000 end) end
    if ok and type(ping)=="number" and ping==ping then
        ping=math.floor(ping+0.5)
        UI.setStat(UI.HomeServer,"ping",tostring(ping).." ms",ping<100 and UI.C.Green or ping<200 and UI.C.Gold or UI.C.Red,false,true)
    end
    local okTime,seconds=pcall(function() return workspace.DistributedGameTime end)
    if okTime and type(seconds)=="number" then
        seconds=math.max(0,math.floor(seconds))
        UI.setStat(UI.HomeServer,"uptime",seconds>=3600 and string.format("%d:%02d:%02d",seconds//3600,seconds%3600//60,seconds%60) or string.format("%d:%02d",seconds//60,seconds%60),nil,false,true)
    end
    UI.setStat(UI.HomeSession,"executor",UI.HomeExecutor or "Unknown",nil,(UI.HomeExecutor or "Unknown")=="Unknown")
    UI.setStat(UI.HomeSession,"build",UI.DevBuild and "Test build" or "Public",UI.DevBuild and UI.C.Gold or nil,true)
    UI.setStat(UI.HomeSession,"version",UI.Version)
end
-- Discord's own counts for the invite (online, members), when the executor can make web requests. They count up.
function UI.loadDiscordCounts()
    if UI.DiscordAsked then return end
    UI.DiscordAsked=true
    local code=tostring(App.Creator.Discord):match("discord%.gg/([%w%-]+)")
    local requestFn=type(request)=="function" and request or type(http_request)=="function" and http_request or (type(syn)=="table" and type(syn.request)=="function" and syn.request) or nil
    if not code or not requestFn then return end
    task.spawn(function()
        local ok,data=pcall(function()
            local response=requestFn({Url="https://discord.com/api/v10/invites/"..code.."?with_counts=true",Method="GET"})
            assert(type(response)=="table" and response.StatusCode==200 and type(response.Body)=="string","Discord unavailable")
            return HttpService:JSONDecode(response.Body)
        end)
        if not ok or type(data)~="table" or not App.alive() then return end
        local online,members=tonumber(data.approximate_presence_count),tonumber(data.approximate_member_count)
        if online and members and online>=0 and members>0 then UI.showDiscordCounts(online,members) end
    end)
end
function UI.showDiscordCounts(online,members)
    if not UI.HomeDiscordCounts then return end
    UI.HomeDiscordCounts.Visible=true
    local function write(fraction)
        UI.setText(UI.HomeOnline,UI.group(online*fraction).." online"); UI.setText(UI.HomeMembers,UI.group(members*fraction).." members")
    end
    if UI.motion()~="full" then write(1); return end
    -- The numbers count up once (a NumberValue tweened by the engine).
    local counter=Instance.new("NumberValue"); counter.Value=0
    local connection=counter.Changed:Connect(function(value) if App.alive() then write(value) end end)
    local tween=UI.TweenService:Create(counter,TweenInfo.new(0.9,Enum.EasingStyle.Quint,Enum.EasingDirection.Out),{Value=1})
    tween.Completed:Connect(function() connection:Disconnect(); write(1); counter:Destroy() end)
    tween:Play()
    UI.pulse(UI.HomeDiscordLive,{BackgroundTransparency=0.6},1.1)
end
-- Every second while Home shows: the server's numbers.
function UI.startHomeTicker()
    if UI.HomeTicking then return end
    UI.HomeTicking=true
    task.spawn(function()
        while App.alive() do
            if UI.Visible and not UI.Minimized and UI.Tab=="Home" then UI.updateHomeStats() end
            task.wait(1)
        end
    end)
end
-- Home opened: fresh numbers and players, and on a page change its cards come in one after another.
function UI.openHome(changed)
    UI.HomeExecutor=UI.HomeExecutor or UI.executorName()
    UI.layoutHome(); UI.updateHomeStats(); UI.renderHomePlayers(); UI.refreshGuide(); UI.refreshNews()
    UI.loadDiscordCounts(); UI.startHomeTicker()
    if changed or not UI.HomeShown then
        UI.HomeShown=true
        local order=0
        for _,card in ipairs({UI.HomeHero,UI.HomeServer.Root,UI.HomeSession.Root,UI.HomeDiscord,UI.HomeNews,UI.HomePlayersCard,UI.HomeGuide}) do
            if card.Visible then
                order=order+1
                local body=card:FindFirstChild("Body")
                UI.reveal(card,order,body)
            end
        end
    end
end
-- Home for the window's width: the hero's buttons beside or under it, the two stat cards side by side or stacked,
-- the Discord button beside or under its text, players in two columns or one and the guide's steps in a row or a column.
function UI.layoutHome()
    if not UI.HomeHero then return end
    -- Each block has its own width where it changes shape (the page's width, without its padding).
    local width=(UI.ContentWidth or 600)-8
    local compact=width<520
    local narrow=width<560
    -- Hero
    UI.HomeHero.Size=UDim2.new(1,0,0,compact and 172 or 118)
    local textWidth=compact and -120 or -330
    UI.HomeGreeting.Size=UDim2.new(1,textWidth,0,18); UI.HomeName.Size=UDim2.new(1,textWidth,0,28)
    UI.HomeName.TextSize=UI.size(compact and 19 or 22)
    if compact then
        UI.HomeCopy.Root.Position=UDim2.new(0,16,0,118); UI.HomeCopy.Root.Size=UDim2.new(0.55,-20,0,40)
        UI.HomeFind.Root.Position=UDim2.new(0.55,4,0,118); UI.HomeFind.Root.Size=UDim2.new(0.45,-20,0,40)
    else
        UI.HomeCopy.Root.Position=UDim2.new(1,-206,0,20); UI.HomeCopy.Root.Size=UDim2.fromOffset(186,40)
        UI.HomeFind.Root.Position=UDim2.new(1,-206,0,66); UI.HomeFind.Root.Size=UDim2.fromOffset(186,34)
    end
    -- Server and session
    local server,session=UI.HomeServer.Root,UI.HomeSession.Root
    if compact then
        UI.HomeStats.Size=UDim2.new(1,0,0,232)
        server.Position=UDim2.new(); server.Size=UDim2.new(1,0,0,112)
        session.Position=UDim2.fromOffset(0,120); session.Size=UDim2.new(1,0,0,112)
    else
        UI.HomeStats.Size=UDim2.new(1,0,0,112)
        server.Position=UDim2.new(); server.Size=UDim2.new(0.56,-5,1,0)
        session.Position=UDim2.new(0.56,5,0,0); session.Size=UDim2.new(0.44,-5,1,0)
    end
    -- Discord
    UI.HomeDiscord.Size=UDim2.new(1,0,0,compact and 140 or 96)
    UI.HomeDiscordTitle.Size=UDim2.new(1,compact and -100 or -270,0,22); UI.HomeDiscordText.Size=UDim2.new(1,compact and -100 or -270,0,16)
    UI.HomeDiscordText.TextWrapped=compact; UI.HomeDiscordText.TextTruncate=compact and Enum.TextTruncate.None or Enum.TextTruncate.AtEnd
    UI.HomeDiscordMark.Position=compact and UDim2.fromOffset(16,16) or UDim2.new(0,16,0.5,-28)
    if compact then UI.HomeInvite.Root.Position=UDim2.new(0,16,1,-52); UI.HomeInvite.Root.Size=UDim2.new(1,-32,0,40)
    else UI.HomeInvite.Root.Position=UDim2.new(1,-176,0.5,-21); UI.HomeInvite.Root.Size=UDim2.fromOffset(160,42) end
    -- What's new: the button is as wide as its words in this language; on a narrow window it shows only its arrow.
    for _,row in pairs(UI.NewsRows or {}) do
        local jump=narrow and 34 or math.clamp(math.ceil(UI.textWidth(row.JumpLabel.Text,row.JumpLabel.TextSize,row.JumpLabel))+44,80,150)
        row.Jump.Size=UDim2.fromOffset(jump,28); row.JumpLabel.Visible=not narrow
        row.Body.Size=UDim2.new(1,-(18+jump+14),0,0)
    end
    -- Players
    UI.HomeGridLayout.CellSize=compact and UDim2.new(1,0,0,62) or UDim2.new(0.5,-4,0,62)
    -- Guide: shown until hidden, first while you have not applied an avatar yet, last after that.
    local guide=Store.Settings.HomeGuide~=false
    UI.HomeGuide.Visible=guide
    local applied=App.Current~=nil and App.Current~=App.Initial
    UI.HomeGuide.LayoutOrder=applied and 6 or 2
    UI.HomeStats.LayoutOrder=applied and 2 or 3; UI.HomeDiscord.LayoutOrder=applied and 3 or 4
