    local caption=UI.text(head,tostring(#rows)..(#rows==1 and " item" or " items")..(preview.Live and "  ·  worn in this game" or ""),11,UI.C.Muted); caption.Position=UDim2.fromOffset(76,32); caption.Size=UDim2.new(1,-80,0,18)
    UI.paragraph(body,"Add puts just that item on the avatar you are wearing; Remove takes it off again. Undo goes back.",11,UI.C.Muted,false,3)
    local list=UI.new("Frame",{LayoutOrder=4,Size=UDim2.new(1,0,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1},body); UI.stack(list,6)
    local token=UI.CatalogBundleToken
    for index,item in ipairs(rows) do
        local _,sub=UI.catalogItemRow(list,index,item,item.Kind and item.Kind.Label or "Accessory",item.Name or ("ID "..tostring(item.Id)),"catalogBundle")
        task.spawn(function()
            local info=Catalog.info(item.Id)
            if not info or not App.alive() or token~=UI.CatalogBundleToken then return end
            item.Kind=item.Kind or Catalog.kind(info.AssetTypeId)
            item.Name=item.Name or (type(info.Name)=="string" and info.Name or nil)
            if sub.Parent and type(info.Name)=="string" then sub.Text=info.Name end
            UI.refreshCatalog()
        end)
    end
    if #rows==0 then UI.emptyList(list,"No catalog items","This avatar has no items that can be added.") end
    UI.refreshCatalog()
end
function UI.clearRows(key, container)
    for _,connection in ipairs(UI.Rows[key] or {}) do connection:Disconnect() end
    UI.Rows[key]={}
    for _,child in ipairs(container:GetChildren()) do if not child:IsA("UIGridStyleLayout") then child:Destroy() end end
end
function UI.rowConnect(key,event,callback)
    table.insert(UI.Rows[key],event:Connect(function(...) if App.alive() then callback(...) end end))
end
function UI.profileRow(container,profile,index,key,onRemove,ask)
    local row=UI.card(container,58); row.LayoutOrder=index
    local wide=not UI.Compact
    -- Right side: Ask skin (a script user sharing a skin), Wear (one tap), Preview, then star/remove.
    local previewWidth=wide and 104 or 40
    local askWidth=ask and (wide and 112 or 52) or 0
    local controls=60+6+previewWidth+6+38+10+(ask and askWidth+6 or 0)
    local thumb=UI.new("ImageLabel",{Position=UDim2.fromOffset(10,9),Size=UDim2.fromOffset(40,40),BackgroundColor3=UI.C.Raised,BorderSizePixel=0,Image=profile.Id and ("rbxthumb://type=AvatarHeadShot&id="..profile.Id.."&w=150&h=150") or ""},row); UI.round(thumb,12)
    local title=UI.text(row,profile.DisplayName~="" and profile.DisplayName or profile.Name,13,nil,true); title.Position=UDim2.fromOffset(60,8); title.Size=UDim2.new(1,-(60+controls),0,22)
    local sub=UI.text(row,"@"..profile.Name,11,UI.C.Muted); sub.Position=UDim2.fromOffset(60,30); sub.Size=UDim2.new(1,-(60+controls),0,20)
    local left=controls
    if ask then
        -- Wear copies their Roblox avatar; Ask skin asks for the skin they wear with the script.
        sub.Text="@"..profile.Name.."  ·  Avatar Studio"; sub.TextColor3=UI.C.Accent
        local button=UI.button(row,wide and "Ask skin" or "Ask",false,function()
            if Sync.Asked[profile.Id] then Sync.cancelAsk(profile.Id) else task.spawn(Sync.ask,profile.Id) end
        end,wide and "shirt" or nil,key)
        button.Root.Size=UDim2.fromOffset(askWidth,38); button.Root.Position=UDim2.new(1,-left,0.5,-19)
        local edge=UI.stroke(button.Root,0.2,UI.C.Accent); edge.Thickness=1
        UI.AskButtons[profile.Id]={Button=button,Wide=wide}
        left=left-askWidth-6
    end
    local wear=UI.button(row,"Wear",true,function() App.wearProfile(profile) end,nil,key)
    wear.Root.Size=UDim2.fromOffset(60,38); wear.Root.Position=UDim2.new(1,-left,0.5,-19)
    local open=UI.button(row,wide and "Preview" or "",false,function()
        UI.selectTab("Avatar"); UI.SearchBox.Text=tostring(profile.Id or profile.Name); UI.query(UI.SearchBox.Text,true)
    end,"box",key)
    open.Root.Size=UDim2.fromOffset(previewWidth,38); open.Root.Position=UDim2.new(1,-(left-66),0.5,-19)
    local remove=UI.button(row,"",false,function() if onRemove then onRemove() else UI.toggleFavorite(profile) end end,onRemove and "x" or "star",key)
    remove.Root.Size=UDim2.fromOffset(38,38); remove.Root.Position=UDim2.new(1,-48,0.5,-19)
end
