            PlaceholderText = "Description (optional): the style, the game it's for…", PlaceholderColor3 = UI.C.Muted, TextColor3 = UI.C.Text, Font = UI.Font.Regular,
            TextSize = UI.size(12), TextWrapped = true, MultiLine = true, ClearTextOnFocus = false, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top}, aboutField)
