-- The code of one skin or of several, copied to the clipboard (and shown in Share & import).
function UI.copyShareCode(code, short, count)
    UI.ExportBox.Text = code
    local clipboard = type(setclipboard) == "function" and setclipboard or type(toclipboard) == "function" and toclipboard or nil
    local copied = clipboard and pcall(clipboard, code)
    if short then
        local gets = (count or 1) > 1 and ("these " .. tostring(count) .. " skins") or "this skin"
        App.report(copied and ("Code copied: " .. code .. ". Whoever pastes it in Import gets " .. gets .. ".") or ("Your code is in Share & import below: " .. code), copied and "success" or "info")
    else
        App.report(copied and "Full code copied. Send it to whoever you want to share it with." or "Full code generated in Share & import below. Select and copy it manually.", copied and "success" or "info")
    end
end
-- Yields. Posts a saved skin to the Community.
function UI.postLook(row, about, discord)
    if UI.PostBusy then return end
    discord = Community.discord(discord)
    UI.PostBusy = true; App.report("Posting to the Community…", "loading")
    task.spawn(function()
        local ok, id, detail = pcall(Community.post, row, about, discord)
        UI.PostBusy = false
        if not App.alive() then return end
        if not ok then App.report(tostring(id), "error"); return end
        if not id then App.report(tostring(detail), "error"); return end
        Store.Settings.CommunityDiscord = discord; App.persist()
        UI.PostFor = nil; UI.CommunityStale = true; UI.renderLooks()
        App.report(detail == true and "Your post was updated." or "Posted! Everyone can find it in Saved Skins > Community.", "success")
    end)
end
-- PICKING: Select in My skins picks several skins, to share them in one code (a pack, see Looks.packPacket) or to
-- delete them together. Delete all empties the library at once. Both ask first, and Undo in the report brings the
-- deleted skins back while the script runs.
UI.LookPicked = {}
function UI.pickedCount() local count = 0; for _ in pairs(UI.LookPicked) do count = count + 1 end; return count end
function UI.setPicking(on)
    UI.LookPicking = on == true; UI.LookPicked = {}
    if on then UI.SelectedLook = nil; UI.PostFor = nil end
    UI.renderLooks()
end
function UI.pickLook(key)
    if UI.LookPicked[key] then UI.LookPicked[key] = nil else UI.LookPicked[key] = true end
    UI.renderLooks()
end
-- Every skin the search shows is picked, or none when they all are.
function UI.pickAllLooks()
    local term, shown, all = UI.LookSearch and UI.LookSearch.Text:lower() or "", {}, true
    for _, row in ipairs(Store.Looks) do
        if term == "" or row.Name:lower():find(term, 1, true) or row.Source:lower():find(term, 1, true) then
            table.insert(shown, row.Key)
            if not UI.LookPicked[row.Key] then all = false end
        end
    end
    for _, key in ipairs(shown) do UI.LookPicked[key] = (not all) or nil end
    UI.renderLooks()
end
function UI.refreshPickBar()
    if not UI.PickStart then return end
    local picking, count = UI.LookPicking == true, UI.pickedCount()
    UI.PickStart.Root.Visible = not picking; UI.PickClear.Root.Visible = not picking
    UI.PickCancel.Root.Visible = picking; UI.PickShare.Root.Visible = picking; UI.PickDelete.Root.Visible = picking; UI.PickAll.Root.Visible = picking
    UI.setText(UI.PickShare.Label, count > 0 and ("Share " .. tostring(count)) or "Share")
    UI.setText(UI.PickDelete.Label, count > 0 and ("Delete " .. tostring(count)) or "Delete")
    UI.enabled(UI.PickShare, count > 0)
    UI.enabled(UI.PickDelete, count > 0)
    UI.enabled(UI.PickClear, #Store.Looks > 0)
end
-- Removes the skins with these keys from the library, after asking. Undo in the report puts them back where they were.
function UI.deleteLooks(keys, title)
    local rows = {}
    for index, row in ipairs(Store.Looks) do if keys[row.Key] then table.insert(rows, {Row = row, Index = index}) end end
    if #rows == 0 then App.report("Tap the skins you want to delete first.", "warning"); return end
    local text = #rows == 1 and ("The skin '" .. rows[1].Row.Name .. "' will be removed from the library.")
        or (tostring(#rows) .. " skins will be removed from the library.")
    UI.confirm(title or "Delete skins?", text, function()
        for index = #Store.Looks, 1, -1 do if keys[Store.Looks[index].Key] then table.remove(Store.Looks, index) end end
        UI.LookPicking = false; UI.LookPicked = {}; UI.SelectedLook = nil; UI.renderLooks()
        local persisted = App.persist()
        if not persisted then App.report("Deletion applies to this session only; the file could not be saved.", "warning"); return end
        App.toast({Title = #rows == 1 and "Skin deleted" or (tostring(#rows) .. " skins deleted"), Kind = "success", Icon = "trash-2", Duration = 8,
            Text = "They are gone from My skins. Undo puts them back.",
            Action = {Text = "Undo", Callback = function()
                if not App.alive() then return end
                local back = 0
                for _, item in ipairs(rows) do
                    if not Looks.find(item.Row.Key) and #Store.Looks < 100 then
                        table.insert(Store.Looks, math.min(item.Index, #Store.Looks + 1), item.Row); back = back + 1
                    end
                end
                UI.renderLooks(); App.persist()
                App.report(back == #rows and "The deleted skins are back." or (tostring(back) .. " of " .. tostring(#rows) .. " skins came back (the library holds 100)."), back == #rows and "success" or "warning")
            end}})
    end, {Confirm = "Delete"})
end
function UI.deletePicked() UI.deleteLooks(UI.LookPicked) end
function UI.deleteAllLooks()
    local keys = {}
    for _, row in ipairs(Store.Looks) do keys[row.Key] = true end
    UI.deleteLooks(keys, "Delete all skins?")
end
function UI.sharePicked()
    local rows = {}
    for _, row in ipairs(Store.Looks) do if UI.LookPicked[row.Key] then table.insert(rows, row) end end
    if #rows == 0 then App.report("Tap the skins you want to share first.", "warning"); return end
    if #rows > Looks.PackMax then App.report("One code holds up to 20 skins.", "warning"); return end
    if UI.ShareBusy then return end
    UI.ShareBusy = true; App.report("Creating the share code…", "loading")
    task.spawn(function()
        local packet, name
        if #rows == 1 then packet, name = Looks.share(rows[1]):sub(7), rows[1].Name
        else packet, name = Looks.packPacket(rows), tostring(#rows) .. " skins" end
        local ok, code, reason = pcall(Share.publishPacket, packet, name)
        UI.ShareBusy = false
        if not App.alive() then return end
        if ok and code then UI.copyShareCode(code, true, #rows)
        elseif #packet > 1900000 then App.report("These skins are too big for one code. Pick fewer skins.", "error"); return
        else
            UI.copyShareCode("LYRA3:" .. packet, false, #rows)
            if not (ok and reason == "too_large") then App.report("The Lyra server could not be reached, so the full code was copied instead.", "warning") end
        end
        UI.setPicking(false)
    end)
end
function UI.renderLooks()
    if not UI.LookList then return end
    UI.clearRows("looks", UI.LookList)
    if UI.SelectedLook and not Looks.find(UI.SelectedLook) then UI.SelectedLook = nil end
    for key in pairs(UI.LookPicked) do if not Looks.find(key) then UI.LookPicked[key] = nil end end
    local term = UI.LookSearch.Text:lower(); local count = 0
    for _, row in ipairs(Store.Looks) do
        if term == "" or row.Name:lower():find(term, 1, true) or row.Source:lower():find(term, 1, true) then
            count = count + 1
            UI.lookRow(row, count)
            if row.Key == UI.SelectedLook and not UI.LookPicking then UI.lookManage(row, count) end
        end
    end
    if UI.LookPicking then UI.setText(UI.LookCount, tostring(UI.pickedCount()) .. " selected  ·  tap skins to pick them, then share or delete them")
    else UI.setText(UI.LookCount, (term ~= "" and (tostring(count) .. " found  ·  ") or "") .. tostring(#Store.Looks) .. "/100 saved  ·  tap the pencil to rename, update or share") end
    UI.refreshPickBar()
    if count == 0 then UI.emptyList(UI.LookList, term ~= "" and "No results" or "Your library is empty", term ~= "" and "Try another term." or "Build a skin in a Catalog Creator game, type a name above and tap Save.") end
end
