        Image = (row.Look or row.User) and ("rbxthumb://type=AvatarHeadShot&id=" .. string.format("%d", row.Look or row.User) .. "&w=48&h=48") or ""}, line)
    UI.round(face, 15)
    if creator then UI.creatorRing(face, 1.5) elseif staff then UI.stroke(face, 0.2, UI.C.Gold) end
    local bubble = UI.new("Frame", {Position = UDim2.fromOffset(40, 1), Size = UDim2.new(1, -41, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundColor3 = mine and UI.C.AccentDark or UI.C.Raised, BackgroundTransparency = mine and 0.45 or 0.25, BorderSizePixel = 0}, line)
    UI.round(bubble, 12)
    if creator then
        bubble.BackgroundColor3 = Color3.new(1, 1, 1); bubble.BackgroundTransparency = mine and 0.2 or 0.12
        UI.new("UIGradient", {Rotation = 20, Color = ColorSequence.new(UI.C.Raised:Lerp(UI.C.Accent, mine and 0.38 or 0.2), UI.C.Raised:Lerp(UI.C.Gold, 0.14))}, bubble)
        UI.creatorRing(bubble, 1, 0.25)
    elseif staff then
        UI.stroke(bubble, 0.35, UI.C.Gold)
    end
    UI.new("UIPadding", {PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 7)}, bubble)
    UI.new("UIListLayout", {SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2)}, bubble)
    local head = UI.strip(bubble, 5); head.LayoutOrder = 1; head.Size = UDim2.new(1, -24, 0, 20)
    local name = UI.stripText(head, "@" .. row.Name, 11, staff and UI.C.Gold or creator and UI.C.Accent or UI.C.Text, true, 1)
    name.TextTruncate = Enum.TextTruncate.AtEnd
    if staff then
        UI.smallIcon(head, "crown", 14, UI.C.Gold).LayoutOrder = 2
        UI.badgePill(head, {Text = "DEV", Icon = "badge-check", Color = "Gold"}).LayoutOrder = 3
    elseif creator then
        UI.smallIcon(head, "badge-check-solid", 14, UI.C.Accent).LayoutOrder = 2
        if not UI.Compact then UI.badgePill(head, {Text = "CREATOR", Icon = "badge-check", Color = "Accent"}).LayoutOrder = 3 end
    end
    UI.stripText(head, UI.chatAgo(row.At), 10, UI.C.Muted, false, 4)
    local text = UI.paragraph(bubble, "", 13, UI.C.Text, false, 2); text.Text = row.Text
    -- The corner button.
    local corner = UI.new("TextButton", {Position = UDim2.new(1, -27, 0, 3), Size = UDim2.fromOffset(26, 26), BackgroundColor3 = UI.C.Base, BackgroundTransparency = 1,
        Text = "", AutoButtonColor = false, ZIndex = 3}, line)
    UI.round(corner, 9)
    local glyph = UI.smallIcon(corner, mine and "trash-2" or "flag", 14, UI.C.Muted, UDim2.new(0.5, -7, 0.5, -7)); glyph.ZIndex = 4
    UI.rowConnect("chat", corner.MouseEnter, function() corner.BackgroundTransparency = 0.5; glyph.ImageColor3 = mine and UI.C.Red or UI.C.Text end)
    UI.rowConnect("chat", corner.MouseLeave, function() corner.BackgroundTransparency = 1; glyph.ImageColor3 = UI.C.Muted end)
    UI.rowConnect("chat", corner.Activated, function()
        if mine then
            UI.confirm("Delete this message?", "It leaves the chat for everyone.", function()
                task.spawn(function()
                    local done, why = Chat.remove(row.Id)
