            or {0.5,0.6,0.7,0.8,0.85,0.9,0.95,1,1.05,1.1,1.2,1.3,1.5,1.75,2}
        UI.BodyDraft[key]=UI.BodyDraft[key] or 1
        add(UI.stepper(page,field[2],field[3],key,values,function(v) return tostring(math.floor(v*100+0.5)).."%" end,UI.BodyDraft))
