-- A switch on a settings card. The whole card is its hit area (a bigger target than the switch); the knob slides over
-- with a little bounce and stretches while it is held.
function UI.toggle(parent,title,description,key,onChange,store)
    store=store or Store.Settings
    local card=UI.controlCard(parent,title,description,58)
    UI.anchor((store==Store.Auto and "auto:" or "setting:")..key,card,{Title=title,Text=description})
    local hit=UI.new("TextButton",{Name="Hit",Size=UDim2.fromScale(1,1),Text="",AutoButtonColor=false,BackgroundTransparency=1},card)
    local button=UI.new("TextButton",{Name="Switch",Position=UDim2.new(1,-60,0.5,-14),Size=UDim2.fromOffset(48,28),Text="",AutoButtonColor=false,BackgroundColor3=UI.C.Raised,BorderSizePixel=0},card)
    UI.new("UICorner",{CornerRadius=UDim.new(1,0)},button)
    local edge=UI.stroke(button,0.5)
    local knob=UI.new("Frame",{Name="Knob",Position=UDim2.fromOffset(4,4),Size=UDim2.fromOffset(20,20),BackgroundColor3=UI.C.Muted,BorderSizePixel=0},button); UI.new("UICorner",{CornerRadius=UDim.new(1,0)},knob)
    local function refresh(animate)
        local val=store[key]==true
        local quick=animate==false and 0 or nil
        UI.tween(button,{BackgroundColor3=val and UI.C.Accent or UI.C.Raised},quick or 0.22)
        UI.tween(edge,{Color=val and UI.C.Accent or UI.C.Line,Transparency=val and 0.2 or 0.5},quick or 0.22)
        UI.tween(knob,{Position=UDim2.fromOffset(val and 24 or 4,4),Size=UDim2.fromOffset(20,20),BackgroundColor3=val and UI.C.Base or UI.C.Muted},quick or 0.34,Enum.EasingStyle.Back)
    end
    local function flip() store[key]=not store[key]; refresh(); if onChange then onChange(store[key]) end; App.persist() end
    UI.connect(button.Activated,flip); UI.connect(hit.Activated,flip)
    local function held(input)
        if input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then return end
        local val=store[key]==true
        UI.tween(knob,{Size=UDim2.fromOffset(26,20),Position=UDim2.fromOffset(val and 18 or 4,4)},0.12)
    end
    local function released(input) if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then refresh() end end
    UI.connect(button.InputBegan,held); UI.connect(hit.InputBegan,held)
    UI.connect(button.InputEnded,released); UI.connect(hit.InputEnded,released)
    UI.connect(hit.MouseEnter,function() UI.tween(card,{BackgroundTransparency=0.08}) end)
    UI.connect(hit.MouseLeave,function() UI.tween(card,{BackgroundTransparency=0.22}) end)
    UI.Toggles=UI.Toggles or {}; UI.Toggles[(store==Store.Auto and "Auto." or "")..key]=refresh
    refresh(false); return card
end
-- Live status of every way to bring the hidden window back, so a player can see what works on this device.
function UI.reopenCard(parent)
    local card=UI.autoCard(parent,0,6,14)
    UI.ReopenRows={}
    for index=1,4 do
        local row=UI.new("Frame",{LayoutOrder=index,Size=UDim2.new(1,0,0,22),BackgroundTransparency=1},card)
        local name=UI.text(row,"",12,UI.C.Text,true); name.Size=UDim2.new(0.58,0,1,0)
        local state=UI.text(row,"",12,UI.C.Muted,true); state.Position=UDim2.new(0.58,0,0,0); state.Size=UDim2.new(0.42,0,1,0); state.TextXAlignment=Enum.TextXAlignment.Right
        UI.ReopenRows[index]={Name=name,State=state}
    end
    UI.ReopenWarning=UI.paragraph(card,"",11,UI.C.Gold,true,10)
    return card
end
function UI.refreshReopenCard()
    if not UI.ReopenRows then return end
    local orb,menu,keyboard=Store.Settings.MobileOrb==true,Store.Settings.MenuReopen==true,UIS.KeyboardEnabled
    local chat=UI.ChatOK==false and {"Blocked on this account",UI.C.Gold} or UI.ChatOK==true and {"Ready",UI.C.Green} or UI.ChatChecked and {"Not detected",UI.C.Muted} or {"Checking…",UI.C.Muted}
    local rows={
        {"Floating button",orb and "On" or "Off",orb and UI.C.Green or UI.C.Muted},
        {"Roblox menu shortcut",menu and "On" or "Off",menu and UI.C.Green or UI.C.Muted},
        {"Shortcut key ("..Store.Settings.Keybind..")",keyboard and "Ready" or "No keyboard",keyboard and UI.C.Green or UI.C.Gold},
        {"Chat  /e copier",chat[1],chat[2]},
    }
    for index,row in ipairs(rows) do
        local entry=UI.ReopenRows[index]
        entry.Name.Text=row[1]; entry.State.Text=row[2]; entry.State.TextColor3=row[3]
    end
    UI.setText(UI.ReopenWarning,UI.canReopen() and "" or "Nothing can reopen the window right now. Turn on the floating button or the Roblox menu shortcut.")
    UI.ReopenWarning.Visible=not UI.canReopen()
end
-- A group of options that stays folded until opened (progressive disclosure), so a page starts short.
function UI.collapsible(parent)
    local holder=UI.new("Frame",{Size=UDim2.new(1,0,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1},parent)
    UI.stack(holder,6)
    local body=UI.new("Frame",{LayoutOrder=2,Size=UDim2.new(1,0,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1,Visible=false},holder)
    UI.stack(body,6)
    local head
    local function setOpen(open)
        body.Visible=open
        UI.setText(head.Label,open and "Hide advanced options" or "Show advanced options")
        if head.Icon then UI.tween(head.Icon,{Rotation=open and 180 or 0},0.3,Enum.EasingStyle.Back) end
        UI.setSelected(head,open)
    end
    head=UI.button(holder,"Show advanced options",false,function() setOpen(not body.Visible) end,"chevron-down")
    head.Root.LayoutOrder=1
    -- The spotlight unfolds it to show a setting inside (see SPOTLIGHT).
    UI.Folds[body]=setOpen
    return holder,body
end
function UI.buildSettings()
