    font.Root.Size=UDim2.fromOffset(170,40); font.Root.Position=UDim2.new(1,-182,0.5,-20); font.MinWidth=200; font.refresh()
    add(UI.stepper(page,"Text size","Makes every text in this window smaller or larger.","TextSize",{80,85,90,95,100,105,110,115,120,125,130},
        function(value) return tostring(value).."%" end,Store.Settings,function(value) UI.setTextSize(value) end))
    add(UI.section(page,"Avatar"))
