    add(UI.toggle(page,"Keep avatar after respawn","Puts your avatar back on when you respawn.","AutoReapply"))
    add(UI.toggle(page,"Hide my avatar until the copy is on","After a respawn, a teleport or Auto-load, your own avatar stays hidden on your screen until the copied one is on, so it never shows for a moment.","HideOriginal",function(on) if not on then Cover.finish() end end))
    local changeCard=add(UI.controlCard(page,"When the game changes your avatar","Catalog games and morphs change your avatar themselves. Take the copied one off so the looks don't mix, put it back on, or do nothing.",170))
    local change=UI.dropdown(changeCard,{{Value="Yield",Label="Take it off"},{Value="Keep",Label="Put it back on"},{Value="Ignore",Label="Do nothing"}},
