    local cancel=UI.button(card,"Cancel",false,function() UI.ModalToken=(UI.ModalToken or 0)+1; UI.ModalAction=nil; UI.hideModal() end); cancel.Root.Name="Cancel"; cancel.Root.Position=UDim2.new(0,16,1,-60); cancel.Root.Size=UDim2.new(0.5,-22,0,44)
    local confirm=UI.button(card,"Confirm",true,function() UI.ModalToken=(UI.ModalToken or 0)+1; local fn=UI.ModalAction; UI.ModalAction=nil; UI.hideModal(); if fn then fn() end end); confirm.Root.Name="Confirm"; confirm.Root.Position=UDim2.new(0.5,6,1,-60); confirm.Root.Size=UDim2.new(0.5,-22,0,44)
    UI.ModalCancel=cancel; UI.ModalConfirm=confirm
