function UI.showModal()
    UI.ModalSerial=(UI.ModalSerial or 0)+1
    UI.closeDropdown(true)
    if UI.FindOpen then UI.closeFind(true) end
    local fresh=not UI.Modal.Visible
    UI.Modal.Visible=true
    if fresh and UI.motion()~="off" then
        UI.Modal.BackgroundTransparency=1; UI.tween(UI.Modal,{BackgroundTransparency=0.35},0.2)
        UI.ModalScale.Scale=0.9; UI.tween(UI.ModalScale,{Scale=1},0.36,Enum.EasingStyle.Back)
    else UI.Modal.BackgroundTransparency=0.35; UI.ModalScale.Scale=1 end
end
function UI.hideModal()
    UI.ModalSerial=(UI.ModalSerial or 0)+1; local serial=UI.ModalSerial
    if UI.motion()=="off" then UI.Modal.Visible=false; return end
    UI.tween(UI.Modal,{BackgroundTransparency=1},0.16); UI.tween(UI.ModalScale,{Scale=0.94},0.16)
    task.delay(0.17,function() if serial==UI.ModalSerial and UI.Modal then UI.Modal.Visible=false end end)
end
-- options: Confirm and Cancel set the button labels; Seconds closes the question as a Cancel after that
-- long if nobody answers, counting down on the Cancel button.
function UI.confirm(title,description,action,options)
    options=options or {}
    UI.ModalToken=(UI.ModalToken or 0)+1; local token=UI.ModalToken
    UI.setText(UI.ModalTitle,title); UI.setText(UI.ModalText,description); UI.ModalAction=action; UI.showModal()
    local cancelText=Lang.text(options.Cancel or "Cancel")
    UI.setText(UI.ModalConfirm.Label,options.Confirm or "Confirm"); UI.setText(UI.ModalCancel.Label,options.Cancel or "Cancel")
    if not options.Seconds then return end
    task.spawn(function()
        for left=options.Seconds,1,-1 do
            if not App.alive() or token~=UI.ModalToken then return end
            UI.ModalCancel.Label.Text=cancelText.." ("..tostring(left)..")"
            task.wait(1)
        end
        if App.alive() and token==UI.ModalToken then UI.ModalToken=token+1; UI.hideModal(); UI.ModalAction=nil; UI.setText(UI.ModalCancel.Label,options.Cancel or "Cancel") end
    end)
end
function UI.toggleFavorite(profile)
    if not profile then return end
    if App.favoriteIndex(profile) then
        UI.confirm("Remove favorite?",profile.Name.." will be removed from your favorites.",function() App.toggleFavorite(profile) end)
    else App.toggleFavorite(profile) end
end
function UI.timelineThumb(frame,snapshot)
    if snapshot.Original then
        UI.new("ImageLabel",{Size=UDim2.fromScale(1,1),BackgroundTransparency=1,BorderSizePixel=0,Image="rbxthumb://type=AvatarHeadShot&id="..tostring(lp.UserId).."&w=150&h=150"},frame)
    elseif snapshot.Change then
        UI.new("ImageLabel",{Size=UDim2.fromScale(1,1),BackgroundTransparency=1,BorderSizePixel=0,ScaleType=Enum.ScaleType.Fit,Image=UI.catalogThumb({Id=snapshot.Change.Id,Bundle=snapshot.Change.Bundle})},frame)
    elseif snapshot.LookKey and Looks.find(snapshot.LookKey) then UI.lookThumb(frame,snapshot.LookKey)
    elseif snapshot.Id or snapshot.ThumbId then
        UI.new("ImageLabel",{Size=UDim2.fromScale(1,1),BackgroundTransparency=1,BorderSizePixel=0,Image="rbxthumb://type=AvatarHeadShot&id="..tostring(snapshot.Id or snapshot.ThumbId).."&w=150&h=150"},frame)
    else UI.icon(frame,"user",UDim2.new(0.5,-12,0.5,-12),UI.C.AccentDark) end
end
function UI.renderTimeline()
    if not UI.TimelineStrip then return end
    local items=table.clone(App.History)
    if App.Current then table.insert(items,App.Current) end
    -- Rebuild only when the history or the busy state changed.
    local signature={tostring(App.Busy)}
    for _,snapshot in ipairs(items) do table.insert(signature,tostring(snapshot)) end
    signature=table.concat(signature,"|")
    if signature==UI.TimelineSignature then return end
    UI.TimelineSignature=signature
    UI.clearRows("timeline",UI.TimelineStrip)
    if #items==0 then
        local empty=UI.text(UI.TimelineStrip,"Avatars you wear appear here.",11,UI.C.Muted); empty.Size=UDim2.new(1,0,1,0)
        return
    end
    for index,snapshot in ipairs(items) do
        local current=snapshot==App.Current
        local tile=UI.new("TextButton",{LayoutOrder=index,Size=UDim2.fromOffset(58,64),BackgroundTransparency=1,Text="",AutoButtonColor=false,BorderSizePixel=0},UI.TimelineStrip)
        local frame=UI.new("Frame",{Position=UDim2.fromOffset(7,0),Size=UDim2.fromOffset(44,44),BackgroundColor3=UI.C.Raised,BorderSizePixel=0,ClipsDescendants=true},tile); UI.round(frame,12)
        UI.stroke(frame,current and 0 or 0.6,current and UI.C.Accent or UI.C.Line).Thickness=current and 2 or 1
        UI.timelineThumb(frame,snapshot)
        local name=snapshot.Original and "Original" or tostring(snapshot.Name or "Avatar")
        local label=UI.text(tile,current and "Now" or name,10,current and UI.C.Accent or UI.C.Muted,current)
        label.Position=UDim2.fromOffset(0,46); label.Size=UDim2.new(1,0,0,18); label.TextXAlignment=Enum.TextXAlignment.Center
        if not current then
            UI.rowConnect("timeline",tile.Activated,function() if not App.Busy then App.jump(snapshot) end end)
            UI.rowConnect("timeline",tile.MouseEnter,function() UI.tween(frame,{BackgroundColor3=UI.C.AccentDark}) end)
            UI.rowConnect("timeline",tile.MouseLeave,function() UI.tween(frame,{BackgroundColor3=UI.C.Raised}) end)
        end
        if App.Busy and not current then tile.Active=false; label.TextTransparency=0.5 end
    end
    -- Keep the newest (current) appearance in view.
    task.defer(function()
        if App.alive() and UI.TimelineStrip then
            UI.TimelineStrip.CanvasPosition=Vector2.new(math.max(0,UI.TimelineStrip.AbsoluteCanvasSize.X-UI.TimelineStrip.AbsoluteWindowSize.X),0)
        end
    end)
end
function UI.refresh()
    if not UI.Apply then return end
    UI.enabled(UI.Apply,App.Preview~=nil and not App.Busy)
    if UI.PickItems then UI.enabled(UI.PickItems,App.Preview~=nil and App.Preview.Description~=nil) end
    if UI.LiveLook then
        local live=App.LiveLook and App.Preview and (App.Preview.Profile or App.Preview).Id==App.LiveLook.Id
        UI.LiveLook.Root.Visible=live==true
        UI.setText(UI.LiveLook.Label,App.Preview and App.Preview.Live and "See profile avatar" or "See in-game look")
    end
    UI.enabled(UI.Favorite,App.Preview~=nil and App.Preview.Id~=nil)
    UI.enabled(UI.Undo,#App.History>0 and not App.Busy)
    UI.enabled(UI.Restore,App.Initial~=nil and (App.Dirty or App.Current~=App.Initial) and not App.Busy)
    UI.enabled(UI.Customize,(App.Current~=nil or App.Initial~=nil) and not App.Busy)
    UI.setText(UI.Apply.Label,App.Busy and "Applying…" or "Apply avatar")
    UI.setText(UI.Favorite.Label,UI.favoriteText())
    UI.setText(UI.HistoryText,#App.History>0 and (tostring(#App.History)..(#App.History==1 and " earlier look · tap to go back" or " earlier looks · tap to go back")) or "No changes yet")
    UI.renderTimeline()
    if UI.Tab=="Looks" and UI.LooksCurrent~=App.Current then UI.LooksCurrent=App.Current; UI.renderLooks() end
    if UI.Tab=="Collection" then UI.renderCollection() end
    if UI.Tab=="Catalog" then UI.refreshCatalog() end
    if UI.Tab=="Customize" and UI.CustomizeFor~=App.Current then UI.renderCustomize() end
    if UI.GuideSteps then UI.refreshGuide() end
    if UI.HomeGuide and UI.HomeApplied~=(App.Current~=nil and App.Current~=App.Initial) then UI.HomeApplied=App.Current~=nil and App.Current~=App.Initial; UI.layoutHome() end
end
-- Reopen by opening and closing the Roblox menu 3 times within 5 seconds. It needs no chat and no on-screen
-- control: only a hidden window reacts, and the window coming back is the only visible sign. This is the
-- one reopen method that explains itself with a notice, so a player who did it by accident learns how to
-- turn it off; chat, the shortcut key and the floating button show nothing.
-- ROBLOX MENU AVATAR: the Players page of the Roblox menu shows a picture of every player. On your screen only,
-- yours becomes the avatar you are wearing: the copied profile's own Roblox picture (with its pose or emote) when
-- the avatar is that profile as it is, else a 3D view of it posed like Roblox's pictures. Nothing is sent to anyone.
-- Everything is wrapped in pcall: if the menu changes, it just does nothing.
UI.MenuAvatarSerial=0
-- Where a full-body picture is seen from: in front of the avatar, turned slightly as Roblox's own pictures are.
UI.PictureTurn=CFrame.Angles(0,math.rad(-15),0)*Vector3.new(0,0,-1)
-- That direction for a posed model: in front of its root, as Roblox frames its pictures. A body turned well away from
-- its root (more than 45 degrees, which no standing pose does) is seen from its own front instead, so a picture never
-- shows an avatar from the side or the back. straight: looked at head-on (head pictures), not turned.
function UI.pictureDirection(model,straight)
    local function flat(name)
        local part=model:FindFirstChild(name)
        if not (part and part:IsA("BasePart")) then return nil end
        local look=part.CFrame.LookVector*Vector3.new(1,0,1)
        return look.Magnitude>0.2 and look.Unit or nil
    end
    local front=flat("HumanoidRootPart") or Vector3.new(0,0,-1)
    local body=flat("UpperTorso") or flat("Torso")
    if body and front:Dot(body)<math.cos(math.rad(45)) then front=body end
    return CFrame.lookAt(Vector3.zero,front):VectorToWorldSpace(straight and Vector3.new(0,0,-1) or UI.PictureTurn)
end
-- Yields. An appearance posed for a picture: the pose saved with the skin (see SAVED POSE), else posed like Roblox's
-- own pictures (see POSE). A kept pose was made on its own rig, so the picture is built on that rig. note(text) hears
-- what happened to a kept pose.
function UI.posedModel(snapshot,rig,note)
    local kept=Visual.picturePose(snapshot)
    rig=kept and Enum.HumanoidRigType[kept.RigType] or rig or Enum.HumanoidRigType.R15
    -- The model already built for your character (this look on this rig) is copied instead of built again, so the
    -- picture is ready at once.
    local made
    local cache=App.ModelCache
    if cache and cache.Snapshot==snapshot and cache.Rig==rig then pcall(function() made=cache.Model:Clone() end) end
    if not made then
        local desc=Codec.decode(snapshot.Data)
        local built,model=pcall(Visual.model,snapshot.Data,desc,rig); desc:Destroy()
        assert(built and model,tostring(model))
        made=model
    end
    UI.preparePreview(made,UI.ThumbWorld)
    local posed,custom=pcall(Visual.applyPose,made,kept)
    if kept and note then note((posed and custom) and ("kept pose on "..kept.RigType) or ("kept pose not applied ("..tostring(posed and "rig "..tostring(F.getTrueRigType(made)) or custom)..")")) end
    if not (posed and custom) then pcall(Pose.apply,made) end
    -- The gear the avatar holds and its background (see HELD ITEM AND BACKGROUND).
    local data=type(snapshot.Data)=="table" and snapshot.Data or {}
    if Codec.id(data.Gear) then pcall(UI.holdGear,made,Codec.id(data.Gear)) end
    if Codec.id(data.Background) then made:SetAttribute("LyraBackground",Codec.id(data.Background)) end
    for _,item in ipairs(made:GetDescendants()) do
        pcall(function() item.Archivable=true end)
        if item:IsA("SurfaceAppearance") then
            local part=item.Parent
            pcall(function() if part:IsA("MeshPart") and part.TextureID=="" and item.ColorMap~="" then part.TextureID=item.ColorMap end end)
            item:Destroy()
        end
    end
    made.Archivable=true
    return made
end
function UI.menuAvatarModel()
    local snapshot=App.Current
    if not snapshot or snapshot.Original then return nil end
    if UI.MenuAvatar and UI.MenuAvatar.Snapshot==snapshot then return UI.MenuAvatar.Model,UI.MenuAvatar.Serial end
    local ok,model=pcall(UI.posedModel,snapshot,F.getTrueRigType(lp.Character),function(text) App.devNote("Menu picture: "..text) end)
    if not ok or not model then return nil end
    if UI.MenuAvatar then pcall(function() UI.MenuAvatar.Model:Destroy() end) end
    UI.MenuAvatarSerial=UI.MenuAvatarSerial+1
    UI.MenuAvatar={Snapshot=snapshot,Model=model,Serial=UI.MenuAvatarSerial}
    return model,UI.MenuAvatarSerial
end
function UI.menuAvatarView(label,model,serial)
    local view=Instance.new("ViewportFrame")
    view.Name="LyraMenuAvatar"; view.Size=UDim2.fromScale(1,1); view.BackgroundTransparency=1; view.BorderSizePixel=0
    view.ZIndex=label.ZIndex+1; view.Ambient=Color3.fromRGB(195,186,213); view.LightColor=Color3.fromRGB(255,244,233); view.LightDirection=Vector3.new(-1,-1,-1)
    view:SetAttribute("Serial",serial)
    local clone=model:Clone(); clone.Parent=view
    -- Full body, framed like the other players' pictures: fit the whole body (height and width) in the card.
    local focus,box=Pose.bounds(clone)
    local card=label.AbsoluteSize
    local aspect=card.X>0 and card.Y>0 and math.clamp(card.X/card.Y,0.5,2) or 1
    local fov=30
    local fit=math.max(box.Y,box.X/aspect)
    local distance=(fit*0.5/math.tan(math.rad(fov/2))+box.Z*0.5)*1.12
    local camera=Instance.new("Camera"); camera.FieldOfView=fov
    -- Turned slightly, as Roblox's own full-body pictures are (see Thumbs.view).
    camera.CFrame=CFrame.lookAt(focus+Vector3.new(0,box.Y*0.04,0)+UI.pictureDirection(clone)*distance,focus); camera.Parent=view; view.CurrentCamera=camera
    local corner=label:FindFirstChildOfClass("UICorner"); if corner then corner:Clone().Parent=view end
    label.ImageTransparency=1
    -- An avatar with a background (see HELD ITEM AND BACKGROUND): the background fills the card's whole picture square
    -- (Roblox pads the picture inside it), never the name below it. It goes in Roblox's square, behind Roblox's
    -- picture, so the picture itself holds exactly what it holds without one; where that can't be done, the picture
    -- holds both, the background drawn behind the avatar.
    local background=model:GetAttribute("LyraBackground")
    if background then
        local placed,inSquare=pcall(UI.squareBackground,label,view,background)
        if not (placed and inSquare) then
            local holder=Instance.new("Frame"); holder.Name="LyraMenuAvatar"; holder.Size=UDim2.fromScale(1,1); holder.BackgroundTransparency=1
            holder.BorderSizePixel=0; holder.ZIndex=label.ZIndex+1; holder:SetAttribute("Serial",serial)
            view.Name="View"; view.ZIndex=2; view.Parent=holder
            pcall(UI.menuBackground,label,holder,background)
            holder.Parent=label
            if Debug.enabled() then task.delay(1,function() pcall(Debug.noteCard,label,"in the picture ("..tostring(inSquare)..")") end) end
            return
        end
    end
    view.Parent=label
    if Debug.enabled() then task.delay(1,function() pcall(Debug.noteCard,label,background and "in Roblox's square" or "none") end) end
end
-- The square a menu card's picture sits in: the largest frame around the picture that holds no text beside it (the
-- name and @username are under it) and is about as tall as it is wide. The picture itself when there is none. Text
-- level with the picture is not the name: the icons of the buttons on another player's picture (its "..." menu) are
-- text too, and counting them stopped the search at the padded frame inside the square, so the background of a
-- script user's synced skin only covered the picture.
function UI.pictureSquare(label)
    local best,cursor=label,label.Parent
    local low,high=label.AbsolutePosition,label.AbsolutePosition+label.AbsoluteSize
--[==[YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU]==]
    for _=1,4 do
        if not (cursor and cursor:IsA("GuiObject")) then break end
        local text=false
        for _,item in ipairs(cursor:GetDescendants()) do
            if (item:IsA("TextLabel") or item:IsA("TextButton")) and item.Visible and item.Text~="" then
                -- Under the picture or above it (a grid card's name), not level with it (icons on its edge).
                local from,to=item.AbsolutePosition.Y,item.AbsolutePosition.Y+item.AbsoluteSize.Y
                if from>=high.Y-1 or to<=low.Y+1 then text=true; break end
            end
        end
        if text then break end
        local size,current=cursor.AbsoluteSize,best.AbsoluteSize
        if size.X>=current.X-1 and size.Y>=current.Y-1 and size.Y<=size.X*1.4 then best=cursor end
        cursor=cursor.Parent
    end
    return best
end
-- The rounding of a menu card's picture square: the radius of the nearest UICorner from the square up, as a length
-- on the square (one given as a share of a larger frame's size is converted), else the Players page cards' 8.
function UI.squareRadius(square)
    local corner,owner,cursor=nil,nil,square
    for _=1,8 do
        if not (cursor and cursor:IsA("GuiObject")) then break end
        corner=cursor:FindFirstChildOfClass("UICorner")
        if corner then owner=cursor; break end
        cursor=cursor.Parent
    end
    local radius=corner and corner.CornerRadius or UDim.new(0,8)
    if radius.Scale>0 then
        local mine,theirs=square.AbsoluteSize,owner.AbsoluteSize
        local short=math.max(1,math.min(mine.X,mine.Y))
        radius=UDim.new(radius.Scale*math.min(theirs.X,theirs.Y)/short,radius.Offset)
    end
    return radius
end
-- Puts an avatar background in Roblox's picture square itself (the Players card's CardThumbnail), behind Roblox's
-- picture (the branch of the square holding it), covering the whole square (its padding too) with the square's rounded
-- corners. Nothing is added to Roblox's picture but the 3D view, as without a background, and nothing reaches past the
-- square: Roblox sizes the card to what it holds, and a background reaching past the picture made the card taller
-- (201 to 254 px), which pushed its rounded bottom out of view. It stays as long as that view: it goes when the view
-- goes. Returns false, adding nothing, when the square can't take it: the square is the picture, it lays out its
-- children, or the menu orders its layers globally. (The menu styles its frames, so a frame's own transparency reads
-- as the unstyled default and is not checked.)
function UI.squareBackground(label,view,id)
    local square=UI.pictureSquare(label)
    if square==label or square:FindFirstChildWhichIsA("UIGridStyleLayout") then return false end
    local layer=label:FindFirstAncestorWhichIsA("ScreenGui")
    if layer and layer.ZIndexBehavior==Enum.ZIndexBehavior.Global then return false end
    local branch=label
    while branch.Parent~=square do
        branch=branch.Parent
        if not branch then return false end
    end
    if not branch:IsA("GuiObject") then return false end
    for _,old in ipairs(square:GetChildren()) do if old.Name=="LyraMenuBackground" then old:Destroy() end end
    local image=UI.backgroundImage(nil,id); image.Name="LyraMenuBackground"; image.ZIndex=branch.ZIndex-1
    local function fit()
        local pad=square:FindFirstChildOfClass("UIPadding")
        local size=square.AbsoluteSize
        local l,r,t,b=0,0,0,0
        if pad then
            l=pad.PaddingLeft.Scale*size.X+pad.PaddingLeft.Offset; r=pad.PaddingRight.Scale*size.X+pad.PaddingRight.Offset
            t=pad.PaddingTop.Scale*size.Y+pad.PaddingTop.Offset; b=pad.PaddingBottom.Scale*size.Y+pad.PaddingBottom.Offset
        end
        image.Position=UDim2.fromOffset(-l,-t); image.Size=UDim2.new(1,l+r,1,t+b)
    end
    local shaped=pcall(function()
        fit()
        local round=Instance.new("UICorner"); round.CornerRadius=UI.squareRadius(square); round.Parent=image
    end)
    if not shaped then image:Destroy(); return false end
    image.Parent=square
    local resized=square:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() pcall(fit) end)
    local function drop()
        resized:Disconnect()
        if image.Parent then pcall(function() image:Destroy() end) end
    end
    view.Destroying:Connect(drop)
    view.AncestryChanged:Connect(function() if not view.Parent then drop() end end)
    return true
end
-- The background inside the picture (see UI.menuAvatarView), where the square can't take it: behind the avatar in its
-- holder, within the picture only (anything reaching past it can make Roblox's card grow), with Roblox's rounded
-- corners on all four sides.
function UI.menuBackground(label,holder,id)
    local image=UI.backgroundImage(holder,id); image.ZIndex=1
    local round=Instance.new("UICorner"); round.CornerRadius=UI.squareRadius(UI.pictureSquare(label)); round.Parent=image
end
-- An avatar background's picture, filling its parent (cropped to its shape).
function UI.backgroundImage(parent,id)
    local image=Instance.new("ImageLabel")
    image.Name="LyraBackground"; image.Size=UDim2.fromScale(1,1); image.BackgroundTransparency=1; image.BorderSizePixel=0
    image.ScaleType=Enum.ScaleType.Crop; image.Image=string.format("rbxthumb://type=Asset&id=%d&w=420&h=420",id)
    image.Parent=parent
    return image
end
-- HELD ITEM: the gear's look, without its scripts, sounds or joints, kept once per gear: a Model of copies of its
-- visible parts with the handle as PrimaryPart, and the tool's Grip. Hitboxes (invisible or huge parts) are left out,
-- so they never stretch the picture's framing. Yields; false when the gear can't be loaded.
-- A gear's particle effects (ParticleEmitter, Fire, Smoke, Sparkles) are not in the picture: Roblox draws no
-- particles in a 3D view inside a window (ViewportFrame), so they could only be imitated, never shown as they are.
UI.GearModels={}
function UI.gearModel(id)
    local cached=UI.GearModels[id]
    if cached~=nil then return cached end
    cached=false
    pcall(function()
        local tool
        for _,root in ipairs(game:GetObjects("rbxassetid://"..tostring(id)) or {}) do
            tool=root:IsA("Tool") and root or root:FindFirstChildWhichIsA("Tool",true)
            if tool then break end
        end
        local handle=tool and tool:FindFirstChild("Handle")
        if not (handle and handle:IsA("BasePart")) then return end
        local model=Instance.new("Model"); model.Name="LyraGear"
        -- Where each part sits: through the tool's own joints from the handle when they reach it (a gear's stored
        -- places can be stale, its welds say how it is held together), else where it is stored.
        local placed,links={[handle]=handle.CFrame},{}
        for _,joint in ipairs(tool:GetDescendants()) do
            if joint:IsA("JointInstance") and joint.Part0 and joint.Part1 and joint.Part0:IsDescendantOf(tool) and joint.Part1:IsDescendantOf(tool) then
                table.insert(links,{joint.Part0,joint.Part1,joint.C0,joint.C1})
            end
        end
        for _=1,#links+1 do
            local changed=false
            for _,link in ipairs(links) do
                local a,b,c0,c1=link[1],link[2],link[3],link[4]
                if placed[a] and not placed[b] then placed[b]=placed[a]*c0*c1:Inverse(); changed=true
                elseif placed[b] and not placed[a] then placed[a]=placed[b]*c1*c0:Inverse(); changed=true end
            end
            if not changed then break end
        end
        for _,part in ipairs(tool:GetDescendants()) do
            if part:IsA("BasePart") and (part==handle or (part.Transparency<1 and part.Size.Magnitude<=40)) then
                local copy=Overlay.carryCopy(part)
                if copy then
                    copy.Name=part==handle and "Handle" or part.Name; copy.CFrame=placed[part] or part.CFrame; copy.Parent=model
                    if part==handle then model.PrimaryPart=copy end
                end
            end
        end
        if model.PrimaryPart then cached={Model=model,Grip=tool.Grip} end
    end)
    UI.GearModels[id]=cached
    return cached
end
-- Roblox's tool hold: while a tool is out, Roblox's Animate script plays its "toolnone" animation over the idle (the
-- right arm forward). The same animation poses the picture.
UI.ToolNone={R15="rbxassetid://507768375",R6="rbxassetid://182393478"}
-- Yields. Poses a picture model's arm as Roblox holds a tool: every joint keeps the pose it has (the idle) and the
-- joints the tool animation moves take its offsets, as its higher priority does in game. Should the animation not
-- load, the right shoulder turns forward a quarter turn, as Roblox's classic R6 tool hold did. The parts are placed
-- from the joints (see Pose.set), so nothing but the arm and what hangs from it moves. Returns how it was posed.
function UI.toolPose(model,r6)
    local map={}
    for _,joint in ipairs(model:GetDescendants()) do
        if joint:IsA("Motor6D") or joint:IsA("AnimationConstraint") then
            local ok,_,part1=pcall(Overlay.jointInfo,joint)
            local read,offset=pcall(function() return joint.Transform end)
            if ok and part1 and read then map[part1.Name]=offset end
        end
    end
    local frames=Pose.frames(r6 and UI.ToolNone.R6 or UI.ToolNone.R15)
    local tool=frames and frames[1]
    local how="Roblox's tool animation"
    if tool and next(tool) then
        for name,offset in pairs(tool) do map[name]=offset end
    else
        how="a quarter turn of the shoulder (the tool animation did not load)"
        if r6 then map["Right Arm"]=CFrame.Angles(0,0,math.rad(90)) else map.RightUpperArm=CFrame.Angles(math.rad(90),0,0) end
    end
    Pose.set(model,map)
    return how
end
-- Puts the gear in a posed picture model's right hand, held as Roblox holds a tool (see UI.toolPose).
function UI.holdGear(model,id)
    local gear=UI.gearModel(id)
    if not gear then return false end
    local r6=F.getTrueRigType(model)==Enum.HumanoidRigType.R6
    local posed,how=pcall(UI.toolPose,model,r6)
    App.devNote("Menu picture gear: "..(posed and ("arm posed by "..tostring(how)) or ("arm left as posed ("..tostring(how)..")")))
    local hand=model:FindFirstChild(r6 and "Right Arm" or "RightHand")
    if not (hand and hand:IsA("BasePart")) then return false end
    -- Roblox holds an R6 tool with a grip of its own (the R6 grip attachment carries no turn); R15 uses the hand's.
    local attachment=not r6 and hand:FindFirstChild("RightGripAttachment")
    local grip=(attachment and attachment:IsA("Attachment")) and attachment.CFrame or CFrame.new(0,-1,0,1,0,0,0,0,1,0,-1,0)
    local copy=gear.Model:Clone()
    local shift=(hand.CFrame*grip*gear.Grip:Inverse())*copy.PrimaryPart.CFrame:Inverse()
    for _,part in ipairs(copy:GetDescendants()) do
        if part:IsA("BasePart") then part.CFrame=shift*part.CFrame; part.Anchored=true end
    end
    copy.Parent=model
    return true
end
-- ROBLOX INSPECT MENU: Roblox's own avatar panel (tap yourself in the Players tab, or the button in Customize) lists
-- the items of the avatar you are wearing. It goes through Roblox's API for this (InspectPlayerFromHumanoidDescription),
-- so the panel stays Roblox's; on your screen its items then read as owned (see YOUR PANEL, OWNED). Your own avatar
-- keeps Roblox's normal panel.
-- Asset ids of a saved appearance: body parts, clothing, animations, accessories, makeup and emotes.
function UI.inspectIds(data)
    local ids={}
    if type(data)~="table" then return ids end
    local props=data.Version==2 and data.Properties or data
    if type(props)=="table" then
        for _,field in ipairs(Codec.assetFields) do local id=Codec.id(props[field]); if id then ids[id]=true end end
        for _,field in ipairs(Codec.accessoryFields) do
            if type(props[field])=="string" then for id in props[field]:gmatch("%d+") do local n=Codec.id(tonumber(id)); if n then ids[n]=true end end end
        end
    end
    for _,list in ipairs({data.Accessories,data.Makeup}) do
        if type(list)=="table" then for _,row in ipairs(list) do if type(row)=="table" and Codec.id(row.AssetId) then ids[row.AssetId]=true end end end
    end
    if type(data.Emotes)=="table" then
        for _,list in pairs(data.Emotes) do if type(list)=="table" then for _,id in ipairs(list) do if Codec.id(id) then ids[id]=true end end end end
    end
    return ids
end
-- Simpler versions of the avatar, for when Roblox's panel keeps showing your own items: level 2 leaves out makeup,
-- emotes, animations and item fitting; level 3 also sends the accessories as Roblox's classic item lists, which
-- leaves out layered clothing.
function UI.inspectData(data,level)
    if level<=1 then return data end
    local copy=Codec.copy(data)
    copy.Makeup=nil; copy.Emotes=nil; copy.EquippedEmotes=nil; copy.Visual=nil
    local props=copy.Version==2 and copy.Properties or copy
    for _,field in ipairs(Codec.assetFields) do if field:find("Animation",1,true) then props[field]=0 end end
    if type(copy.Accessories)=="table" then
        for _,row in ipairs(copy.Accessories) do
            if type(row)=="table" then row.Position=nil; row.Rotation=nil; row.Scale=nil; row.Puffiness=nil end
        end
    end
    if level>=3 then
        local fields={Hat="HatAccessory",Hair="HairAccessory",Face="FaceAccessory",Neck="NeckAccessory",Shoulder="ShouldersAccessory",
            Front="FrontAccessory",Back="BackAccessory",Waist="WaistAccessory"}
        local lists={}
        for _,row in ipairs(type(copy.Accessories)=="table" and copy.Accessories or {}) do
            local field=type(row)=="table" and not row.IsLayered and fields[row.AccessoryType]
            if field and Codec.id(row.AssetId) then lists[field]=lists[field] or {}; table.insert(lists[field],string.format("%d",row.AssetId)) end
        end
        for field,ids in pairs(lists) do props[field]=table.concat(ids,",") end
        copy.HasAccessories=false; copy.Accessories=nil
    end
    return copy
end
-- Attempts in order: the full avatar, the same again (the panel may still have been loading your profile), then the
-- two simpler versions.
UI.InspectLevels={1,1,2,3}
-- who: the user id of a script user sharing a skin through Skin sync, to open the panel on the skin they wear (see
-- THEIR PANEL); nil is you.
function UI.inspectWorn(silent,attempt,who)
    attempt=attempt or 1
    local snapshot,name=App.Current,lp.Name
    if who then
        local player=Players:GetPlayerByUserId(who)
        snapshot=player and Sync.snapshot(who) or nil
        if not snapshot then return false end
        name=player.Name
    end
    if not snapshot or snapshot.Original or type(snapshot.Data)~="table" then
        if not silent then App.report("Wear an avatar first. Your own avatar already shows in Roblox's menu.","info") end
        return false
    end
    local data=UI.inspectData(snapshot.Data,UI.InspectLevels[attempt] or 1)
    local decoded,desc=pcall(Codec.decode,data)
    if not decoded then
        if not silent then App.report("This avatar could not be read.","error") end
        return false
    end
    local shown=pcall(function() game:GetService("GuiService"):InspectPlayerFromHumanoidDescription(desc,name) end)
    -- The previous description is released once the panel has the new one.
    if UI.InspectDesc then pcall(function() UI.InspectDesc:Destroy() end) end
    UI.InspectDesc=desc
    if not shown and not silent then App.report("Roblox's avatar panel is unavailable in this game.","warning") end
    if shown then UI.trackInspect(attempt,UI.inspectIds(data),who) end
    return shown
end
-- The panel draws a 3D avatar for a profile but hides it for an outfit. While the panel shows you, the avatar you are
-- wearing is drawn in that empty space by a view of ours, centred on the panel just above your name. Roblox's own
-- (hidden) 3D view is left alone, and nothing in the panel is changed.
function UI.onScreen(item)
    local cursor=item
    while cursor do
        if cursor:IsA("GuiObject") and not cursor.Visible then return false end
        if cursor:IsA("LayerCollector") then return cursor.Enabled end
        cursor=cursor.Parent
    end
    return false
end
-- Roblox's panel while it is open: it is mounted as "InspectAndBuy" in the Roblox menu's layer, and unmounted when it
-- closes.
function UI.inspectRoot()
    local rgui=game:GetService("CoreGui"):FindFirstChild("RobloxGui")
    return rgui and rgui:FindFirstChild("InspectAndBuy")
end
-- The panel's title ("<name>'s Avatar" in any language): a short visible label that contains the username (yours, or
-- the script user's whose skin the panel shows) but is not just the name itself (player cards) nor a chat line. It is
-- looked for in the panel first, else anywhere in CoreGui.
function UI.inspectTitle(name)
    local core=game:GetService("CoreGui")
    local root=UI.inspectRoot()
    if root then
        local found=UI.inspectTitleIn(root,name)
        if found then return found end
    end
    return UI.inspectTitleIn(core,name)
end
function UI.inspectTitleIn(holder,name)
    local chat=game:GetService("CoreGui"):FindFirstChild("ExperienceChat")
    name=name or lp.Name; local best
    local ok,items=pcall(function() return holder:GetDescendants() end)
    if not ok then return nil end
    for _,item in ipairs(items) do
        -- One protected or half-built element must not end the search, so each one is checked on its own.
        pcall(function()
            if not (item:IsA("TextLabel") or item:IsA("TextButton")) then return end
            -- Rich text tags (bold, colour) are not part of what is shown; a name changed by YOUR NAME still counts.
            local text=Ident.raw(item):gsub("<[^>]+>","")
            if #text<=#name+30 and text~=name and text~="@"..name and text:find(name,1,true) and not text:find(":",1,true)
                and not (UI.Gui and item:IsDescendantOf(UI.Gui)) and not (UI.InspectView and item:IsDescendantOf(UI.InspectView))
                and not (chat and item:IsDescendantOf(chat)) and item.AbsoluteSize.Y>=6 and UI.onScreen(item) then
                if not best or item.AbsoluteSize.Y>best.AbsoluteSize.Y then best=item end
            end
        end)
    end
    return best
end
-- The panel itself: the first frame around the title that reaches well above it. The frames in between only hold
-- the title row and the item list, which start at the title.
function UI.inspectPanel(title)
    local room=math.max(title.AbsoluteSize.Y*3,40)
    local cursor=title.Parent
    while cursor and cursor:IsA("GuiObject") do
        if title.AbsolutePosition.Y-cursor.AbsolutePosition.Y>=room and cursor.AbsoluteSize.X>=title.AbsoluteSize.X then return cursor end
        cursor=cursor.Parent
    end
    return nil
end
-- Which items Roblox's panel lists, read from the item pictures: each one is loaded from the item's asset id.
function UI.panelAssetIds(panel)
    local found={}
    for _,item in ipairs(panel:GetDescendants()) do
        if item:IsA("ImageLabel") or item:IsA("ImageButton") then
            local image=item.Image
            if image~="" then
                local id
                if image:find("rbxthumb",1,true) then
                    if image:match("type=(%a+)")=="Asset" then id=image:match("[&?]id=(%d+)") end
                else
                    id=image:match("[Aa]sset[Ii]d=(%d+)")
                end
                local n=id and Codec.id(tonumber(id))
                if n then found[n]=true end
            end
        end
    end
    return found
end
-- The avatar's background behind the panel's 3D view (see HELD ITEM AND BACKGROUND), placed and shown with it.
function UI.inspectBackground(view,model)
    local id=model and view and model:GetAttribute("LyraBackground")
    local back=UI.InspectBackground
    if not (id and view.Parent and view:IsA("ViewportFrame")) then if back then back.Visible=false end; return end
    if not (back and back.Parent==view.Parent and back:GetAttribute("Id")==id) then
        if back then pcall(function() back:Destroy() end) end
        back=UI.backgroundImage(view.Parent,id); back.Name="LyraInspectBackground"; back:SetAttribute("Id",id)
        UI.round(back,12)
        UI.InspectBackground=back
    end
    back.ZIndex=view.ZIndex-1; back.Position=view.Position; back.Size=view.Size; back.Visible=view.Visible
end
function UI.drawInspectAvatar(view,model,wanted)
    for _,child in ipairs(view:GetChildren()) do if child:GetAttribute("LyraInspect") then child:Destroy() end end
    local clone=model:Clone(); clone:SetAttribute("LyraInspect",true); clone.Parent=view
    local focus,box=Pose.bounds(clone)
    -- A view made this frame has no measured size yet, so the size it is being given is used.
    local size=wanted or view.AbsoluteSize
    local aspect=size.X>0 and size.Y>0 and math.clamp(size.X/size.Y,0.4,2.5) or 1
    local fit=math.max(box.Y,box.X/aspect)
    local camera=Instance.new("Camera"); camera:SetAttribute("LyraInspect",true); camera.FieldOfView=30
    camera.CFrame=CFrame.lookAt(focus+Vector3.new(0,box.Y*0.04,0)+UI.pictureDirection(clone)*((fit*0.5/math.tan(math.rad(15))+box.Z*0.5)*1.1),focus)
    camera.Parent=view; view.CurrentCamera=camera
end
-- The 3D view lives in the same screen layer as the panel's title, so both share one set of coordinates (no
-- top-bar inset maths). Without a layer to share, it gets a screen layer of its own.
-- picture: a user id whose own full-body Roblox picture is shown instead of a 3D view (a profile worn as it is, so the
-- panel shows the same pose as the Roblox menu).
function UI.inspectView(layer,picture)
    local class=picture and "ImageLabel" or "ViewportFrame"
    local view=UI.InspectView
    if view and view.Parent and (view.Parent==layer or not layer) and view.ClassName==class then return view end
    if view then pcall(function() view:Destroy() end) end
    view=Instance.new(class); view.Name="LyraInspectAvatar"; view.BackgroundTransparency=1; view.BorderSizePixel=0; view.Visible=false
    view.ZIndex=1000
    if picture then
        view.ScaleType=Enum.ScaleType.Fit
---- YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
        view.Image=string.format("rbxthumb://type=Avatar&id=%d&w=720&h=720",picture)
    else
        view.Ambient=Color3.fromRGB(195,186,213); view.LightColor=Color3.fromRGB(255,244,233); view.LightDirection=Vector3.new(-1,-1,-1)
    end
    local placed=layer and pcall(function() view.Parent=layer end) and view.Parent==layer
    if not placed then
        if not (UI.InspectOverlay and UI.InspectOverlay.Parent) then
            local gui=Instance.new("ScreenGui"); gui.Name="LyraInspectAvatar"; gui.IgnoreGuiInset=true; gui.ResetOnSpawn=false
            gui.DisplayOrder=5000; gui.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
            UI.mount(gui,lp:FindFirstChild("PlayerGui")); UI.InspectOverlay=gui
        end
        view.Parent=UI.InspectOverlay
    end
    UI.InspectView=view
    return view
end
-- Roblox's newer panel is one rounded frame named ContainerView: the item list on the left, and on the right the
-- space where a profile's 3D avatar goes, above the total and the Buy button. Older and narrow layouts put the avatar
-- above the title instead (UI.inspectPanel).
function UI.inspectContainer(title)
    local cursor=title.Parent
    while cursor and not cursor:IsA("LayerCollector") do
        if cursor.Name=="ContainerView" and cursor:IsA("GuiObject") then return cursor end
        cursor=cursor.Parent
    end
    return nil
end
-- The item list: the largest scrolling list on screen in the panel.
function UI.inspectList(container)
    local best,area=nil,0
    for _,item in ipairs(container:GetDescendants()) do
        if item:IsA("ScrollingFrame") and UI.onScreen(item) then
            local size=item.AbsoluteSize.X*item.AbsoluteSize.Y
            if size>area then best,area=item,size end
        end
    end
    return best
end
-- The empty space beside the item list, from the panel's top down to the total and the Buy button: {X,Y,W,H} on
-- screen, or nil when the list takes the whole width (a narrow layout).
function UI.inspectSide(container,title)
    local cPos,cSize=container.AbsolutePosition,container.AbsoluteSize
    local list=UI.inspectList(container)
    local split=list and (list.AbsolutePosition.X+list.AbsoluteSize.X) or (title.AbsolutePosition.X+title.AbsoluteSize.X)
    local right=cPos.X+cSize.X
    if right-split<math.max(cSize.X*0.22,80) then return nil end
    -- The first text or button below the top third of that side (the total row) ends the space. A layer that covers
    -- the whole side (Roblox's hidden 3D view, a drag area) starts at the top, so it never counts.
    local bottom=cPos.Y+cSize.Y
    for _,item in ipairs(container:GetDescendants()) do
        if (item:IsA("GuiButton") or (item:IsA("TextLabel") and item.Text~="")) and not (UI.InspectView and item:IsDescendantOf(UI.InspectView)) then
            local pos,size=item.AbsolutePosition,item.AbsoluteSize
            if size.Y>0 and pos.X>=split-2 and pos.Y>cPos.Y+cSize.Y*0.3 and pos.Y<bottom and UI.onScreen(item) then bottom=pos.Y end
        end
    end
    return {X=split,Y=cPos.Y,W=right-split,H=bottom-cPos.Y}
end
-- YOUR PANEL, OWNED: the panel lists what you wear against your real inventory, so items you don't own showed their
-- price and an active Buy button. On your screen only, it now reads as it does for the avatar's owner: each item says
-- Owned (Roblox's own word, in your language), the total is 0 and the Buy button is greyed out and blocked, so no
-- purchase starts from it. On an item's page the Buy button says Owned. Text Roblox writes again is marked again, and
-- everything goes back when the panel is left.
function UI.ownedText()
    if UI.OwnedText then return UI.OwnedText end
    local key,text="InGame.InspectMenu.Label.Owned",nil
    local function usable(value) return type(value)=="string" and value~="" and #value<=40 and not value:find("InGame.",1,true) end
    pcall(function()
        local tbl=game:GetService("CoreGui"):FindFirstChild("CoreScriptLocalization")
        local translator=tbl and tbl:GetTranslator(game:GetService("LocalizationService").RobloxLocaleId)
        text=translator and translator:FormatByKey(key)
    end)
    if not usable(text) then
        pcall(function() text=require(game:GetService("CorePackages").Workspace.Packages.RobloxTranslator):FormatByKey(key) end)
    end
    UI.OwnedText=usable(text) and text or "Owned"
    return UI.OwnedText
end
-- A price as the panel writes it: digits and separators, with or without the Robux sign (U+E002).
function UI.isPrice(text)
    if type(text)~="string" or #text>40 then return false end
    local plain=text:gsub("<[^>]+>",""):gsub("\238\128\130",""):gsub("\194\160",""):gsub("\226\128\175",""):gsub("%s","")
    return plain:match("^%d[%d,%.']*$")~=nil
end
-- The word Roblox itself writes in this list for an item you have (it can differ from the menu's general one), read
-- from an item of your own avatar that the worn one shares: its price line, when it is not a price nor ours. Free
-- items also show a word there, so only items you surely own are read.
function UI.panelOwnedWord(container,state,own)
    if not own or not next(own) then return nil end
    for _,image in ipairs(container:GetDescendants()) do
        if image:IsA("ImageLabel") and image.Name=="ItemCardThumbnailImage" then
            local kind,id=image.Image:match("type=(%a+)"),tonumber(image.Image:match("[?&]id=(%d+)"))
            if kind=="Asset" and id and own[id] then
                local row=image.Parent
                while row and row~=container and not (row:IsA("GuiButton") and row.Name:match("^Item%d")) do row=row.Parent end
                local amount=row and row~=container and row:FindFirstChild("ItemCardPriceLineAmount",true)
                if amount and amount:IsA("TextLabel") and amount.Text~="" and not state.Labels[amount] and not UI.isPrice(amount.Text) then return amount.Text end
            end
        end
    end
    return nil
end
function UI.ownedState() return {Labels={},Hidden={},Covers={},Buttons={},Roots={}} end
-- The text Roblox wrote in a label, also while ours is showing.
function UI.ownedRaw(state,label)
    local row=state.Labels[label]
    if row and label.Text==row.Written then return row.Text end
    return label.Text
end
function UI.ownedWrite(state,label,text)
    state.Labels[label]={Text=UI.ownedRaw(state,label),Written=text}
    if label.Text~=text then label.Text=text end
end
function UI.ownedHide(state,item)
    if state.Hidden[item]==nil then state.Hidden[item]=item.Visible end
    if item.Visible then item.Visible=false end
end
-- A property as shown: Roblox's newer menus set many of them through styles, which reading the property misses.
function UI.styled(item,prop)
    local ok,value=pcall(function() return item:GetStyled(prop) end)
    if ok and value~=nil then return value end
    return item[prop]
end
-- The Robux sign next to a price: a small picture beside it, in the same row.
function UI.isIconText(label)
    local ok,family=pcall(function() return label.FontFace.Family end)
    return (ok and tostring(family):find("BuilderIcons",1,true)~=nil) or label.Text=="robux"
end
function UI.ownedSign(state,label)
    local lPos,lSize=label.AbsolutePosition,label.AbsoluteSize
    for _,holder in ipairs({label.Parent,label.Parent and label.Parent.Parent}) do
        if holder then
            for _,item in ipairs(holder:GetChildren()) do
                -- A picture, or a text drawn in Roblox's icon font (BuilderIcons: the word "robux" draws the sign).
                local picture=(item:IsA("ImageLabel") or item:IsA("ImageButton") or (item:IsA("TextLabel") and item~=label and UI.isIconText(item))) and item or nil
                if picture and not label:IsDescendantOf(picture) and picture.Visible then
                    local pos,size=picture.AbsolutePosition,picture.AbsoluteSize
                    local beside=pos.X<lPos.X+2 and math.abs((pos.Y+size.Y/2)-(lPos.Y+lSize.Y/2))<lSize.Y
                    if beside and size.X>0 and size.X<=lSize.Y*1.8 and size.Y<=lSize.Y*1.8 then UI.ownedHide(state,picture) end
                end
            end
        end
    end
end
-- The Buy button: the largest filled button with a short text (Buy items, Buy Item) outside the item lists. Item rows
-- hold several texts, the back and close buttons have none, and Try On or favourite pills are smaller.
function UI.ownedBuyButton(container,lists)
    -- Roblox's own name for it first (the panel names it BuyButton).
    local named=container:FindFirstChild("BuyButton",true)
    if named and named:IsA("GuiButton") and UI.onScreen(named) then return named end
    local best,area=nil,0
    for _,item in ipairs(container:GetDescendants()) do
        if item:IsA("GuiButton") and not item:GetAttribute("LyraOwned") and UI.onScreen(item) then
            local size=item.AbsoluteSize
            local inList=false
            for list in pairs(lists) do if item:IsDescendantOf(list) then inList=true; break end end
            if not inList and size.X>=80 and size.Y>=20 and size.Y<=160 and size.X<container.AbsoluteSize.X*0.8 and size.X*size.Y>area then
                local texts,filled=0,false
                local parts=item:GetDescendants(); table.insert(parts,item)
                for _,part in ipairs(parts) do
                    if (part:IsA("TextLabel") or part:IsA("TextButton")) and part.Text~="" and part.Visible then texts=texts+1 end
                    if part:IsA("GuiObject") and part.Visible and UI.styled(part,"BackgroundTransparency")<0.5 and part.AbsoluteSize.X>=size.X*0.6 then filled=true end
                end
                if filled and texts>=1 and texts<=2 then best,area=item,size.X*size.Y end
            end
        end
    end
    return best
end
-- The whole button: from the part found, up to the largest frame around it that still holds only its text (the blue
-- shape can sit a level or two above the part that takes the taps).
function UI.ownedButtonRoot(container,button)
    local function texts(holder)
        local count=0
        local items=holder:GetDescendants(); table.insert(items,holder)
        for _,item in ipairs(items) do if (item:IsA("TextLabel") or item:IsA("TextButton")) and item.Text~="" and item.Visible and not item:GetAttribute("LyraOwned") then count=count+1 end end
        return count
    end
    local root,own=button,texts(button)
    for _=1,4 do
        local parent=root.Parent
        if not (parent and parent:IsA("GuiObject") and parent~=container and parent:IsDescendantOf(container)) then break end
        local size=parent.AbsoluteSize
        if size.X>container.AbsoluteSize.X*0.6 or size.Y>160 or texts(parent)~=own then break end
        root=parent
    end
    return root
end
-- Greyed out as Roblox greys out a button with nothing to buy (the button at half strength over the panel): a dark
-- layer of ours at half strength over the whole button, which also takes the taps. It sits in the panel's screen
-- layer, outside the button, and follows the button's place on screen: inside it, the button's padding and row layout
-- shrank it to the size of the text.
function UI.ownedButton(state,button,relabel,container)
    local root=container and UI.ownedButtonRoot(container,button) or button
    local cover=state.Covers[button]
    if not (cover and cover.Parent) then
        local layer=root:FindFirstAncestorWhichIsA("LayerCollector")
        if not layer then return end
        cover=Instance.new("TextButton")
        cover.Name="LyraOwned"; cover:SetAttribute("LyraOwned",true); cover.Text=""; cover.AutoButtonColor=false; cover.Selectable=false
        cover.BackgroundColor3=Color3.new(0,0,0); cover.BackgroundTransparency=0.5; cover.BorderSizePixel=0; cover.ZIndex=1001
        -- The button's own rounding, and its border line (drawn just outside it) covered too.
        local corner=root:FindFirstChildOfClass("UICorner")
        local stroke=root:FindFirstChildOfClass("UIStroke")
        local edge=0
        if stroke then local ok,thickness=pcall(function() return UI.styled(stroke,"Thickness") end); edge=ok and tonumber(thickness) or 1 end
        edge=math.clamp(math.ceil(edge),0,4)
        cover:SetAttribute("LyraEdge",edge)
        local radius=corner and corner.CornerRadius or UDim.new(0,math.max(4,math.floor(root.AbsoluteSize.Y*0.2+0.5)))
        local round=Instance.new("UICorner"); round.CornerRadius=UDim.new(radius.Scale,radius.Offset+edge); round.Parent=cover
        cover.Parent=layer
        state.Covers[button]=cover
    end
    state.Roots[button]=root
    UI.ownedPlace(cover,root)
    if relabel then
        -- On an item's page the button's own text says Owned, as on an item you have.
        local text
        local items=root:GetDescendants(); table.insert(items,root)
        for _,item in ipairs(items) do
            if (item:IsA("TextLabel") or item:IsA("TextButton")) and item.Text~="" and not item:GetAttribute("LyraOwned")
                and (not text or item.AbsoluteSize.X*item.AbsoluteSize.Y>text.AbsoluteSize.X*text.AbsoluteSize.Y) then text=item end
        end
        if text then UI.ownedWrite(state,text,relabel) end
    end
end
function UI.ownedPlace(cover,root)
    local layer=cover.Parent
    local origin=layer and layer:IsA("LayerCollector") and layer.AbsolutePosition or Vector2.zero
    local edge=cover:GetAttribute("LyraEdge") or 0
    cover.Position=UDim2.fromOffset(root.AbsolutePosition.X-origin.X-edge,root.AbsolutePosition.Y-origin.Y-edge)
    cover.Size=UDim2.fromOffset(root.AbsoluteSize.X+edge*2,root.AbsoluteSize.Y+edge*2)
    cover.Visible=root.Parent~=nil and UI.onScreen(root)
end
-- Every tick of the panel's loop: the layers follow their buttons (the panel scrolls and moves).
function UI.ownedTrack(states)
    for _,state in ipairs({states.List,states.Detail}) do
        for button,cover in pairs(state.Covers) do
            local root=state.Roots[button]
            if root and cover.Parent then pcall(UI.ownedPlace,cover,root) end
        end
    end
end
function UI.ownedRestore(state)
    for label,row in pairs(state.Labels) do pcall(function() if label.Parent and label.Text==row.Written then label.Text=row.Text end end) end
    for item,visible in pairs(state.Hidden) do pcall(function() if item.Parent and not item.Visible then item.Visible=visible end end) end
    for _,cover in pairs(state.Covers) do pcall(function() cover:Destroy() end) end
    for key,list in pairs(state) do table.clear(list) end
end
-- states: {List, Detail}; listPage: the panel shows the avatar's item list (with its title), else an item's page.
function UI.markOwned(states,container,listPage,own)
    if not Store.Settings.MenuAvatar then return end
    local state=listPage and states.List or states.Detail
    UI.ownedRestore(listPage and states.Detail or states.List)
    states.Word=UI.panelOwnedWord(container,state,own) or states.Word
    local owned=states.Word or UI.ownedText()
    local width=container.AbsoluteSize.X
    -- Prices on screen, and the item lists: a scrolling list holding two prices or more (and, on the list page, the
    -- largest one), so a list is never taken for a total.
    local prices,perList={},{}
    for _,item in ipairs(container:GetDescendants()) do
        if (item:IsA("TextLabel") or item:IsA("TextButton")) and not item:GetAttribute("LyraOwned") and UI.isPrice(UI.ownedRaw(state,item)) and UI.onScreen(item) then
            -- Counts on small buttons (favourites) are not prices.
            local button=item:FindFirstAncestorWhichIsA("GuiButton")
            if not (button and button:IsDescendantOf(container) and button.AbsoluteSize.X<width*0.3) then
-- @YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
                table.insert(prices,item)
                local scroller=item:FindFirstAncestorWhichIsA("ScrollingFrame")
                if scroller and scroller:IsDescendantOf(container) then perList[scroller]=(perList[scroller] or 0)+1 end
            end
        end
    end
    local lists={}
    for scroller,count in pairs(perList) do if count>=2 then lists[scroller]=true end end
    if listPage then local main=UI.inspectList(container); if main then lists[main]=true end end
    local totals={}
    for _,item in ipairs(prices) do
        local inList=false
        for list in pairs(lists) do if item:IsDescendantOf(list) then inList=true; break end end
        if inList then UI.ownedWrite(state,item,owned); UI.ownedSign(state,item)
        else table.insert(totals,item) end
    end
    -- Once greyed out the button no longer looks filled, so the one found stays while it is on screen.
    local button
    for item in pairs(state.Buttons) do if item.Parent and item:IsDescendantOf(container) and UI.onScreen(item) then button=item; break end end
    if not button then
        table.clear(state.Buttons)
        button=UI.ownedBuyButton(container,lists)
        if button then state.Buttons[button]=true end
    end
    for _,total in ipairs(totals) do
        local hidden=false
        if not listPage then
            -- An owned item's page has no total: the small row holding it is hidden (never a list, never a block
            -- with the button or with more than a few texts); otherwise it reads 0.
            local row=total
            while row.Parent and row.Parent~=container and not (button and button:IsDescendantOf(row.Parent)) do row=row.Parent end
            local texts,big=0,row:FindFirstChildWhichIsA("ScrollingFrame",true)~=nil
            for _,part in ipairs(row:GetDescendants()) do if part:IsA("TextLabel") and part.Text~="" then texts=texts+1 end end
            if row~=total and row:IsA("GuiObject") and not big and texts<=3 and row.AbsoluteSize.Y<=math.max(total.AbsoluteSize.Y*4,60)
                and not (button and button:IsDescendantOf(row)) then
                UI.ownedHide(state,row); hidden=true
            end
        end
        if not hidden then UI.ownedWrite(state,total,"0") end
    end
    for item in pairs(state.Buttons) do
        if item.Parent and item:IsDescendantOf(container) then UI.ownedButton(state,item,not listPage and owned or nil,container) end
    end
end
UI.InspectSerial=0
-- who: a script user whose synced skin the panel shows (see THEIR PANEL). Their items keep Roblox's prices and Buy
-- button: the owned marks are only for your own panel.
function UI.trackInspect(attempt,wanted,who)
    UI.InspectSerial=UI.InspectSerial+1; local serial=UI.InspectSerial
    attempt=attempt or 1; wanted=wanted or {}
    local name=lp.Name
    if who then
        local player=Players:GetPlayerByUserId(who)
        if not player then return end
        name=player.Name
    end
    local own=not who and App.Initial and UI.inspectIds(App.Initial.Data) or {}
    local owned={List=UI.ownedState(),Detail=UI.ownedState()}
    task.spawn(function()
        -- A profile worn as it is shows its own Roblox picture, the same one as in the Roblox menu; any other look is
        -- drawn in 3D. A script user's skin is drawn in 3D, as in their pictures.
        local picture=not who and Thumbs.userFor(App.Current) or nil
        local model
        if who then model=Sync.pictureModel(who) elseif not picture then model=UI.menuAvatarModel() end
        if not picture and not model then return end
        local title,lastSearch,drawn=nil,0,nil
        -- The panel stays yours while it stays open: an item's page (tap an item) has no title. The list counts as
        -- shown for a moment after its title was last seen, so a title Roblox redraws is not taken for an item's page.
        local container,lastOwned,titleAt=nil,0,-math.huge
        -- Item check: from 1.5 s after the panel is found, once a second, until it is settled. A skin saved from an
        -- old file or as a visual copy has no catalog items, so there is nothing to check.
        local checkAt,strikes,settled,unreadable=nil,0,next(wanted)==nil,0
        -- Followed while the panel is open; it stops 20 s after the panel was last seen.
        local deadline=os.clock()+20
        while App.alive() and serial==UI.InspectSerial and os.clock()<deadline do
            pcall(function()
                if not (title and title.Parent and UI.onScreen(title) and Ident.raw(title):find(name,1,true)) then
                    title=nil
                    if os.clock()-lastSearch>=0.3 then lastSearch=os.clock(); title=UI.inspectTitle(name) end
                end
                if container and not (container.Parent and UI.onScreen(container)) then container=nil end
                if title then container=UI.inspectContainer(title) or container; titleAt=os.clock() end
                if not who then
                    if container and os.clock()-lastOwned>=0.3 then lastOwned=os.clock(); pcall(UI.markOwned,owned,container,os.clock()-titleAt<1.5,own) end
                    pcall(UI.ownedTrack,owned)
                end
                if not title then
                    if UI.InspectView then UI.InspectView.Visible=false end
                    pcall(UI.inspectBackground,UI.InspectView,model)
                    if container then deadline=os.clock()+20 end
                    return
                end
                deadline=os.clock()+20
                if not who then pcall(Ident.title,title) end
                local panel=container or UI.inspectPanel(title)
                local layer=title:FindFirstAncestorWhichIsA("ScreenGui")
                local view=UI.inspectView(layer,picture)
                -- Coordinates relative to the layer the view is in (the panel's own one, or ours).
                local origin=view.Parent and view.Parent:IsA("LayerCollector") and view.Parent.AbsolutePosition or Vector2.zero
                if view.Parent==UI.InspectOverlay and layer and not layer.IgnoreGuiInset then origin=origin-game:GetService("GuiService"):GetGuiInset() end
                local x,y,width,height
                local side=container and UI.inspectSide(container,title)
                if side then
                    -- Newer panel: the space beside the item list, where Roblox draws a profile's avatar.
                    x,y,width,height=side.X+10,side.Y+10,side.W-20,side.H-20
                else
                    -- The empty space between the panel's top edge and the title, centred on the panel.
                    local tPos,tSize=title.AbsolutePosition,title.AbsoluteSize
                    local top=panel and panel.AbsolutePosition.Y or (tPos.Y-math.max(tSize.Y*8,100))
                    height=tPos.Y-top-12
                    width=math.min(height*0.8,(panel and panel.AbsoluteSize.X or tSize.X*2)*0.6)
                    local center=panel and (panel.AbsolutePosition.X+panel.AbsoluteSize.X/2) or (tPos.X+tSize.X/2)
                    x,y=center-width/2,top+6
                end
                local fits=height>=40 and width>=30
                if fits then
                    view.Size=UDim2.fromOffset(width,height)
                    view.Position=UDim2.fromOffset(x-origin.X,y-origin.Y)
                    -- The camera is framed again when the view's size changes.
                    if model and (not drawn or math.abs(drawn.X-width)>4 or math.abs(drawn.Y-height)>4 or not view:FindFirstChildWhichIsA("Model")) then
                        drawn=Vector2.new(width,height); UI.drawInspectAvatar(view,model,drawn)
                    end
                end
                view.Visible=fits
                pcall(UI.inspectBackground,view,model)
                if panel and not settled then
                    checkAt=checkAt or os.clock()+1.5
                    if os.clock()>=checkAt then
                        checkAt=os.clock()+1
                        local listed=UI.panelAssetIds(panel)
                        local mine,yours=0,0
                        -- Of a script user's own avatar nothing is known here: any listed item that is not of the
                        -- synced skin counts as theirs.
                        for id in pairs(listed) do if wanted[id] then mine=mine+1 elseif who or own[id] then yours=yours+1 end end
                        if mine+yours==0 then
                            -- Pictures that name no item of either avatar: the panel can't be checked.
                            unreadable=unreadable+1
                            if unreadable>=4 then settled=true end
                        elseif yours>mine then
                            strikes=strikes+1
                            if strikes>=2 then
                                settled=true
                                local nextAttempt=attempt+1
                                if UI.InspectLevels[nextAttempt] then
                                    task.defer(function() if App.alive() and serial==UI.InspectSerial then UI.inspectWorn(true,nextAttempt,who) end end)
                                end
                            end
                        else
                            settled=true
                        end
                    end
                end
            end)
            task.wait(0.1)
        end
        pcall(UI.ownedRestore,owned.List); pcall(UI.ownedRestore,owned.Detail)
        if serial==UI.InspectSerial then
            if UI.InspectView then pcall(function() UI.InspectView:Destroy() end); UI.InspectView=nil end
            if UI.InspectOverlay then pcall(function() UI.InspectOverlay:Destroy() end); UI.InspectOverlay=nil end
        end
    end)
end
-- Roblox's own request to open the panel on a player (the Players page, the leaderboard's Examine Avatar, a game's
-- button): when it is you and you wear a copied avatar, the panel is pointed at what you wear. Some executors can't
-- listen to it; the Players page and leaderboard buttons are then followed instead (UI.hookInspectCard).
function UI.watchInspect()
    pcall(function()
        RegisterConnection(game:GetService("GuiService").InspectPlayerFromUserIdWithCtxRequest:Connect(function(userId)
            if not App.alive() then return end
            local uid=tonumber(userId)
            if uid==lp.UserId then UI.InspectHeardAt=os.clock(); UI.inspectSelf()
            elseif uid and Sync.pictureUsers()[uid] then UI.InspectHeardAt=os.clock(); UI.inspectPeer(uid) end
        end))
    end)
end
function UI.inspectHeard()
    return UI.InspectHeardAt~=nil and os.clock()-UI.InspectHeardAt<2
end
-- The profile loads from the web, so the request is repeated once in case it finished after the first one.
function UI.inspectSelf()
    if not Store.Settings.MenuAvatar or not App.Current or App.Current.Original then return end
    task.delay(0.2,function() if App.alive() then UI.inspectWorn(true) end end)
    task.delay(1.3,function() if App.alive() then UI.inspectWorn(true) end end)
end
-- THEIR PANEL: Skin sync shows you the skin another script user wears, but Roblox's avatar panel (Examine Avatar in
-- the leaderboard, a player's card in the Roblox menu, a game's own inspect button) still listed the items of their
-- real avatar. While their skin is synced, the panel opened on them is pointed at that skin instead: its items with
-- Roblox's own names, prices and Buy button, the total, and the skin drawn in 3D where Roblox draws a profile's avatar.
-- On your screen only, with "Show my avatar on the game's copies of me" on (as their pictures).
function UI.inspectPeer(uid)
    if not Sync.pictureUsers()[uid] then return end
    for _,delay in ipairs({0.2,1.3}) do
        task.delay(delay,function() if App.alive() and Sync.pictureUsers()[uid] then UI.inspectWorn(true,nil,uid) end end)
    end
end
-- Whose card of the Roblox menu's Players page this is right now: you, a script user sharing a skin, or nil.
function UI.cardUser(root)
    local names={[lp.DisplayName]=lp.UserId,[lp.Name]=lp.UserId,["@"..lp.Name]=lp.UserId}
    local unique={}
    for uid in pairs(Sync.pictureUsers()) do
        local player=Players:GetPlayerByUserId(uid)
        if player then unique[player.Name]=uid; unique["@"..player.Name]=uid; if player.DisplayName~="" and not names[player.DisplayName] then names[player.DisplayName]=uid end end
    end
    -- A username names one player; a display name can be shared, so it only counts when no username is on the card.
    local byDisplay
    for _,item in ipairs(root:GetDescendants()) do
        if item:IsA("TextLabel") or item:IsA("TextButton") then
            local text=Ident.raw(item)
            if text==lp.Name or text=="@"..lp.Name then return lp.UserId end
            if unique[text] then return unique[text] end
            byDisplay=byDisplay or names[text]
        end
    end
    return byDisplay
end
-- Tapping your own card opens Roblox's panel for your profile; it is then pointed at what you wear. The profile
-- loads from the web, so the request is repeated once in case it finished after the first one.
UI.InspectHooks=setmetatable({},{__mode="k"})
function UI.hookInspectCard(root)
    if UI.InspectHooks[root] then return end
    -- The card's main button is the largest one (small ones are actions like add friend).
    local button,area=nil,0
    local candidates=root:GetDescendants(); table.insert(candidates,root)
    for _,item in ipairs(candidates) do
        if item:IsA("GuiButton") then
            local size=item.AbsoluteSize.X*item.AbsoluteSize.Y
            if size>area then button,area=item,size end
        end
    end
    if not button then return end
    UI.InspectHooks[root]=true
    UI.connect(button.Activated,function()
        -- Cards are recycled while scrolling: only who the card shows right now counts (you, or a script user
        -- sharing a skin, see THEIR PANEL).
        local who=UI.cardUser(root)
        if not who then return end
        -- Roblox's own request, when heard, already did this (see UI.watchInspect).
        task.delay(0.1,function()
            if not App.alive() or UI.inspectHeard() then return end
            if who==lp.UserId then UI.inspectSelf() else UI.inspectPeer(who) end
        end)
    end)
end
-- Finds your card in the Players page (the list recycles its cards, so every card is checked each time).
function UI.patchMenuAvatar()
    local rgui=game:GetService("CoreGui"):FindFirstChild("RobloxGui")
    local page=rgui and rgui:FindFirstChild("peoplepage",true)
    if not page then return end
    -- The menu's other pages (the profile page) are followed by their own watcher, started once; a Players page built
    -- again is the one followed from then on.
    if not (Thumbs.MenuRoot and Thumbs.MenuRoot.Parent) or Thumbs.PeoplePage~=page then pcall(Thumbs.watchMenu,page) end
    local pictures=Store.Settings.MenuAvatar
    -- A profile worn as it is shows that profile's own Roblox picture (its pose or emote included); any other look is
    -- drawn in 3D.
    local profileId=pictures and Thumbs.userFor(App.Current) or nil
    local model,serial
    if pictures and not profileId then model,serial=UI.menuAvatarModel() end
    local names={[lp.DisplayName]=lp.UserId,[lp.Name]=lp.UserId,["@"..lp.Name]=lp.UserId}
    -- Other script users sharing a skin through Skin sync show it in their cards too (see SKIN SYNC PICTURES).
    for uid in pairs(Sync.pictureUsers()) do
        local player=Players:GetPlayerByUserId(uid)
        if player then names[player.Name]=uid; names["@"..player.Name]=uid; if player.DisplayName~="" and not names[player.DisplayName] then names[player.DisplayName]=uid end end
    end
    for _,label in ipairs(page:GetDescendants()) do
        if label:IsA("TextLabel") or label:IsA("TextButton") then
            -- Your name and @username on your card (see YOUR NAME).
            if Ident.Active then pcall(Ident.consider,label) end
        elseif label.Name:find("^Lyra") then
            -- Ours (a profile picture covering Roblox's, a background): never covered itself.
        elseif not pictures then
            local view=label:FindFirstChild("LyraMenuAvatar")
            if view then view:Destroy(); if label:IsA("ImageLabel") then label.ImageTransparency=0 end end
        elseif label.Name=="AvatarThumbnail" and label:IsA("ImageLabel") then
            local root=label.Parent
            while root and root~=page and not root.Name:find("^VirtualizedItem") do root=root.Parent end
            local who
            if root and root~=page then
                for _,item in ipairs(root:GetDescendants()) do
                    if (item:IsA("TextLabel") or item:IsA("TextButton")) and names[Ident.raw(item)] then who=names[Ident.raw(item)]; break end
                end
                pcall(UI.hookInspectCard,root)
            end
            -- The grid's cards show the whole body; the list's rows show a round head picture under the same name, and
            -- the whole body drawn there stuck out of the circle. A picture not laid out yet waits for the next pass.
            local info=Thumbs.read(label.Image)
            local kind=Thumbs.menuKind(label,info)
            if kind then UI.coverMenuPicture(label,who,info,kind=="Avatar",model,serial,profileId,kind) end
        elseif label:IsA("ImageLabel") then
            -- Other pictures of you in the page (the list view's small pictures): found by the picture they load.
            local info=Thumbs.read(label.Image)
            local who=info and (info.User==lp.UserId or Sync.pictureUsers()[info.User]) and info.User or nil
            UI.coverMenuPicture(label,who,info,false,model,serial,profileId,info and info.Kind)
        end
    end
end
-- One picture of the Roblox menu: covered by the copied profile's own picture, by a 3D view of the avatar, or by
-- nothing (Roblox's picture shows again). card: the large picture of a player card. kind: the picture's kind (see
-- Thumbs.menuKind). A picture is drawn again when the avatar changes or when Roblox lays its picture out differently
-- (another kind, round or not, another shape), as a list built before its layout does.
function UI.coverMenuPicture(label,who,info,card,model,serial,profileId,kind)
    local view=label:FindFirstChild("LyraMenuAvatar")
    local shown,shownSerial
    if who==lp.UserId then
        if profileId then shown,shownSerial="profile","user:"..tostring(profileId) else shown,shownSerial=model,serial end
    elseif who then shown,shownSerial=Sync.pictureModel(who) end
    if who and shown then
        kind=kind or "Avatar"
        local key=tostring(shownSerial).."|"..Thumbs.viewKey(label,kind,card)
        if not view or view:GetAttribute("Key")~=key then
            if view then view:Destroy() end
            if shown=="profile" then pcall(UI.menuProfilePicture,label,profileId,info,shownSerial)
            elseif card then pcall(UI.menuAvatarView,label,shown,shownSerial)
            else pcall(UI.menuPicture,label,shown,shownSerial,kind) end
            local made=label:FindFirstChild("LyraMenuAvatar")
            if made then
                made:SetAttribute("Key",key); made:SetAttribute("Kind",kind)
                made:SetAttribute("Way",shown=="profile" and "profile" or card and "card" or "picture")
                made:SetAttribute("LabelSize",label.AbsoluteSize)
            end
        end
    elseif view then view:Destroy(); label.ImageTransparency=0 end
end
-- The copied profile's own Roblox picture, the same kind and size as the one it covers.
function UI.menuProfilePicture(label,userId,info,serial)
    local image=Instance.new("ImageLabel")
    image.Name="LyraMenuAvatar"; image.Size=UDim2.fromScale(1,1); image.BackgroundTransparency=1; image.BorderSizePixel=0
    image.ZIndex=label.ZIndex+1; image.ScaleType=label.ScaleType
    image.Image=Thumbs.swapUser(label.Image,userId) or string.format("rbxthumb://type=%s&id=%d&w=%d&h=%d",info and info.Kind or "Avatar",userId,info and info.W or 420,info and info.H or 420)
    image:SetAttribute("Serial",serial)
    local corner=label:FindFirstChildOfClass("UICorner")
    if corner then corner:Clone().Parent=image
    elseif label.Name~="AvatarThumbnail" and Thumbs.looksRound(label,label.Image,info and info.Kind) then Thumbs.round(image) end
    label.ImageTransparency=1
    image.Parent=label
end
-- PROFILE PAGE, CURRENTLY WEARING: the Roblox menu's profile page lists the items you really wear. While you wear a
-- copied avatar, Roblox's row is hidden on your screen and a row of ours takes its place: a copy of Roblox's scrolling
-- row (same place, size and style) holding copies of one of Roblox's cards, one per item of the avatar (picture, name
-- and price from the catalog). Roblox places its cards one by one as you scroll (only those on screen exist), so our
-- cards are laid out by a list of our own. Tapping one of ours does nothing. Roblox's row comes back when the avatar is
-- your own, the option is off or the page shows someone else.
UI.Worn=nil
-- The items a profile page lists, in Roblox's order: accessories, makeup, face, clothing, then body parts.
function UI.wornIds(data)
    local list,seen={},{}
    local function add(id) id=Codec.id(tonumber(id)); if id and not seen[id] then seen[id]=true; table.insert(list,id) end end
    if type(data)~="table" then return list end
    local props=data.Version==2 and data.Properties or data
    for _,row in ipairs(type(data.Accessories)=="table" and data.Accessories or {}) do if type(row)=="table" then add(row.AssetId) end end
    if type(props)=="table" then
        for _,field in ipairs(Codec.accessoryFields) do if type(props[field])=="string" then for id in props[field]:gmatch("%d+") do add(id) end end end
    end
    for _,row in ipairs(type(data.Makeup)=="table" and data.Makeup or {}) do if type(row)=="table" then add(row.AssetId) end end
    if type(props)=="table" then
        for _,field in ipairs({"Face","Shirt","Pants","GraphicTShirt","Head","Torso","LeftArm","RightArm","LeftLeg","RightLeg"}) do add(props[field]) end
    end
    return list
end
-- A card of the row: a picture and a text.
function UI.isWornCard(item)
    if not item:IsA("GuiObject") or item:GetAttribute("LyraWorn") then return false end
    local picture,text=false,false
    for _,part in ipairs(item:GetDescendants()) do
        if part:IsA("ImageLabel") or part:IsA("ImageButton") then picture=true end
        if part:IsA("TextLabel") and part.Text~="" then text=true end
        if picture and text then return true end
    end
    return false
end
-- The row near your @username: a scrolling list whose cards sit side by side. Returns the scrolling frame and the
-- cards on screen. The Players page is never searched.
function UI.wornRow(label)
    local cursor=label.Parent
    for _=1,8 do
        if not cursor or cursor:IsA("LayerCollector") then return nil end
        if Thumbs.PeoplePage and Thumbs.PeoplePage.Parent and Thumbs.PeoplePage:IsDescendantOf(cursor) then return nil end
        local ok,items=pcall(function() return cursor:GetDescendants() end)
        if ok and #items<=4000 then
            for _,scroller in ipairs(items) do
                if scroller:IsA("ScrollingFrame") and not scroller:GetAttribute("LyraWorn") and not label:IsDescendantOf(scroller) and UI.onScreen(scroller) then
                    for _,holder in ipairs({scroller,scroller:FindFirstChildWhichIsA("GuiObject")}) do
                        local cards={}
                        for _,child in ipairs(holder and holder:GetChildren() or {}) do if UI.isWornCard(child) and child.Visible then table.insert(cards,child) end end
                        local first,second=cards[1],cards[2]
                        local sideBySide=second and math.abs(first.AbsolutePosition.Y-second.AbsolutePosition.Y)<=4 and math.abs(first.AbsolutePosition.X-second.AbsolutePosition.X)>4
                        if sideBySide or (first and scroller.ScrollingDirection==Enum.ScrollingDirection.X) then
                            table.sort(cards,function(a,b) return a.AbsolutePosition.X<b.AbsolutePosition.X end)
                            return scroller,cards
                        end
                    end
                end
            end
        end
        cursor=cursor.Parent
    end
    return nil
end
-- Where a part sits in a card: at each level its name and which child of that name it is, so the same part is found in
-- a copy of the card (Roblox gives many parts the same name).
function UI.partPath(card,part)
    local steps,cursor={},part
    while cursor and cursor~=card do
        local parent=cursor.Parent
        if not parent then return nil end
        local nth=0
        for _,child in ipairs(parent:GetChildren()) do
            if child.Name==cursor.Name then nth=nth+1 end
            if child==cursor then break end
        end
        table.insert(steps,1,{cursor.Name,nth})
        cursor=parent
    end
    return cursor==card and steps or nil
end
function UI.followPath(card,path)
    if not path then return nil end
    local cursor=card
    for _,step in ipairs(path) do
        local found,nth=nil,0
        for _,child in ipairs(cursor:GetChildren()) do
            if child.Name==step[1] then nth=nth+1; if nth==step[2] then found=child; break end end
        end
        cursor=found
        if not cursor then return nil end
    end
    return cursor
end
-- A card's parts, read while Roblox's cards are on screen: its pictures (the item's picture can be drawn in more than
-- one layer), its name (the top text), its price (the text with digits in the bottom row) and the Robux sign beside the
-- price (a small picture, or a text drawn in Roblox's icon font).
UI.RobuxSign="\238\128\130"
function UI.wornParts(card)
    local texts,images,largest={},{},0
    for _,part in ipairs(card:GetDescendants()) do
        if part:IsA("TextLabel") and part.Text~="" and part.Visible then table.insert(texts,part) end
        -- Only parts that draw a picture: the card's own button and frames are images with none.
        if (part:IsA("ImageLabel") or part:IsA("ImageButton")) and part.Visible and part.Image~="" and not part.Image:find("^rbxasset://") then
            table.insert(images,part)
            largest=math.max(largest,part.AbsoluteSize.X*part.AbsoluteSize.Y)
        end
    end
    table.sort(texts,function(a,b)
        if math.abs(a.AbsolutePosition.Y-b.AbsolutePosition.Y)>4 then return a.AbsolutePosition.Y<b.AbsolutePosition.Y end
        return a.AbsolutePosition.X<b.AbsolutePosition.X
    end)
    local parts={Pictures={},Name=texts[1]}
    for _,image in ipairs(images) do
        if largest>0 and image.AbsoluteSize.X*image.AbsoluteSize.Y>=largest*0.4 then table.insert(parts.Pictures,image) end
    end
    local last=texts[#texts]
    if last and last~=parts.Name then
        local row={}
        for _,text in ipairs(texts) do
            if text~=parts.Name and math.abs(text.AbsolutePosition.Y-last.AbsolutePosition.Y)<=4 then table.insert(row,text) end
        end
        -- The price: the text with digits, else (an unavailable item) the widest text of the row.
        for _,text in ipairs(row) do if UI.isPrice(text.Text) then parts.Price=text end end
        if not parts.Price then
            for _,text in ipairs(row) do if not parts.Price or text.AbsoluteSize.X>parts.Price.AbsoluteSize.X then parts.Price=text end end
        end
        -- Any other text of the row left of the price is the Robux sign.
        for _,text in ipairs(row) do
            if text~=parts.Price and text.AbsolutePosition.X<parts.Price.AbsolutePosition.X then parts.SignText=text end
        end
    end
    if parts.Price and not parts.SignText then
        local probe=UI.ownedState()
        UI.ownedSign(probe,parts.Price)
        parts.SignImage=next(probe.Hidden)
        for item,visible in pairs(probe.Hidden) do item.Visible=visible end
    end
    return parts
end
-- The template: a card with a price (so its Robux sign is there to show), else the first one. Read from Roblox's cards
-- on screen, then copied, so the copy is taken before anything is hidden.
function UI.wornTemplate(cards)
    local chosen,unavailable
    for _,card in ipairs(cards) do
        local parts=UI.wornParts(card)
        if parts.Price and UI.isPrice(parts.Price.Text) then chosen=chosen or {Card=card,Parts=parts}
        elseif parts.Price then unavailable=unavailable or parts.Price.Text end
    end
    chosen=chosen or {Card=cards[1],Parts=UI.wornParts(cards[1])}
    local card,parts=chosen.Card,chosen.Parts
    local pictures={}
    for _,image in ipairs(parts.Pictures) do table.insert(pictures,UI.partPath(card,image)) end
    local sample=parts.Price and parts.Price.Text or ""
    -- A price written with the sign in the same text keeps it in front.
    local prefix=sample:match("^(.-"..UI.RobuxSign.."%s*)") or ""
    local copy=card:Clone()
    -- The gap between cards, from Roblox's own row.
    local gap=12
    if cards[2] then gap=math.clamp(cards[2].AbsolutePosition.X-(cards[1].AbsolutePosition.X+cards[1].AbsoluteSize.X),0,64) end
    return {Card=copy,Size=card.AbsoluteSize,Gap=gap,Pictures=pictures,Name=parts.Name and UI.partPath(card,parts.Name),
        Price=parts.Price and UI.partPath(card,parts.Price),Sign=(parts.SignText or parts.SignImage) and UI.partPath(card,parts.SignText or parts.SignImage),
        Prefix=prefix,Unavailable=unavailable or Lang.text("Unavailable"),Sample=sample}
end
-- A price written like Roblox's own in this menu (its thousands separator).
function UI.formatPrice(value,sample)
    local separator=tostring(sample):match("%d([%.,])%d%d%d") or ","
    local text=tostring(math.floor(value))
    while true do
        local changed
        text,changed=text:gsub("^(%d+)(%d%d%d)",function(a,b) return a..separator..b end)
        if changed==0 then break end
    end
    return text
end
function UI.wornPrice(info)
    if type(info)~="table" then return nil end
    if info.IsForSale and tonumber(info.PriceInRobux) then return tonumber(info.PriceInRobux) end
    local details=type(info.CollectiblesItemDetails)=="table" and info.CollectiblesItemDetails or nil
    local lowest=details and tonumber(details.CollectibleLowestResalePrice)
    if lowest and lowest>0 then return lowest end
    return nil
end
function UI.fillWornCard(worn,card,id)
    local info=Catalog.Info[id]
    local template=worn.Template
    for _,path in ipairs(template.Pictures) do
        local picture=UI.followPath(card,path)
        if picture then picture.Image=string.format("rbxthumb://type=Asset&id=%d&w=150&h=150",id) end
    end
    local name=UI.followPath(card,template.Name)
    if name then name.Text=type(info)=="table" and tostring(info.Name or "") or "…" end
    local price=UI.followPath(card,template.Price)
    local sign=UI.followPath(card,template.Sign)
    local value=UI.wornPrice(info)
    if price then
        if value then price.Text=template.Prefix..UI.formatPrice(value,template.Sample)
        else price.Text=info==nil and "" or template.Unavailable end
    end
    if sign then sign.Visible=value~=nil end
end
function UI.clearWorn()
    local worn=UI.Worn
    UI.Worn=nil
    if not worn then return end
    pcall(function() worn.Row:Destroy() end)
    pcall(function() worn.Template.Card:Destroy() end)
    pcall(function() if worn.Scroller.Parent then worn.Scroller.Visible=worn.WasVisible end end)
end
-- Our row: a copy of Roblox's scrolling frame without its cards, with a list of our own.
function UI.wornBuildRow(scroller)
    local row=scroller:Clone()
    for _,child in ipairs(row:GetChildren()) do
        if not (child:IsA("UIPadding") or child:IsA("UICorner")) then child:Destroy() end
    end
    row.Name="LyraWornRow"; row:SetAttribute("LyraWorn",true); row.Visible=true
    row.ScrollingDirection=Enum.ScrollingDirection.X; row.CanvasPosition=Vector2.zero
    row.CanvasSize=UDim2.new(); row.AutomaticCanvasSize=Enum.AutomaticSize.X
    return row
end
-- Runs with the Roblox menu's loop while the menu is open.
function UI.patchProfileWorn()
    local label=UI.ProfileName
    local showing=label and label.Parent and UI.onScreen(label) and Ident.raw(label)=="@"..lp.Name
    local snapshot=App.Current
    local wanted=showing and Store.Settings.MenuAvatar and snapshot and not snapshot.Original and type(snapshot.Data)=="table"
    local worn=UI.Worn
    if worn and (not wanted or worn.Label~=label or not worn.Scroller.Parent or not worn.Row.Parent) then UI.clearWorn(); worn=nil end
    if not wanted then return end
    if not worn then
        local scroller,cards=UI.wornRow(label)
        if not scroller or #cards==0 then return end
        local template=UI.wornTemplate(cards)
        -- The gap in the row's own units: the menu may be scaled (UIScale), screen pixels are not.
        local scale=1
        local cursor=scroller
        while cursor and not cursor:IsA("LayerCollector") do
            local factor=cursor:FindFirstChildOfClass("UIScale")
            if factor and factor.Scale>0 then scale=scale*factor.Scale end
            cursor=cursor.Parent
        end
        local row=UI.wornBuildRow(scroller)
        local list=Instance.new("UIListLayout")
        list.FillDirection=Enum.FillDirection.Horizontal; list.SortOrder=Enum.SortOrder.LayoutOrder
        list.Padding=UDim.new(0,math.floor(template.Gap/scale+0.5)); list.Parent=row
        worn={Label=label,Scroller=scroller,Row=row,Template=template,WasVisible=scroller.Visible,Scale=scale}
        UI.Worn=worn
        row.Parent=scroller.Parent
    end
    -- Roblox's row stays hidden (it may show it again when it redraws).
    if worn.Scroller.Visible then worn.Scroller.Visible=false end
    local ids=UI.wornIds(snapshot.Data)
    if worn.Snapshot==snapshot and not worn.Dirty then return end
    for _,child in ipairs(worn.Row:GetChildren()) do if child:GetAttribute("LyraWornCard") then child:Destroy() end end
    worn.Snapshot=snapshot; worn.Dirty=false
    for index,id in ipairs(ids) do
        local ok,card=pcall(function() return worn.Template.Card:Clone() end)
        if ok and card then
            card:SetAttribute("LyraWorn",true); card:SetAttribute("LyraWornCard",true); card.Name="LyraWorn"..index
            card.Visible=true; card.LayoutOrder=index; card.AnchorPoint=Vector2.zero; card.Position=UDim2.new()
            -- Roblox sizes its cards as a share of its fixed scroll width; ours scroll as far as they need.
            card.Size=UDim2.new(0,math.floor(worn.Template.Size.X/worn.Scale+0.5),1,0)
            pcall(UI.fillWornCard,worn,card,id)
            card.Parent=worn.Row
        end
    end
    -- Names and prices come from the catalog in the background; the cards are filled again when they arrive.
    if not worn.Fetching then
        local missing={}
        for _,id in ipairs(ids) do if Catalog.Info[id]==nil then table.insert(missing,id) end end
        if #missing>0 then
            worn.Fetching=true
            task.spawn(function()
                for _,id in ipairs(missing) do
                    if not App.alive() or UI.Worn~=worn then return end
                    pcall(Catalog.info,id)
                end
                worn.Fetching=false
                if UI.Worn==worn then worn.Dirty=true end
            end)
        end
    end
end
-- A picture in the Roblox menu framed like the one it covers (head, bust or whole body).
function UI.menuPicture(label,model,serial,kind)
    local view=Thumbs.view(label,model,kind,Thumbs.looksRound(label,label.Image,kind))
    view.Name="LyraMenuAvatar"; view.ZIndex=label.ZIndex+1; view:SetAttribute("Serial",serial)
    label.ImageTransparency=1
end
-- A card added to the Players page gets its picture right away instead of at the next turn of the loop below; cards
-- added together are patched together.
function UI.queueMenuPatch()
    if UI.MenuPatchQueued or not Store.Settings.MenuAvatar then return end
    UI.MenuPatchQueued = true
    task.defer(function()
        UI.MenuPatchQueued = false
        if App.alive() and Store.Settings.MenuAvatar then pcall(UI.patchMenuAvatar) end
    end)
end
-- While the menu is open: fast at first (it builds its cards lazily), then slower to follow scrolling.
function UI.runMenuAvatar()
    if UI.MenuAvatarRunning or not (Store.Settings.MenuAvatar or Ident.Active) then return end
    UI.MenuAvatarRunning=true
    task.spawn(function()
        local started=os.clock()
        while App.alive() and UI.MenuIsOpen and (Store.Settings.MenuAvatar or Ident.Active) do
            pcall(UI.patchMenuAvatar)
            pcall(UI.patchProfileWorn)
            task.wait(os.clock()-started<4 and 0.2 or 0.6)
        end
        UI.MenuAvatarRunning=false
    end)
end
function UI.clearMenuAvatar()
    local rgui=game:GetService("CoreGui"):FindFirstChild("RobloxGui")
    if rgui then
        for _,item in ipairs(rgui:GetDescendants()) do
            if item.Name=="LyraMenuAvatar" then
                local parent=item.Parent; item:Destroy()
                if parent and parent:IsA("ImageLabel") then parent.ImageTransparency=0 end
            end
        end
    end
    if UI.MenuAvatar then pcall(function() UI.MenuAvatar.Model:Destroy() end); UI.MenuAvatar=nil end
    pcall(UI.clearWorn)
end
function UI.menuReopen()
    UI.Minimized=false; UI.setVisible(true); UI.layout(false)
    App.toast({Title="Avatar Studio reopened",Text="You opened the Roblox menu 3 times in a row. If that was by accident, you can turn this shortcut off.",
        Kind="info",Icon="menu",Duration=9,
        Action={Text="Turn off shortcut",Callback=function()
            if not App.alive() then return end
            Store.Settings.MenuReopen=false; App.persist()
            local refresh=UI.Toggles and UI.Toggles.MenuReopen; if refresh then refresh() end
            UI.refreshReopenCard()
            App.report("Roblox menu shortcut turned off. You can turn it back on in Settings.","info")
        end}})
end
function UI.watchMenu()
    local GuiService=game:GetService("GuiService")
    UI.connect(GuiService.MenuOpened,function() UI.MenuIsOpen=true; UI.runMenuAvatar() end)
    UI.connect(GuiService.MenuClosed,function() UI.MenuIsOpen=false end)
    local stamps={}
    local openedAt=nil
    UI.connect(GuiService.MenuOpened,function()
        openedAt=(not UI.Visible and Store.Settings.MenuReopen) and os.clock() or nil
    end)
    -- A close only counts when its open was seen while the window was hidden and the shortcut was on.
    UI.connect(GuiService.MenuClosed,function()
        local opened=openedAt; openedAt=nil
        if not opened or UI.Visible or not Store.Settings.MenuReopen then table.clear(stamps); return end
        local now=os.clock()
        table.insert(stamps,now)
        while #stamps>0 and now-stamps[1]>5 do table.remove(stamps,1) end
        if #stamps>=3 then table.clear(stamps); UI.menuReopen() end
    end)
end
-- DEV: MENU DUMP. Dev builds only: "/lyradump" in chat writes, for the next 2 minutes, text files of Roblox's own
-- screens as they appear on screen (the avatar panel, the Roblox menu's Players and profile pages, the leaderboard),
-- so their real layout can be read: LyraDump_<screen>.txt in the executor's workspace folder.
function UI.dumpValue(value)
    local kind=typeof(value)
    if kind=="Vector2" then return string.format("%d,%d",math.floor(value.X+0.5),math.floor(value.Y+0.5)) end
    if kind=="UDim2" then return string.format("{%.2f,%d,%.2f,%d}",value.X.Scale,value.X.Offset,value.Y.Scale,value.Y.Offset) end
    if kind=="Color3" then return string.format("#%02X%02X%02X",math.floor(value.R*255+0.5),math.floor(value.G*255+0.5),math.floor(value.B*255+0.5)) end
    if kind=="number" then return (string.format("%.3f",value):gsub("%.?0+$","")) end
    if kind=="EnumItem" then return value.Name end
    if kind=="string" then return string.format("%q",#value>90 and value:sub(1,90).."…" or value) end
    return tostring(value)
end
function UI.dumpTree(root)
    local lines={}
    local function prop(item,name,styled)
        local ok,value=pcall(function() return styled and UI.styled(item,name) or item[name] end)
        return ok and value~=nil and (name.."="..UI.dumpValue(value)) or nil
    end
    local function walk(item,depth)
        if #lines>=8000 then return end
        local parts={string.rep("  ",depth)..item.ClassName.." \""..item.Name.."\""}
        if item:IsA("GuiObject") then
            for _,name in ipairs({"Visible","AbsolutePosition","AbsoluteSize","Size","Position","AnchorPoint","LayoutOrder","ZIndex","AutomaticSize"}) do
                table.insert(parts,prop(item,name))
            end
            table.insert(parts,prop(item,"BackgroundTransparency",true)); table.insert(parts,prop(item,"BackgroundColor3",true))
            if item:IsA("TextLabel") or item:IsA("TextButton") or item:IsA("TextBox") then
                for _,name in ipairs({"Text","TextTransparency","TextColor3","TextSize","RichText"}) do table.insert(parts,prop(item,name,name~="Text")) end
                pcall(function() table.insert(parts,"Font="..item.FontFace.Family) end)
            end
            if item:IsA("ImageLabel") or item:IsA("ImageButton") then
                for _,name in ipairs({"Image","ImageTransparency","ScaleType"}) do table.insert(parts,prop(item,name,name~="Image")) end
            end
            if item:IsA("ScrollingFrame") then
                for _,name in ipairs({"ScrollingDirection","CanvasSize","AbsoluteCanvasSize","AutomaticCanvasSize","CanvasPosition"}) do table.insert(parts,prop(item,name)) end
            end
            if item:IsA("GuiButton") then table.insert(parts,"Button") end
        elseif item:IsA("UIListLayout") then
            table.insert(parts,prop(item,"FillDirection")); table.insert(parts,prop(item,"Padding"))
        elseif item:IsA("UICorner") then table.insert(parts,prop(item,"CornerRadius"))
        elseif item:IsA("UIPadding") then table.insert(parts,prop(item,"PaddingLeft")); table.insert(parts,prop(item,"PaddingTop"))
        elseif item:IsA("UIScale") then table.insert(parts,prop(item,"Scale")) end
        pcall(function() local tags=item:GetTags(); if #tags>0 then table.insert(parts,"tags="..table.concat(tags," ")) end end)
        local attributes={}
        pcall(function() for key in pairs(item:GetAttributes()) do table.insert(attributes,key) end end)
        if #attributes>0 then table.insert(parts,"attrs="..table.concat(attributes,",")) end
        table.insert(lines,table.concat(parts," "))
        local ok,children=pcall(function() return item:GetChildren() end)
        for _,child in ipairs(ok and children or {}) do walk(child,depth+1) end
    end
    walk(root,0)
    return table.concat(lines,"\n")
end
-- The screens to write, when they are on screen.
function UI.dumpTargets()
    local targets={}
    local core=game:GetService("CoreGui")
    local inspect=UI.inspectRoot()
    if inspect then table.insert(targets,{"InspectPanel",inspect}) end
    local rgui=core:FindFirstChild("RobloxGui")
    local page=rgui and rgui:FindFirstChild("peoplepage",true)
    if page and UI.onScreen(page) then table.insert(targets,{"PlayersPage",page}) end
    local label=UI.ProfileName
    if label and label.Parent and UI.onScreen(label) then
        -- The profile page: the frame around your @username that also holds the row of worn items.
        local cursor=label
        for _=1,8 do
            if not cursor.Parent or cursor.Parent:IsA("LayerCollector") or (page and page:IsDescendantOf(cursor.Parent)) then break end
            cursor=cursor.Parent
        end
        table.insert(targets,{"ProfilePage",cursor})
    end
    local list=core:FindFirstChild("PlayerList")
    if list then table.insert(targets,{"Leaderboard",list}) end
    return targets
end
function UI.startDump()
    if type(writefile)~="function" then App.report("This executor can't write files.","warning"); return end
    UI.DumpUntil=os.clock()+120
    App.report("Menu dump on for 2 minutes: open the Roblox menu, your profile page and the avatar panel, and wait 3 seconds on each.","info")
    if UI.Dumping then return end
    UI.Dumping=true
    task.spawn(function()
        local written={}
        while App.alive() and os.clock()<UI.DumpUntil do
            for _,target in ipairs(UI.dumpTargets()) do
                local name,root=target[1],target[2]
                local row=written[name]
                -- Written once it has been on screen for 2 seconds (loaded), and again if it changed screens.
                if not row or row.Root~=root then written[name]={Root=root,Since=os.clock(),Done=false}
                elseif not row.Done and os.clock()-row.Since>=2 then
                    row.Done=true
                    local ok,text=pcall(UI.dumpTree,root)
                    if ok then
                        local header=string.format("Avatar Studio menu dump · %s · %s · %dx%d\n",name,os.date("!%Y-%m-%d %H:%M:%S"),workspace.CurrentCamera.ViewportSize.X,workspace.CurrentCamera.ViewportSize.Y)
                        pcall(writefile,"LyraDump_"..name..".txt",header..text)
                        App.report("Menu dump written: LyraDump_"..name..".txt","success")
                    end
                end
            end
            task.wait(0.5)
        end
        UI.Dumping=false
    end)
end
function UI.inputs()
    UI.watchMenu()
    UI.connect(UIS.InputBegan,function(input,processed)
        if UI.CapturingKey and input.UserInputType==Enum.UserInputType.Keyboard then
            UI.CapturingKey=false
            if input.KeyCode~=Enum.KeyCode.Escape and input.KeyCode~=Enum.KeyCode.Unknown then
                local reserved={L=true,R=true,K=true,W=true,A=true,S=true,D=true,Space=true,Return=true,Tab=true,Backspace=true}
                if reserved[input.KeyCode.Name] then App.report("That key is already used by the game or hub. Choose another one.","warning")
                else Store.Settings.Keybind=input.KeyCode.Name; App.persist(); UI.refreshReopenCard() end
            end
            UI.KeyButton.Label.Text=Store.Settings.Keybind; return
        end
        if processed or UIS:GetFocusedTextBox() then return end
        if input.KeyCode.Name==Store.Settings.Keybind then UI.setVisible(not UI.Visible) end
    end)
    local function chat(message)
        local normalized=message:lower():gsub("%s+","")
        local devBuild=rawget(_G,"LyraDevBuild")
        if normalized=="/lyradump" and type(devBuild)=="string" and devBuild:match("^%x+$") then UI.startDump(); return end
        if normalized=="/lyralog" and type(devBuild)=="string" and devBuild:match("^%x+$") then App.startLog(); return end
        if normalized=="/ecopier" or normalized=="/ehub" or normalized=="/copier" or normalized=="/hub" or normalized=="/edance1" or normalized=="/dance1" then
            UI.Minimized=false; UI.setVisible(true); UI.layout(false); App.report("Hub opened.","info")
            return
        end
        -- The same message can arrive through more than one chat event; act on it once.
        local command=normalized:gsub("^/e","/")
        if command~="/next" and command~="/prev" and command~="/cycle" then return end
        if UI.LastChatCommand==command and os.clock()-(UI.LastChatAt or 0)<1 then return end
        UI.LastChatCommand=command; UI.LastChatAt=os.clock()
        if command=="/next" then Auto.switchNow(1)
        elseif command=="/prev" then Auto.switchNow(-1)
        else
            Store.Auto.CycleEnabled=not Store.Auto.CycleEnabled
            Auto.DeathsSince=0; Auto.TimerStart=os.clock(); Auto.Pending=nil
            App.persist(); UI.renderAuto()
            App.report(Store.Auto.CycleEnabled and "Avatar cycle on." or "Avatar cycle off.","info")
        end
    end
    UI.connect(lp.Chatted,chat)
    pcall(function()
        local tcs=game:GetService("TextChatService")
        -- "/e copier" is handled by Roblox's emote command, so it never reaches the chat window.
        pcall(function()
            local commands=tcs:FindFirstChild("TextChatCommands")
            local emote=commands and commands:FindFirstChild("RBXEmoteCommand")
            if emote then UI.connect(emote.Triggered,function(source,text) if (not source or source.UserId==lp.UserId) and type(text)=="string" then chat(text) end end) end
        end)
        UI.connect(tcs.MessageReceived,function(message) if message.TextSource and message.TextSource.UserId==lp.UserId then chat(message.Text) end end)
        local command=UI.new("TextChatCommand",{Name="LyraCopierCommand",PrimaryAlias="/copier",SecondaryAlias="/hub"},tcs)
-- YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
        UI.ChatCommand=command
        UI.connect(command.Triggered,function(source) if not source or source.UserId==lp.UserId then chat("/copier") end end)
    end)
end

-- Discord invite: at most two ever. The first plays 5 minutes into a session of this version; the second
-- 1 minute into the 10th run counted from that first one. Without saved data the counts would reset every
-- run, so it never plays then. It respects the Show notifications and Copy the Discord invite settings.
function UI.schedulePromo()
    if type(writefile)~="function" or Store.ReadOnly or not Store.Settings.CopyDiscord then return end
    local promo=Store.Promo
    if promo.Shown>=2 then return end
    promo.Runs=math.min(promo.Runs+1,1000)
    if not App.persist() then return end
    local second=promo.Shown==1
    if second and (promo.Runs<10 or promo.Runs<=promo.FirstAt) then return end
    task.delay(second and 60 or 300,function()
        if not App.alive() or not Store.Settings.Notifications or not Store.Settings.CopyDiscord or not UI.Toasts then return end
        promo.Shown=promo.Shown+1
        if promo.Shown==1 then promo.FirstAt=promo.Runs end
        App.persist()
        local function join()
            local copy=type(setclipboard)=="function" and setclipboard or type(toclipboard)=="function" and toclipboard or nil
            if copy and pcall(copy,App.Creator.Discord) then App.report("Discord invite copied. Paste it in your browser to join.","success"); return end
            UI.Minimized=false; UI.setVisible(true); UI.layout(false); UI.selectTab("Creator")
        end
        -- It closes only when its timer runs out or the invite is copied, never on a stray tap.
        UI.Toasts:Notify({Featured=true,Dismissible=false,Kind="info",Image=UI.LogoImage,Icon="discord",Duration=15,
            Title=second and "You're one of the regulars!" or "Enjoying Avatar Studio?",
            Text=second and "Join the Lyra Discord: new features land there first, plus requests, sneak peeks and help."
                or "Join the Lyra Discord to get updates first, request features and get help fast.",
            Action={Text="Join the Discord",Callback=join}})
    end)
end

-- SKIN OVERLAY: draws an avatar over a character without changing the character. The avatar is a separate local
-- model that follows the character every frame, so the game's rig, joints, animations and movement stay exactly as
-- they were. Used for other script users' skins (skin sync) and for the visual-only mode.
-- Two ways to follow, chosen per character:
--   joints: the character has the standard joints. The overlay keeps its own proportions; its root follows the
--           character's root (lifted by the difference in standing height) and every joint copies the matching
--           joint's animation Transform.
--   parts:  anything else (custom rigs). Each overlay body part is placed on the visible part with the same name.
Overlay.EvadeGame = 3647333358
-- Games where the avatar always goes on the character itself: Jujutsu Shenanigans animates its R6 body its own way and
-- rebuilds your items, so an avatar drawn over it followed its moves only roughly. There the R6 body wears it (an R15
-- skin is rebuilt for R6), whatever Visual-only says. Muscle Legends resizes your body as you train, which an avatar
-- drawn over it did not follow.
Overlay.BodyGames = {[3508322461] = true, [1268927906] = true}
-- Overlay.Auto: on for this game in this session when an avatar that only shows right on R15 went on an R6 character
-- (see R15 AVATARS IN R6 GAMES).
function Overlay.visualOnly()
    if Overlay.BodyGames[game.GameId] then return false end
    return Store.Settings.VisualOnly == true or game.GameId == Overlay.EvadeGame or Overlay.Auto == true
end
-- The folder lives in the camera (local only, and out of reach of game scripts that look for characters in
-- workspace). It follows the current camera, and a removed overlay is rebuilt from its spare copy (Overlay.revive).
-- A game that keeps clearing the camera (three losses in ten seconds) gets the folder in workspace instead.
Overlay.FolderLosses = {}
function Overlay.folder()
    local parent = Overlay.InWorkspace and workspace or workspace.CurrentCamera or workspace
    local folder = Overlay.Folder
    if folder then
        local moved = pcall(function() if folder.Parent ~= parent then folder.Parent = parent end end)
        if moved and folder.Parent == parent then return folder end
        local now = os.clock()
        table.insert(Overlay.FolderLosses, now)
        while #Overlay.FolderLosses > 0 and now - Overlay.FolderLosses[1] > 10 do table.remove(Overlay.FolderLosses, 1) end
        if #Overlay.FolderLosses >= 3 and not Overlay.InWorkspace then Overlay.InWorkspace = true; parent = workspace end
    end
    folder = Instance.new("Folder"); folder.Name = "LyraSkinOverlays"; folder.Parent = parent
    Overlay.Folder = folder
    return folder
end
-- The part a character moves by: its HumanoidRootPart, else its PrimaryPart, else a torso or head. Games with their
-- own movement (Evade) do not always give the character a Humanoid or a standard root.
function Overlay.rootOf(character)
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if root and root:IsA("BasePart") then return root end
    local primary = character and character.PrimaryPart
    if primary then return primary end
    for _, name in ipairs({"Root", "RootPart", "Torso", "UpperTorso", "Head"}) do
        local part = character and character:FindFirstChild(name)
        if part and part:IsA("BasePart") then return part end
    end
    return character and character:FindFirstChildWhichIsA("BasePart") or nil
end
-- WORLD SCAN: models anywhere in the world are found by one shared scan that visits a few hundred instances every
-- frame (workspace and the camera, four folders or models deep), never all at once: searching the whole map every
-- few seconds froze big games (city and driving maps) for a moment each time. It notes models named after a player
-- (a game's separate render model) and models whose body stands where your character is.
Overlay.Scanner = {Found = {}, Named = {}, Done = -math.huge, Passes = 0}
-- A root, torso or head part of the model within a few studs of origin: that distance, else nil.
function Overlay.nearBody(model, origin)
    local near
    for _, name in ipairs({"HumanoidRootPart", "Torso", "UpperTorso", "LowerTorso", "Head"}) do
        local part = model:FindFirstChild(name)
        if part and part:IsA("BasePart") then
            local distance = (part.Position - origin).Magnitude
            if distance < 3.5 and (not near or distance < near) then near = distance end
        end
    end
    return near
end
function Overlay.scanStep(budget)
    local scan = Overlay.Scanner
    if not scan.Stack then
        if os.clock() - scan.Done < 2 then return end
        scan.Stack, scan.PassFound, scan.PassNamed, scan.Names, scan.Skip, scan.PassLights = {}, {}, {}, {}, {}, {}
        for _, player in ipairs(Players:GetPlayers()) do
            scan.Names[player.Name] = true
            if player.Character then scan.Skip[player.Character] = true end
        end
        local root = lp.Character and Overlay.rootOf(lp.Character)
        scan.Origin = root and root.Position or nil
        for _, container in ipairs({workspace, workspace.CurrentCamera}) do
            local ok, list = pcall(function() return container:GetChildren() end)
            if ok then table.insert(scan.Stack, {list, 1, 1}) end
        end
    end
    local stack = scan.Stack
    while budget > 0 and #stack > 0 do
        local top = stack[#stack]
        local child = top[1][top[2]]
        if child == nil then
            table.remove(stack)
        else
            -- The index moves on first, so an instance that errors is skipped next time instead of blocking the scan.
            top[2] = top[2] + 1; budget = budget - 1
            local depth = top[3]
            local isModel = child:IsA("Model")
            -- A highlight kept outside a character can still light it (see GAME HIGHLIGHTS).
            if child:IsA("Highlight") then table.insert(scan.PassLights, child) end
            if (isModel or child:IsA("Folder")) and child ~= Overlay.Folder and not scan.Skip[child] then
                if isModel then
                    if depth <= 3 and scan.Names[child.Name] then
                        local list = scan.PassNamed[child.Name]
                        if not list then list = {}; scan.PassNamed[child.Name] = list end
                        table.insert(list, child)
                    end
                    if scan.Origin then
                        local ok, near = pcall(Overlay.nearBody, child, scan.Origin)
                        if ok and near then table.insert(scan.PassFound, child) end
                    end
                end
                if depth < 4 then
                    local ok, list = pcall(function() return child:GetChildren() end)
                    if ok and #list > 0 then table.insert(stack, {list, 1, depth + 1}) end
                end
            end
        end
    end
    if #stack == 0 then
        scan.Found, scan.Named, scan.Lights = scan.PassFound, scan.PassNamed, scan.PassLights
        scan.Stack, scan.PassFound, scan.PassNamed, scan.Skip, scan.PassLights = nil, nil, nil, nil, nil
        scan.Done = os.clock(); scan.Passes = scan.Passes + 1
    end
end
-- The first look happens at once (the avatar is being applied, a short wait is expected then); later ones spread out.
function Overlay.scanReady()
    for _ = 1, 3 do
        if Overlay.Scanner.Passes > 0 then return end
        pcall(Overlay.scanStep, math.huge)
    end
end
-- Some games draw the visible body as a separate model named after the player (Evade keeps one per player). It is
-- looked for where games keep it (up to three folders deep in workspace). Returns the model and whether a joint links
-- it to the character's root (otherwise it was found only because its visible body stands where the character is).
function Overlay.renderRig(character)
    local root = Overlay.rootOf(character)
    local player = Players:GetPlayerFromCharacter(character)
    if not root or not player then return nil end
    local function check(model)
        if not model or model == character or not model:IsA("Model") or model:IsDescendantOf(character)
            or (Overlay.Folder and model:IsDescendantOf(Overlay.Folder)) then return nil end
        for _, item in ipairs(model:GetDescendants()) do
            if item:IsA("JointInstance") or item:IsA("WeldConstraint") then
                local ok, linked = pcall(function() return item.Part0 == root or item.Part1 == root end)
                if ok and linked then return model, true end
            end
        end
        for _, item in ipairs(root:GetChildren()) do
            if item:IsA("JointInstance") or item:IsA("WeldConstraint") then
                local ok, linked = pcall(function() return (item.Part0 ~= nil and item.Part0:IsDescendantOf(model)) or (item.Part1 ~= nil and item.Part1:IsDescendantOf(model)) end)
                if ok and linked then return model, true end
            end
        end
        local near = 0
        for _, item in ipairs(model:GetDescendants()) do
            if item:IsA("BasePart") and S.BD[item.Name] and item.Name ~= "HumanoidRootPart" and item.Transparency < 1
                and not item:FindFirstAncestorOfClass("Tool") and (item.Position - root.Position).Magnitude < 8 then
                near = near + 1
                if near >= 3 then return model, false end
            end
        end
        return nil
    end
    local found, linked = check(workspace:FindFirstChild(player.Name))
    if found then return found, linked end
    for _, model in ipairs(Overlay.Scanner.Named[player.Name] or {}) do
        if model.Parent then
            found, linked = check(model)
            if found then return found, linked end
        end
    end
    return nil
end
-- Other models drawing your body where you stand. A game can keep the visible body on a separate model with any name,
-- in workspace or only on your screen in the camera (Evade switches to one once a cosmetic or skin was equipped). A
-- model counts when a root, torso or head part of it is within a few studs of your character's root and it shows at
-- least three body parts; other players' characters never count. A spatial query finds most of them; deep adds what
-- the world scan found (parts that spatial queries skip) and the camera. Nearest first.
-- entry: the overlay hiding them, so a body it already hid still counts.
function Overlay.bodies(character, deep, entry)
    local root = Overlay.rootOf(character)
    if not root then return {} end
    local origin = root.Position
    local others = {}
    for _, player in ipairs(Players:GetPlayers()) do
        local other = player.Character
        if other and other ~= character then others[other] = true end
    end
    local function inOther(model)
        local cursor = model
        while cursor and cursor ~= workspace do
            if others[cursor] then return true end
            cursor = cursor.Parent
        end
        return false
    end
    local seen, rows = {}, {}
    local check
    -- One odd model never stops the search for the others.
    local function consider(model, inside)
        if seen[model] then return end
        seen[model] = true
        pcall(check, model, inside)
    end
    check = function(model, inside)
        if model == character or (not inside and model:IsDescendantOf(character)) or (Overlay.Folder and model:IsDescendantOf(Overlay.Folder)) or inOther(model) then return end
        -- A copy the stand-ins dressed in your avatar stays theirs (see Mirror.eligible).
        if Mirror.Dressed[model] then return end
        local near = Overlay.nearBody(model, origin)
        if not near then return end
        local visible = 0
        for _, item in ipairs(model:GetDescendants()) do
            -- Only parts where you stand count (see FAR BODIES).
            if item:IsA("BasePart") and S.BD[item.Name] and item.Name ~= "HumanoidRootPart" and not item:FindFirstAncestorOfClass("Tool")
                and (item.Position - origin).Magnitude <= 12 and (entry and Overlay.original(entry, item) or item.Transparency) < 1 then
                visible = visible + 1
                if visible >= 3 then table.insert(rows, {Model = model, Distance = near}); return end
            end
        end
    end
    -- A body drawn by a model nested inside the character itself (first, so it is judged as such).
    for _, item in ipairs(character:GetDescendants()) do
        if item:IsA("Model") and not item:FindFirstAncestorOfClass("Tool") then consider(item, true) end
    end
    pcall(function()
        local params = OverlapParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = Overlay.Folder and {character, Overlay.Folder} or {character}
        for _, part in ipairs(workspace:GetPartBoundsInRadius(origin, 4, params)) do
            if S.BD[part.Name] then
                local model = part:FindFirstAncestorOfClass("Model")
                if model then consider(model) end
            end
        end
    end)
    if deep then
        Overlay.scanReady()
        for _, model in ipairs(Overlay.Scanner.Found) do if model.Parent then consider(model) end end
        -- The camera holds few things and a body there can appear at any moment: it is looked at directly.
        local camera = workspace.CurrentCamera
        for _, child in ipairs(camera and camera:GetChildren() or {}) do
            if child ~= Overlay.Folder and (child:IsA("Model") or child:IsA("Folder")) then
                if child:IsA("Model") then consider(child) end
                for _, inner in ipairs(child:GetChildren()) do if inner:IsA("Model") then consider(inner) end end
            end
        end
    end
    table.sort(rows, function(x, y) return x.Distance < y.Distance end)
    local models = {}
    for _, row in ipairs(rows) do table.insert(models, row.Model) end
    return models
end
-- Whether a model shows your body where you stand the way Overlay.bodies counts it: at least three visible body parts
-- (outside tools) within 12 studs. entry: the overlay hiding them, so a body it already hid still counts.
function Overlay.shows(model, origin, entry)
    local visible = 0
--: YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
    for _, item in ipairs(model:GetDescendants()) do
        if item:IsA("BasePart") and S.BD[item.Name] and item.Name ~= "HumanoidRootPart" and not item:FindFirstAncestorOfClass("Tool")
            and (item.Position - origin).Magnitude <= 12 and (entry and Overlay.original(entry, item) or item.Transparency) < 1 then
            visible = visible + 1
            if visible >= 3 then return true end
        end
    end
    return false
end
-- Whether a model's body is being animated: an Animator writes the joints' Transform every frame (an idle included),
-- so any joint away from its rest pose means it moves. A body moved by CFrame instead (no animated joints) counts when
-- its limbs changed pose since the last look (kept per overlay entry).
-- direct: only the model's own body (joints moving its direct children), not a body nested inside it.
function Overlay.animated(model, entry, direct)
    for _, item in ipairs(model:GetDescendants()) do
        local joint = (item:IsA("Motor6D") or item:IsA("AnimationConstraint")) and not item:FindFirstAncestorOfClass("Tool")
        if joint and direct then
            local ok, _, part1 = pcall(Overlay.jointInfo, item)
            joint = ok and part1 ~= nil and part1.Parent == model
        end
        if joint then
            local ok, moving = pcall(function()
                local t = item.Transform
                return t.Position.Magnitude > 1e-3 or t.LookVector.Z > -0.99999 or t.UpVector.Y < 0.99999
            end)
            if ok and moving then return true end
        end
    end
    if not entry then return false end
    local torso = model:FindFirstChild("Torso") or model:FindFirstChild("UpperTorso")
    if not (torso and torso:IsA("BasePart")) then return false end
    local key = 0
    for index, name in ipairs({"Left Arm", "Right Arm", "Left Leg", "Right Leg", "LeftUpperArm", "RightUpperArm", "LeftUpperLeg", "RightUpperLeg"}) do
        local part = model:FindFirstChild(name)
        if part and part:IsA("BasePart") then
            local ok, value = pcall(function()
                local relative = torso.CFrame:ToObjectSpace(part.CFrame)
                return relative.LookVector.Y * index + relative.UpVector.Z * index * 3
            end)
            if ok then key = key + value end
        end
    end
    entry.Poses = entry.Poses or setmetatable({}, {__mode = "k"})
    local last = entry.Poses[model]
    entry.Poses[model] = key
    return last ~= nil and math.abs(last - key) > 1e-3
end
-- The body to follow: the render model when a joint links it to the character. Otherwise the body the game animates:
-- when one copy of your body moves while the other stands still, the moving one (Evade animates its separate body,
-- not the character, once a cosmetic or skin was equipped). Otherwise by what you see: the character while its own body
-- shows, else the copy followed so far, the render model, or the nearest body drawn where the character stands.
function Overlay.target(character, extras)
    local rig, linked = Overlay.renderRig(character)
    if rig and linked then return rig end
    local entry = Overlay.Active[character]
    local candidates = {}
    if rig then table.insert(candidates, rig) end
    for _, model in ipairs(extras or {}) do if model ~= rig then table.insert(candidates, model) end end
    if #candidates == 0 then return character end
    local own = Overlay.animated(character, entry, true)
    local moving
    for _, model in ipairs(candidates) do
        if Overlay.animated(model, entry) then moving = moving or model end
    end
    if own and not moving then return character end
    if moving and not own then return moving end
    for _, part in ipairs(character:GetChildren()) do
        if part:IsA("BasePart") and S.BD[part.Name] and part.Name ~= "HumanoidRootPart" then
            local transparency = entry and Overlay.original(entry, part) or part.Transparency
            if transparency < 1 then return character end
        end
    end
    if entry and entry.Target and entry.Target ~= character and table.find(candidates, entry.Target) then return entry.Target end
    return candidates[1]
end
-- The rig the overlay is built as: the one the visible (animated) body uses.
function Overlay.rigType(character)
    local root = Overlay.rootOf(character)
    local extras = root and Players:GetPlayerFromCharacter(character) == lp and Overlay.bodies(character, true) or nil
    return F.getTrueRigType(Overlay.target(character, extras)) or F.getTrueRigType(character)
end
-- Height of the root's centre above the feet when standing (Roblox's HipHeight rule for R15 and R6).
function Overlay.standHeight(model)
    local hum = model:FindFirstChildOfClass("Humanoid")
    local root = model:FindFirstChild("HumanoidRootPart")
    if not hum or not root or not root:IsA("BasePart") then return nil end
    local height = hum.HipHeight + root.Size.Y / 2
    if F.getTrueRigType(model) == Enum.HumanoidRigType.R6 then
        local leg = model:FindFirstChild("Left Leg")
        height = height + (leg and leg:IsA("BasePart") and leg.Size.Y or 2)
    end
    return height
end
-- Turns a built avatar model into a puppet: no physics, no animator of its own, root anchored.
-- Height of the root's centre above the lowest point of the body in the rest pose, measured on the real geometry.
-- Roblox's HipHeight for an avatar does not always match its legs (Korblox, for example), which made skins hover.
function Overlay.restHeight(model)
    local root = model:FindFirstChild("HumanoidRootPart")
    if not root or not root:IsA("BasePart") then return nil end
    local lowest
    for _, part in ipairs(model:GetChildren()) do
        if part:IsA("BasePart") and part ~= root and Appearance.isBody(part, model) then
            local cf, half = part.CFrame, part.Size / 2
            for _, x in ipairs({-1, 1}) do
                for _, y in ipairs({-1, 1}) do
                    for _, z in ipairs({-1, 1}) do
                        local point = cf * Vector3.new(half.X * x, half.Y * y, half.Z * z)
                        if not lowest or point.Y < lowest then lowest = point.Y end
                    end
                end
            end
        end
    end
    return lowest and root.Position.Y - lowest or nil
end
function Overlay.prepare(model)
    local hum = model:FindFirstChildOfClass("Humanoid")
    -- Off before the model enters the world: a live Humanoid turns its head/torso collisions back on.
    if hum then pcall(function() hum.EvaluateStateMachine = false end) end
    UI.preparePreview(model, Overlay.folder())
    model.Name = "LyraSkinOverlay"
    -- Measured now, while the model is still in its rest pose (preparePreview just posed it from its joints).
    local stand = Overlay.restHeight(model)
    if stand then model:SetAttribute("LyraStandHeight", stand) end
    -- Rest pose of every part relative to the root, for drawing this avatar on a body of the other rig type.
    local restRoot = model:FindFirstChild("HumanoidRootPart")
    if restRoot then
        for _, part in ipairs(model:GetChildren()) do
            if part:IsA("BasePart") then part:SetAttribute("LyraRest", restRoot.CFrame:ToObjectSpace(part.CFrame)) end
        end
    end
    pcall(function()
        hum.EvaluateStateMachine = false
        hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
        hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
        hum.RequiresNeck = false; hum.BreakJointsOnDeath = false
    end)
    -- Only the copied joint transforms may move the overlay's joints.
    for _, item in ipairs(model:GetDescendants()) do
        if item:IsA("Animator") then item:Destroy()
        elseif item:IsA("BasePart") then item.Massless = true end
    end
end
function Overlay.setMode(entry, mode)
    if entry.Mode == mode and (mode ~= "puppet" or (entry.Puppet and entry.Puppet.Model == entry.Model)) then return end
    if entry.Puppet then Overlay.puppetStop(entry) end
    entry.Mode = mode; entry.Limbs = nil; entry.ArmBlend = 0; entry.BodyBlend = 0
    local model = entry.Model
    for _, item in ipairs(model:GetDescendants()) do
        if item:IsA("Motor6D") or item:IsA("AnimationConstraint") then
            item.Enabled = mode ~= "parts"
            pcall(function() item.Transform = CFrame.new() end)
        end
    end
    for _, part in ipairs(model:GetChildren()) do
        if part:IsA("BasePart") and (part.Name == "HumanoidRootPart" or Appearance.isBody(part, model)) then
            part.Anchored = mode == "parts" or part.Name == "HumanoidRootPart"
        end
    end
    if mode == "puppet" then Overlay.puppetStart(entry) end
end
function Overlay.build(data, rig)
    local desc = Codec.decode(data)
    local built, model = pcall(Visual.model, data, desc, rig); desc:Destroy()
    assert(built and model, tostring(model))
    Overlay.prepare(model)
    return model
end
function Overlay.showLocal(character, source)
    local model = source:Clone(); assert(model, "Could not prepare the avatar.")
    -- Read now, while the avatar is being applied and waiting is fine: the animations a puppet would play, and the
    -- mood of a dynamic head.
    local set, pack = Overlay.animationSet(model)
    local mood = Overlay.moodSet(model, character)
    Overlay.prepare(model)
    Overlay.attach(character, model, true, "local", {AnimSet = set, Pack = pack, Mood = mood})
end
-- MOOD: a dynamic head's face moves with a mood animation (a smile, a frown) that Animate plays on your character.
-- The avatar drawn over your character plays its own: the avatar's mood, else the one your character's Animate has
-- (Roblox's default), so its face is never left blank. Yields; nil for a head without face controls.
function Overlay.moodSet(model, character)
    local head = model:FindFirstChild("Head")
    if not (head and head:FindFirstChildOfClass("FaceControls")) then return nil end
    local hum = model:FindFirstChildOfClass("Humanoid")
    local desc = hum and hum:FindFirstChildOfClass("HumanoidDescription")
    local ok, assetId = pcall(function() return desc and desc.MoodAnimation end)
    if ok and tonumber(assetId) and tonumber(assetId) ~= 0 then
        local sets = F.animationSets(assetId)
        if sets and sets.mood and #sets.mood > 0 then return sets.mood end
        local one = F.resolveAnimationTrackId(assetId)
        if one then return {{Id = one}} end
    end
    local animate = character and character:FindFirstChild("Animate")
    local folder = animate and F.animateFolder(animate, "mood")
    local list = {}
    for _, child in ipairs(folder and folder:GetDescendants() or {}) do
        if child:IsA("Animation") and child.AnimationId ~= "" then table.insert(list, {Id = child.AnimationId}) end
    end
    return #list > 0 and list or nil
end
-- Keeps the mood playing on the drawn avatar (started again if the model was rebuilt or its animator went).
function Overlay.playMood(entry)
    local model = entry.Model
    local track = entry.MoodTrack
    if track and entry.MoodModel == model and track.IsPlaying and entry.MoodAnimator and entry.MoodAnimator.Parent then return end
    local controller = model:FindFirstChildOfClass("Humanoid") or model:FindFirstChildOfClass("AnimationController")
    if not controller then controller = Instance.new("AnimationController"); controller.Parent = model end
    local animator = controller:FindFirstChildOfClass("Animator")
    if not animator then animator = Instance.new("Animator"); animator.Parent = controller end
    local row = entry.Mood[Overlay.pickVariant(entry.Mood)] or entry.Mood[1]
    local animation = Instance.new("Animation"); animation.AnimationId = F.normalizeAnimId(row.Id)
    local loaded = animator:LoadAnimation(animation)
    loaded.Priority = Enum.AnimationPriority.Core; loaded.Looped = true
    loaded:Play(0.3)
    entry.MoodTrack, entry.MoodModel, entry.MoodAnimator = loaded, model, animator
end
-- PUPPET: an overlay of the other rig type (an R6 avatar drawn on an R15 character, or the other way round) cannot copy
-- the character's joints: following the limbs one by one warped it. Then the overlay animates itself the way
-- Roblox's Animate script does: idle, walk and run (blended by speed), jump, fall, climb, swim and sit follow the
-- character's Humanoid (or the root's motion when there is none), and a held tool raises the arm. What the character
-- carries is drawn on it (see CARRIED ITEMS). On the same rig the overlay always copies the joints: an avatar's own
-- animations are played by the character itself then (see App.visualAnimations), so the hidden body and the overlay
-- move together, and what the body carries is drawn on the overlay's hands and back.
Overlay.PuppetDefaults = {
    R15 = {idle = {{Id = 507766388, Weight = 9}, {Id = 507766666, Weight = 1}}, walk = {{Id = 507777826}}, run = {{Id = 507767714}},
        jump = {{Id = 507765000}}, fall = {{Id = 507767968}}, climb = {{Id = 507765644}}, swim = {{Id = 507784897}},
        swimidle = {{Id = 507785072}}, sit = {{Id = 2506281703}}, toolnone = {{Id = 507768375}}},
    R6 = {idle = {{Id = 180435571, Weight = 9}, {Id = 180435792, Weight = 1}}, walk = {{Id = 180426354}}, run = {{Id = 180426354}},
        jump = {{Id = 125750702}}, fall = {{Id = 180436148}}, climb = {{Id = 180436334}}, sit = {{Id = 178130996}}, toolnone = {{Id = 182393478}}},
}
Overlay.PuppetLooped = {idle = true, walk = true, run = true, fall = true, climb = true, swim = true, swimidle = true, sit = true, toolnone = true}
-- Yields. The animations a puppet of this model plays: Roblox's defaults for its rig and, with Copy animations on,
-- the avatar's own animation pack (packs are R15 animations). Returns the set and whether a pack is in it.
function Overlay.animationSet(model)
    local rig = F.getTrueRigType(model) == Enum.HumanoidRigType.R6 and "R6" or "R15"
    local set, pack = {}, false
    for name, list in pairs(Overlay.PuppetDefaults[rig]) do set[name] = list end
    if rig ~= "R15" or not Store.Settings.CopyAnims then return set, pack end
    local hum = model:FindFirstChildOfClass("Humanoid")
    local desc = hum and hum:FindFirstChildOfClass("HumanoidDescription")
    if not desc then return set, pack end
    local map = {IdleAnimation = {"idle"}, WalkAnimation = {"walk"}, RunAnimation = {"run"}, JumpAnimation = {"jump"},
        FallAnimation = {"fall"}, ClimbAnimation = {"climb"}, SwimAnimation = {"swim", "swimidle"}}
    for field, names in pairs(map) do
        local ok, assetId = pcall(function() return desc[field] end)
        if ok and tonumber(assetId) and tonumber(assetId) ~= 0 then
            local sets = F.animationSets(assetId)
            if sets then
                for _, name in ipairs(names) do
                    local list = sets[name]
                    if list and #list > 0 then set[name] = list; pack = true end
-- v=YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
                end
            else
                local one = F.resolveAnimationTrackId(assetId)
                if one then set[names[1]] = {{Id = one}}; pack = true end
            end
        end
    end
    return set, pack
end
-- Whether this overlay should animate itself on this body: only when it is of the other rig type.
function Overlay.wantsPuppet(entry, target)
    if not entry.Local or not entry.AnimSet then return false end
    if entry.Stiff and target == entry.Character then return true end
    local own, real = F.getTrueRigType(entry.Model), F.getTrueRigType(target)
    return own ~= nil and real ~= nil and own ~= real
end
-- STIFF BODY: the avatar drawn over your character copies its joints, so a character the game leaves without
-- animations (a game whose Animate stopped, or that drives the body its own way) drew a stiff avatar. Once your
-- character's limbs have not moved for a moment, your avatar animates itself as a puppet does (idle, walk, jump…,
-- with its own animation pack when Copy animations is on), and it copies the joints again once your character moves
-- its limbs again. Checked a few times a second.
-- FROZEN AVATAR: an avatar drawn by copying the joints could stand frozen on some skins while your character moved (a
-- cause not found yet). Six times a second the drawn avatar's limbs are compared with your character's: when your
-- character's limbs move and the drawn ones have not moved for a moment, the avatar is linked again; when that happens a
-- second time, this avatar follows your character's parts directly instead (as in Evade), which always moves with it.
-- A key of how the limbs sit relative to the torso: it changes whenever they move.
function Overlay.poseKey(model)
    local torso = model:FindFirstChild("UpperTorso") or model:FindFirstChild("Torso")
    if not (torso and torso:IsA("BasePart")) then return nil end
    local key, found = 0, false
    for index, name in ipairs({"LeftUpperArm", "RightUpperArm", "LeftUpperLeg", "RightUpperLeg", "LeftLowerArm", "RightLowerArm",
        "Left Arm", "Right Arm", "Left Leg", "Right Leg"}) do
        local part = model:FindFirstChild(name)
        if part and part:IsA("BasePart") then
            local relative = torso.CFrame:ToObjectSpace(part.CFrame)
            key = key + (relative.LookVector.Y + relative.UpVector.Z * 3 + relative.RightVector.Y * 5) * index
            found = true
        end
    end
    return found and key or nil
end
function Overlay.checkFollow(entry)
    if not entry.Local or entry.Mode ~= "joints" or entry.Target ~= entry.Character then entry.FrozenChecks = 0; entry.LastRealKey = nil; return end
    local real, mine = Overlay.poseKey(entry.Character), Overlay.poseKey(entry.Model)
    if not real or not mine then return end
    local realMoved = entry.LastRealKey ~= nil and math.abs(real - entry.LastRealKey) > 1e-3
    local mineMoved = entry.LastMineKey ~= nil and math.abs(mine - entry.LastMineKey) > 1e-4
    entry.LastRealKey, entry.LastMineKey = real, mine
    if mineMoved then entry.FrozenChecks = 0
    elseif realMoved then entry.FrozenChecks = (entry.FrozenChecks or 0) + 1 end
    if (entry.FrozenChecks or 0) < 9 then return end
    entry.FrozenChecks, entry.LastRealKey, entry.LastMineKey = 0, nil, nil
    entry.Refollows = (entry.Refollows or 0) + 1
    if entry.Refollows >= 2 then entry.ForceParts = true end
    App.devNote(entry.ForceParts and "Visual-only: the avatar stood frozen again, so it now follows your character's parts."
        or "Visual-only: the avatar stood frozen while your character moved; linking it again.")
    Overlay.link(entry)
end
function Overlay.watchStiff(entry)
    local character = entry.Character
    if not entry.AnimSet or entry.Target ~= character or (entry.Mode ~= "joints" and not entry.Stiff) then entry.StiffSince = nil; return end
    local hum = character:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then return end
    local ok, moving = pcall(Overlay.animated, character, entry, true)
    if not ok then return end
    local now = os.clock()
    if entry.Stiff then
        entry.MovingSince = moving and (entry.MovingSince or now) or nil
        if entry.MovingSince and now - entry.MovingSince >= 0.5 then
            entry.Stiff, entry.MovingSince = nil, nil
            Overlay.link(entry)
        end
    else
        entry.StiffSince = not moving and (entry.StiffSince or now) or nil
        if entry.StiffSince and now - entry.StiffSince >= 1.2 then
            entry.Stiff, entry.StiffSince = true, nil
            Overlay.link(entry)
        end
    end
end
function Overlay.puppetStart(entry)
    local model = entry.Model
    local puppet = {Model = model, Tracks = {}, Variant = {}, Connections = {},
        Rig = F.getTrueRigType(model) == Enum.HumanoidRigType.R6 and "R6" or "R15"}
    pcall(function()
        local controller = model:FindFirstChildOfClass("Humanoid") or model:FindFirstChildOfClass("AnimationController")
        if not controller then controller = Instance.new("AnimationController"); controller.Parent = model end
        -- One animator per controller (the mood may have made it already).
        local animator = controller:FindFirstChildOfClass("Animator")
        if not animator then animator = Instance.new("Animator"); animator.Parent = controller end
        puppet.Animator = animator
    end)
    -- Roblox's Animate reads the speed from Humanoid.Running (relative to the floor, so a moving platform is not a walk).
    local hum = entry.Character:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function() table.insert(puppet.Connections, hum.Running:Connect(function(speed) puppet.Speed = speed end)) end)
    end
    entry.Puppet = puppet
end
function Overlay.puppetStop(entry)
    local puppet = entry.Puppet; entry.Puppet = nil
    if not puppet then return end
    for _, connection in ipairs(puppet.Connections) do connection:Disconnect() end
    for _, track in pairs(puppet.Tracks) do if track then pcall(function() track:Stop(0); track:Destroy() end) end end
    if puppet.Animator then pcall(function() puppet.Animator:Destroy() end) end
end
-- What the character is doing: a state name and a speed.
function Overlay.puppetState(entry)
    local puppet = entry.Puppet
    local character = entry.Character
    local hum = character:FindFirstChildOfClass("Humanoid")
    local root = entry.RealRoot
    local velocity = Vector3.zero
    if root and root.Parent then pcall(function() velocity = root.AssemblyLinearVelocity end) end
    local flat = Vector3.new(velocity.X, 0, velocity.Z).Magnitude
    if hum then
        local T = Enum.HumanoidStateType
        local ok, state = pcall(function() return hum:GetState() end)
        if not ok or hum.Health <= 0 then return "idle", 0 end
        if hum.Sit or state == T.Seated then return "sit", 0 end
        if state == T.Jumping then return "jump", 0 end
        if state == T.Freefall or state == T.FallingDown or state == T.Ragdoll or state == T.Physics then return "fall", 0 end
        if state == T.Climbing then return "climb", velocity.Y end
        if state == T.Swimming then return flat > 1 and "swim" or "swimidle", flat end
        local speed = puppet.Speed
        if type(speed) ~= "number" then speed = hum.MoveDirection.Magnitude > 0.01 and flat or 0 end
        return speed > (puppet.Rig == "R6" and 0.01 or 0.75) and "walk" or "idle", speed
    end
    if velocity.Y > 6 then return "jump", 0 elseif velocity.Y < -10 then return "fall", 0 end
    return flat > 0.75 and "walk" or "idle", flat
end
function Overlay.pickVariant(list)
    local total = 0
    for _, row in ipairs(list) do total = total + (tonumber(row.Weight) or 1) end
    local roll = math.random() * total
    for index, row in ipairs(list) do
        roll = roll - (tonumber(row.Weight) or 1)
        if roll <= 0 then return index end
    end
    return 1
end
function Overlay.puppetTrack(entry, name, index)
    local puppet = entry.Puppet
    local row = entry.AnimSet[name] and entry.AnimSet[name][index]
    if not row or not puppet.Animator then return nil end
    local key = name .. "#" .. index
    local track = puppet.Tracks[key]
    if track == nil then
        local ok, loaded = pcall(function()
            local animation = Instance.new("Animation")
            animation.AnimationId = F.normalizeAnimId(row.Id)
            local made = puppet.Animator:LoadAnimation(animation)
            made.Priority = name == "toolnone" and Enum.AnimationPriority.Idle or Enum.AnimationPriority.Core
            made.Looped = Overlay.PuppetLooped[name] == true
            return made
        end)
        track = ok and loaded or false
        puppet.Tracks[key] = track
    end
    return track or nil
end
-- One frame of the puppet: the locomotion it should play.
function Overlay.puppetStep(entry)
    local puppet = entry.Puppet
    if not puppet or not puppet.Animator or not puppet.Animator.Parent then return end
    -- A loose body, or one the game moves with its own walk and idle, is followed limb by limb, not animated (see
    -- RAGDOLL and GAME MOVES).
    if entry.Loose or entry.GameMoves then
        for _, track in pairs(puppet.Tracks) do
            if track and track.IsPlaying then pcall(function() track:Stop(0.2) end) end
        end
        return
    end
    local state, speed = Overlay.puppetState(entry)
    -- The jump plays for a moment before the fall takes over, as in Roblox's Animate.
    if state == "jump" then puppet.JumpAt = os.clock()
    elseif state == "fall" and puppet.JumpAt and os.clock() - puppet.JumpAt < 0.31 then state = "jump" end
    local wanted = {}
    local function want(name, weight, rate)
        local list = entry.AnimSet[name]
        if not list or #list == 0 then return false end
        local index = puppet.Variant[name]
        if not index or not list[index] then index = Overlay.pickVariant(list); puppet.Variant[name] = index end
        wanted[name .. "#" .. index] = {name, index, weight, rate}
        return true
    end
    if state == "walk" then
        if puppet.Rig == "R15" then
            -- Roblox's R15 walk/run blend: walk up to half the reference speed, both in between, run above.
            local run = speed / 16
            local walkWeight, runWeight, walkRate, runRate = 0.001, 0.001, run / 0.5, run
            if run <= 0.5 then walkWeight = 1
            elseif run < 1 then local blend = (run - 0.5) / 0.5; walkWeight = 1 - blend; runWeight = blend; walkRate = 1; runRate = 1
            else runWeight = 1 end
            want("walk", walkWeight, math.clamp(walkRate, 0.05, 4))
            want("run", runWeight, math.clamp(runRate, 0.05, 4))
        else
            want("walk", 1, math.clamp(speed / 14.5, 0.05, 4))
        end
    elseif state == "climb" then
        want("climb", 1, math.clamp(math.abs(speed) / (puppet.Rig == "R15" and 5 or 12), 0, 4))
    elseif state == "swim" then
        if not want("swim", 1, math.clamp(speed / 10, 0.05, 4)) then want("walk", 1, 1) end
    elseif state == "swimidle" then
        if not want("swimidle", 1, 1) then want("idle", 1, 1) end
    elseif not want(state, 1, 1) then
        want("idle", 1, 1)
    end
    -- The idle look-around is picked again each time the character stops.
    if state ~= "idle" then puppet.Variant.idle = nil end
    if state ~= "sit" and entry.Character:FindFirstChildOfClass("Tool") then want("toolnone", 1, 1) end
    for _, row in pairs(wanted) do
        local track = Overlay.puppetTrack(entry, row[1], row[2])
        if track then
            pcall(function()
                if not track.IsPlaying then track:Play(0.15, row[3], row[4])
                else
                    if math.abs(track.WeightTarget - row[3]) > 0.02 then track:AdjustWeight(row[3], 0.15) end
                    if math.abs(track.Speed - row[4]) > 0.02 then track:AdjustSpeed(row[4]) end
                end
            end)
        end
    end
    for key, track in pairs(puppet.Tracks) do
        if track and not wanted[key] and track.IsPlaying then pcall(function() track:Stop(0.15) end) end
    end
end
-- FOLLOWING THE BODY on a puppet: games pose your character with animations of their own (a knife or a gun raised in
-- both hands, an item carried in front, an emote, a game move), and a puppet only plays walking and standing, so it
-- held them hanging down or stood still. While your character holds a tool or an item in a hand, or the game plays an
-- animation of its own on it, the puppet's arms follow your character's arms; while the game's animation plays, its
-- legs, torso and head follow too. An R6 limb is one piece, so it points where the R15 limb points (from its top to
-- the end of its lower part, the elbow or knee bend included); an R15 limb takes the R6 limb's turn at the shoulder or
-- hip and stays straight.
Overlay.Limbs = {
    {Key = "RightArm", Arm = true, R6 = {"Torso", "Right Arm"}, R15 = {"UpperTorso", "RightUpperArm", "RightLowerArm"}},
    {Key = "LeftArm", Arm = true, R6 = {"Torso", "Left Arm"}, R15 = {"UpperTorso", "LeftUpperArm", "LeftLowerArm"}},
    {Key = "RightLeg", R6 = {"Torso", "Right Leg"}, R15 = {"LowerTorso", "RightUpperLeg", "RightLowerLeg"}},
    {Key = "LeftLeg", R6 = {"Torso", "Left Leg"}, R15 = {"LowerTorso", "LeftUpperLeg", "LeftLowerLeg"}},
    {Key = "Head", R6 = {"Torso", "Head"}, R15 = {"UpperTorso", "Head"}},
    {Key = "Torso", R6 = {"HumanoidRootPart", "Torso"}, R15 = {"HumanoidRootPart", "LowerTorso"}},
}
-- The joint that moves a part of a model (not one inside a tool), with its parts and offsets.
function Overlay.jointTo(model, partName)
    for _, joint in ipairs(model:GetDescendants()) do
        if (joint:IsA("Motor6D") or joint:IsA("AnimationConstraint")) and not joint:FindFirstAncestorOfClass("Tool") then
            local ok, p0, p1, c0, c1 = pcall(Overlay.jointInfo, joint)
            if ok and p0 and p1 and c0 and c1 and p1.Name == partName and p1:IsDescendantOf(model) then return joint, p0, p1, c0, c1 end
        end
    end
    return nil
end
-- Each puppet joint with the real parts it follows (built once per link).
function Overlay.limbRig(entry)
    local target = entry.Target or entry.Character
    local own = F.getTrueRigType(entry.Model) == Enum.HumanoidRigType.R6 and "R6" or "R15"
    local real = F.getTrueRigType(target) == Enum.HumanoidRigType.R6 and "R6" or "R15"
    local found = entry.FoundParts or {}
    local function part(name)
        if name == "HumanoidRootPart" then return entry.RealRoot end
        return Overlay.pick(entry, found[name]) or target:FindFirstChild(name)
    end
    local limbs = {}
    -- The real joint of each limb tells when the game let it loose (see RAGDOLL); only a joint seen once counts, so a
    -- character built without some joints is not taken for a ragdoll.
    entry.SeenJoints = entry.SeenJoints or {}
    for _, spec in ipairs(Overlay.Limbs) do
        local joint, _, _, c0 = Overlay.jointTo(entry.Model, spec[own][2])
        local names = spec[real]
        local limb = joint and {Joint = joint, Turn = c0 - c0.Position, Arm = spec.Arm == true, Key = spec.Key, RealName = names[2]}
        if limb then
            limb.RealJoint = Overlay.jointTo(target, names[2])
            if limb.RealJoint then entry.SeenJoints[names[2]] = true end
        end
        if limb and own == "R6" and real == "R15" and names[3] then
            -- An R6 limb points along the R15 limb, measured in the upper torso (which the R6 torso follows).
            limb.Ref, limb.Upper, limb.Lower = part("UpperTorso"), part(names[2]), part(names[3])
            if not (limb.Ref and limb.Upper and limb.Lower) then limb = nil end
        elseif limb then
            local b = (own == "R6" and real == "R15" and spec.Key == "Torso") and "UpperTorso" or names[2]
            limb.RealA, limb.RealB = part(names[1]), part(b)
            local _, realA, _, rc0, rc1 = Overlay.jointTo(target, b)
            local rest = (realA and realA == limb.RealA and rc0 and rc1) and rc0 * rc1:Inverse() or CFrame.new()
            limb.Rest = rest - rest.Position
            if not (limb.RealA and limb.RealB) then limb = nil end
        end
        if limb then table.insert(limbs, limb) end
    end
    entry.Limbs = limbs
    -- Where the avatar's root goes while the body is loose: where the real root would be if it stayed on the real
    -- torso (an R6 torso sits on its root; an R15 lower torso is offset by its root joint, remembered once read).
    local torsoName = real == "R6" and "Torso" or "LowerTorso"
    local torsoJoint, _, _, tc0, tc1 = Overlay.jointTo(target, torsoName)
    entry.AnchorShifts = entry.AnchorShifts or {}
    if torsoJoint and tc0 and tc1 then entry.AnchorShifts[torsoName] = tc1 * tc0:Inverse() end
    entry.Anchor, entry.AnchorShift = part(torsoName), entry.AnchorShifts[torsoName] or CFrame.new()
    -- The avatar's joints no limb drives (waist, elbows, knees, wrists, ankles): straight while the body is loose.
    local driven, free = {}, {}
    for _, limb in ipairs(limbs) do driven[limb.Joint] = true end
    for _, item in ipairs(entry.Model:GetDescendants()) do
        if (item:IsA("Motor6D") or item:IsA("AnimationConstraint")) and not driven[item] and not item:FindFirstAncestorOfClass("Tool") then
            table.insert(free, item)
        end
    end
    entry.FreeJoints = free
end
-- RAGDOLL: fighting games (JJS) let a knocked-down or dead character fall apart: its limbs' joints are switched off and
-- the parts swing loose. An avatar of the other rig (a puppet) kept playing its own animations on the root, so it lay
-- spread out beside the fallen body. While the body is loose, the puppet stops its animations, its torso lies on the
-- real torso and every limb points where the real one points.
function Overlay.looseJoint(joint)
    if not joint or not joint.Parent then return true end
    local ok, enabled = pcall(function() return joint.Enabled end)
    if ok and enabled == false then return true end
    local readable, p0, p1 = pcall(Overlay.jointInfo, joint)
    return not (readable and p0 and p1)
end
function Overlay.ragdolled(entry)
    local hum = entry.Character:FindFirstChildOfClass("Humanoid")
    if hum then
        if hum.Health <= 0 then return true end
        local ok, state = pcall(function() return hum:GetState() end)
        local T = Enum.HumanoidStateType
        if ok and (state == T.Physics or state == T.Ragdoll or state == T.FallingDown or state == T.Dead) then return true end
    end
    -- Two limbs let loose (a game's own ragdoll that leaves the Humanoid's state alone). Read right after a relink too,
    -- so a loose body never gets a frame of the puppet's own animation.
    if not entry.Limbs then Overlay.limbRig(entry) end
    local loose = 0
    for _, limb in ipairs(entry.Limbs or {}) do
        if limb.Key ~= "Torso" and entry.SeenJoints and entry.SeenJoints[limb.RealName] and Overlay.looseJoint(limb.RealJoint) then loose = loose + 1 end
    end
    return loose >= 2
end
-- What the game is doing with your character: holding something (a tool, an item in a hand), and whether it plays an
-- animation of its own (not Animate's).
function Overlay.posing(entry)
    local character = entry.Character
    local holding = character:FindFirstChildOfClass("Tool") ~= nil
    if not holding then
        for _, row in pairs(entry.Carried or {}) do
            local anchor = type(row) == "table" and row.Anchor
            if anchor and (anchor.Name:find("Hand$") or anchor.Name:find("Arm$")) then holding = true; break end
        end
    end
    local hum = character:FindFirstChildOfClass("Humanoid")
    local animator = hum and hum:FindFirstChildOfClass("Animator")
    local animating, own = false, false
    if animator then
        local animate = character:FindFirstChild("Animate")
        for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
            if track.WeightCurrent > 0.3 then
                if not F.isAnimateTrack(track, animate) then animating = true
                elseif Overlay.gameMove(track) then own = true end
            end
        end
    end
    -- The game's own walk, run and idle (see GAME MOVES) are followed like its other animations, held for a moment so
    -- a default track in between (a fall, a climb) doesn't flicker the puppet's own animation in.
    if own then entry.GameMovesUntil = os.clock() + 1 end
    own = os.clock() < (entry.GameMovesUntil or 0)
    entry.GameMoves = own or nil
    return holding or animating or own, animating or own
end
-- GAME MOVES: a game can put its own walk, run and idle into Animate (JJS). A puppet played Roblox's R15 defaults
-- instead, so the avatar drawn over an R6 body walked like any R15 avatar, not like the game. Animate playing an id that
-- is not one of Roblox's defaults (nor one the copier wrote from an avatar's pack) is the game's own movement: the
-- puppet then stops its own animations and follows the body, as it does for a game's moves.
function Overlay.gameMove(track)
    local ok, id = pcall(function() return F.normalizeAnimId(track.Animation.AnimationId) end)
    return ok and id ~= "" and not F.DefaultAnimIds[id] and not F.WrittenIds[id]
end
-- The shortest turn taking one direction to another.
function Overlay.arc(from, to)
    local dot = math.clamp(from:Dot(to), -1, 1)
    local axis = from:Cross(to)
    if axis.Magnitude < 1e-6 then return dot > 0 and CFrame.new() or CFrame.fromAxisAngle(Vector3.new(1, 0, 0), math.pi) end
    return CFrame.fromAxisAngle(axis.Unit, math.acos(dot))
end
-- The puppet joint's Transform for one limb: the turn the real limb has from its rest, in its parent part's axes, put
-- into the puppet joint's own axes. Nil when the real limb can't be read this frame.
function Overlay.limbTurn(limb)
    local delta
    if limb.Upper then
        local top = limb.Upper.CFrame * CFrame.new(0, limb.Upper.Size.Y / 2, 0)
        local bottom = limb.Lower.CFrame * CFrame.new(0, -limb.Lower.Size.Y / 2, 0)
        local direction = limb.Ref.CFrame:VectorToObjectSpace(bottom.Position - top.Position)
        if direction.Magnitude < 1e-4 then return nil end
        delta = Overlay.arc(Vector3.new(0, -1, 0), direction.Unit)
    else
        local relative = limb.RealA.CFrame:ToObjectSpace(limb.RealB.CFrame)
        delta = (relative - relative.Position) * limb.Rest:Inverse()
    end
    return limb.Turn:Inverse() * delta * limb.Turn
end
function Overlay.puppetLimbs(entry)
    local now = os.clock()
    local dt = math.clamp(now - (entry.LimbClock or now), 0, 0.1); entry.LimbClock = now
    -- Read every frame: the limbs' real joints tell when the body is let loose (see RAGDOLL).
    if not entry.Limbs then Overlay.limbRig(entry) end
    local loose = entry.Loose == true
    local arms, body = Overlay.posing(entry)
    if loose then arms, body = true, true end
    -- Eased in and out over a moment, so the limbs don't snap.
    entry.ArmBlend = math.clamp((entry.ArmBlend or 0) + (arms and dt or -dt) / 0.15, 0, 1)
    entry.BodyBlend = math.clamp((entry.BodyBlend or 0) + (body and dt or -dt) / 0.2, 0, 1)
    -- With its own animations stopped, the joints no limb drives stay straight, as an R6 limb is.
    if loose or entry.GameMoves then
        for _, joint in ipairs(entry.FreeJoints or {}) do pcall(function() joint.Transform = CFrame.new() end) end
    end
    if entry.ArmBlend <= 0 and entry.BodyBlend <= 0 then return end
    for _, limb in ipairs(entry.Limbs) do
        local parts = limb.Upper and {limb.Ref, limb.Upper, limb.Lower} or {limb.RealA, limb.RealB}
        for _, item in ipairs(parts) do if not item.Parent then entry.Limbs = nil; return end end
        if not limb.Joint.Parent then entry.Limbs = nil; return end
        local blend = limb.Arm and math.max(entry.ArmBlend, entry.BodyBlend) or entry.BodyBlend
        if loose and limb.Key == "Torso" then
            -- The root already lies on the real torso (see Overlay.place): the torso's own joint stays straight.
            limb.Joint.Transform = CFrame.new()
        elseif blend > 0 then
            local wanted = Overlay.limbTurn(limb)
            if wanted then limb.Joint.Transform = blend >= 1 and wanted or limb.Joint.Transform:Lerp(wanted, blend) end
        end
    end
end
-- CAMERA FADE: your own overlay fades exactly like your character. The camera (zooming in, first person) and
-- first-person games set LocalTransparencyModifier on the character's parts; each overlay part takes the value of
-- the real part it stands for (the body part of the same name, the matching limb on the other rig, and for an
-- accessory the body part it is worn on). A game that keeps your body visible in first person now shows the copied
-- body there, not your own; when the camera is inside the head, everything on the head stays hidden.
-- A separate body the game draws for you (Evade) is not faded by Roblox's camera, only your character is: the overlay
-- takes the value of that body's parts, so in Evade's first person the copied legs and torso show where the game shows
-- its own, and only the head and what is worn on it hide. Following your hidden character made the whole copy vanish.
function Overlay.fadeLinks(entry, found)
    local model, character = entry.Model, entry.Character
    local other = entry.Target ~= character and Overlay.bodyParts(entry, character) or found
    local function from(list) return list and Overlay.pick(entry, list) or nil end
    local function source(name)
        local part = from(found[name]) or from(other[name])
        if part then return part end
        local group = Overlay.R6Groups[name]
        if group then return from(found[group[1]]) or from(other[group[1]]) end
        for r6, names in pairs(Overlay.R6Groups) do
            if table.find(names, name) then return from(found[r6]) or from(other[r6]) end
        end
        return nil
    end
    local mounts, links = {}, {}
    local function mountOf(accessory)
        if mounts[accessory] ~= nil then return mounts[accessory] end
        local name = false
        for _, joint in ipairs(accessory:GetDescendants()) do
            if joint:IsA("JointInstance") or joint:IsA("WeldConstraint") then
                for _, part in ipairs({joint.Part0, joint.Part1}) do
                    if part and Appearance.isBody(part, model) then name = part.Name end
                end
                if name then break end
            end
        end
        mounts[accessory] = name
        return name
    end
    -- A carried copy fades with the body part its item hangs from.
    local carriedFrom = {}
    for _, row in pairs(entry.Carried or {}) do carriedFrom[row.Copy] = row.Anchor end
    for _, part in ipairs(model:GetDescendants()) do
-- cache YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
        if part:IsA("BasePart") and carriedFrom[part] then
            local decals = {}
            for _, child in ipairs(part:GetChildren()) do if child:IsA("Decal") then table.insert(decals, child) end end
            table.insert(links, {part, carriedFrom[part], carriedFrom[part].Name == "Head", nil, decals})
        elseif part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
            local body = Appearance.isBody(part, model) and part.Name or nil
            if not body then
                local accessory = part:FindFirstAncestorOfClass("Accessory")
                body = accessory and mountOf(accessory) or nil
            end
            local decals = {}
            for _, child in ipairs(part:GetChildren()) do if child:IsA("Decal") then table.insert(decals, child) end end
            table.insert(links, {part, body and source(body) or nil, body == "Head", nil, decals})
        end
    end
    entry.Fades = links
end
function Overlay.fade(entry, camera)
    local head = entry.RealHead or entry.Character:FindFirstChild("Head")
    local inside = false
    -- First person: the camera at (or just in front of) your head, or at the drawn avatar's head, which a puppet or a
    -- taller avatar holds elsewhere. Games with their own first-person camera put it a little in front of the face, and
    -- the drawn avatar's long hair then covered the whole screen.
    if camera then
        local eye = camera.CFrame.Position
        local mine = entry.Model:FindFirstChild("Head")
        if head and head.Parent and (eye - head.Position).Magnitude < 1.25 then inside = true end
        if mine and mine:IsA("BasePart") and (eye - mine.Position).Magnitude < math.max(1.25, mine.Size.Magnitude * 0.6) then inside = true end
        if entry.Character == lp.Character then
            if lp.CameraMode == Enum.CameraMode.LockFirstPerson then inside = true end
            -- First person however far the body is from the camera: a running body bobs and leans away from a camera
            -- that stays put (Evade), and the drawn avatar's hair, hats and floating items then covered the screen
            -- while running. Roblox's camera zoomed all the way in sits on its focus, and Roblox fades your own head.
            local okFocus, focus = pcall(function() return camera.Focus.Position end)
            if okFocus and camera.CameraType ~= Enum.CameraType.Scriptable and (eye - focus).Magnitude < 1 then inside = true end
            local realHead = entry.Character:FindFirstChild("Head")
            if realHead and realHead:IsA("BasePart") and realHead.LocalTransparencyModifier > 0.95 and (eye - realHead.Position).Magnitude < 4 then inside = true end
        end
    end
    entry.Inside = inside or nil
    -- The game hiding your character (an invisibility cloak) hides the drawn avatar too.
    local hiddenByGame = entry.GameFade or 0
    for _, link in ipairs(entry.Fades or {}) do
        local value = 0
        local real = link[2]
        if real and real.Parent then
            local ok, ltm = pcall(function() return real.LocalTransparencyModifier end)
            if ok and type(ltm) == "number" then value = ltm end
        end
        if hiddenByGame > 0 then value = 1 - (1 - value) * (1 - hiddenByGame) end
        if inside and link[3] then value = 1 end
        if link[4] ~= value then
            link[4] = value
            pcall(function() link[1].LocalTransparencyModifier = value end)
            for _, decal in ipairs(link[5]) do pcall(function() decal.LocalTransparencyModifier = value end) end
        end
    end
end
-- CARRIED ITEMS: what your character carries (a held tool, a gun in its holster, a knife on the back) would stay on
-- your hidden body: on a puppet it moved with that body's own animations, and on an avatar of the same rig, whose
-- proportions differ, it floated off the drawn hand or sank into the drawn body. Those parts are hidden there and
-- drawn on the overlay instead, each at the same place relative to the attachment it sits at (the hand's grip, the
-- back), found on the overlay by name, else relative to the matching body part. A part that leaves the character (a
-- tool put away or dropped) is shown again as the game had it.
-- Parts joined to the body that are not body parts or worn accessories, with the body part each one hangs from.
function Overlay.carriedParts(entry)
    local character = entry.Character
    local reached = {}
    for _, part in ipairs(character:GetChildren()) do
        if Appearance.isBody(part, character) then reached[part] = part end
    end
    local links = Rig.links(character)
    for _ = 1, #links + 1 do
        local changed = false
        for _, link in ipairs(links) do
            local a, b = link.A, link.B
            if reached[a] and not reached[b] then reached[b] = reached[a]; changed = true
            elseif reached[b] and not reached[a] then reached[a] = reached[b]; changed = true end
        end
        if not changed then break end
    end
    local carried = {}
    for part, anchor in pairs(reached) do
        local accessory = part:FindFirstAncestorOfClass("Accessory")
        if not Appearance.isBody(part, character) and (not accessory or Overlay.keptItem(entry, accessory)) and not part:GetAttribute("Lyra_VisualFor")
            and Overlay.original(entry, part) < 1 then
            carried[part] = anchor
        end
    end
    return carried
end
-- An item of the game on a character that Settings keeps (see THE GAME'S CLOTHES AND ITEMS): your drawn avatar
-- carries it like a held tool instead of hiding it; on a script user's drawn skin it stays where the game put it.
function Overlay.keptItem(entry, accessory)
    return accessory:IsDescendantOf(entry.Character) and Appearance.keepsItem(entry.Character, accessory)
end
-- The game's clothes on a drawn avatar (yours, or a script user's synced skin): with Keep the game's clothes on, each
-- Shirt, Pants or T-shirt the game put on the character replaces the drawn avatar's own of that kind, which comes back
-- when the game takes its piece off.
Overlay.ClothingProps = {Shirt = "ShirtTemplate", Pants = "PantsTemplate", ShirtGraphic = "Graphic"}
function Overlay.dressGame(entry)
    local model, character = entry.Model, entry.Character
    if entry.ClothesFor ~= model then entry.ClothesFor, entry.OwnClothes, entry.GameClothes = model, {}, {} end
    local wanted = {}
    if Store.Settings.KeepGameClothes then
        for _, item in ipairs(character:GetChildren()) do
            if Overlay.ClothingProps[item.ClassName] and Appearance.keepsClothing(character, item) then wanted[item.ClassName] = item end
        end
    end
    for class, property in pairs(Overlay.ClothingProps) do
        local real, shown = wanted[class], entry.GameClothes[class]
        local template = real and real[property]
        if real and not (shown and shown.Template == template and shown.Copy.Parent == model) then
            for _, child in ipairs(model:GetChildren()) do
                if child.ClassName == class and not child:GetAttribute("Lyra_GameClothing") then
                    if not entry.OwnClothes[class] then entry.OwnClothes[class] = child end
                    child.Parent = nil
                end
            end
            if shown then pcall(function() shown.Copy:Destroy() end) end
            local copy = Instance.new(class)
            copy[property] = template
            if class ~= "ShirtGraphic" then pcall(function() copy.Color3 = real.Color3 end) end
            copy:SetAttribute("Lyra_GameClothing", true); copy.Parent = model
            entry.GameClothes[class] = {Template = template, Copy = copy}
        elseif not real and shown then
            pcall(function() shown.Copy:Destroy() end)
            entry.GameClothes[class] = nil
            local own = entry.OwnClothes[class]
            entry.OwnClothes[class] = nil
            if own then pcall(function() own.Parent = model end) end
        end
    end
end
-- Where a carried part goes on the overlay: the nearest attachment of its body part that an overlay body part also
-- has, else the overlay part of the same name (or the matching limb of the other rig). Returns the real reference
-- and the overlay one.
function Overlay.carryRefs(model, attachments, anchor, part)
    local best, mine, bestDistance
    for _, attachment in ipairs(anchor:GetChildren()) do
        local match = attachment.ClassName == "Attachment" and attachments[attachment.Name]
        if match then
            local distance = (attachment.WorldPosition - part.Position).Magnitude
            if not best or distance < bestDistance then best, mine, bestDistance = attachment, match, distance end
        end
    end
    if best then return best, mine end
    local same = model:FindFirstChild(anchor.Name)
    if same and Appearance.isBody(same, model) then return anchor, same end
    local group = Overlay.R6Groups[anchor.Name]
    if group then
        local upper = model:FindFirstChild(group[1])
        if upper then return anchor, upper end
    end
    for r6, names in pairs(Overlay.R6Groups) do
        if table.find(names, anchor.Name) then
            local limb = model:FindFirstChild(r6)
            if limb then return anchor, limb end
        end
    end
    return nil, nil
end
-- A local, inert copy of a part's look (mesh, decals, surface): no scripts, joints, sounds or effects.
function Overlay.carryCopy(part)
    local ok, copy = pcall(function()
        local archivable = part.Archivable
        part.Archivable = true
        local made = part:Clone()
        part.Archivable = archivable
        return made
    end)
    if not ok or not copy then return nil end
    for _, child in ipairs(copy:GetDescendants()) do
        if not (child:IsA("DataModelMesh") or child:IsA("Decal") or child:IsA("SurfaceAppearance")) then pcall(function() child:Destroy() end) end
    end
    pcall(function()
        copy.Name = "LyraCarried"; copy.Anchored = true; copy.CanCollide = false; copy.CanTouch = false; copy.CanQuery = false; copy.Massless = true
    end)
    return copy
end
function Overlay.carry(entry)
    local old = entry.Carried or {}
    entry.Carried = nil
    if not entry.Local or (entry.Mode ~= "puppet" and entry.Mode ~= "joints") then
        for real, row in pairs(old) do
            pcall(function() row.Copy:Destroy() end)
            Overlay.unhidePart(entry, real)
            for _, decal in ipairs(row.Decals) do Overlay.unhidePart(entry, decal) end
        end
        return
    end
    local model = entry.Model
    local folder = entry.CarryFolder
    if not (folder and folder.Parent == model) then
        folder = Instance.new("Model"); folder.Name = "LyraCarried"; folder.Parent = model; entry.CarryFolder = folder
    end
    local attachments = {}
    for _, part in ipairs(model:GetChildren()) do
        if Appearance.isBody(part, model) then
            for _, child in ipairs(part:GetChildren()) do
                if child.ClassName == "Attachment" and not attachments[child.Name] then attachments[child.Name] = child end
            end
        end
    end
    local carried = {}
    for real, anchor in pairs(Overlay.carriedParts(entry)) do
        local row = old[real]
        if row and row.Anchor == anchor and row.Copy.Parent == folder then
            old[real] = nil
        else
            row = nil
            local realRef, mineRef = Overlay.carryRefs(model, attachments, anchor, real)
            local copy = mineRef and Overlay.carryCopy(real)
            if copy then
                copy.Parent = folder
                local decals = {}
                for _, child in ipairs(real:GetChildren()) do if child:IsA("Decal") then table.insert(decals, child) end end
                row = {Copy = copy, RealRef = realRef, MineRef = mineRef, Anchor = anchor, Decals = decals,
                    RealAttachment = realRef:IsA("Attachment"), MineAttachment = mineRef:IsA("Attachment")}
            end
        end
        if row then
            carried[real] = row
            Overlay.hidePart(entry, real, "Transparency")
            for _, decal in ipairs(row.Decals) do Overlay.hidePart(entry, decal, "Transparency") end
        end
    end
    for real, row in pairs(old) do
        pcall(function() row.Copy:Destroy() end)
        Overlay.unhidePart(entry, real)
        for _, decal in ipairs(row.Decals) do Overlay.unhidePart(entry, decal) end
    end
    entry.Carried = carried
end
-- This frame's place of every carried copy (added to the overlay's BulkMoveTo). Returns whether one went away.
function Overlay.placeCarried(entry, parts, frames)
    local stale = false
    for real, row in pairs(entry.Carried or {}) do
        if real.Parent and real:IsDescendantOf(entry.Character) and row.MineRef.Parent and row.RealRef.Parent then
            local realFrame = row.RealAttachment and row.RealRef.WorldCFrame or row.RealRef.CFrame
            local mineFrame = row.MineAttachment and row.MineRef.WorldCFrame or row.MineRef.CFrame
            parts[#parts + 1] = row.Copy; frames[#frames + 1] = mineFrame * realFrame:ToObjectSpace(real.CFrame)
            -- The game can show or hide pieces of a tool: the copy does the same.
            local shown = Overlay.original(entry, real)
            if row.Shown ~= shown then row.Shown = shown; pcall(function() row.Copy.Transparency = shown end) end
        else
            stale = true
            if row.Shown ~= 1 then row.Shown = 1; pcall(function() row.Copy.Transparency = 1 end) end
        end
    end
    return stale
end
-- The transparency a part had before the overlay hid it.
function Overlay.original(entry, item)
    if entry.HiddenProp[item] == "Transparency" then return entry.Hidden[item] end
    return item.Transparency
end
-- Body parts are normally direct children of the model. Some games nest the visible body, so for a body part with
-- no visible direct child, body-named parts deeper in the model (outside tools) are used. A visible direct child
-- keeps carried models with "Head"/"Torso" parts untouched.
function Overlay.bodyParts(entry, model)
    local direct, nested = {}, {}
    local separate = entry.Local and model ~= entry.Character
    for _, item in ipairs(model:GetDescendants()) do
        if item:IsA("BasePart") and item.Name ~= "HumanoidRootPart" and S.BD[item.Name] ~= nil and not item:FindFirstAncestorOfClass("Tool")
            and not (separate and Overlay.far(entry, item)) then
            local group = item.Parent == model and direct or nested
            local list = group[item.Name]
            if not list then list = {}; group[item.Name] = list end
            table.insert(list, item)
        end
    end
    local found = {}
    for name, list in pairs(direct) do
        local visible = false
        for _, item in ipairs(list) do if Overlay.original(entry, item) < 1 then visible = true; break end end
        found[name] = visible and list or nil
    end
    for name, list in pairs(nested) do
        if not found[name] then
            local merged = table.clone(direct[name] or {})
            for _, item in ipairs(list) do table.insert(merged, item) end
            found[name] = merged
        end
    end
    return found
end
-- Of several parts with the same name, the visible one is followed (a direct child wins a tie).
function Overlay.pick(entry, list)
    local best, bestScore
    for _, item in ipairs(list or {}) do
        local score = Overlay.original(entry, item) + (item.Parent == entry.Target and 0 or 0.001)
        if not best or score < bestScore then best, bestScore = item, score end
    end
    return best
end
-- Part0, Part1, C0 and C1 of a Motor6D or of an AnimationConstraint (the newer avatar joints).
function Overlay.jointInfo(joint)
    if joint:IsA("Motor6D") then return joint.Part0, joint.Part1, joint.C0, joint.C1 end
    local a0, a1 = joint.Attachment0, joint.Attachment1
    if a0 and a1 then return a0.Parent, a1.Parent, a0.CFrame, a1.CFrame end
end
-- Each overlay body joint is paired with the real parts of the same names (games rename or rebuild joints, and
-- newer avatars use AnimationConstraints instead of Motor6Ds). The real joint, when there is one, only lends its
-- animation offset.
function Overlay.pairJoints(entry, model, target, found, realRoot)
    local realJoints = {}
    for _, item in ipairs(target:GetDescendants()) do
        if (item:IsA("Motor6D") or item:IsA("AnimationConstraint")) and not item:FindFirstAncestorOfClass("Tool") then
            local ok, a, b = pcall(Overlay.jointInfo, item)
            if ok and a and b then
                local key = a.Name .. "|" .. b.Name
                if realJoints[key] == nil then realJoints[key] = item end
            end
        end
    end
    local function realPart(name)
        if name == "HumanoidRootPart" then return realRoot end
        return Overlay.pick(entry, found[name])
    end
    local rows, total = {}, 0
    for _, item in ipairs(model:GetDescendants()) do
        if item:IsA("Motor6D") or item:IsA("AnimationConstraint") then
            local ok, p0, p1, c0, c1 = pcall(Overlay.jointInfo, item)
            if ok and p0 and p1 and c0 and c1 and S.BD[p1.Name] ~= nil and p1.Parent == model then
                total = total + 1
                local a, b = realPart(p0.Name), realPart(p1.Name)
                if a and b then
                    local toOwn = (c0 - c0.Position):Inverse()
                    local realJoint = realJoints[p0.Name .. "|" .. p1.Name]
                    local shift
                    if realJoint then
                        local okReal, _, _, realC0 = pcall(Overlay.jointInfo, realJoint)
                        if okReal and realC0 then shift = toOwn * (realC0 - realC0.Position) end
                    end
                    table.insert(rows, {item, realJoint, a, b, toOwn, c1 - c1.Position, shift})
                end
            end
        end
    end
    return rows, total
end
function Overlay.link(entry)
    local character, model = entry.Character, entry.Model
    -- Your own overlay also hides (and may follow) any other copy of your body (see the world scan).
    if entry.Local then entry.Extra = Overlay.bodies(character, true, entry) end
    local target = Overlay.target(character, entry.Extra)
    entry.Target = target
    if entry.Local then pcall(Overlay.releaseCopies, entry) end
    local root, realRoot = model:FindFirstChild("HumanoidRootPart"), Overlay.rootOf(character)
    entry.Root, entry.RealRoot = root, realRoot
    local found = Overlay.bodyParts(entry, target)
    entry.FoundParts = found
    entry.Found = next(found) ~= nil or realRoot ~= nil
    entry.RealHead = Overlay.pick(entry, found.Head)
    Overlay.linkMode(entry, target, found, root, realRoot)
    -- What the character carries goes on a puppet (see CARRIED ITEMS); then the camera fade links.
    if entry.Local then Overlay.carry(entry); Overlay.fadeLinks(entry, found) end
end
function Overlay.linkMode(entry, target, found, root, realRoot)
    local character, model = entry.Character, entry.Model
    if Overlay.wantsPuppet(entry, target) and root and realRoot then
        Overlay.setMode(entry, "puppet")
        local own = model:GetAttribute("LyraStandHeight") or Overlay.standHeight(model)
        local real = Overlay.standHeight(target) or Overlay.standHeight(character)
        entry.Lift = CFrame.new(0, (own and real) and (own - real) or 0, 0)
        entry.Joints, entry.Links, entry.Limbs = {}, {}, nil
        return
    end
    local rows, total = Overlay.pairJoints(entry, model, target, found, realRoot)
    -- A separate render model (Evade) moves its parts itself, sliding and crouching included: parts mode follows it
    -- exactly. Joints mode is for characters whose own body is the visible one, unless it stood frozen on this
    -- character before (see FROZEN AVATAR).
    if not entry.ForceParts and target == character and root and realRoot and realRoot.Name == "HumanoidRootPart" and total >= 5 and #rows >= total * 0.8 then
        if entry.Local and entry.Mode ~= "joints" then
            App.devNote(string.format("Visual-only follows the joints: %d of %d joints paired.", #rows, total))
        end
        Overlay.setMode(entry, "joints")
        -- The overlay's lowest point lands where the character stands: never above it, never pushed below it.
        local own, real = model:GetAttribute("LyraStandHeight") or Overlay.standHeight(model), Overlay.standHeight(character)
        entry.Lift = CFrame.new(0, (own and real) and (own - real) or 0, 0)
        -- Each overlay joint gets the rotation the game's limb really has relative to its parent part, expressed in
        -- the overlay joint's own axes. Games build joints with different C0/C1 axes, so copying Transform as is
        -- would twist the limbs.
        entry.Joints, entry.Links = rows, {}
        return
    end
    if entry.Local and entry.Mode ~= "parts" then
        App.devNote(string.format("Visual-only follows the parts (%s; %d of %d joints paired).",
            entry.ForceParts and "it stood frozen on the joints" or target ~= character and "a separate body" or "too few joints", #rows, total))
    end
    Overlay.setMode(entry, "parts")
    -- SOLVED POSE: an avatar that stood frozen on the joints used to be put part by part on your own body parts, so an
    -- avatar of other proportions came apart (gaps at the shoulders and hips, limbs inside the torso). Its pose is now
    -- worked out here instead: each of its parts is placed from its parent through its own joint, with the rotation
    -- your limb really has, so it keeps its own shape and moves as the joints mode would.
    local solved = {}
    entry.Solve = nil
    if entry.ForceParts and target == character and root and realRoot and total >= 5 and #rows >= total * 0.8 then
        local pending, order, placed = {}, {}, {[root] = true}
        for _, row in ipairs(rows) do
            local ok, p0, p1, c0, c1 = pcall(Overlay.jointInfo, row[1])
            if ok and p0 and p1 and c0 and c1 then table.insert(pending, {p0, p1, c0, c1:Inverse(), row[3], row[4], row[5], row[6], row[7], row[2]}) end
        end
        local moved = true
        while moved do
            moved = false
            for index = #pending, 1, -1 do
                local row = pending[index]
                if placed[row[1]] and not placed[row[2]] then
                    placed[row[2]] = true; table.insert(order, row); table.remove(pending, index); moved = true
                end
            end
        end
        if #order >= total * 0.8 then
            entry.Solve = order
            -- The avatar's lowest point lands where the character stands, as on the joints.
            local own, real = model:GetAttribute("LyraStandHeight") or Overlay.standHeight(model), Overlay.standHeight(character)
            entry.Lift = CFrame.new(0, (own and real) and (own - real) or 0, 0)
            for _, row in ipairs(order) do solved[row[2]] = true end
        end
    end
    -- Parts the target does not have follow the character's root with their rest-pose offset.
    local links = {}
    for _, part in ipairs(model:GetChildren()) do
        if part:IsA("BasePart") and part.Anchored and not solved[part] then
            local real = part.Name == "HumanoidRootPart" and realRoot or Overlay.pick(entry, found[part.Name])
            local mapped, offset
            if not real then mapped, offset = Overlay.crossRig(entry, model, part, found) end
            if real then table.insert(links, {part, real})
            elseif mapped then table.insert(links, {part, mapped, offset})
            elseif root and realRoot then table.insert(links, {part, realRoot, root.CFrame:ToObjectSpace(part.CFrame)})
            else part.Transparency = 1 end
        end
    end
    entry.Joints, entry.Links = {}, links
end
-- An R6 limb is one part; the matching R15 limb is three. Lists start with the upper part.
Overlay.R6Groups = {Torso = {"UpperTorso", "LowerTorso"}, ["Left Arm"] = {"LeftUpperArm", "LeftLowerArm", "LeftHand"},
    ["Right Arm"] = {"RightUpperArm", "RightLowerArm", "RightHand"}, ["Left Leg"] = {"LeftUpperLeg", "LeftLowerLeg", "LeftFoot"},
    ["Right Leg"] = {"RightUpperLeg", "RightLowerLeg", "RightFoot"}}
-- An overlay part with no real part of the same name (an R6 avatar on an R15 body or the other way round) follows
-- the matching limb, with the tops of both limbs lined up. Returns the real part and the offset from it.
function Overlay.crossRig(entry, model, part, found)
    local group = Overlay.R6Groups[part.Name]
    if group then
        local real = Overlay.pick(entry, found[group[1]])
        if real then return real, CFrame.new(0, real.Size.Y / 2 - part.Size.Y / 2, 0) end
        return nil
    end
    local rest = part:GetAttribute("LyraRest")
    if typeof(rest) ~= "CFrame" then return nil end
    for r6, names in pairs(Overlay.R6Groups) do
        if table.find(names, part.Name) then
            local real = Overlay.pick(entry, found[r6])
            local upper = model:FindFirstChild(names[1])
            local upperRest = upper and upper:GetAttribute("LyraRest")
            if not real or typeof(upperRest) ~= "CFrame" then return nil end
            local top = upperRest.Position + Vector3.new(0, upper.Size.Y / 2, 0)
            return real, CFrame.new(0, real.Size.Y / 2, 0) * CFrame.new(-top) * rest
        end
    end
end
-- FAR BODIES: with an avatar drawn over your character, other copies of your body are hidden and may be followed, but
-- only where you stand. A part of such a model that is more than 12 studs from your character is not your body here: a
-- rhythm game keeps the body it shows on its stage inside a model that stays at your feet (Project Afternight's
-- "Rig.PlayerRig", hundreds of studs away). It was hidden with the rest, so the stage showed nobody, and the stand-ins
-- that then dressed it had every part written back to invisible by the overlay. Far parts are now left alone, shown
-- again if they were hidden, and never followed.
function Overlay.far(entry, part)
    local root = entry.RealRoot
    if not (root and root.Parent) then root = Overlay.rootOf(entry.Character) end
    return root ~= nil and (part.Position - root.Position).Magnitude > 12
end
-- A model the stand-ins take over stops being the overlay's: everything hidden in it shows again as the game has it.
function Overlay.forget(model)
    local character = lp.Character
    local entry = character and Overlay.Active[character]
    if not entry or not entry.Local or model == character then return end
    if entry.Kept then entry.Kept[model] = nil end
    local items = {}
    for item in pairs(entry.Hidden) do if item:IsDescendantOf(model) then table.insert(items, item) end end
    for _, item in ipairs(items) do Overlay.unhidePart(entry, item) end
    for item, guard in pairs(entry.HideGuards or {}) do
        if item:IsDescendantOf(model) then guard:Disconnect(); entry.HideGuards[item] = nil end
    end
end
-- STAGE COPIES: rhythm games (and lobbies, cutscenes) copy your character where you stand and then put the copy
-- somewhere else: on the stage, while your own character waits out of sight. With an avatar drawn over your character
-- (visual-only, or an R15 avatar in an R6 game) such a copy was hidden as another copy of your body and stayed hidden
-- wherever the game took it, and a copy made of your hidden body was invisible from the start, so the stage showed
-- nobody. A copy that is no longer where you stand is now shown again as the game made it and handed to the stand-ins
-- (see STAND-INS), which put the avatar you wear on it. It has to be well away (8 studs) on two looks in a row, about
-- a second apart, so a body that only lags behind you for a moment stays the overlay's.
function Overlay.releaseCopies(entry)
    entry.Kept = entry.Kept or setmetatable({}, {__mode = "k"})
    for _, model in ipairs(entry.Extra or {}) do entry.Kept[model] = 0 end
    local root = Overlay.rootOf(entry.Character)
    if not root then return end
    local gone = {}
    for model, away in pairs(entry.Kept) do
        if not model.Parent then entry.Kept[model] = nil
        elseif model ~= entry.Target and not table.find(entry.Extra or {}, model) then
            local other = Overlay.rootOf(model)
            if other and (other.Position - root.Position).Magnitude > 8 then
                if away >= 1 then table.insert(gone, model) else entry.Kept[model] = away + 1 end
            else entry.Kept[model] = 0 end
        end
    end
    for _, model in ipairs(gone) do
        entry.Kept[model] = nil
        local items = {}
        for item in pairs(entry.Hidden) do if item:IsDescendantOf(model) then table.insert(items, item) end end
        for _, item in ipairs(items) do Overlay.unhidePart(entry, item) end
        if App.tracing() then App.trace("Stage copy left your place and is shown again: " .. App.traceName(model)) end
        Mirror.Tries[model] = nil
        Mirror.queue(model, 0.2)
    end
end
-- A copy the game made of your character while the overlay kept it hidden carries the hidden values (the mask on body
-- parts, 1 on worn items). It gets the values the game's own character had. Returns whether the model is such a copy.
function Overlay.unmaskCopy(model)
    local character = lp.Character
    local entry = character and Overlay.Active[character]
    if not entry or not entry.Local or model == character then return false end
    local masked = false
    for _, part in ipairs(model:GetChildren()) do
        if part:IsA("BasePart") and S.BD[part.Name] and part:GetAttribute("Lyra_BeforeOverlay") == nil and isMask(part.Transparency) then masked = true; break end
    end
    if not masked then return false end
    for _, item in ipairs(model:GetDescendants()) do
        if (item:IsA("BasePart") or item:IsA("Decal")) and item.Transparency > 0.99 and not entry.Hidden[item] then
            -- The same part of your own character, by its path of names.
            local names, cursor = {}, item
            while cursor and cursor ~= model do table.insert(names, 1, cursor.Name); cursor = cursor.Parent end
            local twin = character
            for _, name in ipairs(names) do twin = twin and twin:FindFirstChild(name) end
            local value = twin and twin ~= character and entry.HiddenProp[twin] == "Transparency" and entry.Hidden[twin] or nil
            if type(value) == "number" and value < 0.99 then pcall(function() item.Transparency = value end)
            elseif isMask(item.Transparency) then pcall(function() item.Transparency = 0 end) end
        end
    end
    return true
end
-- DRAWN OVER SOMEONE ELSE: an avatar drawn over a script user's character or over a stand-in is not faded by the
-- camera, but it follows the game: when the game hides or fades that whole body (a stage copy waiting for its song, an
-- invisibility power), the drawn avatar hides or fades as much. The least hidden body part counts, so a body with one
-- part the game always hides still shows. A separate body the overlay hides itself is read as the game has it.
function Overlay.fadeRemote(entry)
    local target = entry.Target and entry.Target.Parent and entry.Target or entry.Character
    local least, count = 1, 0
    for _, part in ipairs(target:GetChildren()) do
        if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" and S.BD[part.Name] ~= nil then
            least = math.min(least, Overlay.original(entry, part)); count = count + 1
        end
    end
    -- A body the game draws on parts nested deeper in the model (see Overlay.bodyParts).
    for _, list in pairs(entry.FoundParts or {}) do
        for _, part in ipairs(list) do
            if part.Parent and part.Parent ~= target then least = math.min(least, Overlay.original(entry, part)); count = count + 1 end
        end
    end
    local value = count > 0 and math.clamp(least, 0, 1) or 0
    if value < 0.005 then value = 0 end
    if entry.RemoteFade == value and entry.RemoteFadeFor == entry.Model then return end
    -- Nothing to write on an overlay that was never faded.
    local fresh = entry.RemoteFadeFor ~= entry.Model
    entry.RemoteFade, entry.RemoteFadeFor = value, entry.Model
    if fresh and value == 0 then return end
    for _, item in ipairs(entry.Model:GetDescendants()) do
        if item:IsA("BasePart") or item:IsA("Decal") then pcall(function() item.LocalTransparencyModifier = value end) end
    end
end
-- The visible body and accessories are hidden while the overlay is shown: your own character with Transparency
-- (the camera rewrites LocalTransparencyModifier on it), other players' characters with LocalTransparencyModifier,
-- and a separate render model (local to this client) with Transparency.
-- Hides one part or decal for an overlay. A game that shows it again (on a cosmetic change, or every frame) is undone
-- at once: only the copier writes 1, so any other value is the game's, kept for when the overlay comes off.
-- Your own body parts are hidden with the mask (Cloak.Mask) instead of 1, so the game making your character invisible (setting 1, an
-- invisibility cloak) still shows as a change, and the drawn avatar disappears with it (see Overlay.gameFade).
-- The value that hides item: the mask for your own body parts, 1 for everything else. While a highlight of the game is on
-- your character the mask would show (see GAME HIGHLIGHTS), so your body parts get 1 then too.
function Overlay.hiddenValue(entry, item, property)
    if property == "Transparency" and entry.Local and not entry.Lit and item.Parent == entry.Character and Appearance.isBody(item, entry.Character) then
        return Cloak.Mask
    end
    return 1
end
function Overlay.hidePart(entry, item, property)
    entry.HideGuards = entry.HideGuards or {}
    entry.Normal = entry.Normal or {}
    local character = entry.Character
    local ok, current = pcall(function() return item[property] end)
    if not ok then return end
    local hidden = Overlay.hiddenValue(entry, item, property)
    if not entry.HideGuards[item] then
        local guarded, connection = pcall(function()
            return item:GetPropertyChangedSignal(property):Connect(function()
                if Overlay.Active[character] ~= entry then return end
                local value = item[property]
                local hidden = Overlay.hiddenValue(entry, item, property)
                -- Compared with a tolerance: the property keeps a 32-bit float (see Cloak.Mask).
                if math.abs(value - hidden) > 1e-4 then
                    entry.Hidden[item] = value; entry.HiddenProp[item] = property; item[property] = hidden
                    if hidden ~= 1 then Overlay.gameFade(entry) end
                end
            end)
        end)
        if guarded then entry.HideGuards[item] = connection end
    end
    if math.abs(current - hidden) < 1e-4 then return end
    if entry.Hidden[item] == nil then
        entry.Hidden[item] = current; entry.HiddenProp[item] = property
        -- What the game shows when the overlay first hides it: its usual value.
        if entry.Normal[item] == nil then entry.Normal[item] = current end
    end
    pcall(function() item[property] = hidden end)
end
-- How much the game hides your own character (0 to 1): the least hidden of the body parts it usually shows. The drawn
-- avatar fades as much (see Overlay.fade).
function Overlay.gameFade(entry)
    local least, count = 1, 0
    for item, normal in pairs(entry.Normal or {}) do
        local value = entry.Hidden[item]
        if type(normal) == "number" and normal < 0.5 and type(value) == "number" and entry.HiddenProp[item] == "Transparency"
            and Appearance.isBody(item, entry.Character) then
            least = math.min(least, math.clamp((value - normal) / (1 - normal), 0, 1)); count = count + 1
        end
    end
    entry.GameFade = count > 0 and least or 0
end
-- Shows a hidden part again as the game had it (an item that left your character, such as a dropped tool).
function Overlay.unhidePart(entry, item)
    local guard = entry.HideGuards and entry.HideGuards[item]
    if guard then guard:Disconnect(); entry.HideGuards[item] = nil end
    local old, property = entry.Hidden[item], entry.HiddenProp[item]
    entry.Hidden[item] = nil; entry.HiddenProp[item] = nil
    if old ~= nil and property then pcall(function() item[property] = old end) end
end
-- GAME HIGHLIGHTS: your own body under a drawn avatar is hidden with the mask (see Cloak.Mask), which is almost but not
-- quite invisible, and a Highlight draws every part that is not fully invisible. Fighting games put one on your
-- character when you use a move, get hit or die (JJS), so your hidden R6 body came out as solid blocks through the
-- avatar. While a highlight of the game is on your character, your body parts are hidden fully, and the highlight is
-- drawn on the avatar instead (its colours kept in step every frame), so the effect still shows where your body is.
Overlay.LightFields = {"FillColor", "FillTransparency", "OutlineColor", "OutlineTransparency", "DepthMode"}
-- What a game's highlight lights of the drawn avatar: all of it for one on your character, the same part for one on a
-- body part. Nil when it lights nothing of your body (a held tool, something else).
function Overlay.lightTarget(entry, light)
    local character = entry.Character
    local ok, target = pcall(function() return light.Adornee or light.Parent end)
    if not ok or typeof(target) ~= "Instance" then return nil end
    if target == character or character:IsDescendantOf(target) then return entry.Model end
    if target:IsA("BasePart") and Appearance.isBody(target, character) then
        local own = entry.Model:FindFirstChild(target.Name)
        return (own and own:IsA("BasePart")) and own or entry.Model
    end
    return nil
end
function Overlay.light(entry)
    local active, count = {}, 0
    local function consider(light)
        local ok, on = pcall(function() return light.Enabled and (light.FillTransparency < 1 or light.OutlineTransparency < 1) end)
        if ok and on and not light:IsDescendantOf(entry.Model) then
            local target = Overlay.lightTarget(entry, light)
            if target then active[light] = target; count = count + 1 end
        end
    end
    for light in pairs(entry.Lights or {}) do
        if light.Parent then consider(light) else entry.Lights[light] = nil end
    end
    for _, light in ipairs(Overlay.Scanner.Lights or {}) do
        if light.Parent and not (entry.Lights and entry.Lights[light]) then consider(light) end
    end
    local lit = count > 0
    if lit ~= (entry.Lit == true) then
        entry.Lit = lit or nil
        -- The hidden body parts take the new value at once (their guards see the copier's own value and keep it).
        for item in pairs(entry.Hidden) do
            if entry.HiddenProp[item] == "Transparency" and item.Parent and Appearance.isBody(item, entry.Character) then
                pcall(function() item.Transparency = Overlay.hiddenValue(entry, item, "Transparency") end)
            end
        end
    end
    local mirrors = entry.Mirrors
    if not mirrors then
        if not lit then return end
        mirrors = {}; entry.Mirrors = mirrors
    end
    for light, mirror in pairs(mirrors) do
        if active[light] == nil or mirror.Parent == nil or mirror.Adornee ~= active[light] then
            pcall(function() mirror:Destroy() end); mirrors[light] = nil
        end
    end
    for light, target in pairs(active) do
        local mirror = mirrors[light]
        if not mirror then
            local made, item = pcall(function()
                local copy = Instance.new("Highlight"); copy.Name = "LyraGameHighlight"; copy.Adornee = target; copy.Parent = entry.Model
                return copy
            end)
            if made and item then mirror = item; mirrors[light] = item end
        end
        if mirror then
            pcall(function()
                for _, field in ipairs(Overlay.LightFields) do
                    local value = light[field]
                    if mirror[field] ~= value then mirror[field] = value end
                end
                -- Inside your head (first person) the drawn avatar is faded out, and so is its highlight.
                local shown = not entry.Inside
                if mirror.Enabled ~= shown then mirror.Enabled = shown end
            end)
        end
    end
end
function Overlay.hide(entry)
    local character = entry.Character
    local function hide(item, property) Overlay.hidePart(entry, item, property) end
    local function sweep(model)
        local property = (model ~= character or entry.Local) and "Transparency" or "LocalTransparencyModifier"
        -- Another model's parts far from you are not your body here (see FAR BODIES).
        local separate = entry.Local and model ~= character
        local function away(part) return separate and part:IsA("BasePart") and Overlay.far(entry, part) end
        for _, list in pairs(Overlay.bodyParts(entry, model)) do
            for _, part in ipairs(list) do
                hide(part, property)
                for _, decal in ipairs(part:GetChildren()) do if decal:IsA("Decal") then hide(decal, property) end end
            end
        end
        for _, item in ipairs(model:GetDescendants()) do
            local kept = item:IsA("Accessory") and Overlay.keptItem(entry, item)
            if kept and (not entry.Local or (entry.Mode ~= "puppet" and entry.Mode ~= "joints")) then
                -- Not carried on this avatar (only your own carries): the game's item shows where the game put it.
                for _, child in ipairs(item:GetDescendants()) do if entry.Hidden[child] ~= nil then Overlay.unhidePart(entry, child) end end
            end
            if item:IsA("Accessory") and not item:FindFirstAncestorOfClass("Tool") and not kept then
                local handle = item:FindFirstChild("Handle")
                if not (handle and away(handle)) then
                    for _, child in ipairs(item:GetDescendants()) do if child:IsA("BasePart") or child:IsA("Decal") then hide(child, property) end end
                end
            end
        end
        if separate then
            local gone = {}
            for item in pairs(entry.Hidden) do
                local part = item:IsA("Decal") and item.Parent or item
                if item:IsDescendantOf(model) and part and away(part) then table.insert(gone, item) end
            end
            for _, item in ipairs(gone) do Overlay.unhidePart(entry, item) end
--- YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
        end
    end
    sweep(character)
    local swept = {[character] = true}
    if entry.Target and entry.Target ~= character and entry.Target.Parent then sweep(entry.Target); swept[entry.Target] = true end
    -- Other copies of your body standing where you are (a game can draw it on a separate model, see Overlay.bodies).
    for _, model in ipairs(entry.Extra or {}) do
        if not swept[model] and model.Parent then sweep(model); swept[model] = true end
    end
end
-- Keeps every overlay part out of physics, raycasts and touches, even if something switches them back on.
function Overlay.inert(entry)
    for _, item in ipairs(entry.Model:GetDescendants()) do
        if item:IsA("BasePart") and (item.CanCollide or item.CanQuery or item.CanTouch) then
            item.CanCollide = false; item.CanQuery = false; item.CanTouch = false
        end
    end
end
-- Every overlay part stays out of physics at once and for good: a part that something switches back to colliding
-- (a Humanoid does this to R6 torsos and heads) is switched off again in the same frame, so the overlay never pushes
-- the character it is drawn on.
function Overlay.guard(entry)
    for _, connection in ipairs(entry.Guards or {}) do connection:Disconnect() end
    entry.Guards = {}
    for _, part in ipairs(entry.Model:GetDescendants()) do
        if part:IsA("BasePart") then
            part.CanCollide = false; part.CanTouch = false; part.CanQuery = false
            table.insert(entry.Guards, part:GetPropertyChangedSignal("CanCollide"):Connect(function()
                if part.CanCollide then part.CanCollide = false end
            end))
        end
    end
end
-- Where the overlay's parts go this frame (added to parts/frames for one BulkMoveTo). Returns whether a followed part
-- is gone (the overlay then relinks).
function Overlay.place(entry, parts, frames)
    local stale = false
    if entry.Mode == "joints" or entry.Mode == "puppet" then
        local realRoot = entry.RealRoot
        -- A loose body's root can stay behind (or be taken away) while the torso falls: the puppet lies on the torso.
        local anchor = entry.Mode == "puppet" and entry.Loose and entry.Anchor
        if anchor and anchor.Parent then parts[#parts + 1] = entry.Root; frames[#frames + 1] = anchor.CFrame * entry.AnchorShift * entry.Lift
        elseif realRoot and realRoot.Parent then parts[#parts + 1] = entry.Root; frames[#frames + 1] = realRoot.CFrame * entry.Lift
        else stale = true end
        -- A puppet's joints are moved by its own animations.
        for _, row in ipairs(entry.Joints) do
            local a, b = row[3], row[4]
            if a.Parent and b.Parent then
                local relative = a.CFrame:ToObjectSpace(b.CFrame)
                local turn = row[5] * (relative - relative.Position) * row[6]
                local real = row[2]
                if row[7] and real and real.Parent then turn = CFrame.new(row[7] * real.Transform.Position) * turn end
                row[1].Transform = turn
            else stale = true end
        end
    else
        for _, link in ipairs(entry.Links) do
            if link[2].Parent then parts[#parts + 1] = link[1]; frames[#frames + 1] = link[3] and link[2].CFrame * link[3] or link[2].CFrame
            else stale = true end
        end
        -- See SOLVED POSE: parents first, each part from its parent's place this frame.
        if entry.Solve then
            local realRoot = entry.RealRoot
            if realRoot and realRoot.Parent and entry.Root then
                local at = {[entry.Root] = realRoot.CFrame * (entry.Lift or CFrame.new())}
                for _, row in ipairs(entry.Solve) do
                    local parent, a, b = at[row[1]], row[5], row[6]
                    if parent and a.Parent and b.Parent then
                        local relative = a.CFrame:ToObjectSpace(b.CFrame)
                        local turn = row[7] * (relative - relative.Position) * row[8]
                        local real = row[10]
                        if row[9] and real and real.Parent then turn = CFrame.new(row[9] * real.Transform.Position) * turn end
                        local frame = parent * row[3] * turn * row[4]
                        at[row[2]] = frame
                        parts[#parts + 1] = row[2]; frames[#frames + 1] = frame
                    else stale = true end
                end
            else stale = true end
        end
    end
    if entry.Carried and Overlay.placeCarried(entry, parts, frames) then stale = true end
    return stale
end
function Overlay.attach(character, model, isLocal, key, extra)
    Overlay.clear(character)
    local entry = {Character = character, Model = model, Links = {}, Joints = {}, Hidden = {}, HiddenProp = {}, Local = isLocal, Key = key, Started = os.clock(), Revives = {}}
    for field, value in pairs(extra or {}) do entry[field] = value end
    -- A tool taken out or put away is moved onto the overlay (or shown again) on the next frame.
    if isLocal then
        entry.Watch = {}
        for _, event in ipairs({character.ChildAdded, character.ChildRemoved}) do
            table.insert(entry.Watch, event:Connect(function(child) if child:IsA("Tool") then entry.Relink = true end end))
        end
        -- The game's highlights on your character (see GAME HIGHLIGHTS), from the moment one is added.
        entry.Lights = {}
        for _, item in ipairs(character:GetDescendants()) do if item:IsA("Highlight") then entry.Lights[item] = true end end
        table.insert(entry.Watch, character.DescendantAdded:Connect(function(item) if item:IsA("Highlight") then entry.Lights[item] = true end end))
    end
    local copied, spare = pcall(function() return model:Clone() end)
    entry.Spare = copied and spare or nil
    Overlay.Active[character] = entry
    Overlay.guard(entry)
    Overlay.link(entry)
    Overlay.hide(entry)
    -- Placed at once, so it never shows (or sits) at the world origin for a frame.
    pcall(function()
        local parts, frames = {}, {}
        Overlay.place(entry, parts, frames)
        if #parts > 0 then workspace:BulkMoveTo(parts, frames, Enum.BulkMoveMode.FireCFrameChanged) end
    end)
    Overlay.start()
    return entry
end
-- The game removed the overlay (cleared the camera, for example): put it back, or rebuild it from the spare copy.
-- At most 20 times a minute, so a game that deletes it on every frame does not make it rebuild forever.
function Overlay.revive(entry)
    local now = os.clock()
    for i = #entry.Revives, 1, -1 do if now - entry.Revives[i] > 60 then table.remove(entry.Revives, i) end end
    if #entry.Revives >= 20 then return false end
    table.insert(entry.Revives, now)
    local moved = pcall(function() entry.Model.Parent = Overlay.folder() end)
    if not moved or not entry.Model:IsDescendantOf(workspace) then
        if not entry.Spare then return false end
        local copied, model = pcall(function() return entry.Spare:Clone() end)
        if not copied or not model then return false end
        pcall(function() entry.Model:Destroy() end)
        model.Parent = Overlay.folder(); entry.Model = model; entry.Mode = nil
        Overlay.guard(entry)
    end
    Overlay.link(entry)
    return true
end
function Overlay.clear(character)
    local entry = character and Overlay.Active[character]
    if not entry then return end
    Overlay.Active[character] = nil
    if entry.Puppet then pcall(Overlay.puppetStop, entry) end
    for _, connection in ipairs(entry.Watch or {}) do connection:Disconnect() end
    for _, connection in ipairs(entry.Guards or {}) do connection:Disconnect() end
    for _, connection in pairs(entry.HideGuards or {}) do connection:Disconnect() end
    for item, old in pairs(entry.Hidden) do
        local property = entry.HiddenProp[item]
        pcall(function() if item.Parent then item[property] = old end end)
    end
    pcall(function() entry.Model:Destroy() end)
    if entry.Spare then pcall(function() entry.Spare:Destroy() end) end
end
function Overlay.clearAll()
    for character in pairs(Overlay.Active) do Overlay.clear(character) end
    if Overlay.Connection then Overlay.Connection:Disconnect(); Overlay.Connection = nil end
-- cache YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
    if Overlay.Folder then pcall(function() Overlay.Folder:Destroy() end); Overlay.Folder = nil end
end
function Overlay.start()
    if Overlay.Connection then return end
    local frame = 0
    Overlay.Connection = RS.RenderStepped:Connect(function()
        frame = frame + 1
        -- The shared world scan moves on a little every frame.
        pcall(Overlay.scanStep, 800)
        local parts, frames = {}, {}
        local camera = workspace.CurrentCamera
        for character, entry in pairs(Overlay.Active) do
            if not character.Parent then
                Overlay.clear(character)
            elseif not entry.Model.Parent or not entry.Model:IsDescendantOf(workspace) then
                if not Overlay.revive(entry) then
                    Overlay.clear(character)
                    if entry.Local then App.report("The game keeps removing the avatar drawn over your character, so it was turned off.", "warning") end
                end
            else
                if entry.Relink then entry.Relink = nil; pcall(Overlay.link, entry) end
                local stale = Overlay.place(entry, parts, frames)
                if entry.Target ~= character and not (entry.Target and entry.Target.Parent) then stale = true end
                -- Twice a second (your own overlay: six times): relink when parts were rebuilt (or while a render model
                -- has not appeared yet), hide what loaded late or was reset, and keep the overlay out of physics.
                if frame % (entry.Local and 10 or 30) == 0 then
                    Overlay.folder()
                    -- A render model or another copy of your body can appear later (a game may build it once you
                    -- play or change a cosmetic): your own overlay looks again every second.
                    if stale or not entry.Found or (entry.Local and frame % 60 == 0) then Overlay.link(entry) end
                    if entry.Local then pcall(Overlay.watchStiff, entry); pcall(Overlay.checkFollow, entry) end
                    pcall(Overlay.dressGame, entry)
                    Overlay.hide(entry); Overlay.inert(entry)
                    if entry.Local and not entry.Found and not entry.Warned and os.clock() - entry.Started > 6 then
                        entry.Warned = true
                        App.report("Your character could not be found in this game yet, so the avatar is not drawn. It appears once your character does.", "warning")
                    end
                end
                if entry.Mode == "puppet" then
                    -- A body that fell apart is followed limb by limb (see RAGDOLL).
                    local readable, loose = pcall(Overlay.ragdolled, entry)
                    entry.Loose = (readable and loose) or nil
                    pcall(Overlay.puppetStep, entry); pcall(Overlay.puppetLimbs, entry)
                end
                if entry.Mood and frame % 15 == 0 then pcall(Overlay.playMood, entry) end
                -- Your own overlay fades with your character (zooming in, first person; see CAMERA FADE); one drawn
                -- over someone else follows the game hiding that body (see DRAWN OVER SOMEONE ELSE).
                if entry.Local then pcall(Overlay.fade, entry, camera); pcall(Overlay.light, entry)
                elseif frame % 2 == 0 then pcall(Overlay.fadeRemote, entry) end
            end
        end
        if #parts > 0 then pcall(function() workspace:BulkMoveTo(parts, frames, Enum.BulkMoveMode.FireCFrameChanged) end) end
        if next(Overlay.Active) == nil and Overlay.Connection then Overlay.Connection:Disconnect(); Overlay.Connection = nil end
    end)
end

-- CUSTOM CHARACTERS: some games draw your character their own way, so an avatar put on the character itself cannot show
-- (or shows mixed with the game's body). Visual-only draws it over the character instead, and is suggested once per game
-- in a session, with a button that turns it on. Only on clear signs, read before the avatar goes on: a separate model
-- joined to your character's root draws your body (Evade's way), your own body parts are all hidden while another body
-- is drawn where you stand, or the character has no Roblox body parts at all. A game whose character merely looks
-- unusual, or hides your body only in first person, is never told to.
App.SuggestedVisual = {}
function App.customCharacter(char)
    if not char or not char.Parent then return nil end
    local ok, rig, linked = pcall(Overlay.renderRig, char)
    if ok and rig and linked then return "render" end
    local parts, shown = 0, 0
    for _, part in ipairs(char:GetChildren()) do
        if part:IsA("BasePart") and S.BD[part.Name] and part.Name ~= "HumanoidRootPart" then
            parts = parts + 1
            if part.Transparency < 1 then shown = shown + 1 end
        end
    end
    if parts == 0 then return char:FindFirstChildOfClass("Humanoid") and "nobody" or nil end
    if shown == 0 then
        local found, others = pcall(Overlay.bodies, char, false)
        if found and type(others) == "table" and #others > 0 then return "hidden" end
    end
    return nil
end
function App.suggestVisualOnly(reason)
    if not reason or Overlay.visualOnly() or App.SuggestedVisual[game.GameId] or not App.alive() then return end
    App.SuggestedVisual[game.GameId] = true
    App.toast({Title = "Visual-only works better here", Kind = "info", Icon = "eye-off", Duration = 12,
        Text = "This game draws your character its own way, so an avatar put on the character itself may not show right. Visual-only draws it over your character instead.",
        Action = {Text = "Turn on Visual-only", Callback = function()
            if Overlay.visualOnly() or not App.alive() then return end
            Store.Settings.VisualOnly = true; App.persist()
            if UI.Toggles and UI.Toggles.VisualOnly then pcall(UI.Toggles.VisualOnly) end
            App.switchVisualOnly(true)
        end}})
end

-- CAMERA ON A FLOATING AVATAR: Roblox's camera follows the HumanoidRootPart, not the body. An animation pack that floats
-- (Floating Aura, Levitation…) lifts the body above it, so with such an avatar on, the camera stayed below the floating
-- head. While a copied avatar is on your character itself (not visual-only), a lift the animation holds (the root
-- joint raising the body more than 0.3 studs) raises the camera by as much, eased in and out, through the Humanoid's
-- CameraOffset. Short moves (a walk's bounce, a jump) and every avatar that does not float change nothing, and nothing
-- is written then. What the game puts in CameraOffset is kept; the lift comes off with the avatar.
-- Only the copied pack's own animations count, and never more than CameraLift.Max: a game move that carries the body up
-- through the root joint (The Strongest Battlegrounds' leaps and ultimates) used to take the camera up with it, far
-- above the map. A knocked-down, ragdolled or tipped-over body gets no lift at all: CameraOffset turns with the
-- HumanoidRootPart, so on a body lying on its side the lift pushed the camera sideways and tilted the view.
local CameraLift = {Added = 0, Smooth = 0, Max = 6}
CameraLift.Down = {[Enum.HumanoidStateType.Physics] = true, [Enum.HumanoidStateType.Ragdoll] = true,
    [Enum.HumanoidStateType.FallingDown] = true, [Enum.HumanoidStateType.Dead] = true,
    [Enum.HumanoidStateType.PlatformStanding] = true, [Enum.HumanoidStateType.GettingUp] = true}
-- Whether the body stands as the camera expects: upright, held by its root joint and not let loose by the game.
function CameraLift.standing(char, hum)
    if hum.PlatformStand then return false end
    local ok, state = pcall(function() return hum:GetState() end)
    if ok and CameraLift.Down[state] then return false end
    local root = char:FindFirstChild("HumanoidRootPart")
    if not (root and root:IsA("BasePart")) or root.CFrame.UpVector.Y < 0.7 then return false end
    local joint = CameraLift.rootJoint(char)
    if joint then
        local readable, enabled = pcall(function() return joint.Enabled end)
        if readable and enabled == false then return false end
    end
    return true
end
-- Whether the lift comes from the copied avatar's pack: one of its animations plays and none of the game's own does.
function CameraLift.fromPack(char, hum)
    local animator = hum:FindFirstChildOfClass("Animator")
    if not animator then return false end
    local animate = char:FindFirstChild("Animate")
    local pack = false
    for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
        if track.WeightCurrent > 0.3 then
            if not F.isAnimateTrack(track, animate) then return false end
            local ok, id = pcall(function() return F.normalizeAnimId(track.Animation.AnimationId) end)
            if ok and F.WrittenIds[id] then pack = true end
        end
    end
    return pack
end
function CameraLift.rootJoint(char)
    if CameraLift.JointFor == char and CameraLift.Joint and CameraLift.Joint.Parent then return CameraLift.Joint end
    -- A rig without that joint is looked at again once a second, not every frame (a search of the whole character).
    if CameraLift.JointFor == char and not CameraLift.Joint and os.clock() < (CameraLift.RetryAt or 0) then return nil end
    CameraLift.JointFor, CameraLift.Joint, CameraLift.RetryAt = char, nil, os.clock() + 1
    local root = char:FindFirstChild("HumanoidRootPart")
    local torso = char:FindFirstChild("LowerTorso") or char:FindFirstChild("Torso")
    if not root or not torso then return nil end
    -- The root joint sits in the torso (R15) or the root (R6); the rest of the character only when a game moved it.
    for _, holder in ipairs({torso, root}) do
        for _, item in ipairs(holder:GetChildren()) do
            if item:IsA("Motor6D") and item.Part0 == root and item.Part1 == torso then CameraLift.Joint = item; return item end
        end
    end
    for _, item in ipairs(char:GetDescendants()) do
        if item:IsA("Motor6D") and item.Part0 == root and item.Part1 == torso then CameraLift.Joint = item; break end
    end
    return CameraLift.Joint
end
-- How far the animation holds the body above its rest place, in studs (0 when it does not).
function CameraLift.lift(char)
    local joint = CameraLift.rootJoint(char)
    if not joint then return 0 end
    local ok, value = pcall(function()
        local base = joint.Part0.CFrame * joint.C0
        return (base * joint.Transform).Position.Y - base.Position.Y
    end)
    return (ok and value > 0.3) and math.min(value, CameraLift.Max) or 0
end
function CameraLift.step(dt)
    local char = lp.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum ~= CameraLift.Hum then CameraLift.Hum, CameraLift.Added, CameraLift.Smooth, CameraLift.LastSet = hum, 0, 0, nil end
    if not hum then return end
    local active = S.fvOn and S.TouchedChar == char and not Overlay.visualOnly() and hum.Health > 0
    local standing = active and CameraLift.standing(char, hum)
    local lift = (standing and CameraLift.fromPack(char, hum)) and CameraLift.lift(char) or 0
    -- A body raised on the root joint for longer copied legs (see fitGeometry) raises the camera as much, as the
    -- raised root it replaced did.
    local hipLift = standing and hum:GetAttribute("Lyra_HipLift")
    if type(hipLift) == "number" and hipLift > 0 then lift = lift + hipLift end
    -- A body that falls or tips over drops the lift at once instead of easing it out.
    if hum.Health <= 0 or (active and not standing) then CameraLift.Smooth = 0 end
    CameraLift.Smooth = CameraLift.Smooth + (lift - CameraLift.Smooth) * math.min(1, (dt or 0) * 3)
    local want = CameraLift.Smooth > 0.05 and CameraLift.Smooth or 0
    if want == 0 and CameraLift.Added == 0 then return end
    local current = hum.CameraOffset
    -- A value the game set since (not the one written here) is the game's own, without the lift. A game that moves
    -- the offset from the value written here (a shake added to it, an ease towards its own value) keeps the lift in it:
    -- that lift is taken out first, or it was added again every frame and the camera climbed without end.
    local base = current
    if CameraLift.LastSet and CameraLift.Added ~= 0 then
        local kept = math.abs(current.Y - CameraLift.LastSet.Y) < math.abs(current.Y - (CameraLift.LastSet.Y - CameraLift.Added))
        if (current - CameraLift.LastSet).Magnitude < 1e-3 or kept then base = current - Vector3.new(0, CameraLift.Added, 0) end
    end
    local target = base + Vector3.new(0, want, 0)
    if (target - current).Magnitude > 0.01 or (want == 0 and CameraLift.Added ~= 0) then
        hum.CameraOffset = target
        CameraLift.LastSet, CameraLift.Added = target, want
    else
        -- Too small a change to write: what stays applied is what is there.
        CameraLift.LastSet, CameraLift.Added = current, current.Y - base.Y
    end
end
-- Takes the lift off at once (the script closing).
function CameraLift.reset()
    local hum = CameraLift.Hum
    if hum and hum.Parent and CameraLift.Added ~= 0 and CameraLift.LastSet and (hum.CameraOffset - CameraLift.LastSet).Magnitude < 1e-3 then
        hum.CameraOffset = hum.CameraOffset - Vector3.new(0, CameraLift.Added, 0)
    end
    CameraLift.Added, CameraLift.Smooth, CameraLift.LastSet = 0, 0, nil
end
RegisterConnection(RS.RenderStepped:Connect(function(dt) if App.alive() then pcall(CameraLift.step, dt) end end))

-- FIRST-PERSON ARMS: Evade (and many shooters) draws your arms in first person on a model of its own in the camera
-- (Evade's Viewmodel/Clothing: a Humanoid, two arms, your shirt, your skin colour, your arm meshes), built from your
-- own look. Under a copied avatar they kept showing your own arms while you ran. While a copied avatar is on, such a
-- model wears the copied avatar's shirt, arm colours and arm meshes (from the avatar drawn over you, or from your
-- character when the avatar is on it); its own come back with your own look or when the script closes. Twice a second.
Overlay.ArmParts = {Left = {"Left Arm", "LeftUpperArm", "LeftLowerArm", "LeftHand"}, Right = {"Right Arm", "RightUpperArm", "RightLowerArm", "RightHand"}}
Overlay.ArmRecords = setmetatable({}, {__mode = "k"})
function Overlay.armsSource()
    local char = lp.Character
    if not char or not App.Current or App.Current.Original then return nil end
    local entry = Overlay.Active[char]
    if entry and entry.Local and entry.Model and entry.Model.Parent then return entry.Model end
    if S.fvOn and S.TouchedChar == char then return char end
    return nil
end
-- Models in the camera that show arms and nothing else of a body (no head, no torso), with a Humanoid to wear clothes.
function Overlay.armModels()
    local camera = workspace.CurrentCamera
    local char = lp.Character
    local entry = char and Overlay.Active[char]
    local list = {}
    for _, hum in ipairs(camera and camera:GetDescendants() or {}) do
        local model = hum:IsA("Humanoid") and hum.Parent
        if model and model:IsA("Model") and not (Overlay.Folder and model:IsDescendantOf(Overlay.Folder)) and not Mirror.Dressed[model]
            and not (entry and (entry.Target == model or table.find(entry.Extra or {}, model))) then
            local arms, body = 0, false
            for _, part in ipairs(model:GetChildren()) do
                if part:IsA("BasePart") and part.Transparency < 1 then
                    if table.find(Overlay.ArmParts.Left, part.Name) or table.find(Overlay.ArmParts.Right, part.Name) then arms = arms + 1
                    elseif part.Name == "Head" or part.Name == "Torso" or part.Name == "UpperTorso" then body = true end
                end
            end
            if arms > 0 and not body then table.insert(list, model) end
        end
    end
    return list
end
function Overlay.armMesh(mesh)
    return mesh:IsA("CharacterMesh") and (mesh.BodyPart == Enum.BodyPart.LeftArm or mesh.BodyPart == Enum.BodyPart.RightArm)
end
function Overlay.dressArmModel(model, source)
    local record = Overlay.ArmRecords[model]
    if not record then record = {Colors = {}, Meshes = {}}; Overlay.ArmRecords[model] = record end
    -- The shirt (its sleeves are what an arm shows): the avatar's, or none when the avatar wears none.
    local wanted = source:FindFirstChildOfClass("Shirt")
    local template = wanted and wanted.ShirtTemplate or ""
    local shirt = model:FindFirstChildOfClass("Shirt")
    if not shirt and template ~= "" then
        shirt = Instance.new("Shirt"); shirt:SetAttribute("Lyra_ArmsItem", true); shirt.Parent = model
    end
    if shirt then
        if not shirt:GetAttribute("Lyra_ArmsItem") and record.Shirt ~= shirt then record.Shirt, record.ShirtTemplate = shirt, shirt.ShirtTemplate end
        if shirt.ShirtTemplate ~= template then shirt.ShirtTemplate = template end
        if wanted then pcall(function() if shirt.Color3 ~= wanted.Color3 then shirt.Color3 = wanted.Color3 end end) end
    end
    -- The arms' colour.
    local colors, own = source:FindFirstChildOfClass("BodyColors"), model:FindFirstChildOfClass("BodyColors")
    for side, names in pairs(Overlay.ArmParts) do
        local color = colors and colors[side .. "ArmColor3"]
        if not color then
            local part = source:FindFirstChild(names[1]) or source:FindFirstChild(names[2])
            color = part and part:IsA("BasePart") and part.Color or nil
        end
        if color then
            local key = side .. "ArmColor3"
            if own then
                if record.Colors[key] == nil then record.Colors[key] = own[key] end
                if own[key] ~= color then own[key] = color end
            end
            for _, name in ipairs(names) do
                local part = model:FindFirstChild(name)
                if part and part:IsA("BasePart") then
                    if record.Colors[part] == nil then record.Colors[part] = part.Color end
                    if part.Color ~= color then part.Color = color end
                end
            end
        end
    end
    -- The arm meshes (an R6 package's arms): the avatar's in place of the model's own.
    local meshes, key = {}, {}
    for _, mesh in ipairs(source:GetChildren()) do
        if Overlay.armMesh(mesh) then table.insert(meshes, mesh); table.insert(key, mesh.BodyPart.Name .. ":" .. tostring(mesh.MeshId)) end
    end
    table.sort(key); key = table.concat(key, ",")
    local stale = record.MeshKey ~= key
    for _, mesh in ipairs(model:GetChildren()) do
        if Overlay.armMesh(mesh) and not mesh:GetAttribute("Lyra_ArmsItem") then stale = true end
    end
    if stale then
        for _, mesh in ipairs(model:GetChildren()) do
            if Overlay.armMesh(mesh) then
                if mesh:GetAttribute("Lyra_ArmsItem") then mesh:Destroy() else table.insert(record.Meshes, mesh); mesh.Parent = nil end
            end
        end
        for _, mesh in ipairs(meshes) do
            local copy = mesh:Clone(); copy:SetAttribute("Lyra_ArmsItem", true); copy.Parent = model
        end
        record.MeshKey = key
    end
end
function Overlay.undressArmModel(model)
    local record = Overlay.ArmRecords[model]
    if not record then return end
    Overlay.ArmRecords[model] = nil
    if record.Shirt and record.Shirt.Parent then pcall(function() record.Shirt.ShirtTemplate = record.ShirtTemplate end) end
    local own = model:FindFirstChildOfClass("BodyColors")
    for key, value in pairs(record.Colors) do
        pcall(function()
            if typeof(key) == "Instance" then if key.Parent then key.Color = value end
            elseif own then own[key] = value end
        end)
    end
    for _, item in ipairs(model:GetChildren()) do if item:GetAttribute("Lyra_ArmsItem") then pcall(function() item:Destroy() end) end end
    for _, mesh in ipairs(record.Meshes) do pcall(function() mesh.Parent = model end) end
end
function Overlay.dressArms()
    local source = Overlay.armsSource()
    local seen = {}
    if source then
        for _, model in ipairs(Overlay.armModels()) do
            if not Overlay.ArmRecords[model] then App.devNote("First-person arms found: " .. model:GetFullName() .. "; they wear the copied avatar.") end
            seen[model] = true
            pcall(Overlay.dressArmModel, model, source)
        end
    end
    for model in pairs(Overlay.ArmRecords) do if not seen[model] then pcall(Overlay.undressArmModel, model) end end
end
task.spawn(function()
    while App.alive() do
        pcall(Overlay.dressArms)
        task.wait(0.5)
    end
end)

-- STAND-INS: games build more copies of your avatar than your character: a lobby or menu preview, intro cutscenes, a
-- first-person body. They are usually made from your Roblox profile on the server, so they kept showing your own
-- avatar while you wore another one. Any model with a Humanoid that is not a player's character and shows you is
-- dressed in the avatar you wear, on your screen only; its joints and animations stay the game's, so a cutscene plays
-- as made. It gets its own look back with yours. A model shows you when it is named after you, carries your avatar's
-- description, or wears at least three pieces of your own avatar (two of them accessories).
-- Settings > Advanced > "Show my avatar on the game's copies of me" turns this off, your in-game picture included.
Mirror.Known = setmetatable({}, {__mode = "k"})
Mirror.Dressed = setmetatable({}, {__mode = "k"})
Mirror.Tries = setmetatable({}, {__mode = "k"})
Mirror.Queue, Mirror.Queued = {}, setmetatable({}, {__mode = "k"})
Mirror.Sources, Mirror.OwnKeys = {}, {}
Mirror.Unmasked = setmetatable({}, {__mode = "k"})
function Mirror.wanted()
    return Store.Settings.StandIns ~= false and App.Current ~= nil and not App.Current.Original
end
-- An asset id from a content URL (rbxassetid://1, http://www.roblox.com/asset/?id=1), else the URL itself.
function Mirror.assetKey(url)
    local text = tostring(url or "")
    return text:match("^rbxassetid://(%d+)") or text:match("[?&]id=(%d+)") or text:match("^(%d+)$") or text
end
-- The pieces a model wears: clothing templates and accessory meshes. Pieces the copier added never count.
function Mirror.pieces(model)
    local set, count = {}, 0
    local function add(key, kind)
        if key ~= "" and not set[key] then set[key] = kind; count = count + 1 end
    end
    for _, item in ipairs(model:GetChildren()) do
        if not item:GetAttribute("Copier_CopiedItem") then
            if item:IsA("Shirt") and item.ShirtTemplate ~= "" then add("shirt:" .. Mirror.assetKey(item.ShirtTemplate), "cloth")
            elseif item:IsA("Pants") and item.PantsTemplate ~= "" then add("pants:" .. Mirror.assetKey(item.PantsTemplate), "cloth")
            elseif item:IsA("ShirtGraphic") and item.Graphic ~= "" then add("tee:" .. Mirror.assetKey(item.Graphic), "cloth")
            elseif item:IsA("Accessory") then
                local handle = item:FindFirstChild("Handle")
                local mesh
                if handle and handle:IsA("MeshPart") then mesh = handle.MeshId
                elseif handle then
                    local special = handle:FindFirstChildWhichIsA("SpecialMesh")
                    mesh = special and special.MeshId
                end
                if mesh and mesh ~= "" then add("acc:" .. Mirror.assetKey(mesh), "acc") end
            end
        end
    end
    return {Set = set, Count = count}
end
-- What a description dresses: clothing, face, body parts and accessories. An avatar that wears almost nothing says
-- nothing about whose it is, so it gives no key.
function Mirror.descKey(desc)
    local parts, worn = {}, 0
    local ok = pcall(function()
        for _, field in ipairs({"Shirt", "Pants", "GraphicTShirt", "Face", "Head", "Torso", "LeftArm", "RightArm", "LeftLeg", "RightLeg"}) do
            local value = tostring(desc[field])
            table.insert(parts, value)
            if value ~= "0" then worn = worn + 1 end
        end
        local ids = {}
        for _, row in ipairs(desc:GetAccessories(true)) do table.insert(ids, tostring(row.AssetId)) end
        table.sort(ids)
        worn = worn + #ids
        table.insert(parts, table.concat(ids, ","))
    end)
    return (ok and worn >= 3) and table.concat(parts, "|") or ""
end
-- Remembers your own look while the copier has not changed your character.
function Mirror.learn(char)
    if not char or S.TouchedChar == char then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    local live = hum and App.liveDescription(hum)
    if live and not live:GetAttribute("Lyra_Description") then
        local key = Mirror.descKey(live)
        if key ~= "" then Mirror.OwnKeys[key] = true end
    end
    local pieces = Mirror.pieces(char)
    if pieces.Count >= 2 then Mirror.OwnPieces = pieces end
end
function Mirror.isYou(model, hum)
    if model.Name == lp.Name or model.Name == tostring(lp.UserId) then return true end
    -- A copy of your character made while the overlay kept it hidden (see STAGE COPIES).
    if Mirror.Unmasked[model] then return true end
    local desc = hum:FindFirstChildOfClass("HumanoidDescription")
    if desc and not desc:GetAttribute("Lyra_Description") then
        local key = Mirror.descKey(desc)
        if key ~= "" and Mirror.OwnKeys[key] then return true end
    end
    return Mirror.sameLook(model, Mirror.OwnPieces)
end
-- Whose stand-in a model is: yours, or a script user's sharing a skin through Skin sync (named after them, or wearing
-- their own avatar's pieces, read from their character as the game made it). Returns a user id or nil.
Mirror.PeerPieces = setmetatable({}, {__mode = "k"})
function Mirror.whose(model, hum)
    if Mirror.isYou(model, hum) then return lp.UserId end
    for uid in pairs(Sync.pictureUsers()) do
        local player = Players:GetPlayerByUserId(uid)
        if player then
            if model.Name == player.Name or model.Name == tostring(uid) or (player.DisplayName ~= "" and model.Name == player.DisplayName) then return uid end
            local character = player.Character
            if character then
                local pieces = Mirror.PeerPieces[character]
                if not pieces then pieces = Mirror.pieces(character); Mirror.PeerPieces[character] = pieces end
                if pieces.Count >= 2 and Mirror.sameLook(model, pieces) then return uid end
            end
        end
    end
    return nil
end
-- Whether a model wears an avatar's pieces (see Mirror.pieces).
function Mirror.sameLook(model, own)
    if not own then return false end
    local pieces = Mirror.pieces(model)
    local shared, accessories = 0, 0
    for key, kind in pairs(pieces.Set) do
        if own.Set[key] then
            shared = shared + 1
            if kind == "acc" then accessories = accessories + 1 end
        end
    end
    if shared >= 3 and accessories >= 2 and shared >= math.min(pieces.Count, own.Count) * 0.6 then return true end
    -- An avatar with few accessories (a hat, a shirt and pants): the model wears every piece of it and little else.
    return own.Count >= 2 and shared == own.Count and shared >= pieces.Count * 0.6
end
-- A model joined to a player's character (or held in a tool) is part of that character: resizing or moving its parts
-- would move the character too. Prison Life's guns join such a model to your character while reloading, and dressing
-- it threw the character upside down. A model joined to anything else (a lobby pedestal) is still a stand-in.
function Mirror.onPlayer(part)
    if not part then return false end
    if part:FindFirstAncestorOfClass("Tool") then return true end
    local model = part:FindFirstAncestorOfClass("Model")
    while model do
        if Players:GetPlayerFromCharacter(model) then return true end
        model = model:FindFirstAncestorOfClass("Model")
    end
    return false
end
function Mirror.joined(model)
    if model:FindFirstAncestorOfClass("Tool") then return true end
    for _, part in ipairs(model:GetDescendants()) do
        if part:IsA("BasePart") then
            local okRoot, root = pcall(function() return part.AssemblyRootPart end)
            if okRoot and root and root ~= part and not root:IsDescendantOf(model) and Mirror.onPlayer(root) then return true end
            local okJoints, joints = pcall(function() return part:GetJoints() end)
--: YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
            for _, joint in ipairs(okJoints and joints or {}) do
                local a, b
                if joint:IsA("JointInstance") or joint:IsA("WeldConstraint") then a, b = joint.Part0, joint.Part1
                elseif joint:IsA("Constraint") then
                    a = joint.Attachment0 and joint.Attachment0.Parent; b = joint.Attachment1 and joint.Attachment1.Parent
                end
                for _, other in ipairs({a, b}) do
                    if other and other ~= part and not other:IsDescendantOf(model) and Mirror.onPlayer(other) then return true end
                end
            end
        end
    end
    return false
end
-- The model's Humanoid when it may be a stand-in: alive, not a player's character (nor inside one), not the copier's
-- own models, a standard R6 or R15 body. With visual-only, a copy of your body where you stand belongs to the overlay.
-- skipJoined: leave out the check of every part's joints (Mirror.check makes it once it knows whose the model is).
function Mirror.eligible(model, skipJoined)
    if not model:IsA("Model") or not model.Parent then return nil end
    local hum = model:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then return nil end
    local char = lp.Character
    if model == char or (char and model:IsDescendantOf(char)) then return nil end
    for _, holder in ipairs({Overlay.Folder, UI.Gui, UI.InspectOverlay, UI.InspectView}) do
        if holder and model:IsDescendantOf(holder) then return nil end
    end
    local cursor = model
    while cursor and cursor ~= game do
        if cursor:IsA("Model") and Players:GetPlayerFromCharacter(cursor) then return nil end
        cursor = cursor.Parent
    end
    if not F.getTrueRigType(model) then return nil end
    if not skipJoined and Mirror.joined(model) then return nil end
    if Overlay.visualOnly() and char then
        -- "near": it may leave later (a stage copy made where you stand), so it is looked at again. Only a copy the
        -- overlay hides (it shows at least three body parts where you stand, see Overlay.bodies) is the overlay's: one
        -- showing less, such as the arms Evade shows in first person while you run, is dressed as a stand-in, and again
        -- whenever your avatar changes. Left to the overlay, it kept your own arms, or the first avatar it was dressed
        -- in while it stood elsewhere.
        local entry = Overlay.Active[char]
        if entry and (entry.Target == model or table.find(entry.Extra or {}, model)) then return nil, "near" end
        local root = Overlay.rootOf(char)
        if root and Overlay.nearBody(model, root.Position) and not Mirror.Dressed[model] and Overlay.shows(model, root.Position, entry) then
            return nil, "near"
        end
    end
    return hum
end
function Mirror.queue(model, delay)
    if Mirror.Queued[model] then return end
    Mirror.Queued[model] = true
    task.delay(delay or 0.4, function()
        if not App.alive() then return end
        table.insert(Mirror.Queue, model)
        Mirror.run()
    end)
end
-- A model still being built (pieces arriving, joints not made yet) is looked at again: a few times while its body
-- is incomplete, once when it did not look like you yet (so games full of NPCs are not checked over and over).
function Mirror.retry(model, limit)
    local tries = (Mirror.Tries[model] or 0) + 1
    Mirror.Tries[model] = tries
    if tries <= (limit or 3) then Mirror.queue(model, 1.5) end
end
-- One model at a time, never while an avatar is being applied to your character.
function Mirror.run()
    if Mirror.Running then return end
    Mirror.Running = true
    task.spawn(function()
        while App.alive() and #Mirror.Queue > 0 do
            while App.Busy and App.alive() do task.wait(0.25) end
            local model = table.remove(Mirror.Queue, 1)
            Mirror.Queued[model] = nil
            pcall(Mirror.check, model)
        end
        Mirror.Running = false
    end)
end
Mirror.Seen = setmetatable({}, {__mode = "k"})
function Mirror.check(model)
    local known = Mirror.Known[model] ~= nil
    -- A model not known to show anyone is first asked whose it is: the closer look at every part's joints is only for
    -- models that show you or a script user (games full of NPCs spent a lot of time there).
    local hum, why = Mirror.eligible(model, not known)
    if not hum then
        if why == "near" then Mirror.retry(model, 4)
        elseif model.Parent and not Mirror.Known[model] and model:IsA("Model") and model:FindFirstChildOfClass("Humanoid") and not F.getTrueRigType(model) then Mirror.retry(model) end
        return
    end
    if not known then
        Mirror.Seen[model] = true
        if not Mirror.Unmasked[model] then
            local ok, copy = pcall(Overlay.unmaskCopy, model)
            if ok and copy then Mirror.Unmasked[model] = true end
        end
        local who = Mirror.whose(model, hum)
        if not who then Mirror.retry(model, 1); return end
        if Mirror.joined(model) then return end
        Mirror.Known[model] = who
        Mirror.follow(model)
        pcall(Overlay.forget, model)
        if App.tracing() then
            App.trace(string.format("Stand-in found: %s (%s, %s%s)", App.traceName(model), who == lp.UserId and "yours" or "a script user's",
                tostring(F.getTrueRigType(model)), Mirror.Unmasked[model] and ", a copy of your hidden body" or ""))
        end
    end
    Mirror.dress(model)
end
-- A script user's skin arrived, changed or went: their stand-ins follow it, and models seen before their skin
-- arrived are looked at again.
function Mirror.refreshUser(uid)
    if not App.alive() then return end
    for model, who in pairs(Mirror.Known) do if who == uid and model.Parent then Mirror.queue(model, 0) end end
    if Sync.pictureUsers()[uid] then
        for model in pairs(Mirror.Seen) do if model.Parent and not Mirror.Known[model] then Mirror.Tries[model] = nil; Mirror.queue(model, 0.2) end end
    end
end
-- A game that changes a stand-in it already showed (a new outfit in a lobby) gets it dressed again, at most three
-- times a minute.
function Mirror.follow(model)
    local connection
    connection = model.ChildAdded:Connect(function(child)
        if not App.alive() then connection:Disconnect(); return end
        if child:GetAttribute("Copier_CopiedItem") or child:GetAttribute("Lyra_VisualFor") then return end
        if not (child:IsA("Accessory") or child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic")) then return end
        local record = Mirror.Dressed[model]
        if not record then return end
        local now = os.clock()
        record.Changes = record.Changes or {}
        for i = #record.Changes, 1, -1 do if now - record.Changes[i] > 60 then table.remove(record.Changes, i) end end
        if #record.Changes >= 3 then return end
        table.insert(record.Changes, now)
        record.Snapshot = nil
        Mirror.queue(model, 0.8)
    end)
    RegisterConnection(connection)
end
-- Yields. The avatar model to dress stand-ins of this rig in (the one built for your character when it matches).
function Mirror.source(snapshot, rig)
    for _, row in ipairs(Mirror.Sources) do if row.Snapshot == snapshot and row.Rig == rig then return row.Model end end
    local model
    local cache = App.ModelCache
    if cache and cache.Snapshot == snapshot and cache.Rig == rig then pcall(function() model = cache.Model:Clone() end) end
    if not model then
        local decoded, desc = pcall(Codec.decode, snapshot.Data)
        if not decoded then return nil end
        local ok, made = pcall(Visual.model, snapshot.Data, desc, rig)
        pcall(function() desc:Destroy() end)
        if not ok or not made then return nil end
        model = made
    end
    table.insert(Mirror.Sources, {Snapshot = snapshot, Rig = rig, Model = model})
    while #Mirror.Sources > 6 do
        local old = table.remove(Mirror.Sources, 1)
        pcall(function() old.Model:Destroy() end)
    end
    return model
end
-- A model the physics does not move (in a menu view, or anchored as a lobby display) gets its parts placed from its
-- joints again, in the pose it has.
function Mirror.settle(model)
    if Mirror.joined(model) then return end
    local still = not model:IsDescendantOf(workspace)
    if not still then
        for _, part in ipairs(model:GetChildren()) do
            if part.Name ~= "HumanoidRootPart" and Appearance.isBody(part, model) and part.Anchored then still = true; break end
        end
    end
    if still then pcall(Rig.reachable, model, true) end
end
-- STAND-INS THE GAME HIDES OR FADES: a rhythm game keeps a copy of you on its stage and fades it in and out, a lobby
-- hides its display until you open a menu, a first-person body has no head. Dressing a stand-in made every body part
-- solid again and added items the game knows nothing about, so a hidden copy appeared as a ghost and a faded one kept
-- solid hair and hats. Now what the game gives each body part of a stand-in is kept and followed: the avatar's own
-- transparency is faded as much, and so is everything the copier put on that part (items, face, limb copies). The
-- game's values go back with the stand-in's own look.
function Mirror.fadeStop(fade)
    for _, connection in ipairs(fade and fade.Connections or {}) do connection:Disconnect() end
    if fade then fade.Connections = {} end
end
-- Before the stand-in is dressed: the transparency the game has on each body part (kept from the last time while it
-- is dressed, since the parts then carry the copier's values).
function Mirror.fadeBegin(model, record)
    local old = record and record.Fade
    Mirror.fadeStop(old)
    local fade = {Game = setmetatable({}, {__mode = "k"}), Own = setmetatable({}, {__mode = "k"}), Pending = setmetatable({}, {__mode = "k"}), Connections = {}}
    for _, part in ipairs(model:GetChildren()) do
        if Appearance.isBody(part, model) and part.Name ~= "HumanoidRootPart" then
            local value = old and old.Game[part]
            if value == nil then
                value = part:GetAttribute("Lyra_BeforeOverlay")
                if type(value) ~= "number" then value = part.Transparency end
                if isMask(value) then value = 0 end
            end
            fade.Game[part] = value
        end
    end
    return fade
end
function Mirror.fadeUpdate(model, fade)
    if not model.Parent or not App.alive() then return end
    local now = os.clock()
    if now - (fade.WindowAt or 0) > 3 then fade.WindowAt = now; fade.Writes = 0 end
    -- A part the avatar hides itself (a headless head) always reads 1, so what the game does to it cannot be seen: it
    -- follows the whole body (the least hidden part that can be read).
    local body, count, factors = 1, 0, {}
    for part, own in pairs(fade.Own) do
        if part.Parent == model and own < 0.99 then
            body = math.min(body, math.clamp(fade.Game[part] or 0, 0, 1)); count = count + 1
        end
    end
    if count == 0 or body < 0.005 then body = 0 end
    for part, own in pairs(fade.Own) do
        if part.Parent == model then
            local f = own < 0.99 and math.clamp(fade.Game[part] or 0, 0, 1) or body
            if f < 0.005 then f = 0 end
            factors[part.Name] = f
            -- A part the game keeps writing (a fade on a limb the avatar hides) is not fought over: at most 60 writes
            -- in 3 seconds for the whole stand-in, then it is looked at again.
            local wanted = 1 - (1 - own) * (1 - f)
            if math.abs(part.Transparency - wanted) > 0.005 then
                if (fade.Writes or 0) < 60 then
                    fade.Writes = (fade.Writes or 0) + 1; fade.Pending[part] = wanted
                    pcall(function() part.Transparency = wanted end)
                elseif not fade.Retry then
                    fade.Retry = true
                    task.delay(3.1 - (now - (fade.WindowAt or now)), function() fade.Retry = false; if Mirror.fadeOf(model) == fade then pcall(Mirror.fadeUpdate, model, fade) end end)
                end
            end
            for _, child in ipairs(part:GetChildren()) do
                if child:IsA("Decal") and child:GetAttribute("Lyra_CopiedSurface") then pcall(Cloak.fadeOne, child, f) end
            end
        end
    end
    if App.tracing() and fade.Traced ~= body then
        fade.Traced = body
        App.trace(string.format("Stand-in %s: the game shows its body at transparency %.2f", App.traceName(model), body))
    end
    for _, item in ipairs(model:GetChildren()) do
        if item:IsA("Accessory") and item:GetAttribute("Copier_CopiedItem") then
            Cloak.fadeAll(item, factors[Cloak.mountOf(item, model) or ""] or body)
        elseif item:IsA("BasePart") and item:GetAttribute("Lyra_VisualFor") then
            Cloak.fadeAll(item, factors[tostring(item:GetAttribute("Lyra_VisualFor"))] or body)
        end
    end
end
function Mirror.fadeOf(model)
    local record = Mirror.Dressed[model]
    return record and record.Fade or nil
end
-- After the stand-in is dressed: the avatar's own transparency of each part is read, and the game's later changes are
-- followed. known: the avatar's own values when the parts were not dressed again (they then carry faded values).
function Mirror.fadeWatch(model, fade, known)
    local function schedule()
        if fade.Scheduled then return end
        fade.Scheduled = true
        task.defer(function() fade.Scheduled = false; if Mirror.fadeOf(model) == fade then pcall(Mirror.fadeUpdate, model, fade) end end)
    end
    for part in pairs(fade.Game) do
        if part.Parent == model then
            local own = known and known[part]
            if own == nil then own = part.Transparency end
            fade.Own[part] = isMask(own) and Cloak.Mask or own
            table.insert(fade.Connections, part:GetPropertyChangedSignal("Transparency"):Connect(function()
                local value = part.Transparency
                local pending = fade.Pending[part]
                fade.Pending[part] = nil
                if pending and math.abs(value - pending) < 1e-4 then return end
                fade.Game[part] = value
                schedule()
            end))
        end
    end
    -- Items put on it later follow at once.
    table.insert(fade.Connections, model.ChildAdded:Connect(function(child)
        if child:GetAttribute("Copier_CopiedItem") or child:GetAttribute("Lyra_VisualFor") then schedule() end
    end))
    pcall(Mirror.fadeUpdate, model, fade)
end
-- The stand-in has its own look back: each body part gets what the game has on it now.
function Mirror.fadeRestore(model, fade)
    Mirror.fadeStop(fade)
    -- A part the avatar hid itself may have missed the game hiding it: it is at least as hidden as the whole body.
    local body, count = 1, 0
    for part, own in pairs(fade.Own) do
        if part.Parent == model and own < 0.99 then body = math.min(body, math.clamp(fade.Game[part] or 0, 0, 1)); count = count + 1 end
    end
    if count == 0 then body = 0 end
    for part, value in pairs(fade.Game) do
        if (fade.Own[part] or 0) >= 0.99 then value = math.max(value, body) end
        if part.Parent == model and math.abs(part.Transparency - value) > 1e-4 then pcall(function() part.Transparency = value end) end
    end
end
function Mirror.dress(model)
    local record = Mirror.Dressed[model]
    -- Yours follows the avatar you wear; a script user's follows their synced skin.
    local owner = Mirror.Known[model]
    local peer = owner ~= nil and owner ~= true and owner ~= lp.UserId
    local function current() if peer then return Sync.snapshot(owner) end; return App.Current end
    local wanted = peer and current() ~= nil or (not peer and Mirror.wanted())
    -- The stand-in gets its own look back: the drawn avatar comes off, or its body is rebuilt as the game made it.
    local function undress()
        if not record then return end
        -- Forgotten first: the game's own pieces coming back must not look like a change by the game.
        Mirror.Dressed[model] = nil
        if record.Drawn then Overlay.clear(model)
        elseif model.Parent and record.Original then
            Mirror.fadeStop(record.Fade)
            local report = Appearance.apply(model, record.Original, {Original = true, Mirror = true})
            for _, row in ipairs(report.Items) do pcall(function() row.Template:Destroy() end) end
            Appearance.releaseGeometry(model:FindFirstChildOfClass("Humanoid"))
            if record.Fade then Mirror.fadeRestore(model, record.Fade) end
            Mirror.settle(model)
        end
        if record.Original then pcall(function() record.Original:Destroy() end) end
        record = nil
    end
    if not wanted then undress(); return end
    local snapshot = current()
    local rig = F.getTrueRigType(model)
    -- R15 AVATARS IN R6 GAMES: while your avatar is drawn as R15 over your R6 character, your R6 stand-ins (a copy of
    -- you a menu leaves standing, A Bizarre Run's stand menu) get it drawn over them the same way.
    local draw = not peer and Overlay.Auto == true and rig == Enum.HumanoidRigType.R6
    if record and record.Snapshot == snapshot and (record.Drawn == true) == draw then return end
    if not rig or #Appearance.rigMissing(model) > 0 then Mirror.retry(model); return end
    if draw then
        if record and not record.Drawn then undress() end
        local source = Mirror.source(snapshot, Enum.HumanoidRigType.R15)
        if not source or not App.alive() or not model.Parent or snapshot ~= current() then return end
        local copied, copy = pcall(function() return source:Clone() end)
        if not copied or not copy then return end
        Overlay.prepare(copy)
        Overlay.attach(model, copy, false, "standin")
        Mirror.Dressed[model] = {Snapshot = snapshot, Drawn = true, Changes = record and record.Changes}
        return
    end
    if record and record.Drawn then undress() end
    -- A copy of the stand-in as the game made it, to give it its own look back later.
    local original = record and record.Original
    if not original then
        local archivable = model.Archivable
        pcall(function() model.Archivable = true; original = model:Clone() end)
        pcall(function() model.Archivable = archivable end)
        if not original then return end
        for _, item in ipairs(original:GetDescendants()) do
            if item:IsA("BaseScript") or item:IsA("ModuleScript") then pcall(function() item:Destroy() end) end
        end
    end
    local source = Mirror.source(snapshot, rig)
    if not source or not App.alive() or not model.Parent or snapshot ~= current() then
        if not record then pcall(function() original:Destroy() end) end
        return
    end
    -- What the game has on each body part goes on being followed (see STAND-INS THE GAME HIDES OR FADES).
    local before = record and record.Fade
    local fade = Mirror.fadeBegin(model, record)
    local applied, report = pcall(Appearance.apply, model, source, {Mirror = true})
    if not applied then
        -- Not dressed again: a stand-in dressed before keeps being followed as it is.
        if before then record.Fade = fade; Mirror.fadeWatch(model, fade, before.Own)
        elseif not record then pcall(function() original:Destroy() end) end
        error(report, 0)
    end
    for _, row in ipairs(report.Items) do pcall(function() row.Template:Destroy() end) end
    Mirror.Dressed[model] = {Snapshot = snapshot, Original = original, Changes = record and record.Changes, Fade = fade}
    Mirror.fadeWatch(model, fade)
    Mirror.settle(model)
end
-- After every change of your look: every stand-in follows it, and so do your pictures.
function Mirror.refresh()
    if not App.alive() then return end
    for index = #Mirror.Sources, 1, -1 do
        local row = Mirror.Sources[index]
        if row.Snapshot ~= App.Current and not row.Snapshot.SyncUser then pcall(function() row.Model:Destroy() end); table.remove(Mirror.Sources, index) end
    end
    for model, who in pairs(Mirror.Known) do if model.Parent and (who == true or who == lp.UserId) then Mirror.queue(model, 0) end end
    Thumbs.refresh()
    -- The name Roblox's menus show follows the profile you wear (see YOUR NAME).
    pcall(Ident.refresh)
end
function Mirror.watch()
    if Mirror.Watching then return end
    Mirror.Watching = true
    local function added(item)
        local class = item.ClassName
        if class == "Humanoid" then
            local model = item.Parent
            if model then Mirror.queue(model, 0.4) end
        elseif class == "ImageLabel" or class == "ImageButton" then
            Thumbs.consider(item)
        end
    end
    RegisterConnection(workspace.DescendantAdded:Connect(added))
    local gui = lp:FindFirstChildOfClass("PlayerGui")
    if gui then RegisterConnection(gui.DescendantAdded:Connect(added)) end
    pcall(Mirror.learn, lp.Character)
    task.spawn(function()
        -- Your profile avatar, for stand-ins a game builds from it.
        pcall(function()
            local desc = API.description(lp.UserId)
            local key = Mirror.descKey(desc)
            if key ~= "" then Mirror.OwnKeys[key] = true end
            desc:Destroy()
        end)
        -- What is already there: walked a few hundred instances per frame, a moment after the script starts. Listing a big
        -- map's whole workspace at once (hundreds of thousands of instances) froze phones as the script started.
        task.wait(2)
        local stack, count, slice = {}, 0, os.clock()
        for _, root in ipairs({gui, workspace}) do
            local ok, list = pcall(function() return root:GetChildren() end)
            if ok then table.insert(stack, {list, 1}) end
        end
        while #stack > 0 do
            if not App.alive() then return end
            local top = stack[#stack]
            local item = top[1][top[2]]
            if item == nil then table.remove(stack)
            else
                top[2] = top[2] + 1
                local class = item.ClassName
                if class == "Humanoid" or class == "ImageLabel" or class == "ImageButton" then pcall(added, item) end
                local ok, list = pcall(function() return item:GetChildren() end)
                if ok and #list > 0 then table.insert(stack, {list, 1}) end
                -- At most about two milliseconds of every frame.
                count = count + 1
                if count % 50 == 0 and os.clock() - slice > 0.002 then task.wait(); slice = os.clock() end
            end
        end
    end)
end

-- YOUR PICTURE: games show your avatar's picture (leaderboards, player cards, name tags, the list of a round's
-- players). While a copied avatar is on, those pictures show it: the copied profile's own Roblox picture when the
-- avatar is that profile as it is, else a 3D view of the avatar posed like Roblox's pictures. On your screen only.
Thumbs.Labels = setmetatable({}, {__mode = "k"})
Thumbs.MenuLabels = setmetatable({}, {__mode = "k"})
Thumbs.Watched = setmetatable({}, {__mode = "k"})
Thumbs.WatchCount = 0
-- {Kind, W, H, User} when an image is a picture of your own avatar or of a script user sharing a skin through Skin
-- sync (a headshot, bust or full avatar), else nil.
function Thumbs.parse(image)
    local info = Thumbs.read(image)
    if not info or (info.User ~= lp.UserId and not Sync.pictureUsers()[info.User]) then return nil end
    return info
end
-- Pictures of a user remember which user they show, so they can change when that user's skin arrives.
Thumbs.Seen = setmetatable({}, {__mode = "k"})
function Thumbs.refreshUser(uid)
    for label, user in pairs(Thumbs.Seen) do
        if user == uid and label.Parent then pcall(Thumbs.changed, label) end
    end
end
-- {Kind, W, H, User} for any avatar picture, else nil.
function Thumbs.read(image)
    if type(image) ~= "string" or image == "" then return nil end
    local lower = image:lower()
    local id, kind, w, h
    if lower:find("rbxthumb://", 1, true) then
        kind = image:match("[?&/]type=(%w+)"); id = image:match("[?&]id=(%d+)")
        w = image:match("[?&]w=(%d+)"); h = image:match("[?&]h=(%d+)")
    elseif lower:find("roblox.com", 1, true) and lower:find("userid=", 1, true) then
        id = lower:match("userid=(%d+)")
        kind = lower:find("headshot", 1, true) and "AvatarHeadShot" or lower:find("bust", 1, true) and "AvatarBust" or "Avatar"
        w = lower:match("width=(%d+)") or lower:match("[?&]x=(%d+)"); h = lower:match("height=(%d+)") or lower:match("[?&]y=(%d+)")
    end
    if not tonumber(id) then return nil end
    if kind ~= "AvatarHeadShot" and kind ~= "AvatarBust" and kind ~= "Avatar" then return nil end
    local fallback = kind == "Avatar" and 420 or 150
    return {Kind = kind, W = tonumber(w) or fallback, H = tonumber(h) or fallback, User = tonumber(id)}
end
-- The same picture of another user: only the user id changes, so its kind, size and options (a round crop such as
-- filters=circular) stay as Roblox asked for them.
function Thumbs.swapUser(url, userId)
    if type(url) ~= "string" then return nil end
    local out, count = url:gsub("([?&]id=)%d+", "%1" .. tostring(userId), 1)
    if count == 0 then out, count = url:gsub("([Uu][Ss][Ee][Rr][Ii][Dd]=)%d+", "%1" .. tostring(userId), 1) end
    return count > 0 and out or nil
end
-- The profile whose own picture shows the avatar being worn: a profile copied as it is (not edited, not a saved skin).
function Thumbs.userFor(snapshot)
    if not snapshot or snapshot.Original or snapshot.Catalog or snapshot.Pose or type(snapshot.Data) ~= "table" then return nil end
    local data = snapshot.Data
    if type(data.Tweaks) == "table" and next(data.Tweaks) ~= nil then return nil end
    -- A held gear or a background is drawn with the avatar (see HELD ITEM AND BACKGROUND).
    if Codec.id(data.Gear) or Codec.id(data.Background) then return nil end
    if not snapshot.LookKey and not data.Visual and Codec.id(snapshot.Id) then return Codec.id(snapshot.Id) end
    return Thumbs.sourceUser(snapshot)
end
-- ROBLOX'S OWN PICTURE: a profile worn as it is shows Roblox's own picture of it, drawn by Roblox with its pose, its
-- gear and the gear's effects. A saved skin or a Community skin that is still exactly the avatar of the profile it
-- came from (the one it was copied from, or the account that posted it) shows that same picture: its items are
-- compared once, in the background, with what that profile wears now. A skin that differs (another item, a pose kept
-- for pictures) is drawn in 3D.
Thumbs.Matches = setmetatable({}, {__mode = "k"})
function Thumbs.sourceUser(snapshot)
    local id = Codec.id(snapshot.FromUser) or Codec.id(snapshot.ThumbId)
    local visual = snapshot.Data.Visual
    if not id or (type(visual) == "table" and type(visual.Pose) == "table" and next(visual.Pose)) then return nil end
    local match = Thumbs.Matches[snapshot]
    if match ~= nil then return match or nil end
    Thumbs.Matches[snapshot] = false
    task.spawn(function()
        local ok, same = pcall(function()
            local mine = Codec.decode(snapshot.Data)
            local key = App.lookKey(mine); mine:Destroy()
            local theirs = API.description(id)
            local other = App.lookKey(theirs); theirs:Destroy()
            return key ~= nil and key == other
        end)
        if not (ok and same) then return end
        Thumbs.Matches[snapshot] = id
        App.devNote("This skin is still the avatar of profile " .. tostring(id) .. ": its pictures are Roblox's own.")
        if App.alive() and App.Current == snapshot then pcall(UI.refreshPictures) end
    end)
    return nil
end
function Thumbs.ours(label)
    -- A menu card's background (see UI.squareBackground) sits among Roblox's pictures.
    if label.Name:find("^Lyra") then return true end
    for _, holder in ipairs({UI.Gui, UI.InspectOverlay}) do
        if holder and label:IsDescendantOf(holder) then return true end
    end
    return false
end
function Thumbs.consider(label)
    if Thumbs.ours(label) then return end
    if not Thumbs.Watched[label] and Thumbs.WatchCount < 4000 then
        Thumbs.Watched[label] = true; Thumbs.WatchCount = Thumbs.WatchCount + 1
        pcall(function()
            RegisterConnection(label:GetPropertyChangedSignal("Image"):Connect(function() if App.alive() then Thumbs.changed(label) end end))
        end)
    end
    Thumbs.changed(label)
end
function Thumbs.changed(label)
    local record = Thumbs.Labels[label]
    local image = label.Image
    if record and record.Written and image == record.Written then return end
    if record and record.Forced then
        -- A picture found by the @username next to it: kept while that is still you.
        record.Written = nil
        if Thumbs.nearUsername(label) then record.Original = image; task.spawn(Thumbs.apply, label, record)
        else Thumbs.Labels[label] = nil; Thumbs.restore(label, record, true) end
        return
    end
    local seen = Thumbs.read(image)
    Thumbs.Seen[label] = seen and seen.User or nil
    local info = Thumbs.parse(image)
    if not info then
        -- The game put someone else's picture (or anything else) there: it stays, and the label is let go.
        if record then Thumbs.Labels[label] = nil; Thumbs.restore(label, record, true) end
        return
    end
    if record then record.Original = image; record.Info = info; record.Written = nil
    else record = {Original = image, Info = info, Core = label:IsDescendantOf(game:GetService("CoreGui")), Menu = Thumbs.MenuLabels[label]}; Thumbs.Labels[label] = record end
    task.spawn(Thumbs.apply, label, record)
end
-- Roblox's own elements under a frame, without what the script put there (its names start with Lyra): a 3D picture
-- holds a whole avatar, hundreds of parts, which made one small card count as a long list, so your names on it went
-- back to Roblox's once the picture was drawn. nil when there are more than limit.
function Thumbs.elements(root, limit)
    local found, stack = {}, {root}
    while #stack > 0 do
        local node = table.remove(stack)
        local ok, children = pcall(function() return node:GetChildren() end)
        for _, child in ipairs(ok and children or {}) do
            if not child.Name:find("^Lyra") then
                found[#found + 1] = child
                if #found > limit then return nil end
                stack[#stack + 1] = child
            end
        end
    end
    return found
end
-- THE ROBLOX MENU'S PROFILE PAGE (tap a player in the Players page's list view): your picture there may be loaded from
-- Roblox's servers by an address that does not name you, so it is found as the largest square web picture next to your
-- @username, and followed like the others (as a head picture). Your names there follow YOUR NAME.
function Thumbs.nearUsername(label)
    local cursor = label.Parent
    for _ = 1, 4 do
        if not cursor or cursor:IsA("LayerCollector") then return false end
        local items = Thumbs.elements(cursor, 160)
        if not items then return false end
        for _, item in ipairs(items) do
            if (item:IsA("TextLabel") or item:IsA("TextButton")) and Ident.raw(item) == "@" .. lp.Name then return true end
        end
        cursor = cursor.Parent
    end
    return false
end
function Thumbs.profilePicture(label)
    if not label.Parent or Ident.raw(label) ~= "@" .. lp.Name then return end
    local cursor = label.Parent
    for _ = 1, 4 do
        if not cursor or cursor:IsA("LayerCollector") then return end
        local items = Thumbs.elements(cursor, 160)
        if not items then return end
        local best, area = nil, 0
        for _, item in ipairs(items) do
            if (item:IsA("ImageLabel") or item:IsA("ImageButton")) and item.Name ~= "LyraMenuAvatar" and not Thumbs.ours(item) then
                local record = Thumbs.Labels[item]
                local image = record and record.Original or item.Image
                local info = Thumbs.read(image)
                -- Already followed by its address.
                if info and info.User == lp.UserId then return end
                local size = item.AbsoluteSize
                local web = image:find("^https?://") ~= nil or image:find("rbxcdn", 1, true) ~= nil
                if not info and web and size.X >= 40 and math.abs(size.X - size.Y) <= size.X * 0.2 and size.X * size.Y > area then best, area = item, size.X * size.Y end
            end
        end
        if best then Thumbs.force(best); return end
        cursor = cursor.Parent
    end
end
function Thumbs.force(label)
    if Thumbs.Labels[label] then return end
    local record = {Original = label.Image, Info = {Kind = "AvatarHeadShot", W = 420, H = 420, User = lp.UserId}, Core = true, Forced = true, Menu = true}
    Thumbs.Labels[label] = record
    if not Thumbs.Watched[label] then
        Thumbs.Watched[label] = true; Thumbs.WatchCount = Thumbs.WatchCount + 1
        pcall(function()
            RegisterConnection(label:GetPropertyChangedSignal("Image"):Connect(function() if App.alive() then Thumbs.changed(label) end end))
        end)
    end
    task.spawn(Thumbs.apply, label, record)
end
-- The rest of the Roblox menu (its profile page and other pages): avatar pictures and your names added there are
-- followed like the leaderboard's. Your names in the Players page are changed the moment its cards are built (also
-- when the list builds them again on every open), so Roblox's own never shows; its pictures are handled by
-- UI.patchMenuAvatar, run at once when a card is added.
function Thumbs.watchMenu(page)
    local rgui = game:GetService("CoreGui"):FindFirstChild("RobloxGui")
    if not rgui or not page then return end
    Thumbs.PeoplePage = page
    local root = page
    while root.Parent and root.Parent ~= rgui do root = root.Parent end
    if root.Parent ~= rgui or Thumbs.MenuRoot == root then return end
    Thumbs.MenuRoot = root
    local function added(item)
        local people = Thumbs.PeoplePage and Thumbs.PeoplePage.Parent and item:IsDescendantOf(Thumbs.PeoplePage)
        if people then
            if item:IsA("TextLabel") or item:IsA("TextButton") then Ident.consider(item)
            elseif item:IsA("ImageLabel") and (item.Name == "AvatarThumbnail" or Thumbs.read(item.Image)) then UI.queueMenuPatch() end
            return
        end
        if item:IsA("ImageLabel") or item:IsA("ImageButton") then
            -- Only avatar pictures: the menu has many icons.
            if Thumbs.read(item.Image) then Thumbs.MenuLabels[item] = true; Thumbs.consider(item) end
        elseif item:IsA("TextLabel") or item:IsA("TextButton") then
            Ident.consider(item)
            if Ident.raw(item) == "@" .. lp.Name then
                UI.ProfileName = item
                task.delay(0.3, function() if App.alive() and Store.Settings.MenuAvatar then pcall(Thumbs.profilePicture, item) end end)
            end
        end
    end
    RegisterConnection(root.DescendantAdded:Connect(function(item) if App.alive() then pcall(added, item) end end))
    local ok, items = pcall(function() return root:GetDescendants() end)
    for _, item in ipairs(ok and items or {}) do pcall(added, item) end
end
-- The Roblox menu is followed from the start of the script, so even its first opening shows your names already
-- changed: its Players page is found where it is, or as soon as Roblox builds it.
function Thumbs.findMenu()
    if Thumbs.MenuFinding then return end
    Thumbs.MenuFinding = true
    local rgui = game:GetService("CoreGui"):FindFirstChild("RobloxGui")
    if not rgui then return end
    local page = rgui:FindFirstChild("peoplepage", true)
    if page then Thumbs.watchMenu(page) end
    RegisterConnection(rgui.DescendantAdded:Connect(function(item)
        if App.alive() and item.Name == "peoplepage" then pcall(Thumbs.watchMenu, item) end
    end))
end
-- Pictures in Roblox's own menus (the leaderboard) follow "Show my avatar in the Roblox menu"; the game's pictures
-- follow "Show my avatar on the game's copies of me".
function Thumbs.wanted(record)
    if record and record.Core then return Store.Settings.MenuAvatar ~= false and App.Current ~= nil and not App.Current.Original end
    return Mirror.wanted()
end
-- THE ROBLOX LEADERBOARD: Roblox's own player list. Tapping your name opens a card with your picture and name; on
-- your screen it shows the avatar you wear (the copied profile's own picture when the avatar is that profile as it
-- is), and the name and badge of YOUR NAME. "Examine Avatar" on that card opens Roblox's panel on what you wear, and
-- on a script user's card, on the skin they share.
Thumbs.CoreButtons = setmetatable({}, {__mode = "k"})
-- Roblox builds its leaderboard again when a game turns it off and back on (or turns the top bar off and on): the new
-- one is followed as well, however late in the game it comes.
function Thumbs.followCoreList(list)
    if not App.alive() or not list or Thumbs.CoreList == list then return end
    Thumbs.CoreList = list
    local function added(item)
        if item:IsA("ImageLabel") or item:IsA("ImageButton") then Thumbs.consider(item) end
        if item:IsA("TextLabel") or item:IsA("TextButton") then Ident.consider(item) end
        if item:IsA("GuiButton") then Thumbs.hookCoreButton(item) end
    end
    RegisterConnection(list.DescendantAdded:Connect(function(item) if App.alive() and Thumbs.CoreList == list then pcall(added, item) end end))
    local ok, items = pcall(function() return list:GetDescendants() end)
    for _, item in ipairs(ok and items or {}) do pcall(added, item) end
end
function Thumbs.watchCore()
    if Thumbs.CoreWatching then return end
    Thumbs.CoreWatching = true
    local core = game:GetService("CoreGui")
    local function check(child)
        if child.Name == "PlayerList" and child:IsA("ScreenGui") then Thumbs.followCoreList(child) end
    end
    local heard = pcall(function()
        RegisterConnection(core.ChildAdded:Connect(function(child)
            if not App.alive() then return end
            pcall(check, child)
            -- Named after it is added, by some builds.
            task.defer(function() if App.alive() then pcall(check, child) end end)
        end))
    end)
    local current = core:FindFirstChild("PlayerList")
    if current then pcall(check, current) end
    if heard then return end
    -- Without that signal, CoreGui is looked at every few seconds.
    task.spawn(function()
        while App.alive() do
            local list = core:FindFirstChild("PlayerList")
            if list then pcall(check, list) end
            task.wait(3)
        end
    end)
end
-- Whose card of the leaderboard a button belongs to: a picture of you, or of a script user sharing a skin, in the
-- same small group of elements as the button tapped. Returns that user id, or nil for anyone else.
function Thumbs.coreCardUser(button)
    local peers = Sync.pictureUsers()
    local cursor = button.Parent
    for _ = 1, 6 do
        if not cursor or cursor:IsA("LayerCollector") then return nil end
        local items = Thumbs.elements(cursor, 200)
        if not items then return nil end
        for _, item in ipairs(items) do
            if item:IsA("ImageLabel") or item:IsA("ImageButton") then
                local user = Ident.imageUser(item)
                if user and (user == lp.UserId or peers[user]) then return user end
            end
        end
        cursor = cursor.Parent
    end
    return nil
end
-- A button of the leaderboard tapped on your card may be Examine Avatar: once Roblox's panel shows your profile, it
-- is pointed at what you wear, as from the Players page of the Roblox menu.
function Thumbs.hookCoreButton(button)
    if Thumbs.CoreButtons[button] then return end
    Thumbs.CoreButtons[button] = true
    RegisterConnection(button.Activated:Connect(function()
        if not App.alive() then return end
        local ok, who = pcall(Thumbs.coreCardUser, button)
        if not ok or not who then return end
        local mine = who == lp.UserId
        if mine and (not Store.Settings.MenuAvatar or not App.Current or App.Current.Original) then return end
        -- Only when the panel really opened (other buttons of the card do something else), and only when Roblox's own
        -- request was not heard (UI.watchInspect already answered it). A script user's card opens the panel on the
        -- skin they share (see THEIR PANEL).
        for _, delay in ipairs({0.4, 1.4}) do
            task.delay(delay, function()
                if not App.alive() or UI.inspectHeard() or not UI.inspectRoot() then return end
                if mine then UI.inspectWorn(true) elseif Sync.pictureUsers()[who] then UI.inspectWorn(true, nil, who) end
            end)
        end
    end))
end
-- Yields. The posed avatar model shared with the Roblox menu (built once per look).
function Thumbs.model()
    while Thumbs.Building do task.wait(0.05) end
    Thumbs.Building = true
    local ok, model, serial = pcall(UI.menuAvatarModel)
    Thumbs.Building = false
    if ok then return model, serial end
    return nil, nil
end
function Thumbs.apply(label, record)
    if not App.alive() or Thumbs.Labels[label] ~= record or not label.Parent then return end
    if record.Info.User ~= lp.UserId then
        -- Another script user's picture: their synced skin, posed (see SKIN SYNC PICTURES).
        local model, serial = Sync.pictureModel(record.Info.User)
        if not model or Thumbs.Labels[label] ~= record or not label.Parent then Thumbs.restore(label, record); return end
        if record.View and record.View.Parent == label and record.Serial == serial then return end
        if record.View then pcall(function() record.View:Destroy() end) end
        local ok, view = pcall(Thumbs.view, label, model, record.Info.Kind)
        if not ok then return end
        record.View = view; record.Serial = serial
        if record.Transparency == nil then record.Transparency = label.ImageTransparency end
        label.ImageTransparency = 1
        return
    end
    if not Thumbs.wanted(record) then Thumbs.restore(label, record); return end
    if record.Menu and not record.Corner and Thumbs.looksRound(label, record.Original, record.Info.Kind) then record.Corner = Thumbs.round(label) end
    local userId = Thumbs.userFor(App.Current)
    if userId then
        if record.View then pcall(function() record.View:Destroy() end); record.View = nil end
        if record.Transparency ~= nil then pcall(function() label.ImageTransparency = record.Transparency end); record.Transparency = nil end
        local info = record.Info
        local url = Thumbs.swapUser(record.Original, userId) or string.format("rbxthumb://type=%s&id=%d&w=%d&h=%d", info.Kind, userId, info.W, info.H)
        record.Written = url
        pcall(function() label.Image = url end)
        return
    end
    -- Any other look: the game's picture stays underneath, covered by a posed 3D view.
    if record.Written then record.Written = nil; pcall(function() label.Image = record.Original end) end
    local model, serial = Thumbs.model()
    if not model or Thumbs.Labels[label] ~= record or not label.Parent or not Thumbs.wanted(record) then return end
    if record.View and record.View.Parent == label and record.Serial == serial then return end
    if record.View then pcall(function() record.View:Destroy() end) end
--|YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
    local ok, view = pcall(Thumbs.view, label, model, record.Info.Kind)
    if not ok then return end
    record.View = view; record.Serial = serial
    if record.Transparency == nil then record.Transparency = label.ImageTransparency end
    label.ImageTransparency = 1
end
function Thumbs.restore(label, record, keepImage)
    if record.View then pcall(function() record.View:Destroy() end); record.View = nil end
    if record.Corner then pcall(function() record.Corner:Destroy() end); record.Corner = nil end
    if record.Transparency ~= nil then pcall(function() label.ImageTransparency = record.Transparency end); record.Transparency = nil end
    local written = record.Written
    record.Written = nil
    if written and not keepImage and label.Image == written then pcall(function() label.Image = record.Original end) end
end
function Thumbs.refresh()
    for label, record in pairs(Thumbs.Labels) do
        if label.Parent then task.spawn(Thumbs.apply, label, record) end
    end
end
function Thumbs.clearAll()
    for label, record in pairs(Thumbs.Labels) do pcall(Thumbs.restore, label, record) end
    table.clear(Thumbs.Labels)
end
-- The part of the avatar a picture shows: the whole body, or the head with what is worn on it (and the upper body
-- for a bust). Returns the centre and the height, width and depth to fit.
function Thumbs.frame(model, kind)
    local head = model:FindFirstChild("Head")
    if kind == "Avatar" or not (head and head:IsA("BasePart")) then
        local center, size = Pose.bounds(model)
        return center, size.Y, size.X, size.Z
    end
    local parts = {head}
    for _, accessory in ipairs(model:GetChildren()) do
        local handle = accessory:IsA("Accessory") and accessory:FindFirstChild("Handle")
        if handle and handle:IsA("BasePart") and (handle.Position - head.Position).Magnitude < head.Size.Magnitude * 1.5 then table.insert(parts, handle) end
    end
    if kind == "AvatarBust" then
        for _, name in ipairs({"UpperTorso", "Torso"}) do
            local torso = model:FindFirstChild(name)
            if torso and torso:IsA("BasePart") then table.insert(parts, torso) end
        end
    end
    local low, high = Vector3.new(math.huge, math.huge, math.huge), Vector3.new(-math.huge, -math.huge, -math.huge)
    for _, part in ipairs(parts) do
        local cf, half = part.CFrame, part.Size / 2
        for _, x in ipairs({-1, 1}) do
            for _, y in ipairs({-1, 1}) do
                for _, z in ipairs({-1, 1}) do
                    local point = cf * Vector3.new(half.X * x, half.Y * y, half.Z * z)
                    low = low:Min(point); high = high:Max(point)
                end
            end
        end
    end
    local size = high - low
    if kind == "AvatarHeadShot" then
        -- Like Roblox's head pictures: the face in the middle and about the same size whatever is worn. Long hair, a
        -- big hat or an R6 head (twice as wide as tall) used to zoom out until the body showed, off centre.
        local center = (low + high) / 2
        local focus = head.Position + (center - head.Position) * 0.35
        -- A classic head part is 2 x 1 x 1 but draws a head about as wide as it is tall.
        local headWide = math.min(head.Size.X, head.Size.Y * 1.3)
        local tall = math.clamp(size.Y, head.Size.Y * 1.5, head.Size.Y * 2.4)
        local wide = math.clamp(size.X, headWide * 1.1, headWide * 1.8)
        return focus, tall, wide, math.min(size.Z, head.Size.Z * 2)
    end
    return (low + high) / 2, size.Y, size.X, size.Z
end
-- ROUND PICTURES: the Roblox menu's round pictures (its list view, the profile page) are cut round by Roblox's picture
-- itself or by a style, and a picture of ours carries neither: it gets a round corner of its own. A picture is round
-- when it is square and its address asks for a round crop, a style tag says circle, or it is a head picture there.
function Thumbs.looksRound(label, image, kind)
    local size = label.AbsoluteSize
    if size.X <= 0 or math.abs(size.X - size.Y) > size.X * 0.15 then return false end
    if tostring(image or ""):lower():find("circular", 1, true) then return true end
    local ok, tags = pcall(function() return label:GetTags() end)
    for _, tag in ipairs(ok and tags or {}) do if tostring(tag):lower():find("circle", 1, true) then return true end end
    return kind == "AvatarHeadShot"
end
function Thumbs.round(target)
    if target:FindFirstChildOfClass("UICorner") then return nil end
    local corner = Instance.new("UICorner"); corner.Name = "LyraRound"; corner.CornerRadius = UDim.new(0.5, 0); corner.Parent = target
    return corner
end
-- The kind of a picture of the Roblox menu's Players page: the one its address names (rbxthumb, or a web address with
-- "headshot" or "bust" in it), else told by its shape: a small square picture is a head picture (the list's rows), a
-- larger one the whole body (the grid's cards). nil while Roblox has not laid it out yet.
function Thumbs.menuKind(label, info)
    if info then return info.Kind end
    local lower = tostring(label.Image):lower()
    if lower:find("headshot", 1, true) then return "AvatarHeadShot" end
    if lower:find("bust", 1, true) then return "AvatarBust" end
    local size = label.AbsoluteSize
    if size.X <= 0 or size.Y <= 0 then return nil end
    if size.X <= 100 and math.abs(size.X - size.Y) <= size.X * 0.15 then return "AvatarHeadShot" end
    return "Avatar"
end
-- How a picture over label would be drawn: its kind, round or not and its shape (not its size, which grows while the
-- menu opens). A view drawn for another key is drawn again.
function Thumbs.viewKey(label, kind, card)
    local size = label.AbsoluteSize
    local round = not card and Thumbs.looksRound(label, label.Image, kind)
    local shape = size.X > 0 and size.Y > 0 and string.format("%.1f", size.X / size.Y) or "none"
    return tostring(kind) .. "|" .. (round and "round" or "square") .. "|" .. shape
end
function Thumbs.view(label, model, kind, round)
    local view = Instance.new("ViewportFrame")
    view.Name = "LyraPicture"; view.Size = UDim2.fromScale(1, 1); view.BackgroundTransparency = 1; view.BorderSizePixel = 0
    view.ZIndex = label.ZIndex; view.Ambient = Color3.fromRGB(195, 186, 213); view.LightColor = Color3.fromRGB(255, 244, 233); view.LightDirection = Vector3.new(-1, -1, -1)
    local clone = model:Clone(); clone.Parent = view
    local focus, height, width, depth = Thumbs.frame(clone, kind)
    local size = label.AbsoluteSize
    local aspect = size.X > 0 and size.Y > 0 and math.clamp(size.X / size.Y, 0.4, 2.5) or 1
    local fit = math.max(height, width / aspect)
    local distance = (fit * 0.5 / math.tan(math.rad(15)) + depth * 0.5) * (kind == "Avatar" and 1.12 or 1.06)
    -- Roblox's full-body pictures turn the avatar slightly; head pictures look straight at it. Both face its front.
    local direction = UI.pictureDirection(clone, kind ~= "Avatar")
    local camera = Instance.new("Camera"); camera.FieldOfView = 30
    camera.CFrame = CFrame.lookAt(focus + direction * distance, focus)
    camera.Parent = view; view.CurrentCamera = camera
    local corner = label:FindFirstChildOfClass("UICorner"); if corner then corner:Clone().Parent = view
    elseif round or tostring(label.Image):lower():find("circular", 1, true) then Thumbs.round(view) end
    view:SetAttribute("Round", view:FindFirstChildOfClass("UICorner") ~= nil)
    view.Parent = label
    return view
end

-- DEBUG, THE ROBLOX MENU (dev builds): the avatar pictures of the Roblox menu and of its leaderboard, how the copier
-- read each one, and the pictures it drew over them with where the head and the body fall inside them.
function Debug.corner(item)
    local corner = item:FindFirstChildOfClass("UICorner")
    if not corner then return nil end
    return tostring(Debug.value(corner.CornerRadius.Scale)) .. "," .. tostring(Debug.value(corner.CornerRadius.Offset))
end
-- Where a point falls in a view's picture: x and y from -1 to 1 inside it, y up.
function Debug.onPicture(camera, point, aspect)
    local relative = camera.CFrame:PointToObjectSpace(point)
    if relative.Z >= 0 then return "behind" end
    local scale = -relative.Z * math.tan(math.rad(camera.FieldOfView / 2))
    return {Debug.value(relative.X / (scale * aspect)), Debug.value(relative.Y / scale)}
end
function Debug.menuView(view)
    local out = {Name = view.Name, Class = view.ClassName, Size = Debug.value(view.AbsoluteSize), ZIndex = view.ZIndex, Corner = Debug.corner(view), Attributes = {}}
    for key, value in pairs(view:GetAttributes()) do out.Attributes[key] = Debug.value(value) end
    if view:IsA("ImageLabel") then out.Image = tostring(view.Image):sub(1, 300); return out end
    if not view:IsA("ViewportFrame") then return out end
    local camera = view.CurrentCamera
    if camera then out.Camera = {CFrame = Debug.value(camera.CFrame), FieldOfView = Debug.value(camera.FieldOfView)} end
    local model = view:FindFirstChildWhichIsA("Model")
    if not model then return out end
    local center, size = Pose.bounds(model)
    local head = model:FindFirstChild("Head")
    local parts = 0
    for _, item in ipairs(model:GetDescendants()) do if item:IsA("BasePart") then parts = parts + 1 end end
    out.Model = {Name = model.Name, Parts = parts, Center = Debug.value(center), Size = Debug.value(size), Accessories = {}}
    if head and head:IsA("BasePart") then
        local mesh = head:FindFirstChildOfClass("SpecialMesh")
        out.Model.Head = {Class = head.ClassName, Size = Debug.value(head.Size), Position = Debug.value(head.Position),
            Mesh = mesh and (mesh.MeshType.Name .. " " .. table.concat(Debug.value(mesh.Scale), " x ")) or nil}
    end
    for _, accessory in ipairs(model:GetChildren()) do
        if accessory:IsA("Accessory") then
            local handle = Appearance.handleOf(accessory)
            table.insert(out.Model.Accessories, {Name = accessory.Name, Size = handle and Debug.value(handle.Size) or nil,
                FromHead = handle and head and head:IsA("BasePart") and Debug.value((handle.Position - head.Position).Magnitude) or nil})
        end
    end
    out.Frames = {}
    for _, kind in ipairs({"AvatarHeadShot", "AvatarBust", "Avatar"}) do
        local ok, focus, tall, wide, deep = pcall(Thumbs.frame, model, kind)
        if ok then out.Frames[kind] = {Focus = Debug.value(focus), Height = Debug.value(tall), Width = Debug.value(wide), Depth = Debug.value(deep)} end
    end
    if camera then
        local shape = view.AbsoluteSize
        local aspect = shape.X > 0 and shape.Y > 0 and shape.X / shape.Y or 1
        local spot = {Center = Debug.onPicture(camera, center, aspect), Top = Debug.onPicture(camera, center + Vector3.new(0, size.Y / 2, 0), aspect),
            Bottom = Debug.onPicture(camera, center - Vector3.new(0, size.Y / 2, 0), aspect)}
        if head and head:IsA("BasePart") then
            spot.Head = Debug.onPicture(camera, head.Position, aspect)
            spot.HeadTop = Debug.onPicture(camera, head.Position + Vector3.new(0, head.Size.Y / 2, 0), aspect)
            spot.HeadBottom = Debug.onPicture(camera, head.Position - Vector3.new(0, head.Size.Y / 2, 0), aspect)
        end
        local torso = model:FindFirstChild("Torso") or model:FindFirstChild("UpperTorso")
        if torso and torso:IsA("BasePart") then spot.Torso = Debug.onPicture(camera, torso.Position, aspect) end
        out.InPicture = spot
    end
    return out
end
function Debug.menuPicture(item, root)
    local info = Thumbs.read(item.Image)
    local record = Thumbs.Labels[item]
    local kind = Thumbs.menuKind(item, info)
    local out = {Path = Debug.path(item, root), Class = item.ClassName, Name = item.Name, Image = tostring(item.Image):sub(1, 300), Read = info,
        MenuKind = kind, Round = Thumbs.looksRound(item, item.Image, kind), Size = Debug.value(item.AbsoluteSize), Position = Debug.value(item.AbsolutePosition),
        Visible = item.Visible, ImageTransparency = Debug.value(item.ImageTransparency), ScaleType = item.ScaleType.Name,
        ImageRect = {Debug.value(item.ImageRectOffset), Debug.value(item.ImageRectSize)}, ZIndex = item.ZIndex, Corner = Debug.corner(item),
        Children = {}, Views = {}, Ancestors = {}, Card = {}}
    if record then
        out.Followed = {Kind = record.Info and record.Info.Kind, Core = record.Core == true, Menu = record.Menu == true, Forced = record.Forced == true,
            Original = record.Original ~= item.Image and tostring(record.Original):sub(1, 300) or nil}
    end
    pcall(function() local tags = item:GetTags(); if #tags > 0 then out.Tags = tags end end)
    for _, child in ipairs(item:GetChildren()) do
        if child.Name:find("^Lyra") and (child:IsA("ViewportFrame") or child:IsA("ImageLabel")) then
            local ok, view = pcall(Debug.menuView, child)
            table.insert(out.Views, ok and view or {Name = child.Name, Error = tostring(view)})
        else table.insert(out.Children, child.ClassName .. " " .. child.Name) end
    end
    local cursor, cardRoot = item.Parent, nil
    for _ = 1, 8 do
        if not cursor or cursor == root then break end
        local row = {Name = cursor.Name, Class = cursor.ClassName}
        if cursor:IsA("GuiObject") then row.Size = Debug.value(cursor.AbsoluteSize); row.Clips = cursor.ClipsDescendants; row.Corner = Debug.corner(cursor) end
        table.insert(out.Ancestors, row)
        if not cardRoot and cursor.Name:find("^VirtualizedItem") then cardRoot = cursor end
        cursor = cursor.Parent
    end
    -- The texts of the card holding it: whose picture it is.
    for _, text in ipairs(Thumbs.elements(cardRoot or item.Parent, 120) or {}) do
        if (text:IsA("TextLabel") or text:IsA("TextButton")) and Ident.raw(text) ~= "" and #out.Card < 6 then table.insert(out.Card, Ident.raw(text)) end
    end
    return out
end
-- The Players page card a menu picture was last drawn in, as Roblox built it (dev builds, a second after it is drawn):
-- every frame of the card with what shapes it (corners, clipping, backgrounds, images, layouts), and the frames
-- around it, to see how the card is rounded. background: where the avatar's background went, or "none".
function Debug.noteCard(label, background)
    local layer = label:FindFirstAncestorWhichIsA("LayerCollector")
    local root, cursor = label, label.Parent
    for _ = 1, 8 do
        if not cursor or cursor == layer then break end
        root = cursor
        if cursor.Name:find("^VirtualizedItem") then break end
        cursor = cursor.Parent
    end
    local origin = root:IsA("GuiObject") and root.AbsolutePosition or Vector2.zero
    local out = {Time = os.date("%H:%M:%S"), Background = background, Picture = Debug.path(label, root), Root = Debug.path(root, layer),
        ZIndexBehavior = layer and layer:IsA("ScreenGui") and layer.ZIndexBehavior.Name or nil, Around = {}, Items = {}}
    local function describe(item, depth)
        local row = {Depth = depth, Class = item.ClassName, Name = item.Name}
        if item:IsA("GuiObject") then
            row.Size = Debug.value(item.AbsoluteSize); row.At = Debug.value(item.AbsolutePosition - origin); row.Z = item.ZIndex
            if not item.Visible then row.Hidden = true end
            row.Back = Debug.value(item.BackgroundTransparency)
            if item.BackgroundTransparency < 1 then row.Color = Debug.value(item.BackgroundColor3) end
            if item.ClipsDescendants then row.Clips = true end
            if item.AutomaticSize ~= Enum.AutomaticSize.None then row.Auto = item.AutomaticSize.Name end
            if item:IsA("ImageLabel") or item:IsA("ImageButton") then
                row.Image = tostring(item.Image):sub(1, 120); row.ImageT = Debug.value(item.ImageTransparency); row.ScaleType = item.ScaleType.Name
                if item.ScaleType == Enum.ScaleType.Slice then row.Slice = tostring(item.SliceCenter) end
                row.Tint = Debug.value(item.ImageColor3)
            end
            if item:IsA("CanvasGroup") then row.Group = Debug.value(item.GroupTransparency) end
            if item:IsA("TextLabel") or item:IsA("TextButton") then row.Text = Ident.raw(item):sub(1, 40) end
        elseif item:IsA("UICorner") then
            row.Radius = tostring(item.CornerRadius)
            pcall(function() row.Radii = {tostring(item.TopLeftRadius), tostring(item.TopRightRadius), tostring(item.BottomLeftRadius), tostring(item.BottomRightRadius)} end)
        elseif item:IsA("UIStroke") then
            row.Stroke = {Debug.value(item.Thickness), Debug.value(item.Color), Debug.value(item.Transparency)}
        elseif item:IsA("UIPadding") then
            row.Padding = {tostring(item.PaddingLeft), tostring(item.PaddingRight), tostring(item.PaddingTop), tostring(item.PaddingBottom)}
        end
        pcall(function() local tags = item:GetTags(); if #tags > 0 then row.Tags = tags end end)
        return row
    end
    local function add(item, depth)
        if #out.Items >= 100 then return end
        table.insert(out.Items, describe(item, depth))
        if item:IsA("ViewportFrame") then return end
        for _, child in ipairs(item:GetChildren()) do
            if child:IsA("GuiObject") or child:IsA("UIComponent") then add(child, depth + 1) end
        end
    end
    add(root, 0)
    cursor = root.Parent
    for _ = 1, 4 do
        if not cursor or cursor == layer then break end
        local row = describe(cursor, 0)
        for _, child in ipairs(cursor:GetChildren()) do
            if child:IsA("UIComponent") then row.Has = row.Has or {}; table.insert(row.Has, child.ClassName) end
        end
        table.insert(out.Around, row)
        cursor = cursor.Parent
    end
    Debug.LastCard = out
end
-- The menu picture's model: which way its root, torso and head face, the way the picture looks at it, how many joints
-- still hold it, and where the right hand is next to the torso (forward is -Z).
function Debug.pictureFacing()
    local model = UI.MenuAvatar and UI.MenuAvatar.Model
    if not model then return nil end
    local function look(name)
        local part = model:FindFirstChild(name)
        return part and part:IsA("BasePart") and Debug.value(part.CFrame.LookVector) or nil
    end
    local held = 0
    for _, item in ipairs(model:GetDescendants()) do
        if (item:IsA("JointInstance") or item:IsA("WeldConstraint")) and item.Enabled then held = held + 1 end
    end
    local torso = model:FindFirstChild("UpperTorso") or model:FindFirstChild("Torso")
    local hand = model:FindFirstChild("RightHand") or model:FindFirstChild("Right Arm")
    local okCamera, camera = pcall(UI.pictureDirection, model)
    return {Root = look("HumanoidRootPart"), Torso = torso and Debug.value(torso.CFrame.LookVector) or nil, Head = look("Head"),
        Camera = okCamera and Debug.value(camera) or nil, JointsHolding = held, Gear = model:FindFirstChild("LyraGear") ~= nil,
        Hand = (torso and hand and torso:IsA("BasePart") and hand:IsA("BasePart")) and Debug.value(torso.CFrame:PointToObjectSpace(hand.Position)) or nil}
end
-- Every avatar picture of the Roblox menu and its leaderboard (at most 150), without going inside the copier's own.
--|YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
function Debug.menu()
    local core = game:GetService("CoreGui")
    local rgui = core:FindFirstChild("RobloxGui")
    local page = rgui and rgui:FindFirstChild("peoplepage", true)
    local out = {Open = UI.MenuIsOpen == true, Setting = Store.Settings.MenuAvatar == true, PeoplePage = page and Debug.path(page, rgui) or nil,
        Followed = page ~= nil and Thumbs.PeoplePage == page, Pictures = {}}
    if UI.MenuAvatar and UI.MenuAvatar.Model then
        out.Avatar = {Serial = UI.MenuAvatar.Serial, Rig = tostring(F.getTrueRigType(UI.MenuAvatar.Model)), Name = UI.MenuAvatar.Snapshot and UI.MenuAvatar.Snapshot.Name or nil}
        local okFacing, facing = pcall(Debug.pictureFacing)
        out.Facing = okFacing and facing or {Error = tostring(facing)}
    end
    out.Card = Debug.LastCard
    local roots = {}
    if rgui then table.insert(roots, rgui) end
    if core:FindFirstChild("PlayerList") then table.insert(roots, core:FindFirstChild("PlayerList")) end
    for _, root in ipairs(roots) do
        local stack = {root}
        while #stack > 0 and #out.Pictures < 150 do
            local node = table.remove(stack)
            local ok, children = pcall(function() return node:GetChildren() end)
            for _, child in ipairs(ok and children or {}) do
                if not child.Name:find("^Lyra") then
                    table.insert(stack, child)
                    if child:IsA("ImageLabel") or child:IsA("ImageButton") then
                        local image = tostring(child.Image):lower()
                        if child.Name == "AvatarThumbnail" or Thumbs.Labels[child] or child:FindFirstChild("LyraMenuAvatar") or child:FindFirstChild("LyraPicture")
                            or Thumbs.read(child.Image) or image:find("rbxthumb", 1, true) or image:find("rbxcdn", 1, true) or image:find("headshot", 1, true) then
                            local done, row = pcall(Debug.menuPicture, child, root)
                            table.insert(out.Pictures, done and row or {Path = Debug.path(child, root), Error = tostring(row)})
                        end
                    end
                end
            end
        end
    end
    return out
end
-- The menu's pictures in the summary: one line each, and one for each picture drawn over it.
-- printed: cards already listed in this summary (each shot of the menu holds the same last card).
function Debug.menuLines(menu, add, printed)
    add(string.format("Roblox menu: open %s · pictures setting %s · Players page %s (followed %s) · avatar %s · %d pictures", tostring(menu.Open),
        tostring(menu.Setting), tostring(menu.PeoplePage or "none"), tostring(menu.Followed), menu.Avatar and (tostring(menu.Avatar.Name) .. " " .. menu.Avatar.Rig) or "none",
        #menu.Pictures))
    local function spot(value) return type(value) == "table" and (tostring(value[1]) .. "," .. tostring(value[2])) or tostring(value) end
    for _, picture in ipairs(menu.Pictures) do
        if picture.Error then add("  " .. tostring(picture.Path) .. " · error " .. picture.Error)
        else
            add(string.format("  %s %s %s · read %s · kind %s · round %s · corner %s · %s", picture.Name, table.concat(picture.Size, "x"),
                picture.Visible and "" or "(hidden)", picture.Read and picture.Read.Kind or "nothing", tostring(picture.MenuKind), tostring(picture.Round),
                tostring(picture.Corner), picture.Image:sub(1, 90)))
            for _, view in ipairs(picture.Views) do
                local at = view.Attributes or {}
                local where = view.InPicture
                add(string.format("    drawn: %s %s · way %s kind %s round %s corner %s · head %s (top %s, bottom %s) · body top %s bottom %s", tostring(view.Class),
                    view.Size and table.concat(view.Size, "x") or "?", tostring(at.Way), tostring(at.Kind), tostring(at.Round), tostring(view.Corner),
                    where and spot(where.Head) or "-", where and spot(where.HeadTop) or "-", where and spot(where.HeadBottom) or "-",
                    where and spot(where.Top) or "-", where and spot(where.Bottom) or "-"))
            end
        end
    end
    local function list(value) return type(value) == "table" and table.concat(value, ",") or tostring(value) end
    local facing = menu.Facing
    if facing then
        if facing.Error then add("Menu picture model: error " .. facing.Error)
        else
            add(string.format("Menu picture model: root looks %s · torso %s · head %s · seen from %s · joints holding %s · gear %s · right hand by the torso %s",
                list(facing.Root), list(facing.Torso), list(facing.Head), list(facing.Camera), tostring(facing.JointsHolding), tostring(facing.Gear), list(facing.Hand)))
        end
    end
    local card = menu.Card
    if card and not (printed and printed[card]) then
        if printed then printed[card] = true end
        add(string.format("Players card (drawn %s, background %s, layers %s): %s · picture %s", tostring(card.Time), tostring(card.Background),
            tostring(card.ZIndexBehavior), tostring(card.Root), tostring(card.Picture)))
        local function line(row, indent)
            local parts = {indent .. row.Class .. " " .. row.Name}
            if row.Size then table.insert(parts, list(row.Size) .. " at " .. list(row.At) .. " z" .. tostring(row.Z)) end
            if row.Hidden then table.insert(parts, "hidden") end
            if row.Back and row.Back < 1 then table.insert(parts, "back " .. tostring(row.Back) .. " " .. tostring(row.Color)) end
            if row.Clips then table.insert(parts, "clips") end
            if row.Auto then table.insert(parts, "auto " .. row.Auto) end
            if row.Image then table.insert(parts, string.format("image %s (%s, %s%s, tint %s)", row.Image:sub(1, 70), tostring(row.ImageT), row.ScaleType, row.Slice and (" " .. row.Slice) or "", tostring(row.Tint))) end
            if row.Group then table.insert(parts, "group " .. tostring(row.Group)) end
            if row.Text then table.insert(parts, "text " .. row.Text) end
            if row.Radius then table.insert(parts, "radius " .. row.Radius .. (row.Radii and (" (" .. table.concat(row.Radii, " | ") .. ")") or "")) end
            if row.Stroke then table.insert(parts, "stroke " .. list(row.Stroke)) end
            if row.Padding then table.insert(parts, "padding " .. table.concat(row.Padding, " | ")) end
            if row.Has then table.insert(parts, "has " .. table.concat(row.Has, ",")) end
            if row.Tags then table.insert(parts, "tags " .. table.concat(row.Tags, ",")) end
            add(table.concat(parts, " · "))
        end
        for _, row in ipairs(card.Items or {}) do line(row, "  " .. string.rep(". ", row.Depth or 0)) end
        for _, row in ipairs(card.Around or {}) do line(row, "  around: ") end
    end
end
-- Yields. Waits up to 30 s for the Roblox menu to open, then captures its pictures 3 and 8 s after it opened (time to
-- switch its Players page between grid and list) and saves them with a full capture. tick(text) shows the progress.
function Debug.menuCapture(tick)
    local start = os.clock()
    while not UI.MenuIsOpen and os.clock() - start < 30 and App.alive() do
        if tick then pcall(tick, "Open the Roblox menu (" .. math.ceil(30 - (os.clock() - start)) .. " s)") end
        task.wait(0.5)
    end
    if not UI.MenuIsOpen then App.report("The Roblox menu wasn't opened, so nothing was saved.", "warning"); return false end
    local opened = os.clock()
    local shots = {}
    for _, at in ipairs({3, 8}) do
        if tick then pcall(tick, "Capturing the menu...") end
        while os.clock() - opened < at and App.alive() do task.wait(0.25) end
        local ok, menu = pcall(Debug.menu)
        table.insert(shots, {T = at, Menu = ok and menu or {Error = tostring(menu)}})
    end
    local data = Debug.capture("menu")
    data.MenuShots = shots
    local ok, file, bytes = pcall(Debug.write, "menu", data)
    if ok then App.report(string.format("Menu capture saved: %s (%d KB).", file, math.ceil(bytes / 1024)), "success")
    else App.report("The menu capture could not be saved: " .. tostring(file), "error") end
    return ok
end

-- YOUR NAME: on your screen only, Roblox's leaderboard, the Players page of the Roblox menu, Roblox's avatar panel and
-- your chat messages can show another name and a verified badge: the copied player's (Settings > Name and badge >
-- Copied) or one you type (Custom). Other players keep seeing your real name; only script users in your server see
-- this one (see SHARED NAMES). Roblox's own text is put back when it is off, and a text Roblox
-- writes again (a list that redraws) is changed again.
-- The badge is the sign Roblox's fonts draw for verified accounts (U+E000), so it looks like Roblox's own.
Ident.Original = setmetatable({}, {__mode = "k"})
Ident.Written = setmetatable({}, {__mode = "k"})
Ident.Watched = setmetatable({}, {__mode = "k"})
Ident.Titles = setmetatable({}, {__mode = "k"})
Ident.WatchCount = 0
Ident.Info, Ident.Pending = {}, {}
Ident.Badge = utf8.char(0xE000)
Ident.Active = false
-- The text Roblox wrote in a label, also while ours is showing.
function Ident.raw(label)
    local written = Ident.Written[label]
    if written and label.Text == written then return Ident.Original[label] or label.Text end
    return label.Text
end
-- The user a picture shows, from the picture Roblox put there (a picture changed by YOUR PICTURE included).
function Ident.imageUser(image)
    local record = Thumbs.Labels[image]
    local info = Thumbs.read(record and record.Original or image.Image)
    return info and info.User
end
-- Yields nothing. Username, display name and badge of a profile, fetched once in the background; nil until known.
function Ident.lookup(id)
    local info = Ident.Info[id]
    if info or Ident.Pending[id] then return info end
    Ident.Pending[id] = true
    task.spawn(function()
        local ok, rows = pcall(function() return US:GetUserInfosByUserIdsAsync({id}) end)
        local row = ok and type(rows) == "table" and rows[1]
        if type(row) == "table" then
            Ident.Info[id] = {Name = tostring(row.Username or ""), Display = tostring(row.DisplayName or ""), Verified = row.HasVerifiedBadge == true}
        end
        Ident.Pending[id] = nil
        if App.alive() and Ident.Info[id] then Ident.refresh() end
    end)
    return nil
end
-- The Roblox profile you are wearing: a profile copied from Roblox (edited or not), not a saved skin or your own.
function Ident.copied()
    local snapshot = App.Current
    if not snapshot or snapshot.Original or snapshot.LookKey or snapshot.Catalog or snapshot.SyncUser then return nil end
    local id = Codec.id(snapshot.Id)
    if not id or id == lp.UserId then return nil end
    local info = Ident.lookup(id)
    local name = info and info.Name ~= "" and info.Name or (type(snapshot.Name) == "string" and snapshot.Name ~= "" and snapshot.Name) or nil
    if not name then return nil end
    local display = info and info.Display ~= "" and info.Display or (type(snapshot.DisplayName) == "string" and snapshot.DisplayName ~= "" and snapshot.DisplayName) or name
    return {Id = id, Name = name, Display = display, Verified = info ~= nil and info.Verified}
end
-- What Roblox's menus show for you: {Name, Display, Badge}, or nil when it is your own name and nothing changes.
function Ident.target()
    local mode, badgeMode = Store.Settings.NameMode, Store.Settings.Badge
    if (mode ~= "Copied" and mode ~= "Custom") and (badgeMode ~= "Copied" and badgeMode ~= "On") then return nil end
    local copied = (mode == "Copied" or badgeMode == "Copied") and Ident.copied() or nil
    local name, display = lp.Name, lp.DisplayName
    if mode == "Copied" and copied then
        name, display = copied.Name, copied.Display
    elseif mode == "Custom" then
        if Store.Settings.CustomName ~= "" then name = Store.Settings.CustomName end
        if Store.Settings.CustomDisplay ~= "" then display = Store.Settings.CustomDisplay end
    end
    local badge = badgeMode == "On" or (badgeMode == "Copied" and copied ~= nil and copied.Verified)
    -- A verified account already shows Roblox's own badge.
    local real = false
    pcall(function() real = lp.HasVerifiedBadge == true end)
    if real then badge = false end
    if name == lp.Name and display == lp.DisplayName and not badge then return nil end
    return {Name = name, Display = display, Badge = badge}
end
-- SHARED NAMES: always on, with Skin sync. The name and badge you chose (Settings > Name and badge) are sent to the
-- Lyra server for this Roblox server only. The ones other script users there chose show for them on your screen, in the
-- same places as yours: the Roblox leaderboard, the Roblox menu and the chat. Players without the script see nothing
-- different. A received name is cleaned like one you type, and a badge is not added to an account Roblox already shows
-- as verified.
Ident.Peers = {}
function Ident.peerKey(peers)
    local keys = {}
    for uid, row in pairs(peers) do table.insert(keys, tostring(uid) .. "|" .. row.Name .. "|" .. row.Display .. "|" .. tostring(row.Badge)) end
    table.sort(keys)
    return table.concat(keys, "\n")
end
function Ident.setPeers(list)
    local peers = {}
    for _, row in ipairs(type(list) == "table" and list or {}) do
        local uid = type(row) == "table" and Codec.id(row.user)
        local player = uid and uid ~= lp.UserId and Players:GetPlayerByUserId(uid)
        if player then
            local display, name = Ident.cleanDisplay(row.d), Ident.cleanName(row.u)
            if display == "" then display = player.DisplayName end
            if #name < 3 then name = player.Name end
            local real, badge = false, row.b == true
            pcall(function() real = player.HasVerifiedBadge == true end)
            if real then badge = false end
            if display ~= player.DisplayName or name ~= player.Name or badge then peers[uid] = {Name = name, Display = display, Badge = badge} end
        end
    end
    local changed = Ident.peerKey(peers) ~= Ident.peerKey(Ident.Peers)
    Ident.Peers = peers
    if changed then Ident.refresh() end
end
-- Whose names Roblox's labels may show changed: you, and the script users sharing theirs.
function Ident.candidates()
    local list = {}
    local mine = Ident.target()
    if mine then table.insert(list, {Player = lp, Target = mine}) end
    if Sync.enabled() then
        for uid, target in pairs(Ident.Peers) do
            local player = Players:GetPlayerByUserId(uid)
            if player then table.insert(list, {Player = player, Target = target}) end
        end
    end
    return list
end
-- What you share with the other script users: {d, u, b} (an empty d or u keeps your own), or nil.
function Ident.shared()
    local target = Ident.target()
    if not target then return nil end
    return {d = target.Display ~= lp.DisplayName and target.Display or "", u = target.Name ~= lp.Name and target.Name or "", b = target.Badge == true}
end
-- The new text for one of Roblox's labels, or nil to leave it. player: whose names (you when nil).
function Ident.rewrite(text, target, title, player)
    player = player or lp
    if type(text) ~= "string" or text == "" or not target then return nil end
    if title then
        -- The panel's title ("<username>'s Avatar" in any language).
        local at = text:find(player.Name, 1, true)
        if not at then return nil end
        return text:sub(1, at - 1) .. target.Name .. text:sub(at + #player.Name)
    end
    if text == player.DisplayName then return target.Badge and (target.Display .. " " .. Ident.Badge) or target.Display end
    if text == "@" .. player.Name then return "@" .. target.Name end
    if text == player.Name then return target.Name end
    return nil
end
-- Whether a text is one of the names (as Roblox writes them) of you or of a script user sharing theirs.
function Ident.isOwnText(text)
    for _, row in ipairs(Ident.candidates()) do
        local player = row.Player
        if text == player.DisplayName or text == player.Name or text == "@" .. player.Name then return true end
    end
    return false
end
-- Whether a label with your name is about you: in your row of the leaderboard (PlayerEntry_<your id>; on phones and
-- consoles your row sits above the list as TitlePlayer or TitlePlayerEntry, named without an id), or next to a
-- picture of you or your @username (your card in the leaderboard or the Roblox menu). Display names are not unique,
-- so a name alone is never enough. player: another player instead of you (see SHARED NAMES).
function Ident.mine(label, player)
    player = player or lp
    local cursor = label.Parent
    for _ = 1, 8 do
        if not cursor or cursor:IsA("LayerCollector") then return false end
        local entry = cursor.Name:match("^PlayerEntry_(%d+)$")
        if entry then return tonumber(entry) == player.UserId end
        if (cursor.Name == "TitlePlayer" or cursor.Name == "TitlePlayerEntry") and Thumbs.CoreList and cursor:IsDescendantOf(Thumbs.CoreList) then return player == lp end
        -- Counted without the script's own pictures (see Thumbs.elements).
        local items = Thumbs.elements(cursor, 160)
        if not items then return false end
        for _, item in ipairs(items) do
            if item ~= label then
                if (item:IsA("ImageLabel") or item:IsA("ImageButton")) and Ident.imageUser(item) == player.UserId then return true end
                if (item:IsA("TextLabel") or item:IsA("TextButton")) and Ident.raw(item) == "@" .. player.Name then return true end
            end
        end
        -- One card of the Roblox menu's list: the cards around it are other players.
        if cursor.Name:find("^VirtualizedItem") then return false end
        cursor = cursor.Parent
    end
    return false
end
-- list: whose names to show ({Player, Target} rows; false: none, nil: worked out here).
function Ident.apply(label, list)
    if not label.Parent then return end
    local text = label.Text
    local written = Ident.Written[label]
    local original = (written and text == written) and (Ident.Original[label] or text) or text
    Ident.Original[label] = original
    if list == nil then list = Ident.candidates() end
    local new
    for _, row in ipairs(list or {}) do
        -- The avatar panel's title is only followed while it shows what you wear.
        local title = Ident.Titles[label] and row.Player == lp
        local value = (row.Player == lp or not Ident.Titles[label]) and Ident.rewrite(original, row.Target, title, row.Player) or nil
        if value and value ~= original and (title or Ident.mine(label, row.Player)) then new = value; break end
    end
    if new then
        if text ~= new then Ident.Written[label] = new; label.Text = new end
    elseif written then
        Ident.Written[label] = nil
        if text == written then label.Text = original end
    end
end
-- A label is changed as soon as Roblox writes your name in it, before it is drawn. Roblox fills a card one text at a
-- time, so a name whose @username or picture was not there yet is looked at once more at the end of that step.
function Ident.settle(label)
    pcall(Ident.apply, label)
    if Ident.Active and not Ident.Written[label] and Ident.isOwnText(label.Text) then
        task.defer(function() if App.alive() and Ident.Active and label.Parent then pcall(Ident.apply, label) end end)
    end
end
function Ident.consider(label)
    if not Ident.Active or not (label:IsA("TextLabel") or label:IsA("TextButton")) then return end
    -- Past the limit a label is still changed, only no longer followed.
    if not Ident.Watched[label] and Ident.WatchCount < 3000 then
        Ident.Watched[label] = true; Ident.WatchCount = Ident.WatchCount + 1
        pcall(function()
            RegisterConnection(label:GetPropertyChangedSignal("Text"):Connect(function()
                if App.alive() and (Ident.Active or Ident.Written[label]) then Ident.settle(label) end
            end))
        end)
    end
    Ident.settle(label)
end
-- The title of Roblox's avatar panel while it shows what you wear.
function Ident.title(label)
    if not Ident.Active then return end
    Ident.Titles[label] = true
    Ident.consider(label)
end
-- Every label already followed, after a change of look or of the settings; the leaderboard is read again when it
-- turns on.
function Ident.refresh()
    if not App.alive() then return end
    local list = Ident.candidates()
    local was = Ident.Active
    Ident.Active = #list > 0
    -- The name you share goes out with the next beat (see SHARED NAMES).
    Sync.Woken = true
    if Ident.Active then
        pcall(Ident.hookChat)
        local list = Thumbs.CoreList
        if not was then
            for _, holder in ipairs({list, Thumbs.MenuRoot}) do
                if holder and holder.Parent then
                    local ok, items = pcall(function() return holder:GetDescendants() end)
                    for _, item in ipairs(ok and items or {}) do if item:IsA("TextLabel") or item:IsA("TextButton") then pcall(Ident.consider, item) end end
                end
            end
        end
        if UI.MenuIsOpen then pcall(UI.runMenuAvatar) end
    end
    for label in pairs(Ident.Watched) do
        if label.Parent then pcall(Ident.apply, label, list) end
    end
end
-- CHAT: the name in front of your own messages, and of the messages of script users sharing theirs (Roblox's chat
-- window and the bubbles over heads take it from there). Roblox lets one function change incoming messages; a game's own one (chat tags) keeps running first and
-- only the name in what it returns is changed. Where the executor can't read the game's function, each chat channel's
-- function is used instead, which games rarely set. Older games still on the legacy chat are left alone.
function Ident.chatProperties(message, props)
    if not Ident.Active then return props end
    local source = message.TextSource
    if not source then return props end
    local player, target = nil, nil
    for _, row in ipairs(Ident.candidates()) do
        if row.Player.UserId == source.UserId then player, target = row.Player, row.Target; break end
    end
    if not target then return props end
    local prefix = props and props.PrefixText ~= "" and props.PrefixText or message.PrefixText
    if type(prefix) ~= "string" or prefix == "" then return props end
    local display = target.Badge and (target.Display .. " " .. Ident.Badge) or target.Display
    local new
    local at = prefix:find(player.DisplayName, 1, true)
    if at then new = prefix:sub(1, at - 1) .. display .. prefix:sub(at + #player.DisplayName)
    else
        at = prefix:find(player.Name, 1, true)
        if at then new = prefix:sub(1, at - 1) .. target.Name .. prefix:sub(at + #player.Name) end
    end
    if not new or new == prefix then return props end
    local out = props or Instance.new("TextChatMessageProperties")
    out.PrefixText = new
    return out
end
function Ident.chatHandler(previous)
    return function(message)
        local props
        if previous then
            local ok, value = pcall(previous, message)
            if ok then props = value end
        end
        local ok, value = pcall(Ident.chatProperties, message, props)
        if ok then return value end
        return props
    end
end
function Ident.hookChat()
    if Ident.ChatHooked then return end
    Ident.ChatHooked = true
    local tcs = game:GetService("TextChatService")
    if tcs.ChatVersion ~= Enum.ChatVersion.TextChatService then return end
    if type(getcallbackvalue) == "function" then
        local ok, previous = pcall(getcallbackvalue, tcs, "OnIncomingMessage")
        if ok and (previous == nil or type(previous) == "function") then
            local set = pcall(function() tcs.OnIncomingMessage = Ident.chatHandler(previous) end)
            if set then Ident.ChatRestore = {Target = tcs, Previous = previous}; return end
        end
    end
    Ident.ChatChannels = {}
    local function hook(channel)
        if not channel:IsA("TextChannel") or Ident.ChatChannels[channel] then return end
        if pcall(function() channel.OnIncomingMessage = Ident.chatHandler(nil) end) then Ident.ChatChannels[channel] = true end
    end
    local folder = tcs:FindFirstChild("TextChannels")
    if folder then
        for _, channel in ipairs(folder:GetChildren()) do pcall(hook, channel) end
        RegisterConnection(folder.ChildAdded:Connect(function(channel) if App.alive() then pcall(hook, channel) end end))
    end
end
-- When the script closes: Roblox's text and the chat functions go back as they were.
function Ident.cleanup()
    Ident.Active = false
    for label, written in pairs(Ident.Written) do
        pcall(function() if label.Text == written then label.Text = Ident.Original[label] end end)
    end
    table.clear(Ident.Written)
    if Ident.ChatRestore then
        local row = Ident.ChatRestore
        pcall(function() row.Target.OnIncomingMessage = row.Previous end)
        Ident.ChatRestore = nil
    end
    for channel in pairs(Ident.ChatChannels or {}) do pcall(function() channel.OnIncomingMessage = nil end) end
    Ident.ChatChannels = nil
end

-- POSE: Roblox's avatar pictures, and the avatar in the Roblox menu, show the avatar in the first frame of its idle
-- animation instead of standing stiff: its own animation pack's idle, else Roblox's default idle for its rig. A
-- model is posed from that keyframe without playing anything: every joint takes the keyframe's offset and the parts
-- are placed from the joints. Some packs open on a frame that leans or lies the body down (the picture then looked
-- at its feet), so a pose that does not leave the avatar standing is skipped for a later keyframe, else none is used.
-- A skin saved while posed in a posing game keeps that pose for these pictures instead (see SAVED POSE).
Pose.Cache = {}
Pose.MaxFrames = 6
-- Yields. A list of {[part name] = joint offset}, one per keyframe (the first ones, in time order), or nil.
function Pose.frames(id)
    id = F.normalizeAnimId(id)
    local cached = Pose.Cache[id]
    if cached ~= nil then return cached or nil end
    local result = false
    pcall(function()
        local sequence
        local ok, objects = pcall(function() return game:GetObjects(id) end)
        for _, root in ipairs(ok and objects or {}) do
            if root:IsA("KeyframeSequence") then sequence = root; break end
            local inner = root:FindFirstChildWhichIsA("KeyframeSequence", true)
            if inner then sequence = inner; break end
        end
        if not sequence then
            local got, value = pcall(function() return game:GetService("KeyframeSequenceProvider"):GetKeyframeSequenceAsync(id) end)
            if got and typeof(value) == "Instance" then sequence = value end
        end
        if not sequence then return end
        local frames = sequence:GetKeyframes()
        table.sort(frames, function(a, b) return a.Time < b.Time end)
        local list = {}
        for _, frame in ipairs(frames) do
            if #list >= Pose.MaxFrames then break end
            local map = {}
            local function walk(pose)
                -- A pose with no weight only holds the hierarchy: it does not move its joint.
                if (tonumber(pose.Weight) or 1) > 0 then map[pose.Name] = pose.CFrame end
                for _, child in ipairs(pose:GetSubPoses()) do if child:IsA("Pose") then walk(child) end end
            end
            for _, pose in ipairs(frame:GetPoses()) do if pose:IsA("Pose") then walk(pose) end end
            if next(map) then table.insert(list, map) end
        end
        if #list > 0 then result = list end
    end)
    Pose.Cache[id] = result
    return result or nil
end
-- Yields. The idle a picture of this model is posed with.
function Pose.idleId(model)
    local r6 = F.getTrueRigType(model) == Enum.HumanoidRigType.R6
    if not r6 then
        local hum = model:FindFirstChildOfClass("Humanoid")
        local desc = hum and hum:FindFirstChildOfClass("HumanoidDescription")
        local ok, asset = pcall(function() return desc.IdleAnimation end)
        if ok and tonumber(asset) and tonumber(asset) ~= 0 then
            local sets = F.animationSets(asset)
            local list = sets and sets.idle
            if list and #list > 0 then
                -- The main idle (the one played most), not the rare look-around.
                local best
                for _, row in ipairs(list) do if not best or (tonumber(row.Weight) or 1) > (tonumber(best.Weight) or 1) then best = row end end
                return best.Id
            end
            local one = F.resolveAnimationTrackId(asset)
            if one then return one end
        end
    end
    return r6 and "rbxassetid://180435571" or "rbxassetid://507766388"
end
-- A picture model's parts are placed one by one from its joints. A part moved while its joints hold it takes its
-- whole body with it, and the joints only take a new offset when the engine gets to it: placing the parts then
-- turned or laid the whole avatar down instead of posing it (it was seen from the side, and an arm turned for a
-- gear took the body along). A picture is still, so its joints and welds are let go and every part anchored: each
-- part then goes exactly where its joint puts it, and the root stays where it is, upright.
function Pose.loosen(model)
    for _, item in ipairs(model:GetDescendants()) do
        if item:IsA("JointInstance") or item:IsA("WeldConstraint") or item:IsA("AnimationConstraint") or item:IsA("RigidConstraint") then
            pcall(function() item.Enabled = false end)
        elseif item:IsA("BasePart") then
            item.Anchored = true
        end
    end
    local root = model:FindFirstChild("HumanoidRootPart")
    if root and root:IsA("BasePart") then root.CFrame = CFrame.new(root.Position) end
end
-- Every joint of the model takes the offset its part has in map (none: its rest pose); the parts follow.
function Pose.set(model, map)
    Pose.loosen(model)
    for _, joint in ipairs(model:GetDescendants()) do
        if joint:IsA("Motor6D") or joint:IsA("AnimationConstraint") then
            local ok, _, part1 = pcall(Overlay.jointInfo, joint)
            local offset = map and ok and part1 and map[part1.Name] or nil
            pcall(function() joint.Transform = offset or CFrame.new() end)
        end
    end
    pcall(Rig.reachable, model, true)
end
-- Distance of every body part from the root (the rest pose's reach), measured before posing.
function Pose.reach(model)
    local root = model:FindFirstChild("HumanoidRootPart")
    local reach = {}
    if not root then return reach end
    for _, part in ipairs(model:GetChildren()) do
        if part:IsA("BasePart") and part ~= root and Appearance.isBody(part, model) then reach[part] = (part.Position - root.Position).Magnitude end
    end
    return reach
end
-- Whether a posed model still stands: torso upright, head above the root, no part pulled away from the body.
function Pose.standing(model, reach)
    local root = model:FindFirstChild("HumanoidRootPart")
    local torso = model:FindFirstChild("UpperTorso") or model:FindFirstChild("Torso")
    local head = model:FindFirstChild("Head")
    if not (root and torso and torso:IsA("BasePart")) then return false end
    if torso.CFrame.UpVector.Y < 0.6 then return false end
    if head and head:IsA("BasePart") and head.Position.Y <= root.Position.Y then return false end
    for part, rest in pairs(reach) do
        if part.Parent == model and (part.Position - root.Position).Magnitude > rest * 1.35 + 1.5 then return false end
    end
    return true
end
-- Yields. Poses a prepared model (root at its place); returns whether a pose was used.
function Pose.apply(model)
    local list = Pose.frames(Pose.idleId(model))
    if not list then Pose.set(model, nil); return false end
    local reach = Pose.reach(model)
    for _, map in ipairs(list) do
        Pose.set(model, map)
        if Pose.standing(model, reach) then return true end
    end
    Pose.set(model, nil)
    return false
end
-- The box a picture of the whole avatar fits: the body and what is worn close to it, in world axes (a part the game
-- or an item left far away, or a hidden root, does not stretch it). Returns the centre and the size.
function Pose.bounds(model)
    local root = model:FindFirstChild("HumanoidRootPart")
    local body = {}
    for _, part in ipairs(model:GetChildren()) do
        if part:IsA("BasePart") and part ~= root and Appearance.isBody(part, model) then table.insert(body, part) end
    end
    local function corners(part, low, high)
        local cf, half = part.CFrame, part.Size / 2
        for _, x in ipairs({-1, 1}) do
            for _, y in ipairs({-1, 1}) do
                for _, z in ipairs({-1, 1}) do
                    local point = cf * Vector3.new(half.X * x, half.Y * y, half.Z * z)
                    low = low:Min(point); high = high:Max(point)
                end
            end
        end
        return low, high
    end
    local low, high = Vector3.new(math.huge, math.huge, math.huge), Vector3.new(-math.huge, -math.huge, -math.huge)
    for _, part in ipairs(body) do low, high = corners(part, low, high) end
    if #body == 0 then
        local box, size = model:GetBoundingBox()
        return box.Position, size
    end
    -- Worn items count while they hang near the body (wings and big hats included, a stray part not).
    local center, extent = (low + high) / 2, (high - low).Magnitude
    for _, item in ipairs(model:GetDescendants()) do
        if item:IsA("BasePart") and item.Transparency < 1 and (item:FindFirstAncestorOfClass("Accessory") or item.Parent.Name == "LyraGear") then
            if (item.Position - center).Magnitude <= extent * 1.25 + 2 then low, high = corners(item, low, high) end
        end
    end
    return (low + high) / 2, high - low
end

-- SKIN SYNC: script users in the same server see each other's skin, always (it has no setting). The skin you wear is
-- shared with the Lyra server for this Roblox server only, and the other users' skins are drawn over their characters
-- on your screen. Nothing changes for players without the script.
Sync.Url = "https://api.lyraez.lol/v1/sync"
-- How soon a skin change reaches the others. Yours is sent as soon as it is on (ChangeGap seconds after the last beat
-- at most; it used to wait 5 s). Where the executor can open a WebSocket, the Lyra server pokes this script the moment
-- another user here changes skin (see SKIN SYNC PUSH) and it beats then, PokeGap seconds after the last beat at most;
-- between pokes it beats every PushInterval seconds. Without a socket it beats every Interval seconds, as always. A
-- changed skin is downloaded and drawn in the same pass as the beat that read it.
Sync.Interval, Sync.PushInterval, Sync.ChangeGap, Sync.PokeGap, Sync.Tick = 8, 100, 2, 1, 0.25
function Sync.requestFn()
    return type(request) == "function" and request or type(http_request) == "function" and http_request
        or (type(syn) == "table" and type(syn.request) == "function" and syn.request) or nil
end
function Sync.enabled()
    return App.alive() and not Sync.Closed and game.JobId ~= "" and Sync.requestFn() ~= nil
end
function Sync.call(body)
    local requestFn = Sync.requestFn(); if not requestFn then return nil end
    local ok, response = pcall(requestFn, {Url = Sync.Url, Method = "POST", Headers = {["Content-Type"] = "application/json"}, Body = HttpService:JSONEncode(body)})
    if not ok or type(response) ~= "table" or type(response.Body) ~= "string" then return nil end
    local decoded, reply = pcall(function() return HttpService:JSONDecode(response.Body) end)
    return decoded and type(reply) == "table" and reply or nil
end
-- FNV-1a (32-bit) plus the length: only used to notice that a skin changed.
function Sync.hash(text)
    local h = 2166136261
    for i = 1, #text do h = bit32.bxor(h, string.byte(text, i)); h = (bit32.lshift(h, 24) + h * 403) % 4294967296 end
    return string.format("%08x%08x", h, #text)
end
-- The skin you share. A skin's full copy (every part and mesh) can be a few hundred KB; sending that from a phone on
-- mobile data filled the upload and the game's ping went to seconds. Past MaxShared characters only the avatar
-- description is shared (the other users build it from the catalog items, as a rig change does), and a skin that is
-- still too big is not shared. Skins the Lyra server refused (Rejected) are not sent again this session.
Sync.MaxShared = 60000
Sync.Rejected = {}
function Sync.mine()
    local snapshot = App.Current
    if not snapshot or snapshot.Original or type(snapshot.Data) ~= "table" then return nil end
    if Sync.MineFor ~= snapshot then
        local function encode(data)
            local ok, text = pcall(function() return HttpService:JSONEncode({Version = 2, Data = data}) end)
--: YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
            return ok and type(text) == "string" and text or nil
        end
        local text = encode(snapshot.Data)
        if text and #text > Sync.MaxShared and snapshot.Data.Visual ~= nil then
            local lite = {}
            for key, value in pairs(snapshot.Data) do if key ~= "Visual" then lite[key] = value end end
            text = encode(lite)
        end
        Sync.MineFor = snapshot
        Sync.MineText = text and #text <= Sync.MaxShared and text or nil
        Sync.MineHash = Sync.MineText and Sync.hash(Sync.MineText) or nil
    end
    if Sync.MineHash and Sync.Rejected[Sync.MineHash] then return nil end
    return Sync.MineText, Sync.MineHash
end
-- Another user's skin is untrusted: it goes through the same checks as an imported skin code.
function Sync.decode(text)
    assert(type(text) == "string" and #text <= 262144, "Invalid skin.")
    local ok, packet = pcall(function() return HttpService:JSONDecode(text) end)
    assert(ok and type(packet) == "table" and packet.Version == 2 and type(packet.Data) == "table", "Invalid skin.")
    if packet.Data.Visual then Visual.validate(packet.Data.Visual) end
    local valid, desc = pcall(Codec.decode, packet.Data)
    assert(valid and desc, "Invalid skin.")
    local data = Codec.encode(desc); desc:Destroy(); data.Visual = packet.Data.Visual; data.Tweaks = Tweaks.clean(packet.Data.Tweaks)
    Codec.extras(packet.Data, data)
    return data
end
-- Yields. Returns whether the Lyra server answered, and the error it gave. A skin upload that fails three times (or
-- that the server finds too big) stops being shared until you change skin, so a failing upload is never repeated
-- every few seconds.
Sync.Uploads = {}
-- The name you share goes out when it changes and every two minutes (the server forgets a name not sent for five);
-- the other users' names are asked for every 20 s, and on every beat while the server pokes this script (a poke can
-- be a name that changed; see SHARED NAMES).
Sync.NameEvery, Sync.NamesEvery = 120, 20
function Sync.beat()
    local text, hash = Sync.mine()
    local push = Sync.pushLive()
    -- What a poke asked for is read by this beat.
    Sync.Poked = false
    local body = {a = "beat", job = game.JobId, user = lp.UserId, hash = hash or ""}
    if push then body.ws = true end
    local shared = Ident.shared()
    local nameKey = shared and (shared.d .. "\1" .. shared.u .. "\1" .. tostring(shared.b)) or ""
    if shared and (nameKey ~= Sync.NameSent or os.clock() - (Sync.NameAt or -math.huge) >= Sync.NameEvery) then body.n = shared
    elseif not shared and Sync.NameSent and Sync.NameSent ~= "" then body.n = "" end
    local askNames = push or os.clock() - (Sync.NamesAt or -math.huge) >= Sync.NamesEvery
    if askNames then body.names = true end
    -- The presence beat waiting for a ride (see Sync.carryPresence).
    local carried = Sync.PresenceBody
    if carried then body.p = carried end
    local function upload()
        Sync.Uploads[hash] = (Sync.Uploads[hash] or 0) + 1
        if Sync.Uploads[hash] >= 3 then Sync.Rejected[hash] = true end
        body.data = text
    end
    if hash and Sync.Sent ~= hash then upload() end
    local reply = Sync.call(body)
    if reply and reply.error == "too_large" and hash then Sync.Rejected[hash] = true end
    if not reply or reply.ok ~= true then Sync.Answering = false; return false, reply and reply.error end
    Sync.Answering = true
    if carried then
        -- A Lyra server that does not answer presence here gets it on its own from now on.
        if type(reply.p) == "table" then Sync.PresenceReply = reply.p else Sync.PresenceCarry = false; Sync.PresenceReply = false end
        if Sync.PresenceBody == carried then Sync.PresenceBody = nil end
        body.p = nil
    end
    if hash and reply.need and not body.data and not Sync.Rejected[hash] then
        upload()
        reply = Sync.call(body)
        if reply and reply.error == "too_large" then Sync.Rejected[hash] = true end
        if not reply or reply.ok ~= true then return false, reply and reply.error end
    end
    if hash then Sync.Uploads[hash] = nil; Sync.Rejected[hash] = nil end
    Sync.Sent = hash
    if body.n ~= nil then Sync.NameSent, Sync.NameAt = nameKey, os.clock() end
    if askNames then
        Sync.NamesAt = os.clock()
        pcall(Ident.setPeers, type(reply.names) == "table" and reply.names or {})
    end
    local listed = {}
    if type(reply.peers) == "table" then
        for _, peer in ipairs(reply.peers) do
            if type(peer) == "table" and type(peer.user) == "number" and type(peer.hash) == "string" then listed[peer.user] = peer.hash end
        end
    end
    Sync.Peers = listed
    -- The Server tab shows Ask skin on users sharing a skin: it is drawn again when they change.
    local signature = {}
    for uid in pairs(listed) do table.insert(signature, uid) end
    table.sort(signature); signature = table.concat(signature, ",")
    if signature ~= Sync.PeerSignature then
        Sync.PeerSignature = signature
        if UI.Tab == "Players" then UI.scheduleList("players") end
    end
    Sync.requests(reply.asks, reply.answers)
    return true
end
-- SKIN SYNC PICTURES: a script user's synced skin also shows where the game shows their avatar: its pictures
-- (leaderboards, player cards), their card in the Roblox menu and the game's copies of them (lobby displays,
-- cutscenes), on your screen only, while "Show my avatar on the game's copies of me" is on.
Sync.Snapshots, Sync.Pictures = {}, {}
function Sync.pictureUsers()
    local users = {}
    if not Sync.enabled() or Store.Settings.StandIns == false then return users end
    for uid, shown in pairs(Sync.Shown) do if shown.Data and Sync.Peers[uid] == shown.Hash then users[uid] = true end end
    return users
end
-- A stable snapshot per synced skin (stand-ins and pictures are built once per skin).
function Sync.snapshot(uid)
    if not Sync.pictureUsers()[uid] then return nil end
    local shown = Sync.Shown[uid]
--- YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU
    local snapshot = Sync.Snapshots[uid]
    if not snapshot or snapshot.Hash ~= shown.Hash then
        snapshot = {Data = shown.Data, Hash = shown.Hash, SyncUser = uid, Name = Sync.who(uid)}
        Sync.Snapshots[uid] = snapshot
    end
    return snapshot
end
-- Yields. The synced skin posed for a picture, with a serial that changes with the skin.
Sync.PictureBuilding = {}
function Sync.pictureModel(uid)
    -- One build per user at a time (many pictures can ask at once).
    while Sync.PictureBuilding[uid] and App.alive() do task.wait(0.05) end
    local snapshot = Sync.snapshot(uid)
    if not snapshot then return nil end
    local cached = Sync.Pictures[uid]
    if cached and cached.Snapshot == snapshot then return cached.Model, cached.Serial end
    if cached then pcall(function() cached.Model:Destroy() end); Sync.Pictures[uid] = nil end
    local player = Players:GetPlayerByUserId(uid)
    Sync.PictureBuilding[uid] = true
    local ok, model = pcall(UI.posedModel, snapshot, player and player.Character and F.getTrueRigType(player.Character) or nil)
    Sync.PictureBuilding[uid] = nil
    if not ok or not model then return nil end
    UI.MenuAvatarSerial = UI.MenuAvatarSerial + 1
    Sync.Pictures[uid] = {Snapshot = snapshot, Model = model, Serial = UI.MenuAvatarSerial}
    return model, UI.MenuAvatarSerial
end
-- A user's synced skin arrived, changed or went: their pictures and stand-ins follow.
function Sync.changed(uid)
    task.spawn(function()
        local cached = Sync.Pictures[uid]
        if cached and cached.Snapshot ~= Sync.snapshot(uid) then pcall(function() cached.Model:Destroy() end); Sync.Pictures[uid] = nil end
        if not Sync.pictureUsers()[uid] then Sync.Snapshots[uid] = nil end
        pcall(Thumbs.refreshUser, uid)
        pcall(Mirror.refreshUser, uid)
    end)
end
-- A script user's own avatar, for telling what the game put on them (see THE GAME'S CLOTHES ON SCRIPT USERS):
-- {Clothes = {[template] = true}, Names = {[accessory name] = true}, Meshes = {[mesh] = true}}, or nil until it is
-- read. It is read from Roblox in the background once per player, again a minute after a failure.
Sync.Looks = {}
function Sync.lookOf(uid)
    local row = Sync.Looks[uid]
    if row and row.Look then return row.Look end
    if row and (row.Busy or os.clock() < row.Retry) then return nil end
    row = {Busy = true, Retry = 0}
    Sync.Looks[uid] = row
    task.spawn(function()
        local ok, look = pcall(function()
            local model = API.model(API.description(uid), Enum.HumanoidRigType.R15)
            local found = {Clothes = {}, Names = {}, Meshes = {}}
            for _, item in ipairs(model:GetChildren()) do
                if item:IsA("Accessory") then
                    found.Names[item.Name] = true
                    local key = F.meshKey(Appearance.handleOf(item))
                    if key then found.Meshes[key] = true end
                elseif item:IsA("Shirt") or item:IsA("Pants") or item:IsA("ShirtGraphic") then
                    local key = F.clothingKey(item)
                    if key then found.Clothes[key] = true end
                end
            end
            pcall(function() model:Destroy() end)
            return found
        end)
        if Sync.Looks[uid] ~= row then return end
        row.Busy = false
        if ok and look then row.Look = look else row.Retry = os.clock() + 60 end
    end)
    return nil
end
function Sync.draw()
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= lp then
            local uid, character = player.UserId, player.Character
            local hash, shown = Sync.Peers[uid], Sync.Shown[uid]
            if not hash then
                if shown then Sync.Shown[uid] = nil; if character then Overlay.clear(character) end; Sync.changed(uid) end
            else
                -- One download every few seconds at most, and a skin that fails to arrive is tried again later each
                -- time (8 s, 16 s… up to 2 min, then not until it changes): many users sharing skins at once
                -- used to download all of them over and over.
                local due = not shown or shown.Hash ~= hash or (not shown.Data and os.clock() >= shown.Retry)
                if due and os.clock() >= (Sync.NextGet or 0) then
                    Sync.NextGet = os.clock() + 3
                    local reply = Sync.call({a = "get", job = game.JobId, user = lp.UserId, peer = uid})
                    local ok, data = pcall(function()
                        assert(reply and reply.ok == true and reply.hash == hash, "Skin unavailable.")
                        return Sync.decode(reply.data)
                    end)
                    local fails = (shown and shown.Hash == hash and not ok) and (shown.Fails or 0) + 1 or (ok and 0 or 1)
                    shown = {Hash = hash, Data = ok and data or nil, Fails = fails, BuildFails = 0,
                        Retry = fails >= 6 and math.huge or os.clock() + math.min(120, 8 * 2 ^ (fails - 1))}
                    Sync.Shown[uid] = shown
                    if shown.Data then Sync.changed(uid) end
                end
                local entry = character and Overlay.Active[character]
                if shown and shown.Hash == hash and shown.Data and character and character.Parent and (not entry or entry.Key ~= hash) and os.clock() >= (shown.BuildRetry or 0) then
                    local rig = Overlay.rigType(character)
                    if rig and character:FindFirstChildOfClass("Humanoid") then
                        local ok, model = pcall(Overlay.build, shown.Data, rig)
                        if ok and model then
                            if Sync.enabled() and character.Parent and Sync.Peers[uid] == hash then Overlay.attach(character, model, false, hash)
                            else pcall(function() model:Destroy() end) end
                        else
                            -- A skin that cannot be built here waits longer after each failure (10 s, 20 s… up to 60 s).
                            shown.BuildFails = (shown.BuildFails or 0) + 1
                            shown.BuildRetry = os.clock() + math.min(60, 10 * shown.BuildFails)
                        end
                    end
                end
            end
        end
    end
    for uid in pairs(Sync.Shown) do if not Players:GetPlayerByUserId(uid) then Sync.Shown[uid] = nil; Sync.changed(uid) end end
    for uid in pairs(Sync.Looks) do if not Players:GetPlayerByUserId(uid) then Sync.Looks[uid] = nil end end
end
-- SKIN SYNC PUSH: where the executor has WebSocket.connect, the script keeps a socket to the Lyra server's room for
-- this Roblox server, and the server sends "poke" down it the moment another script user here changes skin or name, or
-- sends or answers a skin request. The script then beats as usual and reads the change from the reply, so a new skin
-- shows in about a second, and between pokes it beats only every PushInterval seconds (polling every 8 s for nothing
-- was most of the Lyra server's bill). The socket carries nothing else: "ping" every Ping seconds, "pong" back.
-- Every failure falls back to polling every 8 s, as before: no WebSocket in the executor, a socket that does not open
-- in 15 s, no pong within PongWait seconds, a socket that closes. It is tried again later (15 s, 30 s… up to 10 min),
-- and after 8 failures in a row (a socket that stays up 5 min clears the count) not again in this session.
Sync.Push = {Url = "wss://api.lyraez.lol/v1/sync/ws", State = "off", Attempt = 0, Fails = 0, NextTry = 0, Ping = 25, PongWait = 10, OpenWait = 15}
function Sync.pushConnector()
    local ok, connect = pcall(function()
        local lib = WebSocket
        if lib == nil and type(syn) == "table" then lib = syn.websocket end
        return lib and (lib.connect or lib.Connect)
    end)
    return ok and type(connect) == "function" and connect or nil
end
function Sync.pushLive() return Sync.Push.State == "live" end
-- Executors name these differently (Connect or connect, Send or send...): each is tried, and a failure is false.
function Sync.pushHook(signal, callback)
    if signal == nil then return false end
    if pcall(function() signal:Connect(callback) end) then return true end
    return (pcall(function() signal:connect(callback) end))
end
function Sync.pushSend(text)
    local socket = Sync.Push.Socket
    if not socket then return false end
    if pcall(function() socket:Send(text) end) then return true end
    return (pcall(function() socket:send(text) end))
end
function Sync.pushClose(socket)
    if not socket then return end
    if not pcall(function() socket:Close() end) then pcall(function() socket:close() end) end
end
function Sync.pushMessage(attempt, message)
    local push = Sync.Push
    if push.Attempt ~= attempt then return end
    local text = type(message) == "string" and message or tostring(message)
    if text == "pong" then
        push.Waiting = nil
        if push.State == "open" then
            push.State, push.LiveAt = "live", os.clock()
            -- Test builds only (see App.devNote).
            pcall(App.devNote, "Skin sync: live connection on. Another user's new skin arrives in about a second.")
        end
    elseif text == "poke" then
        Sync.Poked = true
        pcall(App.trace, "Skin sync: poke")
    end
end
-- The socket failed (reason for Debug): back to polling, with a catch-up beat at once, and another try later.
-- permanent: this executor's sockets can't work (no OnMessage), so no other try this session.
function Sync.pushFail(reason, permanent)
    local push = Sync.Push
    local socket, wasLive = push.Socket, push.State == "live"
    push.Attempt = push.Attempt + 1
    push.Socket, push.State, push.Waiting = nil, "off", nil
    Sync.pushClose(socket)
    if push.LiveAt and os.clock() - push.LiveAt >= 300 then push.Fails = 0 end
    push.LiveAt = nil
    push.Fails = push.Fails + 1
    if permanent or push.Fails >= 8 then push.Disabled = true end
    push.NextTry = os.clock() + math.min(600, 15 * 2 ^ (push.Fails - 1))
    push.Reason = reason
    pcall(App.devNote, "Skin sync: live connection off (" .. tostring(reason) .. "), checking every 8 s"
        .. (push.Disabled and "; no more tries this session." or "; next try in " .. math.floor(push.NextTry - os.clock() + 0.5) .. " s."))
    -- A poke may have been lost while the socket was dying.
    if wasLive then Sync.Poked = true end
end
function Sync.pushOpen()
    local push, connect = Sync.Push, Sync.pushConnector()
    if not connect then return end
    push.Attempt = push.Attempt + 1
    local attempt = push.Attempt
    push.State, push.Started = "connecting", os.clock()
    local url = push.Url .. "?job=" .. game.JobId .. "&user=" .. tostring(lp.UserId)
    task.spawn(function()
        local ok, socket = pcall(connect, url)
        if push.Attempt ~= attempt or push.State ~= "connecting" or not Sync.enabled() then
            -- Too late: it timed out, or sync stopped, while connect was waiting. This socket is not used.
            if ok then Sync.pushClose(socket) end
            return
        end
        if not ok or socket == nil then Sync.pushFail("connect"); return end
        local function signal(name)
            local found, value = pcall(function() return socket[name] end)
            return found and value or nil
        end
        local hooked = Sync.pushHook(signal("OnMessage"), function(message) Sync.pushMessage(attempt, message) end)
        if not hooked then Sync.pushClose(socket); Sync.pushFail("no OnMessage", true); return end
        Sync.pushHook(signal("OnClose"), function() if push.Attempt == attempt then Sync.pushFail("closed") end end)
        push.Socket, push.State = socket, "open"
        -- The first pong proves the socket works both ways: until then the script keeps polling.
        push.PingAt, push.Waiting = os.clock(), os.clock()
        Sync.pushSend("ping")
    end)
end
-- Called on every pass of the sync loop.
function Sync.pushStep()
    local push = Sync.Push
    local now = os.clock()
    if push.State == "off" then
        if not Sync.pushConnector() then
            if not push.NotedMissing then
                push.NotedMissing = true
                pcall(App.devNote, "Skin sync: this executor has no WebSocket.connect, so skin sync checks every 8 s.")
            end
            return
        end
        if not push.Disabled and now >= push.NextTry then Sync.pushOpen() end
    elseif push.State == "connecting" then
        if now - push.Started > push.OpenWait then Sync.pushFail("open timeout") end
    else
        if push.Waiting and now - push.Waiting > push.PongWait then Sync.pushFail("no pong"); return end
        if now - push.PingAt >= push.Ping then
            push.PingAt = now
            push.Waiting = push.Waiting or now
            if not Sync.pushSend("ping") then Sync.pushFail("send") end
        end
    end
end
function Sync.pushStop()
    local push = Sync.Push
    local socket = push.Socket
    push.Attempt = push.Attempt + 1
    push.Socket, push.State, push.Waiting, push.LiveAt = nil, "off", nil, nil
    Sync.pushClose(socket)
end
-- PRESENCE RIDES ON SYNC: while sync is answering, the presence beat (see PRESENCE AND NOTICES) goes inside the next
-- sync beat and its answer comes back in the reply: one request instead of two. Yields; returns the presence reply,
-- or nil to send it on its own as before (sync not running or not answering, no ride within 20 s, or a Lyra server
-- that does not carry presence).
function Sync.carryPresence(body)
    if Sync.PresenceCarry == false or not Sync.Running or not Sync.Answering or not Sync.enabled() then return nil end
    Sync.PresenceBody, Sync.PresenceReply = body, nil
    local deadline = os.clock() + 20
    while Sync.PresenceReply == nil and os.clock() < deadline and App.alive() do task.wait(0.25) end
    local reply = Sync.PresenceReply
    if Sync.PresenceBody == body then Sync.PresenceBody = nil end
    Sync.PresenceReply = nil
    return type(reply) == "table" and reply or nil
end
function Sync.start()
    if Sync.Running then return end
    Sync.Running = true
    task.spawn(function()
        local lastBeat, lastDraw, fails, waitUntil = -math.huge, -math.huge, 0, 0
        while App.alive() and not Sync.Closed do
            if Sync.enabled() then
                pcall(Sync.pushStep)
                local _, hash = Sync.mine()
                -- Without a socket: every Interval seconds (every 4 s while a skin request is open). With one: after
                -- each poke, and every PushInterval seconds (15 s while a skin request is open). Both: as soon as you
                -- change avatar, and with the presence beat when it waits for a ride. After a failed beat the next one
                -- waits longer each time (16 s, 32 s… up to 2 min; at least 25 s when the server asks to slow down).
                local now = os.clock()
                local push = Sync.pushLive()
                local interval = push and Sync.PushInterval or Sync.Interval
                if next(Sync.Asked) or next(Sync.Incoming) then interval = math.min(interval, push and 15 or 4) end
                local soon = Sync.Poked or Sync.PresenceBody ~= nil
                local due = now - lastBeat >= interval or ((Sync.Woken or hash ~= Sync.Sent) and now - lastBeat >= Sync.ChangeGap)
                    or (soon and now - lastBeat >= Sync.PokeGap)
                local beat = due and now >= waitUntil
                if beat then
                    Sync.Woken = false; lastBeat = now
                    local ok, answered, err = pcall(Sync.beat)
                    if ok and answered then fails = 0; waitUntil = 0
                    else
                        fails = fails + 1
                        waitUntil = os.clock() + math.max(err == "rate_limited" and 25 or 0, math.min(120, Sync.Interval * 2 ^ fails))
                    end
                end
                -- Right after a beat (a skin that changed is downloaded and drawn at once), else every 2 s.
                if beat or os.clock() - lastDraw >= 2 then lastDraw = os.clock(); pcall(Sync.draw) end
            end
            task.wait(Sync.Tick)
        end
        Sync.Running = false
    end)
end
function Sync.wake() Sync.Woken = true; Sync.Sent = nil; Sync.NamesAt = nil end
function Sync.stop()
    local gone = {}
    for uid in pairs(Sync.Shown) do table.insert(gone, uid) end
    Sync.Peers = {}; table.clear(Sync.Shown); Sync.Sent = nil; Sync.PeerSignature = nil; Sync.Answering = false
    Sync.pushStop()
    -- Leaving also takes your shared name off the server; the others' names come off your screen.
    Sync.NameSent, Sync.NameAt, Sync.NamesAt = nil, nil, nil
    if next(Ident.Peers) then pcall(Ident.setPeers, {}) end
    for _, uid in ipairs(gone) do Sync.changed(uid) end
    for _, entry in pairs(Sync.Incoming or {}) do if entry.Card then pcall(entry.Card.Close) end end
    if Sync.Incoming then table.clear(Sync.Incoming); table.clear(Sync.Asked) end
    if UI.refreshAskButtons then pcall(UI.refreshAskButtons) end
    for character, entry in pairs(Overlay.Active) do if not entry.Local then Overlay.clear(character) end end
    if Sync.requestFn() and game.JobId ~= "" then task.spawn(Sync.call, {a = "leave", job = game.JobId, user = lp.UserId}) end
end
function Sync.close() Sync.Closed = true; Sync.stop() end
-- SKIN REQUESTS: tap Ask skin on a script user in the Server tab and they get a request card; when they accept, the
-- skin they wear comes to you, to wear or save (see the worker's skin requests). Only users sharing a skin can be
-- asked, a request waits 45 s, and with "Skin requests" off in Settings the ones you get are declined.
Sync.Asked, Sync.Incoming = {}, {}
function Sync.who(uid)
    local player = Players:GetPlayerByUserId(uid)
    return player and (player.DisplayName ~= "" and player.DisplayName or player.Name) or "A player"
end
function Sync.headshot(uid) return "rbxthumb://type=AvatarHeadShot&id=" .. tostring(uid) .. "&w=150&h=150" end
-- Yields. Asks a user for the skin they wear.
function Sync.ask(uid)
    local who = Sync.who(uid)
    if not Sync.enabled() then App.report("Skins can't be shared in this server.", "warning"); return end
    if Sync.Asked[uid] then return end
    Sync.Asked[uid] = {Until = os.clock() + 45, Sending = true}
    UI.refreshAskButtons()
    local reply = Sync.call({a = "ask", job = game.JobId, user = lp.UserId, peer = uid})
    if reply and reply.ok == true then
        Sync.Asked[uid] = {Until = os.clock() + math.clamp(tonumber(reply.wait) or 45, 1, 45)}
        App.report("Request sent to " .. who .. ". Waiting for an answer…", "info")
        UI.askTicker()
    else
        Sync.Asked[uid] = nil
        local err = reply and reply.error
        if err == "cooldown" then App.report(who .. " declined a moment ago. Ask again in " .. tostring(math.max(1, math.floor(tonumber(reply.wait) or 60))) .. " s.", "warning")
        elseif err == "too_many" then App.report("You already have 3 requests waiting. Wait for an answer first.", "warning")
        elseif err == "not_sharing" then App.report(who .. " is not sharing a skin right now.", "warning")
        else App.report("Could not reach the Lyra server. Try again in a moment.", "error") end
    end
    UI.refreshAskButtons()
end
function Sync.cancelAsk(uid)
    if not Sync.Asked[uid] or Sync.Asked[uid].Sending then return end
    Sync.Asked[uid] = nil
    UI.refreshAskButtons()
    task.spawn(Sync.call, {a = "cancel", job = game.JobId, user = lp.UserId, peer = uid})
    App.report("Request cancelled.", "info")
end
-- Yields. Answers a request to you; accepting sends the skin you wear now.
function Sync.answer(uid, accept)
    local entry = Sync.Incoming[uid]
    if entry then entry.Answered = true end
    local name
    if accept then
        local text, hash = Sync.mine()
        if not text then
            accept = false
            App.report("You are not wearing a skin to send, so the request was declined.", "warning")
        else
            -- The other player fetches the skin you share: the Lyra server gets the one you wear now first.
            if Sync.Sent ~= hash then pcall(Sync.beat) end
            name = App.Current and Looks.name(App.Current.Name) or nil
        end
    end
    local reply = Sync.call({a = "answer", job = game.JobId, user = lp.UserId, peer = uid, accept = accept, name = name})
    if not (reply and reply.ok == true) then
        if accept then App.report("The request from " .. Sync.who(uid) .. " ended before your answer arrived.", "warning") end
        return
    end
    if accept then App.toast({Title = "Skin sent", Text = Sync.who(uid) .. " received the skin you are wearing.", Kind = "success", Image = Sync.headshot(uid), Duration = 5}) end
end
-- Yields. Loads the skin an accepted request sent you.
function Sync.receive(uid, name)
    local who = Sync.who(uid)
    local reply = Sync.call({a = "get", job = game.JobId, user = lp.UserId, peer = uid})
    local ok, data = pcall(function()
        assert(reply and reply.ok == true, "Skin unavailable.")
        return Sync.decode(reply.data)
    end)
    if not App.alive() then return end
    if not ok then
        App.toast({Title = "Skin request", Text = who .. " accepted, but the skin could not be loaded. Ask again.", Kind = "warning", Image = Sync.headshot(uid), Duration = 6})
        return
    end
    -- Without a name it is called after them, in your language ("Ronathan's skin").
    UI.receivedSkin(uid, Looks.name(name) or Looks.name(Lang.text(who .. "'s skin")) or "Received skin", data)
end
-- Requests to you and answers to yours, from a beat.
function Sync.requests(asks, answers)
    local listed = {}
    for _, ask in ipairs(type(asks) == "table" and asks or {}) do
        local uid = type(ask) == "table" and tonumber(ask.user)
        -- Only a player in this server can ask you (the Lyra server can't check who is here).
        if uid and uid ~= lp.UserId and Players:GetPlayerByUserId(uid) then
            listed[uid] = true
            if not Sync.Incoming[uid] then
                local wait = math.clamp(tonumber(ask.wait) or 45, 1, 45)
                local entry = {Until = os.clock() + wait}
                Sync.Incoming[uid] = entry
                if Store.Settings.SkinRequests == false then task.spawn(Sync.answer, uid, false)
                else entry.Card = UI.skinRequest(uid, wait) end
            end
        end
    end
    -- Gone from the list: answered, cancelled or expired.
    for uid, entry in pairs(Sync.Incoming) do
        if not listed[uid] then
            Sync.Incoming[uid] = nil
            if entry.Card then entry.Card.Close() end
        end
    end
    for _, answer in ipairs(type(answers) == "table" and answers or {}) do
        local uid = type(answer) == "table" and tonumber(answer.user)
        if uid and Sync.Asked[uid] then
            Sync.Asked[uid] = nil
            if answer.state == "accepted" then task.spawn(Sync.receive, uid, answer.name)
            else App.toast({Title = "Skin request", Text = Sync.who(uid) .. " declined your request.", Kind = "info", Image = Sync.headshot(uid), Duration = 5}) end
        end
    end
    UI.refreshAskButtons()
end

-- Server tab: the Ask skin buttons, which show a waiting request's countdown (tap again to cancel it).
UI.AskButtons = {}
function UI.refreshAskButtons()
    for uid, item in pairs(UI.AskButtons) do
        if not item.Button.Root.Parent then UI.AskButtons[uid] = nil
        else
            local asked = Sync.Asked[uid]
            local left = asked and math.max(0, math.ceil(asked.Until - os.clock())) or 0
            local text = not asked and (item.Wide and "Ask skin" or "Ask") or asked.Sending and "…"
                or (item.Wide and ("Waiting " .. left .. "s") or (left .. "s"))
            if item.Text ~= text then item.Text = text; UI.setText(item.Button.Label, text) end
        end
    end
end
function UI.askTicker()
    if UI.AskTicking then return end
    UI.AskTicking = true
    task.spawn(function()
        while App.alive() and next(Sync.Asked) do
            for uid, asked in pairs(Sync.Asked) do
                -- A few seconds of grace: the answer comes with the next beat.
                if not asked.Sending and os.clock() > asked.Until + 6 then
                    Sync.Asked[uid] = nil
                    App.toast({Title = "Skin request", Text = Sync.who(uid) .. " didn't answer your request.", Kind = "info", Image = Sync.headshot(uid), Duration = 5})
                end
            end
            UI.refreshAskButtons()
            task.wait(1)
        end
        UI.AskTicking = false
        UI.refreshAskButtons()
    end)
end
-- REQUEST CARDS: a skin request to you (accept or decline) and a skin sent to you (wear or save) slide in at the top
-- of the screen, with the window open or not.
function UI.requestStack()
    if UI.RequestStack and UI.RequestStack.Parent then return UI.RequestStack end
    local stack = UI.new("Frame", {Name = "LyraRequests", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 56),
        Size = UDim2.new(0, 360, 1, -66), BackgroundTransparency = 1, ZIndex = 210}, UI.Surface)
    UI.new("UIListLayout", {SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 8), HorizontalAlignment = Enum.HorizontalAlignment.Center}, stack)
    UI.RequestStack, UI.RequestOrder = stack, 0
    return stack
end
-- spec: UserId, Tag, Tone, Title (a name, shown as it is), Text, Chip, Seconds (a countdown; else a close button),
-- Left and Right ({Text, Icon, Callback(card)}), OnTimeout, BodyHeight (room for a longer Text; 34 by default).
-- Returns {Close = function, Right = button, Left = button}.
function UI.requestCard(spec)
    local stack = UI.requestStack()
    local screen = UI.Surface.AbsoluteSize.X
    local width = math.floor(math.min(360, (screen > 0 and screen or 400) - 24))
    stack.Size = UDim2.new(0, width, 1, -66)
    local bodyHeight = math.clamp(math.floor(tonumber(spec.BodyHeight) or 34), 34, 160)
    local extra = bodyHeight - 34
    local tone, height = spec.Tone or UI.C.Accent, 188 + extra
    UI.RequestOrder = UI.RequestOrder + 1
    local holder = UI.new("Frame", {Name = "Request", Size = UDim2.fromOffset(width, height), BackgroundTransparency = 1, LayoutOrder = UI.RequestOrder}, stack)
    local card = UI.new("CanvasGroup", {Size = UDim2.fromScale(1, 1), Position = UDim2.fromOffset(0, -14), GroupTransparency = 1,
        BackgroundColor3 = UI.C.Card, BackgroundTransparency = 0.03, BorderSizePixel = 0}, holder)
    UI.round(card, 18)
    local edge = UI.stroke(card, 0.3, tone); edge.Thickness = 1.2
    -- The card's colour washes down from the top; a soft glow sits behind the picture.
    local wash = UI.new("Frame", {Size = UDim2.fromScale(1, 1), BackgroundColor3 = tone, BorderSizePixel = 0, ZIndex = 1}, card)
    UI.new("UIGradient", {Rotation = 90, Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.78), NumberSequenceKeypoint.new(0.55, 0.95), NumberSequenceKeypoint.new(1, 1)})}, wash)
    local glow = UI.new("Frame", {Position = UDim2.fromOffset(8, 28), Size = UDim2.fromOffset(72, 72), BackgroundColor3 = tone, BackgroundTransparency = 0.84, BorderSizePixel = 0, ZIndex = 2}, card)
    UI.round(glow, 36)
    local picture = UI.new("ImageLabel", {Position = UDim2.fromOffset(16, 36), Size = UDim2.fromOffset(56, 56), BackgroundColor3 = UI.C.Raised, BorderSizePixel = 0,
        Image = Sync.headshot(spec.UserId), ScaleType = Enum.ScaleType.Crop, ZIndex = 3}, card)
    UI.round(picture, 28)
    local ring = UI.stroke(picture, 0.05, tone); ring.Thickness = 2
    local badge = UI.new("Frame", {Position = UDim2.fromOffset(54, 72), Size = UDim2.fromOffset(24, 24), BackgroundColor3 = tone, BorderSizePixel = 0, ZIndex = 4}, card)
    UI.round(badge, 12)
    local cut = UI.stroke(badge, 0, UI.C.Card); cut.Thickness = 2
    local mark = UI.icon(badge, spec.Icon or "shirt", UDim2.fromScale(0.5, 0.5), UI.C.Base)
    mark.AnchorPoint = Vector2.new(0.5, 0.5); mark.ZIndex = 5; UI.new("UIScale", {Scale = 0.62}, mark)
    local tag = UI.text(card, spec.Tag, 10, tone, true); tag.Position = UDim2.fromOffset(16, 12); tag.Size = UDim2.new(1, -100, 0, 16); tag.ZIndex = 3
    local title = UI.text(card, "", 15, UI.C.Text, true); title.Position = UDim2.fromOffset(88, 38); title.Size = UDim2.new(1, -104, 0, 20); title.ZIndex = 3
    title.Text = tostring(spec.Title or "")
    local body = UI.text(card, "", 12, UI.C.Muted); body.Position = UDim2.fromOffset(88, 59); body.Size = UDim2.new(1, -104, 0, bodyHeight); body.ZIndex = 3
    body.TextWrapped = true; body.TextTruncate = Enum.TextTruncate.None; body.TextYAlignment = Enum.TextYAlignment.Top
    UI.setText(body, spec.Text)
    local chip = UI.new("Frame", {Position = UDim2.fromOffset(16, 104 + extra), Size = UDim2.new(1, -32, 0, 28), BackgroundColor3 = UI.C.Raised, BackgroundTransparency = 0.1, BorderSizePixel = 0, ZIndex = 3}, card)
    UI.round(chip, 14)
    local chipIcon = UI.icon(chip, "shirt", UDim2.new(0, 6, 0.5, 0), tone); chipIcon.AnchorPoint = Vector2.new(0, 0.5); chipIcon.ZIndex = 4
    UI.new("UIScale", {Scale = 0.68}, chipIcon)
    local chipText = UI.text(chip, "", 11, UI.C.Text, true); chipText.Position = UDim2.fromOffset(30, 0); chipText.Size = UDim2.new(1, -40, 1, 0); chipText.ZIndex = 4
    UI.setText(chipText, spec.Chip)
    local handle, closed = {}, false
    function handle.Close()
        if closed then return end
        closed = true
        UI.tween(card, {GroupTransparency = 1, Position = UDim2.fromOffset(0, -14)}, 0.18)
        task.delay(0.2, function() pcall(function() holder:Destroy() end) end)
    end
    local half = math.floor((width - 40) / 2)
    local function action(side, primary, x)
        local button = UI.button(card, side.Text, primary, function() if not closed then side.Callback(handle) end end, side.Icon)
        button.Root.Size = UDim2.fromOffset(half, 38); button.Root.Position = x; button.Root.ZIndex = 4
        return button
    end
    handle.Left = action(spec.Left, false, UDim2.fromOffset(16, 140 + extra))
    handle.Right = action(spec.Right, true, UDim2.new(1, -16 - half, 0, 140 + extra))
    -- A countdown (pill and a line along the bottom), or a close button when the card waits for you.
    local line = UI.new("Frame", {Position = UDim2.new(0, 16, 1, -4), Size = UDim2.new(1, -32, 0, 2), BackgroundColor3 = tone, BackgroundTransparency = 0.2, BorderSizePixel = 0, ZIndex = 4}, card)
    UI.round(line, 1)
    local pill = UI.new("Frame", {AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -12, 0, 10), Size = UDim2.fromOffset(spec.Seconds and 46 or 26, 22),
        BackgroundColor3 = UI.C.Raised, BorderSizePixel = 0, ZIndex = 3}, card)
    UI.round(pill, 11)
    local started, total = os.clock(), tonumber(spec.Seconds) or 90
    local count
    if spec.Seconds then
        count = UI.text(pill, "", 11, UI.C.Muted, true); count.Size = UDim2.fromScale(1, 1); count.TextXAlignment = Enum.TextXAlignment.Center; count.ZIndex = 4
    else
        local close = UI.new("TextButton", {Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 4}, pill)
        local cross = UI.icon(close, "x", UDim2.fromScale(0.5, 0.5), UI.C.Muted); cross.AnchorPoint = Vector2.new(0.5, 0.5); cross.ZIndex = 5
        UI.new("UIScale", {Scale = 0.6}, cross)
        UI.connect(close.Activated, handle.Close)
    end
    task.spawn(function()
        while not closed and App.alive() and holder.Parent do
            local left = math.max(0, total - (os.clock() - started))
            local share = left / total
            line.Size = UDim2.new(share, -32 * share, 0, 2)
            if count then count.Text = tostring(math.ceil(left)) .. "s" end
            if left <= 0 then
                if spec.OnTimeout then pcall(spec.OnTimeout) end
                handle.Close(); break
            end
            task.wait(0.2)
        end
    end)
    UI.tween(card, {GroupTransparency = 0, Position = UDim2.fromOffset(0, 0)}, 0.3)
    return handle
end
-- A request to you: their picture and name, the skin you'd send, Decline and Accept.
function UI.skinRequest(uid, seconds)
    local current = App.Current
    local skin = current and not current.Original and Looks.name(current.Name) or nil
    return UI.requestCard({UserId = uid, Tag = "SKIN REQUEST", Title = Sync.who(uid), Seconds = seconds, Icon = "shirt",
        Text = "wants to copy the skin you are wearing.",
        Chip = skin and ("You would send: " .. skin) or "You are not wearing a skin right now",
        Left = {Text = "Decline", Icon = "x", Callback = function(card) card.Close(); task.spawn(Sync.answer, uid, false) end},
        Right = {Text = "Accept", Icon = "check", Callback = function(card)
            card.Close(); App.report("Sending your skin to " .. Sync.who(uid) .. "…", "loading"); task.spawn(Sync.answer, uid, true)
        end}})
end
-- A skin sent to you: wear it now, save it in Saved Skins, or both.
function UI.receivedSkin(uid, name, data)
    local who = Sync.who(uid)
    local saved = false
    local card
    card = UI.requestCard({UserId = uid, Tag = "SKIN RECEIVED", Tone = UI.C.Green, Title = who, Icon = "check",
        Text = "accepted your request and sent the skin they are wearing.", Chip = name,
        Left = {Text = "Save", Icon = "save", Callback = function()
            if saved then return end
            local ok, row = pcall(Looks.addReceived, data, name, "Sent by " .. who)
            if not ok then App.report(tostring(row), "error"); return end
            saved = true
            UI.setText(card.Left.Label, "Saved!"); UI.enabled(card.Left, false)
            if UI.Tab == "Looks" then UI.renderLooks() end
            App.report("Saved in Saved Skins as " .. row.Name .. ".", "success")
        end},
        Right = {Text = "Wear", Icon = "shirt", Callback = function()
            if App.Busy then App.report("Wait for the current change to finish.", "warning"); return end
            task.spawn(App.applySnapshot, {Data = Codec.copy(data), Name = name, ThumbId = uid, Shared = true}, "apply")
        end}})
    App.toast({Title = "Skin received", Text = who .. " sent you their skin.", Kind = "success", Image = Sync.headshot(uid), Duration = 4})
end

-- RESTYLE: a new theme, font or text size is put on the open window in place. Every colour of the old palette
-- becomes the same role's colour in the new one, every label takes the font for its weight, and text sizes are scaled
-- from each label's base size (so going back and forth never drifts).
function UI.colorKey(color)
    return string.format("%d,%d,%d", math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5))
end
function UI.restyle(oldColors, oldScale)
    if not UI.Gui then return end
    local map = {}
    for role, color in pairs(oldColors or {}) do if UI.C[role] then map[UI.colorKey(color)] = UI.C[role] end end
    local scale = UI.TextScale or 1
    oldScale = oldScale or scale
    local regular, bold = UI.FaceRegular, UI.FaceBold
    if not regular then
        pcall(function() regular = Font.fromEnum(UI.Font.Regular); bold = Font.fromEnum(UI.Font.Bold) end)
    end
    local function swap(item, property)
        local ok, value = pcall(function() return item[property] end)
        if ok and typeof(value) == "Color3" then
            local new = map[UI.colorKey(value)]
            if new and new ~= value then pcall(function() item[property] = new end) end
        end
    end
    local roots = {UI.Gui}
    if UI.InspectOverlay then table.insert(roots, UI.InspectOverlay) end
    for _, root in ipairs(roots) do
        for _, item in ipairs(root:GetDescendants()) do
            -- Theme previews keep their own theme's colours (see UI.themeTile).
            if item:GetAttribute("LyraFixed") then continue end
            if item:IsA("GuiObject") then
                swap(item, "BackgroundColor3")
                if item:IsA("TextLabel") or item:IsA("TextButton") or item:IsA("TextBox") then
                    swap(item, "TextColor3")
                    if item:IsA("TextBox") then swap(item, "PlaceholderColor3") end
                    if regular and not item:GetAttribute("LyraOwnFont") then
                        pcall(function()
                            local heavy = item.FontFace.Weight.Value >= Enum.FontWeight.SemiBold.Value
                            item.FontFace = heavy and bold or regular
                        end)
                    end
                    if scale ~= oldScale then
                        local constraint = item:FindFirstChildOfClass("UITextSizeConstraint")
                        local current = item.TextScaled and constraint and constraint.MaxTextSize or item.TextSize
                        local base = item:GetAttribute("LyraTextBase")
                        if type(base) ~= "number" then base = current / oldScale end
                        item:SetAttribute("LyraTextBase", base)
                        local size = math.max(8, math.floor(base * scale + 0.5))
                        if item.TextScaled then
                            if constraint then constraint.MaxTextSize = size end
                        else item.TextSize = size end
                        if UI.Fitted[item] then item:SetAttribute("LyraFitBase", size) end
                    end
                    if UI.Fitted[item] then UI.FitDirty[item] = true end
                elseif item:IsA("ImageLabel") or item:IsA("ImageButton") then swap(item, "ImageColor3")
                elseif item:IsA("ScrollingFrame") then swap(item, "ScrollBarImageColor3") end
            elseif item:IsA("UIStroke") then swap(item, "Color")
            elseif item:IsA("UIGradient") and item ~= UI.Sheen then
                pcall(function()
                    local keys = {}
                    for i, key in ipairs(item.Color.Keypoints) do keys[i] = ColorSequenceKeypoint.new(key.Time, map[UI.colorKey(key.Value)] or key.Value) end
                    item.Color = ColorSequence.new(keys)
                end)
            end
        end
    end
    if UI.Sheen then pcall(function() UI.Sheen.Color = UI.sheenColors() end) end
    -- Pop-ups read their colours from this table when they open.
    pcall(function()
        local theme = UI.Toasts and UI.Toasts.Theme
        if type(theme) == "table" then
            theme.Background = UI.C.Base; theme.Text = UI.C.Text; theme.Muted = UI.C.Muted; theme.Line = UI.C.Line
            if type(theme.Kinds) == "table" then theme.Kinds.info = UI.C.Accent; theme.Kinds.success = UI.C.Green; theme.Kinds.warning = UI.C.Gold; theme.Kinds.error = UI.C.Red end
        end
    end)
end
function UI.setTheme(name)
    if not UI.Themes[name] then return end
    local old = {}
    for role, color in pairs(UI.C) do old[role] = color end
    Store.Settings.Theme = name
    local colors = UI.palette(name)
    for role, color in pairs(colors) do UI.C[role] = color end
    UI.restyle(old)
    pcall(UI.Decor.apply)
    if UI.refreshThemeTiles then UI.refreshThemeTiles() end
    -- The first anime theme chosen says that its cast answers a tap.
    if UI.Decor.Staged and not Store.Settings.CastTipSeen then
        Store.Settings.CastTipSeen = true
        App.toast({Title = name, Text = "Tap a character to hear from them.", Kind = "info", Icon = "smile", Duration = 6})
    end
    App.persist()
end
function UI.setFont(name)
    local regular, bold = nil, nil
    if name ~= "Builder Sans" then
        regular, bold = UI.fontFaces(name)
        if not regular then App.report("This font is not available in your Roblox version.", "warning"); return false end
    end
    Store.Settings.Font = name
    UI.FaceRegular, UI.FaceBold = regular, bold
    UI.restyle({})
    App.persist()
    return true
end
function UI.setTextSize(percent)
    local old = UI.TextScale or 1
    Store.Settings.TextSize = percent
    UI.TextScale = percent / 100
    UI.restyle({}, old)
    UI.layout(false)
    App.persist()
end
-- THEME GALLERY (Settings > Look): every theme as a small picture of the window in its colours, in three groups.
-- The pictures keep their own colours when the theme changes (LyraFixed, see RESTYLE); the theme in use is edged in
-- the accent with a check that pops in.
UI.ThemeGroups={{Title="Classic",Names={"Lavender","Midnight","Rose","Mint","Ember"}},{Title="Seasonal",Names={"Halloween","Christmas"}},
    {Title="Anime",Names={"Re:Zero","Code Geass","Attack on Titan","Demon Slayer","Bleach","Tensura","Franxx"}}}
function UI.themeGallery(parent)
    local card=UI.autoCard(parent,0,8,14)
    UI.anchor("settings:themes",card,{Title="Theme",Text="The window's colours. The seasonal and anime themes also decorate the window."})
    UI.paragraph(card,"Theme",13,UI.C.Text,true,1)
    UI.paragraph(card,"The window's colours. The seasonal and anime themes also decorate the window.",11,UI.C.Muted,false,2)
    UI.ThemeTiles={}; UI.ThemeGrids={}
    for index,group in ipairs(UI.ThemeGroups) do
        UI.paragraph(card,group.Title,10,UI.C.Accent,true,index*10)
        local grid=UI.new("Frame",{Name="Themes"..group.Title,LayoutOrder=index*10+1,Size=UDim2.new(1,0,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1},card)
        table.insert(UI.ThemeGrids,UI.new("UIGridLayout",{CellSize=UDim2.fromOffset(116,94),CellPadding=UDim2.fromOffset(8,8),SortOrder=Enum.SortOrder.LayoutOrder},grid))
        for order,name in ipairs(group.Names) do UI.themeTile(grid,name,order) end
    end
    UI.refreshThemeTiles(true)
    return card
end
function UI.themeTile(parent,name,order)
    local colors=UI.palette(name)
    local special=UI.ThemeSpecial[name]
    local tile=UI.new("TextButton",{Name="Theme_"..name,LayoutOrder=order,Text="",AutoButtonColor=false,BackgroundColor3=UI.C.Raised,BackgroundTransparency=0.5,BorderSizePixel=0},parent)
    UI.round(tile,14); local edge=UI.stroke(tile,0.7)
    local fixed={}
    local function piece(class,props,into) local item=UI.new(class,props,into); table.insert(fixed,item); return item end
--[[YMLXO3K7GUYDENBRMVRTAOJUGU3WMYRWG4ZGCYTBOU]]
    local window=piece("Frame",{Name="Preview",Position=UDim2.fromOffset(8,8),Size=UDim2.new(1,-16,0,52),BackgroundColor3=colors.Base,BorderSizePixel=0},tile); UI.round(window,9)
    piece("UIStroke",{Color=colors.Line,Thickness=1,Transparency=0.15},window)
    local side=piece("Frame",{Position=UDim2.fromOffset(4,4),Size=UDim2.new(0,18,1,-8),BackgroundColor3=colors.Card,BorderSizePixel=0},window); UI.round(side,5)
    local dot=piece("Frame",{Position=UDim2.fromOffset(4,5),Size=UDim2.fromOffset(10,10),BackgroundColor3=colors.Accent,BorderSizePixel=0},side); UI.round(dot,5)
    local active=piece("Frame",{Position=UDim2.fromOffset(3,21),Size=UDim2.new(1,-6,0,6),BackgroundColor3=colors.AccentDark,BorderSizePixel=0},side); UI.round(active,3)
    local bar=piece("Frame",{Position=UDim2.fromOffset(28,7),Size=UDim2.new(0.42,-12,0,6),BackgroundColor3=colors.Accent,BorderSizePixel=0},window); UI.round(bar,3)
    local line=piece("Frame",{Position=UDim2.fromOffset(28,18),Size=UDim2.new(0.62,-18,0,4),BackgroundColor3=colors.Muted,BackgroundTransparency=0.45,BorderSizePixel=0},window); UI.round(line,2)
    local block=piece("Frame",{Position=UDim2.new(0,28,1,-20),Size=UDim2.new(1,-34,0,14),BackgroundColor3=colors.Card,BorderSizePixel=0},window); UI.round(block,4)
    local pill=piece("Frame",{Position=UDim2.new(1,-22,0.5,-3),Size=UDim2.fromOffset(16,6),BackgroundColor3=colors.Green,BorderSizePixel=0},block); UI.round(pill,3)
    if special then
        local art=UI.artImage(window,special.Icon,{AnchorPoint=Vector2.new(1,0),Position=UDim2.new(1,-3,0,3),Size=UDim2.fromOffset(24,24)},"face")
        if art then table.insert(fixed,art); if UI.Cast.Faces[special.Icon] then UI.round(art,12) end end
    end
    for _,item in ipairs(fixed) do item:SetAttribute("LyraFixed",true) end
    local label=UI.text(tile,name,11,nil,true); label.Position=UDim2.fromOffset(10,66); label.Size=UDim2.new(1,-36,0,20)
    UI.fit(label,9)
    local check=UI.new("Frame",{Name="Check",AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.new(1,-17,0,76),Size=UDim2.fromOffset(20,20),BackgroundColor3=UI.C.Accent,BorderSizePixel=0,Visible=false},tile)
    UI.new("UICorner",{CornerRadius=UDim.new(1,0)},check)
    local mark=UI.icon(check,"check",UDim2.fromScale(0.5,0.5),UI.C.Base); mark.AnchorPoint=Vector2.new(0.5,0.5); UI.new("UIScale",{Scale=0.62},mark)
    local pop=UI.new("UIScale",{Scale=1},check)
    UI.press(tile)
    UI.connect(tile.Activated,function() if Store.Settings.Theme~=name then UI.setTheme(name) end end)
    UI.connect(tile.MouseEnter,function() UI.tween(tile,{BackgroundTransparency=0.2}) end)
    UI.connect(tile.MouseLeave,function() UI.tween(tile,{BackgroundTransparency=0.5}) end)
    UI.ThemeTiles[name]={Root=tile,Edge=edge,Check=check,Pop=pop}
end
function UI.refreshThemeTiles(instant)
    for name,tile in pairs(UI.ThemeTiles or {}) do
        local on=name==Store.Settings.Theme
        tile.Edge.Color=on and UI.C.Accent or UI.C.Line
        UI.tween(tile.Edge,{Transparency=on and 0 or 0.7,Thickness=on and 2 or 1},instant and 0 or 0.25)
        local was=tile.Check.Visible
        tile.Check.Visible=on
        if on and not was and not instant and UI.motion()~="off" then tile.Pop.Scale=0.2; UI.tween(tile.Pop,{Scale=1},0.4,Enum.EasingStyle.Back) end
    end
end
function UI.fontOptions()
    local options = {}
    for _, row in ipairs(UI.FontList) do
        local regular = UI.fontFaces(row.Name)
        if regular then table.insert(options, {Value = row.Name, Label = row.Name, Face = regular}) end
    end
    return options
end

-- THEME DECORATIONS: Halloween and Christmas dress the window up, and every anime theme brings its cast. Some pieces
-- sit on the window's corners and edges, half outside it, with a soft shadow on the window below them and a little
-- parallax (they drift against the pointer and float on their own), so they seem to hang in front of it; others live
-- inside: falling snow, a cobweb, a string of lights along the top, the motes of an anime theme. Low effects keeps them
-- still and drops the moving ones; reduced motion stops them. Settings > Theme decorations takes them all away.
-- With an anime theme the floating button also shows the face of the anime's lead.
